# ---------------------------------------------------------------------------
# § 1. Startup: lazy modules, keystone
# ---------------------------------------------------------------------------

class _LazyModule:
    """A module imported on first attribute access (keeps startup fast;
    `logging` alone costs ~15 ms).  The first access replaces this proxy
    with the real module in the globals."""

    __slots__ = ('_lazy_name',)

    def __init__(self, name: str) -> None:
        object.__setattr__(self, '_lazy_name', name)

    def __getattr__(self, attr: str) -> Any:
        name = object.__getattribute__(self, '_lazy_name')
        module = importlib.import_module(name)
        globals()[name] = module
        return getattr(module, attr)


ast = _LazyModule("ast")
copy = _LazyModule("copy")
fnmatch = _LazyModule("fnmatch")
hashlib = _LazyModule("hashlib")
json = _LazyModule("json")
logging = _LazyModule("logging")
random = _LazyModule("random")
shlex = _LazyModule("shlex")
signal = _LazyModule("signal")
socket = _LazyModule("socket")
socketserver = _LazyModule("socketserver")
subprocess = _LazyModule("subprocess")
textwrap = _LazyModule("textwrap")
uuid = _LazyModule("uuid")

Ks = None
KsError = Exception
KS_ARCH_X86 = KS_MODE_64 = None
_KEYSTONE_IMPORT_ATTEMPTED = False

def _ensure_keystone() -> bool:
    """Lazily import keystone to keep startup overhead low on plain builds."""
    global Ks, KsError, KS_ARCH_X86, KS_MODE_64, _KEYSTONE_IMPORT_ATTEMPTED
    if _KEYSTONE_IMPORT_ATTEMPTED:
        return Ks is not None
    _KEYSTONE_IMPORT_ATTEMPTED = True
    try:
        from keystone import Ks as _Ks, KsError as _KsError, KS_ARCH_X86 as _KS_ARCH_X86, KS_MODE_64 as _KS_MODE_64
    except Exception:  # pragma: no cover - optional dependency
        return False
    Ks = _Ks
    KsError = _KsError
    KS_ARCH_X86 = _KS_ARCH_X86
    KS_MODE_64 = _KS_MODE_64
    return True

# Pre-compiled regex patterns used by JIT and BSS code
_RE_REL_TO_RIP_PAT = re.compile(r'\[\s*rel\s+([^\]]+?)\s*\]', re.IGNORECASE)
_RE_ABS_MEM_LITERAL_PAT = re.compile(r'\[\s*(-?(?:0x[0-9A-Fa-f]+|\d+))\s*\]')
_RE_LABEL_PAT = re.compile(r'^(\.\w+|\w+):')
_RE_BSS_PERSISTENT = re.compile(r'persistent:\s*resb\s+(\d+)')
_CT_FAST_CT_INTRINSIC_DISPATCH = {}


def _normalize_rel_to_rip(line: str) -> str:
    """Normalize NASM-style [rel ...] operands to explicit [rip + ...]."""
    if "rel" not in line.lower():
        return line
    return _RE_REL_TO_RIP_PAT.sub(r"[rip + \1]", line)


DEFAULT_MACRO_EXPANSION_LIMIT = 256
_SOURCE_PATH = Path("<source>")


# ---------------------------------------------------------------------------
# § 2. Events: subscriptions, EventBus, JSON projection
# ---------------------------------------------------------------------------

class EventSubscriptionHandle:
    """Opaque handle of one CT event subscription.  Unique within the
    process and never reused; `active` turns false on unsubscribe."""

    __slots__ = ('id', 'pattern', 'handler', 'owner', 'active', 'bus')
    _next_id = 1

    def __init__(self, bus: "EventBus", pattern: str, handler: str, owner: Any = None) -> None:
        self.id = EventSubscriptionHandle._next_id
        EventSubscriptionHandle._next_id += 1
        self.bus = bus
        self.pattern = pattern
        self.handler = handler
        self.owner = owner
        self.active = True

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"EventSubscriptionHandle({self.id}, {self.pattern!r} -> {self.handler!r})"


_DETACH_SHARED_TYPES = frozenset({type(None), bool, int, float, str})


def _detach_value(value: Any, memo: Optional[Dict[int, Any]] = None) -> Any:
    """Recursive copy of the mutable maps and lists in `value`, preserving
    shared references and cycles; immutable compiler values are shared."""
    kind = type(value)
    if kind in _DETACH_SHARED_TYPES:
        return value
    if memo is None:
        memo = {}
    if kind is dict or (kind is not list and kind is not tuple and isinstance(value, dict)):
        existing = memo.get(id(value))
        if existing is not None:
            return existing
        copy: Dict[Any, Any] = {}
        memo[id(value)] = copy
        shared = _DETACH_SHARED_TYPES
        for key, item in value.items():
            copy[key] = item if type(item) in shared else _detach_value(item, memo)
        return copy
    if kind is list or isinstance(value, list):
        existing = memo.get(id(value))
        if existing is not None:
            return existing
        copy_list: List[Any] = []
        memo[id(value)] = copy_list
        copy_list.extend(_detach_value(item, memo) for item in value)
        return copy_list
    if kind is tuple or isinstance(value, tuple):
        return tuple(_detach_value(item, memo) for item in value)
    return value


# Retained records per compile (--events-ring).
DEFAULT_EVENT_RING_CAPACITY = 8192


class EventBus:
    """Synchronous compiler event bus.

    Every published event is a canonical record ``{event, timestamp_ns,
    payload}`` whose payload is a snapshot taken at publication, so later
    changes to the producer's maps cannot alter history or other observers.
    Delivery order: JSONL sinks, then tooling observers (subscribe(); their
    failures are isolated unless ``propagate_errors``), then CT
    subscriptions (ct_subscribe(); run by ``ct_runner`` with a dispatch
    snapshot).  Dispatch is reentrant.  The ring retains the newest
    ``capacity`` records for host/tooling replay only.  Events nobody wanted
    when they happened (see wants()) were never built, so replay cannot
    return them.
    """

    def __init__(self, capacity: int = DEFAULT_EVENT_RING_CAPACITY) -> None:
        # Capacity 0 disables retention only, never dispatch or sinks.
        self._events: Deque[Dict[str, Any]] = deque(maxlen=max(0, int(capacity)))
        self._subscribers: Dict[int, Tuple[str, Callable[[Dict[str, Any]], None], bool]] = {}
        self._ct_subscriptions: "OrderedDict[int, EventSubscriptionHandle]" = OrderedDict()
        self._sinks: List[Callable[[Dict[str, Any]], None]] = []
        # Per-sink event-name patterns (None: every event), --events-filter.
        self._sink_filters: List[Optional[Tuple[str, ...]]] = []
        # wants(): event name -> whether an observer or CT subscription
        # matches; cleared whenever subscriptions or sinks change.
        self._wanted: Dict[str, bool] = {}
        self._lock = threading.RLock()
        self._next_handle = 1
        self._published = 0
        # Runtime toggle (ct-event-set-enabled) and invocation-level hard
        # disable (--no-events).  Disabled publications are dropped.
        self.enabled = True
        self.hard_disabled = False
        # Installed by the parser: runs a snapshot of CT subscriptions.
        self.ct_runner: Optional[Callable[[Dict[str, Any], List[EventSubscriptionHandle]], None]] = None
        # JSONL sinks: a runtime toggle (ct-event-stream-set-enabled), a
        # bypass held while a stream failure is being dispatched, and the
        # parser's handler for a sink failure (True when resumed).
        self.stream_enabled = True
        self.sink_bypass = 0
        self.sink_error_handler: Optional[Callable[[BaseException], bool]] = None

    @property
    def has_sink(self) -> bool:
        return bool(self._sinks)
    @property
    def active(self) -> bool:
        return self.enabled and not self.hard_disabled

    def publish(self, event: str, payload: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
        if not self.active:
            return None
        record: Dict[str, Any] = {
            "event": str(event),
            "timestamp_ns": time.time_ns(),
            "payload": _detach_value(dict(payload or {})),
        }
        return self._dispatch(record)

    def publish_record(self, record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Publish an already-shaped canonical record, keeping its timestamp
        (the daemon forwards events produced by an isolated worker)."""
        if not self.active:
            return None
        canonical = {
            "event": str(record.get("event", "unknown")),
            "timestamp_ns": int(record.get("timestamp_ns", time.time_ns())),
            "payload": _detach_value(dict(record.get("payload") or {})),
        }
        return self._dispatch(canonical)

    def _dispatch(self, record: Dict[str, Any]) -> Dict[str, Any]:
        name = record["event"]
        with self._lock:
            self._events.append(record)
            self._published += 1
            sinks = ([sink for sink, patterns in zip(self._sinks, self._sink_filters)
                      if patterns is None or any(fnmatch.fnmatchcase(name, p) for p in patterns)]
                     if self.stream_enabled and not self.sink_bypass else [])
            callbacks = [
                (handle, callback, propagate_errors)
                for handle, (pattern, callback, propagate_errors) in self._subscribers.items()
                if fnmatch.fnmatchcase(name, pattern)
            ]
            ct_snapshot = [sub for sub in self._ct_subscriptions.values() if fnmatch.fnmatchcase(name, sub.pattern)]
        for sink in sinks:
            try:
                sink(record)
            except ParseError as exc:
                # Recoverable: when resumed, the record is not retried at
                # the sink but publication continues.
                handler = self.sink_error_handler
                if handler is None or not handler(exc):
                    raise
        for handle, callback, propagate_errors in callbacks:
            try:
                callback(record)
            except Exception:
                if propagate_errors:
                    raise
                # Tooling observers are isolated: a failing one is detached.
                self.unsubscribe(handle)
                continue
        if ct_snapshot and self.ct_runner is not None:
            self.ct_runner(record, ct_snapshot)
        return record

    def add_sink(self, sink: Callable[[Dict[str, Any]], None],
                 patterns: Optional[Sequence[str]] = None) -> None:
        """Add a JSONL sink; `patterns` (fnmatch) limits the events it gets."""
        with self._lock:
            self._sinks.append(sink)
            self._sink_filters.append(tuple(patterns) if patterns else None)
            self._wanted.clear()

    def wants(self, event: str) -> bool:
        """Whether publishing `event` would reach anyone (a sink, a tooling
        observer, or a CT subscription); payloads can be skipped otherwise.
        Records nobody wants are not retained in the ring either."""
        if not self.active:
            return False
        sinks_on = bool(self._sinks) and self.stream_enabled and not self.sink_bypass
        if sinks_on and None in self._sink_filters:
            return True
        wanted = self._wanted.get(event)
        if wanted is None:
            with self._lock:
                wanted = any(fnmatch.fnmatchcase(event, pattern)
                             for pattern, _callback, _propagate in self._subscribers.values()) or any(
                    fnmatch.fnmatchcase(event, sub.pattern) for sub in self._ct_subscriptions.values())
                self._wanted[event] = wanted
        if not wanted and sinks_on:
            return any(fnmatch.fnmatchcase(event, p) for patterns in self._sink_filters if patterns
                       for p in patterns)
        return wanted

    def has_subscribers(self) -> bool:
        """Whether any tooling observer is subscribed."""
        return bool(self._subscribers)

    def subscribe(
        self,
        pattern: str,
        callback: Callable[[Dict[str, Any]], None],
        *,
        replay: bool = False,
        propagate_errors: bool = False,
    ) -> int:
        if not pattern:
            raise ValueError("event subscription pattern must not be empty")
        with self._lock:
            handle = self._next_handle
            self._next_handle += 1
            self._subscribers[handle] = (str(pattern), callback, bool(propagate_errors))
            self._wanted.clear()
            history = [dict(item) for item in self._events if fnmatch.fnmatchcase(str(item["event"]), str(pattern))] if replay else []
        for record in history:
            try:
                callback(record)
            except Exception:
                if propagate_errors:
                    self.unsubscribe(handle)
                    raise
        return handle

    def unsubscribe(self, handle: int) -> bool:
        with self._lock:
            self._wanted.clear()
            return self._subscribers.pop(int(handle), None) is not None

    def ct_subscribe(self, pattern: str, handler: str, owner: Any = None) -> EventSubscriptionHandle:
        handle = EventSubscriptionHandle(self, pattern, handler, owner)
        with self._lock:
            self._ct_subscriptions[handle.id] = handle
            self._wanted.clear()
        return handle

    def ct_unsubscribe(self, handle: EventSubscriptionHandle) -> bool:
        with self._lock:
            if handle.bus is not self or self._ct_subscriptions.pop(handle.id, None) is None:
                return False
            self._wanted.clear()
        handle.active = False
        return True

    def recent(self, pattern: str = "*", limit: Optional[int] = None) -> List[Dict[str, Any]]:
        with self._lock:
            rows = [dict(item) for item in self._events if fnmatch.fnmatchcase(str(item["event"]), pattern)]
            if limit is None:
                return rows
            count = int(limit)
            return rows[-count:] if count > 0 else []

    def stats(self) -> Dict[str, int]:
        with self._lock:
            return {
                "subscribers": len(self._subscribers),
                "ct_subscriptions": len(self._ct_subscriptions),
                "events_published": self._published,
                "buffered_events": len(self._events),
            }


_EVENT_RECORD_KEYS = frozenset({"event", "timestamp_ns", "payload"})


_JSON_SCALAR_TYPES = frozenset({type(None), bool, int, float, str})


def _event_json_value(value: Any, active: Set[int]) -> Any:
    """Typed JSON projection of an event value (JSONL sink).  Compiler
    values become objects tagged with `kind`; maps with non-string keys use
    {"kind": "Map", "entries": [[key, value], ...]}.  Raises ValueError for
    cycles and values without a projection."""
    kind = type(value)
    if kind in _JSON_SCALAR_TYPES:
        return value
    projector = _EVENT_JSON_PROJECTIONS.get(kind)
    if projector is not None:
        return projector(value, active)
    if kind is dict or kind is _types.MappingProxyType or kind is list or kind is tuple \
            or isinstance(value, (list, tuple, Mapping)):
        ident = id(value)
        if ident in active:
            raise ValueError("cyclic value cannot be serialized")
        active.add(ident)
        try:
            if kind is list or kind is tuple or isinstance(value, (list, tuple)):
                return [_event_json_value(item, active) for item in value]
            scalars = _JSON_SCALAR_TYPES
            if all(type(key) is str for key in value):
                return {key: (item if type(item) in scalars else _event_json_value(item, active))
                        for key, item in value.items()}
            return {"kind": "Map", "entries": [[_event_json_value(key, active), _event_json_value(item, active)]
                                               for key, item in value.items()]}
        finally:
            active.discard(ident)
    if isinstance(value, (bool, int, float, str)):
        return value
    raise ValueError(f"no JSON projection for {kind.__name__}")


def _event_json_record(record: Dict[str, Any]) -> str:
    return json.dumps(_event_json_value(record, set()), sort_keys=True, separators=(",", ":"))


# Filled in once the typed compiler values are defined.
_EVENT_JSON_PROJECTIONS: Dict[type, Callable[[Any, Set[int]], Any]] = {}


def _event_location(token: Optional["Token"], parser: Optional["Parser"] = None) -> Dict[str, Any]:
    if token is None:
        return {}
    if parser is not None:
        loc = parser.location_for_token(token)
        return {"path": str(loc.path), "line": loc.line, "column": loc.column}
    return {"line": token.line, "column": token.column}


def _env_flag(name: str) -> Optional[bool]:
    raw = os.environ.get(name)
    if raw is None:
        return None
    value = raw.strip().lower()
    if value in {"", "0", "false", "no", "off", "never"}:
        return False
    return True


def _diagnostic_color_enabled() -> bool:
    forced = _env_flag("L2_FORCE_COLOR")
    if forced is not None:
        return forced
    if _env_flag("CLICOLOR_FORCE"):
        return True
    if os.environ.get("NO_COLOR") is not None:
        return False
    if _env_flag("CLICOLOR") is False:
        return False
    try:
        return bool(sys.stderr.isatty())
    except Exception:
        return False

_struct_mod = None
def _get_struct():
    global _struct_mod
    if _struct_mod is None:
        import struct as _s
        _struct_mod = _s
    return _struct_mod


_ct_libc_syscall = None
def _ct_linux_syscall(nr: int, a0: int = 0, a1: int = 0, a2: int = 0, a3: int = 0, a4: int = 0, a5: int = 0) -> int:
    """Call Linux syscall(2) via libc with up to 6 arguments."""
    global _ct_libc_syscall
    if _ct_libc_syscall is None:
        import ctypes as _ctypes
        globals().setdefault('ctypes', _ctypes)
        _libc = _ctypes.CDLL(None, use_errno=True)
        _libc.syscall.restype = _ctypes.c_long
        _libc.syscall.argtypes = [_ctypes.c_long] * 7
        _ct_libc_syscall = _libc.syscall
    return int(_ct_libc_syscall(int(nr), int(a0), int(a1), int(a2), int(a3), int(a4), int(a5)))


_DIAGNOSTIC_SEVERITIES = ("error", "warning", "note")
_DIAGNOSTIC_CATEGORY_RE = re.compile(r"^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$")

# Built-in diagnostic codes: code -> (category, default phase).  Every error
# the compiler raises names one of these codes; the category is derived here,
# never from message text.  The category namespace stays open to extensions
# (diagnostic-new accepts any well-formed category).
_DIAGNOSTIC_CODES: Dict[str, Tuple[str, str]] = {}
# Optional presentation help per code: (hint, helps).
_DIAGNOSTIC_HELP: Dict[str, Tuple[str, Tuple[str, ...]]] = {}


def _register_codes(category: str, phase: str, codes: Sequence[str]) -> None:
    for code in codes:
        if code in _DIAGNOSTIC_CODES:
            raise RuntimeError(f"diagnostic code {code!r} registered twice")
        _DIAGNOSTIC_CODES[code] = (category, phase)


