_register_codes("tooling_error", "tooling", ("tool-unavailable", "integrity-check-failed"))
_register_codes("internal_error", "internal", (
    "internal-parser", "internal-ct-vm", "internal-optimizer",
    "internal-emitter", "internal-import-directive", "internal-frontend-marker", "internal-no-preloaded-source",
    "internal-ct-exception",
))
# Codes recorded by warnings and notes (no category).  Warnings promoted to
# errors by --Werror keep their code and use category promoted_warning.
_WARNING_CODES = frozenset({
    "match-duplicate-pattern", "ct-warning-raised", "ct-note-raised", "warning-redefine",
})
_register_codes("promoted_warning", "warning", ("warning-redefine",))

_DIAGNOSTIC_HELP.update({
    "parser-unexpected-eof": ("the parser reached end-of-file before closing the current construct",
                              ("add the missing closing token such as `end`, `;`, `}`, `)`, or `]`",)),
    "lexer-unterminated-string": ("string literal started but was never closed",
                                  ('add a closing double quote (")', "escape embedded quotes inside strings")),
    "parser-unexpected-end": ("`end` must close an active definition or control block",
                              ("remove this `end` or add its matching opener earlier",
                               "check nesting around `if`/`else`/`for`/`while`/`begin`/`word`")),
    "parser-control-underflow": ("a control keyword appeared without a matching opener",
                                 ("ensure `else` follows an `if`, and `do` follows `while`",
                                  "check that every control block starts before it is closed")),
    "parser-control-mismatch": ("a control keyword tried to close a different control frame",
                                ("verify proper control flow order: `while ... do ... end`, `if ... else ... end`, "
                                 "`for ... end`", "check source location notes for where the block was opened")),
    "parser-macro-unterminated": ("macro declarations must end with ';'", ("add ';' at the end of the macro body",)),
    "parser-definition-unclosed": ("a definition was opened but not closed before end-of-file",
                                   ("add a matching `end` for the current definition",)),
    "parser-control-unclosed": ("control-flow blocks must be explicitly closed",
                                ("add missing `end` tokens for open `if`/`else`/`for`/`while`/`begin` blocks",)),
    "parser-priority-invalid": ("priority directives must be immediately followed by a definition",
                                ("place `word`, `:asm`, `:py`, or `extern` right after `priority`",)),
    "ct-loop-index-unavailable": ("`i` is only valid while executing an active `for ... end` loop body",
                                  ("move `i` into the body of a `for ... end` loop",
                                   "if you need a manual counter, track it in a variable")),
    "ct-stack-underflow": ("a compile-time word popped more values than were available",
                           ("check the stack effect of preceding words",
                            "add missing literals/values before this operation")),
    "emission-unknown-word": ("runtime emission could not resolve the referenced word",
                              ("check spelling and ensure the word is defined/imported before use",
                               "if this word is compile-time only, avoid calling it from runtime code")),
    "emission-compile-only-word": ("compile-time-only words cannot be emitted into runtime code",
                                   ("replace with a runtime word, or run the caller at compile time",
                                    "remove `compile-only` if runtime use is intended")),
    "emission-extern-variadic-count": ("variadic extern lowering requires an explicit literal variadic arg count",
                                       ("push a literal count before the variadic extern word",
                                        "example: `2 printf` means two extra variadic arguments")),
    "emission-extern-signature": ("extern signature metadata does not match declared stack arity",
                                  ("align extern type list length with declared input count",)),
    "internal-emitter": ("the emitter encountered an IR node it cannot lower",
                         ("check preceding macro/rewrite output for malformed ops",)),
    "internal-parser": ("the parser raised an unexpected internal exception",
                        ("re-run with a minimal reproduction and report this as a compiler bug",)),
    "internal-ct-exception": ("unexpected exception while executing compile-time code",
                              ("re-run with a reduced repro and report this as a compiler bug",)),
})


def diagnostic_category(code: str) -> Optional[str]:
    """The built-in category of an error code, or None if unregistered."""
    entry = _DIAGNOSTIC_CODES.get(code)
    return entry[0] if entry is not None else None


# ---------------------------------------------------------------------------
# § 3. Diagnostics and compiler errors
# ---------------------------------------------------------------------------

class Diagnostic:
    """Immutable structured description of an issue.

    Contract fields: `severity`, stable `code`, `category` (errors only),
    optional `phase`, human-readable `message`, `primary` SourceOrigin, and
    ordered `related` records `(kind, message-or-None, SourceOrigin)`.  The
    remaining fields (`path`, `line`, `column`, `length`, `hint`,
    `suggestion`, `notes`, `helps`) are presentation data for rendering."""

    __slots__ = (
        'severity', 'code', 'category', 'phase', 'message', 'primary', 'related',
        'path', 'line', 'column', 'length', 'hint', 'suggestion', 'notes', 'helps',
    )

    def __init__(
        self,
        level: str,
        message: str,
        path: Optional[Path] = None,
        line: int = 0,
        column: int = 0,
        length: int = 0,
        hint: str = "",
        suggestion: str = "",
        code: str = "",
        notes: Optional[Sequence[str]] = None,
        helps: Optional[Sequence[str]] = None,
        *,
        category: Optional[str] = None,
        phase: Optional[str] = None,
        primary: Optional["SourceOrigin"] = None,
        related: Sequence[Tuple[str, Optional[str], "SourceOrigin"]] = (),
    ) -> None:
        setter = object.__setattr__
        if category is None and level == "error" and code:
            category = diagnostic_category(code)
            if phase is None and code in _DIAGNOSTIC_CODES:
                phase = _DIAGNOSTIC_CODES[code][1]
        help_entry = _DIAGNOSTIC_HELP.get(code)
        if help_entry is not None:
            if not hint:
                hint = help_entry[0]
            helps = tuple(helps or ()) + tuple(h for h in help_entry[1] if h not in (helps or ()))
        if primary is not None and primary.path and (path is None or line <= 0):
            path = Path(primary.path)
            line = primary.start_line
            column = primary.start_column
            if primary.start_line == primary.end_line:
                length = max(length, primary.end_column - primary.start_column)
        setter(self, 'severity', level)
        setter(self, 'code', code)
        setter(self, 'category', category)
        setter(self, 'phase', phase)
        setter(self, 'message', message)
        setter(self, 'primary', primary)
        setter(self, 'related', tuple(related))
        setter(self, 'path', path)
        setter(self, 'line', line)
        setter(self, 'column', column)
        setter(self, 'length', length)
        setter(self, 'hint', hint)
        setter(self, 'suggestion', suggestion)
        setter(self, 'notes', tuple(str(item).strip() for item in (notes or ()) if str(item).strip()))
        setter(self, 'helps', tuple(str(item).strip() for item in (helps or ()) if str(item).strip()))

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("Diagnostic is immutable")

    @property
    def level(self) -> str:
        return self.severity

    def replace(self, **changes: Any) -> "Diagnostic":
        """A copy with some fields changed."""
        fields = {name: getattr(self, name) for name in self.__slots__}
        fields.update(changes)
        level = fields.pop('severity')
        return Diagnostic(level, fields.pop('message'), **fields)

    @staticmethod
    def _split_nonempty_lines(text: str) -> List[str]:
        out: List[str] = []
        for raw in str(text).splitlines():
            line = raw.strip()
            if line:
                out.append(line)
        return out

    def format(self, *, color: bool = True) -> str:
        """Format the diagnostic in Rust-style with source context."""
        _RED = "\033[1;31m" if color else ""
        _YELLOW = "\033[1;33m" if color else ""
        _BLUE = "\033[1;34m" if color else ""
        _CYAN = "\033[1;36m" if color else ""
        _BOLD = "\033[1m" if color else ""
        _DIM = "\033[2m" if color else ""
        _RST = "\033[0m" if color else ""

        level_color = _RED if self.level == "error" else (_YELLOW if self.level == "warning" else _BLUE)
        parts: List[str] = []
        code_suffix = f"{_DIM}[{self.code}]{_RST}" if self.code else ""
        parts.append(f"{level_color}{self.level}{code_suffix}{_RST}{_BOLD}: {self.message}{_RST}")

        note_lines: List[str] = []
        if self.hint:
            note_lines.extend(self._split_nonempty_lines(self.hint))
        note_lines.extend(self.notes)
        for _kind, rel_message, rel_origin in self.related:
            if rel_origin is None or rel_origin.path == "<generated>":
                continue
            where = f"{rel_origin.path}:{rel_origin.start_line}:{rel_origin.start_column}"
            note_lines.append(f"{rel_message or _kind}: {where}")

        help_lines: List[str] = []
        if self.suggestion:
            help_lines.extend(self._split_nonempty_lines(self.suggestion))
        help_lines.extend(self.helps)

        if self.path and self.line > 0:
            loc = f"{self.path}:{self.line}"
            if self.column > 0:
                loc += f":{self.column}"
            parts.append(f"  {_BLUE}-->{_RST} {loc}")

            # Try to show the source line
            try:
                src_lines = self.path.read_text(encoding="utf-8", errors="ignore").splitlines()
                if 0 < self.line <= len(src_lines):
                    src_line = src_lines[self.line - 1]
                    line_no = str(self.line)
                    pad = " " * len(line_no)
                    parts.append(f"  {_BLUE}{pad} |{_RST}")
                    parts.append(f"  {_BLUE}{line_no} |{_RST} {src_line}")
                    if self.column > 0:
                        caret_len = max(1, self.length) if self.length else 1
                        arrow = " " * (self.column - 1) + level_color + "^" * caret_len + _RST
                        parts.append(f"  {_BLUE}{pad} |{_RST} {arrow}")
                    for note in note_lines:
                        parts.append(f"  {_BLUE}{pad} |{_RST} {_CYAN}= note: {note}{_RST}")
                    if help_lines:
                        parts.append(f"  {_BLUE}{pad} |{_RST}")
                        for help_line in help_lines:
                            parts.append(f"  {_BLUE}{pad} = {_CYAN}help{_RST}: {help_line}")
            except Exception:
                pass

        else:
            for note in note_lines:
                parts.append(f"  {_CYAN}= note: {note}{_RST}")
            for help_line in help_lines:
                parts.append(f"  {_CYAN}help{_RST}: {help_line}")

        return "\n".join(parts)

    def __str__(self) -> str:
        if self.path and self.line > 0:
            return f"{self.level}: {self.message} at {self.path}:{self.line}:{self.column}"
        return f"{self.level}: {self.message}"


class _DiagnosticError(Exception):
    """Base of compiler errors.  Each carries an immutable Diagnostic built
    from its stable `code` (category and default phase come from the code
    registry); `origin` is the primary SourceOrigin when the producer knows
    it, otherwise dispatch fills in the current location."""

    def __init__(
        self,
        message: str = "",
        *,
        diagnostic: Optional[Diagnostic] = None,
        code: str = "",
        phase: Optional[str] = None,
        origin: Optional["SourceOrigin"] = None,
        related: Sequence[Tuple[str, Optional[str], "SourceOrigin"]] = (),
        path: Optional[Path] = None,
        line: int = 0,
        column: int = 0,
        length: int = 0,
        hint: str = "",
        suggestion: str = "",
        notes: Optional[Sequence[str]] = None,
        helps: Optional[Sequence[str]] = None,
    ) -> None:
        if diagnostic is None and (code or origin is not None or path is not None or line > 0 or hint
                                   or suggestion or notes or helps):
            diagnostic = Diagnostic(
                "error", message, path, line, column, length, hint, suggestion, code, notes, helps,
                phase=phase, primary=origin, related=related,
            )
        self.diagnostic = diagnostic
        super().__init__(message)

    @property
    def code(self) -> str:
        return self.diagnostic.code if self.diagnostic is not None else ""


class ParseError(_DiagnosticError):
    """Raised when the source stream cannot be parsed."""


class CompileError(_DiagnosticError):
    """Raised when IR cannot be turned into assembly."""


def _rewrap_error(exc: BaseException, cls: type, *, notes: Sequence[str] = (),
                  default_code: str = "internal-ct-exception", message: Optional[str] = None,
                  fallback_origin: Optional["SourceOrigin"] = None) -> "_DiagnosticError":
    """Re-raise `exc` as `cls`, keeping its Diagnostic (code, category,
    phase, origins) and adding context notes.  An exception without a
    Diagnostic (an unexpected Python error) gets `default_code`.  A
    Diagnostic without a location gets `fallback_origin` (the CT call site)."""
    inner = getattr(exc, "diagnostic", None)
    if isinstance(inner, Diagnostic) and inner.code:
        changes: Dict[str, Any] = {}
        extra = tuple(note for note in notes if note not in inner.notes)
        if extra:
            changes["notes"] = inner.notes + extra
        if fallback_origin is not None and inner.primary is None and inner.line <= 0:
            changes.update(primary=fallback_origin, path=Path(fallback_origin.path),
                           line=fallback_origin.start_line, column=fallback_origin.start_column)
        diag = inner.replace(**changes) if changes else inner
        return cls(diag.message, diagnostic=diag)
    return cls(message if message is not None else (str(exc) or type(exc).__name__),
               code=default_code, notes=notes, origin=fallback_origin)


def _origin_from_location(loc: Optional["SourceLocation"]) -> Optional["SourceOrigin"]:
    """Approximate SourceOrigin for a recorded op location (path, 1-based
    line, 0-based column); offsets are unknown there and reported as 0."""
    if loc is None or loc.line <= 0:
        return None
    column = loc.column + 1
    return SourceOrigin(str(loc.path), 0, 0, loc.line, column, loc.line, column)


class CompileTimeError(ParseError):
    """Raised when a compile-time word fails with context."""


# ---------------------------------------------------------------------------
# § 5. Tokenizer (Reader, raw :asm bodies)
# ---------------------------------------------------------------------------


_object_setattr = object.__setattr__


# ---------------------------------------------------------------------------
# § 4. Source origins, expansion frames, quotations, match specs
# ---------------------------------------------------------------------------

class SourceOrigin:
    """Immutable source span: canonical path, 0-based half-open code-point
    offsets into the original file, and 1-based start/end line and column
    (the end coordinate is one past the end)."""

    __slots__ = ('path', 'start', 'end', 'start_line', 'start_column', 'end_line', 'end_column')

    def __init__(self, path: str, start: int, end: int, start_line: int, start_column: int,
                 end_line: int, end_column: int) -> None:
        _object_setattr(self, 'path', path)
        _object_setattr(self, 'start', start)
        _object_setattr(self, 'end', end)
        _object_setattr(self, 'start_line', start_line)
        _object_setattr(self, 'start_column', start_column)
        _object_setattr(self, 'end_line', end_line)
        _object_setattr(self, 'end_column', end_column)

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("SourceOrigin is immutable")

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"SourceOrigin({self.path}:{self.start_line}:{self.start_column}-{self.end_line}:{self.end_column})"


# Anchor for compiler-generated Tokens that have no source location at all.
_SYNTHETIC_ORIGIN = SourceOrigin("<generated>", 0, 0, 1, 1, 1, 1)


class ExpansionFrame:
    """Immutable record of one transformation applied to a Token.  `call_site`
    (from the triggering Token) and `definition_origin` (from the macro's
    Word) are resolved lazily when first read."""

    __slots__ = ('kind', 'name', '_call_site', '_definition')

    def __init__(self, kind: str, name: str, call_site: Any, definition_origin: Any = None) -> None:
        _object_setattr(self, 'kind', kind)
        _object_setattr(self, 'name', name)
        _object_setattr(self, '_call_site', call_site)
        _object_setattr(self, '_definition', definition_origin)

    @property
    def definition_origin(self) -> Optional[SourceOrigin]:
        definition = self._definition
        if definition is None or isinstance(definition, SourceOrigin):
            return definition
        resolved = _word_source_origin(definition)
        _object_setattr(self, '_definition', resolved)
        return resolved

    @property
    def call_site(self) -> SourceOrigin:
        site = self._call_site
        if isinstance(site, SourceOrigin):
            return site
        resolved = site.origin if isinstance(site, Token) else _SYNTHETIC_ORIGIN
        _object_setattr(self, '_call_site', resolved)
        return resolved

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("ExpansionFrame is immutable")

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"ExpansionFrame({self.kind}:{self.name})"


# ---------------------------------------------------------------------------
# Machine code cache for JIT-assembled x86-64 (compile-time :asm execution,
# runtime-mode JIT, syscall stubs).
#
# Every keystone call goes through _x86_assemble(), keyed by the exact
# assembly text.  The text is the full wrapped program, so a changed :asm
# body, a changed wrapper, or a different per-call address is a different key:
# a cached entry can never be stale.  Three levels:
#
# * _ASM_CODE_MEMO: text -> bytes in this process.
# * _ASM_CODE_STORE: an append-only pack file in the user cache directory,
#   shared by every compiler process and the daemon's workers.  A process
#   that only needs code someone already assembled never loads keystone
#   (about 17 ms) or assembles anything (about 0.3 ms per body).  Text with
#   absolute addresses (per-process) is kept out of it.
# * Daemon workers load keystone and the pack, and pre-assemble the warm
#   stdlib's compile-time :asm words, before forking each job: the children
#   inherit all of it.  New code a child assembles reaches the pack, and the
#   worker picks it up before the next job, so code for any frequently used
#   word (stdlib or not) is ready in later jobs.
#
# L2_ASM_CACHE=0 disables the pack file; L2_ASM_CACHE_DIR moves it.
# ---------------------------------------------------------------------------

_ASM_CODE_MEMO: Dict[str, bytes] = {}
_ASM_CODE_MEMO_LIMIT = 4096
# :asm body -> (callable, code page) for compile-time bodies without
# per-call addresses.
_CT_ASM_STATIC_FUNCS: Dict[str, Optional[Tuple[Any, Any]]] = {}
_CT_ASM_STATIC_FUNCS_LIMIT = 4096
_KS_INSTANCE: Any = None
_KS_LOCK = threading.Lock()
# An immediate this large is an address of this process (heap, mmap); code
# containing one is not shared through the pack file.
_RE_ASM_ABSOLUTE_ADDRESS = re.compile(r"(?<![\w.])(?:0x[0-9A-Fa-f]{9,}|\d{10,})(?![\w.])")


class _CachePack:
    """Append-only pack file of cached results: records of
    magic | blake2b-128(key) | value length | blake2b-64(digest + value) | value.

    Writers append each record with a single O_APPEND write; readers skip
    corrupt records and wait for incomplete ones.  The file and its directory
    must belong to the current user and not be writable by others (machine
    code from it is executed), otherwise the store is disabled.  Past
    max_bytes the file is rewritten with its newest half.  The file name
    carries a fingerprint of what produced the values, so a new producer
    starts a new file."""

    _MAGIC = b"L2AC"
    _FORMAT = 1

    def __init__(self, kind: str = "x86-code", fingerprint: Optional[Callable[[], str]] = None,
                 max_bytes: int = 8 * 1024 * 1024) -> None:
        self.kind = kind
        self._fingerprint = fingerprint or self._keystone_fingerprint
        self.max_bytes = max_bytes
        self.entries: Dict[bytes, bytes] = {}
        self.path: Optional[Path] = None
        self._offset = 0
        self._identity: Optional[Tuple[int, int]] = None
        self._state = "new"  # new, ready, disabled

    @staticmethod
    def _keystone_fingerprint() -> str:
        """The installed keystone, without importing it: its package files'
        sizes and mtimes."""
        try:
            spec = importlib.util.find_spec("keystone")
        except (ImportError, ValueError):
            spec = None
        if spec is None or not spec.origin:
            return "none"
        parts = []
        directory = os.path.dirname(spec.origin)
        for name in ("libkeystone.so", "keystone.py", "__init__.py"):
            try:
                st = os.stat(os.path.join(directory, name))
            except OSError:
                continue
            parts.append(f"{name}:{st.st_size}:{st.st_mtime_ns}:{st.st_ctime_ns}")
        return "|".join(parts) or "none"

    @staticmethod
    def _directory() -> Optional[Path]:
        override = os.environ.get("L2_ASM_CACHE_DIR")
        if override:
            return Path(override)
        base = os.environ.get("XDG_CACHE_HOME") or os.path.join(os.path.expanduser("~"), ".cache")
        if not base or base.startswith("~"):
            return None
        return Path(base) / "l2"

    @staticmethod
    def _private(st: os.stat_result) -> bool:
        return st.st_uid == os.geteuid() and not (st.st_mode & 0o022)

    def _open(self) -> bool:
        if self._state == "ready":
            return True
        if self._state == "disabled":
            return False
        self._state = "disabled"
        if os.environ.get("L2_ASM_CACHE", "").strip() == "0":
            return False
        directory = self._directory()
        if directory is None:
            return False
        import hashlib
        tag = hashlib.blake2b(self._fingerprint().encode(), digest_size=6).hexdigest()
        try:
            directory.mkdir(mode=0o700, parents=True, exist_ok=True)
            if not self._private(os.stat(directory)):
                return False
        except OSError:
            return False
        self.path = directory / f"{self.kind}-v{self._FORMAT}-{tag}.pack"
        self._state = "ready"
        if not self.path.exists():
            self._prune_old_packs(directory)
        return True

    _KEEP_PACKS = 3

    def _prune_old_packs(self, directory: Path) -> None:
        """A new pack (new keystone or compiler version) replaces the old
        ones: keep the most recently used few of this kind."""
        try:
            packs = sorted(directory.glob(f"{self.kind}-v*.pack"), key=lambda p: p.stat().st_mtime, reverse=True)
        except OSError:
            return
        for old in packs[self._KEEP_PACKS - 1:]:
            try:
                old.unlink()
            except OSError:
                pass

    def refresh(self) -> None:
        """Read records appended since the last call (all of them after the
        file was replaced)."""
        if not self._open():
            return
        assert self.path is not None
        try:
            fd = os.open(self.path, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0))
        except OSError:
            return
        try:
            st = os.fstat(fd)
            if not self._private(st):
                self._state = "disabled"
                self.entries.clear()
                return
            identity = (st.st_ino, st.st_dev)
            if identity != self._identity or st.st_size < self._offset:
                self._identity = identity
                self._offset = 0
                self.entries.clear()
            if st.st_size == self._offset:
                return
            os.lseek(fd, self._offset, os.SEEK_SET)
            chunks = []
            remaining = st.st_size - self._offset
            while remaining > 0:
                chunk = os.read(fd, remaining)
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            self._offset += self._parse(b"".join(chunks))
        except OSError:
            return
        finally:
            os.close(fd)

    def _parse(self, data: bytes) -> int:
        """Load complete records from data; return the bytes consumed.  A
        corrupt record (a write cut short by a crash) is skipped by searching
        for the next record start; an incomplete last record is left for the
        next refresh."""
        import hashlib
        header = _get_struct().Struct("<4s16sI8s")
        size = len(data)

        def record_at(pos: int) -> Optional[Tuple[bytes, bytes, int]]:
            """(digest, code, end) of a valid complete record at pos."""
            if pos + header.size > size:
                return None
            magic, digest, length, check = header.unpack_from(data, pos)
            end = pos + header.size + length
            if magic != self._MAGIC or end > size:
                return None
            code = data[pos + header.size:end]
            if hashlib.blake2b(digest + code, digest_size=8).digest() != check:
                return None
            return digest, code, end

        pos = 0
        while pos + header.size <= size:
            record = record_at(pos)
            if record is not None:
                self.entries[record[0]] = record[1]
                pos = record[2]
                continue
            # Not a valid record here: skip to the next valid one.  If there
            # is none, this may be a record still being written.
            following = data.find(self._MAGIC, pos + 1)
            while following >= 0 and record_at(following) is None:
                following = data.find(self._MAGIC, following + 1)
            if following < 0:
                break
            pos = following
        return pos

    def get(self, digest: bytes) -> Optional[bytes]:
        if self._state == "new":
            self.refresh()
        return self.entries.get(digest)

    def add(self, digest: bytes, code: bytes) -> None:
        if self._state == "new":
            self.refresh()
        if self._state != "ready" or digest in self.entries:
            return
        assert self.path is not None
        import hashlib
        self.entries[digest] = code
        check = hashlib.blake2b(digest + code, digest_size=8).digest()
        record = _get_struct().pack("<4s16sI8s", self._MAGIC, digest, len(code), check) + code
        try:
            fd = os.open(self.path, os.O_WRONLY | os.O_APPEND | os.O_CREAT | getattr(os, "O_CLOEXEC", 0), 0o600)
        except OSError:
            return
        try:
            st = os.fstat(fd)
            if not self._private(st):
                self._state = "disabled"
                return
            os.write(fd, record)
            if st.st_size + len(record) > self.max_bytes:
                self._compact()
        except OSError:
            pass
        finally:
            os.close(fd)

    def _compact(self) -> None:
        """Rewrite the pack with its newest records (half the size limit)."""
        assert self.path is not None
        self.refresh()
        import hashlib
        kept: List[bytes] = []
        total = 0
        for digest, code in reversed(list(self.entries.items())):
            check = hashlib.blake2b(digest + code, digest_size=8).digest()
            record = _get_struct().pack("<4s16sI8s", self._MAGIC, digest, len(code), check) + code
            if total + len(record) > self.max_bytes // 2:
                break
            kept.append(record)
            total += len(record)
        tmp = self.path.with_name(f"{self.path.name}.{os.getpid()}.tmp")
        try:
            fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC | getattr(os, "O_CLOEXEC", 0), 0o600)
            try:
                os.write(fd, b"".join(reversed(kept)))
            finally:
                os.close(fd)
            os.replace(tmp, self.path)
        except OSError:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            return
        self._identity = None
        self.refresh()


_ASM_CODE_STORE = _CachePack()


def _x86_assemble(text: str) -> Optional[bytes]:
    """Machine code for an x86-64 assembly text, from the caches or keystone.
    None when it must be assembled and keystone is not installed.  Keystone
    errors propagate as KsError."""
    code = _ASM_CODE_MEMO.get(text)
    if code is not None:
        return code
    import hashlib
    digest = hashlib.blake2b(text.encode("utf-8"), digest_size=16).digest()
    shareable = _RE_ASM_ABSOLUTE_ADDRESS.search(text) is None
    if shareable:
        code = _ASM_CODE_STORE.get(digest)
    if code is None:
        if not _ensure_keystone():
            return None
        global _KS_INSTANCE
        with _KS_LOCK:
            if _KS_INSTANCE is None:
                _KS_INSTANCE = Ks(KS_ARCH_X86, KS_MODE_64)
            encoding, _ = _KS_INSTANCE.asm(text)
        if encoding is None:
            return b""
        code = bytes(encoding)
        if shareable:
            _ASM_CODE_STORE.add(digest, code)
    if len(_ASM_CODE_MEMO) >= _ASM_CODE_MEMO_LIMIT:
        _ASM_CODE_MEMO.clear()
    _ASM_CODE_MEMO[text] = code
    return code


# Compile-time :asm calls use their own wrapper: the body runs on ctypes
# buffers with rdi/rsi = data/return stack pointers and rdx/rcx = where to
# store their final values.
_CT_ASM_WRAPPER_HEAD = (
    "_ct_entry:",
    "push rbx",
    "push r12",
    "push r13",
    "push r14",
    "push r15",
    "mov r12, rdi",
    "mov r13, rsi",
    "mov r14, rdx",
    "mov r15, rcx",
)
_CT_ASM_WRAPPER_TAIL = (
    "_ct_save:",
    "mov [r14], r12",
    "mov [r15], r13",
    "pop r15",
    "pop r14",
    "pop r13",
    "pop r12",
    "pop rbx",
    "ret",
)
# [rel X] symbols that resolve to a different address on every call.
_CT_ASM_PER_CALL_SYMBOLS = frozenset({
    "data_start", "data_end", "print_buf", "print_buf_end", "persistent", "persistent_end",
})
_RE_REL_SYMBOL_NAME = re.compile(r"([A-Za-z0-9_.$@]+)")


def _ct_asm_wrap(body_lines: Sequence[str]) -> str:
    """The keystone text of a compile-time :asm call: wrapper around the
    (already patched) body, comments stripped, operand sizes in keystone
    syntax."""
    lines = []
    for raw in (*_CT_ASM_WRAPPER_HEAD, *body_lines, *_CT_ASM_WRAPPER_TAIL):
        line = raw.split(";", 1)[0].rstrip()
        if not line.strip():
            continue
        for size in ("qword", "dword", "word", "byte"):
            line = line.replace(f"{size} [", f"{size} ptr [")
        lines.append(line)
    return "\n".join(lines)


def _ct_asm_static_text(asm_body: str) -> Optional[str]:
    """The keystone text of an :asm body that uses no per-call address, or
    None when it does."""
    patched = []
    for line in asm_body.splitlines():
        line = line.strip()
        if line == "ret":
            line = "jmp _ct_save"
        match = _RE_REL_TO_RIP_PAT.search(line)
        if match is not None:
            name = _RE_REL_SYMBOL_NAME.match(match.group(1).strip())
            if name is not None and name.group(1) in _CT_ASM_PER_CALL_SYMBOLS:
                return None
        patched.append(_normalize_rel_to_rip(line))
    return _ct_asm_wrap(patched)


def _ct_asm_map(word_name: str, asm_text: str) -> Tuple[Any, Any]:
    """Assemble (or fetch) and map compile-time :asm code; returns
    (callable, code page)."""
    try:
        code = _x86_assemble(asm_text)
    except KsError as exc:
        raise ParseError(
            f"keystone failed for word '{word_name}': {exc}\n--- asm ---\n{asm_text}\n--- end asm ---",
            code="ct-asm-failed",
        ) from exc
    if code is None:
        raise ParseError("keystone is required for compile-time :asm execution; install keystone-engine",
                         code="ct-asm-failed")
    if not code:
        raise ParseError(f"keystone produced no code for word '{word_name}'", code="ct-asm-failed")
    import ctypes
    import mmap
    code_buf = mmap.mmap(-1, len(code), prot=mmap.PROT_READ | mmap.PROT_WRITE | mmap.PROT_EXEC)
    code_buf.write(code)
    code_ptr = ctypes.addressof(ctypes.c_char.from_buffer(code_buf))
    func_type = ctypes.CFUNCTYPE(None, ctypes.c_uint64, ctypes.c_uint64, ctypes.c_uint64, ctypes.c_uint64)
    return func_type(code_ptr), code_buf


def _ct_asm_static_func(word_name: str, asm_body: str) -> Any:
    """The mapped callable of a compile-time :asm body without per-call
    addresses (built once per body), or None for a body that has them.
    Keyed by the body text, so a redefined word gets its new code."""
    try:
        cached = _CT_ASM_STATIC_FUNCS[asm_body]
    except KeyError:
        pass
    else:
        return None if cached is None else cached[0]
    text = _ct_asm_static_text(asm_body)
    entry = None if text is None else _ct_asm_map(word_name, text)
    if len(_CT_ASM_STATIC_FUNCS) >= _CT_ASM_STATIC_FUNCS_LIMIT:
        _CT_ASM_STATIC_FUNCS.clear()
    _CT_ASM_STATIC_FUNCS[asm_body] = entry
    return None if entry is None else entry[0]


class Syntax:
    """Immutable sequence of Tokens produced by a backtick quotation (or
    list>syntax).  Tokens keep their own provenance."""

    __slots__ = ("tokens",)

    def __init__(self, tokens: Sequence["Token"] = ()) -> None:
        object.__setattr__(self, "tokens", tuple(tokens))

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("Syntax is immutable")

    def lexemes(self) -> Tuple[str, ...]:
        return tuple(token.lexeme for token in self.tokens)

    def __repr__(self) -> str:
        return "`" + " ".join(token.lexeme for token in self.tokens) + "`"


class _QuotationTemplate:
    """A parsed quotation: literal Tokens plus `$name` splices.  A splice's
    `bound` flag records whether `name` was a lexical binding in scope where
    the quotation was written; only bound splices read the binding
    environment."""

    __slots__ = ("parts", "has_splices", "open_token", "unquotes")

    def __init__(self, parts: Sequence[Tuple[Any, ...]], open_token: "Token") -> None:
        self.parts = tuple(parts)
        # ("unquote", prefix, suffix, marker) parts take the values of the
        # `$(expr)` expressions, which run just before the quotation and move
        # their results to the VM's unquote stack.
        self.unquotes = sum(1 for part in self.parts if part[0] == "unquote")
        self.has_splices = self.unquotes > 0 or any(part[0] in ("splice", "rep") for part in self.parts)
        self.open_token = open_token


# Words that cannot be macro parameter or pattern binding names: grammar
# structure and control syntax.  CT-registered block openers are added at
# the point a declaration is parsed.
_RESERVED_BINDING_WORDS = frozenset({
    "if", "else", "for", "while", "do", "word", "with", "begin", "end",
    "again", "continue", "break", "exit", "get_addr",
})

_MATCH_CONSTRAINTS = frozenset({"any", "ident", "int", "float", "number", "string", "char", "literal", "syntax"})


def _match_element_names(elements: Sequence[Tuple[Any, ...]], names: List[str]) -> None:
    for element in elements:
        if element[0] == "cap" and element[1] not in names:
            names.append(element[1])
        elif element[0] == "rep":
            _match_element_names(element[1], names)


class _MatchPattern:
    """One `match` clause pattern: elements ("lit", lexeme), ("wild",),
    ("cap", name, constraint-or-None), or ("rep", elements, separator-or-None,
    minimum) for a `$( ... )*` / `$( ... )+` repetition group;
    `default` marks `[_]`."""

    __slots__ = ("elements", "default", "names", "token")

    def __init__(self, elements: Sequence[Tuple[Any, ...]], default: bool, token: "Token") -> None:
        self.elements = tuple(elements)
        self.default = default
        self.token = token
        names: List[str] = []
        _match_element_names(self.elements, names)
        self.names = tuple(names)

    def duplicate_key(self) -> Tuple[Any, ...]:
        """Shape compared for the duplicate-pattern warning: binding names
        are replaced by their first-occurrence order."""
        order: Dict[str, int] = {}
        key: List[Tuple[Any, ...]] = []
        for element in self.elements:
            if element[0] == "cap":
                index = order.setdefault(element[1], len(order))
                key.append(("cap", index, element[2]))
            else:
                key.append(element)
        return tuple(key)


def _quotation_escape_error(token: "Token") -> Optional["ParseError"]:
    lexeme = token.lexeme
    if lexeme == "\\`" or lexeme == "\\\\" or (lexeme.startswith("\\$") and len(lexeme) > 2):
        return None
    return ParseError(
        f"invalid escape '{lexeme}' in quotation at {token.line}:{token.column}; "
        "only \\$name, \\` and \\\\ are allowed",
        code="syntax-escape-invalid",
    )


def _check_quotation_escapes(tokens: Sequence["Token"]) -> None:
    """Raise for the first invalid escape among a quotation's Tokens."""
    for token in tokens:
        if token.lexeme[0] == "\\":
            error = _quotation_escape_error(token)
            if error is not None:
                raise error


# Internal words around each `$(expr)`: the expression must leave exactly one
# value.  The NUL makes the names impossible to write in source.
_UNQUOTE_BEGIN = "\0unquote-begin"
_UNQUOTE_END = "\0unquote-end"


def _quotation_splice_names(parts: Sequence[Tuple[Any, ...]], names: List[str]) -> None:
    for part in parts:
        if part[0] == "splice" and part[1] not in names:
            names.append(part[1])
        elif part[0] == "rep":
            _quotation_splice_names(part[1], names)


def _adjacent(left: "Token", right: "Token") -> bool:
    return right.start == left.end and right.end > 0 and right._srcmap is left._srcmap


def _repetition_group(tokens: Sequence["Token"], index: int) -> Optional[Tuple[int, Optional[str], int, int]]:
    """When tokens[index] starts `$( ... )*` or `$( ... )+` (optionally
    with a separator written against the quantifier, as in `$( ... ),*`),
    return (index of `)`, separator or None, minimum count, index after the
    group); else None."""
    if index + 1 >= len(tokens) or tokens[index].lexeme != "$":
        return None
    opener = tokens[index + 1]
    if opener.lexeme != "(" or not _adjacent(tokens[index], opener):
        return None
    close = _unquote_close(tokens, index + 1, len(tokens))
    if close < 0 or close + 1 >= len(tokens):
        return None
    nxt = tokens[close + 1]
    if not _adjacent(tokens[close], nxt):
        return None
    if nxt.lexeme in ("*", "+"):
        return close, None, 1 if nxt.lexeme == "+" else 0, close + 2
    if close + 2 < len(tokens) and tokens[close + 2].lexeme in ("*", "+") and _adjacent(nxt, tokens[close + 2]):
        return close, nxt.lexeme, 1 if tokens[close + 2].lexeme == "+" else 0, close + 3
    return None


def _unquote_opens(tokens: Sequence["Token"], index: int) -> bool:
    """True when tokens[index] is `$` (or `prefix$`) directly followed by `(`:
    the start of a `$(expr)` unquote."""
    token = tokens[index]
    lexeme = token.lexeme
    if not lexeme.endswith("$") or lexeme[0] == "\\" or index + 1 >= len(tokens):
        return False
    nxt = tokens[index + 1]
    if not (nxt.lexeme == "(" and nxt.start == token.end and nxt._srcmap is token._srcmap):
        return False
    return _repetition_group(tokens, index) is None


def _unquote_close(tokens: Sequence["Token"], open_paren: int, limit: int) -> int:
    """Index of the `)` closing the unquote whose `(` is at open_paren."""
    depth = 0
    index = open_paren
    while index < limit:
        lexeme = tokens[index].lexeme
        if lexeme == "(":
            depth += 1
        elif lexeme == ")":
            depth -= 1
            if depth == 0:
                return index
        index += 1
    return -1


def _unquote_tokens(value: Any, prefix: str, suffix: str, marker: "Token") -> List["Token"]:
    """Tokens for one `$(expr)` value: a Token or Syntax as is, a string as a
    word, an integer as a literal, a list element by element.  Text written
    directly against the unquote (`get-$(…)`, `$(…)-x`) is pasted on."""
    if isinstance(value, Syntax):
        items: List[Any] = list(value.tokens)
    elif isinstance(value, list):
        items = list(value)
    else:
        items = [value]
    if (prefix or suffix) and len(items) != 1:
        raise ParseError(f"'{prefix}$(...){suffix}' pastes text onto the unquoted value, which needs exactly one "
                         f"token, got {len(items)}", code="syntax-splice-invalid")
    result: List[Token] = []
    for item in items:
        if isinstance(item, Token):
            lexeme = item.lexeme
            template: Token = item
        elif isinstance(item, bool) or isinstance(item, int):
            lexeme = str(int(item))
            template = marker
        elif isinstance(item, str):
            if item == "" or any(ch.isspace() for ch in item):
                raise ParseError(f"an unquoted string must be one non-empty word, got {item!r}",
                                 code="syntax-splice-invalid")
            lexeme = item
            template = marker
        else:
            raise ParseError(f"cannot unquote a {_ct_type_name(item)}; use a Token, Syntax, string, integer, "
                             "or a list of them", code="syntax-splice-invalid")
        if prefix or suffix:
            lexeme = prefix + lexeme + suffix
        result.append(template if lexeme == template.lexeme and template is item else _derive_token(template, lexeme))
    return result


def _build_quotation_template(tokens: Sequence["Token"], open_token: "Token",
                              bound: AbstractSet[str],
                              unquotes: Optional[Dict["Token", Tuple[Any, ...]]] = None,
                              in_repetition: bool = False) -> _QuotationTemplate:
    """Parse the Tokens between two backticks into a quotation template;
    `bound` holds the `$name` bindings lexically in scope, and `unquotes`
    maps placeholder Tokens to their `$( )` unquote parts."""
    parts: List[Tuple[Any, ...]] = []
    index = 0
    while index < len(tokens):
        token = tokens[index]
        index += 1
        if unquotes and token in unquotes:
            if in_repetition:
                raise ParseError("`$( expr )` cannot be used inside a `$( ... )*` repetition",
                                 code="syntax-splice-invalid", origin=token.origin)
            parts.append(unquotes[token])
            continue
        group = _repetition_group(tokens, index - 1)
        if group is not None:
            close, separator, minimum, after = group
            inner = _build_quotation_template(tokens[index + 1:close], open_token, bound, unquotes, True)
            parts.append(("rep", inner.parts, separator, minimum, token))
            index = after
            continue
        lexeme = token.lexeme
        if lexeme[0] == "\\":
            error = _quotation_escape_error(token)
            if error is not None:
                raise error
            if lexeme == "\\`":
                parts.append(("token", _derive_token(token, "`")))
            elif lexeme == "\\\\":
                parts.append(("token", _derive_token(token, "\\")))
            else:
                parts.append(("token", _derive_token(token, lexeme[1:])))
        elif lexeme[0] == "$" and len(lexeme) > 1 and _is_l2_identifier(lexeme[1:]):
            name = lexeme[1:]
            parts.append(("splice", name, token, name in bound))
        else:
            parts.append(("token", token))
    return _QuotationTemplate(parts, open_token)


class _MacroDef:
    """A unified macro: parameter names, the compiled CT body, the body's
    Tokens, user metadata, and the fast-path quotation (a body of exactly
    one quotation followed by `emit`).

    A fast-path macro may be created from its captured source Tokens alone
    (`_MacroDef.from_quotation`): its body, body Tokens, and template are
    then built on first use, from the same Tokens, so defining the ~1,300
    standard-library constants costs only their registration."""

    __slots__ = ("params", "_body", "_body_tokens", "metadata", "_fast", "_source")

    def __init__(self, params: Sequence[str], body: "Definition", body_tokens: "Syntax",
                 metadata: Dict[str, Any], fast: Optional[_QuotationTemplate]) -> None:
        self.params = tuple(params)
        self._body = body
        self._body_tokens = body_tokens
        self.metadata = metadata
        self._fast = fast
        self._source = None

    @classmethod
    def from_quotation(cls, name: str, params: Sequence[str], source: List["Token"]) -> "_MacroDef":
        """`source` is the macro body's Tokens: the quotation (both backticks)
        followed by `emit`; escapes are already validated."""
        mdef = cls.__new__(cls)
        mdef.params = tuple(params)
        mdef.metadata = {}
        mdef._body = mdef._body_tokens = mdef._fast = None
        mdef._source = (name, source)
        return mdef

    def _materialize(self) -> None:
        name, source = self._source
        self._source = None
        fast = _build_quotation_template(source[1:-2], source[0], frozenset(self.params))
        self._fast = fast
        self._body = Definition(name=name, body=[_make_op("syntax", fast), _make_word_op("emit")], terminator=";")
        self._body_tokens = Syntax(source)

    @property
    def body(self) -> "Definition":
        if self._source is not None:
            self._materialize()
        return self._body

    @property
    def body_tokens(self) -> "Syntax":
        if self._source is not None:
            self._materialize()
        return self._body_tokens

    @property
    def fast(self) -> Optional[_QuotationTemplate]:
        if self._source is not None:
            self._materialize()
        return self._fast


class _MatchSpec:
    """A compiled `match`: clause patterns with their body labels."""

    __slots__ = ("clauses", "default_label", "max_length", "token")

    def __init__(self, token: "Token") -> None:
        self.clauses: List[Tuple[_MatchPattern, str]] = []
        self.default_label: Optional[str] = None
        self.max_length = 0
        self.token = token


class ParserCheckpoint:
    """Immutable opaque parser position: cursor index and last-consumed Token,
    tied to the parser that created it.  Holds no token-list snapshot."""

    __slots__ = ('parser', 'pos', 'last_token')

    def __init__(self, parser: Any, pos: int, last_token: Optional["Token"]) -> None:
        _object_setattr(self, 'parser', parser)
        _object_setattr(self, 'pos', pos)
        _object_setattr(self, 'last_token', last_token)

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("ParserCheckpoint is immutable")

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"ParserCheckpoint(pos={self.pos})"


class ParserSession:
    """Opaque speculative-parsing handle.  Saves the token list, cursor and
    last-consumed Token; usable once, in strict LIFO order."""

    __slots__ = ('parser', 'tokens', 'pos', 'last_token', 'open')

    def __init__(self, parser: Any, tokens: List["Token"], pos: int, last_token: Optional["Token"]) -> None:
        self.parser = parser
        self.tokens = tokens
        self.pos = pos
        self.last_token = last_token
        self.open = True

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"ParserSession(pos={self.pos}, open={self.open})"


class SourceCursor:
    """Mutable, identity-based raw-source cursor over explicit text.
    Offsets are 0-based code-point indexes; line and column are derived
    from the offset with LF, CRLF, and lone CR line breaks."""

    __slots__ = ('text', 'path', 'pos', '_file')

    def __init__(self, text: str, path: str) -> None:
        self.text = text
        self.path = path
        self.pos = 0
        self._file: Optional["_SourceFileText"] = None

    def origin(self, start: int, end: int) -> "SourceOrigin":
        source = self._file
        if source is None:
            source = self._file = _SourceFileText(self.text)
        start_line, start_column = source.line_column(start)
        end_line, end_column = source.line_column(end)
        return SourceOrigin(self.path, start, end, start_line, start_column, end_line, end_column)

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"SourceCursor({self.path}@{self.pos}/{len(self.text)})"


def _spec_line_starts(text: str) -> List[int]:
    """Line start offsets where LF, CRLF and lone CR each end one line."""
    if "\r" not in text:
        starts = [0]
        offset = 0
        for line in text.split("\n")[:-1]:
            offset += len(line) + 1
            starts.append(offset)
        return starts
    starts = [0]
    index = 0
    length = len(text)
    find = text.find
    cr = -2  # next CR at or after index (re-searched only once passed)
    while True:
        lf = find("\n", index)
        if cr != -1 and cr < index:
            cr = find("\r", index)
        if lf == -1 and cr == -1:
            break
        if cr != -1 and (lf == -1 or cr < lf):
            nxt = cr + 2 if cr + 1 < length and text[cr + 1] == "\n" else cr + 1
        else:
            nxt = lf + 1
        starts.append(nxt)
        index = nxt
    return starts


class _SourceFileText:
    """Original text of one file with the line tables needed to map the
    flattened (splitlines-based) source back to exact offsets."""

    __slots__ = ('text', 'split_starts', 'spec_starts')

    def __init__(self, text: str) -> None:
        self.text = text
        starts = [0]
        offset = 0
        for piece in text.splitlines(keepends=True):
            offset += len(piece)
            starts.append(offset)
        self.split_starts = starts
        self.spec_starts = _spec_line_starts(text)

    def line_column(self, offset: int) -> Tuple[int, int]:
        text = self.text
        if 0 < offset < len(text) and text[offset - 1] == "\r" and text[offset] == "\n":
            # Between the CR and LF of a CRLF: already at the start of the
            # next line (the LF does not advance the line again).
            offset += 1
        index = bisect.bisect_right(self.spec_starts, offset) - 1
        return index + 1, offset - self.spec_starts[index] + 1


class SourceMap:
    """Maps the flattened source of one tokenize() call back to original
    files, so Token origins can be computed lazily on first use."""

    __slots__ = ('text', 'line_starts', 'spans', 'default_path', '_files', '_span_starts', '_last_span')

    def __init__(self, text: str, line_starts: List[int], spans: Optional[Sequence["FileSpan"]],
                 default_path: str) -> None:
        self.text = text
        self.line_starts = line_starts
        self.spans = list(spans) if spans else []
        self.default_path = default_path
        self._files: Dict[str, _SourceFileText] = {}
        self._span_starts = [span.start_line for span in self.spans]
        self._last_span: Optional["FileSpan"] = None

    def location(self, flat_line: int, column: int) -> Optional[Tuple[Any, int, int]]:
        """(path, local line, 0-based column) of a flattened position from
        the file spans alone, without computing a full SourceOrigin."""
        span = self._last_span
        if span is None or not (span.start_line <= flat_line < span.end_line):
            index = bisect.bisect_right(self._span_starts, flat_line) - 1
            if index < 0:
                return None
            span = self.spans[index]
            if flat_line >= span.end_line:
                return None
            self._last_span = span
        return span.path, span.local_start_line + (flat_line - span.start_line), column

    def _file(self, path: str) -> Optional[_SourceFileText]:
        cached = self._files.get(path)
        if cached is None:
            try:
                # Decode raw bytes: read_text() would translate CRLF/CR to LF
                # and shift every offset after the first such line break.
                cached = _SourceFileText(Path(path).read_bytes().decode("utf-8"))
            except (OSError, UnicodeDecodeError):
                return None
            self._files[path] = cached
        return cached

    def _flat_position(self, offset: int) -> Tuple[int, int]:
        """(1-based flattened line, 0-based column) of a flattened offset."""
        index = bisect.bisect_right(self.line_starts, offset) - 1
        if index < 0:
            index = 0
        return index + 1, offset - self.line_starts[index]

    def _local(self, flat_line: int, column: int) -> Optional[Tuple[str, _SourceFileText, int]]:
        if not self.spans:
            return None
        index = bisect.bisect_right(self._span_starts, flat_line) - 1
        if index < 0:
            return None
        span = self.spans[index]
        if flat_line >= span.end_line:
            return None
        path = str(span.path)
        source = self._file(path)
        if source is None:
            return None
        local_line = span.local_start_line + (flat_line - span.start_line)
        if local_line - 1 >= len(source.split_starts):
            return None
        return path, source, source.split_starts[local_line - 1] + column

    def origin_for(self, token: "Token") -> SourceOrigin:
        start_local = self._local(token.line, token.column)
        if start_local is not None:
            path, source, start = start_local
            end_line, end_column = self._flat_position(token.end)
            end_local = self._local(end_line, end_column)
            end = end_local[2] if end_local is not None and end_local[0] == path else start + (token.end - token.start)
            end = max(start, min(end, len(source.text)))
            start_line, start_column = source.line_column(start)
            stop_line, stop_column = source.line_column(end)
            return SourceOrigin(path, start, end, start_line, start_column, stop_line, stop_column)
        # No file span covers this token (in-memory source or a fragment):
        # report offsets into the tokenized text itself.
        flat = self._files.get("")
        if flat is None:
            flat = _SourceFileText(self.text)
            self._files[""] = flat
        start = max(0, min(token.start, len(self.text)))
        end = max(start, min(token.end, len(self.text)))
        start_line, start_column = flat.line_column(start)
        stop_line, stop_column = flat.line_column(end)
        return SourceOrigin(self.default_path, start, end, start_line, start_column, stop_line, stop_column)


class _TokenFields:
    """Slot layout shared by Token and _TokenBuilder."""
    __slots__ = ('lexeme', 'line', 'column', 'start', 'end', 'expansion_depth',
                 '_srcmap', '_origin', 'expansion_chain')


class _TokenBuilder(_TokenFields):
    """Unguarded twin of Token with the same layout: fields are filled with
    plain attribute stores, then the instance's class is switched to Token.
    This is about 3x faster than object.__setattr__ per field, which matters
    in the tokenizer."""
    __slots__ = ()


class Token(_TokenFields):
    """Immutable lexical token.

    `line`/`column`/`start`/`end` are the internal coordinates in the
    flattened source the parser reads (used for compiler diagnostics).  The
    canonical provenance is `origin` (a SourceOrigin in the original file,
    computed lazily) plus `expansion_chain` (ExpansionFrames, outermost to
    innermost)."""

    __slots__ = ()

    def __new__(cls, lexeme: str, line: int, column: int, start: int, end: int, expansion_depth: int = 0,
                *, srcmap: Optional[SourceMap] = None, origin: Any = None,
                chain: Tuple[ExpansionFrame, ...] = ()) -> "Token":
        tok = _TokenBuilder_new(_TokenBuilder)
        tok.lexeme = lexeme
        tok.line = line
        tok.column = column
        tok.start = start
        tok.end = end
        tok.expansion_depth = expansion_depth
        tok._srcmap = srcmap
        tok._origin = origin
        tok.expansion_chain = chain
        tok.__class__ = cls  # the builder is unguarded: a plain store
        return tok

    def __setattr__(self, name: str, value: Any) -> None:
        raise AttributeError("Token is immutable")

    @property
    def origin(self) -> SourceOrigin:
        origin = self._origin
        if isinstance(origin, SourceOrigin):
            return origin
        if isinstance(origin, Token):
            resolved = origin.origin  # derived token: provenance of its template
        elif self._srcmap is not None:
            resolved = self._srcmap.origin_for(self)
        else:
            resolved = _SYNTHETIC_ORIGIN
        _object_setattr(self, '_origin', resolved)
        return resolved

    @property
    def has_explicit_origin(self) -> bool:
        """True for Tokens built from an explicit SourceOrigin (no flattened
        coordinates of their own)."""
        return self._srcmap is None and isinstance(self._origin, SourceOrigin) and self._origin is not _SYNTHETIC_ORIGIN

    def __repr__(self) -> str:  # pragma: no cover - debug helper
        return f"Token({self.lexeme!r}@{self.line}:{self.column})"


_TokenBuilder_new = _TokenBuilder.__new__


def _derive_token(template: Optional[Token], lexeme: str, *, frame: Optional[ExpansionFrame] = None,
                  line: Optional[int] = None, column: Optional[int] = None,
                  start: Optional[int] = None, end: Optional[int] = None,
                  expansion_depth: Optional[int] = None) -> Token:
    """New Token with `template`'s provenance (origin and expansion chain),
    optionally appending one expansion frame.  Coordinate overrides only
    affect the internal flattened coordinates, never the origin."""
    if template is None:
        chain: Tuple[ExpansionFrame, ...] = (frame,) if frame is not None else ()
        return Token(lexeme, line or 0, column or 0, start or 0, end or 0, expansion_depth or 0,
                     origin=_SYNTHETIC_ORIGIN, chain=chain)
    origin = template._origin if isinstance(template._origin, SourceOrigin) else template
    chain = template.expansion_chain + (frame,) if frame is not None else template.expansion_chain
    return Token(
        lexeme,
        template.line if line is None else line,
        template.column if column is None else column,
        template.start if start is None else start,
        template.end if end is None else end,
        template.expansion_depth if expansion_depth is None else expansion_depth,
        origin=origin,
        chain=chain,
    )


class SourceLocation:
    __slots__ = ('path', 'line', 'column')

    def __init__(self, path: Path, line: int, column: int) -> None:
        self.path = path
        self.line = line
        self.column = column

_SourceLocation_new = SourceLocation.__new__
_SourceLocation_cls = SourceLocation

def _make_loc(path: Path, line: int, column: int) -> SourceLocation:
    loc = _SourceLocation_new(_SourceLocation_cls)
    loc.path = path
    loc.line = line
    loc.column = column
    return loc

_READER_REGEX_CACHE: Dict[Tuple[str, ...], "re.Pattern[str]"] = {}

_STACK_EFFECT_RE = re.compile(r'\[([^\]]*)\]\s*->\s*\[([^\]]*)\]')

def _parse_stack_effect_comment_full(
    source: str, word_token_start: int
) -> Optional[Tuple[Optional[int], Optional[int]]]:
    """Extract ``(inputs, outputs)`` from a stack-effect comment.

    Counts named items in the bracketed arrow form for compiler metadata,
    excluding the preserved-stack ``*`` marker. A side containing ``...``
    is variable-arity and is returned as ``None``.
    """
    line_start = source.rfind('\n', 0, word_token_start)
    line_start = 0 if line_start == -1 else line_start + 1
    line_end = source.find('\n', word_token_start)
    if line_end == -1:
        line_end = len(source)
    lines_to_check = [source[line_start:line_end]]
    if line_start > 0:
        prev_end = line_start - 1
        prev_start = source.rfind('\n', 0, prev_end)
        prev_start = 0 if prev_start == -1 else prev_start + 1
        lines_to_check.append(source[prev_start:prev_end])

    for line in lines_to_check:
        comment_start = line.find('#')
        if comment_start == -1:
            continue
        match = _STACK_EFFECT_RE.search(line[comment_start + 1:])
        if match is None:
            continue

        def count_items(side: str) -> Optional[int]:
            if "..." in side:
                return None
            return sum(
                1
                for item in re.split(r'[,|]', side)
                if item.strip() and item.strip() != '*'
            )

        return count_items(match.group(1)), count_items(match.group(2))
    return None

# The Unicode White_Space property, frozen as part of the L2 specification
# (character classification): token gaps and separator validation
# use exactly these 25 code points, never the host's Unicode database.
_L2_WHITESPACE = (
    "\u0009\u000a\u000b\u000c\u000d \u0085  "
    "           "
    "    　"
)
_L2_WHITESPACE_SET = frozenset(_L2_WHITESPACE)
_L2_WHITESPACE_CLASS = "".join(f"\\u{ord(ch):04x}" for ch in _L2_WHITESPACE)

# The default tokenizer's initial separator set.
DEFAULT_TOKENIZER_SEPARATORS: Tuple[str, ...] = ("(", ")", "{", "}", ";", ",", "[", "]")
# Characters with fixed lexical meaning that a separator may not contain.
_TOKENIZER_RESERVED_CHARS = frozenset('"\'`#')
_TOKENIZER_CONFIG_KEYS = ("separators",)
# A character literal body: exactly one code point, or one escape spelling.
_CHAR_LITERAL_BODY_RE = re.compile(r"[^\\]|\\.|\\x[0-9A-Fa-f]{2}", re.DOTALL)


def _lexer_error(code: str, message: str, origin: Optional[SourceOrigin] = None) -> ParseError:
    return ParseError(message, code=code, origin=origin)


def validate_tokenizer_separators(value: Any, word: str = "ct-tokenizer-set-config") -> List[str]:
    """Validate a `separators` setting and return it with duplicates removed
    (first occurrence kept).  Raises tokenizer-config-invalid."""
    if not isinstance(value, list):
        raise ParseError(f"{word}: 'separators' must be a list of strings, "
                         f"got {_ct_type_name(value)}", code="tokenizer-config-invalid")
    seen: List[str] = []
    for index, item in enumerate(value):
        if not isinstance(item, str):
            raise ParseError(f"{word}: separator {index} must be a string, "
                             f"got {_ct_type_name(item)}", code="tokenizer-config-invalid")
        if item == "":
            raise ParseError(f"{word}: separator {index} is empty", code="tokenizer-config-invalid")
        bad = next((ch for ch in item if ch in _L2_WHITESPACE_SET or ch in _TOKENIZER_RESERVED_CHARS), None)
        if bad is not None:
            raise ParseError(f"{word}: separator {item!r} contains {bad!r}; "
                             "separators may not contain whitespace, quotes, backticks, or '#'", code="tokenizer-config-invalid")
        if item not in seen:
            seen.append(item)
    return seen


def _asm_raw_body_end(source: str, pos: int) -> int:
    """Index of the `}` that closes an `:asm` body starting at `pos`, or -1.
    The body is raw assembly: `;` comments run to the end of the line and
    quoted strings to their closing quote (or the end of the line), so a `}`
    or a quote inside them neither closes the body nor confuses the lexer."""
    n = len(source)
    i = pos
    find = source.find
    while i < n:
        ch = source[i]
        if ch == "}":
            return i
        if ch == ";":
            nl = find("\n", i)
            i = n if nl == -1 else nl
            continue
        if ch == "'" or ch == '"' or ch == "`":
            nl = find("\n", i + 1)
            limit = n if nl == -1 else nl
            close = find(ch, i + 1, limit)
            i = limit if close == -1 else close + 1
            continue
        i += 1
    return -1


class _AsmHeaderTracker:
    """Recognizes `:asm <name> [( effects )] {` in a token stream; `feed`
    returns True on the `{` that opens a raw assembly body."""

    __slots__ = ('state',)

    def __init__(self) -> None:
        self.state = 0

    def feed(self, lexeme: str) -> bool:
        state = self.state
        if state == 0:
            if lexeme == ":asm":
                self.state = 1
            return False
        if state == 1:
            self.state = 2
            return False
        if state == 2:
            if lexeme == "(":
                self.state = 3
                return False
            self.state = 1 if lexeme == ":asm" else 0
            return lexeme == "{"
        if lexeme == ")":
            self.state = 2
        return False


# First characters that make _handle_token try a literal (with + and -
# followed by more, and any non-ASCII digit).
_LITERAL_FIRST_CHARS = frozenset('0123456789".\'')

# First characters of tokens that need the tokenizer's special handling:
# comments, literals, backticks, and the parts of `:asm` headers and bodies.
_TOKEN_SPECIAL_FIRST = frozenset('#;"\'`:{}')


class Reader:
    """Default L2 tokenizer.  Its compiler-scoped configuration is the
    `separators` list; string, character, comment, and backtick rules are
    fixed."""

    def __init__(self) -> None:
        self.line = 1
        self.column = 0
        self.separators: Tuple[str, ...] = DEFAULT_TOKENIZER_SEPARATORS
        self._token_re: Optional["re.Pattern[str]"] = None

    def get_config(self) -> Dict[str, Any]:
        """Detached snapshot of the configuration map."""
        return {"separators": list(self.separators)}

    def set_config(self, config: Any, word: str = "ct-tokenizer-set-config") -> None:
        """Validate the complete map, then replace the active configuration."""
        if not isinstance(config, Mapping):
            raise ParseError(f"{word}: expected a map, got {_ct_type_name(config)}", code="tokenizer-config-invalid")
        for key in config:
            if key not in _TOKENIZER_CONFIG_KEYS:
                raise ParseError(f"{word}: unknown key {key!r}", code="tokenizer-config-invalid")
        if "separators" not in config:
            raise ParseError(f"{word}: missing required key 'separators'", code="tokenizer-config-invalid")
        separators = validate_tokenizer_separators(config["separators"], word)
        self.separators = tuple(separators)
        self._token_re = None

    def _build_token_re(self) -> "re.Pattern[str]":
        """Compiled regex for the current separator set.  Alternatives in
        priority order: string literal, character literal, comment, escaped
        backtick, backtick, separator (longest first), ordinary word."""
        cache_key = self.separators
        cached = _READER_REGEX_CACHE.get(cache_key)
        if cached is not None:
            return cached
        ordered = sorted(self.separators, key=len, reverse=True)
        singles = {sep for sep in ordered if len(sep) == 1}
        multis = [sep for sep in ordered if len(sep) > 1]
        # Characters that can never continue a word.
        excluded = set('#"\'`') | singles
        # Characters that continue a word unless they start an escaped
        # backtick, an escaped backslash right before a backtick, or a
        # multi-character separator.
        guarded = ({"\\"} | {sep[0] for sep in multis}) - excluded
        guards = [r"\\\\`", r"\\`"] + [re.escape(sep) for sep in multis]
        plain_class = _L2_WHITESPACE_CLASS + "".join(re.escape(ch) for ch in sorted(excluded | guarded))
        # Runs of plain characters are consumed in one step ([^...]+ inside
        # the repetition); this matches exactly what one character per step
        # would, since nothing follows the word alternative.
        if guarded:
            guarded_class = "".join(re.escape(ch) for ch in sorted(guarded))
            word = rf"(?:[^{plain_class}]+|(?!{'|'.join(guards)})[{guarded_class}])+"
        else:
            word = rf"[^{plain_class}]+"
        sep_part = "".join(f"|{re.escape(sep)}" for sep in ordered)
        pattern = (
            r'"[^"\\]*(?:\\.[^"\\]*)*"?'  # string literal (possibly unterminated)
            r"|'[^'\\]*(?:\\.[^'\\]*)*'?"  # character literal (possibly unterminated)
            r"|#[^\n\r]*"                 # comment, up to the line break
            r"|\\\\(?=`)"                # `\\` right before a backtick: an escaped backslash
            r"|\\`|`"                     # escaped backtick, backtick
            rf"{sep_part}"                # configured separators, longest first
            rf"|{word}"                   # ordinary word
        )
        # The token is group 1.  Whitespace never starts a token (unless a
        # separator contains it), so the pattern consumes leading whitespace
        # itself instead of failing every alternative at each blank.
        if any(ch in _L2_WHITESPACE for sep in ordered for ch in sep):
            pattern = f"({pattern})"
        else:
            pattern = f"[{_L2_WHITESPACE_CLASS}]*({pattern})"
        compiled = re.compile(pattern, re.DOTALL)
        _READER_REGEX_CACHE[cache_key] = compiled
        return compiled

    def _check_literal(self, text: str, start: int, end: int, origin_at: Callable[[int, int], SourceOrigin]) -> None:
        first = text[start]
        # Closed iff the match ends with the opening quote character and
        # that quote is not escaped (an even run of backslashes before it).
        closed = end - start >= 2 and text[end - 1] == first
        if closed:
            backslashes = 0
            index = end - 2
            while index > start and text[index] == "\\":
                backslashes += 1
                index -= 1
            closed = backslashes % 2 == 0
        if first == '"':
            if not closed:
                raise _lexer_error("lexer-unterminated-string", "unterminated string literal",
                                   origin_at(start, len(text)))
            return
        if not closed:
            raise _lexer_error("lexer-unterminated-char", "unterminated character literal",
                               origin_at(start, len(text)))
        if _CHAR_LITERAL_BODY_RE.fullmatch(text, start + 1, end - 1) is None:
            raise _lexer_error("lexer-invalid-char-literal",
                               f"character literal {text[start:end]!r} must contain exactly one character "
                               "or one escape", origin_at(start, end))

    def tokenize(self, source: str, spans: Optional[Sequence["FileSpan"]] = None,
                 default_path: str = "<source>") -> List[Token]:
        """Tokenize the flattened compiler source.  `spans` map the flattened
        lines back to the original files so each Token's origin names its
        real file and offset."""
        token_re = self._token_re
        if token_re is None:
            token_re = self._token_re = self._build_token_re()
        # Pre-compute line start offsets for O(1) amortized line/column lookup
        _line_starts = [0]
        _line_starts_append = _line_starts.append
        _find = source.find
        _nl_pos = _find('\n')
        while _nl_pos != -1:
            _line_starts_append(_nl_pos + 1)
            _nl_pos = _find('\n', _nl_pos + 1)
        _n_lines = len(_line_starts)
        result: List[Token] = []
        _append = result.append
        srcmap = SourceMap(source, _line_starts, spans, default_path)

        def origin_at(start: int, end: int) -> SourceOrigin:
            line = bisect.bisect_right(_line_starts, start)
            probe = Token(source[start:end] or " ", line, start - _line_starts[line - 1], start, end, srcmap=srcmap)
            return probe.origin

        _Builder_new = _TokenBuilder_new
        _Builder_cls = _TokenBuilder
        _Token_cls = Token
        # Linear scan: tokens arrive in source order, so line index only advances
        _cur_li = 0
        _next_line_start = _line_starts[1] if _n_lines > 1 else 0x7FFFFFFFFFFFFFFF
        # `:asm` bodies are raw text: the body between `{` and `}` becomes
        # one token holding it verbatim, and scanning resumes at the `}`.
        # Inside a backtick quotation the body stays tokenized, so `$name`
        # splices in a generated `:asm` body keep working.
        asm_header = _AsmHeaderTracker()
        _asm_feed = asm_header.feed
        in_quotation = False
        quoted_asm = False  # inside an `:asm` body written in a quotation
        scan_from = 0
        while True:
            raw_start = -1
            resume_at = -1
            for m in token_re.finditer(source, scan_from):
                start, end = m.span(1)
                fc = source[start]
                if fc not in _TOKEN_SPECIAL_FIRST and not quoted_asm:
                    # The common case: a token whose first character needs
                    # none of the checks below (same steps, fewer tests).
                    while start >= _next_line_start:
                        _cur_li += 1
                        _next_line_start = _line_starts[_cur_li + 1] if _cur_li + 1 < _n_lines else 0x7FFFFFFFFFFFFFFF
                    tok = _Builder_new(_Builder_cls)
                    lexeme = tok.lexeme = source[start:end]
                    tok.line = _cur_li + 1
                    tok.column = start - _line_starts[_cur_li]
                    tok.start = start
                    tok.end = end
                    tok.expansion_depth = 0
                    tok._srcmap = srcmap
                    tok._origin = None
                    tok.expansion_chain = ()
                    tok.__class__ = _Token_cls
                    _append(tok)
                    if asm_header.state and _asm_feed(lexeme):
                        if in_quotation:
                            quoted_asm = True
                        else:
                            raw_start = end
                            break
                    continue
                if fc == '#':
                    continue  # skip comment
                if quoted_asm and fc == ';':
                    # An assembler comment in a quoted :asm body: one token to
                    # the end of the line, so any character may appear in it.
                    end = source.find('\n', start)
                    if end < 0:
                        end = len(source)
                    resume_at = end
                elif fc == '"' or fc == "'":
                    self._check_literal(source, start, end, origin_at)
                # Advance line index to find the correct line for this position
                while start >= _next_line_start:
                    _cur_li += 1
                    _next_line_start = _line_starts[_cur_li + 1] if _cur_li + 1 < _n_lines else 0x7FFFFFFFFFFFFFFF
                tok = _Builder_new(_Builder_cls)
                lexeme = tok.lexeme = source[start:end]
                tok.line = _cur_li + 1
                tok.column = start - _line_starts[_cur_li]
                tok.start = start
                tok.end = end
                tok.expansion_depth = 0
                tok._srcmap = srcmap
                tok._origin = None
                tok.expansion_chain = ()
                tok.__class__ = _Token_cls  # the builder is unguarded: a plain store
                _append(tok)
                if resume_at >= 0:
                    break
                if fc == '`' and end - start == 1:
                    in_quotation = not in_quotation
                    quoted_asm = False
                elif quoted_asm:
                    if fc == '}':
                        quoted_asm = False
                elif (fc == ':' or fc == '{' or asm_header.state) and _asm_feed(lexeme):
                    if in_quotation:
                        quoted_asm = True
                    else:
                        raw_start = end
                        break
            if resume_at >= 0:
                scan_from = resume_at
                continue
            if raw_start < 0:
                break
            close = _asm_raw_body_end(source, raw_start)
            if close < 0:
                scan_from = raw_start  # unterminated: the parser reports the missing '}'
                continue
            body_start = raw_start
            while body_start < close and source[body_start] in " \t\r\n":
                body_start += 1
            if body_start < close:
                while body_start >= _next_line_start:
                    _cur_li += 1
                    _next_line_start = _line_starts[_cur_li + 1] if _cur_li + 1 < _n_lines else 0x7FFFFFFFFFFFFFFF
                tok = _Builder_new(_Builder_cls)
                tok.lexeme = source[body_start:close]
                tok.line = _cur_li + 1
                tok.column = body_start - _line_starts[_cur_li]
                tok.start = body_start
                tok.end = close
                tok.expansion_depth = 0
                tok._srcmap = srcmap
                tok._origin = None
                tok.expansion_chain = ()
                tok.__class__ = _Token_cls
                _append(tok)
            scan_from = close
        # Update reader state to end-of-source position
        self.line = _n_lines
        self.column = len(source) - _line_starts[_n_lines - 1]
        return result

    def tokenize_text(self, text: str, path: str) -> List[Token]:
        """`ct-tokenizer-run`: tokenize original source text (not the
        flattened compiler source).  Each Token carries an explicit
        SourceOrigin in `text`, with LF, CRLF, and lone CR line breaks."""
        token_re = self._token_re
        if token_re is None:
            token_re = self._token_re = self._build_token_re()
        file_text = _SourceFileText(text)
        line_column = file_text.line_column

        def origin_at(start: int, end: int) -> SourceOrigin:
            start_line, start_column = line_column(start)
            end_line, end_column = line_column(end)
            return SourceOrigin(path, start, end, start_line, start_column, end_line, end_column)

        result: List[Token] = []
        asm_header = _AsmHeaderTracker()
        in_quotation = False
        quoted_asm = False
        scan_from = 0
        while True:
            raw_start = -1
            resume_at = -1
            for m in token_re.finditer(text, scan_from):
                start, end = m.span(1)
                fc = text[start]
                if fc == '#':
                    continue
                if quoted_asm and fc == ';':
                    end = text.find('\n', start)
                    if end < 0:
                        end = len(text)
                    resume_at = end
                elif fc == '"' or fc == "'":
                    self._check_literal(text, start, end, origin_at)
                origin = origin_at(start, end)
                lexeme = text[start:end]
                result.append(Token(lexeme, origin.start_line, origin.start_column - 1, start, end,
                                    origin=origin))
                if resume_at >= 0:
                    break
                if lexeme == "`":
                    in_quotation = not in_quotation
                    quoted_asm = False
                elif quoted_asm:
                    if lexeme == "}":
                        quoted_asm = False
                elif asm_header.feed(lexeme):
                    if in_quotation:
                        quoted_asm = True
                    else:
                        raw_start = end
                        break
            if resume_at >= 0:
                scan_from = resume_at
                continue
            if raw_start < 0:
                break
            close = _asm_raw_body_end(text, raw_start)
            if close < 0:
                scan_from = raw_start
                continue
            body_start = raw_start
            while body_start < close and text[body_start] in " \t\r\n":
                body_start += 1
            if body_start < close:
                origin = origin_at(body_start, close)
                result.append(Token(text[body_start:close], origin.start_line, origin.start_column - 1,
                                    body_start, close, origin=origin))
            scan_from = close
        return result


