    "and", "or", "xor", "not", "neg", "inc", "dec", "cmp", "test", "call", "jmp", "je", "jne", "jg",
    "jge", "jl", "jle", "ja", "jae", "jb", "jbe", "jnz", "jz", "ret", "syscall", "nop", "sal", "sar",
