class Op:
    """Flat operation used for both compile-time execution and emission."""
    __slots__ = ('op', 'data', 'loc', '_word_ref', '_opcode')

    def __init__(self, op: str, data: Any = None, loc: Optional[SourceLocation] = None,
                 _word_ref: Optional[Word] = None, _opcode: int = OP_OTHER) -> None:
        self.op = op
        self.data = data
        self.loc = loc
        self._word_ref = _word_ref
        self._opcode = _OP_STR_TO_INT.get(op, OP_OTHER)


def _make_op(op: str, data: Any = None, loc: Optional[SourceLocation] = None) -> Op:
    """Fast Op constructor that avoids dict lookup for known opcodes."""
    node = Op.__new__(Op)
    node.op = op
    node.data = data
    node.loc = loc
    node._word_ref = None
    node._opcode = _OP_STR_TO_INT.get(op, OP_OTHER)
    return node


def _make_literal_op(data: Any, loc: Optional[SourceLocation] = None) -> Op:
    """Specialized Op constructor for 'literal' ops."""
    node = Op.__new__(Op)
    node.op = "literal"
    node.data = data
    node.loc = loc
    node._word_ref = None
    node._opcode = OP_LITERAL
    return node


def _make_word_op(data: str, loc: Optional[SourceLocation] = None) -> Op:
    """Specialized Op constructor for 'word' ops."""
    node = Op.__new__(Op)
    node.op = "word"
    node.data = data
    node.loc = loc
    node._word_ref = None
    node._opcode = OP_WORD
    return node


_PARSE_LITERAL_CACHE_MAX = 8192
_PARSE_LITERAL_CACHE_MISS = object()
_PARSE_LITERAL_NOT_LITERAL = object()
_PARSE_LITERAL_CACHE: Dict[str, Any] = {}


class Definition:
    __slots__ = ('name', 'body', 'immediate', 'compile_only', 'runtime_only', 'terminator', 'inline',
                 'preserve', 'stack_inputs', 'stack_outputs', 'effect_exact', '_label_positions',
                 '_for_pairs', '_words_resolved', '_merged_runs')

    def __init__(self, name: str, body: List[Op], immediate: bool = False,
                 compile_only: bool = False, runtime_only: bool = False, terminator: str = "end", inline: bool = False,
                 stack_inputs: Optional[int] = None,
                 stack_outputs: Optional[int] = None, preserve: bool = False) -> None:
        self.name = name
        self.body = body
        self.immediate = immediate
        self.compile_only = compile_only
        self.runtime_only = runtime_only
        self.terminator = terminator
        self.inline = inline
        self.preserve = preserve
        self.stack_inputs = stack_inputs
        self.stack_outputs = stack_outputs
        # True when the effect was declared in cells (ct-definition-set-effect
        # / stack-effect), so the stack checker can rely on it; effect comments
        # count items, not cells (a string is one item, two cells).
        self.effect_exact = False
        self._label_positions = None
        self._for_pairs = None
        self._words_resolved = False
        self._merged_runs = None


class AsmDefinition:
    __slots__ = ('name', 'body', 'immediate', 'compile_only', 'runtime_only', 'inline', 'preserve', 'effects', '_inline_lines', 'stack_inputs', 'stack_outputs', 'effect_exact')

    def __init__(self, name: str, body: str, immediate: bool = False,
                 compile_only: bool = False, runtime_only: bool = False, inline: bool = False,
                 effects: Set[str] = None, _inline_lines: Optional[List[str]] = None,
                 stack_inputs: Optional[int] = None, stack_outputs: Optional[int] = None,
                 preserve: bool = False) -> None:
        self.name = name
        self.body = body
        self.immediate = immediate
        self.compile_only = compile_only
        self.runtime_only = runtime_only
        self.inline = inline
        self.preserve = preserve
        self.effects = effects if effects is not None else set()
        self._inline_lines = _inline_lines
        self.stack_inputs = stack_inputs
        self.stack_outputs = stack_outputs
        # True when the effect was declared in cells (ct-definition-set-effect
        # / stack-effect), so the stack checker can rely on it; effect comments
        # count items, not cells (a string is one item, two cells).
        self.effect_exact = False


class _AsmFragment(str):
    """A CT-supplied assembler fragment.  Emitted verbatim; at a
    boundary with another emitted segment one LF is inserted only when
    neither side already has a line terminator there."""

    __slots__ = ()


_LINE_TERMINATORS = ("\n", "\r")

# The standard runtime BSS layout: the initial runtime BSS buffer.
_RUNTIME_BSS_LAYOUT: Tuple[str, ...] = (
    "global dstack",
    "global dstack_top",
    "global rstack",
    "global rstack_top",
    "align 16",
    "dstack: resb DSTK_BYTES",
    "dstack_top:",
    "align 16",
    "rstack: resb RSTK_BYTES",
    "rstack_top:",
    "align 16",
    "print_buf: resb PRINT_BUF_BYTES",
    "print_buf_end:",
    "align 16",
    "persistent: resb 64",
    "align 16",
    "list_capture_sp: resq 1",
    "list_capture_tmp: resq 1",
    "list_capture_stack: resq 1024",
)


def _join_asm_lines(lines: Sequence[str]) -> str:
    """Join emitted lines.  Compiler lines are separated by LF; around a
    CT fragment the LF is added only when needed, and an empty fragment
    contributes nothing."""
    out: List[str] = []
    previous: Optional[str] = None
    for line in lines:
        fragment = type(line) is _AsmFragment
        if fragment and not line:
            continue
        if previous is not None:
            if not ((fragment or type(previous) is _AsmFragment)
                    and (previous.endswith(_LINE_TERMINATORS) or line.startswith(_LINE_TERMINATORS))):
                out.append("\n")
        out.append(line)
        previous = line
    return "".join(out)


class Module:
    __slots__ = ('forms', 'variables', 'text_preamble', 'data', 'bss', 'cstruct_layouts')

    def __init__(self, forms: List[Any], variables: Dict[str, str] = None,
                 text_preamble: Optional[List[str]] = None,
                 data: Optional[List[str]] = None,
                 bss: Optional[List[str]] = None,
                 cstruct_layouts: Dict[str, CStructLayout] = None) -> None:
        self.forms = forms
        self.variables = variables if variables is not None else {}
        # CT-supplied .text and .data fragments; the effective runtime BSS
        # buffer (None means the standard layout).
        self.text_preamble = text_preamble if text_preamble is not None else []
        self.data = data if data is not None else []
        self.bss = bss
        self.cstruct_layouts = cstruct_layouts if cstruct_layouts is not None else {}


class RewriteHandle:
    """Opaque, immutable identity of one rewrite registration.
    Handles are never reused and go stale when their rule is removed."""

    __slots__ = ('id',)

    def __init__(self, ident: int) -> None:
        self.id = ident

    def __eq__(self, other: object) -> bool:
        return isinstance(other, RewriteHandle) and other.id == self.id

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __hash__(self) -> int:
        return hash(("RewriteHandle", self.id))

    def __repr__(self) -> str:
        return f"<RewriteHandle {self.id}>"


_REWRITE_STAGES = ("reader", "grammar")
# Rewrite handle ids double as registration order; never reused.
_REWRITE_IDS = itertools.count(1)
_REWRITE_CONSTRAINTS = frozenset({"any", "ident", "int", "float", "number", "string", "char", "literal"})
_RE_REWRITE_CAPTURE = re.compile(r"\$(\*?)([A-Za-z_][A-Za-z0-9_]*|[0-9]+)(?::(.*))?\Z", re.S)
_REWRITE_LIT, _REWRITE_WILD, _REWRITE_CAP = 0, 1, 2


class _RewritePiece:
    """One compiled rewrite-pattern element: a literal, the bare `*`
    wildcard, or a capture; `multi` marks a capture bound to a lexeme
    sequence (variadic or quantified) rather than one lexeme."""

    __slots__ = ('kind', 'text', 'constraint', 'negated', 'min_count', 'max_count', 'multi')

    def __init__(self, kind: int, text: str, constraint: Optional[str], negated: bool,
                 min_count: int, max_count: Optional[int], multi: bool) -> None:
        self.kind = kind
        self.text = text
        self.constraint = constraint
        self.negated = negated
        self.min_count = min_count
        self.max_count = max_count
        self.multi = multi

    def accepts(self, lexeme: str) -> bool:
        """Whether one lexeme satisfies the element, ignoring negation."""
        kind = self.kind
        if kind == _REWRITE_LIT:
            return lexeme == self.text
        if kind == _REWRITE_WILD:
            return True
        constraint = self.constraint
        return constraint is None or _match_token_kind(lexeme, constraint)


# ---------------------------------------------------------------------------
# § 7. Rewrites
# ---------------------------------------------------------------------------

def _rewrite_error(code: str, message: str, phase: Optional[str] = None) -> ParseError:
    return ParseError(message, code=code, phase=phase)


def _rewrite_parse_piece(piece: Any) -> _RewritePiece:
    """Compile one pattern element (shared element rules plus the
    rewrite-only negation, `$*name`, and quantifier forms)."""
    def bad(reason: str) -> ParseError:
        return _rewrite_error("rewrite-pattern-invalid", f"invalid rewrite pattern element {piece!r}: {reason}")

    if not isinstance(piece, str) or piece == "":
        raise bad("pattern elements must be nonempty strings")
    body = piece
    negated = False
    if body[0] == "!" and len(body) > 1:
        negated = True
        body = body[1:]
    if body[0] == "\\":
        if len(body) == 1:
            raise bad("an element of only '\\' is invalid")
        return _RewritePiece(_REWRITE_LIT, body[1:], None, negated, 1, 1, False)
    if body[0] == "$" and len(body) > 1:
        quantifier = ""
        if len(body) > 2 and body[-1] in "?*+":
            quantifier = body[-1]
            body = body[:-1]
        match = _RE_REWRITE_CAPTURE.match(body)
        if match is None:
            raise bad("malformed capture; write '\\' before it to match the text literally")
        variadic = match.group(1) == "*"
        name = match.group(2)
        constraint = match.group(3)
        if constraint is not None and constraint not in _REWRITE_CONSTRAINTS:
            if constraint == "syntax":
                raise bad("the 'syntax' constraint is only valid in match patterns; rewrites see Tokens")
            raise bad(f"unknown constraint '{constraint}'; use one of {', '.join(sorted(_REWRITE_CONSTRAINTS))}")
        if negated and (variadic or quantifier):
            raise bad("negation cannot combine with a variadic capture or a quantifier")
        if variadic and quantifier:
            raise bad("a '$*' sequence capture cannot take a quantifier")
        if negated:
            return _RewritePiece(_REWRITE_CAP, name, constraint, True, 1, 1, False)
        if variadic:
            return _RewritePiece(_REWRITE_CAP, name, constraint, False, 0, None, True)
        counts = _REWRITE_QUANTIFIERS[quantifier]
        return _RewritePiece(_REWRITE_CAP, name, constraint, False, counts[0], counts[1], quantifier != "")
    if body == "*":
        if negated:
            raise bad("the wildcard '*' cannot be negated")
        return _RewritePiece(_REWRITE_WILD, "*", None, False, 1, 1, False)
    quantifier = ""
    if len(body) > 1 and body[-1] in "?*+":
        quantifier = body[-1]
        body = body[:-1]
        if body == "*":
            raise bad("the wildcard '*' cannot take a quantifier; write '\\*' for a literal '*'")
        if negated:
            raise bad("negation cannot combine with a quantifier")
    counts = _REWRITE_QUANTIFIERS[quantifier]
    return _RewritePiece(_REWRITE_LIT, body, None, negated, counts[0], counts[1], False)


_REWRITE_QUANTIFIERS: Dict[str, Tuple[int, Optional[int]]] = {
    "": (1, 1), "?": (0, 1), "*": (0, None), "+": (1, None),
}


def _rewrite_compile(pattern: Any, replacement: Any) -> Tuple[Tuple[_RewritePiece, ...], Tuple[Tuple[int, str], ...]]:
    """Validate a complete rule and return its compiled pattern and
    replacement (entries (0, literal), (1, single capture), (2, sequence))."""
    if not isinstance(pattern, list):
        raise _rewrite_error("rewrite-pattern-invalid", f"rewrite pattern must be a list of strings, got {_ct_type_name(pattern)}")
    if not isinstance(replacement, list):
        raise _rewrite_error("rewrite-pattern-invalid",
                             f"rewrite replacement must be a list of strings, got {_ct_type_name(replacement)}")
    pieces = tuple(_rewrite_parse_piece(piece) for piece in pattern)
    shapes: Dict[str, bool] = {}
    for piece in pieces:
        if piece.kind != _REWRITE_CAP or piece.negated:
            continue
        previous = shapes.setdefault(piece.text, piece.multi)
        if previous != piece.multi:
            raise _rewrite_error("rewrite-pattern-invalid",
                                 f"rewrite capture '{piece.text}' mixes single-token and sequence shapes")
    if sum(piece.min_count for piece in pieces) < 1:
        raise _rewrite_error("rewrite-pattern-invalid", "a rewrite pattern must match at least one token")
    compiled: List[Tuple[int, str]] = []
    for element in replacement:
        if not isinstance(element, str) or element == "":
            raise _rewrite_error("rewrite-pattern-invalid",
                                 f"rewrite replacement elements must be nonempty strings, got {element!r}")
        if element[0] == "\\":
            if len(element) == 1:
                raise _rewrite_error("rewrite-pattern-invalid", "a replacement element of only '\\' is invalid")
            compiled.append((0, element[1:]))
            continue
        if element[0] != "$" or len(element) == 1:
            compiled.append((0, element))
            continue
        match = _RE_REWRITE_CAPTURE.match(element)
        if match is None or match.group(3) is not None:
            raise _rewrite_error("rewrite-pattern-invalid",
                                 f"invalid replacement reference {element!r}: references are '$name' or '$*name' "
                                 f"without a constraint; write '\\{element}' for the literal")
        name = match.group(2)
        sequence = match.group(1) == "*"
        if name not in shapes:
            raise _rewrite_error("rewrite-pattern-invalid", f"replacement reference {element!r} is not bound by the pattern")
        if sequence != shapes[name]:
            if sequence:
                raise _rewrite_error("rewrite-pattern-invalid",
                                     f"replacement reference {element!r} needs a sequence capture; '${name}' binds one token")
            raise _rewrite_error("rewrite-pattern-invalid",
                                 f"replacement reference {element!r} needs a single-token capture; "
                                 f"'{name}' binds a sequence, use '$*{name}'")
        compiled.append((2 if sequence else 1, name))
    return pieces, tuple(compiled)


class RewriteRule:
    """One reader- or grammar-stage rewrite registration."""

    __slots__ = (
        'handle', 'stage', 'name', 'pattern', 'replacement', 'priority', 'order', 'enabled',
        'pipeline', 'guard', 'owner', 'pieces', 'repl', 'min_suffix', 'anchor', 'applied',
    )

    def __init__(self, handle: RewriteHandle, stage: str, name: str, pattern: Sequence[str],
                 replacement: Sequence[str], pieces: Tuple[_RewritePiece, ...],
                 repl: Tuple[Tuple[int, str], ...], order: int, owner: Optional[str]) -> None:
        self.handle = handle
        self.stage = stage
        self.name = name
        self.pattern = tuple(pattern)
        self.replacement = tuple(replacement)
        self.priority = 0
        self.order = order
        self.enabled = True
        self.pipeline = "default"
        self.guard: Optional[str] = None
        self.owner = owner
        self.pieces = pieces
        self.repl = repl
        self.applied = 0
        suffix = [0] * (len(pieces) + 1)
        for index in range(len(pieces) - 1, -1, -1):
            suffix[index] = suffix[index + 1] + pieces[index].min_count
        self.min_suffix = tuple(suffix)
        # (offset, lexeme) of the first required literal reachable through
        # fixed-width elements: the rule can only match where that lexeme
        # sits at that offset from the cursor.
        anchor: Optional[Tuple[int, str]] = None
        offset = 0
        for piece in pieces:
            if piece.kind == _REWRITE_LIT and not piece.negated and piece.min_count > 0:
                anchor = (offset, piece.text)
                break
            if piece.min_count != piece.max_count:
                break
            offset += piece.min_count
        self.anchor = anchor

    def rank(self) -> Tuple[int, int]:
        return (-self.priority, self.order)


def _rewrite_match(rule: RewriteRule, tokens: List["Token"], start: int) -> Optional[Tuple[int, Dict[str, Any], int]]:
    """Match a rule at `start`: (end, captures, max expansion depth) or None.
    Repetitions try larger counts first and backtrack."""
    pieces = rule.pieces
    suffix = rule.min_suffix
    count = len(tokens)
    if start + suffix[0] > count:
        return None
    last = len(pieces)

    def step(index: int, pos: int, captures: Dict[str, Any], depth: int) -> Optional[Tuple[int, Dict[str, Any], int]]:
        if index == last:
            return pos, captures, depth
        piece = pieces[index]
        budget = count - pos - suffix[index + 1]
        low = piece.min_count
        if budget < low:
            return None
        if piece.negated:
            token = tokens[pos]
            if piece.accepts(token.lexeme):
                return None
            token_depth = token.expansion_depth
            return step(index + 1, pos + 1, captures, token_depth if token_depth > depth else depth)
        high = budget if piece.max_count is None else min(budget, piece.max_count)
        run = 0
        while run < high and piece.accepts(tokens[pos + run].lexeme):
            run += 1
        if run < low:
            return None
        capture = piece.kind == _REWRITE_CAP
        for take in range(run, low - 1, -1):
            next_captures = captures
            if capture:
                if piece.multi:
                    value: Any = tuple(token.lexeme for token in tokens[pos:pos + take])
                else:
                    value = tokens[pos].lexeme
                name = piece.text
                if name in captures:
                    if captures[name] != value:
                        continue
                else:
                    next_captures = dict(captures)
                    next_captures[name] = value
            next_depth = depth
            for token in tokens[pos:pos + take]:
                if token.expansion_depth > next_depth:
                    next_depth = token.expansion_depth
            result = step(index + 1, pos + take, next_captures, next_depth)
            if result is not None:
                return result
        return None

    return step(0, start, {}, tokens[start].expansion_depth)


def _rewrite_build(rule: RewriteRule, captures: Dict[str, Any]) -> List[str]:
    out: List[str] = []
    for kind, value in rule.repl:
        if kind == 0:
            out.append(value)
        elif kind == 1:
            out.append(captures[value])
        else:
            out.extend(captures[value])
    return out


class _RewriteWindow:
    """Exact seen-state set for one stage at one cursor.  Every state
    shares the prefix before `start` and an unchanged tail of the original
    sequence (`tail` tokens long); a state is keyed by its total length and
    the lexemes between the two, so comparing states costs only the edited
    region rather than the whole token list."""

    __slots__ = ('start', 'tail', 'length', 'anchor', 'states')

    def __init__(self, start: int, tail: int, length: int, anchor: Optional["Token"],
                 states: Dict[Tuple[int, Tuple[str, ...]], Tuple[int, Optional[RewriteRule]]]) -> None:
        self.start = start
        self.tail = tail
        self.length = length
        self.anchor = anchor
        self.states = states


class _RewriteRun:
    """One application context: the live parse, or a list simulation with
    its own step counter, budget, seen states, and patch list."""

    __slots__ = ('count', 'limit', 'windows', 'patches', 'live')

    def __init__(self, limit: Optional[int], live: bool) -> None:
        self.count = 0
        self.limit = limit
        self.windows: Dict[str, _RewriteWindow] = {}
        self.patches: Optional[List[Dict[str, Any]]] = None if live else []
        self.live = live


def _rewrite_pop_handle(vm: "CompileTimeVM", word: str, phase: str) -> RewriteHandle:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, RewriteHandle):
        raise _rewrite_error("rewrite-handle-invalid", f"{word} expects a RewriteHandle, got {_ct_type_name(value)}",
                             phase=phase)
    return value


class RewriteEngine:
    """Reader/grammar rewrite registrations, pipelines, controls, and
    application.  The candidate index holds only eligible rules
    (enabled, on an active pipeline, owner active) in selection order and
    is rebuilt lazily after any change."""

    def __init__(self, parser: "Parser") -> None:
        self._parser = parser
        self.rules: Dict[str, List[RewriteRule]] = {"reader": [], "grammar": []}
        self.live: Dict[int, RewriteRule] = {}
        self._generated = 0
        self.pipelines: Dict[str, Set[str]] = {"reader": {"default"}, "grammar": {"default"}}
        self.scope_stack: List[Dict[str, Set[str]]] = []
        self.max_steps = 100_000
        self.loop_detection = True
        self.loop_reports: List[Dict[str, Any]] = []
        # Conservatively true while an index is stale; exact after a rebuild.
        self.any_reader = False
        self.any_grammar = False
        self._index: Dict[str, Optional[Tuple[Tuple[Tuple[int, Dict[str, List[RewriteRule]]], ...], List[RewriteRule]]]] = {
            "reader": None, "grammar": None,
        }
        self._live_run = _RewriteRun(None, True)

    # -- Index ------------------------------------------------------------------

    def invalidate(self, stage: Optional[str] = None) -> None:
        for name in (_REWRITE_STAGES if stage is None else (stage,)):
            self._index[name] = None
            if self.rules[name]:
                if name == "reader":
                    self.any_reader = True
                else:
                    self.any_grammar = True

    def _eligible(self, rule: RewriteRule) -> bool:
        if not rule.enabled or rule.pipeline not in self.pipelines[rule.stage]:
            return False
        owner = rule.owner
        return owner is None or self._parser._lang_owner_active(owner)

    def _rebuild(self, stage: str):
        anchored: Dict[int, Dict[str, List[RewriteRule]]] = {}
        free: List[RewriteRule] = []
        any_rule = False
        for rule in self.rules[stage]:
            if not self._eligible(rule):
                continue
            any_rule = True
            anchor = rule.anchor
            if anchor is None:
                free.append(rule)
            else:
                anchored.setdefault(anchor[0], {}).setdefault(anchor[1], []).append(rule)
        index = (tuple(sorted(anchored.items())), free)
        self._index[stage] = index
        if stage == "reader":
            self.any_reader = any_rule
        else:
            self.any_grammar = any_rule
        return index

    def _candidates(self, stage: str, tokens: List["Token"], start: int) -> List[RewriteRule]:
        """Eligible rules that can match at `start`, in selection order
        (priority descending, then earlier registration).  The list is a
        fresh or index-owned object never mutated later, so it serves as the
        attempt's snapshot."""
        index = self._index[stage]
        if index is None:
            index = self._rebuild(stage)
        anchored, free = index
        found: Optional[List[RewriteRule]] = None
        merged = False
        count = len(tokens)
        for offset, table in anchored:
            position = start + offset
            if position >= count:
                break
            rules = table.get(tokens[position].lexeme)
            if rules:
                if found is None:
                    found = rules
                else:
                    found = found + rules
                    merged = True
        if free:
            if found is None:
                return free
            found = found + free
            merged = True
        if found is None:
            return []
        if merged:
            found.sort(key=RewriteRule.rank)
        return found

    # -- Registration -------------------------------------------------------------

    def register(self, stage: str, name: Optional[str], pattern: Any, replacement: Any,
                 owner: Optional[str] = None) -> RewriteHandle:
        if name is not None and (not isinstance(name, str) or name == ""):
            raise _rewrite_error("rewrite-name-invalid", f"rewrite rule name must be a nonempty string, got {name!r}")
        pieces, repl = _rewrite_compile(pattern, replacement)
        if name is None:
            name = f"{stage}-rewrite-{self._generated}"
            self._generated += 1
        handle = RewriteHandle(next(_REWRITE_IDS))
        rule = RewriteRule(handle, stage, name, pattern, replacement, pieces, repl, handle.id, owner)
        self.live[handle.id] = rule
        bucket = self.rules[stage]
        bucket.append(rule)
        bucket.sort(key=RewriteRule.rank)
        self.invalidate(stage)
        return handle

    def resolve(self, handle: RewriteHandle) -> Optional[RewriteRule]:
        return self.live.get(handle.id)

    def remove(self, handle: RewriteHandle) -> bool:
        rule = self.live.pop(handle.id, None)
        if rule is None:
            return False
        self.rules[rule.stage].remove(rule)
        self.invalidate(rule.stage)
        return True

    def clear(self, stage: str) -> int:
        bucket = self.rules[stage]
        kept = [rule for rule in bucket if rule.owner is not None]
        removed = len(bucket) - len(kept)
        for rule in bucket:
            if rule.owner is None:
                del self.live[rule.handle.id]
        bucket[:] = kept
        self.invalidate(stage)
        return removed

    def listing(self, stage: str) -> List[Dict[str, Any]]:
        return [{"handle": rule.handle, "name": rule.name}
                for rule in sorted(self.rules[stage], key=lambda rule: rule.order)]

    def by_name(self, stage: str, name: str) -> Optional[RewriteRule]:
        matches = [rule for rule in self.rules[stage] if rule.name == name]
        if len(matches) > 1:
            handles = ", ".join(str(rule.handle.id) for rule in sorted(matches, key=lambda rule: rule.order))
            raise _rewrite_error("rewrite-query-ambiguous",
                                 f"{stage} rewrite name '{name}' is ambiguous: registrations {handles}")
        return matches[0] if matches else None

    def set_priority(self, rule: RewriteRule, priority: int) -> None:
        rule.priority = priority
        self.rules[rule.stage].sort(key=RewriteRule.rank)
        self.invalidate(rule.stage)

    def set_enabled(self, rule: RewriteRule, enabled: bool) -> None:
        rule.enabled = enabled
        self.invalidate(rule.stage)

    def set_pipeline(self, rule: RewriteRule, pipeline: str) -> None:
        rule.pipeline = pipeline
        self.invalidate(rule.stage)

    def set_pipeline_active(self, stage: str, pipeline: str, enabled: bool) -> None:
        if enabled:
            self.pipelines[stage].add(pipeline)
        else:
            self.pipelines[stage].discard(pipeline)
        self.invalidate(stage)

    def scope_push(self) -> int:
        self.scope_stack.append({stage: set(names) for stage, names in self.pipelines.items()})
        return len(self.scope_stack)

    def scope_pop(self) -> bool:
        if not self.scope_stack:
            return False
        restored = self.scope_stack.pop()
        for stage, names in restored.items():
            self.pipelines[stage] = names
        self.invalidate()
        return True

    def view_for(self, parser: "Parser") -> "RewriteEngine":
        """An engine for another parser (a staging parser) over the same
        registrations, pipelines, and controls."""
        view = copy.copy(self)
        view._parser = parser
        view._live_run = _RewriteRun(None, True)
        return view

    def reset_for_parse(self) -> None:
        self._live_run = _RewriteRun(None, True)
        self.scope_stack.clear()

    # -- Application -----------------------------------------------------------------

    def try_live(self, stage: str, token: "Token") -> bool:
        """Apply the first eligible rule matching at the parser cursor; the
        parser then retries from the replacement start."""
        parser = self._parser
        start = parser.pos - 1
        if start < 0:
            return False
        if self._apply_at(self._live_run, stage, parser.tokens, start):
            parser.pos = start
            return True
        return False

    def simulate(self, stage: str, lexemes: List[str], limit: int) -> Tuple[List[str], List[Dict[str, Any]]]:
        """Forward-cursor traversal with local retry over a lexeme list
        (ct-rewrite-run-on-list / ct-rewrite-dry-run)."""
        parser = self._parser
        template = parser._last_token
        intern = parser._intern_expansion_lexeme
        tokens = [_derive_token(template, intern(lexeme)) for lexeme in lexemes]
        run = _RewriteRun(limit, False)
        pos = 0
        while pos < len(tokens):
            if not self._apply_at(run, stage, tokens, pos):
                pos += 1
        return [token.lexeme for token in tokens], run.patches or []

    def _apply_at(self, run: _RewriteRun, stage: str, tokens: List["Token"], start: int) -> bool:
        for rule in self._candidates(stage, tokens, start):
            matched = _rewrite_match(rule, tokens, start)
            if matched is None:
                continue
            end, captures, depth = matched
            if rule.guard is not None and not self._run_guard(rule, start, end, captures):
                continue
            self._commit(run, rule, tokens, start, end, _rewrite_build(rule, captures), depth)
            return True
        return False

    def _run_guard(self, rule: RewriteRule, start: int, end: int, captures: Dict[str, Any]) -> bool:
        parser = self._parser
        guard = rule.guard
        context = (f"{rule.stage} rewrite '{rule.name}' (handle {rule.handle.id}) guard '{guard}' "
                   f"with captures {_rewrite_capture_text(captures)}")
        word, reason = parser._resolve_ct_handler(guard)
        if word is None:
            raise _rewrite_error("rewrite-guard-failed", f"{context}: {reason}")
        payload = {
            "stage": rule.stage,
            "handle": rule.handle,
            "rule": rule.name,
            "start": start,
            "end": end,
            "pattern": list(rule.pattern),
            "replacement": list(rule.replacement),
            "captures": {key: list(value) if isinstance(value, tuple) else value for key, value in captures.items()},
        }
        results = parser._call_ct_handler(word, [payload])
        if len(results) != 1 or not isinstance(results[0], int):
            raise _rewrite_error("rewrite-guard-failed",
                                 f"{context}: stack effect must be 'payload -- applies?' with an integer or boolean "
                                 f"result, returned {_rewrite_values_text(results)}")
        return bool(results[0])

    def _commit(self, run: _RewriteRun, rule: RewriteRule, tokens: List["Token"], start: int, end: int,
                replaced: List[str], depth: int) -> None:
        parser = self._parser
        stage = rule.stage
        next_depth = depth + 1
        if next_depth > parser.macro_expansion_limit:
            raise _rewrite_error("rewrite-expansion-limit",
                                 f"rewrite expansion depth limit ({parser.macro_expansion_limit}) exceeded while "
                                 f"applying {stage} rewrite '{rule.name}'")
        limit = self.max_steps if run.limit is None else run.limit
        if run.count >= limit:
            raise _rewrite_error("rewrite-max-steps",
                                 f"rewrite step budget ({limit}) exhausted: {stage} rewrite '{rule.name}' "
                                 f"(handle {rule.handle.id}) matched after {run.count} committed application(s)"
                                 + _rewrite_patch_note(run))
        window = self._check_loop(run, rule, tokens, start, end, replaced) if self.loop_detection else None
        before = [token.lexeme for token in tokens[start:end]]
        template = tokens[start]
        frame = ExpansionFrame(stage, rule.name, template)
        intern = parser._intern_expansion_lexeme
        tokens[start:end] = [_derive_token(template, intern(lexeme), frame=frame, expansion_depth=next_depth)
                             for lexeme in replaced]
        run.count += 1
        rule.applied += 1
        if window is not None:
            window.length = len(tokens)
            window.anchor = tokens[window.length - window.tail] if window.tail else None
        if run.live:
            bus = parser.event_bus
            if bus is not None and bus.wants("rewrite.applied"):
                payload = self._patch(rule, start, end, before, replaced)
                origin = parser._token_origin(template)
                if origin is not None:
                    payload["source-origin"] = origin
                bus.publish("rewrite.applied", payload)
            if parser.macro_preview:
                _rewrite_preview(parser, rule, template, replaced)
        else:
            run.patches.append(self._patch(rule, start, end, before, replaced))

    @staticmethod
    def _patch(rule: RewriteRule, start: int, end: int, before: List[str], after: List[str]) -> Dict[str, Any]:
        return {"stage": rule.stage, "handle": rule.handle, "rule": rule.name, "start": start, "end": end,
                "before": before, "after": list(after), "priority": rule.priority}

    def _check_loop(self, run: _RewriteRun, rule: RewriteRule, tokens: List["Token"], start: int, end: int,
                    replaced: List[str]) -> _RewriteWindow:
        stage = rule.stage
        length = len(tokens)
        window = run.windows.get(stage)
        if (window is None or window.start != start or window.length != length
                or (window.tail and tokens[length - window.tail] is not window.anchor)):
            # Entering the stage at this cursor: seed the initial sequence.
            window = _RewriteWindow(start, length - start, length, tokens[start] if start < length else None,
                                    {(length, ()): (run.count, None)})
            run.windows[stage] = window
        unchanged = length - end
        if unchanged < window.tail:
            extension = tuple(token.lexeme for token in tokens[length - window.tail:length - unchanged])
            window.states = {(size, middle + extension): seen for (size, middle), seen in window.states.items()}
            window.tail = unchanged
        new_length = length - (end - start) + len(replaced)
        middle = tuple(replaced) + tuple(token.lexeme for token in tokens[end:length - window.tail])
        key = (new_length, middle)
        previous = window.states.get(key)
        step = run.count + 1
        if previous is not None:
            previous_step, previous_rule = previous
            sequence = ([token.lexeme for token in tokens[:start]] + list(middle)
                        + [token.lexeme for token in tokens[length - window.tail:]])
            self.loop_reports.append({
                "phase": "rewrite-loop",
                "stage": stage,
                "handle": rule.handle,
                "rule": rule.name,
                "step": step,
                "previous_step": previous_step,
                "previous_handle": previous_rule.handle if previous_rule is not None else None,
                "previous_rule": previous_rule.name if previous_rule is not None else None,
                "sequence": sequence,
            })
            seen = (f"step {previous_step} ({stage} rewrite '{previous_rule.name}')" if previous_rule is not None
                    else f"the sequence at entry to the {stage} stage (step {previous_step})")
            raise _rewrite_error("rewrite-loop-detected",
                                 f"rewrite loop detected: {stage} rewrite '{rule.name}' (handle {rule.handle.id}) "
                                 f"at step {step} repeats {seen}" + _rewrite_patch_note(run))
        window.states[key] = (step, rule)
        return window


def _rewrite_capture_text(captures: Dict[str, Any]) -> str:
    return "{" + ", ".join(f"{key}: {list(value) if isinstance(value, tuple) else value!r}"
                           for key, value in captures.items()) + "}"


def _rewrite_values_text(values: Sequence[Any]) -> str:
    return "[" + ", ".join(_ct_type_name(value) for value in values) + "]"


def _rewrite_patch_note(run: _RewriteRun) -> str:
    if run.live or not run.patches:
        return ""
    applied = "; ".join(f"{patch['rule']}@{patch['start']}" for patch in run.patches)
    return f"; committed before the failure: {applied}"


def _macro_preview(parser: "Parser", name: str, trigger: "Token", output: Sequence["Token"]) -> None:
    """--macro-preview: one macro expansion, at its call site."""
    preview = " ".join(token.lexeme for token in output)
    if len(preview) > 240:
        preview = preview[:237] + "..."
    origin = parser._token_origin(trigger)
    where = (f"{origin.path}:{origin.start_line}:{origin.start_column}" if origin is not None
             else f"{trigger.line}:{trigger.column}")
    sys.stderr.write(f"[macro-preview] {name} at {where}\n  expand: {preview}\n")


_PREVIEW_FILE_LINES: Dict[str, List[str]] = {}


def _preview_file_lines(path: str) -> List[str]:
    lines = _PREVIEW_FILE_LINES.get(path)
    if lines is None:
        try:
            lines = Path(path).read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            lines = []
        _PREVIEW_FILE_LINES[path] = lines
    return lines


def _rewrite_preview(parser: "Parser", rule: RewriteRule, token: "Token", replaced: Sequence[str]) -> None:
    """--rewrite-preview: one rewrite, with source context from the token's own file."""
    preview = " ".join(replaced)
    if len(preview) > 240:
        preview = preview[:237] + "..."
    origin = parser._token_origin(token)
    if origin is not None:
        path: Optional[str] = origin.path
        line = origin.start_line
        where = f"{origin.path}:{origin.start_line}:{origin.start_column}"
        src_lines = _preview_file_lines(origin.path)
    else:
        path = None
        line = token.line
        where = f"{token.line}:{token.column}"
        src_lines = parser.source.splitlines()
    line_start = max(1, line - 2)
    line_end = min(len(src_lines), line + 2) if src_lines else line + 2
    line_tokens: Dict[int, List[str]] = {}
    for tok in parser.tokens:
        if path is not None:
            tok_origin = tok.origin
            if tok_origin is None or tok_origin.path != path:
                continue
            tok_line = tok_origin.start_line
        else:
            tok_line = tok.line
        if line_start <= tok_line <= line_end:
            line_tokens.setdefault(tok_line, []).append(tok.lexeme)
    lines: List[str] = [
        f"[rewrite-preview] {rule.name} ({rule.stage}) at {where}",
        f"  expand: {preview}",
    ]
    if 1 <= line <= len(src_lines):
        lines.append(f"  source: {src_lines[line - 1]}")
    lines.append("  context:")
    for ln in range(line_start, line_end + 1):
        mark = ">" if ln == line else " "
        src_text = src_lines[ln - 1] if 1 <= ln <= len(src_lines) else ""
        now_text = " ".join(line_tokens.get(ln, []))
        lines.append(f"  {mark} {ln:5d} | src: {src_text}")
        if now_text:
            lines.append(f"  {mark} {ln:5d} | now: {now_text}")
    sys.stderr.write("\n".join(lines) + "\n")


# ---------------------------------------------------------------------------
# § 8. Token hooks and language packs
# ---------------------------------------------------------------------------

class TokenHookHandle:
    """Opaque, immutable identity of one token-hook registration.
    Handles are never reused and go stale when the hook is removed."""

    __slots__ = ('id',)

    def __init__(self, ident: int) -> None:
        self.id = ident

    def __eq__(self, other: object) -> bool:
        return isinstance(other, TokenHookHandle) and other.id == self.id

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __hash__(self) -> int:
        return hash(("TokenHookHandle", self.id))

    def __repr__(self) -> str:
        return f"<TokenHookHandle {self.id}>"


# Token-hook ids double as registration order; never reused.
_TOKEN_HOOK_IDS = itertools.count(1)


class _TokenHook:
    """One token-hook registration.  A pack hook stores its handler name
    (resolved at each dispatch); the global entry (owner None) stores the
    DefinitionHandle bound when it was set."""

    __slots__ = ('handle', 'owner', 'handler', 'target', 'priority', 'enabled')

    def __init__(self, owner: Optional[str], handler: str, target: Optional["DefinitionHandle"]) -> None:
        self.handle = TokenHookHandle(next(_TOKEN_HOOK_IDS))
        self.owner = owner
        self.handler = handler
        self.target = target
        self.priority = 0
        self.enabled = True

    def dispatch_key(self) -> Tuple[int, int]:
        """Higher priority first; later registration first on ties."""
        return (-self.priority, -self.handle.id)


class _LangPack:
    """A language pack: an active flag, metadata, and the resources it owns
    (token hooks, word/macro candidates by name, rewrite registrations)."""

    __slots__ = ('name', 'active', 'metadata', 'hooks', 'resources', 'rewrites')

    def __init__(self, name: str) -> None:
        self.name = name
        self.active = False
        self.metadata: Dict[str, Any] = {}
        self.hooks: List[_TokenHook] = []
        self.resources: Dict[str, "Word"] = {}
        self.rewrites: Dict[str, List[RewriteHandle]] = {"reader": [], "grammar": []}


class _LangState:
    """Language packs and token-hook registrations, shared by a parser and
    its staging parsers.  `chain` is the eligible hooks in dispatch order,
    rebuilt after every change."""

    __slots__ = ('packs', 'hooks', 'global_hook', 'chain')

    def __init__(self) -> None:
        self.packs: Dict[str, _LangPack] = {}
        self.hooks: Dict[int, _TokenHook] = {}
        self.global_hook: Optional[_TokenHook] = None
        self.chain: Tuple[_TokenHook, ...] = ()


def _lang_error(code: str, message: str, phase: Optional[str] = None) -> ParseError:
    return ParseError(message, code=code, phase=phase)


def _lang_portable_copy(value: Any, path: str) -> Any:
    """Validated deep copy of pack metadata: nil, booleans, integers,
    numbers, strings, lists, and string-keyed maps only."""
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, list):
        return [_lang_portable_copy(item, f"{path}[{index}]") for index, item in enumerate(value)]
    if isinstance(value, Mapping):
        copy_map: Dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise _lang_error("language-pack-metadata-invalid",
                                  f"ct-lang-set-meta: {path} has a non-string key {key!r}")
            copy_map[key] = _lang_portable_copy(item, f"{path}.{key}")
        return copy_map
    raise _lang_error("language-pack-metadata-invalid",
                      f"ct-lang-set-meta: {path} holds a {_ct_type_name(value)}, which is not portable CT data")


class StructField:
    __slots__ = ('name', 'offset', 'size')

    def __init__(self, name: str, offset: int, size: int) -> None:
        self.name = name
        self.offset = offset
        self.size = size


class CStructField:
    __slots__ = ('name', 'type_name', 'offset', 'size', 'align')

    def __init__(self, name: str, type_name: str, offset: int, size: int, align: int) -> None:
        self.name = name
        self.type_name = type_name
        self.offset = offset
        self.size = size
        self.align = align


class CStructLayout:
    __slots__ = ('name', 'size', 'align', 'fields')

    def __init__(self, name: str, size: int, align: int, fields: List[CStructField]) -> None:
        self.name = name
        self.size = size
        self.align = align
        self.fields = fields


class MacroContext:
    """Small facade exposed to Python-defined macros."""

    def __init__(self, parser: "Parser") -> None:
        self._parser = parser

    @property
    def parser(self) -> "Parser":
        return self._parser

    def next_token(self) -> Token:
        return self._parser.next_token()

    def peek_token(self) -> Optional[Token]:
        return self._parser.peek_token()

    def emit_literal(self, value: int) -> None:
        self._parser.emit_node(_make_literal_op(value))

    def emit_word(self, name: str) -> None:
        self._parser.emit_node(_make_word_op(name))

    def emit_node(self, node: Op) -> None:
        self._parser.emit_node(node)

    def inject_tokens(self, tokens: Sequence[str], template: Optional[Token] = None) -> None:
        generated = [_derive_token(template, lex) for lex in tokens]
        self.inject_token_objects(generated)

    def inject_token_objects(self, tokens: Sequence[Token]) -> None:
        self._parser.tokens[self._parser.pos:self._parser.pos] = list(tokens)

    def add_reader_rewrite(self, pattern: Sequence[str], replacement: Sequence[str], *,
                           name: Optional[str] = None) -> RewriteHandle:
        return self._parser.rewrites.register("reader", name, list(pattern), list(replacement))

    def add_grammar_rewrite(self, pattern: Sequence[str], replacement: Sequence[str], *,
                            name: Optional[str] = None) -> RewriteHandle:
        return self._parser.rewrites.register("grammar", name, list(pattern), list(replacement))

    def remove_rewrite(self, handle: RewriteHandle) -> bool:
        return self._parser.rewrites.remove(handle)

    def set_macro_expansion_limit(self, limit: int) -> None:
        self._parser.set_macro_expansion_limit(limit)

    def macro_expansion_limit(self) -> int:
        return self._parser.macro_expansion_limit

    def set_macro_preview(self, enabled: bool) -> None:
        self._parser.set_macro_preview(enabled)

    def macro_preview(self) -> bool:
        return self._parser.macro_preview

    def unregister_word(self, name: str) -> bool:
        return self._parser.unregister_word(name)

    def word_exists(self, name: str) -> bool:
        return self._parser.word_exists(name)

    def new_label(self, prefix: str) -> str:
        return self._parser._new_label(prefix)

    def most_recent_definition(self) -> Optional[Word]:
        return self._parser.most_recent_definition()


# Type aliases (only evaluated under TYPE_CHECKING)


# Word effects ---------------------------------------------------------------


WORD_EFFECT_STRING_IO = "string-io"
_WORD_EFFECT_ALIASES: Dict[str, str] = {
    "string": WORD_EFFECT_STRING_IO,
    "strings": WORD_EFFECT_STRING_IO,
    "string-io": WORD_EFFECT_STRING_IO,
    "string_io": WORD_EFFECT_STRING_IO,
    "strings-io": WORD_EFFECT_STRING_IO,
    "strings_io": WORD_EFFECT_STRING_IO,
}


class Word:
    __slots__ = ('name', 'priority', 'immediate', 'definition', 'macro', 'intrinsic',
                 'compile_time_intrinsic',
                 'runtime_intrinsic', 'compile_only', 'runtime_only', 'compile_time_override',
                 'is_extern', 'extern_inputs', 'extern_outputs', 'extern_signature',
                 'extern_variadic', 'inline',
                 # Definition-candidate metadata.
                 'handle', 'seq', 'owner', 'source_text', 'source_origin', 'prefer_l2', 'inherited',
                 'macro_def')

    def __init__(self, name: str, priority: int = 0, immediate: bool = False,
                 definition=None, macro=None, intrinsic=None,
                 compile_time_intrinsic=None, runtime_intrinsic=None,
                 compile_only: bool = False, runtime_only: bool = False, compile_time_override: bool = False,
                 is_extern: bool = False, extern_inputs: int = 0, extern_outputs: int = 0,
                 extern_signature=None, extern_variadic: bool = False,
                 inline: bool = False) -> None:
        self.name = name
        self.priority = priority
        self.immediate = immediate
        self.definition = definition
        self.macro = macro
        self.intrinsic = intrinsic
        self.compile_time_intrinsic = compile_time_intrinsic
        self.runtime_intrinsic = runtime_intrinsic
        self.compile_only = compile_only
        self.runtime_only = runtime_only
        self.compile_time_override = compile_time_override
        self.is_extern = is_extern
        self.extern_inputs = extern_inputs
        self.extern_outputs = extern_outputs
        self.extern_signature = extern_signature
        self.extern_variadic = extern_variadic
        self.inline = inline
        self.handle: Optional[DefinitionHandle] = None
        self.seq = 0
        self.owner: Optional[str] = None
        self.source_text: Optional[str] = None
        # A SourceOrigin, or the declaration's first Token until an origin
        # is first needed (origins are costly to compute).
        self.source_origin: Any = None
        self.prefer_l2 = False
        self.inherited: Tuple[str, ...] = ()
        self.macro_def: Optional[_MacroDef] = None


class DefinitionHandle:
    """Opaque, invocation-scoped identity of one definition candidate.
    Copies of a handle compare equal; distinct candidates never do.  Handles
    have no ordering, are never reused, and go stale on unregistration."""

    __slots__ = ('id',)

    def __init__(self, ident: int) -> None:
        self.id = ident

    def __eq__(self, other: object) -> bool:
        return isinstance(other, DefinitionHandle) and other.id == self.id

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __hash__(self) -> int:
        return hash(("DefinitionHandle", self.id))

    def __repr__(self) -> str:
        return f"<DefinitionHandle {self.id}>"


# Per-name built-in handlers: baseline capabilities of a name, not candidates.
_BASELINE_HANDLERS = ("compile_time_intrinsic", "runtime_intrinsic", "intrinsic")

_suppress_redefine_warnings = False


def _suppress_redefine_warnings_set(value: bool) -> None:
    global _suppress_redefine_warnings
    _suppress_redefine_warnings = value


def _word_source_origin(word: Word) -> Optional[SourceOrigin]:
    origin = word.source_origin
    if isinstance(origin, Token):
        origin = origin.origin
        if origin is _SYNTHETIC_ORIGIN:
            origin = None
        word.source_origin = origin
    return origin


_DEFINITION_RECORD_KEYS = (
    "handle", "name", "owner", "eligible?", "priority", "selected?", "kind",
    "immediate?", "compile-only?", "runtime-only?", "inline?", "preserve?", "prefer-l2?",
    "compile-time-intrinsic?", "runtime-intrinsic?", "emission-intrinsic?",
)
_DEFINITION_RECORD_INDEX = {key: index for index, key in enumerate(_DEFINITION_RECORD_KEYS)}


class _DefinitionRecord(Mapping):
    """Immutable DefinitionCandidate map.  Its fields are captured when the
    record is made; `source-origin` (fixed per candidate) is computed only
    when read, since origins are costly and most records are never read."""

    __slots__ = ("_word", "_values")

    def __init__(self, word: Word, values: Tuple[Any, ...]) -> None:
        self._word = word
        self._values = values

    def __getitem__(self, key: Any) -> Any:
        if key == "source-origin":
            return _word_source_origin(self._word)
        index = _DEFINITION_RECORD_INDEX.get(key) if type(key) is str else None
        if index is None:
            raise KeyError(key)
        return self._values[index]

    def __iter__(self):
        yield from _DEFINITION_RECORD_KEYS[:7]
        yield "source-origin"
        yield from _DEFINITION_RECORD_KEYS[7:]

    def __len__(self) -> int:
        return len(_DEFINITION_RECORD_KEYS) + 1

    def __contains__(self, key: object) -> bool:
        return type(key) is str and (key == "source-origin" or key in _DEFINITION_RECORD_INDEX)

    def __repr__(self) -> str:
        return "DefinitionCandidate(" + repr(dict(self.items())) + ")"


def _definition_kind(word: Word) -> str:
    if word.macro_def is not None:
        return "macro"
    if word.is_extern:
        return "external"
    definition = word.definition
    if isinstance(definition, AsmDefinition):
        return "assembly"
    if isinstance(definition, Definition):
        return "l2"
    if word.macro is not None or word.intrinsic is not None:
        return "python"
    return "l2"


# ---------------------------------------------------------------------------
# § 9. Dictionary and definition candidates
# ---------------------------------------------------------------------------

class Dictionary:
    """The global definition namespace.

    Every name holds its definition candidates in registration order plus an
    optional baseline word carrying the name's built-in handlers.  The
    selected candidate is the eligible one with the highest priority, ties
    going to the newest registration.  `words` maps each name to its
    effective word (the selected candidate, else the baseline) and is what
    lookups read; candidates inherit their name's baseline handlers.
    """

    __slots__ = ('words', 'warn_callback', 'candidates', 'baselines', 'live', 'generation',
                 '_next_handle', '_next_seq', 'listener', 'owner_active', 'pending_consts')

    def __init__(self) -> None:
        self.words: Dict[str, Word] = {}
        self.candidates: Dict[str, List[Word]] = {}
        self.baselines: Dict[str, Word] = {}
        self.live: Dict[int, Word] = {}
        # Bumped whenever an existing name's effective word changes, so
        # cached name resolutions can be dropped.
        self.generation = 0
        self._next_handle = 1
        self._next_seq = 1
        self.warn_callback: Optional[Callable] = None
        # The parser: definition_events_active() / publish_definition_changes().
        self.listener: Any = None
        # owner name -> whether that language pack is effectively active.
        self.owner_active: Optional[Callable[[str], bool]] = None
        # `const NAME value` declarations not yet turned into candidates:
        # name -> (const token, name token, value token).  A declaration is
        # materialized (by the listener, the parser) on first use.
        self.pending_consts: Dict[str, Tuple[Any, Any, Any]] = {}

    # -- Lookup and selection ------------------------------------------------

    def lookup(self, name: str) -> Optional[Word]:
        word = self.words.get(name)
        if word is None and name in self.pending_consts:
            return self.materialize_const(name)
        return word

    def materialize_const(self, name: str) -> Optional[Word]:
        """Turn a pending `const` declaration into its candidate."""
        entry = self.pending_consts.pop(name, None)
        if entry is None or self.listener is None:
            return self.words.get(name)
        self.listener.materialize_const(name, entry)
        return self.words.get(name)

    def materialize_all_consts(self) -> None:
        for name in list(self.pending_consts):
            self.materialize_const(name)

    def eligible(self, word: Word) -> bool:
        owner = word.owner
        if owner is None:
            return True
        check = self.owner_active
        return bool(check(owner)) if check is not None else False

    def selected(self, name: str) -> Optional[Word]:
        if name in self.pending_consts:
            self.materialize_const(name)
        candidates = self.candidates.get(name)
        if not candidates:
            return None
        if len(candidates) == 1:
            only = candidates[0]
            return only if only.owner is None or self.eligible(only) else None
        best: Optional[Word] = None
        for word in candidates:
            if not self.eligible(word):
                continue
            if best is None or (word.priority, word.seq) > (best.priority, best.seq):
                best = word
        return best

    def ordered_candidates(self, name: str) -> List[Word]:
        """Candidates by descending priority, newest registration first."""
        if name in self.pending_consts:
            self.materialize_const(name)
        return sorted(self.candidates.get(name, ()), key=lambda w: (-w.priority, -w.seq))

    def resolve(self, handle: Any) -> Optional[Word]:
        """The live candidate a handle refers to, or None when stale."""
        return self.live.get(handle.id) if isinstance(handle, DefinitionHandle) else None

    def has_name(self, name: str) -> bool:
        return name in self.candidates or name in self.baselines or name in self.pending_consts

    def names(self) -> List[str]:
        return sorted(set(self.candidates) | set(self.baselines) | set(self.pending_consts))

    def selected_snapshot(self) -> Dict[str, Word]:
        """Effective word per name, taken once per emission attempt.
        Pending `const` declarations are left out: constants expand while
        parsing and are never emitted."""
        return dict(self.words)

    def _refresh(self, name: str) -> Optional[Word]:
        selected = self.selected(name)
        effective = selected if selected is not None else self.baselines.get(name)
        previous = self.words.get(name)
        if effective is None:
            self.words.pop(name, None)
        else:
            self.words[name] = effective
        if previous is not None and previous is not effective:
            self.generation += 1
        return selected

    # -- Baselines -------------------------------------------------------------

    @staticmethod
    def _inherit(word: Word, baseline: Optional[Word]) -> None:
        """Give a candidate its current name's baseline handlers, keeping any
        handler the candidate defines itself."""
        inherited: List[str] = []
        for attr in _BASELINE_HANDLERS:
            if attr in word.inherited or getattr(word, attr) is None:
                value = getattr(baseline, attr) if baseline is not None else None
                setattr(word, attr, value)
                if value is not None:
                    inherited.append(attr)
        word.inherited = tuple(inherited)

    def register_baseline(self, word: Word) -> Word:
        """Install the baseline (built-in) word for a name."""
        self.baselines[word.name] = word
        for candidate in self.candidates.get(word.name, ()):
            self._inherit(candidate, word)
        self._refresh(word.name)
        return word

    def baseline(self, name: str) -> Word:
        word = self.baselines.get(name)
        if word is None:
            word = self.register_baseline(Word(name=name))
        return word

    def set_baseline_handler(self, name: str, attr: str, handler: Any) -> Word:
        baseline = self.baseline(name)
        setattr(baseline, attr, handler)
        for candidate in self.candidates.get(name, ()):
            self._inherit(candidate, baseline)
        return baseline

    # -- Candidate records and change notification -----------------------------

    def candidate_record(self, word: Word, selected: Any = False) -> Mapping:
        """Immutable DefinitionCandidate map (summary metadata only)."""
        if selected is False:
            selected = self.selected(word.name)
        baseline = self.baselines.get(word.name)
        definition = word.definition
        return _DefinitionRecord(word, (
            word.handle,
            word.name,
            word.owner,
            1 if self.eligible(word) else 0,
            word.priority,
            1 if selected is word else 0,
            _definition_kind(word),
            1 if word.immediate else 0,
            1 if word.compile_only else 0,
            1 if word.runtime_only else 0,
            1 if word.inline else 0,
            1 if getattr(definition, "preserve", False) else 0,
            1 if word.prefer_l2 else 0,
            1 if baseline is not None and baseline.compile_time_intrinsic is not None else 0,
            1 if baseline is not None and baseline.runtime_intrinsic is not None else 0,
            1 if baseline is not None and baseline.intrinsic is not None else 0,
        ))

    def _notifying(self) -> bool:
        listener = self.listener
        return listener is not None and listener.definition_events_active()

    def _emit_change(self, change: Dict[str, Any], defer: Optional[List[Dict[str, Any]]]) -> None:
        if defer is not None:
            defer.append(change)
        else:
            self.listener.publish_definition_changes([change])

    def _simple_change(self, operation: str, word: Word, previous: Optional[Word], current: Optional[Word],
                       before: Optional[Mapping], defer: Optional[List[Dict[str, Any]]]) -> None:
        after = self.candidate_record(word, current) if word.handle is not None and word.handle.id in self.live else None
        self._emit_change({
            "operation": operation,
            "candidate": word.handle,
            "candidate-before": before,
            "candidate-after": after,
            "name": word.name,
            "previous-selected": previous.handle if previous is not None else None,
            "selected": current.handle if current is not None else None,
        }, defer)

    # -- Candidate mutations ------------------------------------------------------

    def register(self, word: Word, *, warn: bool = True, operation: str = "register",
                 defer: Optional[List[Dict[str, Any]]] = None) -> Word:
        """Register a new candidate; returns the name's selected candidate."""
        name = word.name
        if name in self.pending_consts:
            self.materialize_const(name)  # the earlier `const` comes first
        handle = word.handle = DefinitionHandle(self._next_handle)
        self._next_handle += 1
        word.seq = self._next_seq
        self._next_seq += 1
        self.live[handle.id] = word
        baseline = self.baselines.get(name)
        if baseline is not None or word.inherited:
            self._inherit(word, baseline)
        candidates = self.candidates.get(name)
        if candidates is None and word.owner is None:
            # Fast path: the name's first candidate is selected.
            self.candidates[name] = [word]
            previous = None
            current = word
            if self.words.get(name) is not None:
                self.generation += 1
            self.words[name] = word
        else:
            previous = self.selected(name) if candidates else None
            if candidates is None:
                self.candidates[name] = [word]
            else:
                candidates.append(word)
            if warn and previous is not None and self.eligible(word):
                self._report_shadowing(word, previous)
            current = self._refresh(name)
        if self._notifying():
            self._simple_change(operation, word, previous, current, None, defer)
        return current if current is not None else word

    def _report_shadowing(self, word: Word, previous: Word) -> None:
        name = word.name
        if word.priority > previous.priority:
            sys.stderr.write(f"[note] word {name}: using priority {word.priority} over {previous.priority}\n")
            return
        if word.priority < previous.priority:
            sys.stderr.write(
                f"[note] word {name}: priority {word.priority} is below the selected priority "
                f"{previous.priority}; retained as a shadowed candidate\n"
            )
            return
        if _suppress_redefine_warnings:
            return
        if self.warn_callback is not None:
            self.warn_callback(name, word.priority)
        else:
            sys.stderr.write(f"[warn] redefining word {name} (priority {word.priority})\n")

    def unregister(self, word: Word, *, defer: Optional[List[Dict[str, Any]]] = None) -> bool:
        handle = word.handle
        if handle is None or self.live.get(handle.id) is not word:
            return False
        name = word.name
        notifying = self._notifying()
        before = self.candidate_record(word) if notifying else None
        candidates = self.candidates[name]
        del self.live[handle.id]
        if len(candidates) == 1:
            # Fast path: the name's only candidate goes away.
            previous = word if word.owner is None or self.eligible(word) else None
            del self.candidates[name]
            current = None
            baseline = self.baselines.get(name)
            if baseline is None:
                del self.words[name]
            else:
                self.words[name] = baseline
            self.generation += 1
        else:
            previous = self.selected(name)
            candidates.remove(word)
            current = self._refresh(name)
        if notifying:
            self._simple_change("unregister", word, previous, current, before, defer)
        hook = getattr(self.listener, "on_candidate_unregistered", None)
        if hook is not None:
            hook(word)
        return True

    def set_priority(self, word: Word, priority: int) -> None:
        if word.priority == priority:
            return
        notifying = self._notifying()
        before = self.candidate_record(word) if notifying else None
        previous = self.selected(word.name)
        word.priority = priority
        current = self._refresh(word.name)
        if notifying:
            self._simple_change("set_priority", word, previous, current, before, None)

    def update(self, word: Word, mutate: Callable[[Word], None]) -> None:
        """Apply an in-place change to a candidate and publish `update`."""
        notifying = self._notifying()
        before = self.candidate_record(word) if notifying else None
        previous = self.selected(word.name)
        mutate(word)
        current = self._refresh(word.name)
        self.generation += 1
        if notifying:
            self._simple_change("update", word, previous, current, before, None)

    def owner_changed(self, words: Sequence[Word], apply: Callable[[], None]) -> None:
        """Apply a change to the owners' activation and publish `update`
        (and any selection change) for each affected candidate."""
        notifying = self._notifying()
        before = [(word, self.candidate_record(word) if notifying else None, self.selected(word.name))
                  for word in words]
        apply()
        changes: List[Dict[str, Any]] = []
        for word, record, previous in before:
            current = self._refresh(word.name)
            if notifying:
                self._simple_change("update", word, previous, current, record, changes)
        self.generation += 1
        if changes:
            self.listener.publish_definition_changes(changes)

    def rename(self, word: Word, new_name: str) -> None:
        old_name = word.name
        if new_name == old_name:
            return
        notifying = self._notifying()
        before = self.candidate_record(word) if notifying else None
        old_previous = self.selected(old_name)
        new_previous = self.selected(new_name)
        candidates = self.candidates[old_name]
        candidates.remove(word)
        if not candidates:
            del self.candidates[old_name]
        word.name = new_name
        if word.definition is not None and hasattr(word.definition, "name"):
            word.definition.name = new_name
        word.seq = self._next_seq
        self._next_seq += 1
        self._inherit(word, self.baselines.get(new_name))
        self.candidates.setdefault(new_name, []).append(word)
        old_current = self._refresh(old_name)
        new_current = self._refresh(new_name)
        self.generation += 1
        if notifying:
            self._emit_change({
                "operation": "rename",
                "candidate": word.handle,
                "candidate-before": before,
                "candidate-after": self.candidate_record(word, new_current),
                "old-name": old_name,
                "new-name": new_name,
                "old-previous-selected": old_previous.handle if old_previous is not None else None,
                "old-selected": old_current.handle if old_current is not None else None,
                "new-previous-selected": new_previous.handle if new_previous is not None else None,
                "new-selected": new_current.handle if new_current is not None else None,
            }, None)

    def clone(self, word: Word, new_name: str) -> Word:
        """Register a copy of a candidate under `new_name` (copied priority,
        fresh handle and registration position)."""
        copy = Word(name=new_name)
        for attr in Word.__slots__:
            if attr in ("name", "handle", "seq", "inherited"):
                continue
            setattr(copy, attr, getattr(word, attr))
        for attr in word.inherited:
            setattr(copy, attr, None)
        copy.definition = _clone_definition(word.definition, new_name)
        if word.macro_def is not None:
            mdef = word.macro_def
            copy.macro_def = _MacroDef(mdef.params, mdef.body, mdef.body_tokens,
                                       _ct_deep_clone_value(mdef.metadata, {}), mdef.fast)
        if word.extern_signature is not None:
            args, ret = word.extern_signature
            copy.extern_signature = (list(args), ret)
        self.register(copy, warn=False, operation="clone")
        return copy


def _clone_definition(definition: Any, name: str) -> Any:
    if isinstance(definition, Definition):
        body = [Op(node.op, node.data, node.loc) for node in definition.body]
        copy = Definition(name=name, body=body, immediate=definition.immediate,
                          compile_only=definition.compile_only, runtime_only=definition.runtime_only,
                          terminator=definition.terminator, inline=definition.inline,
                          stack_inputs=definition.stack_inputs, stack_outputs=definition.stack_outputs,
                          preserve=definition.preserve)
        copy.effect_exact = definition.effect_exact
        return copy
    if isinstance(definition, AsmDefinition):
        copy = AsmDefinition(name=name, body=definition.body, immediate=definition.immediate,
                             compile_only=definition.compile_only, runtime_only=definition.runtime_only,
                             inline=definition.inline, preserve=definition.preserve,
                             stack_inputs=definition.stack_inputs, stack_outputs=definition.stack_outputs)
        copy.effects = set(definition.effects)
        copy.effect_exact = definition.effect_exact
        return copy
    return definition


# ---------------------------------------------------------------------------
# § 10. Parser
# ---------------------------------------------------------------------------


Context = None  # Union[Module, Definition] - only used in annotations


class _RecoveryChain:
    """One error-recovery continuation: consecutive dispatches of a retried
    operation.  The retry limit is snapshotted at the first dispatch."""

    __slots__ = ('stage', 'limit', 'attempt', 'started', 'diagnostics', 'retrying')

    def __init__(self, stage: str, limit: int) -> None:
        self.retrying = False
        self.stage = stage
        self.limit = limit
        self.attempt = 0
        self.started = False
        self.diagnostics: List[Diagnostic] = []


def _mark_reported(exc: BaseException) -> None:
    """Note that `exc`'s Diagnostic was recorded and published."""
    try:
        exc.l2_reported = True  # type: ignore[attr-defined]
    except AttributeError:
        pass


class Parser:
    EXTERN_DEFAULT_PRIORITY = 1

    def __init__(
        self,
        dictionary: Dictionary,
        reader: Optional[Reader] = None,
        *,
        macro_expansion_limit: int = DEFAULT_MACRO_EXPANSION_LIMIT,
        macro_preview: bool = False,
        event_bus: Optional[EventBus] = None,
    ) -> None:
        if macro_expansion_limit < 1:
            raise ValueError("macro_expansion_limit must be >= 1")
        self.dictionary = dictionary
        self.reader = reader or Reader()
        self.macro_expansion_limit = macro_expansion_limit
        self.macro_preview = macro_preview
        self.event_bus = event_bus
        self.events_hard_disabled = False
        self.event_ring_capacity = DEFAULT_EVENT_RING_CAPACITY  # --events-ring
        if dictionary.listener is None:
            dictionary.listener = self
            dictionary.owner_active = self._lang_owner_active
        if event_bus is not None:
            event_bus.ct_runner = self._run_ct_event_handlers
            event_bus.sink_error_handler = self._handle_event_stream_failure
        self.tokens: List[Token] = []
        self._token_iter: Optional[Iterable[Token]] = None
        self._token_iter_exhausted = True
        self.pos = 0
        self.context_stack: List[Context] = []
        self.definition_stack: List[Tuple[Word, bool]] = []
        self.last_defined: Optional[Word] = None
        self.source: str = ""
        self.control_stack: List[Dict[str, str]] = []
        self.block_openers: Set[str] = {"word", "with", "for", "while", "begin"}
        self.control_overrides: Set[str] = set()
        self._warned_control_overrides: Set[str] = set()
        self._expansion_lexeme_pool: Dict[str, str] = {}
        self._capture_group_pool: Dict[Tuple[str, ...], Tuple[str, ...]] = {}
        self._macro_hotness: Dict[str, int] = {}
        self._macro_profile: Dict[str, Dict[str, int]] = {}
        self._macro_profile_enabled: bool = False
        self.enable_dead_macro_elimination: bool = False
        self.enable_unused_rewrite_elimination: bool = False
        self.rewrites = RewriteEngine(self)
        self.label_counter = 0
        self._hook_dispatch_depth = 0
        # Subscriptions excluded from the active nested handler-failure
        # dispatch lineage.
        self._excluded_subscriptions: frozenset = frozenset()
        # Subscriptions whose handler is running: they do not receive the
        # ct.execute.* events their own word calls publish.
        self._running_subscriptions: Set[int] = set()
        # Active transformations (kind, name, triggering token); tokens
        # injected while one is active get an ExpansionFrame for it.
        self._expansion_contexts: List[Tuple[str, str, Token]] = []
        self._last_token: Optional[Token] = None
        self.variable_labels: Dict[str, str] = {}
        self.variable_words: Dict[str, str] = {}
        self.file_spans: List[FileSpan] = []
        self._root_srcmap: Optional[SourceMap] = None
        # Warm-prefix parsing (daemon stdlib reuse): pause at end of input
        # instead of finalizing; resume by appending the next root's tokens.
        self._warm_pause = False
        self._warm_resume = False
        # Marker Token -> quotation template whose `$(expr)` values the
        # code parsed before the marker leaves on the stack.
        self._pending_quotations: Dict[Token, _QuotationTemplate] = {}
        self._span_starts: List[int] = []
        self._span_index_len: int = 0
        self._span_cache_idx: int = -1
        self.compile_time_vm = CompileTimeVM(self)
        # Assembly output buffers: CT .text and .data fragments,
        # and the runtime BSS buffer (None until changed: the standard layout).
        self.output_text_preamble: List[str] = []
        self.output_data: List[str] = []
        self.output_bss: Optional[List[str]] = None
        self.cstruct_layouts: Dict[str, CStructLayout] = {}
        self._pending_inline_definition: bool = False
        self._pending_preserve_definition: bool = False
        self._pending_priority: Optional[int] = None
        self.generated_source_map: Dict[int, Tuple[str, int, int, int]] = {}
        self.capture_globals: Dict[str, Any] = {}
        self.capture_mutability_frozen: Set[Tuple[str, str]] = set()
        self.capture_replay_log: List[Dict[str, Any]] = []
        self._capture_lifetime_counter: int = 0
        self._capture_lifetime_active: int = 0
        # Deterministic compile-time RNG: one stream per compilation.
        self._rng = random.Random(_RNG_DEFAULT_SEED)
        self._ct_parser_sessions: List[ParserSession] = []
        # Custom-frontend support: marker token -> SourceUnit, synthetic
        # imports of frontend implementations, and canonical frontend output
        # (which skips reader rewrites, the token hook, and grammar rewrites).
        self._frontend_markers: Dict[Token, Any] = {}
        self._support_import_tokens: Set[Token] = set()
        self._canonical_tokens: Set[Token] = set()
        self._langs = _LangState()
        self._error_restore_points: Deque[Tuple[Any, ...]] = deque(maxlen=512)
        self._error_restore_point_counter = 0
        self._current_error_restore_point: Optional[int] = None
        self._active_error_recovery: Optional[Dict[str, Any]] = None
        self._active_module: Optional[Module] = None
        # Candidates registered early by ct-definition-predeclare-all, by name.
        self._predeclared: Dict[str, Word] = {}
        self._extern_start_token: Optional[Token] = None
        # Lexical `$name` binding scopes (macro parameters, match clauses).
        self._binding_scopes: List[Set[str]] = []
        self._gensym_counter = 0
        # Macro bodies being parsed, and macro bodies currently running.
        self._macro_body_stack: List[Dict[str, Any]] = []
        self._macro_frames: List[Dict[str, Any]] = []
        self._macro_attempts: Dict[Tuple[int, str, int], int] = {}
        # True while parse() runs (emit needs an active input stream).
        self._parsing = False
        # (position, emitted count, token list) of the latest emit.
        self._emit_anchor: Optional[Tuple[int, int, List[Token]]] = None
        # When set, completed source definitions are collected here instead
        # of being registered (validation pass of a batch registration).
        self._definition_sink: Optional[List[Word]] = None
        self._error_recovery_retry_limit = 8
        self._recovery_chain: Optional[_RecoveryChain] = None
        self._recovery_dispatch_depth = 0
        self._unresolved_errors = 0
        self._superseded_diagnostics: Set[int] = set()
        self.diagnostics: List[Diagnostic] = []
        self._max_errors: int = 20
        self._warnings_enabled: Set[str] = set()
        self._werror: bool = False
        # When false, parser skips per-op source location attachment for speed.
        self.capture_op_locations: bool = True
        # Enabled by CLI --preview to capture CT/immediate execution trace events.
        self.preview_trace_enabled: bool = False
        self.preview_trace_events: List[Dict[str, Any]] = []

    def _rebuild_span_index(self) -> None:
        """Rebuild bisect index after file_spans changes."""
        self._span_starts: List[int] = [s.start_line for s in self.file_spans]
        self._span_index_len: int = len(self.file_spans)

    def location_for_token(self, token: Token) -> SourceLocation:
        srcmap = token._srcmap
        if srcmap is None:
            if token._origin.__class__ is SourceOrigin:
                # Built from an explicit SourceOrigin: no flattened coordinates.
                origin = token._origin
                if origin is not _SYNTHETIC_ORIGIN:
                    return _make_loc(Path(origin.path), origin.start_line, origin.start_column - 1)
        elif srcmap is not self._root_srcmap:
            # Tokenized from another file's source unit: its own map applies.
            local = srcmap.location(token.line, token.column)
            if local is not None:
                return _make_loc(local[0], local[1], local[2])
            origin = token.origin
            return _make_loc(Path(origin.path), origin.start_line, origin.start_column - 1)
        spans = self.file_spans
        if not spans:
            return _make_loc(_SOURCE_PATH, token.line, token.column)
        if self._span_index_len != len(spans):
            self._rebuild_span_index()
            self._span_cache_idx = -1
        tl = token.line
        # Fast path: check cached span first (common for sequential access)
        ci = self._span_cache_idx
        if ci >= 0:
            span = spans[ci]
            if span.start_line <= tl < span.end_line:
                return _make_loc(span.path, span.local_start_line + (tl - span.start_line), token.column)
        span_starts = self._span_starts
        idx = bisect.bisect_right(span_starts, tl) - 1
        if idx >= 0:
            span = spans[idx]
            if tl < span.end_line:
                self._span_cache_idx = idx
                return _make_loc(span.path, span.local_start_line + (tl - span.start_line), token.column)
        return _make_loc(_SOURCE_PATH, tl, token.column)

    def _record_diagnostic_obj(self, diag: Diagnostic) -> None:
        """Record a prebuilt diagnostic and enforce max-error limit."""
        self.diagnostics.append(diag)
        if diag.severity != "error":
            # Warnings and notes: recorded first, then dispatched.
            if self.event_bus is not None and self.event_bus.active:
                self.event_bus.publish("compile.diagnostic", {"diagnostic": diag})
            return
        self._publish_error_events({"diagnostic": diag, "recoverable": False})
        self._count_unresolved_error(diag)

    def _add_error_restore_point(
        self,
        stage: str,
        pos: int,
        token: Optional[Token],
        last_token: Optional[Token],
    ) -> int:
        # One is made per parsed token, so it is stored as a compact
        # tuple in a bounded deque and turned into a map only when read.
        self._error_restore_point_counter += 1
        point_id = self._error_restore_point_counter
        self._error_restore_points.append((point_id, stage, pos, token, last_token))
        self._current_error_restore_point = point_id
        return point_id

    @staticmethod
    def _restore_point_map(point: Tuple[Any, ...]) -> Dict[str, Any]:
        point_id, stage, pos, token, last_token = point
        return {
            "id": point_id,
            "stage": stage,
            "pos": int(pos),
            "token": token,
            "last_token": last_token,
            "lexeme": token.lexeme if token is not None else "",
            "line": int(token.line) if token is not None else 0,
            "column": int(token.column) if token is not None else 0,
        }

    def _find_error_restore_point(self, point_id: int) -> Optional[Dict[str, Any]]:
        for point in reversed(self._error_restore_points):
            if point[0] == point_id:
                return self._restore_point_map(point)
        return None

    # -- Error publication and recovery ---------------------------

    def _error_diagnostic(self, exc: BaseException, fallback_token: Optional[Token] = None) -> Diagnostic:
        """The Diagnostic of a compiler error, located at `fallback_token`
        (or the last token) when its producer gave no location."""
        return self._diagnostic_from_parse_error(exc, fallback_token=fallback_token or self._last_token)

    def _publish_error_events(self, payload: Dict[str, Any]) -> None:
        """Publish compiler.error.<category> and then the general
        compiler.error with the same payload."""
        bus = self.event_bus
        if bus is None or not bus.active:
            return
        category = payload["diagnostic"].category or "unclassified_error"
        bus.publish(f"compiler.error.{category}", payload)
        bus.publish("compiler.error", payload)

    def _count_unresolved_error(self, diag: Diagnostic) -> None:
        """Count one unresolved error toward the abort threshold."""
        self._unresolved_errors += 1
        if self._unresolved_errors >= self._max_errors:
            error = ParseError(f"too many errors ({self._max_errors}), aborting", diagnostic=diag)
            error.recoverable = False  # type: ignore[attr-defined]
            error.l2_reported = True  # type: ignore[attr-defined]
            raise error

    def _report_unrecoverable_error(self, exc: BaseException, fallback_token: Optional[Token] = None) -> Diagnostic:
        """Record and publish an error that will not be dispatched for
        recovery (once per exception)."""
        diag = self._error_diagnostic(exc, fallback_token)
        if getattr(exc, "l2_reported", False):
            return diag
        self.diagnostics.append(diag)
        self._publish_error_events({"diagnostic": diag, "recoverable": False})
        _mark_reported(exc)
        self._count_unresolved_error(diag)
        return diag

    def _recovery_payload(self, chain: "_RecoveryChain") -> Dict[str, Any]:
        return {"attempt": chain.attempt, "limit": chain.limit}

    def _finish_recovery_chain(self, stage: str, outcome: str = "success",
                               terminal: Optional[Diagnostic] = None) -> None:
        """End the open recovery chain for `stage`: publish its paired
        compile.recovery.end and mark superseded attempts."""
        chain = self._recovery_chain
        if chain is None or chain.stage != stage:
            return
        self._recovery_chain = None
        keep = None if outcome == "success" else terminal
        for diag in chain.diagnostics:
            if diag is not keep:
                self._superseded_diagnostics.add(id(diag))
        if chain.started and self.event_bus is not None and self.event_bus.active:
            payload: Dict[str, Any] = {
                "diagnostic": chain.diagnostics[-1],
                "recovery": self._recovery_payload(chain),
                "outcome": outcome,
            }
            if terminal is not None:
                payload["terminal-diagnostic"] = terminal
            self.event_bus.publish("compile.recovery.end", payload)

    def _dispatch_continuation_error(self, exc: Exception, stage: str) -> bool:
        """Dispatch a recoverable error whose recovery continues in place
        (event-stream output, CT event handlers); True when a handler
        resumed it.  The outer recovery chain and restore point are kept."""
        saved_chain = self._recovery_chain
        saved_point = self._current_error_restore_point
        self._recovery_chain = None
        try:
            point_id = self._add_error_restore_point(stage, self.pos, self._last_token, self._last_token)
            selected = self._dispatch_recoverable_compile_error(exc, stage=stage, restore_point_id=point_id)
            if selected is not None:
                self._finish_recovery_chain(stage)
            return selected is not None
        finally:
            self._recovery_chain = saved_chain
            self._current_error_restore_point = saved_point

    def _handle_event_stream_failure(self, exc: BaseException) -> bool:
        """A JSONL sink failed: dispatch it with JSONL output bypassed for
        the whole nested lineage; True when a handler resumed it."""
        bus = self.event_bus
        if bus is None or not isinstance(exc, Exception):
            return False
        bus.sink_bypass += 1
        try:
            return self._dispatch_continuation_error(exc, "event-stream")
        finally:
            bus.sink_bypass -= 1

    def on_candidate_unregistered(self, word: Word) -> None:
        """Dictionary hook: subscriptions owned by a removed candidate go."""
        bus = self.event_bus
        if bus is None or word.handle is None:
            return
        for sub in list(bus._ct_subscriptions.values()):
            if sub.owner == word.handle:
                bus.ct_unsubscribe(sub)

    def _dispatch_recoverable_compile_error(
        self,
        exc: Exception,
        *,
        stage: str,
        restore_point_id: Optional[int],
    ) -> Optional[Dict[str, Any]]:
        """Record and publish a compiler error.  When it is recoverable (a
        producer restore point exists, events are enabled, and the error is
        not marked unrecoverable) handlers may resume it; returns the selected
        restore point to retry from, or None when the error stands."""
        if getattr(exc, "l2_reported", False):
            return None
        point = self._find_error_restore_point(restore_point_id) if restore_point_id is not None else None
        point_token = None
        diag = self._error_diagnostic(exc, self._last_token)
        bus = self.event_bus
        chain = self._recovery_chain
        if chain is not None and (chain.stage != stage or self._recovery_dispatch_depth > 0):
            chain = None  # an independent (nested or other-stage) error
        recoverable = (point is not None and getattr(exc, "recoverable", True)
                       and bus is not None and bus.active)

        if chain is not None and (not recoverable or chain.attempt >= chain.limit):
            # The retry failed after the final allowed dispatch (or can no
            # longer be dispatched): terminal error, recorded before publishing.
            note = f"error recovery retry limit ({chain.limit}) reached" if recoverable else ""
            terminal = diag.replace(notes=diag.notes + (note,)) if note else diag
            chain.diagnostics.append(terminal)
            self.diagnostics.append(terminal)
            exc.recoverable = False  # type: ignore[attr-defined]
            if terminal is not diag and isinstance(exc, _DiagnosticError):
                exc.diagnostic = terminal
            _mark_reported(exc)
            try:
                self._publish_error_events({"diagnostic": terminal, "recoverable": False, "terminal": True})
            finally:
                # The paired end event follows the terminal error event.
                self._finish_recovery_chain(stage, "error", terminal)
            self._count_unresolved_error(terminal)
            return None
        if not recoverable:
            self._report_unrecoverable_error(exc, point_token if isinstance(point_token, Token) else None)
            return None

        if chain is None:
            chain = _RecoveryChain(stage, self._error_recovery_retry_limit)
        chain.attempt += 1
        chain.diagnostics.append(diag)
        payload: Dict[str, Any] = {
            "diagnostic": diag,
            "recoverable": True,
            "recovery": self._recovery_payload(chain),
            "restore-point-id": restore_point_id,
            "restore-point": {key: value for key, value in point.items() if key not in ("token", "last_token")},
        }
        handler_context = getattr(exc, "l2_event_context", None)
        if handler_context is not None:
            payload["event-handler"] = handler_context
        active = {"stage": stage, "restore_point_id": restore_point_id, "resume": False}
        previous = self._active_error_recovery
        self._active_error_recovery = active
        self._recovery_dispatch_depth += 1
        try:
            self._publish_error_events(payload)
        except BaseException:
            # A failing handler ends this continuation with an error.
            self._recovery_chain = chain
            self._finish_recovery_chain(stage, "error", diag)
            raise
        finally:
            self._recovery_dispatch_depth -= 1
            self._active_error_recovery = previous
            # The attempt is provisional during dispatch; history gets it now.
            self.diagnostics.append(diag)
            _mark_reported(exc)
        if not active["resume"]:
            self._recovery_chain = chain
            self._finish_recovery_chain(stage, "error", diag)
            self._count_unresolved_error(diag)
            return None
        selected = self._find_error_restore_point(int(active["restore_point_id"]))
        if selected is None or selected.get("stage") != stage:
            raise ParseError("compile error handler selected an invalid restore point",
                             code="recovery-restore-point-invalid")
        self._recovery_chain = chain
        chain.retrying = False
        if not chain.started:
            chain.started = True
            try:
                bus.publish("compile.recovery.start", {"diagnostic": diag, "recovery": self._recovery_payload(chain)})
            except BaseException:
                self._finish_recovery_chain(stage, "error", diag)
                raise
        return selected

    def reportable_diagnostics(self) -> List[Diagnostic]:
        """Diagnostics to show the user: recovered and superseded error
        attempts stay in history but are not reported as errors."""
        return [d for d in self.diagnostics
                if d.severity != "error" or id(d) not in self._superseded_diagnostics]

    def _record_diagnostic(
        self,
        token: Optional[Token],
        message: str,
        *,
        code: str,
        level: str = "error",
        hint: str = "",
        suggestion: str = "",
        notes: Optional[Sequence[str]] = None,
        helps: Optional[Sequence[str]] = None,
    ) -> None:
        """Record a diagnostic and raise ParseError if too many errors."""
        diag = Diagnostic(
            level=level,
            message=message,
            hint=hint,
            suggestion=suggestion,
            code=code,
            notes=notes,
            helps=helps,
            primary=self._token_origin(token),
        )
        self._record_diagnostic_obj(diag)

    def _token_origin(self, token: Optional[Token]) -> Optional[SourceOrigin]:
        """A token's SourceOrigin for diagnostics, or None without a token."""
        if token is None:
            return None
        origin = token.origin
        return None if origin is _SYNTHETIC_ORIGIN else origin

    def _parse_context_notes(self, token: Optional[Token]) -> List[str]:
        notes: List[str] = []
        if self.context_stack:
            ctx = self.context_stack[-1]
            if isinstance(ctx, Definition):
                notes.append(f"while parsing definition '{ctx.name}'")
        if self._macro_body_stack:
            notes.append(f"while parsing macro '{self._macro_body_stack[-1]['name']}'")
        if self.control_stack:
            top = self.control_stack[-1]
            ctype = top.get("type")
            if ctype:
                if "line" in top and "column" in top:
                    notes.append(f"inside '{ctype}' block opened at {top['line']}:{top['column']}")
                else:
                    notes.append(f"inside '{ctype}' block")
        if token is not None and int(getattr(token, "expansion_depth", 0)) > 0:
            notes.append(f"during macro expansion depth {int(token.expansion_depth)}")
        return notes

    def _diagnostic_from_parse_error(self, exc: Exception, *, fallback_token: Optional[Token]) -> Diagnostic:
        """The Diagnostic of a caught compiler error: the producer's own,
        with the current token as primary origin when the producer gave no
        location, plus parser context notes."""
        existing = getattr(exc, "diagnostic", None)
        if not isinstance(existing, Diagnostic) or not existing.code:
            existing = Diagnostic("error", str(exc) or "parse error", code="internal-parser",
                                  notes=[f"uncoded {type(exc).__name__}"])
        changes: Dict[str, Any] = {}
        if existing.primary is None and existing.line <= 0:
            origin = self._token_origin(fallback_token)
            if origin is not None:
                changes.update(primary=origin, path=Path(origin.path), line=origin.start_line,
                               column=origin.start_column,
                               length=max(existing.length, origin.end_column - origin.start_column)
                               if origin.start_line == origin.end_line else existing.length)
        context = [note for note in self._parse_context_notes(fallback_token) if note not in existing.notes]
        if context:
            changes["notes"] = existing.notes + tuple(context)
        return existing.replace(**changes) if changes else existing

    def _warn(
        self,
        token: Optional[Token],
        category: str,
        message: str,
        *,
        hint: str = "",
        suggestion: str = "",
        code: str = "",
        notes: Optional[Sequence[str]] = None,
        helps: Optional[Sequence[str]] = None,
    ) -> None:
        """Record a warning if the category is enabled. Promotes to error under --Werror."""
        if "all" not in self._warnings_enabled and category not in self._warnings_enabled:
            return
        level = "error" if self._werror else "warning"
        self._record_diagnostic(
            token,
            message,
            level=level,
            hint=hint,
            suggestion=suggestion,
            code=code or f"warning-{category}",
            notes=notes,
            helps=helps,
        )

    def _preview_value_repr(self, value: Any, *, max_len: int = 120) -> str:
        try:
            if isinstance(value, Token):
                text = f"Token({value.lexeme}@{value.line}:{value.column})"
            elif isinstance(value, str):
                escaped = value.replace("\\", "\\\\").replace("\n", "\\n").replace('"', '\\"')
                text = f'"{escaped}"'
            elif isinstance(value, list):
                text = f"list(len={len(value)})"
            elif isinstance(value, dict):
                text = f"map(len={len(value)})"
            else:
                text = repr(value)
        except Exception:
            text = "<unprintable>"
        if len(text) > max_len:
            return text[: max_len - 3] + "..."
        return text

    def _preview_stack_snapshot(self, *, max_items: int = 8) -> List[str]:
        stack = self.compile_time_vm.stack
        if not stack:
            return []
        tail = stack[-max_items:]
        out = [self._preview_value_repr(item) for item in tail]
        if len(stack) > max_items:
            out.insert(0, f"... ({len(stack) - max_items} more)")
        return out

    def _record_preview_execution_event(
        self,
        *,
        kind: str,
        word_name: str,
        token: Optional[Token],
        consumed_tokens: Sequence[str],
        stack_before: Sequence[str],
        stack_after: Sequence[str],
        emitted_ops: Sequence[Op],
    ) -> None:
        if not self.preview_trace_enabled:
            return

        emitted: List[str] = []
        for op in emitted_ops[:12]:
            if op.data is None:
                emitted.append(op.op)
            else:
                emitted.append(f"{op.op} {self._preview_value_repr(op.data, max_len=80)}")
        if len(emitted_ops) > 12:
            emitted.append(f"... ({len(emitted_ops) - 12} more)")

        self.preview_trace_events.append(
            {
                "kind": kind,
                "word": word_name,
                "path": str(self.location_for_token(token).path) if token is not None else "",
                "line": int(self.location_for_token(token).line) if token is not None else 0,
                "column": int(self.location_for_token(token).column) if token is not None else 0,
                "consumed": [str(piece) for piece in consumed_tokens],
                "stack_before": [str(piece) for piece in stack_before],
                "stack_after": [str(piece) for piece in stack_after],
                "emitted": emitted,
            }
        )

    def _skip_to_recovery_point(self) -> None:
        """Skip tokens until we reach a safe recovery point (end, ;, or top-level definition keyword)."""
        _recovery_keywords = {"word", "end", ";", ":asm", ":py", "extern", "macro"}
        depth = 0
        while self.pos < len(self.tokens):
            lex = self.tokens[self.pos].lexeme
            if lex == "word" or lex == ":asm" or lex == ":py":
                if depth == 0:
                    break  # Don't consume — let the main loop pick it up
                depth += 1
            elif lex == "end":
                if depth <= 1:
                    self.pos += 1
                    break
                depth -= 1
            elif lex == ";":
                self.pos += 1
                break
            elif lex == "extern" and depth == 0:
                break
            self.pos += 1
        # Reset state for recovery
        if self._macro_body_stack:
            del self._binding_scopes[-len(self._macro_body_stack):]
            self._macro_body_stack.clear()
        self._pending_priority = None
        self._pending_inline_definition = False
        while self.definition_stack:
            self.definition_stack.pop()
        while len(self.context_stack) > 1:
            self.context_stack.pop()
        self.control_stack.clear()

    def emit_tokens(self, tokens: List[Token]) -> None:
        """Insert emitted Tokens at the input position.  Emissions made while
        the parser has not advanced concatenate in call order."""
        anchor = self._emit_anchor
        if anchor is not None and anchor[0] == self.pos and anchor[2] is self.tokens:
            insert_at = anchor[0] + anchor[1]
            self.tokens[insert_at:insert_at] = tokens
            self._emit_anchor = (anchor[0], anchor[1] + len(tokens), self.tokens)
            return
        self.tokens[self.pos:self.pos] = tokens
        self._emit_anchor = (self.pos, len(tokens), self.tokens)

    def inject_token_objects(self, tokens: Sequence[Token]) -> None:
        """Insert tokens at the current parse position.  Inside an active
        transformation (e.g. a token hook) each token gains its frame."""
        if self._expansion_contexts:
            kind, name, trigger = self._expansion_contexts[-1]
            frame = ExpansionFrame(kind, name, trigger)
            tokens = [_derive_token(tok, tok.lexeme, frame=frame) for tok in tokens]
        if self._hook_dispatch_depth:
            # Hooks of one dispatch splice their output in dispatch order.
            self.emit_tokens(list(tokens))
            return
        self.tokens[self.pos:self.pos] = list(tokens)

    # Public helpers for macros ------------------------------------------------
    def next_token(self) -> Token:
        return self._consume()

    def peek_token(self) -> Optional[Token]:
        return None if self.pos >= len(self.tokens) else self.tokens[self.pos]

    def emit_node(self, node: Op) -> None:
        self._append_op(node)

    def most_recent_definition(self) -> Optional[Word]:
        return self.last_defined

    def _resolve_ct_handler(self, name: str) -> Tuple[Optional[Word], str]:
        """Resolve a CT handler name (hook, guard) by CT rules:
        the selected eligible candidate, else the compile-time intrinsic
        baseline.  A selected macro or runtime-only candidate is unavailable
        and never falls through.  Returns (word, "") or (None, reason)."""
        word = self.dictionary.lookup(name)
        if word is None:
            return None, f"word '{name}' is not defined"
        if word.macro_def is not None:
            return None, f"word '{name}' is a macro, not an ordinary CT word"
        if word.runtime_only:
            return None, f"word '{name}' is runtime-only"
        if word.definition is None and word.compile_time_intrinsic is None:
            return None, f"word '{name}' has no compile-time implementation"
        return word, ""

    def _call_ct_handler(self, word: Word, args: Sequence[Any]) -> List[Any]:
        """Run a CT handler on an isolated data stack holding `args`; returns
        the values it left there."""
        vm = self.compile_time_vm
        if vm.runtime_mode:
            raise ParseError(f"CT handler '{word.name}' cannot run in runtime VM mode", code="ct-word-unavailable")
        saved = vm.stack[:]
        vm.stack[:] = list(args)
        try:
            vm._call_word(word)
            return [vm._resolve_handle(value) for value in vm.stack]
        finally:
            vm.stack[:] = saved

    # -- Language packs and token hooks ---------------------------------

    @staticmethod
    def _lang_check_name(name: Any, op: str, what: str = "pack name") -> None:
        if not isinstance(name, str) or name == "":
            raise _lang_error("language-pack-invalid", f"{op}: {what} must be a nonempty string, got {name!r}")

    def _lang_pack(self, name: Any, op: str) -> _LangPack:
        """The existing pack `name`; an unknown pack is an error."""
        self._lang_check_name(name, op)
        pack = self._langs.packs.get(name)
        if pack is None:
            raise _lang_error("language-pack-unknown", f"{op}: unknown language pack '{name}'")
        return pack

    def _lang_owner_active(self, owner: str) -> bool:
        pack = self._langs.packs.get(owner)
        return pack is not None and pack.active

    def _lang_owned(self, pack: _LangPack) -> List[Word]:
        resolve = self.dictionary.resolve
        return [word for word in pack.resources.values() if resolve(word.handle) is word]

    def _lang_refresh_hooks(self) -> None:
        state = self._langs
        eligible = [hook for hook in state.hooks.values()
                    if hook.owner is None or (hook.enabled and self._lang_owner_active(hook.owner))]
        eligible.sort(key=_TokenHook.dispatch_key)
        state.chain = tuple(eligible)

    def lang_create(self, name: Any) -> bool:
        self._lang_check_name(name, "ct-lang-create")
        packs = self._langs.packs
        if name in packs:
            return False
        packs[name] = _LangPack(name)
        return True

    def lang_set_active(self, name: Any, active: bool, op: str) -> bool:
        pack = self._lang_pack(name, op)
        if pack.active == active:
            return False

        def flip() -> None:
            pack.active = active

        self.dictionary.owner_changed(self._lang_owned(pack), flip)
        self.rewrites.invalidate()
        self._lang_refresh_hooks()
        return True

    def lang_set_metadata(self, name: Any, metadata: Any) -> None:
        pack = self._lang_pack(name, "ct-lang-set-meta")
        if metadata is None:
            pack.metadata = {}
            return
        if not isinstance(metadata, Mapping):
            raise _lang_error("language-pack-metadata-invalid",
                              f"ct-lang-set-meta: metadata must be a string-keyed map or nil, got {_ct_type_name(metadata)}")
        pack.metadata = _lang_portable_copy(metadata, "metadata")

    def lang_status(self, name: Any) -> Optional[Dict[str, Any]]:
        self._lang_check_name(name, "ct-lang-status")
        pack = self._langs.packs.get(name)
        if pack is None:
            return None
        hooks = sorted(pack.hooks, key=_TokenHook.dispatch_key)
        owned = self._lang_owned(pack)
        live = self.rewrites.live
        return {
            "name": pack.name,
            "active": 1 if pack.active else 0,
            "metadata": _lang_portable_copy(pack.metadata, "metadata"),
            "token_hooks": [{
                "handle": hook.handle,
                "handler": hook.handler,
                "priority": hook.priority,
                "enabled?": 1 if hook.enabled else 0,
                "active?": 1 if hook.enabled and pack.active else 0,
            } for hook in hooks],
            "words": sorted(word.name for word in owned if word.macro_def is None),
            "macros": sorted(word.name for word in owned if word.macro_def is not None),
            "reader_rewrites": [{"handle": handle, "name": live[handle.id].name}
                                for handle in pack.rewrites["reader"] if handle.id in live],
            "grammar_rewrites": [{"handle": handle, "name": live[handle.id].name}
                                 for handle in pack.rewrites["grammar"] if handle.id in live],
        }

    def lang_remove(self, name: Any) -> bool:
        self._lang_check_name(name, "ct-lang-remove")
        state = self._langs
        pack = state.packs.get(name)
        if pack is None:
            return False
        owned = self._lang_owned(pack)
        del state.packs[name]
        for word in owned:
            self.unregister_candidate(word)
        for stage in _REWRITE_STAGES:
            for handle in pack.rewrites[stage]:
                self.rewrites.remove(handle)
        for hook in pack.hooks:
            state.hooks.pop(hook.handle.id, None)
        self.rewrites.invalidate()
        self._lang_refresh_hooks()
        return True

    def lang_add_rewrite(self, name: Any, stage: str, rule_name: Any, pattern: Any, replacement: Any) -> RewriteHandle:
        pack = self._lang_pack(name, f"ct-lang-add-{stage}-rewrite-named")
        handle = self.rewrites.register(stage, rule_name, pattern, replacement, owner=pack.name)
        pack.rewrites[stage].append(handle)
        return handle

    def lang_add_token_hook(self, name: Any, handler: Any) -> TokenHookHandle:
        pack = self._lang_pack(name, "ct-lang-add-token-hook")
        self._lang_check_name(handler, "ct-lang-add-token-hook", "handler name")
        hook = _TokenHook(pack.name, handler, None)
        pack.hooks.append(hook)
        self._langs.hooks[hook.handle.id] = hook
        self._lang_refresh_hooks()
        return hook.handle

    def lang_hook(self, handle: TokenHookHandle) -> Optional[_TokenHook]:
        hook = self._langs.hooks.get(handle.id)
        return hook if hook is not None and hook.owner is not None else None

    def lang_remove_token_hook(self, handle: TokenHookHandle) -> bool:
        hook = self.lang_hook(handle)
        if hook is None:
            return False
        del self._langs.hooks[handle.id]
        pack = self._langs.packs.get(hook.owner)
        if pack is not None:
            pack.hooks.remove(hook)
        self._lang_refresh_hooks()
        return True

    def set_global_token_hook(self, name: Any) -> None:
        op = "ct-parser-set-token-hook"
        if not isinstance(name, str) or name == "":
            raise _lang_error("token-hook-handler-invalid", f"{op}: handler name must be a nonempty string, got {name!r}")
        candidate = self.dictionary.selected(name)
        if candidate is None:
            reason = ("has only a built-in implementation" if self.dictionary.lookup(name) is not None
                      else "is not defined")
            raise _lang_error("token-hook-handler-invalid", f"{op}: '{name}' {reason}; a hook needs a word definition")
        if candidate.macro_def is not None:
            raise _lang_error("token-hook-handler-invalid", f"{op}: '{name}' is a macro, not an ordinary word")
        self.clear_global_token_hook()
        hook = _TokenHook(None, name, candidate.handle)
        self._langs.hooks[hook.handle.id] = hook
        self._langs.global_hook = hook
        self._lang_refresh_hooks()

    def clear_global_token_hook(self) -> None:
        state = self._langs
        hook = state.global_hook
        if hook is None:
            return
        state.global_hook = None
        state.hooks.pop(hook.handle.id, None)
        self._lang_refresh_hooks()

    def lang_adopt(self, name: Any, resource: Any, macro: bool) -> bool:
        op = "ct-lang-register-macro" if macro else "ct-lang-register-word"
        pack = self._lang_pack(name, op)
        self._lang_check_name(resource, op, "resource name")
        dictionary = self.dictionary
        candidate = dictionary.selected(resource)
        if candidate is None or candidate.owner is not None or (candidate.macro_def is not None) != macro:
            return False
        displaced = pack.resources.get(resource)
        if displaced is not None and dictionary.resolve(displaced.handle) is displaced:
            self.unregister_candidate(displaced)

        def adopt(target: Word) -> None:
            target.owner = pack.name

        dictionary.update(candidate, adopt)
        pack.resources[resource] = candidate
        return True

    def lang_resource(self, name: Any, resource: Any, op: str) -> Optional[Word]:
        pack = self._lang_pack(name, op)
        self._lang_check_name(resource, op, "resource name")
        word = pack.resources.get(resource)
        if word is None or self.dictionary.resolve(word.handle) is not word:
            return None
        return word

    def lang_unregister_resource(self, name: Any, resource: Any) -> bool:
        word = self.lang_resource(name, resource, "ct-lang-unregister-resource")
        if word is None:
            return False
        del self._langs.packs[name].resources[resource]
        return self.unregister_candidate(word)

    def _token_hook_failure(self, token: Token, hook: _TokenHook, index: int, reason: str,
                            returned: Optional[List[Any]] = None) -> ParseError:
        identity = ("the global token hook" if hook.owner is None
                    else f"token hook {hook.handle.id} of pack '{hook.owner}'")
        detail = f"; returned {_rewrite_values_text(returned)}" if returned is not None else ""
        return _lang_error("token-hook-failed",
                           f"{identity} ('{hook.handler}', chain position {index}) failed on token "
                           f"'{token.lexeme}': {reason}{detail}")

    def _run_token_hook(self, token: Token) -> bool:
        """Dispatch the eligible hook chain for one Token.  The chain and
        each hook's target are pinned first; a nonzero result consumes the
        Token and stops the chain."""
        dictionary = self.dictionary
        pinned: List[Tuple[_TokenHook, Optional[Word], str]] = []
        for hook in self._langs.chain:
            if hook.owner is None:
                word = dictionary.resolve(hook.target)
                if word is None or not dictionary.eligible(word):
                    continue
                pinned.append((hook, word, f"word '{word.name}' is runtime-only" if word.runtime_only else ""))
            else:
                word, reason = self._resolve_ct_handler(hook.handler)
                pinned.append((hook, word, reason))
        if not pinned:
            return False
        self._emit_anchor = None
        self._hook_dispatch_depth += 1
        try:
            for index, (hook, word, reason) in enumerate(pinned):
                if word is None or reason:
                    raise self._token_hook_failure(token, hook, index, reason)
                self._expansion_contexts.append(("token-hook", hook.handler, token))
                try:
                    results = self._call_ct_handler(word, [token])
                finally:
                    self._expansion_contexts.pop()
                if len(results) != 1 or not isinstance(results[0], int):
                    raise self._token_hook_failure(
                        token, hook, index,
                        "stack effect must be 'token -- handled?' with an integer or boolean result", results)
                if results[0]:
                    return True
            return False
        finally:
            self._hook_dispatch_depth -= 1


    def set_macro_expansion_limit(self, limit: int) -> None:
        if limit < 1:
            raise ParseError("macro expansion limit must be >= 1", code="ct-argument-invalid")
        self.macro_expansion_limit = int(limit)

    def set_macro_preview(self, enabled: bool) -> None:
        self.macro_preview = bool(enabled)

    def set_macro_profile_enabled(self, enabled: bool) -> None:
        self._macro_profile_enabled = bool(enabled)
        if not self._macro_profile_enabled:
            self._macro_profile.clear()

    def _intern_expansion_lexeme(self, lexeme: str) -> str:
        cached = self._expansion_lexeme_pool.get(lexeme)
        if cached is not None:
            return cached
        interned = sys.intern(str(lexeme))
        self._expansion_lexeme_pool[interned] = interned
        return interned


    def format_macro_profile(self, *, limit: int = 0) -> str:
        rows: List[Tuple[str, Dict[str, int]]] = []
        for name, row in self._macro_profile.items():
            calls = int(row.get("calls", 0))
            if calls <= 0:
                continue
            rows.append((name, row))
        if not rows:
            return "[macro-profile] no macro expansions recorded"

        rows.sort(
            key=lambda item: (
                -int(item[1].get("calls", 0)),
                -int(item[1].get("total_ns", 0)),
                item[0],
            )
        )
        if limit > 0:
            rows = rows[:limit]

        lines = [
            "[macro-profile] name calls tokens total-ms avg-us max-us",
        ]
        for name, row in rows:
            calls = int(row.get("calls", 0))
            tokens = int(row.get("tokens", 0))
            total_ns = int(row.get("total_ns", 0))
            max_ns = int(row.get("max_ns", 0))
            total_ms = total_ns / 1_000_000.0
            avg_us = (total_ns / calls) / 1_000.0 if calls > 0 else 0.0
            max_us = max_ns / 1_000.0
            lines.append(
                f"[macro-profile] {name} {calls} {tokens} {total_ms:.3f} {avg_us:.2f} {max_us:.2f}"
            )
        return "\n".join(lines)

    def _eliminate_dead_macros(self) -> int:
        to_remove: List[str] = []
        for name, word in list(self.dictionary.words.items()):
            if word.macro_def is None or word.owner is not None or len(self.dictionary.candidates.get(name, ())) != 1:
                continue
            if int(self._macro_hotness.get(name, 0)) > 0:
                continue
            # Keep mixed-mode words (for example compile-time intrinsic aliases).
            if word.definition is not None or word.compile_time_intrinsic is not None or word.runtime_intrinsic is not None:
                continue
            to_remove.append(name)

        for name in to_remove:
            self.unregister_word(name)
        return len(to_remove)

    def _eliminate_unused_rewrite_rules(self) -> int:
        """After the parse, drop rules that never applied (their state is
        no longer observable)."""
        engine = self.rewrites
        removed = 0
        for rule in list(engine.live.values()):
            if rule.applied == 0:
                engine.remove(rule.handle)
                removed += 1
        return removed

    def _finalize_parse_performance_passes(self) -> None:
        if self.enable_dead_macro_elimination:
            self._eliminate_dead_macros()
        if self.enable_unused_rewrite_elimination:
            self._eliminate_unused_rewrite_rules()

    def unregister_word(self, name: str) -> bool:
        """Remove the name's candidate when it has exactly one unowned
        candidate (ct-definition-unregister-by-name)."""
        candidates = self.dictionary.candidates.get(name)
        if not candidates or len(candidates) != 1 or candidates[0].owner is not None:
            return False
        return self.unregister_candidate(candidates[0])

    def unregister_candidate(self, word: Word) -> bool:
        """Remove one exact candidate.  Name-keyed metadata is dropped once
        the name has no candidates left."""
        name = word.name
        if not self.dictionary.unregister(word):
            return False
        if name in self.dictionary.candidates:
            return True
        self._macro_hotness.pop(name, None)
        self._macro_profile.pop(name, None)
        return True

    def word_exists(self, name: str) -> bool:
        return self.dictionary.has_name(name)


    def allocate_variable(self, name: str) -> Tuple[str, str]:
        if name in self.variable_labels:
            label = self.variable_labels[name]
        else:
            base = sanitize_label(f"var_{name}")
            label = base
            suffix = 0
            existing = set(self.variable_labels.values())
            while label in existing:
                suffix += 1
                label = f"{base}_{suffix}"
            self.variable_labels[name] = label
        hidden_word = f"__with_{name}"
        self.variable_words[name] = hidden_word
        if self.dictionary.lookup(hidden_word) is None:
            word = Word(name=hidden_word)

            def _intrinsic(builder: FunctionEmitter, target: str = label) -> None:
                builder.push_label(target)

            word.intrinsic = _intrinsic

            # CT intrinsic: allocate a qword in CTMemory for this variable.
            # The address is lazily created on first use and cached.
            _ct_var_addrs: Dict[str, int] = {}

            def _ct_intrinsic(vm: CompileTimeVM, var_name: str = name) -> None:
                if var_name not in _ct_var_addrs:
                    _ct_var_addrs[var_name] = vm.memory.allocate(8)
                vm.push(_ct_var_addrs[var_name])

            word.compile_time_intrinsic = _ct_intrinsic
            word.runtime_intrinsic = _ct_intrinsic
            self.dictionary.register_baseline(word)
        return label, hidden_word

    def _handle_end_control(self) -> None:
        """Close one generic control frame pushed by compile-time words."""
        if not self.control_stack:
            raise ParseError("unexpected 'end' without matching block", code="parser-unexpected-end")

        entry = self.control_stack[-1]
        if isinstance(entry, dict) and entry.get("type") == "begin":
            raise ParseError("'begin' loops close with 'again', not 'end'", code="parser-control-mismatch")
        if isinstance(entry, dict) and entry.get("type") == "match":
            self._finish_match()
            return
        if not isinstance(entry, dict):
            raise ParseError("invalid control frame", code="parser-control-frame-invalid")
        # Validate and stage every close op before changing parser state: a
        # bad descriptor leaves the frame on the stack and appends nothing.
        close_ops = entry.get("close_ops")
        if close_ops is not None and not isinstance(close_ops, list):
            raise ParseError(f"control frame field 'close_ops' must be a list or nil, got {_ct_type_name(close_ops)}",
                             code="parser-control-frame-invalid")
        staged: List[Op] = []
        for index, descriptor in enumerate(close_ops or ()):
            problem = _close_op_problem(descriptor)
            if problem is not None:
                raise ParseError(f"'end' of a '{entry.get('type')}' frame: close_ops[{index}]: {problem}",
                                 code="parser-control-frame-invalid")
            staged.append(_make_op(descriptor["op"], descriptor["data"]))
        self.control_stack.pop()
        for node in staged:
            self._append_op(node)

    def _count_remaining_end_tokens(self, start_index: int) -> int:
        count = 0
        idx = start_index
        toks = self.tokens
        n = len(toks)
        in_definition = bool(self.context_stack and isinstance(self.context_stack[-1], Definition))
        definition_starters = {"word", ":asm", ":py", "extern", "inline"}
        while idx < n:
            tok = toks[idx]
            if (
                in_definition
                and idx > start_index
                and tok.column == 0
                and tok.lexeme in definition_starters
            ):
                break
            if tok.lexeme == "end":
                count += 1
            idx += 1
        return count

    def _auto_close_if_else_frames(self, limit: int) -> int:
        """Implicitly close up to `limit` trailing if/else control frames."""
        closed = 0
        while closed < limit and self.control_stack:
            top = self.control_stack[-1]
            if top.get("type") not in ("if", "else"):
                break
            self._handle_end_control()
            closed += 1
        return closed

    def _handle_flexible_end(self, token: Token) -> None:
        """Close control frames with tolerant if/else shorthand semantics.

        If explicit `end` tokens are fewer than currently open control frames,
        trailing `if`/`else` frames are implicitly closed first so legacy and
        shorthand-heavy styles can coexist.
        """
        if not self.control_stack:
            raise ParseError(f"unexpected 'end' at {token.line}:{token.column}", code="parser-unexpected-end")

        # Common case: one open control frame, so this `end` must close it.
        if len(self.control_stack) == 1:
            self._handle_end_control()
            return

        current_end_index = self.pos - 1
        remaining_ends = self._count_remaining_end_tokens(current_end_index)
        reserved_definition_end = 0
        if self.context_stack and isinstance(self.context_stack[-1], Definition):
            reserved_definition_end = 1
        if reserved_definition_end > 0:
            remaining_ends = max(0, remaining_ends - reserved_definition_end)
        # `begin` frames close with `again`, not `end`.
        open_controls = sum(1 for entry in self.control_stack
                            if not (isinstance(entry, dict) and entry.get("type") == "begin"))
        if remaining_ends < open_controls:
            needed_implicit = open_controls - remaining_ends
            # The current `end` must still close one active control frame.
            # Never consume all open controls via implicit closure.
            max_implicit = max(0, open_controls - 1)
            if needed_implicit > max_implicit:
                needed_implicit = max_implicit
            self._auto_close_if_else_frames(needed_implicit)

        if not self.control_stack:
            raise ParseError(f"unexpected 'end' at {token.line}:{token.column}", code="parser-unexpected-end")

        self._handle_end_control()

    # Parsing ------------------------------------------------------------------
    def parse(self, tokens: Iterable[Token], source: str) -> Module:
        previous = self._parsing
        self._parsing = True
        try:
            return self._parse_tokens(tokens, source)
        finally:
            self._parsing = previous

    def _parse_tokens(self, tokens: Iterable[Token], source: str) -> Module:
        if self._warm_resume:
            # Continue a parse paused at the end of a warm prefix (the daemon's
            # pre-parsed stdlib): every piece of parser state is kept and the
            # new root's tokens are read after the prefix's.
            self._warm_resume = False
            new_tokens = tokens if isinstance(tokens, list) else list(tokens)
            self.tokens = list(self.tokens) + new_tokens
            self._root_srcmap = new_tokens[0]._srcmap if new_tokens else None
            self.source = source
            return self._parse_loop()
        self.tokens = tokens if isinstance(tokens, list) else list(tokens)
        self._root_srcmap = self.tokens[0]._srcmap if self.tokens else None
        self._token_iter = None
        self._token_iter_exhausted = True
        self.source = source
        self.pos = 0
        self._error_restore_points = deque(maxlen=512)
        self._error_restore_point_counter = 0
        self._current_error_restore_point = None
        self._active_error_recovery = None
        self._error_recovery_retry_limit = 8
        self._recovery_chain = None
        self._recovery_dispatch_depth = 0
        self._unresolved_errors = 0
        self._superseded_diagnostics.clear()
        self.diagnostics.clear()
        self.variable_labels = {}
        self.variable_words = {}
        self.cstruct_layouts = {}
        self.context_stack = [
            Module(
                forms=[],
                variables=self.variable_labels,
                cstruct_layouts=self.cstruct_layouts,
            )
        ]
        self._active_module = self.context_stack[0]
        self._predeclared.clear()
        self.definition_stack.clear()
        self.last_defined = None
        self.control_stack = []
        self.label_counter = 0
        self.clear_global_token_hook()
        self._last_token = None
        self.output_text_preamble = []
        self.output_data = []
        self.output_bss = None
        self._pending_inline_definition = False
        self._pending_preserve_definition = False
        self._pending_priority = None
        self.rewrites.reset_for_parse()
        self._macro_hotness.clear()
        self.preview_trace_events.clear()
        for _session in self._ct_parser_sessions:
            _session.open = False
        self._ct_parser_sessions.clear()
        self._canonical_tokens.clear()
        self._support_import_tokens.clear()
        if self._macro_profile_enabled:
            self._macro_profile.clear()
        return self._parse_loop()

    def _parse_loop(self) -> Module:
        _priority_keywords = _PARSE_PRIORITY_KEYWORDS
        _kw_get = _PARSE_KEYWORD_DISPATCH.get
        _tokens = self.tokens
        _rewrites = self.rewrites
        _try_rewrite = _rewrites.try_live
        _run_token_hook = self._run_token_hook
        _langs = self._langs
        _handle_list_begin = self._handle_list_begin
        _handle_list_end = self._handle_list_end
        _consume_pending_inline = self._consume_pending_inline
        _begin_definition = self._begin_definition
        _handle_flexible_end = self._handle_flexible_end
        _try_end_definition = self._try_end_definition
        _parse_asm_definition = self._parse_asm_definition
        _parse_py_definition = self._parse_py_definition
        _parse_extern = self._parse_extern
        _parse_priority_directive = self._parse_priority_directive
        _handle_ret = self._handle_ret
        _parse_bss_list_literal = self._parse_bss_list_literal
        _try_handle_builtin_control = self._try_handle_builtin_control
        _handle_token = self._handle_token
        _canonical_tokens = self._canonical_tokens
        _default_control_words = _DEFAULT_CONTROL_WORDS
        try:
            while self.pos < len(_tokens):
              try:
                token_pos = self.pos
                token = _tokens[token_pos]
                _chain = self._recovery_chain
                if _chain is not None and _chain.stage == "parse":
                    if _chain.retrying:
                        # The retried iteration completed: recovery succeeded.
                        self._finish_recovery_chain("parse")
                    else:
                        _chain.retrying = True
                # _add_error_restore_point, inlined (one per token).
                self._error_restore_point_counter += 1
                restore_point_id = self._error_restore_point_counter
                self._error_restore_points.append((restore_point_id, "parse", token_pos, token, self._last_token))
                self._current_error_restore_point = restore_point_id
                self.pos += 1
                self._last_token = token
                if _canonical_tokens and token in _canonical_tokens:
                    # Custom-frontend output is already canonical core input.
                    pass
                else:
                    if _rewrites.any_reader and _try_rewrite("reader", token):
                        _tokens = self.tokens
                        continue
                    if _langs.chain and _run_token_hook(token):
                        continue
                    if _rewrites.any_grammar and _try_rewrite("grammar", token):
                        _tokens = self.tokens
                        continue
                lexeme = token.lexeme
                if self._pending_priority is not None and lexeme not in _priority_keywords:
                    raise ParseError(
                        f"priority {self._pending_priority} must be followed by definition/extern",
                        code="parser-priority-invalid",
                    )
                if lexeme == ";" and self._macro_body_stack and self._try_finish_macro_definition(token):
                    continue
                if lexeme == "[" and self.control_stack:
                    top = self.control_stack[-1]
                    if top.__class__ is dict and top.get("type") == "match" and self._try_match_clause(token):
                        continue
                kw = _kw_get(lexeme)
                if kw is not None:
                    if kw == _PARSE_KW_LIST_BEGIN:
                        _handle_list_begin()
                    elif kw == _PARSE_KW_LIST_END:
                        _handle_list_end(token)
                    elif kw == _PARSE_KW_WORD:
                        inline_def = _consume_pending_inline()
                        preserve_def = self._consume_pending_preserve()
                        _begin_definition(token, terminator="end", inline=inline_def, preserve=preserve_def)
                    elif kw == _PARSE_KW_END:
                        if self.control_stack:
                            _handle_flexible_end(token)
                        elif _try_end_definition(token):
                            pass
                        else:
                            raise ParseError(f"unexpected 'end' at {token.line}:{token.column}", code="parser-unexpected-end")
                    elif kw == _PARSE_KW_ASM:
                        _parse_asm_definition(token)
                        _tokens = self.tokens
                    elif kw == _PARSE_KW_PY:
                        _parse_py_definition(token)
                        _tokens = self.tokens
                    elif kw == _PARSE_KW_EXTERN:
                        _parse_extern(token)
                    elif kw == _PARSE_KW_PRIORITY:
                        _parse_priority_directive(token)
                    elif kw == _PARSE_KW_RET:
                        _handle_ret(token)
                    elif kw == _PARSE_KW_BSS_LIST_BEGIN:
                        _parse_bss_list_literal(token)
                    elif kw == _PARSE_KW_IMPORT:
                        self._handle_import(token)
                        _tokens = self.tokens
                    elif kw == _PARSE_KW_FRONTEND_UNIT:
                        self._handle_frontend_unit(token)
                        _tokens = self.tokens
                    elif kw == _PARSE_KW_CONST:
                        self._parse_const(token)
                    continue
                if lexeme in _default_control_words and _try_handle_builtin_control(token):
                    continue
                if _handle_token(token):
                    _tokens = self.tokens
              except CompileTimeError as _recov_exc:
                restore_point = self._dispatch_recoverable_compile_error(
                    _recov_exc,
                    stage="parse",
                    restore_point_id=restore_point_id,
                )
                if restore_point is None:
                    raise
                self.pos = int(restore_point["pos"])
                self._last_token = restore_point.get("last_token")
                _tokens = self.tokens
                continue
              except ParseError as _recov_exc:
                restore_point = self._dispatch_recoverable_compile_error(
                    _recov_exc,
                    stage="parse",
                    restore_point_id=restore_point_id,
                )
                if restore_point is not None:
                    self.pos = int(restore_point["pos"])
                    self._last_token = restore_point.get("last_token")
                    _tokens = self.tokens
                    continue
                # Already recorded and published by the dispatch above.
                self._skip_to_recovery_point()
                _tokens = self.tokens
                continue
        except CompileTimeError:
            raise
        except ParseError:
            raise
        except Exception as exc:
            tok = self._last_token
            if tok is None:
                raise ParseError(
                    f"unexpected error during parse: {exc}",
                    code="internal-parser",
                    hint="the parser raised an unexpected internal exception",
                    suggestion="re-run with a reduced source snippet and report this as a compiler bug",
                ) from None
            loc = self.location_for_token(tok)
            raise ParseError(
                f"unexpected error near '{tok.lexeme}' at {tok.line}:{tok.column}: {exc}",
                path=loc.path,
                line=loc.line,
                column=loc.column,
                length=len(tok.lexeme),
                code="internal-parser",
                hint="the parser raised an unexpected internal exception",
                notes=[f"near token '{tok.lexeme}'"],
                helps=["re-run with a minimal reproduction and report this as a compiler bug"],
            ) from None

        if self._warm_pause:
            # A warm prefix ends here: no end-of-input checks or finalization.
            self._warm_pause = False
            return None  # type: ignore[return-value]

        if self._macro_body_stack:
            self._record_diagnostic(
                self._last_token,
                f"unterminated macro definition '{self._macro_body_stack[-1]['name']}' (missing ';')",
                code="parser-macro-unterminated",
                hint="macro declarations must end with ';'",
                suggestion="add ';' at the end of the macro body",
            )
        if self._pending_priority is not None:
            self._record_diagnostic(
                self._last_token,
                f"dangling priority {self._pending_priority} without following definition",
                code="parser-priority-invalid",
                hint="priority directives must be immediately followed by a definition",
                suggestion="place `word`, `:asm`, `:py`, or `extern` right after `priority`",
            )

        if len(self.context_stack) != 1:
            self._record_diagnostic(
                self._last_token,
                "unclosed definition at EOF",
                code="parser-definition-unclosed",
                hint="a definition was opened but not closed before end-of-file",
                suggestion="add a matching `end` for the current definition",
            )
        if self.control_stack:
            self._record_diagnostic(
                self._last_token,
                "unclosed control structure at EOF",
                code="parser-control-unclosed",
                hint="control-flow blocks must be explicitly closed",
                suggestion="add missing `end` tokens for open `if`/`else`/`for`/`while`/`begin` blocks",
            )

        # Parsing ended without the retried operation failing again.
        self._finish_recovery_chain("parse")
        # If any unresolved errors were accumulated, raise with all diagnostics
        error_count = self._unresolved_errors
        if error_count > 0:
            raise ParseError(f"compilation failed with {error_count} error(s)", code="compilation-failed")

        self._finalize_parse_performance_passes()

        module = self.context_stack.pop()
        if not isinstance(module, Module):  # pragma: no cover - defensive
            raise ParseError("internal parser state corrupt", code="internal-parser")
        module.variables = dict(self.variable_labels)
        module.text_preamble = list(self.output_text_preamble)
        module.data = list(self.output_data)
        module.bss = None if self.output_bss is None else list(self.output_bss)
        module.cstruct_layouts = dict(self.cstruct_layouts)
        return module

    def _handle_list_begin(self) -> None:
        label = self._new_label("list")
        self._append_op(_make_op("list_begin", label))
        self._push_control({"type": "list", "label": label})

    def _handle_list_end(self, token: Token) -> None:
        entry = self._pop_control(("list",))
        label = entry["label"]
        self._append_op(_make_op("list_end", label))

    def _parse_bss_list_literal(self, token: Token) -> None:
        values: List[int] = []
        while True:
            if self._eof():
                raise ParseError(f"missing '}}' for '{{' opened at {token.line}:{token.column}", code="parser-bss-list-invalid")
            cur = self._consume()
            if cur.lexeme == "}":
                break
            parsed = _parse_int_or_char_literal(cur)
            if parsed is None:
                raise ParseError(
                    f"only int/char literals are allowed in '{{}}' lists; got '{cur.lexeme}' at {cur.line}:{cur.column}",
                    code="parser-bss-list-invalid",
                )
            values.append(parsed)

        list_size = len(values)
        if not self._eof():
            peek = self.peek_token()
            if peek is not None and peek.lexeme.startswith(":"):
                size_tok = self._consume()
                raw = size_tok.lexeme[1:]
                if not raw:
                    raise ParseError(f"missing size after ':' at {size_tok.line}:{size_tok.column}", code="parser-bss-list-invalid")
                try:
                    list_size = int(raw, 0)
                except ValueError:
                    raise ParseError(f"invalid bss list size '{size_tok.lexeme}' at {size_tok.line}:{size_tok.column}", code="parser-bss-list-invalid")
                if list_size < 0:
                    raise ParseError("bss list size must be >= 0", code="parser-bss-list-invalid")
                if len(values) > list_size:
                    raise ParseError(
                        f"bss list has {len(values)} initializer values but declared size is {list_size}",
                        code="parser-bss-list-invalid",
                    )

        self._append_op(_make_op("bss_list_literal", {"size": list_size, "values": values}))

    def _should_use_custom_control(self, lexeme: str) -> bool:
        """Whether a registered override handles this control token.  A
        registered override must resolve to an available immediate CT word;
        it never falls back to the built-in silently."""
        if lexeme not in self.control_overrides:
            return False
        word = self.dictionary.lookup(lexeme)
        if word is None or word.runtime_only or not word.immediate:
            reason = ("is not defined" if word is None else "is runtime-only" if word.runtime_only
                      else "is not immediate")
            raise ParseError(f"control override '{lexeme}' is registered but its handler {reason}",
                             code="ct-word-unavailable")
        return True

    def _warn_control_override(self, token: Token, lexeme: str) -> None:
        if lexeme in self._warned_control_overrides:
            return
        self._warned_control_overrides.add(lexeme)
        sys.stderr.write(
            f"[warn] default control structure ({lexeme}) has been overridden; using custom implementation\n"
        )

    def _try_handle_builtin_control(self, token: Token) -> bool:
        lexeme = token.lexeme
        if lexeme not in _DEFAULT_CONTROL_WORDS:
            return False
        if self._should_use_custom_control(lexeme):
            self._warn_control_override(token, lexeme)
            return False
        if lexeme == "if":
            self._handle_builtin_if(token)
            return True
        if lexeme == "else":
            self._handle_builtin_else(token)
            return True
        if lexeme == "for":
            self._handle_builtin_for(token)
            return True
        if lexeme == "while":
            self._handle_builtin_while(token)
            return True
        if lexeme == "do":
            self._handle_builtin_do(token)
            return True
        if lexeme == "begin":
            self._handle_builtin_begin(token)
            return True
        if lexeme == "again":
            self._handle_builtin_again(token)
            return True
        if lexeme == "break" or lexeme == "continue":
            self._handle_loop_control(token)
            return True
        if lexeme == "match":
            self._handle_builtin_match(token)
            return True
        return False

    def _handle_builtin_if(self, token: Token) -> None:
        if self.control_stack:
            top = self.control_stack[-1]
            if (
                top.get("type") == "else"
                and isinstance(top.get("line"), int)
                and top["line"] == token.line
            ):
                prev_else = self._pop_control(("else",))
                shared_end = prev_else.get("end")
                if not isinstance(shared_end, str):
                    shared_end = self._new_label("if_end")
                false_label = self._new_label("if_false")
                self._append_op(_make_op("branch_zero", false_label))
                self._push_control(
                    {
                        "type": "if",
                        "false": false_label,
                        "end": shared_end,
                        "close_ops": [
                            {"op": "label", "data": false_label},
                            {"op": "label", "data": shared_end},
                        ],
                        "line": token.line,
                        "column": token.column,
                    }
                )
                return

        false_label = self._new_label("if_false")
        self._append_op(_make_op("branch_zero", false_label))
        self._push_control(
            {
                "type": "if",
                "false": false_label,
                "end": None,
                "close_ops": [{"op": "label", "data": false_label}],
                "line": token.line,
                "column": token.column,
            }
        )

    def _handle_builtin_else(self, token: Token) -> None:
        entry = self._pop_control(("if",))
        false_label = entry.get("false")
        if not isinstance(false_label, str):
            raise ParseError("invalid if control frame", code="parser-control-frame-invalid")
        end_label = entry.get("end")
        if not isinstance(end_label, str):
            end_label = self._new_label("if_end")
        self._append_op(_make_op("jump", end_label))
        self._append_op(_make_op("label", false_label))
        self._push_control(
            {
                "type": "else",
                "end": end_label,
                "close_ops": [{"op": "label", "data": end_label}],
                "line": token.line,
                "column": token.column,
            }
        )

    def _handle_builtin_for(self, token: Token) -> None:
        loop_label = self._new_label("for_loop")
        end_label = self._new_label("for_end")
        frame = {"loop": loop_label, "end": end_label}
        self._append_op(_make_op("for_begin", dict(frame)))
        self._push_control(
            {
                "type": "for",
                "loop": loop_label,
                "end": end_label,
                "close_ops": [{"op": "for_end", "data": dict(frame)}],
                "line": token.line,
                "column": token.column,
            }
        )

    def _handle_builtin_while(self, token: Token) -> None:
        begin_label = self._new_label("begin")
        end_label = self._new_label("end")
        self._append_op(_make_op("label", begin_label))
        self._push_control(
            {
                "type": "while_open",
                "begin": begin_label,
                "end": end_label,
                "line": token.line,
                "column": token.column,
            }
        )

    def _handle_builtin_do(self, token: Token) -> None:
        entry = self._pop_control(("while_open",))
        begin_label = entry.get("begin")
        end_label = entry.get("end")
        if not isinstance(begin_label, str) or not isinstance(end_label, str):
            raise ParseError("invalid while control frame", code="parser-control-frame-invalid")
        self._append_op(_make_op("branch_zero", end_label))
        self._push_control(
            {
                "type": "while",
                "begin": begin_label,
                "end": end_label,
                "close_ops": [
                    {"op": "jump", "data": begin_label},
                    {"op": "label", "data": end_label},
                ],
                "line": token.line,
                "column": token.column,
            }
        )

    # -- Syntax quotations ---------------------------------------

    def _quotation_end(self, open_index: int) -> int:
        """Index of the backtick closing the quotation opened at
        `open_index`, scanning without consuming; an unterminated quotation
        raises syntax-unterminated-quotation (primary span: the opening
        delimiter through EOF)."""
        tokens = self.tokens
        index = open_index + 1
        while index < len(tokens):
            if tokens[index].lexeme == "`":
                return index
            if _unquote_opens(tokens, index):
                close = _unquote_close(tokens, index + 1, len(tokens))
                if close > 0:
                    index = close + 1  # backticks inside `$( … )` belong to the expression
                    continue
            index += 1
        open_token = tokens[open_index]
        origin = self._token_origin(open_token)
        last = tokens[-1] if tokens else open_token
        last_origin = self._token_origin(last)
        if origin is not None and last_origin is not None and last_origin.path == origin.path:
            origin = SourceOrigin(origin.path, origin.start, max(origin.end, last_origin.end), origin.start_line,
                                  origin.start_column, last_origin.end_line, last_origin.end_column)
        raise ParseError(
            f"unterminated quotation: no closing backtick before end of input "
            f"(opened at {open_token.line}:{open_token.column})",
            code="syntax-unterminated-quotation",
            origin=origin,
        )

    def _quotation_template(self, open_index: int, end_index: int) -> _QuotationTemplate:
        """Parse the Tokens between two backticks into a quotation template."""
        return _build_quotation_template(self.tokens[open_index + 1:end_index], self.tokens[open_index],
                                         self._lexical_bindings())

    def _parse_quotation(self, open_token: Token) -> None:
        open_index = self.pos - 1
        end_index = self._quotation_end(open_index)
        tokens = self.tokens
        if any(_unquote_opens(tokens, i) for i in range(open_index + 1, end_index)):
            self._parse_unquoting_quotation(open_token, open_index, end_index)
            return
        template = self._quotation_template(open_index, end_index)
        self.pos = end_index + 1
        self._last_token = self.tokens[end_index]
        self._append_op(_make_op("syntax", template, loc=self.location_for_token(open_token)))

    def _parse_unquoting_quotation(self, open_token: Token, open_index: int, end_index: int) -> None:
        """`` `… $(expr) …` ``.  Each expression's Tokens are parsed as
        ordinary code right after the quotation, left to right, followed by
        a marker Token that appends the quotation op.  Each expression must
        leave one value, which moves to the VM's unquote stack (so every
        expression sees the data stack as it was before the quotation); the
        quotation takes its values from there."""
        tokens = self.tokens
        separators = set(self.reader.separators)
        literal: List[Token] = []
        unquote_parts: Dict[Token, Tuple[Any, ...]] = {}
        expressions: List[Token] = []
        index = open_index + 1
        while index < end_index:
            if not _unquote_opens(tokens, index):
                literal.append(tokens[index])
                index += 1
                continue
            marker = tokens[index]
            close = _unquote_close(tokens, index + 1, end_index)
            if close < 0:
                raise ParseError(f"unterminated '$(' in quotation at {marker.line}:{marker.column}",
                                 code="syntax-splice-invalid")
            begin = _derive_token(marker, _UNQUOTE_BEGIN)
            end = _derive_token(tokens[close], _UNQUOTE_END)
            expressions.append(begin)
            expressions.extend(tokens[index + 2:close])
            expressions.append(end)
            suffix = ""
            after = close + 1
            if after < end_index:
                nxt = tokens[after]
                if (nxt.start == tokens[close].end and nxt._srcmap is tokens[close]._srcmap
                        and nxt.lexeme not in separators and not _unquote_opens(tokens, after)):
                    suffix = nxt.lexeme
                    after += 1
            placeholder = _derive_token(marker, marker.lexeme)  # a distinct Token for this unquote
            unquote_parts[placeholder] = ("unquote", marker.lexeme[:-1], suffix, marker)
            literal.append(placeholder)
            index = after
        template = _build_quotation_template(literal, open_token, self._lexical_bindings(), unquote_parts)
        finish = Token("\0quotation", open_token.line, open_token.column, open_token.start, open_token.end,
                       origin=open_token.origin)
        self._pending_quotations[finish] = template
        self.pos = end_index + 1
        self._last_token = tokens[end_index]
        tokens[self.pos:self.pos] = expressions + [finish]

    def _lexical_bindings(self) -> Set[str]:
        """`$name` bindings lexically in scope at the parse position (macro
        parameters and selected-clause pattern bindings)."""
        names: Set[str] = set()
        for scope in self._binding_scopes:
            names.update(scope)
        return names

    # -- Unified macros ---------------------------------------------

    def _begin_macro_definition(self, macro_token: Token) -> None:
        """`macro name [(params)] body ;` -- the body is CT L2 code parsed
        like a word body with the parameters as lexical bindings."""
        if self._macro_body_stack:
            raise ParseError("nested macro definitions are not supported", code="macro-signature-invalid")
        if len(self.context_stack) > 1:
            raise ParseError("macro definitions must be top-level forms", code="macro-signature-invalid")
        if self._eof():
            raise ParseError("macro name missing after 'macro'", code="macro-signature-invalid")
        name_token = self._consume()
        name = name_token.lexeme
        params: List[str] = []
        if not self._eof() and self.tokens[self.pos].lexeme == "(":
            self._consume()
            while True:
                if self._eof():
                    raise ParseError(f"unterminated parameter list for macro '{name}'", code="macro-signature-invalid")
                tok = self._consume()
                lexeme = tok.lexeme
                if lexeme == ")":
                    break
                if not _is_l2_identifier(lexeme):
                    raise ParseError(f"invalid macro parameter name '{lexeme}' in macro '{name}' at {tok.line}:{tok.column}",
                                     code="macro-signature-invalid")
                if self._reserved_binding_name(lexeme):
                    raise ParseError(f"'{lexeme}' is a reserved word and cannot be a parameter of macro '{name}'",
                                     code="macro-signature-invalid")
                if lexeme in params:
                    raise ParseError(f"duplicate macro parameter '{lexeme}' in macro '{name}'", code="macro-signature-invalid")
                params.append(lexeme)
        info = {
            "name": name,
            "params": tuple(params),
            "token": macro_token,
            "start": self.pos,
            "control_depth": len(self.control_stack),
            "priority": self._consume_pending_priority(),
        }
        if self._define_quotation_macro(info):
            return
        self.context_stack.append(Definition(name=name, body=[], terminator=";"))
        self._binding_scopes.append(set(params))
        self._macro_body_stack.append(info)

    def _define_quotation_macro(self, info: Dict[str, Any]) -> bool:
        """Definition-time shortcut for the common body `` `...` emit ; ``:
        build the same macro without running the general body parser."""
        tokens = self.tokens
        start = info["start"]
        if start >= len(tokens) or tokens[start].lexeme != "`":
            return False
        end = self._quotation_end(start)
        if end + 2 >= len(tokens) or tokens[end + 1].lexeme != "emit" or tokens[end + 2].lexeme != ";":
            return False
        if any(_unquote_opens(tokens, i) for i in range(start + 1, end)):
            return False  # `$(expr)` needs the general body parser
        # Macros are top-level forms, so the only bindings in scope are the
        # parameters.  Escapes are checked now; the template, body, and body
        # Syntax are built from the captured Tokens on first use.
        source = tokens[start:end + 2]
        _check_quotation_escapes(source[1:-2])
        self.pos = end + 3
        self._last_token = tokens[end + 2]
        self._register_macro(info, None, source, tokens[end + 2], None)
        return True

    def _register_macro(self, info: Dict[str, Any], definition: Definition, body_tokens: Sequence[Token],
                        end_token: Token, fast: Optional[_QuotationTemplate]) -> None:
        word = Word(name=info["name"], priority=info["priority"])
        if definition is None:  # the quotation fast path, built lazily
            word.macro_def = _MacroDef.from_quotation(info["name"], info["params"], list(body_tokens))
        else:
            word.macro_def = _MacroDef(info["params"], definition, Syntax(body_tokens), {}, fast)
        word.source_origin = info["token"]
        word.source_text = self._declaration_source(info["token"], end_token)
        changes: List[Dict[str, Any]] = []
        word = self._commit_source_candidate(word, changes)
        self.last_defined = word
        self.publish_definition_changes(changes)

    def _parse_const(self, token: Token) -> None:
        """`const NAME value` -- NAME expands to the single token
        `value`, like `macro NAME `value` emit ;`.  Only the declaration is
        recorded; the candidate is created on first use (or at once when NAME
        already has a definition, so shadowing works as for any definition)."""
        if len(self.context_stack) > 1 or self._macro_body_stack:
            raise ParseError("'const' must be a top-level form", code="definition-const-invalid")
        if self.pos + 1 >= len(self.tokens):
            raise ParseError("'const' needs a name and a value: const NAME value", code="definition-const-invalid")
        name_token = self.tokens[self.pos]
        value_token = self.tokens[self.pos + 1]
        name = name_token.lexeme
        if not _is_l2_identifier(name.replace(".", "_")) or name in _PARSE_KEYWORD_DISPATCH:
            raise ParseError(f"invalid const name '{name}'", code="definition-const-invalid")
        if value_token.lexeme in ("`", ";") or value_token.lexeme in _PARSE_KEYWORD_DISPATCH:
            raise ParseError(f"const '{name}' needs a single-token value, got '{value_token.lexeme}'",
                             code="definition-const-invalid")
        self.pos += 2
        self._last_token = value_token
        dictionary = self.dictionary
        if self._pending_priority is not None or dictionary.has_name(name):
            self.materialize_const(name, (token, name_token, value_token), priority=self._consume_pending_priority())
        else:
            dictionary.pending_consts[name] = (token, name_token, value_token)

    def materialize_const(self, name: str, entry: Tuple[Token, Token, Token], *, priority: int = 0) -> None:
        const_token, name_token, value_token = entry
        open_tick = _derive_token(value_token, "`")
        source = [open_tick, value_token, _derive_token(value_token, "`"), _derive_token(value_token, "emit")]
        word = Word(name=name, priority=priority)
        word.macro_def = _MacroDef.from_quotation(name, (), source)
        word.source_origin = const_token
        word.source_text = self._declaration_source(const_token, value_token)
        changes: List[Dict[str, Any]] = []
        self._commit_source_candidate(word, changes)
        self.publish_definition_changes(changes)

    def _try_finish_macro_definition(self, end_token: Token) -> bool:
        """A `;` at the top level of the macro body being parsed ends it."""
        info = self._macro_body_stack[-1]
        if len(self.control_stack) != info["control_depth"]:
            return False
        if not isinstance(self.context_stack[-1], Definition) or self.context_stack[-1].terminator != ";":
            return False
        self._macro_body_stack.pop()
        definition = self.context_stack.pop()
        self._binding_scopes.pop()
        body_tokens = self.tokens[info["start"]:self.pos - 1]
        self._register_macro(info, definition, body_tokens, end_token, self._macro_fast_template(definition))
        return True

    def _macro_fast_template(self, definition: Definition) -> Optional[_QuotationTemplate]:
        """A body that is exactly one quotation followed by `emit` expands
        by splicing directly (same result, no CT execution)."""
        body = definition.body
        if (len(body) == 2 and body[0]._opcode == OP_SYNTAX and body[1]._opcode == OP_WORD
                and body[1].data == "emit" and not body[0].data.unquotes):
            return body[0].data
        return None


    def _expand_macro(self, word: Word, trigger: Token) -> None:
        """Expand one macro invocation: capture its N argument values, run
        its body, and insert the emitted Tokens (into the calling macro's
        output buffer when invoked from a running macro body)."""
        mdef: _MacroDef = word.macro_def
        name = word.name
        if word.runtime_only:
            raise ParseError(f"macro '{name}' is runtime-only and cannot run at compile time",
                             code="ct-runtime-only-target")
        depth = trigger.expansion_depth + 1
        if depth > self.macro_expansion_limit:
            raise ParseError(f"expansion depth limit ({self.macro_expansion_limit}) exceeded while expanding '{name}'",
                             code="macro-expansion-limit")
        params = mdef.params
        count = len(params)
        values = self._peek_input_values(self.pos, count) if count else []
        if len(values) < count:
            raise ParseError(
                f"macro '{name}' expects {count} argument value(s) but only {len(values)} remain before end of input",
                code="macro-insufficient-arguments",
                origin=self._token_origin(trigger),
            )
        if count:
            self.pos = values[-1][1]
            self._last_token = self.tokens[self.pos - 1]
        bindings = {param: value for param, (value, _) in zip(params, values)}
        self._macro_hotness[name] = self._macro_hotness.get(name, 0) + 1
        nesting = len(self._macro_frames)
        # A recovery retry re-expands the same invocation (same trigger).
        attempt_key = (id(trigger), name, nesting)
        attempt = self._macro_attempts.get(attempt_key, 0) + 1
        self._macro_attempts[attempt_key] = attempt
        bus = self.event_bus
        observed = bus is not None and bus.wants("macro.expansion")
        started = time.perf_counter_ns() if self._macro_profile_enabled else 0
        try:
            if mdef.fast is not None:
                tokens = self._splice_macro_template(mdef.fast, bindings)
            else:
                tokens = self._run_macro_body(word, bindings, trigger)
        except (ParseError, CompileError) as exc:
            if observed:
                diag = getattr(exc, "diagnostic", None)
                bus.publish("macro.expansion", {
                    "macro": name, "call-site": self._token_origin(trigger), "depth": nesting,
                    "attempt": attempt, "status": "failed",
                    "code": getattr(diag, "code", None), "phase": getattr(diag, "phase", None),
                })
            raise
        frame = ExpansionFrame("macro", name, trigger, word)  # definition origin resolved on demand
        output = [_derive_token(tok, tok.lexeme, frame=frame, expansion_depth=depth) for tok in tokens]
        if self._macro_frames:
            self._macro_frames[-1]["buffer"].extend(output)
        else:
            self.tokens[self.pos:self.pos] = output
        if self._macro_profile_enabled:
            row = self._macro_profile.setdefault(name, {"calls": 0, "tokens": 0, "total_ns": 0, "max_ns": 0})
            elapsed = time.perf_counter_ns() - started
            row["calls"] += 1
            row["tokens"] += len(output)
            row["total_ns"] += elapsed
            row["max_ns"] = max(row["max_ns"], elapsed)
        if observed:
            bus.publish("macro.expansion", {
                "macro": name, "call-site": self._token_origin(trigger), "depth": nesting,
                "attempt": attempt, "status": "success", "tokens": list(output),
            })
        if self.macro_preview:
            _macro_preview(self, name, trigger, output)

    def _splice_macro_template(self, template: _QuotationTemplate, bindings: Dict[str, Any]) -> List[Token]:
        vm = self.compile_time_vm
        saved = vm.binding_env
        vm.binding_env = bindings
        try:
            return list(vm._evaluate_quotation(template).tokens)
        finally:
            vm.binding_env = saved

    def _run_macro_body(self, word: Word, bindings: Dict[str, Any], trigger: Token) -> List[Token]:
        """Run a macro body on its own CT data stack with its parameter
        bindings; returns what it emitted.  Output is discarded on failure."""
        vm = self.compile_time_vm
        frame = {
            "macro": word.name,
            "definition-origin": _word_source_origin(word),
            "call-site": self._token_origin(trigger),
            "buffer": [],
        }
        self._macro_frames.append(frame)
        saved_stack = vm.stack
        saved_env = vm.binding_env
        saved_depth = len(vm._binding_stack)
        vm.stack = []
        vm.binding_env = dict(bindings)
        try:
            vm.run_macro_body(word.name, word.macro_def.body)
        finally:
            vm.stack = saved_stack
            vm.binding_env = saved_env
            del vm._binding_stack[saved_depth:]
            self._macro_frames.pop()
        return frame["buffer"]

    def macro_context(self) -> Dict[str, Any]:
        if not self._macro_frames:
            raise ParseError("ct-macro-context is only available while a macro body runs",
                             code="macro-context-unavailable")
        trace = [{"macro": f["macro"], "definition-origin": f["definition-origin"], "call-site": f["call-site"]}
                 for f in self._macro_frames]
        current = trace[-1]
        return {"macro": current["macro"], "definition-origin": current["definition-origin"],
                "call-site": current["call-site"], "expansion-trace": trace}

    def _compile_macro_body(self, name: str, params: Sequence[str], body: "Syntax") -> Definition:
        """Parse Tokens as a macro body (validated, not executed)."""
        staged, sink = _staging_parser(self)
        header = [_derive_token(None, "macro"), _derive_token(None, name)]
        if params:
            header.append(_derive_token(None, "("))
            header.extend(_derive_token(None, p) for p in params)
            header.append(_derive_token(None, ")"))
        staged.parse(header + list(body.tokens) + [_derive_token(None, ";")], "")
        if len(sink) != 1 or sink[0].macro_def is None:
            raise ParseError(f"invalid body for macro '{name}'", code="macro-body-invalid")
        return sink[0].macro_def.body

    # -- match over the token stream -------------------------------

    def _reserved_binding_name(self, name: str) -> bool:
        return name in _RESERVED_BINDING_WORDS or name in self.block_openers

    def _match_pattern_error(self, token: Token, message: str) -> ParseError:
        return ParseError(f"{message} at {token.line}:{token.column}", code="match-pattern-invalid",
                          origin=self._token_origin(token))

    def _match_header_end(self, open_index: int) -> Optional[int]:
        """When the `[` at `open_index` starts a `[pattern] =>` clause header,
        the index of its `=>`; else None.  A lone `\\` escapes the next
        token, so `\\]` does not close the pattern."""
        tokens = self.tokens
        index = open_index + 1
        while index < len(tokens):
            lexeme = tokens[index].lexeme
            if lexeme == "\\":
                index += 2
                continue
            if lexeme == "]":
                if index + 1 < len(tokens) and tokens[index + 1].lexeme == "=>":
                    return index + 1
                return None
            index += 1
        return None

    def _parse_match_pattern(self, open_index: int, arrow_index: int) -> _MatchPattern:
        """Parse the elements between `[` and `]` (the `]` is just before
        `arrow_index`)."""
        open_token = self.tokens[open_index]
        items = self.tokens[open_index + 1:arrow_index - 1]
        if len(items) == 1 and items[0].lexeme == "_":
            return _MatchPattern((), True, open_token)
        elements = self._parse_match_elements(items, open_token)
        return _MatchPattern(elements, False, open_token)

    def _parse_match_elements(self, items: Sequence[Token], open_token: Token) -> List[Tuple[Any, ...]]:
        elements: List[Tuple[Any, ...]] = []
        index = 0
        expect_element = True
        while index < len(items):
            token = items[index]
            lexeme = token.lexeme
            if not expect_element:
                if lexeme != ",":
                    raise self._match_pattern_error(token, f"expected ',' between pattern elements, got '{lexeme}'")
                expect_element = True
                index += 1
                continue
            group = _repetition_group(items, index)
            if group is not None:
                close, separator, minimum, after = group
                inner = self._parse_match_elements(items[index + 2:close], token)
                elements.append(("rep", tuple(inner), separator, minimum))
                index = after
                expect_element = False
                continue
            if lexeme == ",":
                raise self._match_pattern_error(token, "empty pattern element")
            if lexeme == "\\":
                if index + 1 >= len(items):
                    raise self._match_pattern_error(token, "a trailing '\\' escapes nothing")
                elements.append(("lit", items[index + 1].lexeme))
                index += 2
                expect_element = False
                continue
            elements.append(self._match_element(token))
            index += 1
            expect_element = False
        if not elements:
            raise self._match_pattern_error(open_token, "a pattern must match at least one value")
        if expect_element:
            raise self._match_pattern_error(items[-1], "trailing ',' in pattern")
        return elements

    def _match_element(self, token: Token) -> Tuple[Any, ...]:
        lexeme = token.lexeme
        if lexeme[0] == "\\":
            return ("lit", lexeme[1:])
        if lexeme == "*":
            return ("wild",)
        if lexeme.startswith("$*"):
            raise self._match_pattern_error(token, f"'{lexeme}' is a rewrite-only form; write '\\{lexeme}' for the literal")
        if lexeme[0] == "!" and len(lexeme) > 1:
            raise self._match_pattern_error(token, f"'{lexeme}' (negation) is a rewrite-only form; write '\\{lexeme}' for the literal")
        if len(lexeme) > 1 and lexeme[-1] in "?*+":
            raise self._match_pattern_error(
                token, f"'{lexeme}' ends with the rewrite quantifier '{lexeme[-1]}'; write '\\{lexeme}' for the literal")
        if lexeme[0] == "$":
            body = lexeme[1:]
            name, _, constraint = body.partition(":")
            if not _is_l2_identifier(name):
                raise self._match_pattern_error(token, f"invalid binding '{lexeme}'")
            if self._reserved_binding_name(name):
                raise self._match_pattern_error(token, f"'{name}' is a reserved word and cannot be a binding name")
            if ":" in body:
                if constraint not in _MATCH_CONSTRAINTS:
                    raise self._match_pattern_error(
                        token, f"unknown constraint '{constraint}'; use one of {', '.join(sorted(_MATCH_CONSTRAINTS))}")
                return ("cap", name, constraint)
            return ("cap", name, None)
        return ("lit", lexeme)

    def _handle_builtin_match(self, token: Token) -> None:
        spec = _MatchSpec(token)
        end_label = self._new_label("match_end")
        self._append_op(_make_op("match_select", spec, loc=self.location_for_token(token)))
        frame: Dict[str, Any] = {
            "type": "match",
            "spec": spec,
            "end": end_label,
            "keys": set(),
            "open": False,
            "line": token.line,
            "column": token.column,
        }
        self._push_control(frame)
        arrow = self._match_header_end(self.pos) if self.pos < len(self.tokens) and self.tokens[self.pos].lexeme == "[" else None
        if arrow is None:
            raise ParseError(f"'match' must be followed by a '[pattern] =>' clause at {token.line}:{token.column}",
                             code="match-pattern-invalid")
        self._start_match_clause(frame, self.pos, arrow)

    def _try_match_clause(self, token: Token) -> bool:
        """At a match's clause level, `[pattern] =>` starts the next clause."""
        frame = self.control_stack[-1]
        open_index = self.pos - 1
        arrow = self._match_header_end(open_index)
        if arrow is None:
            return False
        self._start_match_clause(frame, open_index, arrow)
        return True

    def _close_match_clause(self, frame: Dict[str, Any]) -> None:
        if frame["open"]:
            self._append_op(_make_op("match_leave", None))
            self._append_op(_make_op("jump", frame["end"]))
            self._binding_scopes.pop()
            frame["open"] = False

    def _start_match_clause(self, frame: Dict[str, Any], open_index: int, arrow_index: int) -> None:
        spec: _MatchSpec = frame["spec"]
        pattern = self._parse_match_pattern(open_index, arrow_index)
        self.pos = arrow_index + 1
        self._last_token = self.tokens[arrow_index]
        if spec.default_label is not None:
            raise self._match_pattern_error(pattern.token, "the default clause '[_]' must be the last clause")
        if pattern.default:
            following = self.tokens[self.pos:self.pos + 2]
            if len(following) == 2 and following[0].lexeme == "_" and following[1].lexeme == "end":
                raise self._match_pattern_error(
                    following[0], "'[_] => _' was removed; an empty default body passes input through")
        else:
            key = pattern.duplicate_key()
            if key in frame["keys"]:
                self._record_diagnostic(pattern.token, "duplicate match pattern; this clause can never be selected",
                                        code="match-duplicate-pattern", level="warning")
            frame["keys"].add(key)
        self._close_match_clause(frame)
        label = self._new_label("match_clause")
        self._append_op(_make_op("label", label))
        if pattern.default:
            spec.default_label = label
        else:
            spec.clauses.append((pattern, label))
            spec.max_length = max(spec.max_length, len(pattern.elements))
        self._binding_scopes.append(set(pattern.names))
        frame["open"] = True

    def _finish_match(self) -> None:
        frame = self.control_stack.pop()
        self._close_match_clause(frame)
        self._append_op(_make_op("label", frame["end"]))

    def _peek_input_values(self, start: int, count: int) -> List[Tuple[Any, int]]:
        """Up to `count` input values from token index `start`, without
        consuming: each is (Token or Syntax, index after it).  A complete
        backtick quotation is one Syntax value; an unterminated one raises
        syntax-unterminated-quotation."""
        values: List[Tuple[Any, int]] = []
        tokens = self.tokens
        index = start
        while len(values) < count and index < len(tokens):
            token = tokens[index]
            if token.lexeme == "`":
                end = self._quotation_end(index)
                template = self._quotation_template_raw(index, end)
                values.append((template, end + 1))
                index = end + 1
                continue
            values.append((token, index + 1))
            index += 1
        return values

    def _quotation_template_raw(self, open_index: int, end_index: int) -> "Syntax":
        """A quotation read as an input value: its Tokens with escapes
        applied; `$name` stays literal (no bindings at the call site)."""
        tokens: List[Token] = []
        for token in self.tokens[open_index + 1:end_index]:
            lexeme = token.lexeme
            if lexeme == "\\`":
                tokens.append(_derive_token(token, "`"))
            elif lexeme == "\\\\":
                tokens.append(_derive_token(token, "\\"))
            elif lexeme.startswith("\\$") and len(lexeme) > 2:
                tokens.append(_derive_token(token, lexeme[1:]))
            elif lexeme[0] == "\\":
                raise ParseError(f"invalid escape '{lexeme}' in quotation at {token.line}:{token.column}",
                                 code="syntax-escape-invalid")
            else:
                tokens.append(token)
        return Syntax(tokens)

    def _handle_builtin_begin(self, token: Token) -> None:
        begin_label = self._new_label("begin")
        end_label = self._new_label("again_end")
        self._append_op(_make_op("label", begin_label))
        self._push_control(
            {
                "type": "begin",
                "begin": begin_label,
                "end": end_label,
                "line": token.line,
                "column": token.column,
            }
        )

    def _handle_builtin_again(self, token: Token) -> None:
        entry = self._pop_control(("begin",))
        self._append_op(_make_op("jump", entry["begin"]))
        self._append_op(_make_op("label", entry["end"]))

    def _handle_loop_control(self, token: Token) -> None:
        """`break` leaves and `continue` restarts the innermost enclosing
        loop (`for`, `while ... do ... end`, `begin ... again`)."""
        frame = None
        crossed_matches = 0
        for entry in reversed(self.control_stack):
            if isinstance(entry, dict) and entry.get("type") in _LOOP_FRAME_TYPES:
                frame = entry
                break
            if isinstance(entry, dict) and entry.get("type") == "match":
                crossed_matches += 1
        if frame is None:
            raise ParseError(f"'{token.lexeme}' outside a loop at {token.line}:{token.column}",
                             code="parser-loop-control-outside-loop")
        # Leaving match clauses restores their enclosing bindings first.
        for _ in range(crossed_matches):
            self._append_op(_make_op("match_leave", None, loc=self.location_for_token(token)))
        kind = frame["type"]
        if kind == "for":
            close_ops = frame["close_ops"]
            if token.lexeme == "continue":
                label = frame.get("continue")
                if label is None:
                    # The counter step (for_end) follows this label.
                    label = frame["continue"] = self._new_label("for_continue")
                    close_ops.insert(0, {"op": "label", "data": label})
                self._append_op(_make_op("jump", label, loc=self.location_for_token(token)))
                return
            label = frame.get("break")
            if label is None:
                label = frame["break"] = self._new_label("for_break")
                close_ops.append({"op": "label", "data": label})
            # Leave the loop: drop its counter and frame, then jump past it.
            self._append_op(_make_op("for_drop", None, loc=self.location_for_token(token)))
            self._append_op(_make_op("jump", label, loc=self.location_for_token(token)))
            return
        target = frame["begin"] if token.lexeme == "continue" else frame["end"]
        self._append_op(_make_op("jump", target, loc=self.location_for_token(token)))

    def _parse_priority_directive(self, token: Token) -> None:
        if self._eof():
            raise ParseError(f"priority value missing at {token.line}:{token.column}", code="parser-priority-invalid")
        value_tok = self._consume()
        try:
            value = int(value_tok.lexeme, 0)
        except ValueError:
            raise ParseError(
                f"invalid priority '{value_tok.lexeme}' at {value_tok.line}:{value_tok.column}",
                code="parser-priority-invalid",
            )
        self._pending_priority = value

    def _consume_pending_priority(self, *, default: int = 0) -> int:
        if self._pending_priority is None:
            return default
        value = self._pending_priority
        self._pending_priority = None
        return value

    def _handle_ret(self, token: Token) -> None:
        self._append_op(_make_op("ret", loc=self.location_for_token(token)))

    # Internal helpers ---------------------------------------------------------

    def _parse_extern(self, token: Token) -> None:
        # extern <name> [inputs outputs]
        # OR
        # extern <ret_type> <name>(<args>)

        if self._eof():
            raise ParseError(f"extern missing name at {token.line}:{token.column}", code="parser-extern-invalid")

        priority = self._consume_pending_priority(default=self.EXTERN_DEFAULT_PRIORITY)
        self._extern_start_token = token
        first_token = self._consume()
        if self._try_parse_c_extern(first_token, priority=priority):
            return
        self._parse_legacy_extern(first_token, priority=priority)

    def _commit_extern(self, word: Word) -> None:
        start = self._extern_start_token
        word.source_origin = start
        end = self.tokens[self.pos - 1] if 0 < self.pos <= len(self.tokens) else None
        word.source_text = self._declaration_source(start, end)
        self._commit_source_candidate(word)

    def _parse_legacy_extern(self, name_token: Token, *, priority: int = 0) -> None:
        word = Word(name=name_token.lexeme, priority=priority)
        word.is_extern = True
        peek = self.peek_token()
        if peek is not None and peek.lexeme.isdigit():
            word.extern_inputs = int(self._consume().lexeme)
            peek = self.peek_token()
            if peek is not None and peek.lexeme.isdigit():
                word.extern_outputs = int(self._consume().lexeme)
            else:
                word.extern_outputs = 0
        else:
            word.extern_inputs = 0
            word.extern_outputs = 0
        self._commit_extern(word)

    def _try_parse_c_extern(self, first_token: Token, *, priority: int = 0) -> bool:
        saved_pos = self.pos
        prefix_tokens: List[str] = [first_token.lexeme]

        while True:
            if self._eof():
                self.pos = saved_pos
                return False
            lookahead = self._consume()
            if lookahead.lexeme == "(":
                break
            if lookahead.lexeme.isdigit():
                self.pos = saved_pos
                return False
            prefix_tokens.append(lookahead.lexeme)

        if not prefix_tokens:
            raise ParseError("extern missing return type/name before '('", code="parser-extern-invalid")

        name_lexeme = prefix_tokens.pop()
        if not _is_identifier(name_lexeme):
            prefix_name, suffix_name = _split_trailing_identifier(name_lexeme)
            if suffix_name is None:
                raise ParseError(f"extern expected identifier before '(' but got '{name_lexeme}'", code="parser-extern-invalid")
            name_lexeme = suffix_name
            if prefix_name:
                prefix_tokens.append(prefix_name)

        if not _is_identifier(name_lexeme):
            raise ParseError(f"extern expected identifier before '(' but got '{name_lexeme}'", code="parser-extern-invalid")

        ret_type = _normalize_c_type_tokens(prefix_tokens, allow_default=True)
        inputs, arg_types, variadic = self._parse_c_param_list()
        outputs = 0 if ret_type == "void" else 1
        self._register_c_extern(name_lexeme, inputs, outputs, arg_types, ret_type,
                                priority=priority, variadic=variadic)
        return True

    def _parse_c_param_list(self) -> Tuple[int, List[str], bool]:
        """Parse C-style parameter list. Returns (count, types, is_variadic)."""
        inputs = 0
        arg_types: List[str] = []
        variadic = False

        if self._eof():
            raise ParseError("extern unclosed '('", code="parser-extern-invalid")
        peek = self.peek_token()
        if peek.lexeme == ")":
            self._consume()
            return inputs, arg_types, False

        while True:
            # Check for ... (variadic)
            peek = self.peek_token()
            if peek is not None and peek.lexeme == "...":
                self._consume()
                variadic = True
                if self._eof():
                    raise ParseError("extern unclosed '(' after '...'", code="parser-extern-invalid")
                closing = self._consume()
                if closing.lexeme != ")":
                    raise ParseError("expected ')' after '...' in extern parameter list", code="parser-extern-invalid")
                break
            lexemes = self._collect_c_param_lexemes()
            arg_type = _normalize_c_type_tokens(lexemes, allow_default=False)
            if arg_type == "void" and inputs == 0:
                if self._eof():
                    raise ParseError("extern unclosed '(' after 'void'", code="parser-extern-invalid")
                closing = self._consume()
                if closing.lexeme != ")":
                    raise ParseError("expected ')' after 'void' in extern parameter list", code="parser-extern-invalid")
                return 0, [], False
            inputs += 1
            arg_types.append(arg_type)
            if self._eof():
                raise ParseError("extern unclosed '('", code="parser-extern-invalid")
            separator = self._consume()
            if separator.lexeme == ")":
                break
            if separator.lexeme != ",":
                raise ParseError(
                    f"expected ',' or ')' in extern parameter list, got '{separator.lexeme}'",
                    code="parser-extern-invalid",
                )
        return inputs, arg_types, variadic

    def _collect_c_param_lexemes(self) -> List[str]:
        lexemes: List[str] = []
        while True:
            if self._eof():
                raise ParseError("extern unclosed '('", code="parser-extern-invalid")
            peek = self.peek_token()
            if peek.lexeme in (",", ")"):
                break
            lexemes.append(self._consume().lexeme)

        if not lexemes:
            raise ParseError("missing parameter type in extern declaration", code="parser-extern-invalid")

        if len(lexemes) > 1 and _is_identifier(lexemes[-1]):
            lexemes.pop()
            return lexemes

        prefix, suffix = _split_trailing_identifier(lexemes[-1])
        if suffix is not None:
            if prefix:
                lexemes[-1] = prefix
            else:
                lexemes.pop()
        return lexemes

    def _register_c_extern(
        self,
        name: str,
        inputs: int,
        outputs: int,
        arg_types: List[str],
        ret_type: str,
        *,
        priority: int = 0,
        variadic: bool = False,
    ) -> None:
        word = Word(name=name, priority=priority)
        word.is_extern = True
        word.extern_inputs = inputs
        word.extern_outputs = outputs
        word.extern_signature = (arg_types, ret_type)
        word.extern_variadic = variadic
        self._commit_extern(word)

    def _handle_token(self, token: Token) -> bool:
        """Handle a token. Returns True if the token list was modified (macro expansion)."""
        lexeme = token.lexeme
        lexeme_len = len(lexeme)
        first = lexeme[0]
        if first == "`" and lexeme_len == 1:
            self._parse_quotation(token)
            return True
        if first == "\0" and token in self._pending_quotations:
            template = self._pending_quotations.pop(token)
            self._append_op(_make_op("syntax", template, loc=self.location_for_token(template.open_token)))
            return False
        if first == "$" and lexeme_len > 1 and self._binding_scopes and _is_l2_identifier(lexeme[1:]):
            # Inside a macro body or match clause every $name reads a
            # binding; an unbound one is an error when it runs.
            self._append_op(_make_op("binding", lexeme[1:], loc=self.location_for_token(token)))
            return False
        _append_op = self._append_op
        _try_literal = self._try_literal
        words = self.dictionary.words
        # Fast-path: cached literal parsing for numeric/quoted candidates.
        if (
            first in _LITERAL_FIRST_CHARS
            or ((first == '-' or first == '+') and lexeme_len > 1)
            or (first > '\x7f' and first.isdigit())
        ):
            if _try_literal(token):
                return False

        if first == '&':
            target_name = lexeme[1:]
            if not target_name:
                raise ParseError(f"missing word name after '&' at {token.line}:{token.column}", code="parser-word-pointer-invalid")
            _append_op(_make_op("word_ptr", target_name))
            return False

        word = words.get(lexeme)
        if word is None and lexeme in self.dictionary.pending_consts:
            word = self.dictionary.materialize_const(lexeme)
        if word is not None:
            if word.macro_def is not None:
                if self._macro_body_stack:
                    # Inside a macro body a macro name is a direct call.
                    _append_op(_make_word_op(lexeme))
                    return False
                self._expand_macro(word, token)
                return True
            if word.immediate:
                if word.macro:
                    produced = word.macro(MacroContext(self))
                    if produced:
                        for node in produced:
                            _append_op(node)
                else:
                    self._execute_immediate_word(word)
                return False

        _append_op(_make_word_op(lexeme))
        return False

    def _execute_immediate_word(self, word: Word) -> None:
        consumed_tokens: List[str] = []
        stack_before: List[str] = []
        stack_after: List[str] = []
        emitted_ops: List[Op] = []
        token = self._last_token
        target_ops: Optional[List[Op]] = None
        target_len_before = 0
        pos_before = self.pos

        if self.preview_trace_enabled:
            stack_before = self._preview_stack_snapshot()
            target = self.context_stack[-1] if self.context_stack else None
            if isinstance(target, Definition):
                target_ops = target.body
                target_len_before = len(target_ops)
            elif isinstance(target, Module):
                target_ops = target.forms  # type: ignore[assignment]
                target_len_before = len(target_ops)

        try:
            self.compile_time_vm.invoke(word)
        except CompileTimeError:
            raise
        except ParseError:
            raise
        except Exception as exc:  # pragma: no cover - defensive
            raise _rewrap_error(exc, CompileTimeError,
                                message=f"compile-time word '{word.name}' failed: {exc}") from None

        if self.preview_trace_enabled:
            pos_after = self.pos
            consumed_tokens = [tok.lexeme for tok in self.tokens[pos_before:pos_after]]
            stack_after = self._preview_stack_snapshot()
            if target_ops is not None and len(target_ops) > target_len_before:
                emitted_ops = [node for node in target_ops[target_len_before:] if isinstance(node, Op)]
            self._record_preview_execution_event(
                kind="immediate",
                word_name=word.name,
                token=token,
                consumed_tokens=consumed_tokens,
                stack_before=stack_before,
                stack_after=stack_after,
                emitted_ops=emitted_ops,
            )

    def _push_control(self, entry: Dict[str, str]) -> None:
        if "line" not in entry or "column" not in entry:
            tok = self._last_token
            if tok is not None:
                entry = dict(entry)
                entry["line"] = tok.line
                entry["column"] = tok.column
        self.control_stack.append(entry)

    def _pop_control(self, expected: Tuple[str, ...]) -> Dict[str, str]:
        if not self.control_stack:
            raise ParseError("control stack underflow", code="parser-control-underflow")
        entry = self.control_stack.pop()
        if entry.get("type") not in expected:
            tok = self._last_token
            location = ""
            if tok is not None:
                location = f" at {tok.line}:{tok.column} near '{tok.lexeme}'"
            origin = ""
            if "line" in entry and "column" in entry:
                origin = f" (opened at {entry['line']}:{entry['column']})"
            raise ParseError(f"mismatched control word '{entry.get('type')}'" + origin + location, code="parser-control-mismatch")
        return entry

    def _new_label(self, prefix: str) -> str:
        label = f"L_{prefix}_{self.label_counter}"
        self.label_counter += 1
        return label

    def _handle_import(self, token: Token) -> None:
        """Canonical import request: `import` followed by a string literal.
        The named file is loaded now and its tokens are read next."""
        def where() -> str:  # only needed for error messages
            origin = token.origin
            return f"{origin.path}:{origin.start_line}:{origin.start_column}"
        if self.pos >= len(self.tokens):
            raise ParseError(f"'import' must be followed by a string literal path at {where()}", code="import-malformed")
        path_token = self.tokens[self.pos]
        try:
            target = _parse_string_literal(path_token)
        except ParseError as exc:
            raise ParseError(f"invalid import path at {where()}: {exc}", code="import-malformed") from exc
        if target is None or target == "":
            raise ParseError(f"'import' must be followed by a non-empty string literal path "
                             f"at {where()}, got {path_token.lexeme!r}", code="import-malformed")
        self.pos += 1
        self._last_token = path_token
        compiler = getattr(self, "_compiler_ref", None)
        if compiler is None:
            raise ParseError(f"cannot import {target!r} at {where()}: no compiler source loader", code="import-unresolved")
        support = token in self._support_import_tokens
        new_tokens = compiler._import_request(token, target, support=support)
        if new_tokens:
            self.tokens[self.pos:self.pos] = new_tokens

    def _handle_frontend_unit(self, token: Token) -> None:
        if token not in self._frontend_markers:
            raise ParseError("internal frontend marker without a source unit", code="internal-frontend-marker")
        new_tokens = self._compiler_ref._expand_frontend_unit(token)
        if new_tokens:
            self.tokens[self.pos:self.pos] = new_tokens

    def _try_end_definition(self, token: Token) -> bool:
        if len(self.context_stack) <= 1:
            return False
        ctx = self.context_stack[-1]
        if not isinstance(ctx, Definition):
            return False
        if ctx.terminator != token.lexeme:
            return False
        self._end_definition(token)
        return True

    def _consume_pending_inline(self) -> bool:
        pending = self._pending_inline_definition
        self._pending_inline_definition = False
        return pending

    def _consume_pending_preserve(self) -> bool:
        pending = self._pending_preserve_definition
        self._pending_preserve_definition = False
        return pending

    def _begin_definition(self, token: Token, terminator: str = "end", inline: bool = False,
                          preserve: bool = False) -> None:
        if self._eof():
            raise ParseError(
                f"definition name missing after '{token.lexeme}' at {token.line}:{token.column}",
                code="parser-definition-name-missing",
            )
        name_token = self._consume()
        priority = self._consume_pending_priority()
        effect = self._stack_effect_for(token)
        stack_inputs = effect[0] if effect is not None else None
        stack_outputs = effect[1] if effect is not None else None
        definition = Definition(
            name=name_token.lexeme,
            body=[],
            terminator=terminator,
            inline=inline,
            preserve=preserve,
            stack_inputs=stack_inputs,
            stack_outputs=stack_outputs,
        )
        if self.event_bus is not None:
            payload = {"name": definition.name, "kind": "regular", "source_location": _event_location(name_token, self), "phase": "begin"}
            self.event_bus.publish("word.compile.begin", payload)
            self.event_bus.publish("compile", payload)
        self.context_stack.append(definition)
        # Staged until its body is complete: CT code cannot see a partially
        # built definition.
        candidate = Word(name=definition.name, priority=priority)
        candidate.definition = definition
        candidate.inline = inline
        candidate.source_origin = token
        self.definition_stack.append((candidate, token))

    def _end_definition(self, token: Token) -> None:
        if len(self.context_stack) <= 1:
            raise ParseError(f"unexpected '{token.lexeme}' at {token.line}:{token.column}", code="parser-definition-terminator")
        ctx = self.context_stack.pop()
        if not isinstance(ctx, Definition):
            raise ParseError(f"'{token.lexeme}' can only close definitions", code="parser-definition-terminator")
        if ctx.terminator != token.lexeme:
            raise ParseError(
                f"definition '{ctx.name}' expects terminator '{ctx.terminator}' but got '{token.lexeme}'",
                code="parser-definition-terminator",
            )
        word, start_token = self.definition_stack.pop()
        ctx.immediate = word.immediate
        ctx.compile_only = word.compile_only
        ctx.runtime_only = word.runtime_only
        ctx.inline = word.inline
        if word.runtime_only and (word.compile_only or word.immediate):
            raise ParseError(
                f"word '{word.name}' cannot be both runtime-only and compile-time-active",
                code="definition-flags-conflict",
            )
        if word.compile_only or word.immediate:
            word.compile_time_override = True
        module = self.context_stack[-1]
        if not isinstance(module, Module):
            raise ParseError("nested definitions are not supported yet", code="parser-nested-definition")
        word.source_text = self._declaration_source(start_token, token)
        changes: List[Dict[str, Any]] = []
        word = self._commit_source_candidate(word, changes)
        module.forms.append(word.definition)
        self.last_defined = word
        if self.event_bus is not None:
            self.event_bus.publish("word.compile.end", {"name": ctx.name, "kind": "regular", "duration_ns": 0, "size_bytes": len(ctx.body)})
        self.publish_definition_changes(changes)

    def _parse_effect_annotations(self) -> List[str]:
        """Parse a '(effects ...)' clause that follows a :asm name."""
        open_tok = self._consume()
        if open_tok.lexeme != "(":  # pragma: no cover - defensive
            raise ParseError("internal parser error: effect clause must start with '('", code="internal-parser")
        tokens: List[Token] = []
        while True:
            if self._eof():
                raise ParseError("unterminated effect clause in asm definition", code="parser-effect-clause-invalid")
            tok = self._consume()
            if tok.lexeme == ")":
                break
            tokens.append(tok)
        if not tokens:
            raise ParseError("effect clause must include 'effect' or 'effects'", code="parser-effect-clause-invalid")
        keyword = tokens.pop(0)
        if keyword.lexeme.lower() not in {"effect", "effects"}:
            raise ParseError(
                f"effect clause must start with 'effect' or 'effects', got '{keyword.lexeme}'",
                code="parser-effect-clause-invalid",
            )
        effect_names: List[str] = []
        for tok in tokens:
            if tok.lexeme == ",":
                continue
            normalized = tok.lexeme.lower().replace("_", "-")
            canonical = _WORD_EFFECT_ALIASES.get(normalized)
            if canonical is None:
                raise ParseError(
                    f"unknown effect '{tok.lexeme}' at {tok.line}:{tok.column}",
                    code="parser-effect-clause-invalid",
                )
            if canonical not in effect_names:
                effect_names.append(canonical)
        if not effect_names:
            raise ParseError("effect clause missing effect names", code="parser-effect-clause-invalid")
        return effect_names

    def _parse_asm_definition(self, token: Token) -> None:
        if self._eof():
            raise ParseError(f"definition name missing after ':asm' at {token.line}:{token.column}", code="parser-asm-invalid")
        inline_def = self._consume_pending_inline()
        preserve_def = self._consume_pending_preserve()
        name_token = self._consume()
        effect_names: Optional[List[str]] = None
        if not self._eof():
            next_token = self.peek_token()
            if next_token is not None and next_token.lexeme == "(":
                effect_names = self._parse_effect_annotations()
        brace_token = self._consume()
        if brace_token.lexeme != "{":
            raise ParseError(f"expected '{{' after asm name at {brace_token.line}:{brace_token.column}", code="parser-asm-invalid")
        block_start = brace_token.end
        block_end: Optional[int] = None
        body_tokens: List[Token] = []
        # Scan for closing brace directly via list indexing (avoid method-call overhead)
        # (the same pass notes whether any body token was expanded or comes
        # from another source text, which forces reconstruction from tokens)
        _tokens = self.tokens
        _tlen = len(_tokens)
        _pos = self.pos
        brace_srcmap = brace_token._srcmap
        expanded = foreign = False
        while _pos < _tlen:
            nt = _tokens[_pos]
            _pos += 1
            if nt.lexeme == "}":
                block_end = nt.start
                break
            body_tokens.append(nt)
            if nt.expansion_depth > 0:
                expanded = True
            if nt._srcmap is not brace_srcmap:
                foreign = True
        self.pos = _pos
        if block_end is None:
            raise ParseError("missing '}' to terminate asm body", code="parser-asm-invalid")
        brace_text = self._source_text_of(brace_token)
        asm_body = brace_text[block_start:block_end] if brace_text is not None else ""
        reconstruct_from_tokens = brace_text is None or expanded
        if body_tokens and (block_end <= block_start or foreign):
            reconstruct_from_tokens = True
        if reconstruct_from_tokens:
            asm_body = _reconstruct_asm_from_tokens(body_tokens)
        priority = self._consume_pending_priority()
        effect = self._stack_effect_for(token)
        stack_inputs = effect[0] if effect is not None else None
        stack_outputs = effect[1] if effect is not None else None
        definition = AsmDefinition(
            name=name_token.lexeme,
            body=asm_body,
            inline=inline_def,
            preserve=preserve_def,
            stack_inputs=stack_inputs,
            stack_outputs=stack_outputs,
        )
        if self.event_bus is not None:
            payload = {"name": definition.name, "kind": "asm", "source_location": _event_location(name_token, self), "phase": "begin"}
            self.event_bus.publish("word.compile.begin", payload)
            self.event_bus.publish("compile", payload)
        if effect_names is not None:
            definition.effects = set(effect_names)
        candidate = Word(name=definition.name, priority=priority)
        candidate.definition = definition
        candidate.source_origin = token
        if inline_def:
            candidate.inline = True
        module = self.context_stack[-1]
        if not isinstance(module, Module):
            raise ParseError("asm definitions must be top-level forms", code="parser-asm-invalid")
        if self._eof():
            raise ParseError("asm definition missing terminator ';'", code="parser-asm-invalid")
        terminator = self._consume()
        if terminator.lexeme != ";":
            raise ParseError(f"expected ';' after asm definition at {terminator.line}:{terminator.column}", code="parser-asm-invalid")
        candidate.source_text = self._declaration_source(token, terminator)
        changes: List[Dict[str, Any]] = []
        word = self._commit_source_candidate(candidate, changes)
        module.forms.append(word.definition)
        self.last_defined = word
        if self.event_bus is not None:
            self.event_bus.publish("word.compile.end", {"name": definition.name, "kind": "asm", "duration_ns": 0, "size_bytes": len(asm_body.encode("utf-8"))})
        self.publish_definition_changes(changes)

    def _parse_py_definition(self, token: Token) -> None:
        if self._eof():
            raise ParseError(f"definition name missing after ':py' at {token.line}:{token.column}", code="parser-py-invalid")
        name_token = self._consume()
        brace_token = self._consume()
        if brace_token.lexeme != "{":
            raise ParseError(f"expected '{{' after py name at {brace_token.line}:{brace_token.column}", code="parser-py-invalid")
        block_start = brace_token.end
        block_end: Optional[int] = None
        _tokens = self.tokens
        _tlen = len(_tokens)
        _pos = self.pos
        while _pos < _tlen:
            nt = _tokens[_pos]
            _pos += 1
            if nt.lexeme == "}":
                block_end = nt.start
                break
        self.pos = _pos
        if block_end is None:
            raise ParseError("missing '}' to terminate py body", code="parser-py-invalid")
        import textwrap
        brace_text = self._source_text_of(brace_token)
        if brace_text is None:
            raise ParseError(f"py body for '{name_token.lexeme}' has no source text", code="parser-py-invalid")
        py_body = textwrap.dedent(brace_text[block_start:block_end])
        priority = self._consume_pending_priority()
        word = Word(name=name_token.lexeme, priority=priority)
        word.source_origin = token
        namespace = self._py_exec_namespace()
        try:
            exec(py_body, namespace)
        except Exception as exc:  # pragma: no cover - user code
            raise ParseError(f"python macro body for '{word.name}' raised: {exc}", code="py-definition-failed") from exc
        macro_fn = namespace.get("macro")
        intrinsic_fn = namespace.get("intrinsic")
        if macro_fn is None and intrinsic_fn is None:
            raise ParseError("python definition must define 'macro' or 'intrinsic'", code="py-definition-failed")
        if macro_fn is not None:
            word.macro = macro_fn
            word.immediate = True
        if intrinsic_fn is not None:
            word.intrinsic = intrinsic_fn
        if self._eof():
            raise ParseError("py definition missing terminator ';'", code="parser-py-invalid")
        terminator = self._consume()
        if terminator.lexeme != ";":
            raise ParseError(f"expected ';' after py definition at {terminator.line}:{terminator.column}", code="parser-py-invalid")
        word.source_text = self._declaration_source(token, terminator)
        self._commit_source_candidate(word)

    # -- Definition candidates --------------------------------------

    def definition_events_active(self) -> bool:
        """Definition change records are built only when someone wants
        a definition.* event (a CT subscription, an observer, or a sink)."""
        bus = self.event_bus
        return (bus is not None and bus.active
                and (bus.wants("definition.candidates.changed") or bus.wants("definition.selection.changed")))

    def publish_definition_changes(self, changes: Sequence[Dict[str, Any]]) -> None:
        """Publish definition.candidates.changed for each change, each
        followed by definition.selection.changed for every name whose
        selected handle changed."""
        bus = self.event_bus
        if not changes or bus is None or not bus.active:
            return
        want_candidates = bus.wants("definition.candidates.changed")
        want_selection = bus.wants("definition.selection.changed")
        if not want_candidates and not want_selection:
            return
        for change in changes:
            operation = change["operation"]
            if want_candidates:
                bus.publish("definition.candidates.changed", change)
            if not want_selection:
                continue
            if operation == "rename":
                pairs = ((change["old-name"], change["old-previous-selected"], change["old-selected"]),
                         (change["new-name"], change["new-previous-selected"], change["new-selected"]))
            else:
                pairs = ((change["name"], change["previous-selected"], change["selected"]),)
            for name, previous, current in pairs:
                if previous != current:
                    bus.publish("definition.selection.changed", {
                        "name": name, "previous-handle": previous, "selected-handle": current, "cause": operation,
                    })

    def _declaration_source(self, start: Optional[Token], end: Optional[Token]) -> Optional[str]:
        """The exact source slice of a declaration, from its first to its
        last token, or None when it has no original text (generated tokens,
        or tokens from different sources)."""
        if start is None or end is None:
            return None
        srcmap = start._srcmap
        if srcmap is None or srcmap is not end._srcmap or start.expansion_chain or end.expansion_chain:
            return None
        text = srcmap.text
        if start.start < 0 or end.end < start.start or end.end > len(text):
            return None
        return text[start.start:end.end]

    def _commit_source_candidate(self, word: Word, changes: Optional[List[Dict[str, Any]]] = None) -> Word:
        """Register a completed source-level candidate.  In a staging parse
        the candidate is collected instead; a candidate predeclared by
        ct-definition-predeclare-all is completed in place, keeping its
        handle and registration order without a second event."""
        sink = self._definition_sink
        if sink is not None:
            sink.append(word)
            return word
        predeclared = self._predeclared.pop(word.name, None)
        if predeclared is not None and self.dictionary.resolve(predeclared.handle) is predeclared:
            for attr in ("priority", "definition", "immediate", "compile_only", "runtime_only", "inline",
                         "compile_time_override", "source_text", "source_origin"):
                setattr(predeclared, attr, getattr(word, attr))
            self.dictionary._refresh(word.name)
            self.dictionary.generation += 1
            return predeclared
        self.dictionary.register(word, defer=changes)
        return word

    def _source_text_of(self, token: Token) -> Optional[str]:
        """The text a token's start/end offsets index: the source of the
        tokenize call that produced it, or None for tokens without one."""
        srcmap = token._srcmap
        return srcmap.text if srcmap is not None else None

    def _stack_effect_for(self, token: Token) -> Optional[Tuple[Optional[int], Optional[int]]]:
        text = self._source_text_of(token)
        if text is None:
            return None
        return _parse_stack_effect_comment_full(text, token.start)

    def _py_exec_namespace(self) -> Dict[str, Any]:
        return dict(PY_EXEC_GLOBALS)

    def _append_op(self, node: Op) -> None:
        if self.capture_op_locations and node.loc is None:
            tok = self._last_token
            if tok is not None and tok._srcmap is not self._root_srcmap:
                node.loc = self.location_for_token(tok)
            elif tok is not None:
                # Inlined fast path of location_for_token
                spans = self.file_spans
                if spans:
                    if self._span_index_len != len(spans):
                        self._rebuild_span_index()
                        self._span_cache_idx = -1
                    tl = tok.line
                    ci = self._span_cache_idx
                    if ci >= 0:
                        span = spans[ci]
                        if span.start_line <= tl < span.end_line:
                            node.loc = _make_loc(span.path, span.local_start_line + (tl - span.start_line), tok.column)
                        else:
                            node.loc = self._location_for_token_slow(tok, tl)
                    else:
                        node.loc = self._location_for_token_slow(tok, tl)
                else:
                    node.loc = _make_loc(_SOURCE_PATH, tok.line, tok.column)
        target = self.context_stack[-1]
        if target.__class__ is Definition:
            target.body.append(node)
        else:
            target.forms.append(node)

    def _location_for_token_slow(self, token: Token, tl: int) -> SourceLocation:
        """Slow path for location_for_token: bisect lookup."""
        span_starts = self._span_starts
        idx = bisect.bisect_right(span_starts, tl) - 1
        if idx >= 0:
            span = self.file_spans[idx]
            if tl < span.end_line:
                self._span_cache_idx = idx
                return _make_loc(span.path, span.local_start_line + (tl - span.start_line), token.column)
        return _make_loc(_SOURCE_PATH, tl, token.column)

    def _try_literal(self, token: Token) -> bool:
        lexeme = token.lexeme
        cached = _PARSE_LITERAL_CACHE.get(lexeme, _PARSE_LITERAL_CACHE_MISS)
        if cached is _PARSE_LITERAL_NOT_LITERAL:
            return False
        if cached is not _PARSE_LITERAL_CACHE_MISS:
            self._append_op(_make_literal_op(cached))
            return True

        first = lexeme[0] if lexeme else '\0'
        if first.isdigit() or first == '-' or first == '+':
            try:
                value = int(lexeme, 0)
                _PARSE_LITERAL_CACHE[lexeme] = value
                if len(_PARSE_LITERAL_CACHE) > _PARSE_LITERAL_CACHE_MAX:
                    _PARSE_LITERAL_CACHE.clear()
                self._append_op(_make_literal_op(value))
                return True
            except ValueError:
                pass

        # Try float
        if first.isdigit() or first == '-' or first == '+' or first == '.':
            try:
                if "." in lexeme or "e" in lexeme.lower():
                    value = float(lexeme)
                    _PARSE_LITERAL_CACHE[lexeme] = value
                    if len(_PARSE_LITERAL_CACHE) > _PARSE_LITERAL_CACHE_MAX:
                        _PARSE_LITERAL_CACHE.clear()
                    self._append_op(_make_literal_op(value))
                    return True
            except ValueError:
                pass

        if first == '"':
            string_value = _parse_string_literal(token)
            if string_value is not None:
                _PARSE_LITERAL_CACHE[lexeme] = string_value
                if len(_PARSE_LITERAL_CACHE) > _PARSE_LITERAL_CACHE_MAX:
                    _PARSE_LITERAL_CACHE.clear()
                self._append_op(_make_literal_op(string_value))
                return True

        if first == "'":
            char_value = _parse_char_literal(token)
            if char_value is not None:
                _PARSE_LITERAL_CACHE[lexeme] = char_value
                if len(_PARSE_LITERAL_CACHE) > _PARSE_LITERAL_CACHE_MAX:
                    _PARSE_LITERAL_CACHE.clear()
                self._append_op(_make_literal_op(char_value))
                return True

        _PARSE_LITERAL_CACHE[lexeme] = _PARSE_LITERAL_NOT_LITERAL
        if len(_PARSE_LITERAL_CACHE) > _PARSE_LITERAL_CACHE_MAX:
            _PARSE_LITERAL_CACHE.clear()
        return False

    def _consume(self) -> Token:
        pos = self.pos
        if pos >= len(self.tokens):
            raise ParseError("unexpected EOF", code="parser-unexpected-eof")
        self.pos = pos + 1
        return self.tokens[pos]

    def _eof(self) -> bool:
        return self.pos >= len(self.tokens)

    def _ensure_tokens(self, upto: int) -> None:
        if self._token_iter_exhausted:
            return
        if self._token_iter is None:
            self._token_iter_exhausted = True
            return
        while len(self.tokens) <= upto and not self._token_iter_exhausted:
            try:
                next_tok = next(self._token_iter)
            except StopIteration:
                self._token_iter_exhausted = True
                break
            self.tokens.append(next_tok)


# ---------------------------------------------------------------------------
# § 11. Compile-time VM
# ---------------------------------------------------------------------------


def _to_i64(v: int) -> int:
    """Truncate to signed 64-bit integer (matching x86-64 register semantics)."""
    v = v & 0xFFFFFFFFFFFFFFFF
    if v >= 0x8000000000000000:
        v -= 0x10000000000000000
    return v


class _CTVMJump(Exception):
    """Raised by the ``jmp`` intrinsic to transfer control in _execute_nodes."""

    def __init__(self, target_ip: int) -> None:
        self.target_ip = target_ip


class _CTVMReturn(Exception):
    """Raised to return from the current word frame in _execute_nodes."""


class _CTVMExit(Exception):
    """Raised by the ``exit`` intrinsic to stop compile-time execution."""

    def __init__(self, code: int = 0) -> None:
        self.code = code


class CTMemory:
    """Managed memory for the compile-time VM.

    Uses ctypes buffers with real process addresses so that ``c@``, ``c!``,
    ``@``, ``!`` can operate on them directly via ``ctypes.from_address``.

    String literals are slab-allocated from a contiguous data section so that
    ``data_start``/``data_end`` bracket them correctly for ``print``'s range
    check.
    """

    PERSISTENT_SIZE = 64  # matches default BSS ``persistent: resb 64``
    PRINT_BUF_SIZE = 128   # matches ``PRINT_BUF_BYTES``
    DATA_SECTION_SIZE = 4 * 1024 * 1024  # 4 MB slab for string literals

    def __init__(self, persistent_size: int = 0) -> None:
        import ctypes as _ctypes
        globals().setdefault('ctypes', _ctypes)
        self._buffers: List[Any] = []  # prevent GC of ctypes objects
        self._string_cache: Dict[str, Tuple[int, int]] = {}  # cache string literals

        # Persistent BSS region (for ``mem`` word)
        actual_persistent = persistent_size if persistent_size > 0 else self.PERSISTENT_SIZE
        self._persistent = ctypes.create_string_buffer(actual_persistent)
        self._persistent_size = actual_persistent
        self._buffers.append(self._persistent)
        self.persistent_addr: int = ctypes.addressof(self._persistent)

        # print_buf region (for words that use ``[rel print_buf]``)
        self._print_buf = ctypes.create_string_buffer(self.PRINT_BUF_SIZE)
        self._buffers.append(self._print_buf)
        self.print_buf_addr: int = ctypes.addressof(self._print_buf)

        # Data section – contiguous slab for string literals so that
        # data_start..data_end consistently brackets all of them.
        self._data_section = ctypes.create_string_buffer(self.DATA_SECTION_SIZE)
        self._buffers.append(self._data_section)
        self.data_start: int = ctypes.addressof(self._data_section)
        self.data_end: int = self.data_start + self.DATA_SECTION_SIZE
        self._data_offset: int = 0

        # sys_argc / sys_argv – populated by invoke()
        self._sys_argc = ctypes.c_int64(0)
        self._buffers.append(self._sys_argc)
        self.sys_argc_addr: int = ctypes.addressof(self._sys_argc)

        self._sys_argv_ptrs: Optional[ctypes.Array[Any]] = None
        self._sys_argv = ctypes.c_int64(0)  # qword holding pointer to argv array
        self._buffers.append(self._sys_argv)
        self.sys_argv_addr: int = ctypes.addressof(self._sys_argv)

    # -- argv helpers ------------------------------------------------------

    def setup_argv(self, args: List[str]) -> None:
        """Populate sys_argc / sys_argv from *args*."""
        self._sys_argc.value = len(args)
        # Build null-terminated C string array
        argv_bufs: List[Any] = []
        for arg in args:
            encoded = arg.encode("utf-8") + b"\x00"
            buf = ctypes.create_string_buffer(encoded, len(encoded))
            self._buffers.append(buf)
            argv_bufs.append(buf)
        # pointer array (+ NULL sentinel)
        arr_type = ctypes.c_int64 * (len(args) + 1)
        self._sys_argv_ptrs = arr_type()
        for i, buf in enumerate(argv_bufs):
            self._sys_argv_ptrs[i] = ctypes.addressof(buf)
        self._sys_argv_ptrs[len(args)] = 0
        self._buffers.append(self._sys_argv_ptrs)
        self._sys_argv.value = ctypes.addressof(self._sys_argv_ptrs)

    # -- allocation --------------------------------------------------------

    def allocate(self, size: int) -> int:
        """Allocate a zero-filled region, return its real address.
        Adds padding to mimic real mmap which always gives full pages."""
        if size <= 0:
            size = 1
        buf = ctypes.create_string_buffer(size + 16)  # padding for null terminators
        addr = ctypes.addressof(buf)
        self._buffers.append(buf)
        return addr

    def store_string(self, s: str) -> Tuple[int, int]:
        """Store a UTF-8 string in the data section slab.  Returns ``(addr, length)``.
        Caches immutable string literals to avoid redundant allocations."""
        cached = self._string_cache.get(s)
        if cached is not None:
            return cached
        encoded = s.encode("utf-8")
        needed = len(encoded) + 1  # null terminator
        aligned = (needed + 7) & ~7  # 8-byte align
        if self._data_offset + aligned > self.DATA_SECTION_SIZE:
            raise RuntimeError("CT data section overflow")
        addr = self.data_start + self._data_offset
        ctypes.memmove(addr, encoded, len(encoded))
        ctypes.c_uint8.from_address(addr + len(encoded)).value = 0  # null terminator
        self._data_offset += aligned
        result = (addr, len(encoded))
        self._string_cache[s] = result
        return result

    # -- low-level access --------------------------------------------------

    @staticmethod
    def read_byte(addr: int) -> int:
        return ctypes.c_uint8.from_address(addr).value

    @staticmethod
    def write_byte(addr: int, value: int) -> None:
        ctypes.c_uint8.from_address(addr).value = value & 0xFF

    @staticmethod
    def read_qword(addr: int) -> int:
        return ctypes.c_int64.from_address(addr).value

    @staticmethod
    def write_qword(addr: int, value: int) -> None:
        ctypes.c_int64.from_address(addr).value = _to_i64(value)

    @staticmethod
    def read_bytes(addr: int, length: int) -> bytes:
        return ctypes.string_at(addr, length)


def _match_token_kind(lexeme: str, constraint: str) -> bool:
    """Whether a Token's lexeme belongs to a lexical pattern constraint."""
    if constraint == "any":
        return True
    if constraint == "ident":
        return _is_l2_identifier(lexeme)
    is_int = _parse_l2_int(lexeme) is not None and lexeme.strip() == lexeme
    is_float = not is_int and _DEFINITION_FLOAT_RE.fullmatch(lexeme) is not None
    is_string = len(lexeme) >= 2 and lexeme[0] == '"' and lexeme[-1] == '"'
    is_char = len(lexeme) >= 3 and lexeme[0] == "'" and lexeme[-1] == "'"
    if constraint == "int":
        return is_int
    if constraint == "float":
        return is_float
    if constraint == "number":
        return is_int or is_float
    if constraint == "string":
        return is_string
    if constraint == "char":
        return is_char
    if constraint == "literal":
        return is_int or is_float or is_string or is_char
    return False


class _MatchInput:
    """Input values for matching, peeked from the parser on demand (a
    repetition group can match any number of them)."""

    __slots__ = ("parser", "values", "next_index", "exhausted")

    def __init__(self, parser: Any, start: int) -> None:
        self.parser = parser
        self.values: List[Tuple[Any, int]] = []
        self.next_index = start
        self.exhausted = False

    def get(self, index: int) -> Optional[Tuple[Any, int]]:
        while index >= len(self.values) and not self.exhausted:
            more = self.parser._peek_input_values(self.next_index, max(16, index + 1 - len(self.values)))
            if not more:
                self.exhausted = True
                break
            self.values.extend(more)
            self.next_index = more[-1][1]
        return self.values[index] if index < len(self.values) else None


def _match_element_value(element: Tuple[Any, ...], value: Any, bindings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    kind = element[0]
    if kind == "lit":
        return bindings if isinstance(value, Token) and value.lexeme == element[1] else None
    if kind == "wild":
        return bindings
    name, constraint = element[1], element[2]
    if constraint is not None:
        if constraint == "syntax":
            if not isinstance(value, Syntax):
                return None
        elif constraint != "any" and (not isinstance(value, Token) or not _match_token_kind(value.lexeme, constraint)):
            return None
    if name in bindings:
        return bindings if _ct_values_equal(bindings[name], value) else None
    bound = dict(bindings)
    bound[name] = value
    return bound


def _match_sequence(elements: Sequence[Tuple[Any, ...]], ei: int, vi: int, source: _MatchInput,
                    bindings: Dict[str, Any]) -> Optional[Tuple[int, Dict[str, Any]]]:
    """Match elements[ei:] from value vi; (values consumed up to, bindings).
    A repetition group is greedy and gives back iterations when the rest of
    the pattern needs them; each name inside it binds to a list."""
    if ei == len(elements):
        return vi, bindings
    element = elements[ei]
    if element[0] == "rep":
        _, inner, separator, minimum = element
        iterations: List[Tuple[int, Dict[str, Any]]] = []
        position = vi
        while True:
            start = position
            if iterations and separator is not None:
                entry = source.get(start)
                if entry is None or not isinstance(entry[0], Token) or entry[0].lexeme != separator:
                    break
                start += 1
            result = _match_sequence(inner, 0, start, source, {})
            if result is None or result[0] == start:
                break
            iterations.append(result)
            position = result[0]
        names: List[str] = []
        _match_element_names(inner, names)
        for count in range(len(iterations), minimum - 1, -1):
            combined = dict(bindings)
            if any(name in combined for name in names):
                return None
            for name in names:
                combined[name] = [iteration[1].get(name) for iteration in iterations[:count]]
            end = iterations[count - 1][0] if count else vi
            result = _match_sequence(elements, ei + 1, end, source, combined)
            if result is not None:
                return result
        return None
    entry = source.get(vi)
    if entry is None:
        return None
    bound = _match_element_value(element, entry[0], bindings)
    if bound is None:
        return None
    return _match_sequence(elements, ei + 1, vi + 1, source, bound)


def _match_values(pattern: _MatchPattern, values: List[Tuple[Any, int]]) -> Optional[Dict[str, Any]]:
    """Bindings when `pattern` matches the first of `values`, else None (a
    repeated binding must equal its first value)."""
    source = _MatchInput(None, 0)
    source.values = list(values)
    source.exhausted = True
    result = _match_sequence(pattern.elements, 0, 0, source, {})
    return None if result is None else result[1]


class CompileTimeVM:
    NATIVE_STACK_SIZE = 8 * 1024 * 1024  # 8 MB per native stack

    def __init__(self, parser: Parser) -> None:
        self.parser = parser
        self.dictionary = parser.dictionary
        # Bound methods _execute_nodes uses, built on its first call.
        self._exec_bound: Optional[Tuple[Any, ...]] = None
        # Reused native stacks of _run_asm_on_ints (built on first use).
        self._asm_int_buffers: Optional[Tuple[Any, ...]] = None
        self.stack: List[Any] = []
        self.return_stack: List[Any] = []
        self.loop_stack: List[Dict[str, Any]] = []
        self._unquote_depths: List[int] = []  # `$( … )` stack depth checks
        self._unquote_values: List[Any] = []  # `$( … )` values awaiting their quotation
        # Values of the lexical `$name` bindings of the executing macro body
        # or match clause (None when no binding scope is active).
        self.binding_env: Optional[Dict[str, Any]] = None
        self._binding_stack: List[Optional[Dict[str, Any]]] = []
        self._handles = _CTHandleTable()
        self.call_stack: List[str] = []
        # Runtime-faithful execution state — lazily allocated on first use
        self._memory: Optional[CTMemory] = None
        self.runtime_mode: bool = False
        self._list_capture_stack: List[Any] = []  # for list_begin/list_end (int depth or native r12 addr)
        self._ct_executed: Set[str] = set()  # words already executed at CT
        # Native stack state (used only in runtime_mode)
        self.r12: int = 0  # data stack pointer (grows downward)
        self.r13: int = 0  # return stack pointer (grows downward)
        self._native_data_stack: Optional[Any] = None   # ctypes buffer
        self._native_data_top: int = 0
        # REPL persistent state
        self._repl_initialized: bool = False
        self._repl_libs: List[str] = []
        self._native_return_stack: Optional[Any] = None  # ctypes buffer
        self._native_return_top: int = 0
        # JIT cache: word name -> ctypes callable
        self._jit_cache: Dict[str, Any] = {}
        self._jit_code_pages: List[Any] = []  # keep mmap pages alive
        # Pre-allocated output structs for JIT calls (lazily allocated)
        self._jit_out2: Optional[Any] = None
        self._jit_out2_addr: int = 0
        self._jit_out4: Optional[Any] = None
        self._jit_out4_addr: int = 0
        # Runtime mmap/munmap/mremap leak tracker state (used by --leak-check)
        self._mmap_leak_check_enabled: bool = False
        self._mmap_live_regions: Dict[int, int] = {}
        # Mappings the running program made (start -> length), always kept:
        # munmap/mremap from compile-time execution are limited to these.
        self._owned_maps: Dict[int, int] = {}
        self._mmap_anomaly_count: int = 0
        self._mmap_call_count: int = 0
        self._munmap_call_count: int = 0
        self._mremap_call_count: int = 0
        # BSS symbol table for JIT patching
        self._bss_symbols: Dict[str, int] = {}
        # dlopen handles for C extern support
        self._dl_handles: List[Any] = []  # ctypes.CDLL handles
        self._dl_func_cache: Dict[str, Any] = {}  # name -> ctypes callable
        self._dl_load_errors: Dict[str, str] = {}
        # Native code pointers returned by libl2 factories
        # (l2_compile / l2_jit_from_asm).  `call` on one of these
        # dispatches through l2_invoke_trampoline so the target sees
        # the CT VM's `r12` in the actual r12 register.
        self._libl2_trampolines: Set[int] = set()
        self._ct_libs: List[str] = []  # library names from -l flags
        self._ct_source_embed_text: Optional[str] = None
        self._ct_source_embed_buf: Optional[Any] = None
        self._ctypes_struct_cache: Dict[str, Any] = {}
        self._in_fork_child: bool = False
        self.current_location: Optional[SourceLocation] = None
        # Coroutine JIT support: save buffer for callee-saved regs (lazily allocated)
        self._jit_save_buf: Optional[Any] = None
        self._jit_save_buf_addr: int = 0

    def set_runtime_embedded_source(self, source_text: Optional[str]) -> None:
        """Set expanded source text exposed to runtime eval bridges during ct-run-main."""
        self._ct_source_embed_text = source_text if source_text else None
        self._ct_source_embed_buf = None

    def _notify_eval_runtime_bridges(self) -> None:
        """Push stack/source bridge state into loaded eval runtime libraries if available."""
        if not self.runtime_mode or not self._dl_handles:
            return

        stack_top = int(self._native_data_top)
        if stack_top:
            for handle in self._dl_handles:
                setter = getattr(handle, "l2_set_eval_stack_top", None)
                if setter is None:
                    continue
                try:
                    setter.argtypes = [ctypes.c_uint64]
                    setter.restype = None
                    setter(stack_top)
                except Exception:
                    continue

        source_text = self._ct_source_embed_text
        if not source_text:
            return
        source_bytes = source_text.encode("utf-8", errors="replace")
        if not source_bytes:
            return

        # Keep the backing buffer alive for the invocation lifetime.
        self._ct_source_embed_buf = ctypes.create_string_buffer(source_bytes + b"\0")
        source_addr = ctypes.addressof(self._ct_source_embed_buf)
        source_len = len(source_bytes)
        for handle in self._dl_handles:
            setter = getattr(handle, "l2_set_embedded_source", None)
            if setter is None:
                continue
            try:
                setter.argtypes = [ctypes.c_void_p, ctypes.c_longlong]
                setter.restype = None
                setter(source_addr, source_len)
            except Exception:
                continue

    @property
    def memory(self) -> CTMemory:
        if self._memory is None:
            self._memory = CTMemory()
        return self._memory

    @memory.setter
    def memory(self, value: CTMemory) -> None:
        self._memory = value

    def _ensure_jit_out(self) -> None:
        if self._jit_out2 is None:
            import ctypes as _ctypes
            globals().setdefault('ctypes', _ctypes)
            self._jit_out2 = (_ctypes.c_int64 * 2)()
            self._jit_out2_addr = _ctypes.addressof(self._jit_out2)
            # Syscall path currently writes up to 10 qwords.
            self._jit_out4 = (_ctypes.c_int64 * 10)()
            self._jit_out4_addr = _ctypes.addressof(self._jit_out4)

    def _ensure_jit_save_buf(self) -> None:
        if self._jit_save_buf is None:
            self._jit_save_buf = (ctypes.c_int64 * 8)()
            self._jit_save_buf_addr = ctypes.addressof(self._jit_save_buf)

    @staticmethod
    def _u64(value: int) -> int:
        return int(value) & 0xFFFFFFFFFFFFFFFF

    def _reset_mmap_leak_tracker(self, enabled: bool) -> None:
        self._mmap_leak_check_enabled = bool(enabled)
        self._mmap_live_regions = {}
        self._mmap_anomaly_count = 0
        self._mmap_call_count = 0
        self._munmap_call_count = 0
        self._mremap_call_count = 0

    def _owns_mapping(self, addr: int, length: int) -> bool:
        """Whether [addr, addr+length) lies in a mapping this program made."""
        addr &= _I64_MASK_
        if length <= 0:
            return False
        for start, size in self._owned_maps.items():
            end = start + ((size + 4095) & ~4095)
            if start <= addr and addr + length <= end:
                return True
        return False

    def _release_mapping(self, addr: int, length: int) -> None:
        addr &= _I64_MASK_
        size = self._owned_maps.get(addr)
        if size is not None and length >= size:
            del self._owned_maps[addr]

    def _track_syscall_mmap(self, addr: int, length: int, result: int) -> None:
        if not self._mmap_leak_check_enabled:
            return
        self._mmap_call_count += 1
        # Linux syscall ABI returns negative errno on failure.
        if int(result) < 0:
            return
        size = int(length)
        if size <= 0:
            return
        key = self._u64(addr)
        if key in self._mmap_live_regions:
            self._mmap_anomaly_count += 1
        self._mmap_live_regions[key] = size

    def _track_syscall_munmap(self, addr: int, length: int, result: int) -> None:
        if not self._mmap_leak_check_enabled:
            return
        self._munmap_call_count += 1
        # Only successful munmap operations should release accounting entries.
        if int(result) != 0:
            return
        size = int(length)
        if size <= 0:
            return
        key = self._u64(addr)
        existing = self._mmap_live_regions.get(key)
        if existing is None:
            self._mmap_anomaly_count += 1
            return
        if size == existing:
            del self._mmap_live_regions[key]
            return
        if 0 < size < existing:
            # Partial unmap from the mapping start: keep the remaining suffix.
            del self._mmap_live_regions[key]
            self._mmap_live_regions[self._u64(key + size)] = existing - size
            return
        # munmap size larger than mapping is suspicious; drop the entry and flag it.
        del self._mmap_live_regions[key]
        self._mmap_anomaly_count += 1

    def _track_syscall_mremap(self, old_addr: int, old_size: int, new_size: int, result: int) -> None:
        if not self._mmap_leak_check_enabled:
            return
        self._mremap_call_count += 1
        # Linux syscall ABI returns negative errno on failure.
        if int(result) < 0:
            return

        old_len = int(old_size)
        new_len = int(new_size)
        if old_len <= 0 or new_len <= 0:
            self._mmap_anomaly_count += 1
            return

        old_key = self._u64(old_addr)
        new_key = self._u64(result)
        existing = self._mmap_live_regions.get(old_key)
        if existing is None:
            self._mmap_anomaly_count += 1
        else:
            if int(existing) != old_len:
                self._mmap_anomaly_count += 1
            del self._mmap_live_regions[old_key]

        if new_key in self._mmap_live_regions and new_key != old_key:
            self._mmap_anomaly_count += 1
        self._mmap_live_regions[new_key] = new_len

    def mmap_leak_check_report(self) -> Tuple[bool, str]:
        leaked_regions = len(self._mmap_live_regions)
        leaked_bytes = sum(max(0, int(size)) for size in self._mmap_live_regions.values())
        anomalies = int(self._mmap_anomaly_count)
        has_issues = leaked_regions > 0 or anomalies > 0
        status = "failed" if has_issues else "passed"
        summary = (
            f"[ctvm] mmap leak check {status}: "
            f"leaked_regions={leaked_regions} leaked_bytes={leaked_bytes} "
            f"mmap_calls={int(self._mmap_call_count)} munmap_calls={int(self._munmap_call_count)} "
            f"mremap_calls={int(self._mremap_call_count)} "
            f"anomalies={anomalies}"
        )
        return has_issues, summary

    @staticmethod
    def _parse_data_scalar(text: str) -> Optional[int]:
        token = text.strip()
        if not token:
            return None
        if token == "?":
            return 0
        try:
            return int(token, 0)
        except ValueError:
            pass
        normalized = token.replace("_", "")
        sign = 1
        body = normalized
        if body.startswith(("+", "-")):
            if body[0] == "-":
                sign = -1
            body = body[1:]
        lower = body.lower()
        try:
            if lower.endswith("h") and re.match(r"^[0-9a-f]+h$", lower):
                return sign * int(lower[:-1], 16)
            if lower.endswith("b") and re.match(r"^[01]+b$", lower):
                return sign * int(lower[:-1], 2)
            if lower.endswith(("o", "q")) and re.match(r"^[0-7]+[oq]$", lower):
                return sign * int(lower[:-1], 8)
            if lower.endswith("d") and re.match(r"^[0-9]+d$", lower):
                return sign * int(lower[:-1], 10)
        except ValueError:
            pass
        if len(token) >= 2 and token[0] == token[-1] and token[0] in ('"', "'"):
            try:
                literal = ast.literal_eval(token)
            except Exception:
                return None
            if isinstance(literal, int):
                return int(literal)
            if isinstance(literal, str) and len(literal) == 1:
                return ord(literal)
            if isinstance(literal, (bytes, bytearray)) and len(literal) == 1:
                return int(literal[0])
        return None

    @staticmethod
    def _split_data_operands(text: str) -> List[str]:
        items: List[str] = []
        buf: List[str] = []
        quote: Optional[str] = None
        escaped = False
        depth = 0

        for ch in text:
            if quote is not None:
                buf.append(ch)
                if escaped:
                    escaped = False
                elif ch == "\\":
                    escaped = True
                elif ch == quote:
                    quote = None
                continue

            if ch in ('"', "'"):
                quote = ch
                buf.append(ch)
                continue

            if ch == "(":
                depth += 1
                buf.append(ch)
                continue
            if ch == ")":
                if depth > 0:
                    depth -= 1
                buf.append(ch)
                continue

            if ch == "," and depth == 0:
                item = "".join(buf).strip()
                if item:
                    items.append(item)
                buf = []
                continue

            buf.append(ch)

        tail = "".join(buf).strip()
        if tail:
            items.append(tail)
        return items

    @staticmethod
    def _consume_data_labels(text: str) -> Tuple[List[str], str]:
        labels: List[str] = []
        rest = text.strip()
        while rest:
            match = re.match(r"^([A-Za-z0-9_.$@]+)\s*:\s*(.*)$", rest)
            if match is None:
                break
            labels.append(match.group(1))
            rest = match.group(2).strip()
        return labels, rest

    def _parse_data_atom_values(self, unit: int, token: str) -> List[int]:
        item = token.strip()
        if not item:
            return [0]

        dup_match = re.match(r"^(.*?)\bdup\s*\((.*)\)\s*$", item, re.IGNORECASE)
        if dup_match is not None:
            parsed_count = self._parse_data_scalar(dup_match.group(1).strip())
            count = int(parsed_count) if parsed_count is not None else 1
            if count <= 0:
                return []
            inner_values = self._parse_data_values(unit, dup_match.group(2).strip())
            return inner_values * count

        if item == "?":
            return [0]

        if len(item) >= 2 and item[0] == item[-1] and item[0] in ('"', "'"):
            try:
                literal = ast.literal_eval(item)
            except Exception:
                literal = None
            if isinstance(literal, str):
                if unit == 1:
                    blob = literal.encode("utf-8", errors="ignore")
                    return [int(b) for b in blob] if blob else [0]
                expanded = [ord(ch) for ch in literal]
                return expanded if expanded else [0]
            if isinstance(literal, (bytes, bytearray)):
                expanded = [int(b) for b in literal]
                return expanded if expanded else [0]
            if isinstance(literal, int):
                return [int(literal)]

        parsed_scalar = self._parse_data_scalar(item)
        if parsed_scalar is not None:
            return [int(parsed_scalar)]
        return [0]

    def _parse_data_values(self, unit: int, operands: str) -> List[int]:
        parts = self._split_data_operands(operands)
        if not parts:
            return [0]
        values: List[int] = []
        for part in parts:
            values.extend(self._parse_data_atom_values(unit, part))
        return values if values else [0]

    def _materialize_custom_data_symbols(self) -> None:
        """Populate the runtime symbol map from CT .data fragments."""
        if self.memory is None:
            return
        if not self.parser.output_data:
            return
        data_lines = "\n".join(self.parser.output_data).splitlines()

        unit_sizes = {
            "db": 1,
            "dw": 2,
            "dd": 4,
            "dq": 8,
            "dt": 10,
            "do": 16,
            "dy": 32,
            "dz": 64,
            "resb": 1,
            "resw": 2,
            "resd": 4,
            "resq": 8,
            "rest": 10,
            "reso": 16,
            "resy": 32,
            "resz": 64,
        }
        pending_labels: List[str] = []

        for raw_line in data_lines:
            line = raw_line.split(";", 1)[0].strip()
            if not line:
                continue

            labels, remainder = self._consume_data_labels(line)
            for label_name in labels:
                if label_name not in pending_labels:
                    pending_labels.append(label_name)
            if not remainder:
                continue

            if not pending_labels:
                continue

            parts = remainder.split(None, 1)
            directive = parts[0].lower()
            operands = parts[1].strip() if len(parts) > 1 else ""
            repeat_count = 1

            while directive == "times":
                time_parts = operands.split(None, 2)
                if len(time_parts) < 2:
                    break
                parsed_repeat = self._parse_data_scalar(time_parts[0])
                step_repeat = int(parsed_repeat) if parsed_repeat is not None else 1
                if step_repeat < 0:
                    step_repeat = 0
                repeat_count *= step_repeat
                directive = time_parts[1].lower()
                operands = time_parts[2].strip() if len(time_parts) >= 3 else ""

            target_labels = [name for name in pending_labels if name not in self._bss_symbols]
            pending_labels = []
            if not target_labels:
                continue

            if directive == "equ":
                equ_parts = self._split_data_operands(operands)
                equ_token = equ_parts[0] if equ_parts else "0"
                equ_value = self._parse_data_scalar(equ_token)
                value = int(equ_value) if equ_value is not None else 0
                for name in target_labels:
                    self._bss_symbols[name] = value
                continue

            unit = unit_sizes.get(directive)
            if unit is None:
                # Unknown declaration style: still provide stable address labels
                # so [rel label] references can be resolved by the JIT.
                addr = self.memory.allocate(8)
                for name in target_labels:
                    self._bss_symbols[name] = addr
                continue

            values: List[int]
            if directive.startswith("res"):
                count_parts = self._split_data_operands(operands)
                count_token = count_parts[0] if count_parts else "1"
                parsed_count = self._parse_data_scalar(count_token)
                count = int(parsed_count) if parsed_count is not None else 1
                if count < 0:
                    count = 0
                total = count * max(0, repeat_count)
                values = [0] * max(0, total)
            else:
                base_values = self._parse_data_values(unit, operands)
                rep = max(0, repeat_count)
                values = base_values * rep if rep > 0 else []

            byte_count = unit * len(values)
            addr = self.memory.allocate(byte_count if byte_count > 0 else unit)
            for name in target_labels:
                self._bss_symbols[name] = addr

            if unit == 1:
                for idx, value in enumerate(values):
                    ctypes.c_uint8.from_address(addr + idx).value = int(value) & 0xFF
            elif unit == 2:
                for idx, value in enumerate(values):
                    ctypes.c_uint16.from_address(addr + idx * 2).value = int(value) & 0xFFFF
            elif unit == 4:
                for idx, value in enumerate(values):
                    ctypes.c_uint32.from_address(addr + idx * 4).value = int(value) & 0xFFFFFFFF
            elif unit == 8:
                for idx, value in enumerate(values):
                    ctypes.c_int64.from_address(addr + idx * 8).value = _to_i64(int(value))
            else:
                mask = (1 << (unit * 8)) - 1
                for idx, value in enumerate(values):
                    raw = int(value) & mask
                    blob = raw.to_bytes(unit, byteorder="little", signed=False)
                    ctypes.memmove(addr + idx * unit, blob, unit)

        if pending_labels:
            unresolved = [name for name in pending_labels if name not in self._bss_symbols]
            if unresolved:
                addr = self.memory.allocate(1)
                for name in unresolved:
                    self._bss_symbols[name] = addr

    @staticmethod
    def _is_coroutine_asm(body: str) -> bool:
        """Detect asm words that manipulate the x86 return stack (coroutine patterns).

        Heuristic: if the body pops rsi/rdi before any label (capturing the
        return address), it's a coroutine word.
        """
        for raw_line in body.splitlines():
            line = raw_line.strip()
            if not line or line.startswith(";"):
                continue
            if _RE_LABEL_PAT.match(line):
                break
            if line.startswith("pop "):
                reg = line.split()[1].rstrip(",")
                if reg in ("rsi", "rdi"):
                    return True
        return False

    @staticmethod
    def _pick_rel_patch_scratch_register(line: str) -> str:
        for reg in ("r11", "r10", "r9", "r8", "rdx", "rcx", "rbx", "rax"):
            if re.search(rf'(?<![A-Za-z0-9_]){reg}(?![A-Za-z0-9_])', line) is None:
                return reg
        return "r11"

    def _resolve_rel_symbol_expression(self, line: str, symbols: Dict[str, int]) -> Optional[str]:
        m = _RE_REL_TO_RIP_PAT.search(line)
        if m is None:
            return None
        expr = m.group(1).strip()
        sym_match = re.match(r"([A-Za-z0-9_.$@]+)(.*)$", expr)
        if sym_match is None:
            return None
        sym = sym_match.group(1)
        if sym not in symbols:
            return None
        suffix = sym_match.group(2)
        return f"{symbols[sym]}{suffix}"

    def _emit_rel_symbol_patch(self, out_lines: List[str], line: str, addr_expr: Any, *, indent: str = "    ") -> None:
        scratch = self._pick_rel_patch_scratch_register(line)
        out_lines.append(f"{indent}push {scratch}")
        out_lines.append(f"{indent}mov {scratch}, {addr_expr}")
        out_lines.append(f"{indent}{_RE_REL_TO_RIP_PAT.sub(f'[{scratch}]', line)}")
        out_lines.append(f"{indent}pop {scratch}")

    def _emit_abs_mem_literal_patch(self, out_lines: List[str], line: str, addr_expr: str, *, indent: str = "    ") -> None:
        scratch = self._pick_rel_patch_scratch_register(line)
        out_lines.append(f"{indent}push {scratch}")
        out_lines.append(f"{indent}mov {scratch}, {addr_expr}")
        out_lines.append(f"{indent}{_RE_ABS_MEM_LITERAL_PAT.sub(f'[{scratch}]', line, count=1)}")
        out_lines.append(f"{indent}pop {scratch}")

    def _patch_direct_word_call(self, out_lines: List[str], line: str, current_word: str, local_labels: Set[str]) -> bool:
        m = re.match(r"^(call|jmp)\s+([A-Za-z_.$][A-Za-z0-9_.$@]*)$", line)
        if m is None:
            return False
        op, target = m.group(1), m.group(2)
        if target in local_labels or target == current_word:
            return False
        target_word = self.dictionary.lookup(target)
        if target_word is None or target_word.definition is None:
            return False
        target_addr = self._compile_raw_jit(target_word)
        out_lines.append(f"    mov rax, {target_addr}")
        out_lines.append(f"    {op} rax")
        return True

    def reset(self) -> None:
        self.stack.clear()
        self.return_stack.clear()
        self.loop_stack.clear()
        self._handles.clear()
        self.call_stack.clear()
        self._list_capture_stack.clear()
        self.r12 = 0
        self.r13 = 0
        self.current_location = None
        self._repl_initialized = False

    def invoke(
        self,
        word: Word,
        *,
        runtime_mode: bool = False,
        libs: Optional[List[str]] = None,
        mmap_leak_check: bool = False,
        argv: Optional[Sequence[str]] = None,
    ) -> int:
        self.reset()
        self._ensure_jit_out()
        prev_mode = self.runtime_mode
        self.runtime_mode = runtime_mode
        exit_code = 0
        if runtime_mode:
            self._reset_mmap_leak_tracker(mmap_leak_check)
            # Determine persistent size from BSS overrides if available.
            persistent_size = _ct_persistent_size(self.parser)
            self.memory = CTMemory(persistent_size)  # fresh memory per invocation
            runtime_argv = list(argv) if argv is not None else list(sys.argv)
            self.memory.setup_argv(runtime_argv)

            # Allocate native stacks
            self._native_data_stack = ctypes.create_string_buffer(self.NATIVE_STACK_SIZE)
            self._native_data_top = ctypes.addressof(self._native_data_stack) + self.NATIVE_STACK_SIZE
            self.r12 = self._native_data_top  # empty, grows downward

            self._native_return_stack = ctypes.create_string_buffer(self.NATIVE_STACK_SIZE)
            self._native_return_top = ctypes.addressof(self._native_return_stack) + self.NATIVE_STACK_SIZE
            self.r13 = self._native_return_top  # empty, grows downward

            # Runtime BSS slots used by list literal helpers and heap checks.
            list_capture_sp_addr = self.memory.allocate(8)
            list_capture_tmp_addr = self.memory.allocate(8)
            list_capture_stack_addr = self.memory.allocate(8 * 1024)
            CTMemory.write_qword(list_capture_sp_addr, 0)
            CTMemory.write_qword(list_capture_tmp_addr, 0)

            # BSS symbol table for JIT [rel SYMBOL] patching
            self._bss_symbols = {
                "dstack": ctypes.addressof(self._native_data_stack),
                "dstack_top": self._native_data_top,
                "rstack": ctypes.addressof(self._native_return_stack),
                "rstack_top": self._native_return_top,
                "data_start": self.memory.data_start,
                "data_end": self.memory.data_start + self.memory._data_offset if self.memory._data_offset else self.memory.data_end,
                "print_buf": self.memory.print_buf_addr,
                "print_buf_end": self.memory.print_buf_addr + CTMemory.PRINT_BUF_SIZE,
                "persistent": self.memory.persistent_addr,
                "persistent_end": self.memory.persistent_addr + self.memory._persistent_size,
                "sys_argc": self.memory.sys_argc_addr,
                "sys_argv": self.memory.sys_argv_addr,
                "list_capture_sp": list_capture_sp_addr,
                "list_capture_tmp": list_capture_tmp_addr,
                "list_capture_stack": list_capture_stack_addr,
            }
            self._materialize_custom_data_symbols()
            self._in_fork_child = False

            # JIT cache is per-invocation (addresses change)
            self._jit_cache = {}
            self._jit_code_pages = []

            # dlopen libraries for C extern support
            self._dl_handles = []
            self._dl_func_cache = {}
            self._dl_load_errors = {}
            self._libl2_trampolines = set()
            all_libs = []
            dstack_shim = self._ct_runtime_symbol_shim("dstack_top", self._native_data_top)
            if dstack_shim is not None:
                all_libs.append(dstack_shim)
            all_libs.extend(self._ct_libs)
            if libs:
                for lib in libs:
                    if lib not in all_libs:
                        all_libs.append(lib)
            for lib_name in all_libs:
                self._dlopen(lib_name)
            self._notify_eval_runtime_bridges()

            # Deep word chains need extra Python stack depth.
            old_limit = sys.getrecursionlimit()
            if old_limit < 10000:
                sys.setrecursionlimit(10000)
        else:
            self._reset_mmap_leak_tracker(False)
        try:
            self._call_word(word)
        except _CTVMExit as exc:
            # Mirror process-exit semantics for ct-run-main/script mode.
            exit_code = int(getattr(exc, "code", 0)) & 0xFF
        finally:
            self.runtime_mode = prev_mode
            # Clear JIT cache; code pages are libc mmap'd and we intentionally
            # leak them — the OS reclaims them at process exit.
            self._jit_cache.clear()
            self._jit_code_pages.clear()
            self._dl_func_cache.clear()
            self._dl_handles.clear()
            self._dl_load_errors.clear()
            self._libl2_trampolines.clear()
        return exit_code

    def invoke_with_args(self, word: Word, args: Sequence[Any]) -> None:
        self.reset()
        for value in args:
            self.push(value)
        self._call_word(word)

    def invoke_repl(self, word: Word, *, libs: Optional[List[str]] = None, argv: Optional[Sequence[str]] = None) -> None:
        """Execute *word* in runtime mode, preserving stack/memory across calls.

        On the first call (or after ``reset()``), allocates native stacks and
        memory.  Subsequent calls reuse the existing state so values left on
        the data stack persist between REPL evaluations.
        """
        self._ensure_jit_out()
        prev_mode = self.runtime_mode
        self.runtime_mode = True

        if not self._repl_initialized:
            persistent_size = _ct_persistent_size(self.parser)
            self.memory = CTMemory(persistent_size)
            runtime_argv = list(argv) if argv is not None else list(sys.argv)
            self.memory.setup_argv(runtime_argv)

            self._native_data_stack = ctypes.create_string_buffer(self.NATIVE_STACK_SIZE)
            self._native_data_top = ctypes.addressof(self._native_data_stack) + self.NATIVE_STACK_SIZE
            self.r12 = self._native_data_top

            self._native_return_stack = ctypes.create_string_buffer(self.NATIVE_STACK_SIZE)
            self._native_return_top = ctypes.addressof(self._native_return_stack) + self.NATIVE_STACK_SIZE
            self.r13 = self._native_return_top

            list_capture_sp_addr = self.memory.allocate(8)
            list_capture_tmp_addr = self.memory.allocate(8)
            list_capture_stack_addr = self.memory.allocate(8 * 1024)
            CTMemory.write_qword(list_capture_sp_addr, 0)
            CTMemory.write_qword(list_capture_tmp_addr, 0)

            self._bss_symbols = {
                "dstack": ctypes.addressof(self._native_data_stack),
                "dstack_top": self._native_data_top,
                "rstack": ctypes.addressof(self._native_return_stack),
                "rstack_top": self._native_return_top,
                "data_start": self.memory.data_start,
                "data_end": self.memory.data_start + self.memory._data_offset if self.memory._data_offset else self.memory.data_end,
                "print_buf": self.memory.print_buf_addr,
                "print_buf_end": self.memory.print_buf_addr + CTMemory.PRINT_BUF_SIZE,
                "persistent": self.memory.persistent_addr,
                "persistent_end": self.memory.persistent_addr + self.memory._persistent_size,
                "sys_argc": self.memory.sys_argc_addr,
                "sys_argv": self.memory.sys_argv_addr,
                "list_capture_sp": list_capture_sp_addr,
                "list_capture_tmp": list_capture_tmp_addr,
                "list_capture_stack": list_capture_stack_addr,
            }
            self._materialize_custom_data_symbols()
            self._jit_cache = {}
            self._jit_code_pages = []
            self._dl_handles = []
            self._dl_func_cache = {}
            self._libl2_trampolines = set()
            self._in_fork_child = False
            all_libs = list(self._ct_libs)
            if libs:
                for lib in libs:
                    if lib not in all_libs:
                        all_libs.append(lib)
            for lib_name in all_libs:
                self._dlopen(lib_name)
            self._notify_eval_runtime_bridges()

            old_limit = sys.getrecursionlimit()
            if old_limit < 10000:
                sys.setrecursionlimit(10000)
            self._repl_initialized = True
            self._repl_libs = list(libs or [])
        else:
            # Subsequent call — open any new libraries not yet loaded
            if argv is not None:
                self.memory.setup_argv(list(argv))
            if libs:
                for lib in libs:
                    if lib not in self._repl_libs:
                        self._dlopen(lib)
                        self._repl_libs.append(lib)
            self._notify_eval_runtime_bridges()

        self._materialize_custom_data_symbols()

        # Clear transient state but keep stacks and memory
        self.call_stack.clear()
        self.loop_stack.clear()
        self._list_capture_stack.clear()
        self.current_location = None
        # JIT cache must be cleared because word definitions change between
        # REPL evaluations (re-parsed each time).
        self._jit_cache.clear()

        try:
            self._call_word(word)
        except _CTVMExit:
            pass
        finally:
            self.runtime_mode = prev_mode

    def repl_stack_values(self) -> List[int]:
        """Return current native data stack contents (bottom to top)."""
        if not self._repl_initialized or self.r12 >= self._native_data_top:
            return []
        values = []
        addr = self._native_data_top - 8
        while addr >= self.r12:
            values.append(CTMemory.read_qword(addr))
            addr -= 8
        return values

    def push(self, value: Any) -> None:
        if self.runtime_mode:
            self.r12 -= 8
            if isinstance(value, float):
                bits = _get_struct().unpack("q", _get_struct().pack("d", value))[0]
                CTMemory.write_qword(self.r12, bits)
            else:
                CTMemory.write_qword(self.r12, _to_i64(int(value)))
        else:
            self.stack.append(value)

    def pop(self) -> Any:
        if self.runtime_mode:
            if self.r12 >= self._native_data_top:
                raise ParseError("compile-time stack underflow", code="ct-stack-underflow")
            val = CTMemory.read_qword(self.r12)
            self.r12 += 8
            return val
        if not self.stack:
            raise ParseError("compile-time stack underflow", code="ct-stack-underflow")
        return self.stack.pop()

    def _resolve_handle(self, value: Any) -> Any:
        if isinstance(value, int):
            for delta in (0, -1, 1):
                candidate = value + delta
                if candidate in self._handles.objects:
                    obj = self._handles.objects[candidate]
                    self._handles.objects[value] = obj
                    return obj
            # Occasionally a raw object id can appear on the stack; recover it if we still
            # hold the object reference.
            for obj in self._handles.objects.values():
                if id(obj) == value:
                    self._handles.objects[value] = obj
                    return obj
        return value

    def peek(self) -> Any:
        if self.runtime_mode:
            if self.r12 >= self._native_data_top:
                raise ParseError("compile-time stack underflow", code="ct-stack-underflow")
            return CTMemory.read_qword(self.r12)
        if not self.stack:
            raise ParseError("compile-time stack underflow", code="ct-stack-underflow")
        return self.stack[-1]

    def pop_int(self) -> int:
        if self.runtime_mode:
            return self.pop()  # already returns int from native stack
        value = self.pop()
        if isinstance(value, bool):
            return int(value)
        if not isinstance(value, int):
            raise ParseError(f"expected integer on compile-time stack, got {type(value).__name__}: {value!r}", code="ct-argument-type")
        return value

    # -- return stack helpers (native r13 in runtime_mode) -----------------

    def push_return(self, value: int) -> None:
        if self.runtime_mode:
            self.r13 -= 8
            CTMemory.write_qword(self.r13, _to_i64(value))
        else:
            self.return_stack.append(value)

    def pop_return(self) -> int:
        if self.runtime_mode:
            val = CTMemory.read_qword(self.r13)
            self.r13 += 8
            return val
        return self.return_stack.pop()

    def peek_return(self) -> int:
        if self.runtime_mode:
            return CTMemory.read_qword(self.r13)
        return self.return_stack[-1]

    def poke_return(self, value: int) -> None:
        """Overwrite top of return stack."""
        if self.runtime_mode:
            CTMemory.write_qword(self.r13, _to_i64(value))
        else:
            self.return_stack[-1] = value

    def return_stack_empty(self) -> bool:
        if self.runtime_mode:
            return self.r13 >= self._native_return_top
        return len(self.return_stack) == 0

    # -- native stack depth ------------------------------------------------

    def native_stack_depth(self) -> int:
        """Number of items on data stack (runtime_mode only)."""
        return (self._native_data_top - self.r12) // 8

    def pop_str(self) -> str:
        value = self._resolve_handle(self.pop())
        if not isinstance(value, str):
            raise ParseError("expected string on compile-time stack", code="ct-argument-type")
        return value

    def pop_list(self) -> List[Any]:
        value = self._resolve_handle(self.pop())
        if not isinstance(value, list):
            known = value in self._handles.objects if isinstance(value, int) else False
            handles_size = len(self._handles.objects)
            handle_keys = list(self._handles.objects.keys())
            raise ParseError(
                f"expected list on compile-time stack, got {type(value).__name__} value={value!r} known_handle={known} handles={handles_size}:{handle_keys!r} stack={self.stack!r}",
                code="ct-argument-type",
            )
        return value

    def pop_token(self) -> Token:
        value = self._resolve_handle(self.pop())
        if not isinstance(value, Token):
            raise ParseError("expected token on compile-time stack", code="ct-argument-type")
        return value

    # -- dlopen / C extern support -----------------------------------------

    def _dlopen(self, lib_name: str) -> None:
        """Open a shared library and append to _dl_handles."""
        import ctypes.util
        import ctypes as _ctypes
        # Try as given first (handles absolute paths, "libc.so.6", etc.)
        candidates = [lib_name]
        # If given a static archive (.a), try .so from the same directory
        if lib_name.endswith(".a"):
            so_variant = lib_name[:-2] + ".so"
            candidates.append(so_variant)
        # Try lib<name>.so
        if not lib_name.startswith("lib") and "." not in lib_name:
            candidates.append(f"lib{lib_name}.so")
        # Use ctypes.util.find_library for short names like "m", "c"
        found = ctypes.util.find_library(lib_name)
        if found:
            candidates.append(found)
        last_error: Optional[BaseException] = None
        # Prefer RTLD_NOW|RTLD_GLOBAL if available for stronger linkage semantics
        mode = 0
        if hasattr(_ctypes, "RTLD_NOW") and hasattr(_ctypes, "RTLD_GLOBAL"):
            mode = int(_ctypes.RTLD_NOW) | int(_ctypes.RTLD_GLOBAL)
        elif hasattr(_ctypes, "RTLD_GLOBAL"):
            mode = int(_ctypes.RTLD_GLOBAL)

        for candidate in candidates:
            try:
                handle = _ctypes.CDLL(candidate, mode=mode, use_errno=True)
                self._dl_handles.append(handle)
                # clear any recorded load error for the logical lib_name
                self._dl_load_errors.pop(lib_name, None)
                return
            except OSError as exc:
                last_error = exc
                # record specific candidate failure for debugging
                self._dl_load_errors["%s(%s)" % (lib_name, candidate)] = str(exc)
                continue
        # Not fatal — the library may not be needed at CT
        if last_error is not None:
            self._dl_load_errors[lib_name] = str(last_error)

    def _ct_runtime_symbol_shim(self, symbol_name: str, symbol_value: int) -> Optional[str]:
        """Build a tiny shared object exporting *symbol_name* as an absolute symbol."""
        import shutil
        import subprocess
        import sys

        # Lazy cache on the instance
        cache = getattr(self, "_ct_shim_cache", None)
        if cache is None:
            cache = {}
            setattr(self, "_ct_shim_cache", cache)

        key = (symbol_name, int(symbol_value))
        if key in cache:
            return cache[key]

        cc = shutil.which("cc") or shutil.which("gcc") or shutil.which("clang")
        if cc is None:
            return None

        shim_dir = Path("build") / ".l2cache" / "ct_symbol_shims"
        try:
            shim_dir.mkdir(parents=True, exist_ok=True)
        except OSError:
            return None

        shim_base = shim_dir / f"{symbol_name}_{symbol_value:x}"
        so_path = shim_base.with_suffix(".so")

        # Only support the assembler shim on Linux for now; other platforms are best-effort
        if not sys.platform.startswith("linux"):
            # record a negative cache to avoid retry storms
            cache[key] = None
            return None

        if not so_path.exists():
            asm_path = shim_base.with_suffix(".s")
            tmp_so = shim_base.with_suffix(".so.tmp")
            asm_text = textwrap.dedent(
                f"""
                .text
                .globl {symbol_name}_shim_stub
                .type {symbol_name}_shim_stub, @function
                {symbol_name}_shim_stub:
                    ret

                .globl {symbol_name}
                .set {symbol_name}, 0x{int(symbol_value):x}
                """
            ).lstrip()
            try:
                asm_path.write_text(asm_text, encoding="utf-8")
                # build to a temp file then atomically rename
                proc = subprocess.run(
                    [cc, "-shared", "-fPIC", str(asm_path), "-o", str(tmp_so)],
                    check=False,
                    capture_output=True,
                    text=True,
                )
                if proc.returncode != 0:
                    try:
                        tmp_so.unlink(missing_ok=True)
                    except OSError:
                        pass
                    return None
                try:
                    tmp_so.replace(so_path)
                except Exception:
                    try:
                        tmp_so.unlink(missing_ok=True)
                    except OSError:
                        pass
                    return None
            except Exception:
                try:
                    so_path.unlink(missing_ok=True)
                except OSError:
                    pass
                return None

        cache[key] = str(so_path)
        return cache[key]

    _CTYPE_MAP: Optional[Dict[str, Any]] = None

    @classmethod
    def _get_ctype_map(cls) -> Dict[str, Any]:
        if cls._CTYPE_MAP is None:
            import ctypes
            cls._CTYPE_MAP = {
                "int": ctypes.c_int,
                "int8_t": ctypes.c_int8,
                "uint8_t": ctypes.c_uint8,
                "int16_t": ctypes.c_int16,
                "uint16_t": ctypes.c_uint16,
                "int32_t": ctypes.c_int32,
                "uint32_t": ctypes.c_uint32,
                "long": ctypes.c_long,
                "long long": ctypes.c_longlong,
                "int64_t": ctypes.c_int64,
                "unsigned int": ctypes.c_uint,
                "unsigned long": ctypes.c_ulong,
                "unsigned long long": ctypes.c_ulonglong,
                "uint64_t": ctypes.c_uint64,
                "size_t": ctypes.c_size_t,
                "ssize_t": ctypes.c_ssize_t,
                "char": ctypes.c_char,
                "char*": ctypes.c_void_p,
                "void*": ctypes.c_void_p,
                "double": ctypes.c_double,
                "float": ctypes.c_float,
            }
        return cls._CTYPE_MAP

    def _resolve_struct_ctype(self, struct_name: str) -> Any:
        cached = self._ctypes_struct_cache.get(struct_name)
        if cached is not None:
            return cached
        layout = self.parser.cstruct_layouts.get(struct_name)
        if layout is None:
            raise ParseError(f"unknown cstruct '{struct_name}' used in extern signature", code="extern-type-invalid")
        fields = []
        for field in layout.fields:
            fields.append((field.name, self._resolve_ctype(field.type_name)))
        struct_cls = type(f"CTStruct_{sanitize_label(struct_name)}", (ctypes.Structure,), {"_fields_": fields})
        self._ctypes_struct_cache[struct_name] = struct_cls
        return struct_cls

    def _resolve_ctype(self, type_name: str) -> Any:
        """Map a C type name string to a ctypes type."""
        import ctypes
        t = _canonical_c_type_name(type_name)
        if t.endswith("*"):
            return ctypes.c_void_p
        if t.startswith("struct "):
            return self._resolve_struct_ctype(t[len("struct "):].strip())
        t = t.replace("*", "* ").replace("  ", " ").strip()
        ctype_map = self._get_ctype_map()
        if t in ctype_map:
            return ctype_map[t]
        # Default to c_long (64-bit on Linux x86-64)
        return ctypes.c_long

    def _dlsym(self, name: str) -> Any:
        """Look up a symbol across all dl handles, return a raw function pointer or None."""
        for handle in self._dl_handles:
            try:
                return getattr(handle, name)
            except AttributeError:
                continue
        if self._dl_load_errors:
            load_details = "; ".join(f"{lib}: {error}" for lib, error in sorted(self._dl_load_errors.items()))
            raise ParseError(f"extern '{name}' not found in any loaded library (load failures: {load_details})", code="ct-extern-unavailable")
        return None

    def _libl2_invoke_bridge(self) -> Any:
        """Cached ctypes binding for l2_invoke_trampoline (r12-in/r12-out)."""
        bridge = self._dl_func_cache.get("__bridge_l2_invoke_trampoline")
        if bridge is None:
            bridge = self._dlsym("l2_invoke_trampoline")
            if bridge is None:
                raise ParseError(
                    "libl2 was loaded but 'l2_invoke_trampoline' is missing "
                    "(rebuild libl2 from the current main.c)",
                    code="ct-extern-unavailable",
                )
            bridge.restype = ctypes.c_uint64
            bridge.argtypes = [ctypes.c_void_p, ctypes.c_uint64]
            self._dl_func_cache["__bridge_l2_invoke_trampoline"] = bridge
        return bridge

    def _call_libl2_trampoline_factory(self, name: str, word: Word) -> int:
        """Invoke l2_compile / l2_jit_from_asm and return the raw fn ptr.

        Argument marshalling follows the extern declaration on the L2
        side: `_cstr` variants take a single pointer, the plain
        variants take (source_ptr, source_len).
        """
        bridge_key = f"__bridge_{name}"
        bridge = self._dl_func_cache.get(bridge_key)
        if bridge is None:
            bridge = self._dlsym(name)
            if bridge is None:
                raise ParseError(f"extern '{name}' not found in any loaded library", code="ct-extern-unavailable")
            bridge.restype = ctypes.c_void_p
            if name.endswith("_cstr"):
                bridge.argtypes = [ctypes.c_void_p]
            else:
                bridge.argtypes = [ctypes.c_void_p, ctypes.c_longlong]
            self._dl_func_cache[bridge_key] = bridge
        if name.endswith("_cstr"):
            source_addr = int(self.pop())
            raw = bridge(source_addr)
        else:
            source_len = int(self.pop())
            source_addr = int(self.pop())
            raw = bridge(source_addr, source_len)
        if raw is None:
            raise ParseError(f"{name} returned NULL", code="ct-extern-unavailable")
        return int(raw)

    def _call_extern_ct(self, word: Word) -> None:
        """Call an extern C function via dlsym/ctypes on the native stacks."""
        name = word.name

        # Special handling for exit — intercept it before doing anything
        if name == "exit":
            raise _CTVMExit()

        # Stack-ABI bridges: these words mutate the native stack pointer rather than
        # returning normal C values, so call the explicit compute helpers.
        if name == "eval":
            source_len = int(self.pop())
            source_addr = int(self.pop())
            bridge = self._dl_func_cache.get("__bridge_l2_eval_compute")
            if bridge is None:
                bridge = self._dlsym("l2_eval_compute")
                if bridge is None:
                    raise ParseError("extern 'eval' requires symbol 'l2_eval_compute'", code="ct-extern-unavailable")
                bridge.restype = ctypes.c_uint64
                bridge.argtypes = [ctypes.c_void_p, ctypes.c_longlong, ctypes.c_uint64]
                self._dl_func_cache["__bridge_l2_eval_compute"] = bridge
            self.r12 = int(bridge(source_addr, source_len, int(self.r12)))
            return

        if name == "eval_env":
            stack_top_addr = int(self.pop())
            source_len = int(self.pop())
            source_addr = int(self.pop())
            bridge = self._dl_func_cache.get("__bridge_l2_eval_env_compute")
            if bridge is None:
                bridge = self._dlsym("l2_eval_env_compute")
                if bridge is None:
                    raise ParseError("extern 'eval_env' requires symbol 'l2_eval_env_compute'", code="ct-extern-unavailable")
                bridge.restype = ctypes.c_uint64
                bridge.argtypes = [ctypes.c_void_p, ctypes.c_longlong, ctypes.c_longlong]
                self._dl_func_cache["__bridge_l2_eval_env_compute"] = bridge
            self.r12 = int(bridge(source_addr, source_len, stack_top_addr))
            return

        # libl2 trampoline factories: call the C function normally, then
        # remember the returned pointer so `call` can invoke it via the
        # r12-in/r12-out ABI (see _rt_call and l2_invoke_trampoline).
        if name in ("l2_compile", "l2_compile_cstr",
                    "l2_jit_from_asm", "l2_jit_from_asm_cstr"):
            fn_ptr = self._call_libl2_trampoline_factory(name, word)
            self._libl2_trampolines.add(int(fn_ptr))
            self.push(int(fn_ptr))
            return

        # Companion releases: call through as usual but also drop the
        # pointer from our tracking set so later reuse of the address
        # (unlikely but possible) does not misroute `call`.
        if name in ("l2_release", "l2_jit_release"):
            fn_ptr = int(self.pop())
            self._libl2_trampolines.discard(fn_ptr)
            bridge_key = f"__bridge_{name}"
            bridge = self._dl_func_cache.get(bridge_key)
            if bridge is None:
                bridge = self._dlsym(name)
                if bridge is None:
                    raise ParseError(f"extern '{name}' not found in any loaded library", code="ct-extern-unavailable")
                bridge.restype = None
                bridge.argtypes = [ctypes.c_void_p]
                self._dl_func_cache[bridge_key] = bridge
            bridge(fn_ptr)
            return

        func = self._dl_func_cache.get(name)
        if func is None:
            raw = self._dlsym(name)
            if raw is None:
                raise ParseError(f"extern '{name}' not found in any loaded library", code="ct-extern-unavailable")

            signature = word.extern_signature
            inputs = word.extern_inputs
            outputs = word.extern_outputs

            if signature:
                arg_types, ret_type = signature
                c_arg_types = [self._resolve_ctype(t) for t in arg_types]
                if ret_type == "void":
                    c_ret_type = None
                else:
                    c_ret_type = self._resolve_ctype(ret_type)
            else:
                # Legacy mode: assume all int64 args
                arg_types = []
                c_arg_types = [ctypes.c_int64] * inputs
                c_ret_type = ctypes.c_int64 if outputs > 0 else None

            # Configure the ctypes function object directly
            raw.restype = c_ret_type
            raw.argtypes = c_arg_types
            # Stash metadata for calling
            raw._ct_inputs = inputs
            raw._ct_outputs = outputs
            raw._ct_arg_types = c_arg_types
            raw._ct_ret_type = c_ret_type
            raw._ct_signature = signature
            func = raw
            self._dl_func_cache[name] = func

        inputs = func._ct_inputs
        outputs = func._ct_outputs
        arg_types = list(func._ct_signature[0]) if func._ct_signature else []

        # For variadic externs, the TOS value is the extra arg count
        # (consumed by the compiler, not passed to C).
        va_extra = 0
        if getattr(word, "extern_variadic", False):
            va_extra = int(self.pop())
            inputs += va_extra
            for _ in range(va_extra):
                arg_types.append("long")
            # Update ctypes argtypes to include the variadic args
            func.argtypes = list(func._ct_arg_types) + [ctypes.c_int64] * va_extra

        # Pop arguments off the native data stack (right-to-left / reverse order)
        raw_args = []
        for i in range(inputs):
            raw_args.append(self.pop())
        raw_args.reverse()

        # Convert arguments to proper ctypes values
        call_args = []
        for i, raw in enumerate(raw_args):
            arg_type = _canonical_c_type_name(arg_types[i]) if i < len(arg_types) else None
            if arg_type in ("float", "double"):
                # Reinterpret the int64 bits as a double (matching the language's convention)
                raw_int = _to_i64(int(raw))
                double_val = _get_struct().unpack("d", _get_struct().pack("q", raw_int))[0]
                call_args.append(double_val)
            elif arg_type is not None and arg_type.startswith("struct ") and not arg_type.endswith("*"):
                struct_name = arg_type[len("struct "):].strip()
                struct_ctype = self._resolve_struct_ctype(struct_name)
                call_args.append(struct_ctype.from_address(int(raw)))
            else:
                call_args.append(int(raw))

        result = func(*call_args)

        if outputs > 0 and result is not None:
            ret_type = _canonical_c_type_name(func._ct_signature[1]) if func._ct_signature else None
            if ret_type in ("float", "double"):
                int_bits = _get_struct().unpack("q", _get_struct().pack("d", float(result)))[0]
                self.push(int_bits)
            elif ret_type is not None and ret_type.startswith("struct "):
                struct_name = ret_type[len("struct "):].strip()
                layout = self.parser.cstruct_layouts.get(struct_name)
                if layout is None:
                    raise ParseError(f"unknown cstruct '{struct_name}' used in extern return type", code="extern-type-invalid")
                out_ptr = self.memory.allocate(layout.size)
                ctypes.memmove(out_ptr, ctypes.byref(result), layout.size)
                self.push(out_ptr)
            else:
                self.push(int(result))

    def run_macro_body(self, name: str, definition: Definition) -> None:
        """Execute a macro body (the caller set up its stack and bindings)."""
        self.call_stack.append(name)
        try:
            self._execute_nodes(definition.body, _defn=definition)
        except _CTVMReturn:
            pass
        except CompileTimeError:
            raise
        except (_CTVMJump, _CTVMExit):
            raise
        except ParseError as exc:
            stack_chain = " -> ".join(self.call_stack)
            notes = [f"compile-time stack: {stack_chain}"] if stack_chain else []
            raise _rewrap_error(exc, CompileTimeError, notes=notes, default_code="ct-word-failed",
                                fallback_origin=_origin_from_location(self.current_location)) from None
        except Exception as exc:
            stack_chain = " -> ".join(self.call_stack)
            notes = [f"compile-time stack: {stack_chain}"] if stack_chain else []
            raise _rewrap_error(exc, CompileTimeError, notes=notes,
                                message=f"compile-time failure in macro '{name}': {exc}",
                                fallback_origin=_origin_from_location(self.current_location)) from None
        finally:
            self.call_stack.pop()

    def _call_word(self, word: Word, _plain: bool = False) -> None:
        """Run one word.  _plain: the caller checked that this is a compile-time
        call of an ordinary Definition that the checks below would run as its
        body (no macro, intrinsic, or compile-only/runtime-only flag)."""
        if not _plain and word.macro_def is not None and not self.runtime_mode:
            # A macro called from CT code reads its arguments from the input.
            parser = self.parser
            trigger = parser._last_token or _derive_token(None, word.name)
            parser._expand_macro(word, trigger)
            return
        self.call_stack.append(word.name)
        bus = self.parser.event_bus
        if bus is not None and bus.wants("ct.execute.begin"):
            bus.publish("ct.execute.begin", {"word": word.name, "runtime_mode": self.runtime_mode})
        _event_start = time.perf_counter_ns()
        try:
            if _plain:
                definition = word.definition
                self._execute_nodes(definition.body, _defn=definition)
                return
            if word.runtime_only and not self.runtime_mode:
                raise ParseError(
                    f"word '{word.name}' is runtime-only and cannot be executed at compile time",
                    code="ct-runtime-only-target",
                )
            definition = word.definition
            # In runtime_mode, prefer runtime_intrinsic (for exit/jmp/syscall
            # and __with_* variables).  All other :asm words run as native JIT.
            if self.runtime_mode and word.runtime_intrinsic is not None:
                word.runtime_intrinsic(self)
                return

            if (
                not self.runtime_mode
                and isinstance(definition, Definition)
                and word.compile_only
                and not word.compile_time_override
            ):
                body = definition.body
                if len(body) == 1:
                    node = body[0]
                    if node._opcode == OP_LITERAL:
                        data = node.data
                        self.push(_float_bits(data) if type(data) is float else data)
                        return
                    if node._opcode == OP_WORD:
                        if node._word_ref is None:
                            self._resolve_words_in_body(definition)
                        ref = node._word_ref
                        if (
                            ref is not None
                            and ref.compile_time_intrinsic is not None
                            and not ref.compile_time_override
                            and not ref.immediate
                            and not (self.runtime_mode
                                     and ref.compile_time_intrinsic in _CT_VALUE_STACK_INTRINSICS)
                        ):
                            ref.compile_time_intrinsic(self)
                            return

            prefer_definition = word.compile_time_override or (isinstance(definition, Definition) and (word.immediate or word.compile_only))
            if (not prefer_definition and word.compile_time_intrinsic is not None
                    and not (self.runtime_mode and word.compile_time_intrinsic in _CT_VALUE_STACK_INTRINSICS)):
                word.compile_time_intrinsic(self)
                return
            # C extern words: call via dlopen/dlsym in runtime_mode
            if self.runtime_mode and getattr(word, "is_extern", False):
                self._call_extern_ct(word)
                return
            if definition is None:
                raise ParseError(f"word '{word.name}' has no compile-time definition", code="ct-word-unavailable")
            if isinstance(definition, AsmDefinition):
                if self.runtime_mode:
                    self._run_jit(word)
                else:
                    self._run_asm_definition(word)
                return
            # Whole-word JIT for regular definitions in runtime mode
            if self.runtime_mode and isinstance(definition, Definition):
                ck = f"__defn_jit_{word.name}"
                jf = self._jit_cache.get(ck)
                if jf is None and ck + "_miss" not in self._jit_cache:
                    jf = self._compile_definition_jit(word)
                    if jf is not None:
                        self._jit_cache[ck] = jf
                        self._jit_cache[ck + "_addr"] = ctypes.cast(jf, ctypes.c_void_p).value
                    else:
                        self._jit_cache[ck + "_miss"] = True
                if jf is not None:
                    out = self._jit_out2
                    jf(self.r12, self.r13, self._jit_out2_addr)
                    self.r12 = out[0]
                    self.r13 = out[1]
                    return
            self._execute_nodes(definition.body, _defn=definition)
        except CompileTimeError:
            raise
        except (_CTVMJump, _CTVMExit, _CTVMReturn):
            raise
        except ParseError as exc:
            stack_chain = " -> ".join(self.call_stack)
            notes = [f"compile-time stack: {stack_chain}"] if stack_chain else []
            raise _rewrap_error(exc, CompileTimeError, notes=notes, default_code="ct-word-failed",
                                fallback_origin=_origin_from_location(self.current_location)) from None
        except Exception as exc:
            stack_chain = " -> ".join(self.call_stack)
            notes = [f"compile-time stack: {stack_chain}"] if stack_chain else []
            raise _rewrap_error(exc, CompileTimeError, notes=notes,
                                message=f"compile-time failure in '{word.name}': {exc}",
                                fallback_origin=_origin_from_location(self.current_location)) from None
        finally:
            bus = self.parser.event_bus
            if bus is not None and bus.wants("ct.execute.end"):
                bus.publish("ct.execute.end", {"word": word.name, "duration_ns": time.perf_counter_ns() - _event_start, "runtime_mode": self.runtime_mode})
            self.call_stack.pop()

    # -- Native JIT execution (runtime_mode) --------------------------------

    _JIT_FUNC_TYPE: Optional[Any] = None

    def _run_jit(self, word: Word) -> None:
        """JIT-compile (once) and execute an :asm word on the native r12/r13 stacks."""
        func = self._jit_cache.get(word.name)
        if func is None:
            func = self._compile_jit(word)
            self._jit_cache[word.name] = func

        out = self._jit_out2
        func(self.r12, self.r13, self._jit_out2_addr)
        self.r12 = out[0]
        self.r13 = out[1]

    def _compile_jit(self, word: Word) -> Any:
        """Assemble an :asm word into executable memory and return a ctypes callable."""
        definition = word.definition
        if not isinstance(definition, AsmDefinition):
            raise ParseError(f"word '{word.name}' has no asm body", code="ct-jit-failed")
        asm_body = definition.body.strip("\n")
        is_coro = self._is_coroutine_asm(asm_body)

        bss = self._bss_symbols

        # Build wrapper
        lines: List[str] = []
        if is_coro:
            self._ensure_jit_save_buf()
            sb = self._jit_save_buf_addr
            # Use register-indirect addressing: x86-64 mov [disp],reg only
            # supports 32-bit displacement -- sb is a 64-bit heap address.
            lines.extend([
                "_ct_entry:",
                f"    mov rax, {sb}",        # load save buffer base
                "    mov [rax], rbx",
                "    mov [rax + 8], r12",
                "    mov [rax + 16], r13",
                "    mov [rax + 24], r14",
                "    mov [rax + 32], r15",
                "    mov [rax + 40], rdx",   # output ptr
                "    mov r12, rdi",
                "    mov r13, rsi",
                # Replace return address with trampoline
                "    pop rcx",
                "    mov [rax + 48], rcx",   # save ctypes return addr
                "    lea rcx, [rip + _ct_trampoline]",
                "    push rcx",
            ])
        else:
            # Standard wrapper: save callee-saved regs on stack
            lines.extend([
                "_ct_entry:",
                "    push rbx",
                "    push r12",
                "    push r13",
                "    push r14",
                "    push r15",
                "    sub rsp, 16",       # align + room for output ptr
                "    mov [rsp], rdx",    # save output-struct pointer
                "    mov r12, rdi",      # data stack
                "    mov r13, rsi",      # return stack
            ])

        # Patch asm body
        # Collect dot-prefixed local labels and build rename map for Keystone
        _local_labels: Set[str] = set()
        for raw_line in asm_body.splitlines():
            line = raw_line.strip()
            lm = _RE_LABEL_PAT.match(line)
            if lm and lm.group(1).startswith('.'):
                _local_labels.add(lm.group(1))

        for raw_line in asm_body.splitlines():
            line = raw_line.strip()
            if not line or line.startswith(";"):
                continue
            if line.startswith("extern"):
                continue  # strip extern declarations
            if line == "ret" and not is_coro:
                line = "jmp _ct_save"

            # Rename dot-prefixed local labels to Keystone-compatible names
            for lbl in _local_labels:
                line = re.sub(rf'(?<!\w){re.escape(lbl)}(?=\s|:|,|$|\]|\))',
                              '_jl' + lbl[1:], line)

            abs_mem_match = _RE_ABS_MEM_LITERAL_PAT.search(line)
            if abs_mem_match is not None:
                self._emit_abs_mem_literal_patch(lines, line, abs_mem_match.group(1))
                continue

            # Patch [rel SYMBOL] -> concrete address
            rel_expr = self._resolve_rel_symbol_expression(line, bss)
            if rel_expr is not None:
                if line.lstrip().startswith("lea"):
                    # lea REG, [rel X] -> mov REG, addr
                    line = _RE_REL_TO_RIP_PAT.sub(rel_expr, line).replace("lea", "mov", 1)
                else:
                    self._emit_rel_symbol_patch(lines, line, rel_expr)
                    continue

            if self._patch_direct_word_call(lines, line, word.name, _local_labels):
                continue
            # Convert NASM 'rel' to explicit rip-relative for Keystone
            line = _normalize_rel_to_rip(line)
            lines.append(f"    {line}")

        # Save/epilogue
        if is_coro:
            sb = self._jit_save_buf_addr
            lines.extend([
                "_ct_trampoline:",
                f"    mov rax, {sb}",        # reload save buffer base
                "    mov rcx, [rax + 40]",   # output ptr
                "    mov [rcx], r12",
                "    mov [rcx + 8], r13",
                "    mov rbx, [rax]",
                "    mov r12, [rax + 8]",
                "    mov r13, [rax + 16]",
                "    mov r14, [rax + 24]",
                "    mov r15, [rax + 32]",
                "    mov rcx, [rax + 48]",   # ctypes return addr
                "    push rcx",
                "    ret",
            ])
        else:
            lines.extend([
                "_ct_save:",
                "    mov rax, [rsp]",      # output-struct pointer
                "    mov [rax], r12",
                "    mov [rax + 8], r13",
                "    add rsp, 16",
                "    pop r15",
                "    pop r14",
                "    pop r13",
                "    pop r12",
                "    pop rbx",
                "    ret",
            ])

        ptr = self._jit_assemble_page(lines, word.name)
        if CompileTimeVM._JIT_FUNC_TYPE is None:
            CompileTimeVM._JIT_FUNC_TYPE = ctypes.CFUNCTYPE(None, ctypes.c_int64, ctypes.c_int64, ctypes.c_void_p)
        func = self._JIT_FUNC_TYPE(ptr)
        return func

    def _jit_assemble_page(self, lines: List[str], word_name: str) -> int:
        """Assemble lines into an RWX page and return its address."""
        def _norm(l: str) -> str:
            l = l.split(";", 1)[0].rstrip()
            for sz in ("qword", "dword", "word", "byte"):
                l = l.replace(f"{sz} [", f"{sz} ptr [")
            return l
        normalized = [_norm(l) for l in lines if _norm(l).strip()]
        try:
            code = _x86_assemble("\n".join(normalized))
        except KsError as exc:
            debug_txt = "\n".join(normalized)
            raise ParseError(
                f"JIT assembly failed for '{word_name}': {exc}\n--- asm ---\n{debug_txt}\n--- end ---",
                code="ct-jit-failed",
            ) from exc
        if code is None:
            raise ParseError("keystone-engine is required for JIT execution", code="ct-jit-failed")
        if not code:
            raise ParseError(f"JIT produced no code for '{word_name}'", code="ct-jit-failed")
        page_size = max(len(code), 4096)
        _libc = ctypes.CDLL(None, use_errno=True)
        _libc.mmap.restype = ctypes.c_void_p
        _libc.mmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int,
                                ctypes.c_int, ctypes.c_int, ctypes.c_long]
        PROT_RWX = 0x1 | 0x2 | 0x4
        MAP_PRIVATE = 0x02
        MAP_ANONYMOUS = 0x20
        ptr = _libc.mmap(None, page_size, PROT_RWX,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)
        if ptr == ctypes.c_void_p(-1).value or ptr is None:
            raise RuntimeError(f"mmap failed for JIT code ({page_size} bytes)")
        ctypes.memmove(ptr, code, len(code))
        self._jit_code_pages.append((ptr, page_size))
        return ptr

    def _compile_raw_jit(self, word: Word) -> int:
        """Compile a word into executable memory without a wrapper.

        Returns the native code address (not a ctypes callable).
        For AsmDefinition: just the asm body (patched, no wrapper).
        For Definition: compiled body with ret (no entry/exit wrapper).
        """
        cache_key = f"__raw_jit_{word.name}"
        cached = self._jit_cache.get(cache_key)
        if cached is not None:
            return cached

        definition = word.definition
        bss = self._bss_symbols
        lines: List[str] = []

        if isinstance(definition, AsmDefinition):
            asm_body = definition.body.strip("\n")
            is_coro = self._is_coroutine_asm(asm_body)
            _local_labels: Set[str] = set()
            for raw_line in asm_body.splitlines():
                line = raw_line.strip()
                lm = _RE_LABEL_PAT.match(line)
                if lm and lm.group(1).startswith('.'):
                    _local_labels.add(lm.group(1))
            for raw_line in asm_body.splitlines():
                line = raw_line.strip()
                if not line or line.startswith(";") or line.startswith("extern"):
                    continue
                # Keep ret as-is (raw functions return normally)
                for lbl in _local_labels:
                    line = re.sub(rf'(?<!\w){re.escape(lbl)}(?=\s|:|,|$|\]|\))',
                                  '_jl' + lbl[1:], line)
                abs_mem_match = _RE_ABS_MEM_LITERAL_PAT.search(line)
                if abs_mem_match is not None:
                    self._emit_abs_mem_literal_patch(lines, line, abs_mem_match.group(1))
                    continue
                rel_expr = self._resolve_rel_symbol_expression(line, bss)
                if rel_expr is not None:
                    if line.lstrip().startswith("lea"):
                        line = _RE_REL_TO_RIP_PAT.sub(rel_expr, line).replace("lea", "mov", 1)
                    else:
                        self._emit_rel_symbol_patch(lines, line, rel_expr)
                        continue

                if self._patch_direct_word_call(lines, line, word.name, _local_labels):
                    continue
                line = _normalize_rel_to_rip(line)
                lines.append(f"    {line}")
            lines.append("    ret")
        elif isinstance(definition, Definition):
            lines.extend(self._compile_raw_definition_lines(word, definition))
        else:
            raise ParseError(f"cannot raw-JIT word '{word.name}'", code="ct-jit-failed")

        ptr = self._jit_assemble_page(lines, f"raw_{word.name}")
        self._jit_cache[cache_key] = ptr
        return ptr

    def _compile_raw_definition_lines(self, word: Word, defn: Definition) -> List[str]:
        """Compile a Definition body to raw JIT asm lines (no wrapper, just body + ret)."""
        self._resolve_words_in_body(defn)
        bss = self._bss_symbols
        body = defn.body
        lines: List[str] = []
        uid = id(defn)
        lc = [0]
        def _nl(prefix: str) -> str:
            lc[0] += 1
            return f"_rj{uid}_{prefix}_{lc[0]}"

        # Label maps
        label_map: Dict[str, str] = {}
        for node in body:
            if node._opcode == OP_LABEL:
                ln = str(node.data)
                if ln not in label_map:
                    label_map[ln] = _nl("lbl")

        for_map: Dict[int, Tuple[str, str]] = {}
        fstack: List[Tuple[int, str, str]] = []
        for idx, node in enumerate(body):
            if node._opcode == OP_FOR_BEGIN:
                bl, el = _nl("for_top"), _nl("for_end")
                fstack.append((idx, bl, el))
            elif node._opcode == OP_FOR_END:
                if fstack:
                    bi, bl, el = fstack.pop()
                    for_map[bi] = (bl, el)
                    for_map[idx] = (bl, el)

        out2_addr = self._jit_out2_addr

        for idx, node in enumerate(body):
            opc = node._opcode
            if opc == OP_LITERAL:
                data = node.data
                if isinstance(data, str):
                    addr, length = self.memory.store_string(data)
                    lines.append("    sub r12, 16")
                    lines.append(f"    mov rax, {addr}")
                    lines.append("    mov [r12 + 8], rax")
                    if -0x80000000 <= length <= 0x7FFFFFFF:
                        lines.append(f"    mov qword [r12], {length}")
                    else:
                        lines.append(f"    mov rax, {length}")
                        lines.append("    mov [r12], rax")
                elif isinstance(data, float):
                    val = _get_struct().unpack("q", _get_struct().pack("d", float(data)))[0]
                    lines.append("    sub r12, 8")
                    if -0x80000000 <= val <= 0x7FFFFFFF:
                        lines.append(f"    mov qword [r12], {val}")
                    else:
                        lines.append(f"    mov rax, {val}")
                        lines.append("    mov [r12], rax")
                else:
                    val = int(data) & 0xFFFFFFFFFFFFFFFF
                    if val >= 0x8000000000000000:
                        val -= 0x10000000000000000
                    lines.append("    sub r12, 8")
                    if -0x80000000 <= val <= 0x7FFFFFFF:
                        lines.append(f"    mov qword [r12], {val}")
                    else:
                        lines.append(f"    mov rax, {val}")
                        lines.append("    mov [r12], rax")
            elif opc == OP_WORD:
                wref = node._word_ref
                if wref is None:
                    # Structured loops are labels and jumps by now; the only
                    # unresolved word handled here is `exit`.
                    if node.data == "exit":
                        lines.append("    ret")
                    continue

                wd = wref.definition
                if isinstance(wd, AsmDefinition):
                    if self._is_coroutine_asm(wd.body.strip("\n")):
                        # Coroutine asm: call raw JIT instead of inlining
                        raw_addr = self._compile_raw_jit(wref)
                        lines.append(f"    mov rax, {raw_addr}")
                        lines.append("    call rax")
                    else:
                        # Inline asm body
                        prefix = _nl(f"a{idx}")
                        _local_labels: Set[str] = set()
                        asm_txt = wd.body.strip("\n")
                        has_ret = False
                        for raw_line in asm_txt.splitlines():
                            ln = raw_line.strip()
                            lm = _RE_LABEL_PAT.match(ln)
                            if lm:
                                _local_labels.add(lm.group(1))
                            if ln == "ret":
                                has_ret = True
                        end_lbl = f"{prefix}_end" if has_ret else None
                        for raw_line in asm_txt.splitlines():
                            ln = raw_line.strip()
                            if not ln or ln.startswith(";") or ln.startswith("extern"):
                                continue
                            if ln == "ret":
                                lines.append(f"    jmp {end_lbl}")
                                continue
                            for lbl in _local_labels:
                                ln = re.sub(rf'(?<!\w){re.escape(lbl)}(?=\s|:|,|$|\]|\))',
                                            prefix + lbl, ln)
                            rel_expr = self._resolve_rel_symbol_expression(ln, bss)
                            if rel_expr is not None:
                                if ln.lstrip().startswith("lea"):
                                    ln = _RE_REL_TO_RIP_PAT.sub(rel_expr, ln).replace("lea", "mov", 1)
                                else:
                                    self._emit_rel_symbol_patch(lines, ln, rel_expr)
                                    continue
                            ln = _normalize_rel_to_rip(ln)
                            lines.append(f"    {ln}")
                        if end_lbl is not None:
                            lines.append(f"{end_lbl}:")
                elif isinstance(wd, Definition):
                    # Call standard JIT'd sub-definition via output buffer
                    ck = f"__defn_jit_{wref.name}"
                    if ck not in self._jit_cache:
                        sub = self._compile_definition_jit(wref)
                        if sub is None:
                            # Can't JIT; fall back to raw JIT of the sub-word
                            raw_addr = self._compile_raw_jit(wref)
                            lines.append(f"    mov rax, {raw_addr}")
                            lines.append("    call rax")
                            continue
                        self._jit_cache[ck] = sub
                        self._jit_cache[ck + "_addr"] = ctypes.cast(sub, ctypes.c_void_p).value
                    func_addr = self._jit_cache.get(ck + "_addr")
                    if func_addr is None:
                        raise ParseError(f"raw JIT: missing JIT for '{wref.name}'", code="ct-jit-failed")
                    lines.append("    mov rdi, r12")
                    lines.append("    mov rsi, r13")
                    lines.append(f"    mov rdx, {out2_addr}")
                    lines.append(f"    mov rax, {func_addr}")
                    lines.append("    call rax")
                    lines.append(f"    mov rax, {out2_addr}")
                    lines.append("    mov r12, [rax]")
                    lines.append("    mov r13, [rax + 8]")
                else:
                    raise ParseError(f"raw JIT: unsupported word '{wref.name}'", code="ct-jit-failed")
            elif opc == OP_WORD_PTR:
                # Word pointer: push the raw JIT address of the target
                target_name = str(node.data)
                tw = self.dictionary.lookup(target_name)
                if tw is None:
                    raise ParseError(f"raw JIT: unknown word '{target_name}'", code="ct-jit-failed")
                raw_addr = self._compile_raw_jit(tw)
                lines.append("    sub r12, 8")
                lines.append(f"    mov rax, {raw_addr}")
                lines.append("    mov [r12], rax")
            elif opc == OP_FOR_BEGIN:
                pair = for_map.get(idx)
                if pair is None:
                    raise ParseError("raw JIT: unmatched for", code="ct-jit-failed")
                bl, el = pair
                lines.append("    mov rax, [r12]")
                lines.append("    add r12, 8")
                lines.append("    cmp rax, 0")
                lines.append(f"    jle {el}")
                lines.append("    sub r13, 8")
                lines.append("    mov [r13], rax")
                lines.append(f"{bl}:")
            elif opc == OP_FOR_END:
                pair = for_map.get(idx)
                if pair is None:
                    raise ParseError("raw JIT: unmatched for end", code="ct-jit-failed")
                bl, el = pair
                lines.append("    dec qword [r13]")
                lines.append("    cmp qword [r13], 0")
                lines.append(f"    jg {bl}")
                lines.append("    add r13, 8")
                lines.append(f"{el}:")
            elif opc == OP_BRANCH_ZERO:
                ln = str(node.data)
                al = label_map.get(ln)
                if al is None:
                    raise ParseError("raw JIT: unknown branch target", code="ct-jit-failed")
                lines.append("    mov rax, [r12]")
                lines.append("    add r12, 8")
                lines.append("    test rax, rax")
                lines.append(f"    jz {al}")
            elif opc == OP_JUMP:
                ln = str(node.data)
                al = label_map.get(ln)
                if al is None:
                    raise ParseError("raw JIT: unknown jump target", code="ct-jit-failed")
                lines.append(f"    jmp {al}")
            elif opc == OP_LABEL:
                ln = str(node.data)
                al = label_map.get(ln)
                if al is None:
                    raise ParseError("raw JIT: unknown label", code="ct-jit-failed")
                lines.append(f"{al}:")
            elif opc == OP_FOR_DROP:
                lines.append("    add r13, 8")
            else:
                raise ParseError(f"raw JIT: unsupported opcode {opc} in '{word.name}'", code="ct-jit-failed")

        lines.append("    ret")
        return lines

    # -- Whole-word JIT: compile Definition bodies to native code -----------

    def _compile_definition_jit(self, word: Word) -> Any:
        """JIT-compile a regular Definition body into native x86-64 code.

        Returns a ctypes callable or None if the definition cannot be JIT'd.
        """
        defn = word.definition
        if not isinstance(defn, Definition):
            return None
        # Guard against infinite recursion (recursive words)
        compiling = getattr(self, "_djit_compiling", None)
        if compiling is None:
            compiling = set()
            self._djit_compiling = compiling
        if word.name in compiling:
            return None  # recursive word, can't JIT
        compiling.add(word.name)
        try:
            return self._compile_definition_jit_inner(word, defn)
        finally:
            compiling.discard(word.name)

    def _compile_definition_jit_inner(self, word: Word, defn: Definition) -> Any:
        # Ensure word references are resolved
        self._resolve_words_in_body(defn)

        body = defn.body
        bss = self._bss_symbols

        # Pre-scan: bail if any op is unsupported
        for node in body:
            opc = node._opcode
            if opc == OP_LITERAL:
                if isinstance(node.data, str):
                    return None
            elif opc == OP_WORD:
                wref = node._word_ref
                if wref is None:
                    name = node.data
                    if name not in ("begin", "again", "continue", "exit"):
                        return None
                    if self.runtime_mode and name == "exit":
                        # Runtime mode must preserve process-exit semantics.
                        exit_word = self.dictionary.lookup("exit")
                        if exit_word is not None and exit_word.runtime_intrinsic is not None:
                            return None
                elif wref.runtime_intrinsic is not None:
                    return None
                elif getattr(wref, "is_extern", False):
                    return None  # extern words need _call_extern_ct
                else:
                    wd = wref.definition
                    if wd is None:
                        return None
                    if not isinstance(wd, (AsmDefinition, Definition)):
                        return None
                    if isinstance(wd, Definition):
                        ck = f"__defn_jit_{wref.name}"
                        if ck not in self._jit_cache:
                            sub = self._compile_definition_jit(wref)
                            if sub is None:
                                return None
                            self._jit_cache[ck] = sub
                            self._jit_cache[ck + "_addr"] = ctypes.cast(sub, ctypes.c_void_p).value
            elif opc in (OP_FOR_BEGIN, OP_FOR_END, OP_BRANCH_ZERO, OP_JUMP, OP_LABEL, OP_FOR_DROP):
                pass
            else:
                return None

        uid = id(defn)
        lc = [0]
        def _nl(prefix: str) -> str:
            lc[0] += 1
            return f"_dj{uid}_{prefix}_{lc[0]}"

        # Build label maps
        label_map: Dict[str, str] = {}
        for node in body:
            if node._opcode == OP_LABEL:
                ln = str(node.data)
                if ln not in label_map:
                    label_map[ln] = _nl("lbl")

        # For-loop pairing
        for_map: Dict[int, Tuple[str, str]] = {}
        fstack: List[Tuple[int, str, str]] = []
        for idx, node in enumerate(body):
            if node._opcode == OP_FOR_BEGIN:
                bl, el = _nl("for_top"), _nl("for_end")
                fstack.append((idx, bl, el))
            elif node._opcode == OP_FOR_END:
                if fstack:
                    bi, bl, el = fstack.pop()
                    for_map[bi] = (bl, el)
                    for_map[idx] = (bl, el)

        # begin/again pairing
        lines: List[str] = []
        # Entry wrapper
        lines.extend([
            "_ct_entry:",
            "    push rbx",
            "    push r12",
            "    push r13",
            "    push r14",
            "    push r15",
            "    sub rsp, 16",
            "    mov [rsp], rdx",
            "    mov r12, rdi",
            "    mov r13, rsi",
        ])


        def _patch_asm_body(asm_body: str, prefix: str) -> List[str]:
            """Patch an asm body for inlining: uniquify labels, patch [rel]."""
            result: List[str] = []
            local_labels: Set[str] = set()
            has_ret = False
            for raw_line in asm_body.splitlines():
                line = raw_line.strip()
                lm = _RE_LABEL_PAT.match(line)
                if lm:
                    local_labels.add(lm.group(1))
                if line == "ret":
                    has_ret = True
            end_label = f"{prefix}_end" if has_ret else None
            for raw_line in asm_body.splitlines():
                line = raw_line.strip()
                if not line or line.startswith(";") or line.startswith("extern"):
                    continue
                if line == "ret":
                    result.append(f"    jmp {end_label}")
                    continue
                for label in local_labels:
                    line = re.sub(rf'(?<!\w){re.escape(label)}(?=\s|:|,|$|\]|\))', prefix + label, line)
                rel_expr = self._resolve_rel_symbol_expression(line, bss)
                if rel_expr is not None:
                    if line.lstrip().startswith("lea"):
                        line = _RE_REL_TO_RIP_PAT.sub(rel_expr, line).replace("lea", "mov", 1)
                    else:
                        self._emit_rel_symbol_patch(result, line, rel_expr)
                        continue
                # Convert NASM 'rel' to explicit rip-relative for Keystone
                line = _normalize_rel_to_rip(line)
                result.append(f"    {line}")
            if end_label is not None:
                result.append(f"{end_label}:")
            return result

        for idx, node in enumerate(body):
            opc = node._opcode

            if opc == OP_LITERAL:
                data = node.data
                if isinstance(data, float):
                    val = _get_struct().unpack("q", _get_struct().pack("d", float(data)))[0]
                else:
                    val = int(data) & 0xFFFFFFFFFFFFFFFF
                if val >= 0x8000000000000000:
                    val -= 0x10000000000000000
                lines.append("    sub r12, 8")
                if -0x80000000 <= val <= 0x7FFFFFFF:
                    lines.append(f"    mov qword [r12], {val}")
                else:
                    lines.append(f"    mov rax, {val}")
                    lines.append("    mov [r12], rax")

            elif opc == OP_WORD:
                wref = node._word_ref
                if wref is None:
                    # Structured loops are labels and jumps by now; the only
                    # unresolved word handled here is `exit`.
                    if node.data == "exit":
                        lines.append("    jmp _ct_save")
                    continue

                wd = wref.definition
                if isinstance(wd, AsmDefinition):
                    prefix = _nl(f"a{idx}")
                    lines.extend(_patch_asm_body(wd.body.strip("\n"), prefix))
                elif isinstance(wd, Definition):
                    # Call JIT'd sub-definition
                    ck = f"__defn_jit_{wref.name}"
                    func_addr = self._jit_cache.get(ck + "_addr")
                    if func_addr is None:
                        return None  # should have been pre-compiled above
                    # Save & call: rdi=r12, rsi=r13, rdx=output_ptr
                    lines.append("    mov rax, [rsp]")
                    lines.append("    mov rdi, r12")
                    lines.append("    mov rsi, r13")
                    lines.append("    mov rdx, rax")
                    lines.append(f"    mov rax, {func_addr}")
                    lines.append("    call rax")
                    # Restore r12/r13 from output struct
                    lines.append("    mov rax, [rsp]")
                    lines.append("    mov r12, [rax]")
                    lines.append("    mov r13, [rax + 8]")

            elif opc == OP_FOR_BEGIN:
                pair = for_map.get(idx)
                if pair is None:
                    return None
                bl, el = pair
                lines.append("    mov rax, [r12]")
                lines.append("    add r12, 8")
                lines.append("    cmp rax, 0")
                lines.append(f"    jle {el}")
                lines.append("    sub r13, 8")
                lines.append("    mov [r13], rax")
                lines.append(f"{bl}:")

            elif opc == OP_FOR_END:
                pair = for_map.get(idx)
                if pair is None:
                    return None
                bl, el = pair
                lines.append("    dec qword [r13]")
                lines.append("    cmp qword [r13], 0")
                lines.append(f"    jg {bl}")
                lines.append("    add r13, 8")
                lines.append(f"{el}:")

            elif opc == OP_BRANCH_ZERO:
                ln = str(node.data)
                al = label_map.get(ln)
                if al is None:
                    return None
                lines.append("    mov rax, [r12]")
                lines.append("    add r12, 8")
                lines.append("    test rax, rax")
                lines.append(f"    jz {al}")

            elif opc == OP_JUMP:
                ln = str(node.data)
                al = label_map.get(ln)
                if al is None:
                    return None
                lines.append(f"    jmp {al}")

            elif opc == OP_LABEL:
                ln = str(node.data)
                al = label_map.get(ln)
                if al is None:
                    return None
                lines.append(f"{al}:")

            elif opc == OP_FOR_DROP:
                lines.append("    add r13, 8")

        # Epilog
        lines.extend([
            "_ct_save:",
            "    mov rax, [rsp]",
            "    mov [rax], r12",
            "    mov [rax + 8], r13",
            "    add rsp, 16",
            "    pop r15",
            "    pop r14",
            "    pop r13",
            "    pop r12",
            "    pop rbx",
            "    ret",
        ])

        def _norm(l: str) -> str:
            l = l.split(";", 1)[0].rstrip()
            for sz in ("qword", "dword", "word", "byte"):
                l = l.replace(f"{sz} [", f"{sz} ptr [")
            return l
        normalized = [_norm(l) for l in lines if _norm(l).strip()]

        try:
            code = _x86_assemble("\n".join(normalized))
        except KsError:
            return None
        if not code:
            return None

        page_size = max(len(code), 4096)
        _libc = ctypes.CDLL(None, use_errno=True)
        _libc.mmap.restype = ctypes.c_void_p
        _libc.mmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int,
                                ctypes.c_int, ctypes.c_int, ctypes.c_long]
        PROT_RWX = 0x1 | 0x2 | 0x4
        MAP_PRIVATE = 0x02
        MAP_ANONYMOUS = 0x20
        ptr = _libc.mmap(None, page_size, PROT_RWX,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)
        if ptr == ctypes.c_void_p(-1).value or ptr is None:
            return None
        ctypes.memmove(ptr, code, len(code))
        self._jit_code_pages.append((ptr, page_size))
        if CompileTimeVM._JIT_FUNC_TYPE is None:
            CompileTimeVM._JIT_FUNC_TYPE = ctypes.CFUNCTYPE(None, ctypes.c_int64, ctypes.c_int64, ctypes.c_void_p)
        return self._JIT_FUNC_TYPE(ptr)

    def _ct_native_with_string_cells(self, name: str, equivalent: Callable[[List[Any]], bool]) -> bool:
        """A string operand is its runtime (address, length) cells, so
        `"a" 1 +` adds 1 to the length as at runtime.  Only the topmost string
        among the top two items is split (the cells below it are what the
        runtime word would see).  Other non-integers in arithmetic are a
        ct-argument-type error."""
        stack = self.stack
        for index in (-1, -2):
            if len(stack) < -index:
                break
            value = stack[index]
            if type(value) is str:
                addr, length = self.memory.store_string(value)
                if index == -1:
                    stack[-1:] = [addr, length]
                else:
                    stack[-2:-1] = [addr, length]
                if equivalent(stack):
                    return True
                break
            if type(value) not in (int, bool):
                break
        if equivalent in _CT_NATIVE_STRICT:
            operands = ", ".join(_ct_type_name(value) for value in stack[-2:])
            raise ParseError(f"'{name}' expects integers or strings at compile time, got [{operands}]",
                             code="ct-argument-type")
        return False

    # -- Old non-runtime asm execution (kept for non-runtime CT mode) -------

    def _ct_asm_compile(self, word: Word, asm_body: str, data_start: int,
                        data_end: int) -> Tuple[Any, Any]:
        """Wrap, assemble and map an :asm body that uses per-call addresses
        ([rel data_start], [rel print_buf], ...).  Returns (callable, code
        page)."""
        PRINT_BUF_BYTES = 128
        print_buffer = ctypes.create_string_buffer(PRINT_BUF_BYTES)
        self._handles.refs.append(print_buffer)
        print_buf = ctypes.addressof(print_buffer)
        symbols: Dict[str, int] = {
            "data_start": data_start,
            "data_end": data_end,
            "print_buf": print_buf,
            "print_buf_end": print_buf + PRINT_BUF_BYTES,
        }
        if self.memory is not None:
            symbols.update({
                "persistent": self.memory.persistent_addr,
                "persistent_end": self.memory.persistent_addr + self.memory._persistent_size,
            })
        patched_body: List[str] = []
        for line in asm_body.splitlines():
            line = line.strip()
            if line == "ret":
                line = "jmp _ct_save"
            # Replace [rel SYMBOL] with concrete addresses
            rel_expr = self._resolve_rel_symbol_expression(line, symbols)
            if rel_expr is not None:
                # lea REG, [rel X]  ->  mov REG, addr
                if line.lstrip().startswith("lea"):
                    line = _RE_REL_TO_RIP_PAT.sub(rel_expr, line).replace("lea", "mov", 1)
                else:
                    self._emit_rel_symbol_patch(patched_body, line, rel_expr, indent="")
                    continue
            patched_body.append(_normalize_rel_to_rip(line))
        return _ct_asm_map(word.name, _ct_asm_wrap(patched_body))

    def _run_asm_definition(self, word: Word) -> None:
        definition = word.definition
        if isinstance(definition, AsmDefinition):
            needed = _asm_required_depth(definition.body)
            if needed:
                stack = self.stack
                # A string may become two cells (address, length): count it
                # as two, so a valid call is never rejected.
                available = len(stack) + sum(1 for value in stack if type(value) is str)
                if available < needed:
                    raise ParseError(f"stack underflow in '{word.name}': needs {needed} value(s), has {len(stack)}",
                                     code="ct-stack-underflow")
            equivalent = _ct_native_equivalent(definition.body)
            if equivalent is not None:
                if equivalent(self.stack) or self._ct_native_with_string_cells(word.name, equivalent):
                    return
        import ctypes as _ctypes
        globals().setdefault("ctypes", _ctypes)
        if not isinstance(definition, AsmDefinition):  # pragma: no cover - defensive
            raise ParseError(f"word '{word.name}' has no asm body", code="ct-asm-failed")
        asm_body = definition.body.strip("\n")
        if self._run_asm_on_ints(word, asm_body):
            return

        # Determine whether this asm expects string semantics via declared effects.
        string_mode = WORD_EFFECT_STRING_IO in definition.effects

        handles = self._handles

        non_int_data = any(not isinstance(v, int) for v in self.stack)
        non_int_return = any(not isinstance(v, int) for v in self.return_stack)

        # Collect all strings present on data and return stacks so we can point
        # puts() at a real buffer and pass its range check (data_start..data_end).
        strings: List[str] = []
        if string_mode:
            for v in self.stack + self.return_stack:
                if isinstance(v, str):
                    strings.append(v)
        data_blob = b""
        string_addrs: Dict[str, Tuple[int, int]] = {}
        if strings:
            offset = 0
            parts: List[bytes] = []
            seen: Dict[str, Tuple[int, int]] = {}
            for s in strings:
                if s in seen:
                    string_addrs[s] = seen[s]
                    continue
                encoded = s.encode("utf-8") + b"\x00"
                parts.append(encoded)
                addr = offset
                length = len(encoded) - 1
                seen[s] = (addr, length)
                string_addrs[s] = (addr, length)
                offset += len(encoded)
            data_blob = b"".join(parts)
        string_buffer: Optional[ctypes.Array[Any]] = None
        data_start = 0
        data_end = 0
        if data_blob:
            string_buffer = ctypes.create_string_buffer(data_blob)
            data_start = ctypes.addressof(string_buffer)
            data_end = data_start + len(data_blob)
            handles.refs.append(string_buffer)
            for s, (off, _len) in string_addrs.items():
                handles.objects[data_start + off] = s

        # A body that uses no per-call address ([rel data_start] etc.) always
        # assembles to the same code: keep that callable (and its code page)
        # instead of rebuilding, assembling and mapping it on every call.
        func = _ct_asm_static_func(word.name, asm_body)
        if func is None:
            func, _code_buf = self._ct_asm_compile(word, asm_body, data_start, data_end)

        handles = self._handles
        # String-mode strings are marshalled as (address, byte length) cell
        # pairs; remember each pair so unmarshalling restores exactly those.
        string_pairs: Dict[int, int] = {}

        def _marshal_stack(py_stack: List[Any]) -> Tuple[int, int, int, Any]:
            extra_cells = 0
            if string_mode:
                extra_cells = sum(1 for value in py_stack if isinstance(value, str))
            capacity = len(py_stack) + extra_cells + 16
            buffer = (ctypes.c_int64 * capacity)()
            base = ctypes.addressof(buffer)
            top = base + capacity * 8
            sp = top

            def _push_cell(cell_value: int) -> None:
                nonlocal sp
                sp -= 8
                if sp < base:
                    raise ParseError(
                        f"compile-time asm '{word.name}' marshal overflow",
                        code="ct-asm-failed",
                    )
                ctypes.c_int64.from_address(sp).value = int(cell_value)

            for value in py_stack:
                if isinstance(value, int):
                    _push_cell(value)
                elif isinstance(value, str):
                    if string_mode:
                        offset, strlen = string_addrs.get(value, (0, 0))
                        addr = data_start + offset if data_start else handles.store(value)
                        # puts expects (len, addr) with len on top
                        _push_cell(addr)
                        _push_cell(strlen)
                        string_pairs[addr] = strlen
                    else:
                        _push_cell(handles.store(value))
                else:
                    _push_cell(handles.store(value))
            return sp, top, base, buffer

        # r12/r13 must point at the top element (or top of buffer if empty)
        buffers: List[Any] = []
        d_sp, d_top, d_base, d_buf = _marshal_stack(self.stack)
        buffers.append(d_buf)
        r_sp, r_top, r_base, r_buf = _marshal_stack(self.return_stack)
        buffers.append(r_buf)
        out_d = ctypes.c_uint64(0)
        out_r = ctypes.c_uint64(0)
        func(d_sp, r_sp, ctypes.addressof(out_d), ctypes.addressof(out_r))

        new_d = out_d.value
        new_r = out_r.value
        if not (d_base <= new_d <= d_top):
            raise ParseError(f"compile-time asm '{word.name}' corrupted data stack pointer", code="ct-asm-failed")
        if not (r_base <= new_r <= r_top):
            raise ParseError(f"compile-time asm '{word.name}' corrupted return stack pointer", code="ct-asm-failed")

        def _unmarshal_stack(sp: int, top: int, table: _CTHandleTable) -> List[Any]:
            if sp == top:
                return []
            values: List[Any] = []
            objects = table.objects
            addr = top - 8
            while addr >= sp:
                raw = ctypes.c_int64.from_address(addr).value
                if raw in objects:
                    values.append(objects[raw])
                    # A string-mode pair still intact (the length cell right
                    # above its address) is one string again.  A string
                    # outside string mode is a single handle cell.
                    length = string_pairs.get(raw)
                    if (length is not None and addr - 8 >= sp
                            and ctypes.c_int64.from_address(addr - 8).value == length):
                        addr -= 8
                else:
                    values.append(raw)
                addr -= 8
            return values

        self.stack = _unmarshal_stack(new_d, d_top, handles)
        self.return_stack = _unmarshal_stack(new_r, r_top, handles)

    def _run_asm_on_ints(self, word: Word, asm_body: str) -> bool:
        """_run_asm_definition when both stacks hold only integers; False
        (nothing done) otherwise.  Same layout as the general path: each
        stack's cells end at the top of its buffer with 16 spare cells below,
        the same pointer checks, handle values mapped back to their objects.
        The buffers are reused between calls and filled with slice copies (a
        non-integer value makes ctypes reject the copy: general path)."""
        data, rets = self.stack, self.return_stack
        nd, nr = len(data), len(rets)
        buffers = self._asm_int_buffers
        if buffers is None or buffers[1] < nd + 16 or buffers[4] < nr + 16:
            c_int64 = ctypes.c_int64
            d_cap = max(nd + 16, 256, 2 * buffers[1] if buffers else 0)
            r_cap = max(nr + 16, 256, 2 * buffers[4] if buffers else 0)
            d_arr = (c_int64 * d_cap)()
            r_arr = (c_int64 * r_cap)()
            outs = (ctypes.c_uint64 * 2)()
            buffers = self._asm_int_buffers = (
                d_arr, d_cap, ctypes.addressof(d_arr), r_arr, r_cap, ctypes.addressof(r_arr),
                outs, ctypes.addressof(outs),
            )
        d_arr, d_cap, d_addr, r_arr, r_cap, r_addr, outs, outs_addr = buffers
        try:
            if nd:
                d_arr[d_cap - nd:d_cap] = data[::-1]
            if nr:
                r_arr[r_cap - nr:r_cap] = rets[::-1]
        except TypeError:
            return False
        func = _ct_asm_static_func(word.name, asm_body)
        if func is None:
            func, _code_buf = self._ct_asm_compile(word, asm_body, 0, 0)
        d_top, r_top = d_addr + d_cap * 8, r_addr + r_cap * 8
        func(d_top - nd * 8, r_top - nr * 8, outs_addr, outs_addr + 8)
        new_d, new_r = outs[0], outs[1]
        if not (d_top - (nd + 16) * 8 <= new_d <= d_top):
            raise ParseError(f"compile-time asm '{word.name}' corrupted data stack pointer", code="ct-asm-failed")
        if not (r_top - (nr + 16) * 8 <= new_r <= r_top):
            raise ParseError(f"compile-time asm '{word.name}' corrupted return stack pointer", code="ct-asm-failed")
        values = d_arr[(new_d - d_addr) // 8:d_cap][::-1]
        returns = r_arr[(new_r - r_addr) // 8:r_cap][::-1]
        objects = self._handles.objects
        if objects:
            values = [objects.get(raw, raw) for raw in values]
            returns = [objects.get(raw, raw) for raw in returns]
        self.stack = values
        self.return_stack = returns
        return True

    def _match_select(self, spec: _MatchSpec) -> str:
        """Test the clauses of a `match` against the parser's input in order,
        without consuming; consume the first match, bind its captures, and
        return its body label.  The default clause consumes nothing."""
        parser = self.parser
        if not parser._parsing:
            raise ParseError("match needs an active compiler input stream", code="emit-no-input")
        source = _MatchInput(parser, parser.pos)
        for pattern, label in spec.clauses:
            result = _match_sequence(pattern.elements, 0, 0, source, {})
            if result is None:
                continue
            count, bindings = result
            if count:
                consumed = source.values[count - 1][1]
                parser.pos = consumed
                parser._last_token = parser.tokens[consumed - 1]
            self._enter_bindings(bindings)
            return label
        values = [source.get(i) for i in range(4)]
        values = [v for v in values if v is not None]
        if spec.default_label is not None:
            self._enter_bindings({})
            return spec.default_label
        upcoming = " ".join(repr(v) if isinstance(v, Syntax) else v.lexeme for v, _ in values[:4]) or "end of input"
        raise ParseError(f"no match clause fits the input ({upcoming}) and there is no '[_]' default",
                         code="match-no-clause", origin=_origin_from_location(self.current_location))

    def _enter_bindings(self, bindings: Dict[str, Any]) -> None:
        self._binding_stack.append(self.binding_env)
        env = dict(self.binding_env) if self.binding_env else {}
        env.update(bindings)
        self.binding_env = env

    def _evaluate_quotation(self, template: _QuotationTemplate) -> Syntax:
        """The Syntax value of a quotation: literal Tokens as written, with
        each `$name` splice replaced by its bound Token or Syntax and each
        `$(expr)` unquote by its value (taken from the data stack)."""
        if not template.has_splices:
            return Syntax(part[1] for part in template.parts)
        unquoted: List[Any] = []
        if template.unquotes:
            count = template.unquotes
            values = self._unquote_values
            if len(values) < count:
                raise ParseError(f"quotation needs {count} unquote value(s), {len(values)} available",
                                 code="internal-ct-vm")
            unquoted = values[-count:]
            del values[-count:]
        tokens: List[Token] = []
        self._expand_quotation_parts(template.parts, self.binding_env, unquoted, [0], tokens)
        return Syntax(tokens)

    def _expand_quotation_parts(self, parts: Sequence[Tuple[Any, ...]], env: Optional[Dict[str, Any]],
                                unquoted: List[Any], unquote_index: List[int], tokens: List[Token]) -> None:
        for part in parts:
            kind = part[0]
            if kind == "token":
                tokens.append(part[1])
                continue
            if kind == "unquote":
                _, prefix, suffix, marker = part
                tokens.extend(_unquote_tokens(unquoted[unquote_index[0]], prefix, suffix, marker))
                unquote_index[0] += 1
                continue
            if kind == "rep":
                self._expand_repetition(part, env, unquoted, unquote_index, tokens)
                continue
            _, name, marker, bound = part
            if not bound or env is None or name not in env:
                marker_origin = self.parser._token_origin(marker)
                related = ([("splice", f"'${name}' written here", marker_origin)]
                           if marker_origin is not None else [])
                raise ParseError(f"unbound '${name}' in quotation", code="syntax-binding-unbound",
                                 related=related)
            value = env[name]
            if isinstance(value, Token):
                tokens.append(value)
            elif isinstance(value, Syntax):
                tokens.extend(value.tokens)
            elif isinstance(value, list):
                raise ParseError(f"'${name}' is repeated (bound by a $( )* group); splice it inside $( ... )*",
                                 code="syntax-splice-invalid")
            else:
                raise ParseError(f"'${name}' is a {_ct_type_name(value)}; only a Token or Syntax can be spliced",
                                 code="syntax-splice-invalid")

    def _expand_repetition(self, part: Tuple[Any, ...], env: Optional[Dict[str, Any]], unquoted: List[Any],
                           unquote_index: List[int], tokens: List[Token]) -> None:
        """`$( ... )*` in a quotation: the parts once per element of the
        repeated (list-bound) names they use, with the separator between."""
        _, inner, separator, minimum, marker = part
        names: List[str] = []
        _quotation_splice_names(inner, names)
        repeated = {name: env[name] for name in names if env is not None and isinstance(env.get(name), list)}
        if not repeated:
            raise ParseError("$( ... )* repeats nothing: it uses no binding from a repetition group",
                             code="syntax-splice-invalid")
        lengths = {len(values) for values in repeated.values()}
        if len(lengths) != 1:
            detail = ", ".join(f"${name}: {len(values)}" for name, values in repeated.items())
            raise ParseError(f"$( ... )* repeats bindings of different lengths ({detail})",
                             code="syntax-splice-invalid")
        count = lengths.pop()
        if count < minimum:
            raise ParseError("$( ... )+ needs at least one repetition", code="syntax-splice-invalid")
        for index in range(count):
            if index and separator is not None:
                tokens.append(_derive_token(marker, separator))
            local = dict(env) if env else {}
            for name, values in repeated.items():
                local[name] = values[index]
            self._expand_quotation_parts(inner, local, unquoted, unquote_index, tokens)

    def _call_word_by_name(self, name: str) -> None:
        word = None
        if name == "emit" and not self.runtime_mode:
            word = self.dictionary.baselines.get("emit")
        if word is None:
            word = self.dictionary.lookup(name)
        if word is None:
            raise ParseError(f"unknown word '{name}' during compile-time execution", code="ct-word-unavailable")
        self._call_word(word)

    def _resolve_words_in_body(self, defn: Definition) -> None:
        """Pre-resolve word name -> Word objects on Op nodes (once per Definition)."""
        # In runtime mode we may need a second pass to bind `exit` to the real
        # runtime word instead of treating it as a structural keyword.
        generation = self.dictionary.generation
        resolved = defn._words_resolved
        if resolved is not False and resolved != generation:
            # A name's selected word changed since this body was resolved.
            for node in defn.body:
                if node._opcode == OP_WORD:
                    node._word_ref = None
            defn._merged_runs = None
            if self.runtime_mode and self._jit_cache:
                self._jit_cache.clear()
            resolved = False
        if resolved is not False and not self.runtime_mode:
            return
        lookup = self.dictionary.lookup
        for node in defn.body:
            if node._opcode == OP_WORD and node._word_ref is None:
                name = str(node.data)
                # Skip structural keywords that _execute_nodes handles inline
                if name == "get_addr":
                    continue
                if name == "exit" and not self.runtime_mode:
                    continue
                if name == "emit" and not self.runtime_mode:
                    # At compile time `emit` is always the built-in splice,
                    # so a user's (runtime) `emit` never changes a macro.
                    ref = self.dictionary.baselines.get("emit") or lookup(name)
                    node._word_ref = ref
                    continue
                ref = lookup(name)
                if ref is not None:
                    node._word_ref = ref
        defn._words_resolved = generation

    def _prepare_definition(self, defn: Definition) -> Tuple[Dict[str, int], Dict[int, int]]:
        """Return (label_positions, for_pairs), cached on the Definition."""
        if defn._label_positions is None:
            lp, fp = self._analyze_nodes(defn.body)
            defn._label_positions = lp
            defn._for_pairs = fp
        self._resolve_words_in_body(defn)
        if self.runtime_mode:
            # Merged JIT runs are a performance optimization, but have shown
            # intermittent instability on some environments. Keep them opt-in.
            if os.environ.get("L2_CT_MERGED_JIT", "0") == "1":
                if defn._merged_runs is None:
                    defn._merged_runs = self._find_mergeable_runs(defn)
            else:
                defn._merged_runs = {}
        return defn._label_positions, defn._for_pairs

    def _find_mergeable_runs(self, defn: Definition) -> Dict[int, Tuple[int, str]]:
        """Find consecutive runs of JIT-able asm word ops (length >= 2)."""
        runs: Dict[int, Tuple[int, str]] = {}
        body = defn.body
        n = len(body)
        i = 0
        while i < n:
            # Start of a potential run
            if body[i]._opcode == OP_WORD and body[i]._word_ref is not None:
                w = body[i]._word_ref
                if (w.runtime_intrinsic is None and isinstance(w.definition, AsmDefinition)
                        and not w.compile_time_override):
                    run_start = i
                    run_words = [w.name]
                    i += 1
                    while i < n and body[i]._opcode == OP_WORD and body[i]._word_ref is not None:
                        w2 = body[i]._word_ref
                        if (w2.runtime_intrinsic is None and isinstance(w2.definition, AsmDefinition)
                                and not w2.compile_time_override):
                            run_words.append(w2.name)
                            i += 1
                        else:
                            break
                    if len(run_words) >= 2:
                        key = f"__merged_{defn.name}_{run_start}_{i}"
                        runs[run_start] = (i, key)
                    continue
            i += 1
        return runs

    def _compile_merged_jit(self, words: List[Word], cache_key: str) -> Any:
        """Compile multiple asm word bodies into a single JIT function."""
        bss = self._bss_symbols

        lines: List[str] = []
        # Entry wrapper (same as _compile_jit)
        lines.extend([
            "_ct_entry:",
            "    push rbx",
            "    push r12",
            "    push r13",
            "    push r14",
            "    push r15",
            "    sub rsp, 16",
            "    mov [rsp], rdx",
            "    mov r12, rdi",
            "    mov r13, rsi",
        ])

        # Append each word's asm body, with labels uniquified
        for word_idx, word in enumerate(words):
            defn = word.definition
            asm_body = defn.body.strip("\n")
            prefix = f"_m{word_idx}_"

            # Collect all labels in this asm body first
            local_labels: Set[str] = set()
            for raw_line in asm_body.splitlines():
                line = raw_line.strip()
                lm = _RE_LABEL_PAT.match(line)
                if lm:
                    local_labels.add(lm.group(1))

            for raw_line in asm_body.splitlines():
                line = raw_line.strip()
                if not line or line.startswith(";"):
                    continue
                if line.startswith("extern"):
                    continue
                if line == "ret":
                    # Last word: jmp to save; others: fall through
                    if word_idx < len(words) - 1:
                        continue  # just skip ret -> fall through
                    else:
                        line = "jmp _ct_save"

                # Replace all references to local labels with prefixed versions
                for label in local_labels:
                    # Use word-boundary replacement to avoid partial matches
                    line = re.sub(rf'(?<!\w){re.escape(label)}(?=\s|:|,|$|\]|\))', prefix + label, line)

                # Patch [rel SYMBOL] -> concrete address
                rel_expr = self._resolve_rel_symbol_expression(line, bss)
                if rel_expr is not None:
                    if line.lstrip().startswith("lea"):
                        line = _RE_REL_TO_RIP_PAT.sub(rel_expr, line).replace("lea", "mov", 1)
                    else:
                        self._emit_rel_symbol_patch(lines, line, rel_expr)
                        continue

                if self._patch_direct_word_call(lines, line, "__merged__", local_labels):
                    continue
                # Convert NASM 'rel' to explicit rip-relative for Keystone
                line = _normalize_rel_to_rip(line)
                lines.append(f"    {line}")

        # Save epilog
        lines.extend([
            "_ct_save:",
            "    mov rax, [rsp]",
            "    mov [rax], r12",
            "    mov [rax + 8], r13",
            "    add rsp, 16",
            "    pop r15",
            "    pop r14",
            "    pop r13",
            "    pop r12",
            "    pop rbx",
            "    ret",
        ])

        # Normalize for Keystone
        def _norm(l: str) -> str:
            l = l.split(";", 1)[0].rstrip()
            for sz in ("qword", "dword", "word", "byte"):
                l = l.replace(f"{sz} [", f"{sz} ptr [")
            return l
        normalized = [_norm(l) for l in lines if _norm(l).strip()]

        try:
            code = _x86_assemble("\n".join(normalized))
        except KsError as exc:
            debug_txt = "\n".join(normalized)
            raise ParseError(
                f"JIT merged assembly failed for '{cache_key}': {exc}\n--- asm ---\n{debug_txt}\n--- end ---",
                code="ct-jit-failed",
            ) from exc
        if code is None:
            raise ParseError("keystone-engine is required for JIT execution", code="ct-jit-failed")
        if not code:
            raise ParseError(f"JIT merged produced no code for '{cache_key}'", code="ct-jit-failed")

        page_size = max(len(code), 4096)
        _libc = ctypes.CDLL(None, use_errno=True)
        _libc.mmap.restype = ctypes.c_void_p
        _libc.mmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int,
                                ctypes.c_int, ctypes.c_int, ctypes.c_long]
        PROT_RWX = 0x1 | 0x2 | 0x4
        MAP_PRIVATE = 0x02
        MAP_ANONYMOUS = 0x20
        ptr = _libc.mmap(None, page_size, PROT_RWX,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)
        if ptr == ctypes.c_void_p(-1).value or ptr is None:
            raise RuntimeError(f"mmap failed for merged JIT code ({page_size} bytes)")
        ctypes.memmove(ptr, code, len(code))
        self._jit_code_pages.append((ptr, page_size))
        return self._JIT_FUNC_TYPE(ptr)

    def _execute_nodes(self, nodes: Sequence[Op], *, _defn: Optional[Definition] = None) -> None:
        _runtime_mode = self.runtime_mode
        # Use cached analysis if we have one, else compute fresh.  A prepared
        # body whose words were resolved in the current dictionary generation
        # needs nothing from _prepare_definition at compile time.
        if _defn is not None:
            resolved = _defn._words_resolved
            if (not _runtime_mode and _defn._label_positions is not None and resolved is not False
                    and resolved == self.dictionary.generation):
                label_positions = _defn._label_positions
                loop_pairs = _defn._for_pairs
            else:
                label_positions, loop_pairs = self._prepare_definition(_defn)
        else:
            label_positions, loop_pairs = self._analyze_nodes(nodes)
        prev_loop_stack = self.loop_stack
        self.loop_stack = []
        prev_binding_env = self.binding_env
        prev_binding_depth = len(self._binding_stack)

        # Local variable aliases for hot-path speedup (bound methods are built
        # once per VM).
        bound = self._exec_bound
        if bound is None or bound[0].__self__ is not self:
            bound = self._exec_bound = (
                self.push, self.pop, self.pop_int, self.push_return, self.pop_return,
                self.peek_return, self.poke_return, self._call_word,
            )
        _push, _pop, _pop_int, _push_return, _pop_return, _peek_return, _poke_return, _call_word = bound
        _AsmDef = AsmDefinition
        _Definition = Definition
        _ct_native_by_body = _CT_NATIVE_BY_BODY
        _MISSING = _CT_NATIVE_MISSING

        if _runtime_mode:
            _ct_fast_dispatch = None
            # Hot JIT-call locals (avoid repeated attribute access)
            _jit_cache = self._jit_cache
            _jit_out2 = self._jit_out2
            _jit_out2_addr = self._jit_out2_addr
            _compile_jit = self._compile_jit
            _compile_merged = self._compile_merged_jit
            _merged_runs = _defn._merged_runs if _defn is not None and _defn._merged_runs else None
            # Inline ctypes for runtime mode — eliminates per-op function call overhead
            _c_int64_at = ctypes.c_int64.from_address
            _I64_MASK = 0xFFFFFFFFFFFFFFFF
            _I64_SIGN = 0x8000000000000000
            _I64_WRAP = 0x10000000000000000
            _store_string = self.memory.store_string
        else:
            _ct_fast_dispatch = _CT_FAST_CT_INTRINSIC_DISPATCH
            _jit_cache = _jit_out2 = _compile_jit = _compile_merged = _merged_runs = None
            _jit_out2_addr = 0
            _c_int64_at = _I64_MASK = _I64_SIGN = _I64_WRAP = _store_string = None  # type: ignore[assignment]

        ip = 0
        prev_location = self.current_location
        # Local opcode constants (avoid global dict lookup)
        _OP_WORD = OP_WORD
        _OP_LITERAL = OP_LITERAL
        _OP_WORD_PTR = OP_WORD_PTR
        _OP_FOR_BEGIN = OP_FOR_BEGIN
        _OP_FOR_END = OP_FOR_END
        _OP_BRANCH_ZERO = OP_BRANCH_ZERO
        _OP_JUMP = OP_JUMP
        _OP_LABEL = OP_LABEL
        _OP_LIST_BEGIN = OP_LIST_BEGIN
        _OP_RET = OP_RET
        _OP_LIST_END = OP_LIST_END
        _OP_LIST_LITERAL = OP_LIST_LITERAL
        try:
            while ip < len(nodes):
                _node = nodes[ip]
                kind = _node._opcode

                if kind == _OP_WORD:
                    # Merged JIT run: call one combined function for N words
                    if _merged_runs is not None:
                        run_info = _merged_runs.get(ip)
                        if run_info is not None:
                            end_ip, cache_key = run_info
                            func = _jit_cache.get(cache_key)
                            if func is None:
                                hit_key = cache_key + "_hits"
                                hits = _jit_cache.get(hit_key, 0) + 1
                                _jit_cache[hit_key] = hits
                                if hits >= 2:
                                    run_words = [nodes[j]._word_ref for j in range(ip, end_ip)]
                                    func = _compile_merged(run_words, cache_key)
                                    _jit_cache[cache_key] = func
                            if func is not None:
                                func(self.r12, self.r13, _jit_out2_addr)
                                self.r12 = _jit_out2[0]
                                self.r13 = _jit_out2[1]
                                ip = end_ip
                                continue

                    # Fast path: pre-resolved word reference
                    word = _node._word_ref
                    if word is not None:
                        if not _runtime_mode and _ct_fast_dispatch is not None:
                            fast_intrinsic = _ct_fast_dispatch.get(word.name)
                            if (
                                fast_intrinsic is not None
                                and word.compile_time_intrinsic is fast_intrinsic
                                and not word.compile_time_override
                                and not word.immediate
                            ):
                                self.current_location = _node.loc
                                self.call_stack.append(word.name)
                                try:
                                    fast_intrinsic(self)
                                except _CTVMJump as jmp:
                                    self.call_stack.pop()
                                    ip = jmp.target_ip
                                    continue
                                except _CTVMReturn:
                                    self.call_stack.pop()
                                    return
                                except ParseError as exc:
                                    self.call_stack.pop()
                                    raise _rewrap_error(
                                        exc, CompileTimeError, default_code="ct-word-failed",
                                        fallback_origin=_origin_from_location(self.current_location),
                                        notes=[f"compile-time stack: {' -> '.join(self.call_stack + [word.name])}"],
                                    ) from None
                                except Exception as exc:
                                    self.call_stack.pop()
                                    raise _rewrap_error(
                                        exc, CompileTimeError,
                                        message=f"compile-time failure in '{word.name}': {exc}",
                                        notes=[f"compile-time stack: {' -> '.join(self.call_stack + [word.name])}"],
                                    ) from None
                                else:
                                    self.call_stack.pop()
                                ip += 1
                                continue

                        if _runtime_mode:
                            ri = word.runtime_intrinsic
                            if ri is not None:
                                self.call_stack.append(word.name)
                                try:
                                    ri(self)
                                except _CTVMJump as jmp:
                                    self.call_stack.pop()
                                    ip = jmp.target_ip
                                    continue
                                except _CTVMReturn:
                                    self.call_stack.pop()
                                    return
                                finally:
                                    if self.call_stack and self.call_stack[-1] == word.name:
                                        self.call_stack.pop()
                                ip += 1
                                continue
                            defn = word.definition
                            if isinstance(defn, _AsmDef):
                                wn = word.name
                                func = _jit_cache.get(wn)
                                if func is None:
                                    func = _compile_jit(word)
                                    _jit_cache[wn] = func
                                func(self.r12, self.r13, _jit_out2_addr)
                                self.r12 = _jit_out2[0]
                                self.r13 = _jit_out2[1]
                                ip += 1
                                continue
                            # Whole-word JIT for Definition bodies
                            ck = "__defn_jit_" + word.name
                            jf = _jit_cache.get(ck)
                            if jf is None and _jit_cache.get(ck + "_miss") is None:
                                jf = self._compile_definition_jit(word)
                                if jf is not None:
                                    _jit_cache[ck] = jf
                                    _jit_cache[ck + "_addr"] = ctypes.cast(jf, ctypes.c_void_p).value
                                else:
                                    _jit_cache[ck + "_miss"] = True
                            if jf is not None:
                                jf(self.r12, self.r13, _jit_out2_addr)
                                self.r12 = _jit_out2[0]
                                self.r13 = _jit_out2[1]
                                ip += 1
                                continue
                        self.current_location = _node.loc
                        if not _runtime_mode:
                            # An :asm word with a Python equivalent (+, <, ==,
                            # ...) on integers: run the equivalent directly.
                            # Anything it declines (strings, other values) or
                            # raises on goes through _call_word, which repeats
                            # the attempt on the unchanged stack, so results,
                            # errors and events are those of the full call.
                            defn = word.definition
                            if (isinstance(defn, _AsmDef)
                                    and word.macro_def is None
                                    and not word.runtime_only
                                    and (word.compile_time_override or word.compile_time_intrinsic is None)):
                                equivalent = _ct_native_by_body.get(defn.body, _MISSING)
                                if equivalent is _MISSING:
                                    equivalent = _ct_native_equivalent(defn.body)
                                if equivalent is not None:
                                    bus = self.parser.event_bus
                                    if bus is None or not (bus.wants("ct.execute.begin")
                                                           or bus.wants("ct.execute.end")):
                                        try:
                                            done = equivalent(self.stack)
                                        except Exception:
                                            done = False
                                        if done:
                                            ip += 1
                                            continue
                            elif (isinstance(defn, _Definition)
                                    and word.macro_def is None
                                    and word.compile_time_intrinsic is None
                                    and not word.runtime_only
                                    and not word.compile_only):
                                try:
                                    _call_word(word, True)
                                except _CTVMJump as jmp:
                                    ip = jmp.target_ip
                                    continue
                                except _CTVMReturn:
                                    return
                                ip += 1
                                continue
                        try:
                            _call_word(word)
                        except _CTVMJump as jmp:
                            ip = jmp.target_ip
                            continue
                        except _CTVMReturn:
                            return
                        ip += 1
                        continue

                    # Structural keywords or unresolved words
                    name = _node.data
                    if name == "exit":
                        if _runtime_mode:
                            exit_word = self.dictionary.lookup("exit")
                            if exit_word is not None and exit_word.runtime_intrinsic is not None:
                                self.current_location = _node.loc
                                _call_word(exit_word)
                                ip += 1
                                continue
                        return
                    if _runtime_mode and name == "get_addr":
                        r12 = self.r12 - 8
                        _c_int64_at(r12).value = ip + 1
                        self.r12 = r12
                        ip += 1
                        continue
                    self.current_location = _node.loc
                    w = self.dictionary.lookup(name)
                    if w is None:
                        raise ParseError(f"unknown word '{name}' during compile-time execution", code="ct-word-unavailable")
                    try:
                        _call_word(w)
                    except _CTVMJump as jmp:
                        ip = jmp.target_ip
                        continue
                    except _CTVMReturn:
                        return
                    ip += 1
                    continue

                if kind == _OP_LITERAL:
                    if _runtime_mode:
                        data = _node.data
                        if isinstance(data, str):
                            addr, length = _store_string(data)
                            r12 = self.r12 - 16
                            _c_int64_at(r12 + 8).value = addr
                            _c_int64_at(r12).value = length
                            self.r12 = r12
                        elif isinstance(data, float):
                            r12 = self.r12 - 8
                            bits = _get_struct().unpack("q", _get_struct().pack("d", float(data)))[0]
                            _c_int64_at(r12).value = bits
                            self.r12 = r12
                        else:
                            r12 = self.r12 - 8
                            v = int(data) & _I64_MASK
                            if v >= _I64_SIGN:
                                v -= _I64_WRAP
                            _c_int64_at(r12).value = v
                            self.r12 = r12
                    else:
                        data = _node.data
                        # A float is its IEEE-754 bit pattern, as at runtime.
                        _push(_float_bits(data) if type(data) is float else data)
                    ip += 1
                    continue

                if kind == _OP_FOR_END:
                    if not self.loop_stack:
                        raise ParseError("'next' without matching 'for'", code="ct-control-flow-invalid")
                    frame = self.loop_stack[-1]
                    if not isinstance(frame, dict):
                        raise ParseError("internal loop bookkeeping error", code="internal-ct-vm")
                    begin_ip = int(frame.get("begin_ip", -1))
                    if begin_ip < 0:
                        raise ParseError("internal loop bookkeeping error", code="internal-ct-vm")
                    if _runtime_mode:
                        val = _c_int64_at(self.r13).value - 1
                        _c_int64_at(self.r13).value = val
                        frame["remaining"] = int(val)
                        if val > 0:
                            ip = begin_ip + 1
                            continue
                        self.r13 += 8
                    else:
                        val = _peek_return() - 1
                        _poke_return(val)
                        frame["remaining"] = int(val)
                        if val > 0:
                            ip = begin_ip + 1
                            continue
                        _pop_return()
                    self.loop_stack.pop()
                    ip += 1
                    continue

                if kind == _OP_FOR_BEGIN:
                    if _runtime_mode:
                        count = _c_int64_at(self.r12).value
                        self.r12 += 8
                        if count <= 0:
                            match = loop_pairs.get(ip)
                            if match is None:
                                raise ParseError("internal loop bookkeeping error", code="internal-ct-vm")
                            ip = match + 1
                            continue
                        r13 = self.r13 - 8
                        v = count & _I64_MASK
                        if v >= _I64_SIGN:
                            v -= _I64_WRAP
                        _c_int64_at(r13).value = v
                        self.r13 = r13
                    else:
                        count = _pop_int()
                        if count <= 0:
                            match = loop_pairs.get(ip)
                            if match is None:
                                raise ParseError("internal loop bookkeeping error", code="internal-ct-vm")
                            ip = match + 1
                            continue
                        _push_return(count)
                    self.loop_stack.append(
                        {
                            "begin_ip": int(ip),
                            "initial": int(count),
                            "remaining": int(count),
                        }
                    )
                    ip += 1
                    continue

                if kind == _OP_BRANCH_ZERO:
                    if _runtime_mode:
                        condition = _c_int64_at(self.r12).value
                        self.r12 += 8
                        if condition == 0:
                            ip = label_positions.get(str(_node.data), -1)
                            if ip == -1:
                                raise ParseError(f"unknown label during compile-time execution", code="ct-control-flow-invalid")
                        else:
                            ip += 1
                    else:
                        condition = _pop()
                        if isinstance(condition, bool):
                            flag = condition
                        elif isinstance(condition, int):
                            flag = condition != 0
                        else:
                            raise ParseError("branch expects integer or boolean condition", code="ct-control-flow-invalid")
                        if not flag:
                            ip = label_positions.get(str(_node.data), -1)
                            if ip == -1:
                                raise ParseError(f"unknown label during compile-time execution", code="ct-control-flow-invalid")
                        else:
                            ip += 1
                    continue

                if kind == _OP_JUMP:
                    ip = label_positions.get(str(_node.data), -1)
                    if ip == -1:
                        raise ParseError(f"unknown label during compile-time execution", code="ct-control-flow-invalid")
                    continue

                if kind == _OP_LABEL:
                    ip += 1
                    continue

                if kind == _OP_WORD_PTR:
                    target_name = str(_node.data)
                    target_word = self.dictionary.lookup(target_name)
                    if target_word is None:
                        raise ParseError(
                            f"unknown word '{target_name}' referenced by pointer during compile-time execution",
                            code="ct-word-unavailable",
                        )
                    if _runtime_mode:
                        # Push native code address so asm can jmp/call it
                        addr = self._compile_raw_jit(target_word)
                        _push(addr)
                        # Store reverse mapping so _rt_jmp can resolve back to Word
                        self._handles.objects[addr] = target_word
                    else:
                        _push(self._handles.store(target_word))
                    ip += 1
                    continue

                if kind == _OP_LIST_BEGIN:
                    if _runtime_mode:
                        self._list_capture_stack.append(self.r12)
                    else:
                        self._list_capture_stack.append(len(self.stack))
                    ip += 1
                    continue

                if kind == _OP_LIST_LITERAL:
                    values = list(_node.data or [])
                    count = len(values)
                    buf_size = (count + 1) * 8
                    addr = self.memory.allocate(buf_size)
                    CTMemory.write_qword(addr, count)
                    for idx_item, val in enumerate(values):
                        CTMemory.write_qword(addr + 8 + idx_item * 8, int(val))
                    _push(addr)
                    ip += 1
                    continue

                if kind == OP_BSS_LIST_LITERAL:
                    payload = _node.data if isinstance(_node.data, dict) else {}
                    count = int(payload.get("size", 0))
                    values = list(payload.get("values", []) or [])
                    if count < 0:
                        raise ParseError("bss list size must be >= 0", code="ct-argument-invalid")
                    if len(values) > count:
                        raise ParseError("bss list has more initializer values than declared size", code="ct-argument-invalid")
                    buf_size = (count + 1) * 8
                    addr = self.memory.allocate(buf_size)
                    CTMemory.write_qword(addr, count)
                    for idx_item, val in enumerate(values):
                        CTMemory.write_qword(addr + 8 + idx_item * 8, int(val))
                    for idx_item in range(len(values), count):
                        CTMemory.write_qword(addr + 8 + idx_item * 8, 0)
                    _push(addr)
                    ip += 1
                    continue

                if kind == _OP_LIST_END:
                    if not self._list_capture_stack:
                        raise ParseError("']' without matching '['", code="ct-control-flow-invalid")
                    saved = self._list_capture_stack.pop()
                    if _runtime_mode:
                        items: List[int] = []
                        ptr = saved - 8
                        while ptr >= self.r12:
                            items.append(_c_int64_at(ptr).value)
                            ptr -= 8
                        self.r12 = saved
                    else:
                        items = self.stack[saved:]
                        del self.stack[saved:]
                    count = len(items)
                    buf_size = (count + 1) * 8
                    addr = self.memory.allocate(buf_size)
                    CTMemory.write_qword(addr, count)
                    for idx_item, val in enumerate(items):
                        CTMemory.write_qword(addr + 8 + idx_item * 8, val)
                    _push(addr)
                    ip += 1
                    continue

                if kind == _OP_RET:
                    return

                if kind == OP_MATCH_SELECT:
                    if _runtime_mode:
                        self.current_location = _node.loc
                        raise ParseError("match is compile-time only", code="match-runtime")
                    self.current_location = _node.loc
                    target = self._match_select(_node.data)
                    ip = label_positions.get(target, -1)
                    if ip == -1:
                        raise ParseError("unknown match clause label", code="internal-ct-vm")
                    continue

                if kind == OP_MATCH_LEAVE:
                    self.binding_env = self._binding_stack.pop() if self._binding_stack else None
                    ip += 1
                    continue

                if kind == OP_BINDING:
                    env = self.binding_env
                    name = _node.data
                    if env is None or name not in env:
                        self.current_location = _node.loc
                        raise ParseError(f"unbound '${name}'", code="syntax-binding-unbound")
                    _push(env[name])
                    ip += 1
                    continue

                if kind == OP_SYNTAX:
                    if _runtime_mode:
                        self.current_location = _node.loc
                        raise ParseError("a quotation is a compile-time value and cannot run in runtime code",
                                         code="syntax-quotation-runtime")
                    _push(self._evaluate_quotation(_node.data))
                    ip += 1
                    continue

                if kind == OP_FOR_DROP:
                    if not self.loop_stack:
                        raise ParseError("'break' without an active for loop", code="ct-control-flow-invalid")
                    self.loop_stack.pop()
                    if _runtime_mode:
                        self.r13 += 8
                    else:
                        _pop_return()
                    ip += 1
                    continue

                self.current_location = _node.loc
                raise ParseError(f"unsupported compile-time op (opcode={kind})", code="internal-ct-vm")
        finally:
            self.current_location = prev_location
            self.loop_stack = prev_loop_stack
            # A body left by exit, a jump, or an error drops its bindings.
            self.binding_env = prev_binding_env
            del self._binding_stack[prev_binding_depth:]

    def _analyze_nodes(self, nodes: Sequence[Op]) -> Tuple[Dict[str, int], Dict[int, int]]:
        """Single-pass analysis: returns (label_positions, for_pairs)."""
        label_positions: Dict[str, int] = {}
        for_pairs: Dict[int, int] = {}
        for_stack: List[int] = []
        for idx, node in enumerate(nodes):
            opc = node._opcode
            if opc == OP_LABEL:
                label_positions[str(node.data)] = idx
            elif opc == OP_FOR_BEGIN:
                for_stack.append(idx)
            elif opc == OP_FOR_END:
                if not for_stack:
                    raise ParseError("'next' without matching 'for'", code="ct-control-flow-invalid")
                begin_idx = for_stack.pop()
                for_pairs[begin_idx] = idx
                for_pairs[idx] = begin_idx
        if for_stack:
            raise ParseError("'for' without matching 'next'", code="ct-control-flow-invalid")
        return label_positions, for_pairs

    def _label_positions(self, nodes: Sequence[Op]) -> Dict[str, int]:
        positions: Dict[str, int] = {}
        for idx, node in enumerate(nodes):
            if node._opcode == OP_LABEL:
                positions[str(node.data)] = idx
        return positions

    def _for_pairs(self, nodes: Sequence[Op]) -> Dict[int, int]:
        stack: List[int] = []
        pairs: Dict[int, int] = {}
        for idx, node in enumerate(nodes):
            if node._opcode == OP_FOR_BEGIN:
                stack.append(idx)
            elif node._opcode == OP_FOR_END:
                if not stack:
                    raise ParseError("'next' without matching 'for'", code="ct-control-flow-invalid")
                begin_idx = stack.pop()
                pairs[begin_idx] = idx
                pairs[idx] = begin_idx
        if stack:
            raise ParseError("'for' without matching 'next'", code="ct-control-flow-invalid")
        return pairs

    def _jump_to_label(self, labels: Dict[str, int], target: str) -> int:
        if target not in labels:
            raise ParseError(f"unknown label '{target}' during compile-time execution", code="ct-control-flow-invalid")
        return labels[target]


# ---------------------------------------------------------------------------
# § 12. NASM emitter helpers
# ---------------------------------------------------------------------------


class Emission:
    __slots__ = ('text', 'data', 'bss', 'c_header', 'fragments')

    def __init__(self, text: List[str] = None, data: List[str] = None, bss: List[str] = None, c_header: str = "") -> None:
        self.text = text if text is not None else []
        self.data = data if data is not None else []
        self.bss = bss if bss is not None else []
        self.c_header = c_header
        # Set once CT fragments are added; plain line joins apply until then.
        self.fragments = False

    def text_byte_length(self) -> int:
        """Return UTF-8 byte length of the text section without building an intermediate string."""
        if self.fragments:
            return len(_join_asm_lines(self.text).encode("utf-8"))
        total = 0
        for index, line in enumerate(self.text):
            total += len(line.encode("utf-8"))
            if index:
                total += 1
        return total

    def snapshot_byte_length(self) -> int:
        """Return UTF-8 byte length of the full assembled output without joining the whole buffer."""
        if self.fragments:
            return len(self.snapshot().encode("utf-8"))
        total = 0
        for section in (self.text, self.data, self.bss):
            for index, line in enumerate(section):
                total += len(line.encode("utf-8"))
                if index:
                    total += 1
            if section:
                total += 1
        total += len("section .note.GNU-stack noalloc noexec nowrite".encode("utf-8")) + 1
        return total

    def snapshot(self) -> str:
        parts: List[str] = []
        if self.text:
            parts.extend(["section .text", *self.text])
        if self.data:
            parts.extend(["section .data", *self.data])
        if self.bss:
            parts.extend(["section .bss", *self.bss])
        parts.append("section .note.GNU-stack noalloc noexec nowrite")
        if self.fragments:
            return _join_asm_lines(parts)
        return "\n".join(parts)


_ASM_LABEL_ONLY_RE = re.compile(r"^\s*([A-Za-z0-9_.$@]+):\s*$")
_ASM_JUMP_RE = re.compile(r"^j([a-z]+)$", re.IGNORECASE)
_ASM_LABEL_NAME_RE = re.compile(r"^[A-Za-z0-9_.$@]+$")
_ASM_LEA_SELF_RE = re.compile(r"^\[\s*([A-Za-z0-9_.$@]+)\s*\]$")
_ASM_REL_LABEL_REF_RE = re.compile(r"(?:\brel\s+|\brip\s*\+\s*)([A-Za-z0-9_.$@]+)", re.IGNORECASE)
_ASM_INVERT_JCC: Dict[str, str] = {
    "je": "jne", "jne": "je", "jz": "jnz", "jnz": "jz",
    "jg": "jle", "jge": "jl", "jl": "jge", "jle": "jg",
    "ja": "jbe", "jae": "jb", "jb": "jae", "jbe": "ja",
    "jo": "jno", "jno": "jo", "js": "jns", "jns": "js",
    "jp": "jnp", "jnp": "jp",
}


def _split_asm_comment(line: str) -> Tuple[str, str]:
    if ";" not in line:
        return line.rstrip(), ""
    code, comment = line.split(";", 1)
    return code.rstrip(), comment


def _parse_asm_instruction(line: str) -> Optional[Tuple[str, List[str]]]:
    code, _ = _split_asm_comment(line)
    text = code.strip()
    if not text:
        return None
    if text.startswith("%"):
        return None
    if text.lower().startswith("section ") or text.lower().startswith("global ") or text.lower().startswith("extern "):
        return None
    if _ASM_LABEL_ONLY_RE.match(text):
        return None
    parts = text.split(None, 1)
    mnemonic = parts[0].lower()
    ops: List[str] = []
    if len(parts) > 1:
        ops = [p.strip() for p in parts[1].split(",") if p.strip()]
    return mnemonic, ops


def _render_instruction(mnemonic: str, operands: Sequence[str], original: str) -> str:
    indent = "    "
    m = re.match(r"^(\s+)", original)
    if m is not None:
        indent = m.group(1)
    if operands:
        return f"{indent}{mnemonic} " + ", ".join(operands)
    return f"{indent}{mnemonic}"


def _invert_jcc(mnemonic: str) -> Optional[str]:
    return _ASM_INVERT_JCC.get(mnemonic.lower())


def _compiler_source_fingerprint() -> str:
    """This compiler's source file (path and identity: size, modification
    time, change time, inode).  Any write changes it, so results cached by
    another version of the code are never reused."""
    try:
        identity = _file_identity(os.stat(__file__))
    except OSError:
        return "unknown"
    return f"{os.path.abspath(__file__)}:" + ":".join(map(str, identity))


# Results of the text peephole pass, keyed by the exact input text: in this
# process (a daemon worker keeps them for its jobs) and in a pack file, so
# compiling an unchanged program again skips the pass.  The pass is a pure
# function of its input, and the pack is tied to this compiler's source.
_PEEPHOLE_MEMO: "OrderedDict[bytes, Tuple[str, Dict[str, int]]]" = OrderedDict()
_PEEPHOLE_MEMO_LIMIT = 32
_PEEPHOLE_STORE = _CachePack("peephole", _compiler_source_fingerprint, 32 * 1024 * 1024)


def optimize_emitted_asm_text(
    asm_text: str,
    *,
    collect_pass_logs: bool = False,
) -> Tuple[str, Dict[str, int], List[str]]:
    """Run an extensive but conservative post-emission optimization pass."""
    if collect_pass_logs:
        return _optimize_emitted_asm_text_uncached(asm_text, collect_pass_logs=True)
    import hashlib
    digest = hashlib.blake2b(asm_text.encode("utf-8"), digest_size=16).digest()
    hit = _PEEPHOLE_MEMO.get(digest)
    if hit is None:
        packed = _PEEPHOLE_STORE.get(digest)
        if packed is not None:
            try:
                import zlib
                text, stats = json.loads(zlib.decompress(packed).decode("utf-8"))
                hit = (text, {str(k): int(v) for k, v in stats.items()})
            except Exception:
                hit = None
    if hit is None:
        text, stats, _logs = _optimize_emitted_asm_text_uncached(asm_text)
        hit = (text, dict(stats))
        try:
            import zlib
            _PEEPHOLE_STORE.add(digest, zlib.compress(json.dumps([text, stats]).encode("utf-8"), 6))
        except Exception:
            pass
    _PEEPHOLE_MEMO[digest] = hit
    _PEEPHOLE_MEMO.move_to_end(digest)
    while len(_PEEPHOLE_MEMO) > _PEEPHOLE_MEMO_LIMIT:
        _PEEPHOLE_MEMO.popitem(last=False)
    return hit[0], dict(hit[1]), []


def _optimize_emitted_asm_text_uncached(
    asm_text: str,
    *,
    collect_pass_logs: bool = False,
) -> Tuple[str, Dict[str, int], List[str]]:
    if not asm_text or not any(ch in asm_text for ch in (":", "jmp", "jz", "jnz", "je", "jne", "jg", "jge", "jl", "jle", "ja", "jae", "jb", "jbe")):
        return asm_text, {
            "removed_nops": 0,
            "removed_self_moves": 0,
            "removed_trivial_arith": 0,
            "removed_jump_to_next_label": 0,
            "threaded_jump_targets": 0,
            "removed_unreachable_after_terminator": 0,
            "inverted_conditional_branches": 0,
            "collapsed_redundant_jumps": 0,
            "removed_redundant_labels": 0,
            "collapsed_blank_runs": 0,
        }, []
    lines = asm_text.splitlines()
    _PARSE_SENTINEL = object()
    _parse_cache: Dict[str, object] = {}
    _is_code_cache: Dict[str, bool] = {}
    _label_only_cache: Dict[str, object] = {}
    _hint_cache: Dict[str, str] = {}
    _refs_cache: Dict[str, Tuple[str, ...]] = {}

    _PASS_A_CANDIDATES = {
        "nop", "mov", "xchg", "lea", "add", "sub", "or", "xor", "shl", "shr", "sar", "imul", "mul"
    }

    def _parse_cached(line: str) -> Optional[Tuple[str, List[str]]]:
        cached = _parse_cache.get(line, _PARSE_SENTINEL)
        if cached is _PARSE_SENTINEL:
            parsed = _parse_asm_instruction(line)
            _parse_cache[line] = parsed if parsed is not None else None
            return parsed
        return cached if cached is not None else None

    def _is_code_line(line: str) -> bool:
        cached = _is_code_cache.get(line)
        if cached is not None:
            return cached
        s = line.lstrip()
        is_code = bool(s and not s.startswith(";"))
        _is_code_cache[line] = is_code
        return is_code

    def _label_only(line: str) -> Optional[str]:
        cached = _label_only_cache.get(line, _PARSE_SENTINEL)
        if cached is _PARSE_SENTINEL:
            s = line.strip()
            label: Optional[str] = None
            if s.endswith(":"):
                candidate = s[:-1]
                if _ASM_LABEL_NAME_RE.match(candidate):
                    label = candidate
            _label_only_cache[line] = label if label is not None else None
            return label
        return cached if cached is not None else None

    def _instr_hint(line: str) -> str:
        """Best-effort mnemonic-like token for quick pass filtering."""
        cached = _hint_cache.get(line)
        if cached is not None:
            return cached
        s = line.lstrip()
        if not s or s.startswith(";") or s.startswith("%"):
            _hint_cache[line] = ""
            return ""
        end = 0
        n = len(s)
        while end < n and s[end] not in " \t;":
            end += 1
        tok = s[:end].lower()
        if not tok or tok.endswith(":"):
            tok = ""
        _hint_cache[line] = tok
        return tok

    stats: Dict[str, int] = {
        "removed_nops": 0,
        "removed_self_moves": 0,
        "removed_trivial_arith": 0,
        "removed_jump_to_next_label": 0,
        "threaded_jump_targets": 0,
        "removed_unreachable_after_terminator": 0,
        "inverted_conditional_branches": 0,
        "collapsed_redundant_jumps": 0,
        "removed_redundant_labels": 0,
        "collapsed_blank_runs": 0,
    }

    def _next_code_index(arr: Sequence[str], i: int) -> int:
        j = i
        while j < len(arr):
            if _is_code_line(arr[j]):
                return j
            j += 1
        return -1

    def _collect_label_positions(arr: Sequence[str]) -> Dict[str, int]:
        pos: Dict[str, int] = {}
        for idx, ln in enumerate(arr):
            label = _label_only(ln)
            if label is not None:
                pos[label] = idx
        return pos

    def _collect_referenced_labels(arr: Sequence[str]) -> Set[str]:
        """Precompute every label referenced by jumps/branches in a single scan."""
        refs: Set[str] = set()
        for ln in arr:
            line_refs = _refs_cache.get(ln)
            if line_refs is None:
                found: List[str] = []
                parsed = _parse_cached(ln)
                if parsed is not None:
                    for op in parsed[1]:
                        if _ASM_LABEL_NAME_RE.match(op):
                            found.append(op)
                        else:
                            for match in _ASM_REL_LABEL_REF_RE.finditer(op):
                                label = match.group(1)
                                if _ASM_LABEL_NAME_RE.match(label):
                                    found.append(label)
                line_refs = _refs_cache[ln] = tuple(found)
            if line_refs:
                refs.update(line_refs)
        return refs

    def _resolve_jmp_chain(target: str, arr: Sequence[str], lbl_pos: Dict[str, int]) -> str:
        seen: Set[str] = set()
        cur = target
        while cur not in seen:
            seen.add(cur)
            idx = lbl_pos.get(cur)
            if idx is None:
                return cur
            nxt = _next_code_index(arr, idx + 1)
            if nxt < 0:
                return cur
            if _instr_hint(arr[nxt]) != "jmp":
                return cur
            parsed = _parse_cached(arr[nxt])
            if parsed is None:
                return cur
            mnem, ops = parsed
            if mnem != "jmp" or len(ops) != 1 or not _ASM_LABEL_NAME_RE.match(ops[0]):
                return cur
            cur = ops[0]
        return target

    pass_logs: List[str] = []

    def _record_pass(round_no: int, pass_name: str, before: Dict[str, int], after: Dict[str, int]) -> None:
        if not collect_pass_logs:
            return
        delta_parts: List[str] = []
        for key in sorted(after):
            delta = after[key] - before.get(key, 0)
            if delta:
                delta_parts.append(f"{key}=+{delta}")
        if delta_parts:
            pass_logs.append(f"round {round_no} {pass_name}: " + ", ".join(delta_parts))
        else:
            pass_logs.append(f"round {round_no} {pass_name}: no changes")

    # Fixed-point optimization rounds.
    rounds_run = 0
    for round_idx in range(10):
        changed = False
        rounds_run = round_idx + 1

        # Pass A: local no-op/trivial arithmetic cleanup.
        _before_a = dict(stats)
        stage_a: List[str] = []
        for ln in lines:
            hint = _instr_hint(ln)
            if hint not in _PASS_A_CANDIDATES:
                stage_a.append(ln)
                continue
            parsed = _parse_cached(ln)
            if parsed is None:
                stage_a.append(ln)
                continue
            mnem, ops = parsed
            if mnem == "nop":
                stats["removed_nops"] += 1
                changed = True
                continue
            if mnem in ("mov", "xchg") and len(ops) == 2 and ops[0] == ops[1]:
                stats["removed_self_moves"] += 1
                changed = True
                continue
            if mnem == "lea" and len(ops) == 2:
                m_lea = _ASM_LEA_SELF_RE.match(ops[1])
                if m_lea is not None and m_lea.group(1) == ops[0]:
                    stats["removed_self_moves"] += 1
                    changed = True
                    continue
            if mnem in ("add", "sub", "or", "xor", "shl", "shr", "sar") and len(ops) == 2 and ops[1] in ("0", "0x0"):
                stats["removed_trivial_arith"] += 1
                changed = True
                continue
            if mnem in ("imul", "mul") and len(ops) == 2 and ops[1] in ("1", "0x1"):
                stats["removed_trivial_arith"] += 1
                changed = True
                continue
            stage_a.append(ln)
        lines = stage_a
        _record_pass(round_idx + 1, "A/local-cleanup", _before_a, stats)

        # Pass B: jump threading and jump-to-next-label elimination.
        _before_b = dict(stats)
        lbl_pos = _collect_label_positions(lines)
        for i, ln in enumerate(list(lines)):
            hint = _instr_hint(ln)
            if not hint or hint[0] != "j":
                continue
            parsed = _parse_cached(ln)
            if parsed is None:
                continue
            mnem, ops = parsed
            if len(ops) != 1 or not _ASM_LABEL_NAME_RE.match(ops[0]):
                continue
            if mnem == "jmp" or _ASM_JUMP_RE.match(mnem):
                old_target = ops[0]
                new_target = _resolve_jmp_chain(old_target, lines, lbl_pos)
                if new_target != old_target:
                    lines[i] = _render_instruction(mnem, [new_target], ln)
                    stats["threaded_jump_targets"] += 1
                    changed = True

                if mnem == "jmp":
                    j = _next_code_index(lines, i + 1)
                    if j >= 0:
                        label = _label_only(lines[j])
                        if label is not None and label == new_target:
                            lines[i] = ""
                            stats["removed_jump_to_next_label"] += 1
                            changed = True
        _record_pass(round_idx + 1, "B/jump-threading", _before_b, stats)

        # Pass C: remove unreachable instructions after unconditional terminators.
        _before_c = dict(stats)
        stage_c: List[str] = []
        unreachable = False
        for ln in lines:
            if _label_only(ln) is not None:
                unreachable = False
            if not _is_code_line(ln):
                stage_c.append(ln)
                continue
            parsed = _parse_cached(ln)
            if unreachable and parsed is not None:
                stage_c.append("")
                stats["removed_unreachable_after_terminator"] += 1
                changed = True
                continue
            stage_c.append(ln)
            if parsed is not None:
                mnem, _ops = parsed
                if mnem in ("jmp", "ret", "ud2"):
                    unreachable = True
        lines = stage_c
        _record_pass(round_idx + 1, "C/unreachable-prune", _before_c, stats)

        # Pass D: invert branch pattern: jcc L1 ; jmp L2 ; L1:
        _before_d = dict(stats)
        i = 0
        while i < len(lines):
            hint_i = _instr_hint(lines[i])
            if not hint_i or hint_i[0] != "j" or hint_i == "jmp":
                i += 1
                continue
            parsed = _parse_cached(lines[i])
            if parsed is None:
                i += 1
                continue
            mnem, ops = parsed
            inv = _invert_jcc(mnem)
            if inv is None or len(ops) != 1 or not _ASM_LABEL_NAME_RE.match(ops[0]):
                i += 1
                continue
            j = _next_code_index(lines, i + 1)
            if j < 0:
                i += 1
                continue
            if _instr_hint(lines[j]) != "jmp":
                i += 1
                continue
            parsed_j = _parse_cached(lines[j])
            if parsed_j is None or parsed_j[0] != "jmp" or len(parsed_j[1]) != 1:
                i += 1
                continue
            k = _next_code_index(lines, j + 1)
            if k < 0:
                i += 1
                continue
            label = _label_only(lines[k])
            if label is None or label != ops[0]:
                i += 1
                continue

            lines[i] = _render_instruction(inv, [parsed_j[1][0]], lines[i])
            lines[j] = ""
            stats["inverted_conditional_branches"] += 1
            changed = True
            i = k + 1
        _record_pass(round_idx + 1, "D/branch-invert", _before_d, stats)

        # Pass E: collapse duplicate adjacent labels and retarget branches.
        _before_e = dict(stats)
        # Skip expensive label-alias analysis when there are no adjacent labels.
        has_adjacent_labels = False
        prev_label_pending = False
        for _ln in lines:
            lbl = _label_only(_ln)
            if lbl is not None:
                if prev_label_pending:
                    has_adjacent_labels = True
                    break
                prev_label_pending = True
                continue
            s = _ln.strip()
            if not s or s.startswith(";"):
                continue
            prev_label_pending = False

        if not has_adjacent_labels:
            _record_pass(round_idx + 1, "E/label-collapse", _before_e, stats)
        else:
            alias: Dict[str, str] = {}
            referenced_labels = _collect_referenced_labels(lines)

            i = 0
            while i < len(lines):
                src_label = _label_only(lines[i])
                if src_label is None:
                    i += 1
                    continue
                j = i + 1
                while j < len(lines):
                    sj = lines[j].strip()
                    if not sj or sj.startswith(";"):
                        j += 1
                        continue
                    dst_label = _label_only(lines[j])
                    if dst_label is not None:
                        if src_label not in referenced_labels:
                            alias[src_label] = dst_label
                            lines[i] = ""
                            stats["removed_redundant_labels"] += 1
                            changed = True
                    break
                i = j

            if alias:
                def _resolve_alias(lbl: str) -> str:
                    seen: Set[str] = set()
                    cur = lbl
                    while cur in alias and cur not in seen:
                        seen.add(cur)
                        cur = alias[cur]
                    return cur

                for idx, ln in enumerate(lines):
                    parsed = _parse_cached(ln)
                    if parsed is None:
                        continue
                    mnem, ops = parsed
                    if len(ops) == 1 and _ASM_LABEL_NAME_RE.match(ops[0]):
                        mapped = _resolve_alias(ops[0])
                        if mapped != ops[0]:
                            lines[idx] = _render_instruction(mnem, [mapped], ln)
                            stats["threaded_jump_targets"] += 1
                            changed = True
            _record_pass(round_idx + 1, "E/label-collapse", _before_e, stats)

        # Pass F: collapse back-to-back unconditional jumps.
        _before_f = dict(stats)
        for idx, ln in enumerate(lines):
            if _instr_hint(ln) != "jmp":
                continue
            nxt = _next_code_index(lines, idx + 1)
            if nxt >= 0:
                if _instr_hint(lines[nxt]) == "jmp":
                    lines[idx] = ""
                    stats["collapsed_redundant_jumps"] += 1
                    changed = True
        _record_pass(round_idx + 1, "F/jump-collapse", _before_f, stats)

        if not changed:
            break

    # Final formatting cleanup.
    optimized: List[str] = []
    blank_run = 0
    for ln in lines:
        if ln.strip() == "":
            blank_run += 1
            if blank_run > 1:
                stats["collapsed_blank_runs"] += 1
                continue
        else:
            blank_run = 0
        optimized.append(ln)

    if collect_pass_logs:
        pass_logs.append(f"rounds_run={rounds_run}")

    return "\n".join(optimized), stats, pass_logs


class FunctionEmitter:
    """Utility for emitting per-word assembly."""

    def __init__(self, text: List[str], debug_enabled: bool = False) -> None:
        self.text = text
        self.debug_enabled = debug_enabled
        self._current_loc: Optional[SourceLocation] = None
        self._generated_debug_path = "<generated>"

    def _emit_line_directive(self, line: int, path: str, increment: int) -> None:
        escaped = path.replace("\\", "\\\\").replace('"', '\\"')
        self.text.append(f'%line {line}+{increment} "{escaped}"')

    def set_location(self, loc) -> None:
        if not self.debug_enabled:
            return
        # Defensive: if loc is a Token, convert to SourceLocation, did not have a better solution, works for me
        if loc is not None and not hasattr(loc, 'path') and hasattr(loc, 'line') and hasattr(loc, 'column'):
            # Assume self has a reference to the parser or a location_for_token function
            # If not, fallback to generic source path
            try:
                loc = self.location_for_token(loc)
            except Exception:
                from pathlib import Path
                loc = type('SourceLocation', (), {})()
                loc.path = Path('<source>')
                loc.line = getattr(loc, 'line', 0)
                loc.column = getattr(loc, 'column', 0)
        if loc is None:
            if self._current_loc is None:
                return
            self._emit_line_directive(1, self._generated_debug_path, increment=1)
            self._current_loc = None
            return
        if self._current_loc == loc:
            return
        self._emit_line_directive(loc.line, str(loc.path), increment=0)
        self._current_loc = loc

    def emit(self, line: str) -> None:
        self.text.append(line)

    def comment(self, message: str) -> None:
        self.text.append(f"    ; {message}")

    def push_literal(self, value: int) -> None:
        # x86-64 only encodes a sign-extended 32-bit immediate for a memory
        # store, so wider values go through rax.
        value &= 0xFFFFFFFFFFFFFFFF
        if value & 0x8000000000000000:
            value -= 0x10000000000000000
        _a = self.text.append
        _a(f"    ; push {value}")
        _a("    sub r12, 8")
        if -0x80000000 <= value <= 0x7FFFFFFF:
            _a(f"    mov qword [r12], {value}")
        else:
            _a(f"    mov rax, {value}")
            _a("    mov [r12], rax")

    def push_float(self, label: str) -> None:
        _a = self.text.append
        _a(f"    ; push float from {label}")
        _a("    sub r12, 8")
        _a(f"    mov rax, [rel {label}]")
        _a("    mov [r12], rax")

    def push_label(self, label: str) -> None:
        _a = self.text.append
        _a(f"    ; push {label}")
        _a("    sub r12, 8")
        _a(f"    lea rax, [rel {label}]")
        _a("    mov [r12], rax")

    def push_from(self, register: str) -> None:
        _a = self.text.append
        _a("    sub r12, 8")
        _a(f"    mov [r12], {register}")

    def pop_to(self, register: str) -> None:
        _a = self.text.append
        _a(f"    mov {register}, [r12]")
        _a("    add r12, 8")

    def ret(self) -> None:
        self.text.append("    ret")


def _int_trunc_div(lhs: int, rhs: int) -> int:
    if rhs == 0:
        raise ZeroDivisionError("division by zero")
    quotient = abs(lhs) // abs(rhs)
    if (lhs < 0) ^ (rhs < 0):
        quotient = -quotient
    return quotient


def _int_trunc_mod(lhs: int, rhs: int) -> int:
    if rhs == 0:
        raise ZeroDivisionError("division by zero")
    return lhs - _int_trunc_div(lhs, rhs) * rhs


# ---------------------------------------------------------------------------
# § 13. CT native equivalents of stdlib :asm words
# ---------------------------------------------------------------------------
# Running an :asm word at compile time marshals the whole CT stack into
# native cells and back.  For the integer words below the CT VM computes the
# result directly instead, with the same 64-bit semantics.  The equivalent is
# keyed by the word's assembly (comments and whitespace removed), not by its
# name: a user word with another body, or a stdlib body that changes, simply
# runs natively.  Only all-integer operands take the shortcut; anything else
# (handles, nil, strings) keeps the native behaviour.

_I64_MASK_ = (1 << 64) - 1
_I64_SIGN_ = 1 << 63


def _float_bits(value: float) -> int:
    """The signed 64-bit integer holding a double's IEEE-754 bits (how a float
    is a cell, at runtime and at compile time)."""
    return _get_struct().unpack("q", _get_struct().pack("d", value))[0]


def _wrap_i64(value: int) -> int:
    value &= _I64_MASK_
    return value - (1 << 64) if value & _I64_SIGN_ else value


def _ct_int_division(lhs: int, rhs: int, remainder: bool) -> int:
    if rhs == 0 or (lhs == -_I64_SIGN_ and rhs == -1):
        raise ParseError("integer division overflow or division by zero at compile time",
                         code="ct-argument-invalid")
    return _int_trunc_mod(lhs, rhs) if remainder else _int_trunc_div(lhs, rhs)


def _ct_native_binary(func: Callable[[int, int], int]) -> Callable[[List[Any]], bool]:
    low, high = -_I64_SIGN_, _I64_SIGN_

    def run(stack: List[Any]) -> bool:
        if len(stack) < 2:
            return False
        rhs = stack[-1]
        lhs = stack[-2]
        # Operands as _wrap_i64 gives them: a plain int already in range is
        # returned unchanged, so only bools and out-of-range ints are wrapped.
        if type(lhs) is not int or not low <= lhs < high:
            if type(lhs) is not bool and type(lhs) is not int:
                return False
            lhs = _wrap_i64(lhs)
        if type(rhs) is not int or not low <= rhs < high:
            if type(rhs) is not bool and type(rhs) is not int:
                return False
            rhs = _wrap_i64(rhs)
        result = func(lhs, rhs)
        stack.pop()
        stack[-1] = result
        return True
    return run


def _ct_native_unary(func: Callable[[int], int]) -> Callable[[List[Any]], bool]:
    low, high = -_I64_SIGN_, _I64_SIGN_

    def run(stack: List[Any]) -> bool:
        if not stack:
            return False
        value = stack[-1]
        if type(value) is not int or not low <= value < high:
            if type(value) is not bool and type(value) is not int:
                return False
            value = _wrap_i64(value)
        stack[-1] = func(value)
        return True
    return run


def _ct_native_clamp(stack: List[Any]) -> bool:
    """x lo hi -- y: cmovl/cmovg on signed values, lo applied first."""
    if len(stack) < 3 or any(type(value) not in (int, bool) for value in stack[-3:]):
        return False
    x, lo, hi = (_wrap_i64(value) for value in stack[-3:])
    if x < lo:
        x = lo
    if x > hi:
        x = hi
    del stack[-2:]
    stack[-1] = x
    return True


def _rotate_left(value: int, count: int) -> int:
    count &= 63
    value &= _I64_MASK_
    return _wrap_i64((value << count) | (value >> (64 - count)) if count else value)


def _ct_native_not(stack: List[Any]) -> bool:
    if not stack or type(stack[-1]) not in (int, bool):
        return False
    stack[-1] = 1 if _wrap_i64(stack[-1]) == 0 else 0
    return True


def _asm_body_key(body: str) -> str:
    lines = []
    for line in body.splitlines():
        line = " ".join(line.split(";", 1)[0].split())
        if line:
            lines.append(line)
    return "\n".join(lines)


_ASM_POP_TOP = "mov rax, [r12]\nadd r12, 8\n"
_ASM_COMPARE = _ASM_POP_TOP + "mov rbx, [r12]\ncmp rbx, rax\nmov rbx, 0\n{}\nmov [r12], rbx"
_ASM_LOGICAL = (_ASM_POP_TOP + "mov rbx, [r12]\ntest rax, rax\nsetnz cl\ntest rbx, rbx\nsetnz dl\n"
                "movzx rcx, cl\nmovzx rdx, dl\n{} rcx, rdx\nmov [r12], rcx")
_ASM_DIVIDE = "mov rbx, [r12]\nadd r12, 8\nmov rax, [r12]\ncqo\nidiv rbx\nmov [r12], {}"
_ASM_SHIFT = "mov rcx, [r12]\nadd r12, 8\n{} qword [r12], cl"
_ASM_MINMAX = "mov rax, [r12]\nadd r12, 8\nmov rbx, [r12]\ncmp rbx, rax\n{} rbx, rax\nmov [r12], rbx"

# Arithmetic and ordering on a non-integer, non-string CT value (a list,
# map, Token, nil) is a ct-argument-type error instead of handle arithmetic.
_CT_NATIVE_STRICT: Set[Callable[[List[Any]], bool]] = set()


def _ct_native_strict(func: Callable[[List[Any]], bool]) -> Callable[[List[Any]], bool]:
    _CT_NATIVE_STRICT.add(func)
    return func


_CT_NATIVE_EQUIVALENTS: Dict[str, Callable[[List[Any]], bool]] = {
    _ASM_POP_TOP + "add qword [r12], rax": _ct_native_strict(_ct_native_binary(lambda a, b: _wrap_i64(a + b))),
    _ASM_POP_TOP + "sub qword [r12], rax": _ct_native_strict(_ct_native_binary(lambda a, b: _wrap_i64(a - b))),
    _ASM_POP_TOP + "imul qword [r12]\nmov [r12], rax": _ct_native_strict(_ct_native_binary(lambda a, b: _wrap_i64(a * b))),
    _ASM_DIVIDE.format("rax"): _ct_native_strict(_ct_native_binary(lambda a, b: _ct_int_division(a, b, False))),
    _ASM_DIVIDE.format("rdx"): _ct_native_strict(_ct_native_binary(lambda a, b: _ct_int_division(a, b, True))),
    _ASM_COMPARE.format("sete bl"): _ct_native_binary(lambda a, b: 1 if a == b else 0),
    _ASM_COMPARE.format("setne bl"): _ct_native_binary(lambda a, b: 1 if a != b else 0),
    _ASM_COMPARE.format("setl bl"): _ct_native_strict(_ct_native_binary(lambda a, b: 1 if a < b else 0)),
    _ASM_COMPARE.format("setg bl"): _ct_native_strict(_ct_native_binary(lambda a, b: 1 if a > b else 0)),
    _ASM_COMPARE.format("setle bl"): _ct_native_strict(_ct_native_binary(lambda a, b: 1 if a <= b else 0)),
    _ASM_COMPARE.format("setge bl"): _ct_native_strict(_ct_native_binary(lambda a, b: 1 if a >= b else 0)),
    _ASM_LOGICAL.format("and"): _ct_native_binary(lambda a, b: 1 if a and b else 0),
    _ASM_LOGICAL.format("or"): _ct_native_binary(lambda a, b: 1 if a or b else 0),
    "mov rax, [r12]\ntest rax, rax\nsetz al\nmovzx rax, al\nmov [r12], rax": _ct_native_not,
    # More stdlib words (core.sl), with x86-64 semantics: shift and
    # rotate counts use their low 6 bits, comparisons are signed.
    "mov rax, [r12]\nneg rax\nmov [r12], rax": _ct_native_strict(_ct_native_unary(lambda a: _wrap_i64(-a))),
    "mov rax, [r12]\ntest rax, rax\njge .done\nneg rax\n.done:\nmov [r12], rax":
        _ct_native_strict(_ct_native_unary(lambda a: _wrap_i64(-a) if a < 0 else a)),
    "mov rax, [r12]\nxor rax, 1\nmov [r12], rax": _ct_native_strict(_ct_native_unary(lambda a: a ^ 1)),
    _ASM_POP_TOP + "and qword [r12], rax": _ct_native_strict(_ct_native_binary(lambda a, b: a & b)),
    _ASM_POP_TOP + "or qword [r12], rax": _ct_native_strict(_ct_native_binary(lambda a, b: a | b)),
    _ASM_POP_TOP + "xor qword [r12], rax": _ct_native_strict(_ct_native_binary(lambda a, b: a ^ b)),
    "not qword [r12]": _ct_native_strict(_ct_native_unary(lambda a: ~a)),
    _ASM_SHIFT.format("shl"): _ct_native_strict(_ct_native_binary(lambda a, b: _wrap_i64(a << (b & 63)))),
    _ASM_SHIFT.format("sal"): _ct_native_strict(_ct_native_binary(lambda a, b: _wrap_i64(a << (b & 63)))),
    _ASM_SHIFT.format("shr"): _ct_native_strict(_ct_native_binary(
        lambda a, b: _wrap_i64((a & _I64_MASK_) >> (b & 63)))),
    _ASM_SHIFT.format("sar"): _ct_native_strict(_ct_native_binary(lambda a, b: a >> (b & 63))),
    _ASM_SHIFT.format("rol"): _ct_native_strict(_ct_native_binary(lambda a, b: _rotate_left(a, b))),
    _ASM_SHIFT.format("ror"): _ct_native_strict(_ct_native_binary(lambda a, b: _rotate_left(a, 64 - (b & 63)))),
    "inc qword [r12]": _ct_native_strict(_ct_native_unary(lambda a: _wrap_i64(a + 1))),
    "dec qword [r12]": _ct_native_strict(_ct_native_unary(lambda a: _wrap_i64(a - 1))),
    _ASM_MINMAX.format("cmovg"): _ct_native_strict(_ct_native_binary(lambda a, b: min(a, b))),
    _ASM_MINMAX.format("cmovl"): _ct_native_strict(_ct_native_binary(lambda a, b: max(a, b))),
    ("mov rax, [r12]\nmov rbx, [r12 + 8]\nmov rcx, [r12 + 16]\ncmp rcx, rbx\ncmovl rcx, rbx\n"
     "cmp rcx, rax\ncmovg rcx, rax\nmov [r12 + 16], rcx\nadd r12, 16"): _ct_native_strict(_ct_native_clamp),
}
# Raw body text -> equivalent (or None); bodies are looked up once each.
_CT_NATIVE_BY_BODY: Dict[str, Optional[Callable[[List[Any]], bool]]] = {}
_CT_NATIVE_MISSING = object()


def _fold_div(a: int, b: int) -> int:
    if a == -0x8000000000000000 and b == -1:
        # Traps at runtime (#DE); leave it unfolded so behaviour matches.
        raise OverflowError("INT64_MIN / -1")
    return _int_trunc_div(a, b)


def _fold_mod(a: int, b: int) -> int:
    if a == -0x8000000000000000 and b == -1:
        raise OverflowError("INT64_MIN % -1")
    return _int_trunc_mod(a, b)


# Folding of these names when no word of that name is defined at all (a
# program without the stdlib): they fold with the stdlib's meaning, as they
# always did.  A defined word folds by its definition instead (see
# Assembler._attempt_constant_fold_tail).
_FOLDABLE_UNDEFINED_WORDS: Dict[str, Tuple[int, Callable[..., int]]] = {
    "+": (2, lambda a, b: _wrap_i64(a + b)),
    "-": (2, lambda a, b: _wrap_i64(a - b)),
    "*": (2, lambda a, b: _wrap_i64(a * b)),
    "/": (2, _fold_div),
    "%": (2, _fold_mod),
    "==": (2, lambda a, b: 1 if a == b else 0),
    "!=": (2, lambda a, b: 1 if a != b else 0),
    "<": (2, lambda a, b: 1 if a < b else 0),
    "<=": (2, lambda a, b: 1 if a <= b else 0),
    ">": (2, lambda a, b: 1 if a > b else 0),
    ">=": (2, lambda a, b: 1 if a >= b else 0),
    "not": (1, lambda a: 1 if a == 0 else 0),
}


_RE_ASM_R12_OPERAND = re.compile(r"\[\s*r12\s*(?:([+-])\s*(0x[0-9a-fA-F]+|\d+)\s*)?\]", re.IGNORECASE)
_RE_ASM_R12_STEP = re.compile(r"(add|sub)\s+r12\s*,\s*(0x[0-9a-fA-F]+|\d+)", re.IGNORECASE)
_ASM_REQUIRED_DEPTH: Dict[str, int] = {}


def _asm_required_depth(body: str) -> int:
    """Data stack cells an :asm body certainly uses: the deepest [r12+k]
    operand in its straight-line start (before any label, jump, call or
    instruction that changes r12 other than add/sub of a constant), with
    r12's movement tracked.  That part always runs, so a stack with fewer
    cells would be read (or written) out of bounds."""
    cached = _ASM_REQUIRED_DEPTH.get(body)
    if cached is not None:
        return cached
    depth = 0
    moved = 0  # bytes r12 moved up (popped) so far
    for raw in body.splitlines():
        line = raw.split(";", 1)[0].strip()
        if not line:
            continue
        mnemonic = line.split(None, 1)[0].lower()
        if line.endswith(":") or mnemonic.endswith(":") or mnemonic.startswith("j") \
                or mnemonic in ("call", "ret", "loop", "loope", "loopne", "syscall", "int", "ud2", "hlt"):
            break
        for match in _RE_ASM_R12_OPERAND.finditer(line):
            offset = int(match.group(2), 0) if match.group(2) else 0
            if match.group(1) == "-":
                offset = -offset
            position = moved + offset
            if position >= 0:
                depth = max(depth, position // 8 + 1)
        if "r12" in line.lower() and "[" in line and _RE_ASM_R12_OPERAND.search(line) is None \
                and re.search(r"\[[^\]]*\br12\b", line, re.IGNORECASE):
            break  # an indexed r12 operand: not followed further
        step = _RE_ASM_R12_STEP.fullmatch(line)
        if step is not None:
            amount = int(step.group(2), 0)
            moved += amount if step.group(1).lower() == "add" else -amount
            continue
        operands = line[len(mnemonic):].split(",", 1)[0].strip().lower()
        if re.fullmatch(r"r12[dwb]?", operands) or mnemonic in ("xchg", "push", "pop") and "r12" in line.lower():
            break  # r12 changes in a way that is not followed
    _ASM_REQUIRED_DEPTH[body] = depth
    return depth


def _ct_native_equivalent(body: str) -> Optional[Callable[[List[Any]], bool]]:
    try:
        return _CT_NATIVE_BY_BODY[body]
    except KeyError:
        found = _CT_NATIVE_BY_BODY[body] = _CT_NATIVE_EQUIVALENTS.get(_asm_body_key(body))
        return found




