def sanitize_label(name: str) -> str:
    # Keep the special `_start` label unchanged so the program entrypoint
    # remains a plain `_start` symbol expected by the linker.
    if name == "_start":
        _sanitize_label_cache[name] = name
        return name
    cached = _sanitize_label_cache.get(name)
    if cached is not None:
        return cached
    parts: List[str] = []
    for ch in name:
        if ch.isalnum() or ch == "_":
            parts.append(ch)
        else:
            parts.append(f"_{ord(ch):02x}")
    safe = "".join(parts) or "anon"
    if safe[0].isdigit():
        safe = "_" + safe
    # Prefix sanitized labels to avoid accidental collisions with
    # assembler pseudo-ops or common identifiers (e.g. `abs`). The
    # prefix is applied consistently so all emitted references using
    # `sanitize_label` remain correct.
    prefixed = f"w_{safe}"
    _sanitize_label_cache[name] = prefixed
    return prefixed


# Auto-inline asm bodies with at most this many instructions (excl. ret/blanks).
_ASM_AUTO_INLINE_THRESHOLD = 8

# Pre-compiled regexes for sanitizing symbol references in asm bodies.
_RE_ASM_CALL = re.compile(r"\bcall\s+([A-Za-z_][A-Za-z0-9_]*)\b")
_RE_ASM_GLOBAL = re.compile(r"\bglobal\s+([A-Za-z_][A-Za-z0-9_]*)\b")
_RE_ASM_EXTERN = re.compile(r"\bextern\s+([A-Za-z_][A-Za-z0-9_]*)\b")
_RE_ASM_CALL_EXTRACT = re.compile(r"call\s+(?:qword\s+)?(?:\[rel\s+([A-Za-z0-9_.$@]+)\]|([A-Za-z0-9_.$@]+))")


def _is_identifier(text: str) -> bool:
    if not text:
        return False
    first = text[0]
    if not (first.isalpha() or first == "_"):
        return False
    return all(ch.isalnum() or ch == "_" for ch in text)


_C_TYPE_IGNORED_QUALIFIERS = {
    "const",
    "volatile",
    "register",
    "restrict",
    "static",
    "extern",
    "_Atomic",
}

_C_FIELD_TYPE_ALIASES: Dict[str, str] = {
    "i8": "int8_t",
    "u8": "uint8_t",
    "i16": "int16_t",
    "u16": "uint16_t",
    "i32": "int32_t",
    "u32": "uint32_t",
    "i64": "int64_t",
    "u64": "uint64_t",
    "isize": "long",
    "usize": "size_t",
    "f32": "float",
    "f64": "double",
    "ptr": "void*",
}

_C_SCALAR_TYPE_INFO: Dict[str, Tuple[int, int, str]] = {
    "char": (1, 1, "INTEGER"),
    "signed char": (1, 1, "INTEGER"),
    "unsigned char": (1, 1, "INTEGER"),
    "short": (2, 2, "INTEGER"),
    "short int": (2, 2, "INTEGER"),
    "unsigned short": (2, 2, "INTEGER"),
    "unsigned short int": (2, 2, "INTEGER"),
    "int": (4, 4, "INTEGER"),
    "unsigned int": (4, 4, "INTEGER"),
    "int32_t": (4, 4, "INTEGER"),
    "uint32_t": (4, 4, "INTEGER"),
    "long": (8, 8, "INTEGER"),
    "unsigned long": (8, 8, "INTEGER"),
    "long long": (8, 8, "INTEGER"),
    "unsigned long long": (8, 8, "INTEGER"),
    "int64_t": (8, 8, "INTEGER"),
    "uint64_t": (8, 8, "INTEGER"),
    "size_t": (8, 8, "INTEGER"),
    "ssize_t": (8, 8, "INTEGER"),
    "void": (0, 1, "INTEGER"),
    "float": (4, 4, "SSE"),
    "double": (8, 8, "SSE"),
}


def _round_up(value: int, align: int) -> int:
    if align <= 1:
        return value
    return ((value + align - 1) // align) * align


def _canonical_c_type_name(type_name: str) -> str:
    text = " ".join(type_name.strip().split())
    if not text:
        return text
    text = _C_FIELD_TYPE_ALIASES.get(text, text)
    text = text.replace(" *", "*")
    return text




def _c_type_size_align_class(
    type_name: str,
    cstruct_layouts: Dict[str, CStructLayout],
) -> Tuple[int, int, str, Optional[CStructLayout]]:
    t = _canonical_c_type_name(type_name)
    if not t:
        return 8, 8, "INTEGER", None
    if t.endswith("*"):
        return 8, 8, "INTEGER", None
    if t in _C_SCALAR_TYPE_INFO:
        size, align, cls = _C_SCALAR_TYPE_INFO[t]
        return size, align, cls, None
    if t.startswith("struct "):
        struct_name = t[len("struct "):].strip()
        layout = cstruct_layouts.get(struct_name)
        if layout is None:
            raise CompileError(
                f"unknown cstruct '{struct_name}' used in extern signature",
                code="extern-type-invalid",
            )
        return layout.size, layout.align, "STRUCT", layout
    # Preserve backward compatibility for unknown scalar-ish names.
    return 8, 8, "INTEGER", None


def _merge_eightbyte_class(current: str, incoming: str) -> str:
    if current == "NO_CLASS":
        return incoming
    if current == incoming:
        return current
    if current == "INTEGER" or incoming == "INTEGER":
        return "INTEGER"
    return incoming


def _classify_struct_eightbytes(
    layout: CStructLayout,
    cstruct_layouts: Dict[str, CStructLayout],
    cache: Optional[Dict[str, Optional[List[str]]]] = None,
) -> Optional[List[str]]:
    if cache is None:
        cache = {}
    cached = cache.get(layout.name)
    if cached is not None or layout.name in cache:
        return cached

    if layout.size <= 0:
        cache[layout.name] = []
        return []
    if layout.size > 16:
        cache[layout.name] = None
        return None

    chunk_count = (layout.size + 7) // 8
    classes: List[str] = ["NO_CLASS"] * chunk_count

    for field in layout.fields:
        f_size, _, f_class, nested = _c_type_size_align_class(field.type_name, cstruct_layouts)
        if f_size == 0:
            continue
        if nested is not None:
            nested_classes = _classify_struct_eightbytes(nested, cstruct_layouts, cache)
            if nested_classes is None:
                cache[layout.name] = None
                return None
            base_chunk = field.offset // 8
            for idx, cls in enumerate(nested_classes):
                chunk = base_chunk + idx
                if chunk >= len(classes):
                    cache[layout.name] = None
                    return None
                classes[chunk] = _merge_eightbyte_class(classes[chunk], cls or "INTEGER")
            continue

        start_chunk = field.offset // 8
        end_chunk = (field.offset + f_size - 1) // 8
        if end_chunk >= len(classes):
            cache[layout.name] = None
            return None
        if f_class == "SSE" and start_chunk != end_chunk:
            cache[layout.name] = None
            return None
        for chunk in range(start_chunk, end_chunk + 1):
            classes[chunk] = _merge_eightbyte_class(classes[chunk], f_class)

    for idx, cls in enumerate(classes):
        if cls == "NO_CLASS":
            classes[idx] = "INTEGER"
    cache[layout.name] = classes
    return classes


def _split_trailing_identifier(text: str) -> Tuple[str, Optional[str]]:
    if not text:
        return text, None
    idx = len(text)
    while idx > 0 and (text[idx - 1].isalnum() or text[idx - 1] == "_"):
        idx -= 1
    if idx == 0 or idx == len(text):
        return text, None
    prefix = text[:idx]
    suffix = text[idx:]
    if any(not ch.isalnum() and ch != "_" for ch in prefix):
        return prefix, suffix
    return text, None


def _normalize_c_type_tokens(tokens: Sequence[str], *, allow_default: bool) -> str:
    pointer_count = 0
    parts: List[str] = []
    for raw in tokens:
        text = raw.strip()
        if not text:
            continue
        if set(text) == {"*"}:
            pointer_count += len(text)
            continue
        while text.startswith("*"):
            pointer_count += 1
            text = text[1:]
        while text.endswith("*"):
            pointer_count += 1
            text = text[:-1]
        if not text:
            continue
        if text in _C_TYPE_IGNORED_QUALIFIERS:
            continue
        parts.append(text)
    if not parts:
        if allow_default:
            base = "int"
        else:
            raise ParseError("expected C type before parameter name", code="parser-extern-invalid")
    else:
        base = " ".join(parts)
    return base + ("*" * pointer_count)


def _ctype_uses_sse(type_name: Optional[str]) -> bool:
    if type_name is None:
        return False
    base = type_name.rstrip("*")
    return base in {"float", "double"}


def _parse_string_literal(token: Token) -> Optional[str]:
    text = token.lexeme
    if len(text) < 2 or text[0] != '"' or text[-1] != '"':
        return None
    body = text[1:-1]
    result: List[str] = []
    idx = 0
    while idx < len(body):
        char = body[idx]
        if char != "\\":
            result.append(char)
            idx += 1
            continue
        idx += 1
        if idx >= len(body):
            raise ParseError(
                f"unterminated escape sequence in string literal at {token.line}:{token.column}",
                code="lexer-invalid-escape",
            )
        escape = body[idx]
        idx += 1
        if escape == 'n':
            result.append("\n")
        elif escape == 't':
            result.append("\t")
        elif escape == 'r':
            result.append("\r")
        elif escape == '0':
            result.append("\0")
        elif escape == '"':
            result.append('"')
        elif escape == "\\":
            result.append("\\")
        else:
            raise ParseError(
                f"unsupported escape sequence '\\{escape}' in string literal at {token.line}:{token.column}",
                code="lexer-invalid-escape",
            )
    return "".join(result)


def _parse_char_literal(token: Token) -> Optional[int]:
    text = token.lexeme
    if len(text) < 2 or text[0] != "'" or text[-1] != "'":
        return None
    body = text[1:-1]
    if not body:
        raise ParseError(f"empty char literal at {token.line}:{token.column}", code="lexer-invalid-char-literal")
    if body[0] != "\\":
        if len(body) != 1:
            raise ParseError(f"char literal must contain exactly one character at {token.line}:{token.column}", code="lexer-invalid-char-literal")
        return ord(body)
    if len(body) < 2:
        raise ParseError(f"unterminated escape in char literal at {token.line}:{token.column}", code="lexer-invalid-escape")
    esc = body[1:]
    if esc == "n":
        return ord("\n")
    if esc == "t":
        return ord("\t")
    if esc == "r":
        return ord("\r")
    if esc == "0":
        return 0
    if esc == "'":
        return ord("'")
    if esc == '"':
        return ord('"')
    if esc == "\\":
        return ord("\\")
    if esc.startswith("x") and len(esc) == 3:
        try:
            return int(esc[1:], 16)
        except ValueError:
            pass
    raise ParseError(f"unsupported char escape '\\{esc}' at {token.line}:{token.column}", code="lexer-invalid-escape")


def _parse_int_or_char_literal(token: Token) -> Optional[int]:
    char_value = _parse_char_literal(token)
    if char_value is not None:
        return char_value
    try:
        return int(token.lexeme, 0)
    except ValueError:
        return None


class _CTHandleTable:
    """Keeps Python object references stable across compile-time asm calls."""

    def __init__(self) -> None:
        self.objects: Dict[int, Any] = {}
        self.refs: List[Any] = []
        self.string_buffers: List[ctypes.Array[Any]] = []

    def clear(self) -> None:
        self.objects.clear()
        self.refs.clear()
        self.string_buffers.clear()

    def store(self, value: Any) -> int:
        addr = id(value)
        self.refs.append(value)
        self.objects[addr] = value
        return addr



# ---------------------------------------------------------------------------
# § 14. Assembler: emission and optimization
# ---------------------------------------------------------------------------

class Assembler:
    def __init__(
        self,
        dictionary: Dictionary,
        *,
        enable_constant_folding: bool = True,
        enable_peephole_optimization: bool = True,
        enable_loop_unroll: bool = True,
        enable_auto_inline: bool = True,
        enable_string_deduplication: bool = True,
        enable_extern_type_check: bool = True,
        enable_stack_check: bool = True,
        loop_unroll_threshold: int = 8,
        verbosity: int = 0,
        event_bus: Optional[EventBus] = None,
    ) -> None:
        self.dictionary = dictionary
        # Effective word per name; emit() replaces it with one snapshot per
        # emission attempt so every reference resolves consistently.
        self._emit_words: Dict[str, Word] = dictionary.words
        self._catalog_words: Optional[Dict[str, Word]] = None
        self.event_bus = event_bus
        self._string_literals: Dict[str, Tuple[str, int]] = {}
        self._string_literal_counter: int = 0
        self._float_literals: Dict[float, str] = {}
        self._data_section: Optional[List[str]] = None
        self._inline_stack: List[str] = []
        self._inline_counter: int = 0
        self._unroll_counter: int = 0
        self._emit_stack: List[str] = []
        self._cstruct_layouts: Dict[str, CStructLayout] = {}
        self._export_all_defs: bool = False
        self._generated_bss: List[str] = []
        self._generated_bss_counter: int = 0
        self._current_emit_loc: Optional[SourceLocation] = None
        self.enable_constant_folding = enable_constant_folding
        self.enable_peephole_optimization = enable_peephole_optimization
        self.enable_loop_unroll = enable_loop_unroll
        self.enable_auto_inline = enable_auto_inline
        self.enable_string_deduplication = enable_string_deduplication
        self.enable_extern_type_check = enable_extern_type_check
        self.enable_stack_check = enable_stack_check
        self.loop_unroll_threshold = loop_unroll_threshold
        self.verbosity = verbosity
        self._last_cfg_definitions: List[Definition] = []
        self._need_cfg: bool = False

    def _raise_compile_error(
        self,
        message: str,
        *,
        node: Optional[Op] = None,
        code: str,
        hint: str = "",
        suggestion: str = "",
        notes: Optional[Sequence[str]] = None,
        helps: Optional[Sequence[str]] = None,
    ) -> None:
        loc = node.loc if node is not None else self._current_emit_loc
        merged_code = code
        merged_hint = hint
        merged_suggestion = suggestion
        h_notes: List[str] = []
        h_helps: List[str] = []

        merged_notes: List[str] = []
        for item in notes or ():
            piece = str(item).strip()
            if piece and piece not in merged_notes:
                merged_notes.append(piece)
        for item in h_notes:
            if item and item not in merged_notes:
                merged_notes.append(item)
        if self._emit_stack:
            ctx_note = f"while emitting '{self._emit_stack[-1]}'"
            if ctx_note not in merged_notes:
                merged_notes.append(ctx_note)

        merged_helps: List[str] = []
        for item in helps or ():
            piece = str(item).strip()
            if piece and piece not in merged_helps:
                merged_helps.append(piece)
        for item in h_helps:
            if item and item not in merged_helps:
                merged_helps.append(item)

        diag = Diagnostic(
            level="error",
            message=message,
            hint=merged_hint,
            suggestion=merged_suggestion,
            code=merged_code,
            notes=merged_notes,
            helps=merged_helps,
            primary=_origin_from_location(loc),
        )
        raise CompileError(message, diagnostic=diag)

    def _copy_definition_for_cfg(self, definition: Definition) -> Definition:
        return Definition(
            name=definition.name,
            body=[_make_op(node.op, node.data, node.loc) for node in definition.body],
            immediate=definition.immediate,
            compile_only=definition.compile_only,
            runtime_only=definition.runtime_only,
            terminator=definition.terminator,
            inline=definition.inline,
        )

    def _format_cfg_op(self, node: Op) -> str:
        kind = node._opcode
        data = node.data
        if kind == OP_LITERAL:
            return f"push {data!r}"
        if kind == OP_WORD:
            return str(data)
        if kind == OP_WORD_PTR:
            return f"&{data}"
        if kind == OP_BRANCH_ZERO:
            return "branch_zero"
        if kind == OP_JUMP:
            return "jump"
        if kind == OP_LABEL:
            return f".{data}:"
        if kind == OP_FOR_BEGIN:
            return "for"
        if kind == OP_FOR_END:
            return "end  (for)"
        if kind == OP_LIST_BEGIN:
            return "list_begin"
        if kind == OP_LIST_END:
            return "list_end"
        if kind == OP_LIST_LITERAL:
            return f"list_literal {data}"
        if kind == OP_BSS_LIST_LITERAL:
            return f"bss_list_literal {data}"
        if kind == OP_RET:
            return "ret"
        if kind == OP_FOR_DROP:
            return "for_drop"
        if kind == OP_MATCH_SELECT:
            return f"match_select ({len(data.clauses)} clauses)"
        if kind == OP_MATCH_LEAVE:
            return "match_leave"
        if kind == OP_BINDING:
            return f"${data}"
        if kind == OP_SYNTAX:
            return "syntax " + " ".join(
                f"{part[1]}$(…){part[2]}" if part[0] == "unquote" else str(part[1]) if part[0] == "splice"
                else part[1].lexeme for part in data.parts)
        return f"{node.op}" if data is None else f"{node.op} {data!r}"

    @staticmethod
    def _dot_html_escape(text: str) -> str:
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")

    @staticmethod
    def _dot_escape(text: str) -> str:
        return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")

    @staticmethod
    def _dot_id(text: str) -> str:
        return re.sub(r"[^A-Za-z0-9_]", "_", text)

    def _cfg_loc_str(self, node: Op) -> str:
        if node.loc is None:
            return ""
        return f"{node.loc.path.name}:{node.loc.line}"

    def _definition_cfg_blocks_and_edges(self, definition: Definition) -> Tuple[List[Tuple[int, int]], List[Tuple[int, int, str]]]:
        nodes = definition.body
        if not nodes:
            return [], []

        label_positions = self._cfg_label_positions(nodes)
        for_pairs = self._for_pairs(nodes)

        leaders: Set[int] = {0}

        def add_leader(idx: int) -> None:
            if 0 <= idx < len(nodes):
                leaders.add(idx)

        for idx, node in enumerate(nodes):
            kind = node._opcode
            if kind == OP_LABEL:
                leaders.add(idx)
            elif kind == OP_BRANCH_ZERO:
                target = label_positions.get(str(node.data))
                if target is not None:
                    add_leader(target)
                add_leader(idx + 1)
            elif kind == OP_JUMP:
                target = label_positions.get(str(node.data))
                if target is not None:
                    add_leader(target)
                add_leader(idx + 1)
            elif kind == OP_FOR_BEGIN:
                end_idx = for_pairs.get(idx)
                if end_idx is not None:
                    add_leader(end_idx + 1)
                add_leader(idx + 1)
            elif kind == OP_FOR_END:
                begin_idx = for_pairs.get(idx)
                if begin_idx is not None:
                    add_leader(begin_idx + 1)
                add_leader(idx + 1)

        ordered = sorted(leaders)
        blocks: List[Tuple[int, int]] = []
        for i, start in enumerate(ordered):
            end = ordered[i + 1] if i + 1 < len(ordered) else len(nodes)
            if start < end:
                blocks.append((start, end))

        block_by_ip: Dict[int, int] = {}
        for block_idx, (start, end) in enumerate(blocks):
            for ip in range(start, end):
                block_by_ip[ip] = block_idx

        edges: List[Tuple[int, int, str]] = []

        def add_edge(src_block: int, target_ip: int, label: str) -> None:
            if target_ip < 0 or target_ip >= len(nodes):
                return
            dst_block = block_by_ip.get(target_ip)
            if dst_block is None:
                return
            edges.append((src_block, dst_block, label))

        for block_idx, (_start, end) in enumerate(blocks):
            last_ip = end - 1
            node = nodes[last_ip]
            kind = node._opcode

            if kind == OP_BRANCH_ZERO:
                target = label_positions.get(str(node.data))
                if target is not None:
                    add_edge(block_idx, target, "zero")
                add_edge(block_idx, last_ip + 1, "nonzero")
                continue

            if kind == OP_JUMP:
                target = label_positions.get(str(node.data))
                if target is not None:
                    add_edge(block_idx, target, "jmp")
                continue

            if kind == OP_FOR_BEGIN:
                end_idx = for_pairs.get(last_ip)
                add_edge(block_idx, last_ip + 1, "enter")
                if end_idx is not None:
                    add_edge(block_idx, end_idx + 1, "empty")
                continue

            if kind == OP_FOR_END:
                begin_idx = for_pairs.get(last_ip)
                if begin_idx is not None:
                    add_edge(block_idx, begin_idx + 1, "loop")
                add_edge(block_idx, last_ip + 1, "exit")
                continue

            add_edge(block_idx, last_ip + 1, "next")

        edges.sort(key=lambda item: (item[0], item[1], item[2]))
        return blocks, edges

    def _cfg_label_positions(self, nodes: Sequence[Op]) -> Dict[str, int]:
        positions: Dict[str, int] = {}
        for idx, node in enumerate(nodes):
            if node._opcode == OP_LABEL:
                positions[str(node.data)] = idx
        return positions

    # ---- edge style lookup ----
    _CFG_EDGE_STYLES: Dict[str, Dict[str, str]] = {
        "nonzero": {"color": "#2e7d32", "fontcolor": "#2e7d32", "label": "T", "penwidth": "2"},
        "zero":    {"color": "#c62828", "fontcolor": "#c62828", "label": "F", "style": "dashed", "penwidth": "2"},
        "jmp":     {"color": "#1565c0", "fontcolor": "#1565c0", "label": "jmp", "penwidth": "1.5"},
        "next":    {"color": "#616161", "fontcolor": "#616161", "label": ""},
        "enter":   {"color": "#2e7d32", "fontcolor": "#2e7d32", "label": "enter", "penwidth": "2"},
        "empty":   {"color": "#c62828", "fontcolor": "#c62828", "label": "empty", "style": "dashed", "penwidth": "1.5"},
        "loop":    {"color": "#6a1b9a", "fontcolor": "#6a1b9a", "label": "loop", "style": "bold", "penwidth": "2"},
        "exit":    {"color": "#ef6c00", "fontcolor": "#ef6c00", "label": "exit", "penwidth": "1.5"},
    }

    def _cfg_edge_attrs(self, label: str) -> str:
        style = self._CFG_EDGE_STYLES.get(label, {"label": label, "color": "black"})
        parts = [f'{k}="{v}"' for k, v in style.items()]
        return ", ".join(parts)

    def render_last_cfg_dot(self) -> str:
        lines: List[str] = [
            "digraph l2_cfg {",
            '    rankdir=TB;',
            '    newrank=true;',
            '    compound=true;',
            '    fontname="Helvetica";',
            '    node [shape=plaintext, fontname="Courier New", fontsize=10];',
            '    edge [fontname="Helvetica", fontsize=9];',
        ]

        if not self._last_cfg_definitions:
            lines.append('    empty [shape=box, label="(no definitions)"];')
            lines.append("}")
            return "\n".join(lines)

        for defn in self._last_cfg_definitions:
            cluster_id = self._dot_id(f"cluster_{defn.name}")
            prefix = self._dot_id(defn.name)

            blocks, edges = self._definition_cfg_blocks_and_edges(defn)

            # Determine which blocks are loop-back targets
            back_targets: Set[int] = set()
            for src, dst, elabel in edges:
                if elabel == "loop" or (elabel == "jmp" and dst <= src):
                    back_targets.add(dst)

            # Determine exit blocks (no outgoing edges)
            has_successor: Set[int] = {src for src, _, _ in edges}

            lines.append(f"    subgraph {cluster_id} {{")
            lines.append(f'        label=<<B>{self._dot_html_escape(defn.name)}</B>>;')
            lines.append('        labeljust=l;')
            lines.append('        style=dashed; color="#9e9e9e";')
            lines.append(f'        fontname="Helvetica"; fontsize=12;')

            if not blocks:
                node_id = self._dot_id(f"{defn.name}_empty")
                lines.append(f'        {node_id} [shape=box, label="(empty)"];')
                lines.append("    }")
                continue

            for block_idx, (start, end) in enumerate(blocks):
                node_id = f"{prefix}_b{block_idx}"
                is_entry = block_idx == 0
                is_exit = block_idx not in has_successor
                is_loop_head = block_idx in back_targets

                # Pick header colour
                if is_entry:
                    hdr_bg = "#c8e6c9"  # green
                    hdr_fg = "#1b5e20"
                elif is_exit:
                    hdr_bg = "#ffcdd2"  # red
                    hdr_fg = "#b71c1c"
                elif is_loop_head:
                    hdr_bg = "#bbdefb"  # blue
                    hdr_fg = "#0d47a1"
                else:
                    hdr_bg = "#e0e0e0"  # grey
                    hdr_fg = "#212121"

                # Block annotation
                tag = ""
                if is_entry:
                    tag = " (entry)"
                if is_exit:
                    tag += " (exit)"
                if is_loop_head:
                    tag += " (loop)"

                # Source location from first non-label instruction
                loc_str = ""
                for ip in range(start, end):
                    n = defn.body[ip]
                    if n._opcode != OP_LABEL:
                        loc_str = self._cfg_loc_str(n)
                        break
                if not loc_str and defn.body[start].loc:
                    loc_str = self._cfg_loc_str(defn.body[start])

                # Build HTML table label
                hdr_text = f"BB{block_idx}{tag}"
                if loc_str:
                    hdr_text += f"  [{loc_str}]"

                rows: List[str] = []
                rows.append(f'<TR><TD BGCOLOR="{hdr_bg}" ALIGN="LEFT"><FONT COLOR="{hdr_fg}"><B>{self._dot_html_escape(hdr_text)}</B></FONT></TD></TR>')

                for ip in range(start, end):
                    n = defn.body[ip]
                    op_text = self._format_cfg_op(n)
                    esc = self._dot_html_escape(f"  {ip:3d}  {op_text}")
                    kind = n._opcode
                    if kind in (OP_BRANCH_ZERO, OP_JUMP, OP_FOR_BEGIN, OP_FOR_END):
                        # Highlight control-flow ops
                        rows.append(f'<TR><TD ALIGN="LEFT" BGCOLOR="#fff9c4"><FONT COLOR="#f57f17" FACE="Courier New">{esc}</FONT></TD></TR>')
                    elif kind == OP_LABEL:
                        rows.append(f'<TR><TD ALIGN="LEFT" BGCOLOR="#f5f5f5"><FONT COLOR="#9e9e9e" FACE="Courier New">{esc}</FONT></TD></TR>')
                    else:
                        rows.append(f'<TR><TD ALIGN="LEFT"><FONT FACE="Courier New">{esc}</FONT></TD></TR>')

                table = f'<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="4">{"".join(rows)}</TABLE>>'
                lines.append(f"        {node_id} [label={table}];")

            for src, dst, edge_label in edges:
                src_id = f"{prefix}_b{src}"
                dst_id = f"{prefix}_b{dst}"
                attrs = self._cfg_edge_attrs(edge_label)
                lines.append(f"        {src_id} -> {dst_id} [{attrs}];")

            lines.append("    }")

        # Legend
        lines.append("    subgraph cluster_legend {")
        lines.append('        label=<<B>Legend</B>>;')
        lines.append('        fontname="Helvetica"; fontsize=10;')
        lines.append('        style=solid; color="#bdbdbd";')
        lines.append('        node [shape=box, fontname="Helvetica", fontsize=9, width=1.3, height=0.3];')
        lines.append('        edge [style=invis];')
        lines.append('        leg_entry [label="entry", style=filled, fillcolor="#c8e6c9", fontcolor="#1b5e20"];')
        lines.append('        leg_exit  [label="exit",  style=filled, fillcolor="#ffcdd2", fontcolor="#b71c1c"];')
        lines.append('        leg_loop  [label="loop header", style=filled, fillcolor="#bbdefb", fontcolor="#0d47a1"];')
        lines.append('        leg_norm  [label="basic block", style=filled, fillcolor="#e0e0e0", fontcolor="#212121"];')
        lines.append('        leg_entry -> leg_exit -> leg_loop -> leg_norm;')
        lines.append("    }")

        lines.append("}")
        return "\n".join(lines)

    @staticmethod
    def _log_op_diff(name: str, pass_name: str, before: list, after: list) -> None:
        """Print a contextual diff of (op, data) tuples for v4 optimization detail."""
        import difflib
        def _fmt(op_data: tuple) -> str:
            op, data = op_data
            if op == "literal":
                return f"  {data!r}" if isinstance(data, str) else f"  {data}"
            if op == "word":
                return f"  {data}"
            return f"  [{op}] {data!r}" if data is not None else f"  [{op}]"
        before_lines = [_fmt(t) for t in before]
        after_lines = [_fmt(t) for t in after]
        diff = list(difflib.unified_diff(before_lines, after_lines, n=1, lineterm=""))
        if len(diff) <= 2:
            return
        for line in diff[2:]:  # skip --- / +++ header
            if line.startswith("@@"):
                print(f"[v4]   {pass_name} '{name}' {line}")
            elif line.startswith("-"):
                print(f"[v4]     - {line[1:]}")
            elif line.startswith("+"):
                print(f"[v4]     + {line[1:]}")
            else:
                print(f"[v4]      {line[1:]}")

    def _peephole_optimize_definition(self, definition: Definition) -> None:
        nodes = definition.body
        if not nodes:
            return
        all_rules = _PEEPHOLE_ALL_RULES
        first_words = _PEEPHOLE_FIRST_WORDS
        _OP_W = OP_WORD

        # Outer loop: keeps re-running all passes until nothing changes.
        any_changed = True
        while any_changed:
            any_changed = False

            # ---------- Pass 1: word-only pattern rewriting ----------
            changed = True
            while changed:
                changed = False
                optimized: List[Op] = []
                _opt_append = optimized.append
                idx = 0
                nlen = len(nodes)
                while idx < nlen:
                    node = nodes[idx]
                    if node._opcode != _OP_W:
                        _opt_append(node)
                        idx += 1
                        continue
                    word_name = node.data
                    if word_name not in first_words:
                        _opt_append(node)
                        idx += 1
                        continue

                    best_repl: Optional[Tuple[str, ...]] = None
                    best_pat: Optional[Tuple[str, ...]] = None
                    best_len = 0
                    best_cost = 1_000_000

                    if idx + 2 < nlen:
                        b = nodes[idx + 1]
                        c = nodes[idx + 2]
                        if b._opcode == _OP_W and c._opcode == _OP_W:
                            pat3 = (word_name, b.data, c.data)
                            repl3 = all_rules.get(pat3)
                            if repl3 is not None:
                                cost3 = int(_PEEPHOLE_RULE_COST.get(pat3, len(repl3)))
                                best_repl = repl3
                                best_pat = pat3
                                best_len = 3
                                best_cost = cost3

                    if idx + 1 < nlen:
                        b = nodes[idx + 1]
                        if b._opcode == _OP_W:
                            pat2 = (word_name, b.data)
                            repl2 = all_rules.get(pat2)
                            if repl2 is not None:
                                cost2 = int(_PEEPHOLE_RULE_COST.get(pat2, len(repl2)))
                                if (
                                    best_repl is None
                                    or cost2 < best_cost
                                    or (cost2 == best_cost and 2 > best_len)
                                ):
                                    best_repl = repl2
                                    best_pat = pat2
                                    best_len = 2
                                    best_cost = cost2

                    if best_repl is not None and best_pat is not None:
                        base_loc = node.loc
                        for r in best_repl:
                            if r[0] == 'l' and r[:8] == "literal_":
                                _opt_append(_make_literal_op(int(r[8:]), loc=base_loc))
                            else:
                                _opt_append(_make_word_op(r, base_loc))
                        idx += best_len
                        changed = True
                        continue

                    if best_repl is None:
                        _opt_append(node)
                        idx += 1
                if changed:
                    any_changed = True
                nodes = optimized

            # ---------- Pass 2: literal + word algebraic identities ----------
            _CANCEL_PAIRS = _PEEPHOLE_CANCEL_PAIRS
            _SHIFT_OPS = _PEEPHOLE_SHIFT_OPS
            changed = True
            while changed:
                changed = False
                optimized = []
                _opt_a = optimized.append
                nlen = len(nodes)
                idx = 0
                while idx < nlen:
                    node = nodes[idx]
                    n_oc = node._opcode

                    # -- Redundant unary pairs (word word) --
                    if n_oc == OP_WORD and idx + 1 < nlen:
                        b = nodes[idx + 1]
                        if b._opcode == OP_WORD:
                            wa, wb = node.data, b.data
                            if (wa, wb) in _CANCEL_PAIRS:
                                idx += 2
                                changed = True
                                continue
                            if wa == "abs" and wb == "abs":
                                _opt_a(node)
                                idx += 2
                                changed = True
                                continue

                    # -- scalar literal patterns (excludes string literals which push 2 values) --
                    if n_oc == OP_LITERAL and type(node.data) is not str and idx + 1 < nlen:
                        b = nodes[idx + 1]
                        b_oc = b._opcode

                        # literal + dup -> literal literal
                        if b_oc == OP_WORD and b.data == "dup":
                            _opt_a(node)
                            _opt_a(_make_literal_op(node.data, node.loc))
                            idx += 2
                            changed = True
                            continue

                        # literal + drop -> (nothing)
                        if b_oc == OP_WORD and b.data == "drop":
                            idx += 2
                            changed = True
                            continue

                        # literal literal + 2drop / swap
                        if b_oc == OP_LITERAL and type(b.data) is not str and idx + 2 < nlen:
                            c = nodes[idx + 2]
                            if c._opcode == OP_WORD:
                                cd = c.data
                                if cd == "2drop":
                                    idx += 3
                                    changed = True
                                    continue
                                if cd == "swap":
                                    _opt_a(_make_literal_op(b.data, b.loc))
                                    _opt_a(_make_literal_op(node.data, node.loc))
                                    idx += 3
                                    changed = True
                                    continue

                        # Binary op identities: literal K + word
                        if type(node.data) is int and b_oc == OP_WORD:
                            k = node.data
                            w = b.data
                            base_loc = node.loc or b.loc

                            if (w == "+" and k == 0) or (w == "-" and k == 0) or (w == "*" and k == 1) or (w == "/" and k == 1):
                                idx += 2; changed = True; continue

                            if w == "*":
                                if k == 0:
                                    _opt_a(_make_word_op("drop", base_loc))
                                    _opt_a(_make_literal_op(0, base_loc))
                                    idx += 2; changed = True; continue
                                if k == -1:
                                    _opt_a(_make_word_op("neg", base_loc))
                                    idx += 2; changed = True; continue
                                if k > 1 and (k & (k - 1)) == 0:
                                    _opt_a(_make_literal_op(k.bit_length() - 1, base_loc))
                                    _opt_a(_make_word_op("shl", base_loc))
                                    idx += 2; changed = True; continue

                            if w == "band":
                                if k == 0:
                                    _opt_a(_make_word_op("drop", base_loc))
                                    _opt_a(_make_literal_op(0, base_loc))
                                    idx += 2; changed = True; continue
                                if k == -1:
                                    idx += 2; changed = True; continue

                            if w == "bor":
                                if k == -1:
                                    _opt_a(_make_word_op("drop", base_loc))
                                    _opt_a(_make_literal_op(-1, base_loc))
                                    idx += 2; changed = True; continue
                                if k == 0:
                                    idx += 2; changed = True; continue

                            if w == "bxor" and k == 0:
                                idx += 2; changed = True; continue

                            if w == "%" and k == 1:
                                _opt_a(_make_word_op("drop", base_loc))
                                _opt_a(_make_literal_op(0, base_loc))
                                idx += 2; changed = True; continue

                            if w == "==" and k == 0:
                                _opt_a(_make_word_op("not", base_loc))
                                idx += 2; changed = True; continue

                            if w in _SHIFT_OPS and k == 0:
                                idx += 2; changed = True; continue

                            if w == "+":
                                if k == 1:
                                    _opt_a(_make_word_op("inc", base_loc))
                                    idx += 2; changed = True; continue
                                if k == -1:
                                    _opt_a(_make_word_op("dec", base_loc))
                                    idx += 2; changed = True; continue
                            if w == "-":
                                if k == 1:
                                    _opt_a(_make_word_op("dec", base_loc))
                                    idx += 2; changed = True; continue
                                if k == -1:
                                    _opt_a(_make_word_op("inc", base_loc))
                                    idx += 2; changed = True; continue

                    _opt_a(node)
                    idx += 1
                if changed:
                    any_changed = True
                nodes = optimized

            # ---------- Pass 3: dead-code after unconditional jump/end ----------
            new_nodes: List[Op] = []
            dead = False
            for node in nodes:
                kind = node._opcode
                if dead:
                    # A label ends the dead region; loop delimiters are kept
                    # (and end it) so for_begin/for_end stay paired, e.g. a
                    # for_end right after `break`'s jump.
                    if kind == OP_LABEL or kind == OP_FOR_END or kind == OP_FOR_BEGIN:
                        dead = False
                        new_nodes.append(node)
                    else:
                        any_changed = True
                    continue
                new_nodes.append(node)
                if kind in _PEEPHOLE_TERMINATORS:
                    dead = True
            if len(new_nodes) != len(nodes):
                any_changed = True
            nodes = new_nodes

        definition.body = nodes

    def _fold_constants_in_definition(self, definition: Definition) -> None:
        if not definition.body:
            return
        optimized: List[Op] = []
        for node in definition.body:
            optimized.append(node)
            self._attempt_constant_fold_tail(optimized)
        definition.body = optimized

    def _attempt_constant_fold_tail(self, nodes: List[Op]) -> None:
        """Fold `lit ... lit word` at the end of nodes into one literal when the
        definition the call would run is a stdlib :asm word with a Python
        equivalent (+ - * / % comparisons, logic, bitwise, shifts, min/max,
        abs/neg/inc/dec, clamp): the result is computed by that equivalent, so
        it is exactly what the word computes, and a redefined word (a user's
        `+`) is never folded.  The operand count is the body's stack depth."""
        _LIT = OP_LITERAL
        words = self._emit_words
        while nodes:
            last = nodes[-1]
            if last._opcode != OP_WORD:
                return
            word = words.get(last.data)
            if word is None:
                entry = _FOLDABLE_UNDEFINED_WORDS.get(last.data)
                if entry is None:
                    return
                arity, func = entry

                def equivalent(stack: List[Any], func: Callable[..., int] = func, arity: int = arity) -> bool:
                    stack[-arity:] = [func(*stack[-arity:])]
                    return True
            else:
                definition = word.definition
                if not isinstance(definition, AsmDefinition):
                    return
                equivalent = _ct_native_equivalent(definition.body)
                if equivalent is None:
                    return
                arity = _asm_required_depth(definition.body)
            if arity < 1 or len(nodes) < arity + 1:
                return
            operands = nodes[-(arity + 1):-1]
            if any(op._opcode != _LIT or type(op.data) is not int for op in operands):
                return
            stack: List[Any] = [_wrap_i64(op.data) for op in operands]
            try:
                done = equivalent(stack)
            except Exception:
                return  # e.g. division by zero: left to the program
            if not done or len(stack) != 1 or type(stack[0]) is not int:
                return
            new_loc = operands[0].loc or last.loc
            nodes[-(arity + 1):] = [_make_literal_op(stack[0], new_loc)]

    def _audit_optimized_definition(self, definition: Definition) -> None:
        labels: Set[str] = set()
        branch_targets: Set[str] = set()
        for_depth = 0
        begin_depth = 0

        for node in definition.body:
            kind = node._opcode
            if kind == OP_LABEL:
                labels.add(str(node.data))
                continue
            if kind == OP_FOR_BEGIN:
                for_depth += 1
                continue
            if kind == OP_FOR_END:
                if for_depth <= 0:
                    raise CompileError(
                        f"optimizer audit failed in '{definition.name}': unmatched for-loop end",
                        code="internal-optimizer",
                    )
                for_depth -= 1
                continue
            if kind == OP_WORD:
                lex = str(node.data)
                if lex == "begin":
                    begin_depth += 1
                elif lex == "again":
                    if begin_depth <= 0:
                        raise CompileError(
                            f"optimizer audit failed in '{definition.name}': unmatched begin/again pair",
                            code="internal-optimizer",
                        )
                    begin_depth -= 1
                continue
            if kind in (OP_BRANCH_ZERO, OP_JUMP):
                branch_targets.add(str(node.data))

        if for_depth != 0:
            raise CompileError(
                f"optimizer audit failed in '{definition.name}': unterminated for-loop after optimization",
                code="internal-optimizer",
            )
        if begin_depth != 0:
            raise CompileError(
                f"optimizer audit failed in '{definition.name}': unterminated begin/again block after optimization",
                code="internal-optimizer",
            )

        missing = sorted(target for target in branch_targets if target not in labels)
        if missing:
            raise CompileError(
                f"optimizer audit failed in '{definition.name}': missing label(s) {', '.join(missing)}",
                code="internal-optimizer",
            )

    def _for_pairs(self, nodes: Sequence[Op]) -> Dict[int, int]:
        stack: List[int] = []
        pairs: Dict[int, int] = {}
        for idx, node in enumerate(nodes):
            if node._opcode == OP_FOR_BEGIN:
                stack.append(idx)
            elif node._opcode == OP_FOR_END:
                if not stack:
                    raise CompileError("'end' without matching 'for'", code="ct-control-flow-invalid")
                begin_idx = stack.pop()
                pairs[begin_idx] = idx
                pairs[idx] = begin_idx
        if stack:
            raise CompileError("'for' without matching 'end'", code="ct-control-flow-invalid")
        return pairs

    def _collect_internal_labels(self, nodes: Sequence[Op]) -> Set[str]:
        labels: Set[str] = set()
        for node in nodes:
            kind = node._opcode
            data = node.data
            if kind == OP_LABEL:
                labels.add(str(data))
            elif kind == OP_FOR_BEGIN or kind == OP_FOR_END:
                labels.add(str(data["loop"]))
                labels.add(str(data["end"]))
            elif kind == OP_LIST_BEGIN or kind == OP_LIST_END:
                labels.add(str(data))
        return labels

    def _clone_nodes_with_label_remap(
        self,
        nodes: Sequence[Op],
        internal_labels: Set[str],
        suffix: str,
    ) -> List[Op]:
        label_map: Dict[str, str] = {}

        def remap(label: str) -> str:
            if label not in internal_labels:
                return label
            if label not in label_map:
                label_map[label] = f"{label}__unr{suffix}"
            return label_map[label]

        cloned: List[Op] = []
        for node in nodes:
            kind = node._opcode
            data = node.data
            if kind == OP_LABEL:
                cloned.append(_make_op("label", remap(str(data)), loc=node.loc))
                continue
            if kind == OP_JUMP or kind == OP_BRANCH_ZERO:
                target = str(data)
                mapped = remap(target) if target in internal_labels else target
                cloned.append(_make_op(node.op, mapped, node.loc))
                continue
            if kind == OP_FOR_BEGIN or kind == OP_FOR_END:
                cloned.append(
                    Op(
                        op=node.op,
                        data={
                            "loop": remap(str(data["loop"])),
                            "end": remap(str(data["end"])),
                        },
                        loc=node.loc,
                    )
                )
                continue
            if kind == OP_LIST_BEGIN or kind == OP_LIST_END:
                cloned.append(_make_op(node.op, remap(str(data)), loc=node.loc))
                continue
            cloned.append(_make_op(node.op, data, node.loc))
        return cloned

    def _unroll_constant_for_loops(self, definition: Definition) -> None:
        threshold = self.loop_unroll_threshold
        if threshold <= 0:
            return
        nodes = definition.body
        pairs = self._for_pairs(nodes)
        if not pairs:
            return

        rebuilt: List[Op] = []
        idx = 0
        while idx < len(nodes):
            node = nodes[idx]
            if node._opcode == OP_FOR_BEGIN and idx > 0:
                prev = nodes[idx - 1]
                if prev._opcode == OP_LITERAL and isinstance(prev.data, int):
                    count = int(prev.data)
                    end_idx = pairs.get(idx)
                    if end_idx is None:
                        raise CompileError("internal loop bookkeeping error", code="internal-optimizer")
                    if count <= 0:
                        if rebuilt and rebuilt[-1] is prev:
                            rebuilt.pop()
                        idx = end_idx + 1
                        continue
                    # An unrolled loop has no counter, so a body that leaves
                    # the loop with `break` (for_drop) is kept as a loop.
                    if count <= threshold and not any(n._opcode == OP_FOR_DROP for n in nodes[idx + 1:end_idx]):
                        if rebuilt and rebuilt[-1] is prev:
                            rebuilt.pop()
                        body = nodes[idx + 1:end_idx]
                        internal_labels = self._collect_internal_labels(body)
                        for copy_idx in range(count):
                            suffix = f"{self._unroll_counter}_{copy_idx}"
                            rebuilt.extend(
                                self._clone_nodes_with_label_remap(
                                    body,
                                    internal_labels,
                                    suffix,
                                )
                            )
                        self._unroll_counter += 1
                        idx = end_idx + 1
                        continue
            rebuilt.append(node)
            idx += 1

        definition.body = rebuilt

    def _fold_static_list_literals_definition(self, definition: Definition) -> None:
        nodes = definition.body
        rebuilt: List[Op] = []
        idx = 0
        while idx < len(nodes):
            node = nodes[idx]
            if node.op != "list_begin":
                rebuilt.append(node)
                idx += 1
                continue

            depth = 1
            j = idx + 1
            static_values: List[int] = []
            is_static = True

            while j < len(nodes):
                cur = nodes[j]
                if cur._opcode == OP_LIST_BEGIN:
                    depth += 1
                    is_static = False
                    j += 1
                    continue
                if cur._opcode == OP_LIST_END:
                    depth -= 1
                    if depth == 0:
                        break
                    j += 1
                    continue

                if depth == 1:
                    if cur._opcode == OP_LITERAL and isinstance(cur.data, int):
                        static_values.append(int(cur.data))
                    else:
                        is_static = False
                j += 1

            if depth != 0:
                rebuilt.append(node)
                idx += 1
                continue

            if is_static:
                rebuilt.append(_make_op("list_literal", static_values, node.loc))
                idx = j + 1
                continue

            rebuilt.append(node)
            idx += 1

        definition.body = rebuilt

    # Known stack effects: (inputs_consumed, outputs_produced)
    _BUILTIN_STACK_EFFECTS: Dict[str, Tuple[int, int]] = {
        "dup":   (1, 2),
        "drop":  (1, 0),
        "swap":  (2, 2),
        "over":  (2, 3),
        "rot":   (3, 3),
        "nip":   (2, 1),
        "tuck":  (2, 3),
        "+":     (2, 1),
        "-":     (2, 1),
        "*":     (2, 1),
        "/":     (2, 1),
        "mod":   (2, 1),
        "=":     (2, 1),
        "!=":    (2, 1),
        "<":     (2, 1),
        ">":     (2, 1),
        "<=":    (2, 1),
        ">=":    (2, 1),
        "and":   (2, 1),
        "or":    (2, 1),
        "xor":   (2, 1),
        "not":   (1, 1),
        "shl":   (2, 1),
        "shr":   (2, 1),
        "neg":   (1, 1),
        "@":     (1, 1),
        "!":     (2, 0),
        "@8":    (1, 1),
        "!8":    (2, 0),
        "@16":   (1, 1),
        "!16":   (2, 0),
        "@32":   (1, 1),
        "!32":   (2, 0),
    }

    def _check_extern_types(self, definitions: Sequence[Union["Definition", "AsmDefinition"]]) -> None:
        def _declared_effect(word: Word) -> Optional[Tuple[int, int]]:
            definition = word.definition
            if not getattr(definition, "effect_exact", False):
                return None
            inputs = definition.stack_inputs
            outputs = definition.stack_outputs
            if inputs is None or outputs is None:
                return None
            return inputs, outputs

        """Basic type checking: verify stack depth at extern call sites and builtin underflows."""
        _v = self.verbosity
        _effects = self._BUILTIN_STACK_EFFECTS
        _OP_LIT = OP_LITERAL
        _OP_W = OP_WORD
        _OP_WP = OP_WORD_PTR
        _OP_LIST_LIT = OP_LIST_LITERAL
        _OP_BSS_LIST_LIT = OP_BSS_LIST_LITERAL
        _check_extern = self.enable_extern_type_check
        _check_stack = self.enable_stack_check
        extern_issues: List[str] = []
        stack_issues: List[str] = []
        for defn in definitions:
            if not isinstance(defn, Definition):
                continue
            # depth tracks values on the data stack relative to entry.
            # 'main' starts with an empty stack.  For other words we can
            # only check underflows when a stack-effect comment provides
            # the input count.
            si = defn.stack_inputs
            if si is not None:
                known_entry_depth = si
            elif defn.name == 'main':
                known_entry_depth = 0
            else:
                known_entry_depth = -1  # unknown — disable underflow checks
            depth: Optional[int] = known_entry_depth if known_entry_depth >= 0 else 0
            for node in defn.body:
                opc = node._opcode
                if depth is None:
                    # After control flow we can't track depth reliably
                    if opc == _OP_W and _check_extern:
                        word = self._emit_words.get(str(node.data))
                        if word and word.is_extern and word.extern_signature:
                            # Can't verify — depth unknown after branch
                            if _v >= 3:
                                print(f"[v3] type-check: '{defn.name}' -> extern '{word.name}' skipped (unknown depth)")
                    continue
                if opc == _OP_LIT:
                    # String literals push 2 values (addr + len), others push 1.
                    depth += 2 if isinstance(node.data, str) else 1
                elif opc == _OP_WP:
                    depth += 1
                elif opc == _OP_LIST_LIT or opc == _OP_BSS_LIST_LIT or opc == OP_SYNTAX or opc == OP_BINDING:
                    depth += 1
                elif opc == OP_MATCH_SELECT:
                    depth = None
                elif opc in (OP_BRANCH_ZERO, OP_JUMP, OP_LABEL, OP_FOR_BEGIN, OP_FOR_END):
                    # Control flow — stop tracking precisely
                    if opc == OP_BRANCH_ZERO:
                        depth -= 1
                    depth = None
                elif opc == _OP_W:
                    name = str(node.data)
                    word = self._emit_words.get(name)
                    if word is None:
                        depth = None
                        continue
                    if word.is_extern and word.extern_signature:
                        inputs = word.extern_inputs
                        outputs = word.extern_outputs
                        if _check_extern and known_entry_depth >= 0 and depth < inputs:
                            extern_issues.append(
                                f"in '{defn.name}': extern '{name}' expects {inputs} "
                                f"argument{'s' if inputs != 1 else ''}, but only {depth} "
                                f"value{'s' if depth != 1 else ''} on the stack"
                            )
                        depth = depth - inputs + outputs
                    elif name in _effects or _declared_effect(word) is not None:
                        consumed, produced = _effects[name] if name in _effects else _declared_effect(word)
                        if known_entry_depth >= 0 and depth < consumed:
                            if _check_stack:
                                stack_issues.append(
                                    f"in '{defn.name}': '{name}' needs {consumed} "
                                    f"value{'s' if consumed != 1 else ''}, but only {depth} "
                                    f"on the stack"
                                )
                            depth = None
                        else:
                            depth = depth - consumed + produced
                    elif word.is_extern:
                        # Extern without signature — apply inputs/outputs
                        depth = depth - word.extern_inputs + word.extern_outputs
                    else:
                        # Unknown word — lose depth tracking
                        depth = None
            # A definition that declares its outputs must end with them
            # (checked when the depth is known to the end of a straight body).
            so = defn.stack_outputs
            if (_check_stack and defn.effect_exact and so is not None and depth is not None
                    and known_entry_depth >= 0 and depth != so):
                stack_issues.append(
                    f"'{defn.name}' declares {so} output{'s' if so != 1 else ''} but leaves {depth}"
                )

        for issue in extern_issues:
            print(f"[extern-type-check] warning: {issue}")
        for issue in stack_issues:
            print(f"[stack-check] warning: {issue}")
        if _v >= 1 and not extern_issues and not stack_issues:
            print(f"[v1] type-check: no issues found")

    def _reachable_runtime_defs(self, runtime_defs: Sequence[Union[Definition, AsmDefinition]], extra_roots: Optional[Sequence[str]] = None) -> Set[str]:
        edges: Dict[str, Set[str]] = {}
        _OP_W = OP_WORD
        _OP_WP = OP_WORD_PTR
        for definition in runtime_defs:
            refs: Set[str] = set()
            if isinstance(definition, Definition):
                for node in definition.body:
                    oc = node._opcode
                    if oc == _OP_W or oc == _OP_WP:
                        refs.add(str(node.data))
            elif isinstance(definition, AsmDefinition):
                # Collect obvious textual `call` targets from asm bodies so
                # asm-defined entry points can create edges into the word
                # graph.  The extractor below will tolerate common call forms
                # such as `call foo` and `call [rel foo]`.
                asm_calls = self._extract_called_symbols_from_asm(definition.body)
                for sym in asm_calls:
                    refs.add(sym)
            edges[definition.name] = refs

        # Map sanitized labels back to their original definition names so
        # calls to emitted/sanitized labels (e.g. `w_foo`) can be resolved
        # to the corresponding word names present in `edges`.
        sanitized_map: Dict[str, str] = {sanitize_label(n): n for n in edges}

        reachable: Set[str] = set()
        stack: List[str] = ["main"]
        if extra_roots:
            for r in extra_roots:
                if r and r not in stack:
                    stack.append(r)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            for dep in edges.get(name, ()): 
                # Direct name hit
                if dep in edges and dep not in reachable:
                    stack.append(dep)
                    continue
                # Possibly a sanitized label; resolve back to original name
                resolved = sanitized_map.get(dep)
                if resolved and resolved not in reachable:
                    stack.append(resolved)
        return reachable

    def _extract_called_symbols_from_asm(self, asm_body: str) -> Set[str]:
        """Return set of symbol names called from a raw asm body.

        This looks for typical `call <symbol>` forms and also
        `call [rel <symbol>]` and `call qword [rel <symbol>]`.
        """
        calls: Set[str] = set()
        for m in _RE_ASM_CALL_EXTRACT.finditer(asm_body):
            sym = m.group(1) or m.group(2)
            if sym:
                calls.add(sym)
        return calls

    def _emit_externs(self, text: List[str]) -> None:
        externs = sorted([w.name for w in self._emit_words.values() if getattr(w, "is_extern", False)])
        for name in externs:
            text.append(f"extern {name}")

    def emit(self, module: Module, debug: bool = False, entry_mode: str = "program", c_abi: bool = False, module_name: str = "l2") -> Emission:
        if entry_mode not in {"program", "library"}:
            raise CompileError(f"unknown entry mode '{entry_mode}'", code="emission-entry-mode-invalid")
        is_program = entry_mode == "program"
        emission = Emission()
        self._emit_words = self.dictionary.selected_snapshot()
        self._catalog_words = self._emit_words
        self._export_all_defs = not is_program
        self._last_cfg_definitions = []
        try:
            self._emit_externs(emission.text)
            # Determine whether user provided a top-level `:asm _start` in
            # the module forms so the prelude can avoid emitting the
            # default startup stub.
            # Detect whether the user supplied a `_start` either as a top-level
            # AsmDefinition form or as a registered dictionary word (imports
            # or CT execution may register it). This influences prelude
            # generation so the default stub is suppressed when present.
            user_has_start = any(
                isinstance(f, AsmDefinition) and f.name == "_start" for f in module.forms
            ) or (
                (self._emit_words.get("_start") is not None)
                and isinstance(self._emit_words.get("_start").definition, AsmDefinition)
            )
            # Defer runtime prelude generation until after top-level forms are
            # parsed into `definitions` so we can accurately detect a user
            # provided `_start` AsmDefinition and suppress the default stub.
            # Prelude will be generated after definitions are known.
            # If user provided a raw assembly `_start` via `:asm _start {...}`
            # inject it verbatim into the text section so it becomes the
            # program entrypoint. Emit the raw body (no automatic `ret`).
            # Do not inject `_start` body here; rely on definitions emission
            # and the earlier `user_has_start` check to suppress the default
            # startup stub. This avoids emitting `_start` twice.
            self._string_literals = {}
            self._string_literal_counter = 0
            self._float_literals = {}
            self._data_section = emission.data
            self._generated_bss = []
            self._generated_bss_counter = 0
            self._cstruct_layouts = dict(module.cstruct_layouts)

            valid_defs = (Definition, AsmDefinition)
            definitions = self._selected_definitions(module)

            stray_forms = [form for form in module.forms if not isinstance(form, valid_defs)]
            if stray_forms:
                raise CompileError("top-level literals or word references are not supported yet", code="emission-top-level-form")

            _v = self.verbosity
            if _v >= 1:
                import time as _time_mod
                _emit_t0 = _time_mod.perf_counter()
                n_def = sum(1 for d in definitions if isinstance(d, Definition))
                n_asm = sum(1 for d in definitions if isinstance(d, AsmDefinition))
                print(f"[v1] definitions: {n_def} high-level, {n_asm} asm")
                opts = []
                if self.enable_loop_unroll: opts.append(f"loop-unroll(threshold={self.loop_unroll_threshold})")
                if self.enable_peephole_optimization: opts.append("peephole")
                if self.enable_constant_folding: opts.append("constant-folding")
                if self.enable_auto_inline: opts.append("auto-inline")
                if self.enable_string_deduplication: opts.append("string-dedup")
                else: opts.append("string-no-dedup")
                if self.enable_extern_type_check: opts.append("extern-type-check")
                if self.enable_stack_check: opts.append("stack-check")
                print(f"[v1] optimizations: {', '.join(opts) if opts else 'none'}")

            if _v >= 2:
                # v2: log per-definition summary before optimization
                for defn in definitions:
                    if isinstance(defn, Definition):
                        print(f"[v2] def '{defn.name}': {len(defn.body)} ops, inline={getattr(defn, 'inline', False)}, compile_only={getattr(defn, 'compile_only', False)}")
                    else:
                        print(f"[v2] asm '{defn.name}'")

            # --- Early DCE: compute reachable set before optimization passes
            # so we skip optimizing definitions that will be eliminated. ---
            if is_program:
                _early_rt = [d for d in definitions if not getattr(d, "compile_only", False)]
                _early_reachable = self._reachable_runtime_defs(_early_rt)
                # Also include inline defs that are referenced by reachable defs
                # (they need optimization for correct inlining).
            else:
                _early_reachable = None  # library mode: optimize everything

            if self.enable_loop_unroll:
                if self.event_bus is not None:
                    self.event_bus.publish("optimization.begin", {"pass": "loop-unroll"})
                if _v >= 1: _t0 = _time_mod.perf_counter()
                for defn in definitions:
                    if isinstance(defn, Definition):
                        if _early_reachable is not None and defn.name not in _early_reachable:
                            continue
                        self._unroll_constant_for_loops(defn)
                if _v >= 1:
                    print(f"[v1] loop unrolling: {(_time_mod.perf_counter() - _t0)*1000:.2f}ms")
                if self.event_bus is not None:
                    self.event_bus.publish("optimization.end", {"pass": "loop-unroll"})
            if self.enable_peephole_optimization:
                if self.event_bus is not None:
                    self.event_bus.publish("optimization.begin", {"pass": "peephole"})
                if _v >= 1: _t0 = _time_mod.perf_counter()
                if _v >= 4:
                    for defn in definitions:
                        if isinstance(defn, Definition):
                            if _early_reachable is not None and defn.name not in _early_reachable:
                                continue
                            before_ops = [(n.op, n.data) for n in defn.body]
                            self._peephole_optimize_definition(defn)
                            after_ops = [(n.op, n.data) for n in defn.body]
                            if before_ops != after_ops:
                                print(f"[v2] peephole '{defn.name}': {len(before_ops)} -> {len(after_ops)} ops ({len(before_ops) - len(after_ops)} removed)")
                                self._log_op_diff(defn.name, "peephole", before_ops, after_ops)
                elif _v >= 2:
                    for defn in definitions:
                        if isinstance(defn, Definition):
                            if _early_reachable is not None and defn.name not in _early_reachable:
                                continue
                            _before = len(defn.body)
                            self._peephole_optimize_definition(defn)
                            _after = len(defn.body)
                            if _before != _after:
                                print(f"[v2] peephole '{defn.name}': {_before} -> {_after} ops ({_before - _after} removed)")
                else:
                    for defn in definitions:
                        if isinstance(defn, Definition):
                            if _early_reachable is not None and defn.name not in _early_reachable:
                                continue
                            self._peephole_optimize_definition(defn)
                if _v >= 1:
                    print(f"[v1] peephole optimization: {(_time_mod.perf_counter() - _t0)*1000:.2f}ms")
                if self.event_bus is not None:
                    self.event_bus.publish("optimization.end", {"pass": "peephole"})
            if self.enable_constant_folding:
                if self.event_bus is not None:
                    self.event_bus.publish("optimization.begin", {"pass": "constant-fold"})
                if _v >= 1: _t0 = _time_mod.perf_counter()
                if _v >= 4:
                    for defn in definitions:
                        if isinstance(defn, Definition):
                            if _early_reachable is not None and defn.name not in _early_reachable:
                                continue
                            before_ops = [(n.op, n.data) for n in defn.body]
                            self._fold_constants_in_definition(defn)
                            after_ops = [(n.op, n.data) for n in defn.body]
                            if before_ops != after_ops:
                                print(f"[v2] constant-fold '{defn.name}': {len(before_ops)} -> {len(after_ops)} ops ({len(before_ops) - len(after_ops)} folded)")
                                self._log_op_diff(defn.name, "constant-fold", before_ops, after_ops)
                elif _v >= 2:
                    for defn in definitions:
                        if isinstance(defn, Definition):
                            if _early_reachable is not None and defn.name not in _early_reachable:
                                continue
                            _before = len(defn.body)
                            self._fold_constants_in_definition(defn)
                            _after = len(defn.body)
                            if _before != _after:
                                print(f"[v2] constant-fold '{defn.name}': {_before} -> {_after} ops ({_before - _after} folded)")
                else:
                    for defn in definitions:
                        if isinstance(defn, Definition):
                            if _early_reachable is not None and defn.name not in _early_reachable:
                                continue
                            self._fold_constants_in_definition(defn)
                if _v >= 1:
                    print(f"[v1] constant folding: {(_time_mod.perf_counter() - _t0)*1000:.2f}ms")
                if self.event_bus is not None:
                    self.event_bus.publish("optimization.end", {"pass": "constant-fold"})

            if _v >= 1:
                _t0 = _time_mod.perf_counter()
            for defn in definitions:
                if not isinstance(defn, Definition):
                    continue
                if _early_reachable is not None and defn.name not in _early_reachable:
                    continue
                self._audit_optimized_definition(defn)
            if _v >= 1:
                print(f"[v1] optimizer audit: {(_time_mod.perf_counter() - _t0)*1000:.2f}ms")

            runtime_defs = [defn for defn in definitions if not getattr(defn, "compile_only", False)]
            if is_program:
                if not any(defn.name == "main" for defn in runtime_defs):
                    raise CompileError("missing 'main' definition", code="emission-main-missing")
                # Determine if any user-provided `_start` asm calls into
                # defined words and use those call targets as additional
                # reachability roots. This avoids unconditionally emitting
                # every `:asm` body while still preserving functions that
                # are invoked from a custom `_start` stub.
                # Build a quick lookup of runtime definition names -> defn
                name_to_def: Dict[str, Union[Definition, AsmDefinition]] = {d.name: d for d in runtime_defs}
                # Look for an asm `_start` among parsed definitions (not just runtime_defs)
                asm_start = next((d for d in definitions if isinstance(d, AsmDefinition) and d.name == "_start"), None)
                extra_roots: List[str] = []
                extra_roots.extend(
                    defn.name for defn in runtime_defs if getattr(defn, "preserve", False)
                )
                if asm_start is not None:
                    called = self._extract_called_symbols_from_asm(asm_start.body)
                    # Resolve called symbols to definition names using both
                    # raw and sanitized forms.
                    sanitized_map = {sanitize_label(n): n for n in name_to_def}
                    for sym in called:
                        if sym in name_to_def:
                            extra_roots.append(sym)
                        else:
                            resolved = sanitized_map.get(sym)
                            if resolved:
                                extra_roots.append(resolved)

                # Ensure a user-provided raw `_start` asm definition is
                # always emitted (it should override the default stub).
                if asm_start is not None and asm_start not in runtime_defs:
                    runtime_defs.append(asm_start)

                reachable = self._reachable_runtime_defs(runtime_defs, extra_roots=extra_roots)
                if len(reachable) != len(runtime_defs):
                    eliminated = [defn.name for defn in runtime_defs if defn.name not in reachable]
                    _n_before_dce = len(runtime_defs)
                    runtime_defs = [defn for defn in runtime_defs if defn.name in reachable]
                    if _v >= 1:
                        print(f"[v1] DCE: {_n_before_dce} -> {len(runtime_defs)} definitions ({_n_before_dce - len(runtime_defs)} eliminated)")
                    if _v >= 2 and eliminated:
                        print(f"[v2] DCE eliminated: {', '.join(eliminated)}")
                    if self.event_bus is not None:
                        for name in eliminated:
                            self.event_bus.publish("dce.eliminate", {"name": name, "reason": "unreachable"})
                # Ensure `_start` is preserved even if not reachable from
                # `main` or the discovered roots; user-provided `_start`
                # must override the default stub.
                if asm_start is not None and asm_start not in runtime_defs:
                    runtime_defs.append(asm_start)
            elif self._export_all_defs:
                exported = sorted({sanitize_label(defn.name) for defn in runtime_defs})
                for label in exported:
                    emission.text.append(f"global {label}")

            runtime_defs = [
                defn for defn in runtime_defs
                if not getattr(defn, "inline", False) or getattr(defn, "preserve", False)
            ]

            if self._need_cfg:
                self._last_cfg_definitions = [
                    self._copy_definition_for_cfg(defn)
                    for defn in runtime_defs
                    if isinstance(defn, Definition)
                ]

            if self.enable_extern_type_check or self.enable_stack_check:
                if _v >= 1: _t0 = _time_mod.perf_counter()
                self._check_extern_types(runtime_defs)
                if _v >= 1:
                    print(f"[v1] type/stack checking: {(_time_mod.perf_counter() - _t0)*1000:.2f}ms")

            if _v >= 1:
                print(f"[v1] emitting {len(runtime_defs)} runtime definitions")

            if _v >= 1: _t0 = _time_mod.perf_counter()
            text_bytes_before = emission.text_byte_length()
            for definition in runtime_defs:
                _event_start = time.perf_counter_ns()
                if _v >= 3:
                    body_len = len(definition.body) if isinstance(definition, Definition) else 0
                    kind = "asm" if isinstance(definition, AsmDefinition) else "def"
                    # v3: dump full body opcodes
                    print(f"[v3] emit {kind} '{definition.name}' (body ops: {body_len})")
                    if isinstance(definition, Definition) and definition.body:
                        for i, node in enumerate(definition.body):
                            print(f"[v3]   [{i}] {node.op}({node.data!r})")
                self._emit_definition(definition, emission.text, debug=debug)
                if self.event_bus is not None:
                    text_bytes_after = emission.text_byte_length()
                    self.event_bus.publish(
                        "emit.section",
                        {"section": "text", "word": definition.name, "bytes_appended": max(0, text_bytes_after - text_bytes_before)},
                    )
                    text_bytes_before = text_bytes_after
                    self.event_bus.publish(
                        "word.compile.end",
                        {"name": definition.name, "kind": "asm" if isinstance(definition, AsmDefinition) else "regular", "duration_ns": time.perf_counter_ns() - _event_start, "size_bytes": 0},
                    )
            if c_abi:
                self._emit_sysv_wrappers(runtime_defs, emission, module, module_name=module_name)
            if _v >= 1:
                print(f"[v1] code emission: {(_time_mod.perf_counter() - _t0)*1000:.2f}ms")

            # --- now generate and emit the runtime prelude ---
            # Only an explicit `:asm _start` definition suppresses the default
            # startup stub; CT text-preamble fragments never own the entry
            # point (a `_start` inside one is an ordinary duplicate symbol).
            user_has_start = any(isinstance(d, AsmDefinition) and d.name == "_start" for d in definitions)
            prelude_lines = self._runtime_prelude(entry_mode, has_user_start=user_has_start)
            if user_has_start and prelude_lines is not None:
                # Avoid re-declaring the default startup symbol when the
                # user provided their own `_start`. Do not remove the
                # user's `_start` body. Only
                # filter out any stray `global _start` markers.
                prelude_lines = [l for l in prelude_lines if l.strip() != "global _start"]
            # Tag any `_start:` occurrences in the prelude with a
            # provenance comment so generated ASM files make it easy
            # to see where each `_start` originated. This is
            # non-destructive (comments only) and helps debug duplicates.
            if prelude_lines is not None:
                tagged = []
                for l in prelude_lines:
                    if l.strip().startswith("_start:"):
                        tagged.append("; __ORIGIN__ prelude")
                        tagged.append(l)
                    else:
                        tagged.append(l)
                prelude_lines = tagged
            # Runtime prelude, then the CT text preamble, then definitions.
            emission.text = (prelude_lines if prelude_lines is not None else []) + list(module.text_preamble) + list(emission.text)
            if module.text_preamble or module.data or module.bss is not None:
                emission.fragments = True
            try:
                self._emitted_start = user_has_start
            except Exception:
                self._emitted_start = False
            # If no `_start` has been emitted (either detected in
            # definitions or already present in the
            # composed `emission.text`), append the default startup
            # stub now (after definitions) so the emitter does not
            # produce duplicate `_start` labels.
            if is_program and not (user_has_start or getattr(self, "_emitted_start", False)):
                emission.text.extend([
                    "; __ORIGIN__ default_stub",
                    "global _start",
                    "_start:",
                    "    ; Linux x86-64 startup: argc/argv from stack",
                    "    mov rdi, [rsp]",         # argc
                    "    lea rsi, [rsp+8]",      # argv
                    "    mov [rel sys_argc], rdi",
                    "    mov [rel sys_argv], rsi",
                    "    ; initialize data/return stack pointers",
                    "    lea r12, [rel dstack_top]",
                    "    lea r13, [rel rstack_top]",
                    f"    call {sanitize_label('main')}",
                    "    mov rax, 0",
                    "    lea rcx, [rel dstack_top]",
                    "    cmp r12, rcx",
                    "    je .no_exit_value",
                    "    mov rax, [r12]",
                    "    add r12, 8",
                    ".no_exit_value:",
                    "    mov rdi, rax",
                    "    mov rax, 60",
                    "    syscall",
                ])

            if module.data and self._data_section is not None:
                self._data_section.extend(module.data)

            self._emit_variables(module.variables)

            if self._data_section is not None:
                self._ensure_data_start()
                if not self._data_section or self._data_section[-1] != "data_end:":
                    self._data_section.append("data_end:")
            bss_lines = module.bss if module.bss is not None else list(_RUNTIME_BSS_LAYOUT)
            if self._generated_bss:
                bss_lines = list(bss_lines) + self._generated_bss
            emission.bss.extend(bss_lines)
            if _v >= 1:
                _emit_dt = (_time_mod.perf_counter() - _emit_t0) * 1000
                print(f"[v1] total emit: {_emit_dt:.2f}ms")
            return emission
        finally:
            self._data_section = None
            self._export_all_defs = False

    def _selected_definitions(self, module: Module) -> List[Union[Definition, AsmDefinition]]:
        """The definitions to emit: each name's selected candidate in the
        emission snapshot, in module order, then selected definitions that
        have no module form (revealed fallbacks, clones, renames)."""
        valid_defs = (Definition, AsmDefinition)
        chosen: Dict[int, Tuple[int, Union[Definition, AsmDefinition]]] = {}
        for word in self._emit_words.values():
            definition = word.definition
            if word.handle is not None and isinstance(definition, valid_defs):
                chosen[id(definition)] = (word.seq, definition)
        ordered: List[Union[Definition, AsmDefinition]] = []
        for form in module.forms:
            entry = chosen.pop(id(form), None)
            if entry is not None:
                ordered.append(entry[1])
        ordered.extend(definition for _, definition in sorted(chosen.values(), key=lambda item: item[0]))
        return ordered

    def _emit_variables(self, variables: Dict[str, str]) -> None:
        if not variables:
            return
        self._ensure_data_start()
        existing = set()
        if self._data_section is not None:
            for line in self._data_section:
                if ":" in line:
                    label = line.split(":", 1)[0]
                    existing.add(label.strip())
        for label in variables.values():
            if label in existing:
                continue
            self._data_section.append(f"{label}: dq 0")

    def _allocate_bss_list_storage(self, size: int) -> str:
        if size < 0:
            raise CompileError("bss list size must be >= 0", code="emission-bss-list-invalid")
        label = f"bss_list_{self._generated_bss_counter}"
        self._generated_bss_counter += 1
        self._generated_bss.append("align 16")
        self._generated_bss.append(f"{label}: resq {size + 1}")
        return label

    def _ensure_data_start(self) -> None:
        if self._data_section is None:
            raise CompileError("data section is not initialized", code="internal-emitter")
        if not self._data_section:
            self._data_section.append("data_start:")
            return
        if not any(line.strip().startswith("data_start:") for line in self._data_section):
            self._data_section.insert(0, "data_start:")

    def _intern_string_literal(self, value: str) -> Tuple[str, int]:
        if self._data_section is None:
            raise CompileError("string literal emission requested without data section", code="internal-emitter")
        self._ensure_data_start()
        if self.enable_string_deduplication and value in self._string_literals:
            return self._string_literals[value]
        label = f"str_{self._string_literal_counter}"
        self._string_literal_counter += 1
        encoded = value.encode("utf-8")
        bytes_with_nul = list(encoded) + [0]
        byte_list = ", ".join(str(b) for b in bytes_with_nul)
        self._data_section.append(f"{label}: db {byte_list}")
        self._data_section.append(f"{label}_len equ {len(encoded)}")
        self._string_literals[value] = (label, len(encoded))
        return label, len(encoded)

    def _intern_float_literal(self, value: float) -> str:
        if self._data_section is None:
            raise CompileError("float literal emission requested without data section", code="internal-emitter")
        self._ensure_data_start()
        if value in self._float_literals:
            return self._float_literals[value]
        label = f"flt_{len(self._float_literals)}"
        # Use hex representation of double precision float
        import struct
        hex_val = _get_struct().pack('>d', value).hex()
        # NASM expects hex starting with 0x
        self._data_section.append(f"{label}: dq 0x{hex_val}")
        self._float_literals[value] = label
        return label

    def _emit_definition(
        self,
        definition: Union[Definition, AsmDefinition],
        text: List[str],
        *,
        debug: bool = False,
    ) -> None:
        # If a `_start` label has already been emitted in the prelude,
        # skip emitting a second `_start` definition which would cause
        # assembler redefinition errors. The prelude-provided `_start`
        # (if present) is taken to be authoritative.
        if definition.name == "_start" and getattr(self, "_emitted_start", False):
            return
        # If this is a raw assembly definition, tag its origin so the
        # generated ASM clearly shows the source of the label (helpful
        # when diagnosing duplicate `_start` occurrences).
        if isinstance(definition, AsmDefinition):
            text.append(f"; __ORIGIN__ AsmDefinition {definition.name}")
        label = sanitize_label(definition.name)

        # Record start index so we can write a per-definition snapshot
        start_index = len(text)
        # If this definition is the program entry `_start`, ensure it's
        # exported as a global symbol so the linker sets the process
        # entry point correctly. Some earlier sanitizer passes may
        # remove `global _start` from prelude fragments; make sure user
        # provided `_start` remains globally visible.
        if label == "_start":
            text.append("global _start")
        text.append(f"{label}:")
        builder = FunctionEmitter(text, debug_enabled=debug)
        self._emit_stack.append(definition.name)
        try:
            if isinstance(definition, Definition):
                idx = 0
                body = definition.body
                body_len = len(body)
                while idx < body_len:
                    node = body[idx]
                    self._current_emit_loc = node.loc
                    if node._opcode == OP_WORD:
                        next_node = body[idx + 1] if idx + 1 < body_len else None
                        tail_position = next_node is None or next_node._opcode == OP_RET
                        if tail_position and self._emit_tail_wordref(str(node.data), builder):
                            if next_node is not None and next_node._opcode == OP_RET:
                                idx += 2
                            else:
                                idx += 1
                            continue
                    self._emit_node(node, builder)
                    idx += 1
            elif isinstance(definition, AsmDefinition):
                self._emit_asm_body(definition, builder)
            else:  # pragma: no cover - defensive
                raise CompileError("unknown definition type", code="internal-emitter")
            builder.emit("    ret")
        finally:
            self._emit_stack.pop()

    def _emit_inline_definition(self, word: Word, builder: FunctionEmitter) -> None:
        definition = word.definition
        if not isinstance(definition, Definition):
            raise CompileError(f"inline word '{word.name}' requires a high-level definition", code="emission-inline-invalid")

        self._emit_stack.append(f"{word.name} (inline)")

        suffix = self._inline_counter
        self._inline_counter += 1

        label_map: Dict[str, str] = {}

        def remap(label: str) -> str:
            if label not in label_map:
                label_map[label] = f"{label}__inl{suffix}"
            return label_map[label]

        for node in definition.body:
            kind = node._opcode
            data = node.data
            if kind == OP_LABEL:
                mapped = remap(str(data))
                self._emit_node(_make_op("label", mapped), builder)
                continue
            if kind == OP_JUMP:
                mapped = remap(str(data))
                self._emit_node(_make_op("jump", mapped), builder)
                continue
            if kind == OP_BRANCH_ZERO:
                mapped = remap(str(data))
                self._emit_node(_make_op("branch_zero", mapped), builder)
                continue
            if kind == OP_FOR_BEGIN:
                mapped = {
                    "loop": remap(data["loop"]),
                    "end": remap(data["end"]),
                }
                self._emit_node(_make_op("for_begin", mapped), builder)
                continue
            if kind == OP_FOR_END:
                mapped = {
                    "loop": remap(data["loop"]),
                    "end": remap(data["end"]),
                }
                self._emit_node(_make_op("for_end", mapped), builder)
                continue
            if kind == OP_LIST_BEGIN or kind == OP_LIST_END:
                mapped = remap(str(data))
                self._emit_node(_make_op(node.op, mapped), builder)
                continue
            self._emit_node(node, builder)

        self._emit_stack.pop()

    def _emit_asm_body(self, definition: AsmDefinition, builder: FunctionEmitter) -> None:
        body = definition.body.strip("\n")
        if not body:
            return
        _call_sub = _RE_ASM_CALL.sub
        _global_sub = _RE_ASM_GLOBAL.sub
        _extern_sub = _RE_ASM_EXTERN.sub
        def repl_sym(m: re.Match) -> str:
            name = m.group(1)
            # Skip registers and common assembler keywords
            if name.lower() in _X86_64_REGISTERS:
                return m.group(0)
            # Sanitization prefixing is applied to avoid accidental collisions.
            return m.group(0).replace(name, sanitize_label(name))
        for line in body.splitlines():
            if not line.strip():
                continue
            if "call " in line or "global " in line or "extern " in line:
                line = _call_sub(repl_sym, line)
                line = _global_sub(repl_sym, line)
                line = _extern_sub(repl_sym, line)
            builder.emit(line)

    def _emit_asm_body_inline(self, definition: AsmDefinition, builder: FunctionEmitter) -> None:
        """Emit an asm body inline, stripping ret instructions."""
        # Cache sanitized lines on the definition to avoid re-parsing.
        cached = definition._inline_lines
        if cached is None:
            _call_sub = _RE_ASM_CALL.sub
            _global_sub = _RE_ASM_GLOBAL.sub
            _extern_sub = _RE_ASM_EXTERN.sub
            def repl_sym(m: re.Match) -> str:
                name = m.group(1)
                # Skip registers and common assembler keywords
                if name.lower() in _X86_64_REGISTERS:
                    return m.group(0)
                # Sanitization prefixing is applied to avoid accidental collisions.
                return m.group(0).replace(name, sanitize_label(name))
            cached = []
            body = definition.body.strip("\n")
            for line in body.splitlines():
                stripped = line.strip()
                if not stripped or stripped == "ret":
                    continue
                if "call " in line or "global " in line or "extern " in line:
                    line = _call_sub(repl_sym, line)
                    line = _global_sub(repl_sym, line)
                    line = _extern_sub(repl_sym, line)
                cached.append(line)
            definition._inline_lines = cached
        text = builder.text
        text.extend(cached)

    def _emit_node(self, node: Op, builder: FunctionEmitter) -> None:
        kind = node._opcode
        data = node.data
        self._current_emit_loc = node.loc
        builder.set_location(node.loc)

        if kind == OP_WORD:
            self._emit_wordref(data, builder)
            return

        if kind == OP_LITERAL:
            if isinstance(data, int):
                builder.push_literal(data)
                return
            if isinstance(data, float):
                label = self._intern_float_literal(data)
                builder.push_float(label)
                return
            if isinstance(data, str):
                label, length = self._intern_string_literal(data)
                builder.push_label(label)
                builder.push_literal(length)
                return
            self._raise_compile_error(
                f"unsupported literal type {type(data)!r}",
                node=node,
                code="internal-emitter",
            )

        if kind == OP_WORD_PTR:
            self._emit_wordptr(data, builder)
            return

        if kind == OP_BRANCH_ZERO:
            self._emit_branch_zero(data, builder)
            return

        if kind == OP_JUMP:
            builder.emit(f"    jmp {data}")
            return

        if kind == OP_LABEL:
            builder.emit(f"{data}:")
            return

        if kind == OP_FOR_BEGIN:
            self._emit_for_begin(data, builder)
            return

        if kind == OP_FOR_END:
            self._emit_for_next(data, builder)
            return

        if kind == OP_LIST_BEGIN:
            builder.comment("list begin")
            builder.emit("    mov rax, [rel list_capture_sp]")
            builder.emit("    lea rdx, [rel list_capture_stack]")
            builder.emit("    mov [rdx + rax*8], r12")
            builder.emit("    inc rax")
            builder.emit("    mov [rel list_capture_sp], rax")
            return

        if kind == OP_LIST_LITERAL:
            values = list(data or [])
            count = len(values)
            bytes_needed = (count + 1) * 8
            builder.comment("list literal")
            builder.emit("    xor rdi, rdi")
            builder.emit(f"    mov rsi, {bytes_needed}")
            builder.emit("    mov rdx, 3")
            builder.emit("    mov r10, 34")
            builder.emit("    mov r8, -1")
            builder.emit("    xor r9, r9")
            builder.emit("    mov rax, 9")
            builder.emit("    syscall")
            builder.emit(f"    mov qword [rax], {count}")
            for idx_item, value in enumerate(values):
                builder.emit(f"    mov qword [rax + {8 + idx_item * 8}], {int(value)}")
            builder.emit("    sub r12, 8")
            builder.emit("    mov [r12], rax")
            return

        if kind == OP_BSS_LIST_LITERAL:
            payload = data if isinstance(data, dict) else {}
            count = int(payload.get("size", 0))
            values = [int(v) for v in list(payload.get("values", []) or [])]
            if count < 0:
                self._raise_compile_error(
                    "bss list size must be >= 0",
                    node=node,
                    code="emission-bss-list-invalid",
                    hint="bss list declarations require a non-negative size",
                    suggestion="use `:0` for empty lists or provide a positive size",
                )
            if len(values) > count:
                self._raise_compile_error(
                    "bss list has more initializer values than declared size",
                    node=node,
                    code="emission-bss-list-invalid",
                    hint="initializer count cannot exceed declared bss list size",
                    suggestion="increase declared size or remove extra initializer values",
                )
            label = self._allocate_bss_list_storage(count)
            builder.comment("bss list literal")
            builder.emit(f"    lea rax, [rel {label}]")
            builder.emit(f"    mov qword [rax], {count}")
            for idx_item, value in enumerate(values):
                value = _wrap_i64(int(value)) if isinstance(value, int) else value
                if isinstance(value, int) and not (-0x80000000 <= value <= 0x7FFFFFFF):
                    builder.emit(f"    mov r11, {value}")
                    builder.emit(f"    mov qword [rax + {8 + idx_item * 8}], r11")
                else:
                    builder.emit(f"    mov qword [rax + {8 + idx_item * 8}], {value}")
            for idx_item in range(len(values), count):
                builder.emit(f"    mov qword [rax + {8 + idx_item * 8}], 0")
            builder.emit("    sub r12, 8")
            builder.emit("    mov [r12], rax")
            return

        if kind == OP_LIST_END:
            base = str(data)
            loop_label = f"{base}_copy_loop"
            done_label = f"{base}_copy_done"

            builder.comment("list end")
            # pop capture start pointer
            builder.emit("    mov rax, [rel list_capture_sp]")
            builder.emit("    dec rax")
            builder.emit("    mov [rel list_capture_sp], rax")
            builder.emit("    lea r11, [rel list_capture_stack]")
            builder.emit("    mov rbx, [r11 + rax*8]")
            # count = (start_r12 - r12) / 8
            builder.emit("    mov rcx, rbx")
            builder.emit("    sub rcx, r12")
            builder.emit("    shr rcx, 3")
            builder.emit("    mov [rel list_capture_tmp], rcx")

            # bytes = (count + 1) * 8
            builder.emit("    mov rsi, rcx")
            builder.emit("    inc rsi")
            builder.emit("    shl rsi, 3")

            # mmap(NULL, bytes, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANON, -1, 0)
            builder.emit("    xor rdi, rdi")
            builder.emit("    mov rdx, 3")
            builder.emit("    mov r10, 34")
            builder.emit("    mov r8, -1")
            builder.emit("    xor r9, r9")
            builder.emit("    mov rax, 9")
            builder.emit("    syscall")

            # store length
            builder.emit("    mov rdx, [rel list_capture_tmp]")
            builder.emit("    mov [rax], rdx")

            # copy elements, preserving original push order
            builder.emit("    xor rcx, rcx")
            builder.emit(f"{loop_label}:")
            builder.emit("    cmp rcx, rdx")
            builder.emit(f"    je {done_label}")
            builder.emit("    mov r8, rdx")
            builder.emit("    dec r8")
            builder.emit("    sub r8, rcx")
            builder.emit("    shl r8, 3")
            builder.emit("    mov r9, [r12 + r8]")
            builder.emit("    mov [rax + 8 + rcx*8], r9")
            builder.emit("    inc rcx")
            builder.emit(f"    jmp {loop_label}")
            builder.emit(f"{done_label}:")

            # drop captured values and push list pointer
            builder.emit("    mov r12, rbx")
            builder.emit("    sub r12, 8")
            builder.emit("    mov [r12], rax")
            return

        if kind == OP_RET:
            builder.ret()
            return

        if kind == OP_FOR_DROP:
            builder.emit("    add r13, 8")
            return

        if kind in (OP_MATCH_SELECT, OP_MATCH_LEAVE, OP_BINDING):
            self._raise_compile_error("match and $name bindings are compile-time only and cannot be compiled into "
                                      "runtime code; mark the word compile-only", node=node, code="match-runtime")

        if kind == OP_SYNTAX:
            self._raise_compile_error("a quotation is a compile-time value and cannot be compiled into runtime code; "
                                      "mark the word compile-only or keep it out of runtime code",
                                      node=node, code="syntax-quotation-runtime")

        self._raise_compile_error(f"unsupported operation '{node.op}' (data {node.data!r})", node=node,
                                  code="emission-op-unsupported")

    def _emit_mmap_alloc(self, builder: FunctionEmitter, size: int, target_reg: str = "rax") -> None:
        alloc_size = max(1, int(size))
        builder.emit("    xor rdi, rdi")
        builder.emit(f"    mov rsi, {alloc_size}")
        builder.emit("    mov rdx, 3")
        builder.emit("    mov r10, 34")
        builder.emit("    mov r8, -1")
        builder.emit("    xor r9, r9")
        builder.emit("    mov rax, 9")
        builder.emit("    syscall")
        if target_reg != "rax":
            builder.emit(f"    mov {target_reg}, rax")

    def _analyze_extern_c_type(self, type_name: str) -> Dict[str, Any]:
        size, align, cls, layout = _c_type_size_align_class(type_name, self._cstruct_layouts)
        info: Dict[str, Any] = {
            "name": _canonical_c_type_name(type_name),
            "size": size,
            "align": align,
            "class": cls,
            "kind": "struct" if layout is not None else "scalar",
            "layout": layout,
            "pass_mode": "scalar",
            "eightbytes": [],
        }
        if layout is not None:
            eb = _classify_struct_eightbytes(layout, self._cstruct_layouts)
            info["eightbytes"] = eb or []
            info["pass_mode"] = "register" if eb is not None else "memory"
        return info

    def _emit_copy_bytes_from_ptr(
        self,
        builder: FunctionEmitter,
        *,
        src_ptr_reg: str,
        dst_expr: str,
        size: int,
    ) -> None:
        copied = 0
        while copied + 8 <= size:
            builder.emit(f"    mov r11, [{src_ptr_reg} + {copied}]")
            builder.emit(f"    mov qword [{dst_expr} + {copied}], r11")
            copied += 8
        while copied < size:
            builder.emit(f"    mov r11b, byte [{src_ptr_reg} + {copied}]")
            builder.emit(f"    mov byte [{dst_expr} + {copied}], r11b")
            copied += 1

    @staticmethod
    def _pop_preceding_literal(builder: FunctionEmitter) -> Optional[int]:
        """If the last emitted instructions are a literal push, remove them and return the value."""
        text = builder.text
        n = len(text)
        if n < 3:
            return None
        # push_literal emits:  "; push N" / "sub r12, 8" / "mov qword [r12], N"
        # (wide values: "; push N" / "sub r12, 8" / "mov rax, N" / "mov [r12], rax")
        if n >= 4 and text[n - 1].strip() == "mov [r12], rax" and text[n - 3].strip() == "sub r12, 8" \
                and text[n - 4].strip().startswith("; push") and text[n - 2].strip().startswith("mov rax, "):
            try:
                value = int(text[n - 2].strip()[len("mov rax, "):])
            except ValueError:
                return None
            del text[n - 4:n]
            return value
        mov_line = text[n - 1].strip()
        sub_line = text[n - 2].strip()
        cmt_line = text[n - 3].strip()
        if not (sub_line == "sub r12, 8" and mov_line.startswith("mov qword [r12],") and cmt_line.startswith("; push")):
            return None
        val_str = mov_line.split(",", 1)[1].strip()
        try:
            value = int(val_str)
        except ValueError:
            return None
        del text[n - 3:n]
        return value

    def _emit_extern_wordref(self, name: str, word: Word, builder: FunctionEmitter) -> None:
        inputs = getattr(word, "extern_inputs", 0)
        outputs = getattr(word, "extern_outputs", 0)
        signature = getattr(word, "extern_signature", None)

        if signature is None and inputs <= 0 and outputs <= 0:
            builder.emit(f"    call {name}")
            return

        arg_types = list(signature[0]) if signature else ["long"] * inputs
        ret_type = signature[1] if signature else ("long" if outputs > 0 else "void")

        # For variadic externs, consume the preceding literal as the count of
        # extra variadic arguments.  These are NOT passed to the C function as
        # a count parameter – they simply tell the compiler how many additional
        # stack values to pop and place into registers / the C stack.
        if getattr(word, "extern_variadic", False):
            va_count = self._pop_preceding_literal(builder)
            if va_count is None:
                self._raise_compile_error(
                    f"variadic extern '{name}' requires a literal arg count on TOS",
                    code="emission-extern-variadic-count",
                )
            for _ in range(va_count):
                arg_types.append("long")
            inputs += va_count

        if len(arg_types) != inputs and signature is not None:
            self._raise_compile_error(f"extern '{name}' mismatch: {inputs} inputs vs {len(arg_types)} types",
                                      code="emission-extern-signature")

        arg_infos = [self._analyze_extern_c_type(t) for t in arg_types]
        ret_info = self._analyze_extern_c_type(ret_type)

        regs = ["rdi", "rsi", "rdx", "rcx", "r8", "r9"]
        xmm_regs = [f"xmm{i}" for i in range(8)]

        ret_uses_sret = ret_info["kind"] == "struct" and ret_info["pass_mode"] == "memory"
        int_idx = 1 if ret_uses_sret else 0
        xmm_idx = 0

        arg_locs: List[Dict[str, Any]] = []
        stack_cursor = 0

        for info in arg_infos:
            if info["kind"] == "struct":
                if info["pass_mode"] == "register":
                    classes: List[str] = list(info["eightbytes"])
                    need_int = sum(1 for c in classes if c == "INTEGER")
                    need_xmm = sum(1 for c in classes if c == "SSE")
                    if int_idx + need_int <= len(regs) and xmm_idx + need_xmm <= len(xmm_regs):
                        chunks: List[Tuple[str, str, int]] = []
                        int_off = int_idx
                        xmm_off = xmm_idx
                        for chunk_idx, cls in enumerate(classes):
                            if cls == "SSE":
                                chunks.append((cls, xmm_regs[xmm_off], chunk_idx * 8))
                                xmm_off += 1
                            else:
                                chunks.append(("INTEGER", regs[int_off], chunk_idx * 8))
                                int_off += 1
                        int_idx = int_off
                        xmm_idx = xmm_off
                        arg_locs.append({"mode": "struct_reg", "chunks": chunks, "info": info})
                    else:
                        stack_size = _round_up(int(info["size"]), 8)
                        stack_off = stack_cursor
                        stack_cursor += stack_size
                        arg_locs.append({"mode": "struct_stack", "stack_off": stack_off, "info": info})
                else:
                    stack_size = _round_up(int(info["size"]), 8)
                    stack_off = stack_cursor
                    stack_cursor += stack_size
                    arg_locs.append({"mode": "struct_stack", "stack_off": stack_off, "info": info})
                continue

            if info["class"] == "SSE":
                if xmm_idx < len(xmm_regs):
                    arg_locs.append({"mode": "scalar_reg", "reg": xmm_regs[xmm_idx], "class": "SSE"})
                    xmm_idx += 1
                else:
                    stack_off = stack_cursor
                    stack_cursor += 8
                    arg_locs.append({"mode": "scalar_stack", "stack_off": stack_off, "class": "SSE"})
            else:
                if int_idx < len(regs):
                    arg_locs.append({"mode": "scalar_reg", "reg": regs[int_idx], "class": "INTEGER"})
                    int_idx += 1
                else:
                    stack_off = stack_cursor
                    stack_cursor += 8
                    arg_locs.append({"mode": "scalar_stack", "stack_off": stack_off, "class": "INTEGER"})

        # Preserve and realign RSP for C ABI calls regardless current call depth.
        stack_bytes = max(15, int(stack_cursor) + 15)
        builder.emit("    mov r14, rsp")
        builder.emit(f"    sub rsp, {stack_bytes}")
        builder.emit("    and rsp, -16")

        if ret_info["kind"] == "struct":
            self._emit_mmap_alloc(builder, int(ret_info["size"]), target_reg="r15")
            if ret_uses_sret:
                builder.emit("    mov rdi, r15")

        total_args = len(arg_locs)
        for idx, loc in enumerate(reversed(arg_locs)):
            addr = f"[r12 + {idx * 8}]" if idx > 0 else "[r12]"
            mode = str(loc["mode"])

            if mode == "scalar_reg":
                reg = str(loc["reg"])
                cls = str(loc["class"])
                if cls == "SSE":
                    builder.emit(f"    mov rax, {addr}")
                    builder.emit(f"    movq {reg}, rax")
                else:
                    builder.emit(f"    mov {reg}, {addr}")
                continue

            if mode == "scalar_stack":
                stack_off = int(loc["stack_off"])
                builder.emit(f"    mov rax, {addr}")
                builder.emit(f"    mov qword [rsp + {stack_off}], rax")
                continue

            if mode == "struct_reg":
                chunks: List[Tuple[str, str, int]] = list(loc["chunks"])
                builder.emit(f"    mov rax, {addr}")
                for cls, target, off in chunks:
                    if cls == "SSE":
                        builder.emit(f"    movq {target}, [rax + {off}]")
                    else:
                        builder.emit(f"    mov {target}, [rax + {off}]")
                continue

            if mode == "struct_stack":
                stack_off = int(loc["stack_off"])
                size = int(loc["info"]["size"])
                builder.emit(f"    mov rax, {addr}")
                self._emit_copy_bytes_from_ptr(builder, src_ptr_reg="rax", dst_expr=f"rsp + {stack_off}", size=size)
                continue

            self._raise_compile_error(
                f"internal extern lowering error for '{name}': unknown arg mode {mode!r}",
                code="internal-emitter",
                hint="extern lowering encountered an unexpected internal arg mode",
                suggestion="this is likely a compiler bug; please report a minimal repro",
            )

        if total_args:
            builder.emit(f"    add r12, {total_args * 8}")

        builder.emit(f"    mov al, {xmm_idx}")
        builder.emit(f"    call {name}")

        builder.emit("    mov rsp, r14")

        if ret_info["kind"] == "struct":
            if not ret_uses_sret:
                ret_classes: List[str] = list(ret_info["eightbytes"])
                int_ret_regs = ["rax", "rdx"]
                xmm_ret_regs = ["xmm0", "xmm1"]
                int_ret_idx = 0
                xmm_ret_idx = 0
                for chunk_idx, cls in enumerate(ret_classes):
                    off = chunk_idx * 8
                    if cls == "SSE":
                        src = xmm_ret_regs[xmm_ret_idx]
                        xmm_ret_idx += 1
                        builder.emit(f"    movq [r15 + {off}], {src}")
                    else:
                        src = int_ret_regs[int_ret_idx]
                        int_ret_idx += 1
                        builder.emit(f"    mov [r15 + {off}], {src}")
            builder.emit("    sub r12, 8")
            builder.emit("    mov [r12], r15")
            return

        if _ctype_uses_sse(ret_type):
            builder.emit("    sub r12, 8")
            builder.emit("    movq rax, xmm0")
            builder.emit("    mov [r12], rax")
        elif outputs == 1:
            builder.push_from("rax")
        elif outputs > 1:
            self._raise_compile_error(
                "extern only supports 0 or 1 scalar output",
                code="emission-extern-signature",
                hint="extern lowering currently supports at most one scalar return value",
                suggestion="wrap multiple return values in a struct or return a pointer",
            )

    def _emit_wordref(self, name: str, builder: FunctionEmitter) -> None:
        word = self._emit_words.get(name)
        if word is None:
            self._raise_compile_error(f"unknown word '{name}'", code="emission-unknown-word")
        if word.compile_only:
            self._raise_compile_error(f"word '{name}' is compile-time only and cannot be used at runtime",
                                      code="emission-compile-only-word")
        if getattr(word, "inline", False):
            if isinstance(word.definition, Definition):
                if word.name in self._inline_stack:
                    self._raise_compile_error(
                        f"recursive inline expansion for '{word.name}'",
                        code="emission-inline-invalid",
                        hint="inliner detected a recursive cycle",
                        suggestion="remove `inline` from at least one function in the cycle",
                    )
                self._inline_stack.append(word.name)
                self._emit_inline_definition(word, builder)
                self._inline_stack.pop()
                return
            if isinstance(word.definition, AsmDefinition):
                self._emit_asm_body_inline(word.definition, builder)
                return
        if word.intrinsic:
            word.intrinsic(builder)
            return
        # Auto-inline small asm bodies even without explicit `inline` keyword.
        if self.enable_auto_inline and isinstance(word.definition, AsmDefinition) and self._asm_auto_inline_ok(word.definition):
            self._emit_asm_body_inline(word.definition, builder)
            return
        if getattr(word, "is_extern", False):
            self._emit_extern_wordref(name, word, builder)
        else:
            builder.emit(f"    call {sanitize_label(name)}")

    def _emit_tail_wordref(self, name: str, builder: FunctionEmitter) -> bool:
        word = self._emit_words.get(name)
        if word is None:
            self._raise_compile_error(f"unknown word '{name}'", code="emission-unknown-word")
        if word.compile_only:
            self._raise_compile_error(f"word '{name}' is compile-time only and cannot be used at runtime",
                                      code="emission-compile-only-word")

        # Tail-jump only for regular runtime words that would otherwise emit a call.
        if getattr(word, "inline", False):
            return False
        if word.intrinsic is not None:
            return False
        if getattr(word, "is_extern", False):
            return False
        if self.enable_auto_inline and isinstance(word.definition, AsmDefinition) and self._asm_auto_inline_ok(word.definition):
            return False

        builder.emit(f"    jmp {sanitize_label(name)}")
        return True

    @staticmethod
    def _asm_auto_inline_ok(defn: AsmDefinition) -> bool:
        """Return True if *defn* is small enough to auto-inline at call sites."""
        cached = defn._inline_lines
        if cached is not None:
            return len(cached) <= _ASM_AUTO_INLINE_THRESHOLD
        count = 0
        for line in defn.body.split('\n'):
            s = line.strip()
            if not s or s == 'ret':
                continue
            if s.endswith(':'):
                return False  # labels would duplicate on multiple inlines
            if 'rsp' in s:
                return False  # references call-frame; must stay a real call
            count += 1
            if count > _ASM_AUTO_INLINE_THRESHOLD:
                return False
        return True

    def _emit_wordptr(self, name: str, builder: FunctionEmitter) -> None:
        word = self._emit_words.get(name)
        if word is None:
            self._raise_compile_error(f"unknown word '{name}'", code="emission-unknown-word")
        if getattr(word, "is_extern", False):
            builder.push_label(name)
            return
        builder.push_label(sanitize_label(name))

    def _emit_branch_zero(self, target: str, builder: FunctionEmitter) -> None:
        builder.pop_to("rax")
        builder.emit("    test rax, rax")
        builder.emit(f"    jz {target}")

    def _emit_for_begin(self, data: Dict[str, str], builder: FunctionEmitter) -> None:
        loop_label = data["loop"]
        end_label = data["end"]
        builder.pop_to("rax")
        builder.emit("    cmp rax, 0")
        builder.emit(f"    jle {end_label}")
        builder.emit("    sub r13, 8")
        builder.emit("    mov [r13], rax")
        builder.emit(f"{loop_label}:")

    def _emit_for_next(self, data: Dict[str, str], builder: FunctionEmitter) -> None:
        loop_label = data["loop"]
        end_label = data["end"]
        builder.emit("    mov rax, [r13]")
        builder.emit("    dec rax")
        builder.emit("    mov [r13], rax")
        builder.emit(f"    jg {loop_label}")
        builder.emit("    add r13, 8")
        builder.emit(f"{end_label}:")

    def _emit_sysv_wrappers(
        self,
        definitions: Sequence[Union[Definition, AsmDefinition]],
        emission: Emission,
        module: Module,
        module_name: str = "l2",
    ) -> None:
        targets = [
            d for d in definitions
            if not getattr(d, "compile_only", False)
            and not getattr(d, "immediate", False)
        ]

        if not targets:
            return

        arg_regs = ["rsi", "rdx", "rcx", "r8", "r9"]
        wrapper_lines: List[str] = [
            "",
            "; -----------------------------------------------------------------------------",
            "; SysV C ABI Wrappers",
            "; -----------------------------------------------------------------------------",
        ]
        header_decls: List[str] = []
        guard = re.sub(r'[^a-zA-Z0-9_]', '_', module_name).upper()
        wrapper_symbols: Set[str] = set()
        c_names = [re.sub(r'[^a-zA-Z0-9_]', '_', d.name) for d in targets]
        for index, c_name in enumerate(c_names):
            if c_name and c_name[0].isdigit():
                c_names[index] = "_" + c_name
        c_name_counts: Dict[str, int] = {}
        for c_name in c_names:
            c_name_counts[c_name] = c_name_counts.get(c_name, 0) + 1
        reserved_c_names = set(c_names)
        used_c_names: Set[str] = set()

        for defn, base_c_name in zip(targets, c_names):
            c_name = base_c_name
            if c_name_counts[base_c_name] > 1:
                c_name = f"{base_c_name}__{defn.name.encode('utf-8').hex()}"
                while c_name in reserved_c_names or c_name in used_c_names:
                    c_name += "_"
            elif c_name in used_c_names:
                raise CompileError(
                    f"function '{defn.name}' collides with another SysV wrapper symbol 'l2_{c_name}'",
                    code="emission-symbol-collision",
                )
            used_c_names.add(c_name)
            wrapper_sym = f"l2_{c_name}"
            if wrapper_sym in wrapper_symbols:
                raise CompileError(
                    f"function '{defn.name}' collides with another SysV wrapper symbol '{wrapper_sym}'",
                    code="emission-symbol-collision",
                )
            wrapper_symbols.add(wrapper_sym)

            wrapper_lines.extend([
                f"global {wrapper_sym}",
                f"{wrapper_sym}:",
                "    push rbp",
                "    mov rbp, rsp",
                "    push rbx",
                "    push r12",
                "    push r13",
                "    sub rsp, 56",
                "    mov [rbp - 80], rdi",
                f"    mov [rbp - 72], {arg_regs[0]}",
                f"    mov [rbp - 64], {arg_regs[1]}",
                f"    mov [rbp - 56], {arg_regs[2]}",
                f"    mov [rbp - 48], {arg_regs[3]}",
                f"    mov [rbp - 40], {arg_regs[4]}",
                "    lea r12, [rel dstack_top]",
                "    lea r13, [rel rstack_top]",
                "    xor ecx, ecx",
                f".l2_{c_name}_args_loop:",
                "    cmp rcx, [rbp - 80]",
                f"    jae .l2_{c_name}_args_done",
                "    cmp rcx, 5",
                f"    jae .l2_{c_name}_stack_arg",
                "    mov rax, [rbp + rcx * 8 - 72]",
                f"    jmp .l2_{c_name}_push_arg",
                f".l2_{c_name}_stack_arg:",
                "    mov rax, [rbp + rcx * 8 - 24]",
                f".l2_{c_name}_push_arg:",
                "    sub r12, 8",
                "    mov [r12], rax",
                "    inc rcx",
                f"    jmp .l2_{c_name}_args_loop",
                f".l2_{c_name}_args_done:",
            ])

            wrapper_lines.append(f"    call {sanitize_label(defn.name)}")
            wrapper_lines.extend([
                "    mov rax, [r12]",
                "    add r12, 8",
            ])

            wrapper_lines.extend([
                "    add rsp, 56",
                "    pop r13",
                "    pop r12",
                "    pop rbx",
                "    pop rbp",
                "    ret",
                "",
            ])

            header_decls.append(f"int64_t {wrapper_sym}(size_t argc, ...);")

        emission.text.extend(wrapper_lines)

        decls_formatted = "\n".join(header_decls)
        emission.c_header = (
            f"/* Auto-generated by L2 compiler with --c-abi. Do not edit. */\n"
            f"#ifndef L2_WRAPPERS_{guard}_H\n"
            f"#define L2_WRAPPERS_{guard}_H\n\n"
            f"#include <stdint.h>\n\n"
            f"#include <stddef.h>\n\n"
            f"#ifdef __cplusplus\n"
            f"extern \"C\" {{\n"
            f"#endif\n\n"
            f"{decls_formatted}\n\n"
            f"#ifdef __cplusplus\n"
            f"}}\n"
            f"#endif\n\n"
            f"#endif /* L2_WRAPPERS_{guard}_H */\n"
        )

    def _runtime_prelude(self, entry_mode: str, has_user_start: bool = False) -> List[str]:
        lines: List[str] = [
            "%define DSTK_BYTES 65536",
            "%define RSTK_BYTES 65536",
            "%define PRINT_BUF_BYTES 128",
        ]
        is_program = entry_mode == "program"
        lines.extend([
            "global sys_argc",
            "global sys_argv",
            "section .data",
            "sys_argc: dq 0",
            "sys_argv: dq 0",
            "section .text",
        ])
        # Do not emit the default `_start` stub here; it will be appended
        # after definitions have been emitted if no user `_start` was
        # provided. This avoids duplicate or partial `_start` blocks.

        return lines

    @property
    def source_catalog(self) -> Optional[List[Tuple[str, str]]]:
        """Name -> exact retained source of each final selected definition
        of the last emission (built on demand for --source-embed)."""
        words = self._catalog_words
        if words is None:
            return None
        return sorted((name, word.source_text) for name, word in words.items()
                      if word.handle is not None and word.source_text)

    def write_asm(self, emission: Emission, path: Path) -> None:
        path.write_text(emission.snapshot())

# ---------------------------------------------------------------------------
# § 15. Built-in macros and compile-time words
# ---------------------------------------------------------------------------


def macro_immediate(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    word = parser.most_recent_definition()
    if word is None:
        raise ParseError("'immediate' must follow a definition", code="definition-modifier-invalid")
    if word.runtime_only:
        raise ParseError(f"word '{word.name}' is runtime-only and cannot be immediate", code="definition-modifier-invalid")
    word.immediate = True
    if word.definition is not None:
        word.definition.immediate = True
    return None


def macro_compile_only(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    word = parser.most_recent_definition()
    if word is None:
        raise ParseError("'compile-only' must follow a definition", code="definition-modifier-invalid")
    if word.runtime_only:
        raise ParseError(f"word '{word.name}' is runtime-only and cannot be compile-only", code="definition-modifier-invalid")
    word.compile_only = True
    if word.definition is not None:
        word.definition.compile_only = True
    return None


def macro_runtime(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    word = parser.most_recent_definition()
    if word is None:
        raise ParseError("'runtime' must follow a definition", code="definition-modifier-invalid")
    if word.immediate:
        raise ParseError(f"word '{word.name}' is immediate and cannot be runtime-only", code="definition-modifier-invalid")
    if word.compile_only:
        raise ParseError(f"word '{word.name}' is compile-only and cannot be runtime-only", code="definition-modifier-invalid")
    word.runtime_only = True
    if word.definition is not None:
        word.definition.runtime_only = True
    return None


def macro_inline(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    next_tok = parser.peek_token()
    if next_tok is None or next_tok.lexeme not in ("word", ":asm", "preserve"):
        raise ParseError("'inline' must be followed by 'word', ':asm', or 'preserve'", code="definition-modifier-invalid")
    if parser._pending_inline_definition:
        raise ParseError("duplicate 'inline' before definition", code="definition-modifier-invalid")
    parser._pending_inline_definition = True
    return None


def macro_preserve(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    next_tok = parser.peek_token()
    if not parser._pending_inline_definition:
        raise ParseError("'preserve' must follow 'inline'", code="definition-modifier-invalid")
    if parser._pending_preserve_definition:
        raise ParseError("duplicate 'preserve' before definition", code="definition-modifier-invalid")
    if next_tok is None or next_tok.lexeme not in ("word", ":asm"):
        raise ParseError("'preserve' must be followed by 'word' or ':asm'", code="definition-modifier-invalid")
    parser._pending_preserve_definition = True
    return None


def _ensure_parser_event_bus(parser: "Parser") -> EventBus:
    """The parser's event bus, created on first use.  It is enabled by
    default; --no-events creates it hard-disabled."""
    if parser.event_bus is None:
        parser.event_bus = EventBus(getattr(parser, "event_ring_capacity", DEFAULT_EVENT_RING_CAPACITY))
        compiler_ref = getattr(parser, "_compiler_ref", None)
        if compiler_ref is not None:
            compiler_ref.event_bus = parser.event_bus
            compiler_ref.assembler.event_bus = parser.event_bus
    bus = parser.event_bus
    bus.ct_runner = parser._run_ct_event_handlers
    bus.sink_error_handler = parser._handle_event_stream_failure
    if parser.events_hard_disabled:
        bus.hard_disabled = True
    return bus


def _event_handler_context(record: Dict[str, Any], sub: EventSubscriptionHandle, index: int) -> Dict[str, Any]:
    return {"event": record["event"], "subscription": sub, "dispatch-index": index, "handler": sub.handler}


def _event_handler_failure(parser: "Parser", record: Dict[str, Any], sub: EventSubscriptionHandle,
                           index: int, reason: str) -> ParseError:
    """A CT handler failure without its own Diagnostic: a recoverable
    event-handler-failed (recovery_error, phase event-dispatch)."""
    notes = [f"event '{record['event']}', subscription {sub.id}, dispatch index {index}, "
             f"handler '{sub.handler}'"]
    payload = record.get("payload")
    related: List[Tuple[str, Optional[str], SourceOrigin]] = []
    if isinstance(payload, dict) and isinstance(payload.get("source-origin"), SourceOrigin):
        related.append(("event-source", "event published here", payload["source-origin"]))
    return ParseError(f"event handler '{sub.handler}' failed: {reason}", code="event-handler-failed",
                      phase="event-dispatch", origin=parser._token_origin(parser._last_token),
                      notes=notes, related=related)


def _parser_run_ct_event_handlers(self: "Parser", record: Dict[str, Any],
                                  subscriptions: List[EventSubscriptionHandle]) -> None:
    """Run a dispatch snapshot of CT subscriptions in registration order.
    Handler words are resolved and pinned before the first one runs; each
    gets its own detached copy of the event and an isolated data stack.
    Subscriptions excluded by the active failure lineage, and owned ones
    whose candidate is gone or ineligible, are skipped.  A failure is
    dispatched as a nested recoverable error with the failing subscription
    excluded; when resumed the dispatch continues with the next handler."""
    dictionary = self.dictionary
    excluded = self._excluded_subscriptions
    running = self._running_subscriptions
    execution_event = record["event"].startswith("ct.execute.")
    pinned = []
    for sub in subscriptions:
        if sub.id in excluded or (execution_event and sub.id in running):
            continue
        if sub.owner is not None:
            owner = dictionary.resolve(sub.owner)
            if owner is None or not dictionary.eligible(owner):
                continue
        pinned.append((sub, dictionary.lookup(sub.handler)))
    vm = self.compile_time_vm
    for index, (sub, word) in enumerate(pinned, 1):
        try:
            if word is None:
                raise _event_handler_failure(self, record, sub, index, f"word '{sub.handler}' is not defined")
            if word.runtime_only or word.immediate or word.macro_def is not None:
                kind = "runtime-only" if word.runtime_only else "a macro" if word.macro_def is not None else "immediate"
                raise _event_handler_failure(self, record, sub, index, f"word '{sub.handler}' is {kind}")
            if vm.runtime_mode:
                raise _event_handler_failure(self, record, sub, index, "CT handlers cannot run in runtime VM mode")
            saved = vm.stack[:]
            vm.stack[:] = [_detach_value(record)]
            nested = sub.id in running
            running.add(sub.id)
            try:
                vm._call_word(word)
                leftover = len(vm.stack)
            finally:
                if not nested:
                    running.discard(sub.id)
                vm.stack[:] = saved
            if leftover:
                raise _event_handler_failure(self, record, sub, index,
                                             f"stack effect must be 'event --', left {leftover} value(s)")
        except ParseError as exc:
            # A handler's own Diagnostic is kept; the event context goes in
            # the error event's payload rather than a second wrapper error.
            if getattr(exc, "l2_event_context", None) is None:
                exc.l2_event_context = _event_handler_context(record, sub, index)  # type: ignore[attr-defined]
            previous = self._excluded_subscriptions
            self._excluded_subscriptions = previous | {sub.id}
            try:
                resumed = self._dispatch_continuation_error(exc, "event-dispatch")
            finally:
                self._excluded_subscriptions = previous
            if not resumed:
                raise


def _ct_events_bus(vm: CompileTimeVM, word: str) -> EventBus:
    """The event bus for a CT publication or subscription; raises while
    events are disabled."""
    bus = _ensure_parser_event_bus(vm.parser)
    if bus.hard_disabled:
        raise ParseError(f"{word}: events are disabled for this compilation (--no-events)",
                         code="event-bus-disabled")
    if not bus.enabled:
        raise ParseError(f"{word}: events are disabled (ct-event-set-enabled)", code="event-bus-disabled")
    return bus


def _ct_pop_event_name(vm: CompileTimeVM, word: str) -> str:
    name = vm._resolve_handle(vm.pop())
    if not isinstance(name, str) or name == "":
        raise ParseError(f"{word}: event name must be a non-empty string, got {_ct_type_name(name)}",
                         code="ct-argument-invalid")
    return name


def _ct_pop_event(vm: CompileTimeVM, word: str) -> Dict[str, Any]:
    """A canonical event draft or published event view."""
    event = vm._resolve_handle(vm.pop())
    if not isinstance(event, dict) or not isinstance(event.get("event"), str) or not isinstance(event.get("payload"), dict):
        raise ParseError(f"{word} expects an event map with 'event' and 'payload', got {_ct_type_name(event)}",
                         code="ct-argument-type")
    return event


def _ct_event_subscribe(vm: CompileTimeVM) -> None:
    owner = vm._resolve_handle(vm.pop())
    handler = vm._resolve_handle(vm.pop())
    pattern = vm._resolve_handle(vm.pop())
    if not isinstance(pattern, str) or pattern == "":
        raise ParseError("ct-event-subscribe: pattern must be a non-empty string", code="ct-argument-invalid")
    if not isinstance(handler, str) or handler == "":
        raise ParseError("ct-event-subscribe: handler must be a non-empty word name", code="ct-argument-invalid")
    candidate = None
    if owner is not None:
        if not isinstance(owner, DefinitionHandle):
            raise ParseError(f"ct-event-subscribe: owner must be nil or a DefinitionHandle, got {_ct_type_name(owner)}",
                             code="ct-argument-type")
        candidate = vm.dictionary.resolve(owner)
        if candidate is None:
            raise ParseError("ct-event-subscribe: the owner definition candidate is stale",
                             code="definition-argument-invalid", phase="event-subscription")
    handle = _ct_events_bus(vm, "ct-event-subscribe").ct_subscribe(pattern, handler, owner)
    if candidate is not None:
        vm.dictionary.update(candidate, lambda word: None)  # attaching an owned subscription is an update
    vm.push(handle)


def _ct_event_unsubscribe(vm: CompileTimeVM) -> None:
    handle = vm._resolve_handle(vm.pop())
    if not isinstance(handle, EventSubscriptionHandle):
        raise ParseError(f"ct-event-unsubscribe expects an EventSubscriptionHandle, got {_ct_type_name(handle)}",
                         code="ct-argument-type")
    bus = vm.parser.event_bus
    removed = bus is not None and bus.ct_unsubscribe(handle)
    if removed and handle.owner is not None:
        candidate = vm.dictionary.resolve(handle.owner)
        if candidate is not None:
            vm.dictionary.update(candidate, lambda word: None)
    vm.push(1 if removed else 0)


def _ct_event_emit(vm: CompileTimeVM) -> None:
    payload = vm._resolve_handle(vm.pop())
    name = _ct_pop_event_name(vm, "ct-event-emit")
    if payload is None:
        payload = {}
    if not isinstance(payload, dict):
        raise ParseError(f"ct-event-emit: payload must be a map or nil, got {_ct_type_name(payload)}",
                         code="ct-argument-type")
    _ct_events_bus(vm, "ct-event-emit").publish(name, payload)
    vm.push(1)


def _ct_event_emit_object(vm: CompileTimeVM) -> None:
    event = _ct_pop_event(vm, "ct-event-emit-object")
    extra = [key for key in event if key not in _EVENT_RECORD_KEYS]
    if extra:
        raise ParseError(f"ct-event-emit-object: unexpected key {extra[0]!r}; events have only event, "
                         "timestamp_ns, and payload", code="ct-argument-invalid")
    if event["event"] == "":
        raise ParseError("ct-event-emit-object: event name must not be empty", code="ct-argument-invalid")
    if "timestamp_ns" in event:
        stamp = event["timestamp_ns"]
        if isinstance(stamp, bool) or not isinstance(stamp, int):
            raise ParseError("ct-event-emit-object: timestamp_ns must be an integer", code="ct-argument-type")
    _ct_events_bus(vm, "ct-event-emit-object").publish(event["event"], event["payload"])
    vm.push(1)


def _ct_event_new(vm: CompileTimeVM) -> None:
    vm.push({"event": _ct_pop_event_name(vm, "event-new"), "payload": {}})


def _ct_event_payload_set(vm: CompileTimeVM) -> None:
    value = vm._resolve_handle(vm.pop())
    key = vm._resolve_handle(vm.pop())
    event = _ct_pop_event(vm, "event-payload-set")
    _ct_check_map_key(key, "event-payload-set")
    event["payload"][key] = value
    vm.push(event)


def _ct_event_payload_get(vm: CompileTimeVM) -> None:
    key = vm._resolve_handle(vm.pop())
    event = _ct_pop_event(vm, "event-payload-get")
    _ct_check_map_key(key, "event-payload-get")
    payload = event["payload"]
    if key in payload:
        vm.push(payload[key])
        vm.push(1)
    else:
        vm.push(None)
        vm.push(0)


def _ct_event_name(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_event(vm, "event-name")["event"])


def _ct_event_timestamp(vm: CompileTimeVM) -> None:
    event = _ct_pop_event(vm, "event-timestamp")
    if "timestamp_ns" in event:
        vm.push(event["timestamp_ns"])
        vm.push(1)
    else:
        vm.push(None)
        vm.push(0)


def _ct_event_payload(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_event(vm, "event-payload")["payload"])


def _ct_event_enabled(vm: CompileTimeVM) -> None:
    parser = vm.parser
    bus = parser.event_bus
    if parser.events_hard_disabled:
        vm.push(0)
    else:
        vm.push(1 if bus is None or bus.enabled else 0)


def _ct_event_set_enabled(vm: CompileTimeVM) -> None:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, (bool, int)):
        raise ParseError(f"ct-event-set-enabled expects an integer or boolean, got {_ct_type_name(value)}",
                         code="ct-argument-type")
    enable = bool(value)
    parser = vm.parser
    if parser.events_hard_disabled:
        if enable:
            raise ParseError("ct-event-set-enabled: events are disabled for this compilation (--no-events)",
                             code="event-bus-disabled")
        vm.push(0)
        return
    bus = _ensure_parser_event_bus(parser)
    previous = 1 if bus.enabled else 0
    bus.enabled = enable
    vm.push(previous)


def _ct_event_stream_enabled(vm: CompileTimeVM) -> None:
    """-- enabled : whether a configured JSONL sink is currently writing."""
    parser = vm.parser
    bus = parser.event_bus
    vm.push(1 if bus is not None and not parser.events_hard_disabled and bus.has_sink and bus.stream_enabled else 0)


def _ct_event_stream_set_enabled(vm: CompileTimeVM) -> None:
    """enabled -- previous-enabled : toggles future writes to an already
    configured JSONL sink; cannot create a sink or override --no-events."""
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, int):
        raise ParseError(f"ct-event-stream-set-enabled expects an integer or boolean, got {_ct_type_name(value)}",
                         code="ct-argument-type")
    parser = vm.parser
    bus = parser.event_bus
    configured = bus is not None and bus.has_sink and not parser.events_hard_disabled
    if not configured:
        if value:
            raise ParseError("ct-event-stream-set-enabled: no event stream is configured "
                             "(use --events-stream PATH; not with --no-events or --no-events-json)",
                             code="event-bus-disabled")
        vm.push(0)
        return
    previous = 1 if bus.stream_enabled else 0
    bus.stream_enabled = bool(value)
    vm.push(previous)


Parser._run_ct_event_handlers = _parser_run_ct_event_handlers  # type: ignore[attr-defined]


def _json_origin(origin: SourceOrigin, active: Set[int]) -> Dict[str, Any]:
    return {"kind": "SourceOrigin", "path": origin.path, "start": origin.start, "end": origin.end,
            "start_line": origin.start_line, "start_column": origin.start_column,
            "end_line": origin.end_line, "end_column": origin.end_column}


def _json_frame(frame: ExpansionFrame, active: Set[int]) -> Dict[str, Any]:
    # The frame's own `kind` field is `frame_kind`, since `kind` tags the type.
    definition = frame.definition_origin
    return {"kind": "ExpansionFrame", "frame_kind": frame.kind, "name": frame.name,
            "call_site": _json_origin(frame.call_site, active),
            "definition_origin": _json_origin(definition, active) if definition is not None else None}


def _json_token(token: Token, active: Set[int]) -> Dict[str, Any]:
    return {"kind": "Token", "lexeme": token.lexeme, "origin": _json_origin(token.origin, active),
            "expansion_chain": [_json_frame(frame, active) for frame in token.expansion_chain]}


def _json_diagnostic(diag: Diagnostic, active: Set[int]) -> Dict[str, Any]:
    related = []
    for kind, message, origin in diag.related:
        record: Dict[str, Any] = {"kind": kind}
        if message is not None:
            record["message"] = message
        record["origin"] = _json_origin(origin, active)
        related.append(record)
    return {"kind": "Diagnostic", "severity": diag.severity, "code": diag.code, "category": diag.category,
            "phase": diag.phase, "message": diag.message,
            "primary": _json_origin(diag.primary, active) if diag.primary is not None else None,
            "related": related}


_EVENT_JSON_PROJECTIONS.update({
    SourceOrigin: _json_origin,
    ExpansionFrame: _json_frame,
    Token: _json_token,
    Diagnostic: _json_diagnostic,
    EventSubscriptionHandle: lambda handle, active: {"kind": "EventSubscriptionHandle", "id": handle.id},
    DefinitionHandle: lambda handle, active: {"kind": "DefinitionHandle", "id": handle.id},
    RewriteHandle: lambda handle, active: {"kind": "RewriteHandle", "id": handle.id},
    TokenHookHandle: lambda handle, active: {"kind": "TokenHookHandle", "id": handle.id},
    Syntax: lambda value, active: {"kind": "Syntax", "tokens": [_json_token(token, active) for token in value.tokens]},
    ParserCheckpoint: lambda value, active: {"kind": "ParserCheckpoint", "pos": value.pos},
    ParserSession: lambda value, active: {"kind": "ParserSession", "pos": value.pos, "open": value.open},
    SourceCursor: lambda value, active: {"kind": "SourceCursor", "path": value.path, "pos": value.pos},
})


def _jsonl_event_sink(stream: Any) -> Callable[[Dict[str, Any]], None]:
    """--events-stream writer.  A value without a projection or a write
    failure raises a recoverable event-stream-output-failed error."""
    def write(record: Dict[str, Any]) -> None:
        try:
            line = _event_json_record(record)
            stream.write(line + "\n")
            stream.flush()
        except (ValueError, OSError) as exc:
            raise ParseError(f"cannot write event '{record.get('event')}' to the event stream: {exc}",
                             code="event-stream-output-failed") from None
    return write


def macro_on_event(ctx: MacroContext) -> Optional[List[Op]]:
    """Subscribe the preceding word as a global CT event handler."""
    parser = ctx.parser
    pattern_token = parser.next_token()
    if pattern_token.lexeme in ("{", "where"):
        raise ParseError("on-event requires an event pattern after the word definition", code="parser-directive-invalid")
    word = parser.most_recent_definition()
    if word is None:
        raise ParseError("suffix 'on-event' requires a preceding word definition", code="parser-directive-invalid")
    if word.runtime_only or word.immediate:
        raise ParseError(f"event listener '{word.name}' must be compile-only", code="definition-modifier-invalid")
    word.compile_only = True
    if word.definition is not None:
        word.definition.compile_only = True
    pattern = pattern_token.lexeme
    if len(pattern) >= 2 and pattern[0] == '"' and pattern[-1] == '"':
        pattern = _parse_string_literal(pattern_token) or ""
    if pattern == "":
        raise ParseError("on-event requires a non-empty event pattern", code="parser-directive-invalid")
    bus = _ensure_parser_event_bus(parser)
    if bus.hard_disabled:
        raise ParseError("on-event: events are disabled for this compilation (--no-events)",
                         code="event-bus-disabled")
    bus.ct_subscribe(pattern, word.name)
    return None


def macro_emit_event(ctx: MacroContext) -> Optional[List[Op]]:
    """Publish an event from L2 source: ``emit-event name``.  The payload
    holds the directive's SourceOrigin at key ``source-origin``."""
    parser = ctx.parser
    token = parser.next_token()
    name = token.lexeme
    if len(name) >= 2 and name[0] == '"' and name[-1] == '"':
        name = _parse_string_literal(token) or ""
    if name == "":
        raise ParseError("emit-event requires a non-empty event name", code="parser-directive-invalid")
    bus = _ensure_parser_event_bus(parser)
    if not bus.active:
        raise ParseError("emit-event: events are disabled", code="event-bus-disabled")
    bus.publish(name, {"source-origin": token.origin})
    return None


def _require_definition_context(parser: "Parser", word_name: str) -> Definition:
    if not parser.context_stack or not isinstance(parser.context_stack[-1], Definition):
        raise ParseError(f"'{word_name}' can only appear inside a definition", code="parser-directive-invalid")
    return parser.context_stack[-1]


def macro_label(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    if parser._eof():
        raise ParseError("label name missing after 'label'", code="parser-label-invalid")
    tok = parser.next_token()
    name = tok.lexeme
    if not _is_identifier(name):
        raise ParseError(f"invalid label name '{name}'", code="parser-label-invalid")
    definition = _require_definition_context(parser, "label")
    if any(node._opcode == OP_LABEL and node.data == name for node in definition.body):
        raise ParseError(f"duplicate label '{name}' in definition '{definition.name}'", code="parser-label-invalid")
    parser.emit_node(_make_op("label", name))
    return None


def macro_goto(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser
    if parser._eof():
        raise ParseError("label name missing after 'goto'", code="parser-label-invalid")
    tok = parser.next_token()
    name = tok.lexeme
    if not _is_identifier(name):
        raise ParseError(f"invalid label name '{name}'", code="parser-label-invalid")
    _require_definition_context(parser, "goto")
    parser.emit_node(_make_op("jump", name))
    return None


def macro_compile_time(ctx: MacroContext) -> Optional[List[Op]]:
    """Run the next word at compile time and still emit it for runtime."""
    parser = ctx.parser
    if parser._eof():
        raise ParseError("word name missing after 'compile-time'", code="parser-directive-invalid")
    tok = parser.next_token()
    name = tok.lexeme
    word = parser.dictionary.lookup(name)
    if word is None:
        raise ParseError(f"unknown word '{name}' for compile-time", code="ct-word-unavailable")
    if word.runtime_only:
        raise ParseError(f"word '{name}' is runtime-only", code="ct-runtime-only-target")
    if word.compile_only:
        raise ParseError(f"word '{name}' is compile-time only", code="ct-word-unavailable")

    stack_before: List[str] = []
    stack_after: List[str] = []
    emitted_ops: List[Op] = []
    target_ops: Optional[List[Any]] = None
    target_len_before = 0
    if parser.preview_trace_enabled:
        stack_before = parser._preview_stack_snapshot()
        target = parser.context_stack[-1] if parser.context_stack else None
        if isinstance(target, Definition):
            target_ops = target.body
            target_len_before = len(target_ops)
        elif isinstance(target, Module):
            target_ops = target.forms
            target_len_before = len(target_ops)

    parser.compile_time_vm.invoke(word)
    parser.compile_time_vm._ct_executed.add(name)
    if isinstance(parser.context_stack[-1], Definition):
        parser.emit_node(_make_op("word", name))

    if parser.preview_trace_enabled:
        stack_after = parser._preview_stack_snapshot()
        if target_ops is not None and len(target_ops) > target_len_before:
            emitted_ops = [node for node in target_ops[target_len_before:] if isinstance(node, Op)]
        parser._record_preview_execution_event(
            kind="compile-time",
            word_name=name,
            token=tok,
            consumed_tokens=[name],
            stack_before=stack_before,
            stack_after=stack_after,
            emitted_ops=emitted_ops,
        )
    return None


def macro_with(ctx: MacroContext) -> Optional[List[Op]]:
    parser = ctx.parser

    names: List[str] = []
    template: Optional[Token] = None
    seen: set[str] = set()
    while True:
        if parser._eof():
            raise ParseError("missing 'in' after 'with'", code="parser-with-invalid")
        tok = parser.next_token()
        template = template or tok
        if tok.lexeme == "in":
            break
        if not _is_identifier(tok.lexeme):
            raise ParseError("invalid variable name in 'with'", code="parser-with-invalid")
        if tok.lexeme in seen:
            raise ParseError("duplicate variable name in 'with'", code="parser-with-invalid")
        seen.add(tok.lexeme)
        names.append(tok.lexeme)
    if not names:
        raise ParseError("'with' requires at least one variable name", code="parser-with-invalid")

    body: List[Token] = []
    else_line: Optional[int] = None
    depth = 0
    while True:
        if parser._eof():
            raise ParseError("unterminated 'with' block (missing 'end')", code="parser-with-invalid")
        tok = parser.next_token()
        if else_line is not None and tok.line != else_line:
            else_line = None
        if tok.lexeme == "end":
            if depth == 0:
                break
            depth -= 1
            body.append(tok)
            continue
        if tok.lexeme == "if":
            # Support shorthand elif form `else <cond> if` inside with-blocks.
            # This inline `if` shares the same closing `end` as the preceding
            # branch and therefore must not increment nesting depth.
            if else_line != tok.line:
                depth += 1
        elif tok.lexeme == "else":
            else_line = tok.line
        elif tok.lexeme == "again":
            depth -= 1  # closes a `begin`, which counted as an opener
        elif tok.lexeme in parser.block_openers:
            depth += 1
        body.append(tok)

    helper_for: Dict[str, str] = {}
    for name in names:
        _, helper = parser.allocate_variable(name)
        helper_for[name] = helper

    emitted_tokens: List[Token] = []

    def _emit_lex(lex: str, src_tok: Optional[Token] = None) -> None:
        emitted_tokens.append(_derive_token(src_tok or template, lex))

    # Initialize variables by storing current stack values into their buffers
    for name in reversed(names):
        helper = helper_for[name]
        _emit_lex(helper, template)
        _emit_lex("swap", template)
        _emit_lex("!", template)

    i = 0
    while i < len(body):
        tok = body[i]
        name = tok.lexeme
        helper = helper_for.get(name)
        if helper is not None:
            next_tok = body[i + 1] if i + 1 < len(body) else None
            if next_tok is not None and next_tok.lexeme == "!":
                _emit_lex(helper, tok)
                _emit_lex("swap", tok)
                _emit_lex("!", tok)
                i += 2
                continue
            if next_tok is not None and next_tok.lexeme == "@":
                _emit_lex(helper, tok)
                i += 1
                continue
            _emit_lex(helper, tok)
            _emit_lex("@", tok)
            i += 1
            continue
        _emit_lex(tok.lexeme, tok)
        i += 1

    ctx.inject_token_objects(emitted_tokens)
    return None


def macro_begin_definition(ctx: MacroContext) -> Optional[List[Op]]:
    ctx.parser._begin_macro_definition(ctx.parser._last_token)
    return None



def _struct_emit_definition(tokens: List[Token], template: Token, name: str, body: Sequence[str]) -> None:
    def make_token(lexeme: str) -> Token:
        return _derive_token(template, lexeme)

    tokens.append(make_token("word"))
    tokens.append(make_token(name))
    for lexeme in body:
        tokens.append(make_token(lexeme))
    tokens.append(make_token("end"))








# ---------------------------------------------------------------------------
# CT data and value utilities (nil, lists, maps, strings).
# Reads consume their subject; mutations return the subject first, then any
# results.  Invalid types, indexes and map keys raise a CT error before any
# mutation.  Character classification uses fixed sets, never the host
# Python's Unicode database.
# ---------------------------------------------------------------------------

_L2_ASCII_UPPER = str.maketrans("abcdefghijklmnopqrstuvwxyz", "ABCDEFGHIJKLMNOPQRSTUVWXYZ")
_L2_ASCII_LOWER = str.maketrans("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")


def _l2_strip(text: str) -> str:
    return text.strip(_L2_WHITESPACE)


def _is_l2_identifier(text: str) -> bool:
    """L2 identifier rule: first code point is an ASCII letter, `_`, or any
    code point >= U+0080; later code points may also be ASCII digits."""
    if not text:
        return False
    for index, ch in enumerate(text):
        if ch == "_" or ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ord(ch) >= 0x80:
            continue
        if index > 0 and "0" <= ch <= "9":
            continue
        return False
    return True


def _parse_l2_int(text: str) -> Optional[int]:
    """Parse a signed integer for `try-string>int`; return None on failure."""
    body = _l2_strip(text)
    if not body:
        return None
    sign = 1
    if body[0] in "+-":
        if body[0] == "-":
            sign = -1
        body = body[1:]
    base = 10
    if len(body) >= 2 and body[0] == "0" and body[1] in "xXbBoO":
        base = {"x": 16, "b": 2, "o": 8}[body[1].lower()]
        body = body[2:]
    if not body:
        return None
    digits = "0123456789abcdef"[:base]
    value = 0
    previous_underscore = True  # rejects leading and prefix-adjacent underscores
    for ch in body:
        if ch == "_":
            if previous_underscore:
                return None
            previous_underscore = True
            continue
        digit = digits.find(ch.lower()) if ch.isascii() else -1
        if digit < 0:
            return None
        value = value * base + digit
        previous_underscore = False
    if previous_underscore:
        return None
    return sign * value


def _ct_type_name(value: Any) -> str:
    if value is None:
        return "nil"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "list"
    if isinstance(value, Mapping):
        return "map"
    if isinstance(value, Token):
        return "token"
    if isinstance(value, SourceOrigin):
        return "SourceOrigin"
    if isinstance(value, ExpansionFrame):
        return "ExpansionFrame"
    if isinstance(value, SourceCursor):
        return "SourceCursor"
    if isinstance(value, Diagnostic):
        return "Diagnostic"
    if isinstance(value, EventSubscriptionHandle):
        return "EventSubscriptionHandle"
    if isinstance(value, DefinitionHandle):
        return "DefinitionHandle"
    if isinstance(value, RewriteHandle):
        return "RewriteHandle"
    if isinstance(value, TokenHookHandle):
        return "TokenHookHandle"
    if isinstance(value, Syntax):
        return "Syntax"
    return type(value).__name__


def _ct_pop_list(vm: CompileTimeVM, word: str) -> List[Any]:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, list):
        raise ParseError(f"{word} expects a list, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_map(vm: CompileTimeVM, word: str) -> Mapping:
    """Pop a map for reading; immutable compiler-provided maps are accepted."""
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, Mapping):
        raise ParseError(f"{word} expects a map, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_mutable_map(vm: CompileTimeVM, word: str) -> Dict[Any, Any]:
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, dict):
        return value
    if isinstance(value, Mapping):
        raise ParseError(f"{word} cannot modify an immutable compiler-provided map", code="ct-map-immutable")
    raise ParseError(f"{word} expects a map, got {_ct_type_name(value)}", code="ct-argument-type")


def _ct_pop_index(vm: CompileTimeVM, word: str) -> int:
    value = vm.pop()
    if isinstance(value, bool) or not isinstance(value, int):
        raise ParseError(f"{word} expects an integer index, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_string(vm: CompileTimeVM, word: str) -> str:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, str):
        raise ParseError(f"{word} expects a string, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_check_map_key(key: Any, word: str) -> None:
    # bool is a subclass of int, so booleans are accepted here.
    if key is None or isinstance(key, (str, int)):
        return
    raise ParseError(
        f"{word}: unsupported map key type {_ct_type_name(key)}; "
        "keys must be strings, integers, booleans, or nil",
        code="ct-map-key-invalid",
    )


def _ct_checked_index(lst: List[Any], index: int, word: str) -> int:
    length = len(lst)
    if index < -length or index >= length:
        raise ParseError(f"{word}: index {index} out of range for list of length {length}", code="ct-index-out-of-range")
    return index


def _ct_is_scalar(value: Any) -> bool:
    return value is None or isinstance(value, (bool, int, float, str))


def _ct_values_equal(left: Any, right: Any) -> bool:
    """Structural, cycle-safe CT equality used by list-find/list-contains?."""
    return _ct_equal(left, right, set())


def _ct_values_identical(left: Any, right: Any) -> bool:
    """Like _ct_values_equal, but Tokens (also inside Syntax) must also have
    the same provenance: a stored value is replaced by an equal-looking Token
    from elsewhere (macro metadata, the ct_store library)."""
    return _ct_equal(left, right, set(), strict=True)


def _tokens_identical(left: "Token", right: "Token") -> bool:
    if left is right:
        return True
    a, b = left.origin, right.origin
    return (left.lexeme == right.lexeme and (a.path, a.start, a.end) == (b.path, b.start, b.end)
            and len(left.expansion_chain) == len(right.expansion_chain))


def _ct_equal(left: Any, right: Any, seen: Set[Tuple[int, int]], strict: bool = False) -> bool:
    if isinstance(left, Syntax) or isinstance(right, Syntax):
        # Syntax values compare by their Token lexemes, ignoring provenance.
        if not (isinstance(left, Syntax) and isinstance(right, Syntax)):
            return False
        if strict:
            return len(left.tokens) == len(right.tokens) and all(
                _tokens_identical(a, b) for a, b in zip(left.tokens, right.tokens))
        return left.lexemes() == right.lexemes()
    if isinstance(left, Token) or isinstance(right, Token):
        if not (isinstance(left, Token) and isinstance(right, Token)):
            return False
        return _tokens_identical(left, right) if strict else left.lexeme == right.lexeme
    if isinstance(left, list) or isinstance(right, list):
        if not (isinstance(left, list) and isinstance(right, list)):
            return False
        pair = (id(left), id(right))
        if pair in seen:
            return True
        seen.add(pair)
        if len(left) != len(right):
            return False
        return all(_ct_equal(a, b, seen, strict) for a, b in zip(left, right))
    if isinstance(left, Mapping) or isinstance(right, Mapping):
        if not (isinstance(left, Mapping) and isinstance(right, Mapping)):
            return False
        pair = (id(left), id(right))
        if pair in seen:
            return True
        seen.add(pair)
        if len(left) != len(right):
            return False
        for key, value in left.items():
            if key not in right:
                return False
            if not _ct_equal(value, right[key], seen, strict):
                return False
        return True
    if _ct_is_scalar(left) and _ct_is_scalar(right):
        return left == right
    return left is right


def _ct_deep_clone_value(value: Any, memo: Dict[int, Any]) -> Any:
    if isinstance(value, list):
        existing = memo.get(id(value))
        if existing is not None:
            return existing
        copy_list: List[Any] = []
        memo[id(value)] = copy_list
        for item in value:
            copy_list.append(_ct_deep_clone_value(item, memo))
        return copy_list
    if isinstance(value, Mapping):
        existing = memo.get(id(value))
        if existing is not None:
            return existing
        copy_map: Dict[Any, Any] = {}
        memo[id(value)] = copy_map
        for key, item in value.items():
            copy_map[key] = _ct_deep_clone_value(item, memo)
        return copy_map
    return value


# -- nil and scalars ---------------------------------------------------------

def _ct_nil(vm: CompileTimeVM) -> None:
    vm.push(None)


def _ct_nil_p(vm: CompileTimeVM) -> None:
    vm.push(1 if vm.pop() is None else 0)


def _ct_identifier_p(vm: CompileTimeVM) -> None:
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, Token):
        value = value.lexeme
    if not isinstance(value, str):
        vm.push(0)
        return
    vm.push(1 if _is_l2_identifier(value) else 0)


def _ct_int_to_string(vm: CompileTimeVM) -> None:
    value = vm.pop()
    if isinstance(value, bool):
        vm.push("1" if value else "0")
        return
    if not isinstance(value, int):
        raise ParseError(f"int>string expects an integer, got {_ct_type_name(value)}", code="ct-argument-type")
    vm.push(str(value))


# -- lists -------------------------------------------------------------------

def _ct_list_new(vm: CompileTimeVM) -> None:
    vm.push([])


def _ct_list_clone(vm: CompileTimeVM) -> None:
    vm.push(list(_ct_pop_list(vm, "list-clone")))


def _ct_list_deep_clone(vm: CompileTimeVM) -> None:
    vm.push(_ct_deep_clone_value(_ct_pop_list(vm, "list-deep-clone"), {}))


def _ct_list_get(vm: CompileTimeVM) -> None:
    index = _ct_pop_index(vm, "list-get")
    lst = _ct_pop_list(vm, "list-get")
    vm.push(lst[_ct_checked_index(lst, index, "list-get")])


def _ct_list_last(vm: CompileTimeVM) -> None:
    lst = _ct_pop_list(vm, "list-last")
    if not lst:
        raise ParseError("list-last: list is empty", code="ct-collection-empty")
    vm.push(lst[-1])


def _ct_list_peek_front(vm: CompileTimeVM) -> None:
    lst = _ct_pop_list(vm, "list-peek-front")
    if not lst:
        raise ParseError("list-peek-front: list is empty", code="ct-collection-empty")
    vm.push(lst[0])


def _ct_list_find(vm: CompileTimeVM) -> None:
    needle = vm.pop()
    lst = _ct_pop_list(vm, "list-find")
    for index, item in enumerate(lst):
        if _ct_values_equal(item, needle):
            vm.push(index)
            vm.push(1)
            return
    vm.push(-1)
    vm.push(0)


def _ct_list_contains(vm: CompileTimeVM) -> None:
    needle = vm.pop()
    lst = _ct_pop_list(vm, "list-contains?")
    vm.push(1 if any(_ct_values_equal(item, needle) for item in lst) else 0)


def _ct_list_length(vm: CompileTimeVM) -> None:
    vm.push(len(_ct_pop_list(vm, "list-length")))


def _ct_list_empty(vm: CompileTimeVM) -> None:
    vm.push(1 if not _ct_pop_list(vm, "list-empty?") else 0)


def _ct_list_slice(vm: CompileTimeVM) -> None:
    end = _ct_pop_index(vm, "list-slice")
    start = _ct_pop_index(vm, "list-slice")
    lst = _ct_pop_list(vm, "list-slice")
    vm.push(lst[start:end])


def _ct_list_append(vm: CompileTimeVM) -> None:
    value = vm.pop()
    lst = _ct_pop_list(vm, "list-append")
    lst.append(value)
    vm.push(lst)


def _ct_list_push_front(vm: CompileTimeVM) -> None:
    value = vm.pop()
    lst = _ct_pop_list(vm, "list-push-front")
    lst.insert(0, value)
    vm.push(lst)


def _ct_list_extend(vm: CompileTimeVM) -> None:
    source = _ct_pop_list(vm, "list-extend")
    target = _ct_pop_list(vm, "list-extend")
    target.extend(list(source))  # self-extension appends one snapshot
    vm.push(target)


def _ct_list_insert(vm: CompileTimeVM) -> None:
    value = vm.pop()
    index = _ct_pop_index(vm, "list-insert")
    lst = _ct_pop_list(vm, "list-insert")
    length = len(lst)
    if index < -length or index > length:
        raise ParseError(f"list-insert: index {index} out of range for list of length {length}", code="ct-index-out-of-range")
    if index < 0:
        index += length
    lst.insert(index, value)
    vm.push(lst)


def _ct_list_set(vm: CompileTimeVM) -> None:
    value = vm.pop()
    index = _ct_pop_index(vm, "list-set")
    lst = _ct_pop_list(vm, "list-set")
    lst[_ct_checked_index(lst, index, "list-set")] = value
    vm.push(lst)


def _ct_list_reverse(vm: CompileTimeVM) -> None:
    lst = _ct_pop_list(vm, "list-reverse")
    lst.reverse()
    vm.push(lst)


def _ct_list_clear(vm: CompileTimeVM) -> None:
    lst = _ct_pop_list(vm, "list-clear")
    lst.clear()
    vm.push(lst)


def _ct_list_pop(vm: CompileTimeVM) -> None:
    lst = _ct_pop_list(vm, "list-pop")
    vm.push(lst)
    if lst:
        vm.push(lst.pop())
        vm.push(1)
    else:
        vm.push(None)
        vm.push(0)


def _ct_list_pop_front(vm: CompileTimeVM) -> None:
    lst = _ct_pop_list(vm, "list-pop-front")
    vm.push(lst)
    if lst:
        vm.push(lst.pop(0))
        vm.push(1)
    else:
        vm.push(None)
        vm.push(0)


def _ct_list_remove(vm: CompileTimeVM) -> None:
    index = _ct_pop_index(vm, "list-remove")
    lst = _ct_pop_list(vm, "list-remove")
    value = lst.pop(_ct_checked_index(lst, index, "list-remove"))
    vm.push(lst)
    vm.push(value)


# -- maps --------------------------------------------------------------------

def _ct_map_new(vm: CompileTimeVM) -> None:
    vm.push({})


def _ct_map_clone(vm: CompileTimeVM) -> None:
    vm.push(dict(_ct_pop_map(vm, "map-clone")))


def _ct_map_get(vm: CompileTimeVM) -> None:
    key = vm.pop()
    map_obj = _ct_pop_map(vm, "map-get")
    _ct_check_map_key(key, "map-get")
    if key in map_obj:
        vm.push(map_obj[key])
        vm.push(1)
    else:
        vm.push(None)
        vm.push(0)


def _ct_map_has(vm: CompileTimeVM) -> None:
    key = vm.pop()
    map_obj = _ct_pop_map(vm, "map-has?")
    _ct_check_map_key(key, "map-has?")
    vm.push(1 if key in map_obj else 0)


def _ct_map_keys(vm: CompileTimeVM) -> None:
    vm.push(list(_ct_pop_map(vm, "map-keys").keys()))


def _ct_map_values(vm: CompileTimeVM) -> None:
    vm.push(list(_ct_pop_map(vm, "map-values").values()))


def _ct_map_length(vm: CompileTimeVM) -> None:
    vm.push(len(_ct_pop_map(vm, "map-length")))


def _ct_map_empty(vm: CompileTimeVM) -> None:
    vm.push(1 if not _ct_pop_map(vm, "map-empty?") else 0)


def _ct_map_set(vm: CompileTimeVM) -> None:
    value = vm.pop()
    key = vm.pop()
    map_obj = _ct_pop_mutable_map(vm, "map-set")
    _ct_check_map_key(key, "map-set")
    # Assigning to an equivalent existing key keeps its stored representative
    # and insertion position.
    map_obj[key] = value
    vm.push(map_obj)


def _ct_map_delete(vm: CompileTimeVM) -> None:
    key = vm.pop()
    map_obj = _ct_pop_mutable_map(vm, "map-delete")
    _ct_check_map_key(key, "map-delete")
    existed = key in map_obj
    if existed:
        del map_obj[key]
    vm.push(map_obj)
    vm.push(1 if existed else 0)


def _ct_map_clear(vm: CompileTimeVM) -> None:
    map_obj = _ct_pop_mutable_map(vm, "map-clear")
    map_obj.clear()
    vm.push(map_obj)


def _ct_map_merge(vm: CompileTimeVM) -> None:
    source = _ct_pop_map(vm, "map-merge")
    target = _ct_pop_mutable_map(vm, "map-merge")
    for key in source:
        _ct_check_map_key(key, "map-merge")
    if source is not target:
        target.update(source)
    vm.push(target)


# -- strings -----------------------------------------------------------------

def _ct_string_append(vm: CompileTimeVM) -> None:
    right = _ct_pop_string(vm, "string-append")
    left = _ct_pop_string(vm, "string-append")
    vm.push(left + right)


def _ct_string_length(vm: CompileTimeVM) -> None:
    vm.push(len(_ct_pop_string(vm, "string-length")))


def _ct_string_split(vm: CompileTimeVM) -> None:
    separator = _ct_pop_string(vm, "string-split")
    text = _ct_pop_string(vm, "string-split")
    if separator == "":
        raise ParseError("string-split: separator must not be empty", code="ct-argument-invalid")
    vm.push(text.split(separator))


def _ct_string_join(vm: CompileTimeVM) -> None:
    separator = _ct_pop_string(vm, "string-join")
    items = _ct_pop_list(vm, "string-join")
    for index, item in enumerate(items):
        if not isinstance(item, str):
            raise ParseError(
                f"string-join: element {index} is {_ct_type_name(item)}, expected string "
                "(convert integers with int>string)",
                code="ct-argument-type",
            )
    vm.push(separator.join(items))


def _ct_string_replace(vm: CompileTimeVM) -> None:
    replacement = _ct_pop_string(vm, "string-replace")
    old = _ct_pop_string(vm, "string-replace")
    text = _ct_pop_string(vm, "string-replace")
    if old == "":
        raise ParseError("string-replace: substring to replace must not be empty", code="ct-argument-invalid")
    vm.push(text.replace(old, replacement))


def _ct_string_strip(vm: CompileTimeVM) -> None:
    vm.push(_l2_strip(_ct_pop_string(vm, "string-strip")))


def _ct_string_upper(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_string(vm, "string-upper").translate(_L2_ASCII_UPPER))


def _ct_string_lower(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_string(vm, "string-lower").translate(_L2_ASCII_LOWER))


def _ct_string_contains(vm: CompileTimeVM) -> None:
    needle = _ct_pop_string(vm, "string-contains?")
    haystack = _ct_pop_string(vm, "string-contains?")
    vm.push(1 if needle in haystack else 0)


def _ct_string_starts_with(vm: CompileTimeVM) -> None:
    prefix = _ct_pop_string(vm, "string-starts-with?")
    text = _ct_pop_string(vm, "string-starts-with?")
    vm.push(1 if text.startswith(prefix) else 0)


def _ct_string_ends_with(vm: CompileTimeVM) -> None:
    suffix = _ct_pop_string(vm, "string-ends-with?")
    text = _ct_pop_string(vm, "string-ends-with?")
    vm.push(1 if text.endswith(suffix) else 0)


def _ct_string_equal(vm: CompileTimeVM) -> None:
    right = _ct_pop_string(vm, "string-equal?")
    left = _ct_pop_string(vm, "string-equal?")
    vm.push(1 if left == right else 0)


def _ct_try_string_to_int(vm: CompileTimeVM) -> None:
    value = _parse_l2_int(_ct_pop_string(vm, "try-string>int"))
    if value is None:
        vm.push(0)
        vm.push(0)
    else:
        vm.push(value)
        vm.push(1)


def _ct_persistent_size(parser: "Parser") -> int:
    """`persistent` size from CT-supplied runtime BSS fragments (0: the
    standard layout's default)."""
    size = 0
    for line in parser.output_bss or ():
        if type(line) is _AsmFragment:
            match = _RE_BSS_PERSISTENT.search(line)
            if match:
                size = int(match.group(1))
    return size


def _ct_output_pop_fragment(vm: CompileTimeVM, word: str) -> _AsmFragment:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, str):
        raise ParseError(f"{word}: fragment must be a string, got {_ct_type_name(value)}", code="ct-argument-type")
    return _AsmFragment(value)


def _ct_output_pop_fragments(vm: CompileTimeVM, word: str) -> List[_AsmFragment]:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, list):
        raise ParseError(f"{word}: fragment-list must be a list of strings, got {_ct_type_name(value)}",
                         code="ct-argument-type")
    for index, item in enumerate(value):
        if not isinstance(item, str):
            raise ParseError(f"{word}: element {index} is {_ct_type_name(item)}, expected a string",
                             code="ct-argument-type")
    return [_AsmFragment(item) for item in value]


def _ct_output_words(buffer: str, label: str) -> List[Tuple[str, Callable[[CompileTimeVM], None]]]:
    """append/set/clear words for one buffer.  The runtime BSS buffer
    starts as the standard layout; the others start empty."""
    def current(parser: "Parser") -> List[str]:
        lines = getattr(parser, buffer)
        if lines is None:  # runtime BSS not yet changed: the standard layout
            lines = list(_RUNTIME_BSS_LAYOUT)
            setattr(parser, buffer, lines)
        return lines

    def append(vm: CompileTimeVM) -> None:
        fragment = _ct_output_pop_fragment(vm, f"ct-output-append-{label}")
        current(vm.parser).append(fragment)

    def set_(vm: CompileTimeVM) -> None:
        setattr(vm.parser, buffer, _ct_output_pop_fragments(vm, f"ct-output-set-{label}"))

    def clear(vm: CompileTimeVM) -> None:
        setattr(vm.parser, buffer, [])

    return [(f"ct-output-append-{label}", append), (f"ct-output-set-{label}", set_),
            (f"ct-output-clear-{label}", clear)]


_CT_OUTPUT_WORDS = (_ct_output_words("output_text_preamble", "text-preamble")
                    + _ct_output_words("output_data", "data")
                    + _ct_output_words("output_bss", "bss"))


def _ct_loop_index(vm: CompileTimeVM) -> None:
    if not vm.loop_stack:
        raise ParseError("'i' used outside of a for loop", code="ct-loop-index-unavailable")
    frame = vm.loop_stack[-1]
    if not isinstance(frame, dict):
        raise ParseError("'i' used outside of a for loop", code="ct-loop-index-unavailable")
    try:
        idx = int(frame["initial"]) - int(frame["remaining"])
    except Exception:
        raise ParseError("'i' used outside of a for loop", code="ct-loop-index-unavailable") from None
    vm.push(idx)


# -- Compiler control and operation emission -------------------------

_LABEL_PREFIX_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
_OVERRIDABLE_CONTROL_WORDS = frozenset({"if", "else", "for", "while", "do"})


def _ct_pop_typed(vm: CompileTimeVM, word: str, kind: type, what: str) -> Any:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, kind):
        raise ParseError(f"{word}: {what}, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_frame(vm: CompileTimeVM, word: str) -> Dict[str, Any]:
    return _ct_pop_typed(vm, word, dict, "expects a control frame map")


def _ct_pop_nonempty(vm: CompileTimeVM, word: str, what: str) -> str:
    value = _ct_pop_typed(vm, word, str, f"{what} must be a string")
    if value == "":
        raise ParseError(f"{word}: {what} must not be empty", code="ct-argument-invalid")
    return value


def _ct_control_frame_new(vm: CompileTimeVM) -> None:
    """type -- frame"""
    vm.push({"type": _ct_pop_typed(vm, "ct-control-frame-new", str, "type must be a string")})


def _ct_control_get(vm: CompileTimeVM) -> None:
    """frame key -- value found?"""
    key = _ct_pop_typed(vm, "ct-control-get", str, "key must be a string")
    frame = _ct_pop_frame(vm, "ct-control-get")
    if key in frame:
        vm.push(frame[key])
        vm.push(1)
    else:
        vm.push(None)
        vm.push(0)


def _ct_unquote_begin(vm: CompileTimeVM) -> None:
    vm._unquote_depths.append(len(vm.stack))


def _ct_unquote_end(vm: CompileTimeVM) -> None:
    """Move the expression's value to the unquote stack, so the next
    `$( … )` sees the data stack as it was before the quotation."""
    depth = vm._unquote_depths.pop() if vm._unquote_depths else len(vm.stack) - 1
    left = len(vm.stack) - depth
    # The value is the top of the stack.  The expression may consume one
    # value below it: `$( )` splices (and consumes) the top value, `$(dup)`
    # a copy of it, `$(1 +)` the incremented top.
    if left not in (0, 1) or not vm.stack:
        raise ParseError(f"`$( … )` must leave one value: it may consume at most one value and must push one "
                         f"(net change 0 or +1), got {left:+d}", code="syntax-splice-invalid")
    vm._unquote_values.append(vm.stack.pop())


def _ct_control_get_or_nil(vm: CompileTimeVM) -> None:
    """frame key -- value|nil (ct-control-get without the found flag)"""
    key = _ct_pop_typed(vm, "ct-control-get?", str, "key must be a string")
    frame = _ct_pop_frame(vm, "ct-control-get?")
    vm.push(frame.get(key))


def _ct_control_set(vm: CompileTimeVM) -> None:
    """frame key value -- frame (mutates and returns the same map)"""
    value = vm.pop()
    key = _ct_pop_typed(vm, "ct-control-set", str, "key must be a string")
    frame = _ct_pop_frame(vm, "ct-control-set")
    frame[key] = value
    vm.push(frame)


def _ct_control_push(vm: CompileTimeVM) -> None:
    """frame -- : pushes a shallow top-level copy."""
    vm.parser._push_control(dict(_ct_pop_frame(vm, "ct-control-push")))


def _ct_control_pop(vm: CompileTimeVM) -> None:
    """-- frame"""
    if not vm.parser.control_stack:
        raise ParseError("ct-control-pop: control stack underflow", code="parser-control-underflow")
    vm.push(dict(vm.parser.control_stack.pop()))


def _ct_control_peek(vm: CompileTimeVM) -> None:
    """-- frame-or-nil"""
    stack = vm.parser.control_stack
    vm.push(dict(stack[-1]) if stack else None)


def _ct_control_depth(vm: CompileTimeVM) -> None:
    vm.push(len(vm.parser.control_stack))


def _close_op_problem(descriptor: Any) -> Optional[str]:
    """Why a close-op descriptor is not canonical (exactly `op` and `data`,
    `op` a nonempty string), or None."""
    if not isinstance(descriptor, dict):
        return f"a close-op descriptor must be a map, got {_ct_type_name(descriptor)}"
    if len(descriptor) != 2 or "op" not in descriptor or "data" not in descriptor:
        return f"a close-op descriptor must have exactly the keys 'op' and 'data', got {sorted(map(str, descriptor))}"
    op = descriptor["op"]
    if not isinstance(op, str) or op == "":
        return f"a close-op 'op' must be a nonempty string, got {op!r}"
    return None


def _ct_control_add_close_op(vm: CompileTimeVM) -> None:
    """frame op data -- frame"""
    word = "ct-control-add-close-op"
    data = vm.pop()
    op = _ct_pop_nonempty(vm, word, "op")
    frame = _ct_pop_frame(vm, word)
    close_ops = frame.get("close_ops")
    if close_ops is not None:
        if not isinstance(close_ops, list):
            raise ParseError(f"{word}: the frame's close_ops must be a list or nil, got {_ct_type_name(close_ops)}",
                             code="ct-argument-invalid")
        for index, descriptor in enumerate(close_ops):
            problem = _close_op_problem(descriptor)
            if problem is not None:
                raise ParseError(f"{word}: close_ops[{index}]: {problem}", code="ct-argument-invalid")
        close_ops.append({"op": op, "data": data})
    else:
        frame["close_ops"] = [{"op": op, "data": data}]
    vm.push(frame)


def _ct_op_emit(vm: CompileTimeVM) -> None:
    """op data -- : appends an internal Op holding `data` by reference."""
    data = vm.pop()
    op = _ct_pop_nonempty(vm, "ct-op-emit", "op")
    vm.parser.emit_node(_make_op(op, data))


def _ct_label_new(vm: CompileTimeVM) -> None:
    """prefix -- label"""
    prefix = _ct_pop_typed(vm, "ct-label-new", str, "prefix must be a string")
    if not _LABEL_PREFIX_RE.match(prefix):
        raise ParseError(f"ct-label-new: prefix must match [A-Za-z_][A-Za-z0-9_]*, got {prefix!r}",
                         code="ct-argument-invalid")
    vm.push(vm.parser._new_label(prefix))


def _ct_parser_last_line(vm: CompileTimeVM) -> None:
    tok = vm.parser._last_token
    vm.push(0 if tok is None else tok.line)


def _ct_parser_register_block_opener(vm: CompileTimeVM) -> None:
    vm.parser.block_openers.add(_ct_pop_nonempty(vm, "ct-parser-register-block-opener", "name"))


def _ct_parser_unregister_block_opener(vm: CompileTimeVM) -> None:
    vm.parser.block_openers.discard(_ct_pop_nonempty(vm, "ct-parser-unregister-block-opener", "name"))


def _ct_control_override_name(vm: CompileTimeVM, word: str) -> str:
    name = _ct_pop_typed(vm, word, str, "name must be a string")
    if name not in _OVERRIDABLE_CONTROL_WORDS:
        raise ParseError(f"{word}: only if, else, for, while, and do can be overridden, got {name!r}",
                         code="ct-argument-invalid")
    return name


def _ct_control_register_override(vm: CompileTimeVM) -> None:
    vm.parser.control_overrides.add(_ct_control_override_name(vm, "ct-control-register-override"))


def _ct_control_unregister_override(vm: CompileTimeVM) -> None:
    vm.parser.control_overrides.discard(_ct_control_override_name(vm, "ct-control-unregister-override"))


def _ct_stack_need(vm: CompileTimeVM, count: int, word: str) -> List[Any]:
    stack = vm.stack
    if len(stack) < count:
        raise ParseError(f"stack underflow in '{word}': needs {count} value(s), has {len(stack)}",
                         code="ct-stack-underflow")
    return stack


def _ct_dup(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 1, "dup")
    stack.append(stack[-1])


def _ct_drop(vm: CompileTimeVM) -> None:
    _ct_stack_need(vm, 1, "drop").pop()


def _ct_swap(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 2, "swap")
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _ct_over(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 2, "over")
    stack.append(stack[-2])


def _ct_rot(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 3, "rot")
    stack.append(stack.pop(-3))


def _ct_minus_rot(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 3, "-rot")
    stack.insert(-2, stack.pop())


def _ct_nip(vm: CompileTimeVM) -> None:
    del _ct_stack_need(vm, 2, "nip")[-2]


def _ct_tuck(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 2, "tuck")
    stack.insert(-2, stack[-1])


def _ct_2dup(vm: CompileTimeVM) -> None:
    stack = _ct_stack_need(vm, 2, "2dup")
    stack.extend(stack[-2:])


def _ct_2drop(vm: CompileTimeVM) -> None:
    del _ct_stack_need(vm, 2, "2drop")[-2:]


# Data-stack words with a CT-VM fast path.  They act on the CT value stack,
# so the runtime-mode VM (native stack) keeps using their assembly bodies.
_CT_VALUE_STACK_WORDS = {
    "dup": _ct_dup, "drop": _ct_drop, "swap": _ct_swap, "over": _ct_over, "rot": _ct_rot,
    "-rot": _ct_minus_rot, "nip": _ct_nip, "tuck": _ct_tuck, "2dup": _ct_2dup, "2drop": _ct_2drop,
}
_CT_VALUE_STACK_INTRINSICS = frozenset(_CT_VALUE_STACK_WORDS.values())


def is_ct_api_word(name: str, word: "Word") -> bool:
    """True for words that belong to the documented CT API: they have a
    compile-time intrinsic that is not an internal ``__`` helper or one of
    the ordinary stack words given a CT-VM fast path."""
    intrinsic = word.compile_time_intrinsic
    return (intrinsic is not None and not name.startswith("__") and "\0" not in name
            and intrinsic not in _CT_VALUE_STACK_INTRINSICS)

_CT_FAST_CT_INTRINSIC_DISPATCH = {
    **_CT_VALUE_STACK_WORDS,
    "nil": _ct_nil,
    "nil?": _ct_nil_p,
    "list-new": _ct_list_new,
    "list-clone": _ct_list_clone,
    "list-deep-clone": _ct_list_deep_clone,
    "list-append": _ct_list_append,
    "list-pop": _ct_list_pop,
    "list-pop-front": _ct_list_pop_front,
    "list-peek-front": _ct_list_peek_front,
    "list-push-front": _ct_list_push_front,
    "list-reverse": _ct_list_reverse,
    "list-length": _ct_list_length,
    "list-empty?": _ct_list_empty,
    "list-get": _ct_list_get,
    "list-set": _ct_list_set,
    "list-clear": _ct_list_clear,
    "list-extend": _ct_list_extend,
    "list-last": _ct_list_last,
    "list-insert": _ct_list_insert,
    "list-remove": _ct_list_remove,
    "list-slice": _ct_list_slice,
    "list-find": _ct_list_find,
    "list-contains?": _ct_list_contains,
    "map-new": _ct_map_new,
    "map-set": _ct_map_set,
    "map-get": _ct_map_get,
    "map-has?": _ct_map_has,
    "map-delete": _ct_map_delete,
    "map-clear": _ct_map_clear,
    "map-length": _ct_map_length,
    "map-empty?": _ct_map_empty,
    "map-keys": _ct_map_keys,
    "map-values": _ct_map_values,
    "map-clone": _ct_map_clone,
    "map-merge": _ct_map_merge,
}


_SURROGATE_RE = re.compile("[\ud800-\udfff]")


def _source_cursor_error(word: str, message: str) -> ParseError:
    return ParseError(f"{word}: {message}", code="source-cursor-invalid-argument")


def _ct_pop_source_cursor(vm: CompileTimeVM, word: str) -> SourceCursor:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, SourceCursor):
        raise _source_cursor_error(word, f"expected a source cursor, got {_ct_type_name(value)}")
    return value


def _source_cursor_offset(value: Any, cursor: SourceCursor, word: str, what: str = "offset") -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise _source_cursor_error(word, f"{what} must be an integer, got {_ct_type_name(value)}")
    if not 0 <= value <= len(cursor.text):
        raise _source_cursor_error(word, f"{what} {value} is outside [0, {len(cursor.text)}]")
    return value


def _source_cursor_range(vm: CompileTimeVM, word: str) -> Tuple[SourceCursor, int, int]:
    end_value = vm._resolve_handle(vm.pop())
    start_value = vm._resolve_handle(vm.pop())
    cursor = _ct_pop_source_cursor(vm, word)
    start = _source_cursor_offset(start_value, cursor, word, "start")
    end = _source_cursor_offset(end_value, cursor, word, "end")
    if start > end:
        raise _source_cursor_error(word, f"start {start} is after end {end}")
    return cursor, start, end


def _source_cursor_next(cursor: SourceCursor, word: str) -> int:
    if cursor.pos >= len(cursor.text):
        origin = cursor.origin(cursor.pos, cursor.pos)
        raise ParseError(f"{word}: at end of source "
                         f"({origin.path}:{origin.start_line}:{origin.start_column})", code="source-cursor-eof")
    return ord(cursor.text[cursor.pos])


def _ct_source_cursor_new(vm: CompileTimeVM) -> None:
    path = vm._resolve_handle(vm.pop())
    text = vm._resolve_handle(vm.pop())
    if not isinstance(text, str):
        raise _source_cursor_error("source-cursor-new", f"source text must be a string, got {_ct_type_name(text)}")
    if not isinstance(path, str):
        raise _source_cursor_error("source-cursor-new", f"path must be a string, got {_ct_type_name(path)}")
    if _SURROGATE_RE.search(text) is not None:
        raise _source_cursor_error("source-cursor-new", "source text contains a surrogate code point")
    vm.push(SourceCursor(text, path))


def _ct_source_cursor_peek(vm: CompileTimeVM) -> None:
    cursor = _ct_pop_source_cursor(vm, "source-cursor-peek")
    vm.push(_source_cursor_next(cursor, "source-cursor-peek"))


def _ct_source_cursor_read(vm: CompileTimeVM) -> None:
    cursor = _ct_pop_source_cursor(vm, "source-cursor-read")
    codepoint = _source_cursor_next(cursor, "source-cursor-read")
    cursor.pos += 1
    vm.push(cursor)
    vm.push(codepoint)


def _ct_source_cursor_eof(vm: CompileTimeVM) -> None:
    cursor = _ct_pop_source_cursor(vm, "source-cursor-eof?")
    vm.push(1 if cursor.pos >= len(cursor.text) else 0)


def _ct_source_cursor_pos(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_source_cursor(vm, "source-cursor-pos").pos)


def _ct_source_cursor_set_pos(vm: CompileTimeVM) -> None:
    value = vm._resolve_handle(vm.pop())
    cursor = _ct_pop_source_cursor(vm, "source-cursor-set-pos")
    cursor.pos = _source_cursor_offset(value, cursor, "source-cursor-set-pos")
    vm.push(cursor)


def _ct_source_cursor_slice(vm: CompileTimeVM) -> None:
    cursor, start, end = _source_cursor_range(vm, "source-cursor-slice")
    vm.push(cursor.text[start:end])


def _ct_source_cursor_span(vm: CompileTimeVM) -> None:
    cursor, start, end = _source_cursor_range(vm, "source-cursor-span")
    vm.push(cursor.origin(start, end))


def _ct_tokenizer_get_config(vm: CompileTimeVM) -> None:
    vm.push(vm.parser.reader.get_config())


def _ct_tokenizer_set_config(vm: CompileTimeVM) -> None:
    vm.parser.reader.set_config(vm._resolve_handle(vm.pop()))


def _ct_tokenizer_run(vm: CompileTimeVM) -> None:
    path = _ct_pop_string(vm, "ct-tokenizer-run")
    text = _ct_pop_string(vm, "ct-tokenizer-run")
    vm.push(vm.parser.reader.tokenize_text(text, path))


_RNG_DEFAULT_SEED = 0x1A2B3C4D


def _ct_string_utf8_length(vm: CompileTimeVM) -> None:
    """string -- byte-count"""
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, str):
        raise ParseError(f"string-utf8-length expects a string, got {_ct_type_name(value)}", code="ct-argument-type")
    vm.push(len(value.encode("utf-8", errors="surrogatepass")))


def _ct_rng_pop_int(vm: CompileTimeVM, word: str, argument: str) -> int:
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, bool) or not isinstance(value, int):
        raise ParseError(f"{word}: {argument} must be an integer, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_rng_seed(vm: CompileTimeVM) -> None:
    """seed -- : reset the stream; the seed is reduced modulo 2**64."""
    seed = _ct_rng_pop_int(vm, "ct-rng-seed", "seed")
    vm.parser._rng.seed(seed % (1 << 64))


def _ct_rng_int(vm: CompileTimeVM) -> None:
    """bound -- n : n in [0, bound)."""
    bound = _ct_rng_pop_int(vm, "ct-rng-int", "bound")
    if bound <= 0:
        raise ParseError(f"ct-rng-int: bound must be > 0, got {bound}", code="ct-argument-invalid")
    vm.push(vm.parser._rng.randrange(bound))


def _ct_rng_range(vm: CompileTimeVM) -> None:
    """lo hi -- n : n in [lo, hi]."""
    hi = _ct_rng_pop_int(vm, "ct-rng-range", "hi")
    lo = _ct_rng_pop_int(vm, "ct-rng-range", "lo")
    if lo > hi:
        raise ParseError(f"ct-rng-range: lo ({lo}) must be <= hi ({hi})", code="ct-argument-invalid")
    vm.push(vm.parser._rng.randint(lo, hi))


def _capture_deep_clone(value: Any) -> Any:
    if isinstance(value, list):
        return [_capture_deep_clone(item) for item in value]
    if isinstance(value, tuple):
        return [_capture_deep_clone(item) for item in value]
    if isinstance(value, dict):
        return {
            _capture_deep_clone(key): _capture_deep_clone(item)
            for key, item in value.items()
        }
    if isinstance(value, Token):
        return value.lexeme
    return value



def _capture_normalize_value(value: Any) -> Any:
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, Token):
        return value.lexeme
    if isinstance(value, list):
        return [_capture_normalize_value(item) for item in value]
    if isinstance(value, tuple):
        return [_capture_normalize_value(item) for item in value]
    if isinstance(value, dict):
        out: Dict[str, Any] = {}
        for key, item in value.items():
            if isinstance(key, (bool, int, float, str)):
                out[str(key)] = _capture_normalize_value(item)
            elif isinstance(key, Token):
                out[key.lexeme] = _capture_normalize_value(item)
            else:
                out[str(key)] = _capture_normalize_value(item)
        return out
    return repr(value)


def _capture_serialize_text(value: Any) -> str:
    import json

    normalized = _capture_normalize_value(value)
    return json.dumps(normalized, sort_keys=True, ensure_ascii=True, separators=(",", ":"))


def _capture_diff_values(left: Any, right: Any, *, path: str, out: List[str]) -> None:
    if type(left) is not type(right):
        out.append(f"{path}: type mismatch ({type(left).__name__} != {type(right).__name__})")
        return

    if isinstance(left, dict):
        keys = sorted(set(left.keys()) | set(right.keys()))
        for key in keys:
            key_path = f"{path}.{key}"
            if key not in left:
                out.append(f"{key_path}: missing on left")
                continue
            if key not in right:
                out.append(f"{key_path}: missing on right")
                continue
            _capture_diff_values(left[key], right[key], path=key_path, out=out)
        return

    if isinstance(left, list):
        max_len = max(len(left), len(right))
        for idx in range(max_len):
            idx_path = f"{path}[{idx}]"
            if idx >= len(left):
                out.append(f"{idx_path}: missing on left")
                continue
            if idx >= len(right):
                out.append(f"{idx_path}: missing on right")
                continue
            _capture_diff_values(left[idx], right[idx], path=idx_path, out=out)
        return

    if left != right:
        out.append(f"{path}: {left!r} != {right!r}")



def _ct_gensym(vm: CompileTimeVM) -> None:
    """gensym: prefix -- identifier.  The prefix is sanitized to
    [A-Za-z0-9_] (trimmed of underscores, `g` if empty, `g_` prepended when
    it starts with a digit), then `_N` is appended with a counter that only
    grows, skipping names the compiler already knows."""
    prefix = _ct_pop_string(vm, "gensym")
    safe_prefix = re.sub(r"[^A-Za-z0-9_]", "_", prefix).strip("_")
    if not safe_prefix:
        safe_prefix = "g"
    if safe_prefix[0].isdigit():
        safe_prefix = "g_" + safe_prefix
    parser = vm.parser
    counter = parser._gensym_counter
    while True:
        counter += 1
        candidate = f"{safe_prefix}_{counter}"
        if not vm.dictionary.has_name(candidate):
            break
    parser._gensym_counter = counter
    vm.push(candidate)


def _ct_repr(vm: CompileTimeVM) -> None:
    value = vm._resolve_handle(vm.pop())
    vm.push(_capture_serialize_text(value))



def _ct_introspection_value(value: Any) -> Any:
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, Token):
        return value.lexeme
    if isinstance(value, Word):
        return value.name
    if isinstance(value, list):
        return [_ct_introspection_value(item) for item in value]
    if isinstance(value, tuple):
        return [_ct_introspection_value(item) for item in value]
    if isinstance(value, dict):
        snapshot: Dict[Any, Any] = {}
        for key, item in value.items():
            if isinstance(key, (bool, int, float, str)):
                snap_key = key
            elif isinstance(key, Token):
                snap_key = key.lexeme
            elif isinstance(key, Word):
                snap_key = key.name
            else:
                snap_key = str(key)
            snapshot[snap_key] = _ct_introspection_value(item)
        return snapshot
    return repr(value)


# ---------------------------------------------------------------------------
# Definition candidates.  Name-based inspection reads the selected
# eligible candidate; name-based mutation needs exactly one unowned
# candidate.  Handle-based getters accept any live candidate; generic
# mutators reject pack-owned candidates.  Stale handles make getters push
# `nil 0` and setters/removers push `0`.
# ---------------------------------------------------------------------------

_DEFINITION_FLOAT_RE = re.compile(r"[+-]?(?:\d+\.\d*|\.\d+)(?:[eE][+-]?\d+)?")
_DEFINITION_FLAG_KEYS = ("immediate", "compile-only", "runtime-only", "inline", "preserve")


def _ct_pop_definition_handle(vm: CompileTimeVM, word: str) -> DefinitionHandle:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, DefinitionHandle):
        raise ParseError(f"{word} expects a DefinitionHandle, got {_ct_type_name(value)}",
                         code="definition-argument-type")
    return value


def _ct_pop_definition_string(vm: CompileTimeVM, word: str, what: str = "name") -> str:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, str):
        raise ParseError(f"{word} expects a string {what}, got {_ct_type_name(value)}",
                         code="definition-argument-type")
    if what == "name" and not value:
        raise ParseError(f"{word}: definition name must not be empty", code="definition-argument-invalid")
    return value


def _ct_pop_definition_priority(vm: CompileTimeVM, word: str) -> int:
    value = vm.pop()
    if isinstance(value, bool) or not isinstance(value, int):
        raise ParseError(f"{word} expects an integer priority, got {_ct_type_name(value)}",
                         code="definition-argument-type")
    return value


def _valid_definition_name(parser: Parser, name: str) -> bool:
    """A name a source definition could declare: one ordinary token that
    is not a literal."""
    if not name or name[0] in "\"'" or any(ch in _L2_WHITESPACE for ch in name):
        return False
    try:
        tokens = parser.reader.tokenize_text(name, "<definition-name>")
    except ParseError:
        return False
    if len(tokens) != 1 or tokens[0].lexeme != name:
        return False
    return _parse_l2_int(name) is None and not _DEFINITION_FLOAT_RE.fullmatch(name)


def _ct_pop_new_definition_name(vm: CompileTimeVM, word: str) -> str:
    name = _ct_pop_definition_string(vm, word)
    if not _valid_definition_name(vm.parser, name):
        raise ParseError(f"{word}: {name!r} is not a valid definition name", code="definition-argument-invalid")
    return name


def _ct_live_candidate(vm: CompileTimeVM, handle: DefinitionHandle) -> Optional[Word]:
    return vm.dictionary.resolve(handle)


def _ct_mutable_candidate(vm: CompileTimeVM, word: str, handle: DefinitionHandle) -> Optional[Word]:
    """The live, unowned candidate for `handle` (None when stale); a live
    pack-owned candidate is an error."""
    candidate = vm.dictionary.resolve(handle)
    if candidate is not None and candidate.owner is not None:
        raise ParseError(
            f"{word}: definition '{candidate.name}' is owned by language pack '{candidate.owner}'; "
            "use that pack's operations",
            code="definition-owned",
        )
    return candidate


def _ct_unique_candidate(vm: CompileTimeVM, name: str) -> Optional[Word]:
    """The name's sole candidate when it is unowned, else None."""
    candidates = vm.dictionary.candidates.get(name)
    if not candidates or len(candidates) != 1 or candidates[0].owner is not None:
        return None
    return candidates[0]


def _ct_push_found(vm: CompileTimeVM, value: Any) -> None:
    if value is None:
        vm.push(None)
        vm.push(0)
    else:
        vm.push(value)
        vm.push(1)


def _ct_definition_candidates(vm: CompileTimeVM) -> None:
    name = _ct_pop_definition_string(vm, "ct-definition-candidates")
    dictionary = vm.dictionary
    selected = dictionary.selected(name)
    vm.push([dictionary.candidate_record(word, selected) for word in dictionary.ordered_candidates(name)])


def _ct_definition_exists(vm: CompileTimeVM) -> None:
    name = _ct_pop_definition_string(vm, "ct-definition-exists?")
    vm.push(1 if vm.dictionary.has_name(name) else 0)


def _ct_effect_count(vm: CompileTimeVM, word: str, value: Any) -> Optional[int]:
    value = vm._resolve_handle(value)
    if value is None:
        return None
    if type(value) is not int or value < 0:
        raise ParseError(f"{word}: a count must be a non-negative integer or nil, got {value!r}",
                         code="ct-argument-type")
    return value


def _ct_definition_set_effect(vm: CompileTimeVM) -> None:
    """name inputs outputs -- ok: declare the selected word or :asm
    definition's stack effect in cells (nil: unknown).  The stack checker
    relies on such declarations; effect comments count items."""
    outputs = _ct_effect_count(vm, "ct-definition-set-effect", vm.pop())
    inputs = _ct_effect_count(vm, "ct-definition-set-effect", vm.pop())
    name = _ct_pop_definition_string(vm, "ct-definition-set-effect", "name")
    word = vm.dictionary.lookup(name)
    definition = word.definition if word is not None else None
    if not isinstance(definition, (Definition, AsmDefinition)):
        vm.push(0)
        return
    definition.stack_inputs = inputs
    definition.stack_outputs = outputs
    definition.effect_exact = inputs is not None and outputs is not None
    vm.push(1)


def _ct_definition_effect(vm: CompileTimeVM) -> None:
    """name -- inputs outputs found: the declared effect (nil when unknown)."""
    name = _ct_pop_definition_string(vm, "ct-definition-effect", "name")
    word = vm.dictionary.lookup(name)
    definition = word.definition if word is not None else None
    if not isinstance(definition, (Definition, AsmDefinition)):
        vm.push(None)
        vm.push(None)
        vm.push(0)
        return
    vm.push(definition.stack_inputs)
    vm.push(definition.stack_outputs)
    vm.push(1)


def _ct_definition_list_names(vm: CompileTimeVM) -> None:
    vm.push(vm.dictionary.names())


def _ct_definition_list_names_prefix(vm: CompileTimeVM) -> None:
    prefix = _ct_pop_definition_string(vm, "ct-definition-list-names-prefix", "prefix")
    vm.push([name for name in vm.dictionary.names() if name.startswith(prefix)])


def _ct_definition_get(vm: CompileTimeVM) -> None:
    candidate = _ct_live_candidate(vm, _ct_pop_definition_handle(vm, "ct-definition-get"))
    _ct_push_found(vm, None if candidate is None else vm.dictionary.candidate_record(candidate))


def _ct_definition_get_by_name(vm: CompileTimeVM) -> None:
    name = _ct_pop_definition_string(vm, "ct-definition-get-by-name")
    candidate = vm.dictionary.selected(name)
    _ct_push_found(vm, None if candidate is None else vm.dictionary.candidate_record(candidate, candidate))


def _definition_body_value(word: Word) -> Optional[List[Any]]:
    """Detached snapshot of a candidate's current executable body."""
    definition = word.macro_def.body if word.macro_def is not None else word.definition
    if isinstance(definition, Definition):
        return [{"op": node.op, "data": _ct_introspection_value(node.data)} for node in definition.body]
    return None


def _definition_asm_value(word: Word) -> Optional[str]:
    definition = word.definition
    return definition.body if isinstance(definition, AsmDefinition) else None


def _definition_reader(name: str, by_name: bool, read: Callable[[Word], Any]) -> Callable[[CompileTimeVM], None]:
    def reader(vm: CompileTimeVM) -> None:
        if by_name:
            candidate = vm.dictionary.selected(_ct_pop_definition_string(vm, name))
        else:
            candidate = _ct_live_candidate(vm, _ct_pop_definition_handle(vm, name))
        _ct_push_found(vm, None if candidate is None else read(candidate))
    reader.__name__ = "_ct_" + name.replace("-", "_")
    return reader


def _ct_pop_flag_patch(vm: CompileTimeVM, word: str) -> Dict[str, bool]:
    patch = vm._resolve_handle(vm.pop())
    if not isinstance(patch, Mapping):
        raise ParseError(f"{word} expects a flag map, got {_ct_type_name(patch)}", code="definition-argument-type")
    flags: Dict[str, bool] = {}
    for key, value in patch.items():
        if key not in _DEFINITION_FLAG_KEYS:
            raise ParseError(f"{word}: unknown definition flag {key!r}", code="definition-argument-invalid")
        if not isinstance(value, int):
            raise ParseError(f"{word}: flag {key!r} expects an integer or boolean, got {_ct_type_name(value)}",
                             code="definition-argument-type")
        flags[key] = bool(value)
    return flags


def _apply_definition_flags(word: str, candidate: Word, flags: Dict[str, bool]) -> bool:
    """Validate a flag patch against a candidate; apply it and return True
    when it changes anything."""
    current = {
        "immediate": candidate.immediate,
        "compile-only": candidate.compile_only,
        "runtime-only": candidate.runtime_only,
        "inline": candidate.inline,
        "preserve": bool(getattr(candidate.definition, "preserve", False)),
    }
    merged = dict(current)
    merged.update(flags)
    if merged["runtime-only"] and (merged["immediate"] or merged["compile-only"]):
        raise ParseError(f"{word}: '{candidate.name}' cannot be both runtime-only and compile-time-active",
                         code="definition-flags-conflict")
    if merged["runtime-only"] and candidate.prefer_l2:
        raise ParseError(f"{word}: '{candidate.name}' prefers its L2 definition at compile time and cannot be runtime-only",
                         code="definition-flags-conflict")
    if merged["preserve"] and not merged["inline"]:
        raise ParseError(f"{word}: 'preserve' requires 'inline'", code="definition-flags-conflict")
    if (merged["inline"] or merged["preserve"]) and not isinstance(candidate.definition, (Definition, AsmDefinition)):
        raise ParseError(f"{word}: only word and :asm definitions can be inline", code="definition-kind-invalid")
    return merged != current


def _set_definition_flags(candidate: Word, flags: Dict[str, bool]) -> None:
    if "immediate" in flags:
        candidate.immediate = flags["immediate"]
    if "compile-only" in flags:
        candidate.compile_only = flags["compile-only"]
    if "runtime-only" in flags:
        candidate.runtime_only = flags["runtime-only"]
    if "inline" in flags:
        candidate.inline = flags["inline"]
    definition = candidate.definition
    if definition is not None:
        definition.immediate = candidate.immediate
        definition.compile_only = candidate.compile_only
        definition.runtime_only = candidate.runtime_only
        definition.inline = candidate.inline
        if "preserve" in flags:
            definition.preserve = flags["preserve"]
    candidate.compile_time_override = candidate.prefer_l2 or candidate.immediate or candidate.compile_only


def _definition_setter(name: str, by_name: bool, pop_value: Callable[[CompileTimeVM, str], Any],
                       apply: Callable[[CompileTimeVM, str, Word, Any], None]) -> Callable[[CompileTimeVM], None]:
    """A `target value -- ok?` mutator: the value is validated first, then
    the target is resolved (stale handle or non-unique name pushes 0)."""
    def setter(vm: CompileTimeVM) -> None:
        value = pop_value(vm, name)
        if by_name:
            candidate = _ct_unique_candidate(vm, _ct_pop_definition_string(vm, name))
        else:
            candidate = _ct_mutable_candidate(vm, name, _ct_pop_definition_handle(vm, name))
        if candidate is None:
            vm.push(0)
            return
        apply(vm, name, candidate, value)
        vm.push(1)
    setter.__name__ = "_ct_" + name.replace("-", "_").replace("?", "_p")
    return setter


def _apply_priority(vm: CompileTimeVM, word: str, candidate: Word, priority: int) -> None:
    vm.dictionary.set_priority(candidate, priority)


def _apply_flags(vm: CompileTimeVM, word: str, candidate: Word, flags: Dict[str, bool]) -> None:
    if _apply_definition_flags(word, candidate, flags):
        vm.dictionary.update(candidate, lambda target: _set_definition_flags(target, flags))


def _ct_pop_asm_source(vm: CompileTimeVM, word: str) -> str:
    source = _ct_pop_definition_string(vm, word, "assembly source")
    if "\x00" in source:
        raise ParseError(f"{word}: assembly source must not contain NUL", code="definition-argument-invalid")
    return source


def _apply_asm(vm: CompileTimeVM, word: str, candidate: Word, source: str) -> None:
    definition = candidate.definition
    if not isinstance(definition, AsmDefinition):
        raise ParseError(f"{word}: '{candidate.name}' is a {_definition_kind(candidate)} definition, not assembly",
                         code="definition-kind-invalid")
    if definition.body == source:
        return

    def replace(target: Word) -> None:
        definition.body = source
        definition._inline_lines = None

    vm.dictionary.update(candidate, replace)


def _ct_pop_new_name_value(vm: CompileTimeVM, word: str) -> str:
    return _ct_pop_new_definition_name(vm, word)


def _apply_rename(vm: CompileTimeVM, word: str, candidate: Word, new_name: str) -> None:
    vm.dictionary.rename(candidate, new_name)


def _ct_definition_clone_common(vm: CompileTimeVM, word: str, by_name: bool) -> None:
    new_name = _ct_pop_new_definition_name(vm, word)
    if by_name:
        source = _ct_unique_candidate(vm, _ct_pop_definition_string(vm, word))
    else:
        source = _ct_mutable_candidate(vm, word, _ct_pop_definition_handle(vm, word))
    if source is None:
        _ct_push_found(vm, None)
        return
    _ct_push_found(vm, vm.dictionary.clone(source, new_name).handle)


def _ct_definition_clone(vm: CompileTimeVM) -> None:
    _ct_definition_clone_common(vm, "ct-definition-clone", False)


def _ct_definition_clone_by_name(vm: CompileTimeVM) -> None:
    _ct_definition_clone_common(vm, "ct-definition-clone-by-name", True)


def _ct_definition_unregister(vm: CompileTimeVM) -> None:
    candidate = _ct_mutable_candidate(vm, "ct-definition-unregister",
                                      _ct_pop_definition_handle(vm, "ct-definition-unregister"))
    vm.push(1 if candidate is not None and vm.parser.unregister_candidate(candidate) else 0)


def _ct_definition_unregister_by_name(vm: CompileTimeVM) -> None:
    name = _ct_pop_definition_string(vm, "ct-definition-unregister-by-name")
    vm.push(1 if vm.parser.unregister_word(name) else 0)


def _mark_prefer_l2(vm: CompileTimeVM, word: str, candidate: Optional[Word]) -> None:
    if candidate is None:
        vm.push(0)
        return
    if candidate.owner is not None:
        raise ParseError(f"{word}: definition '{candidate.name}' is owned by language pack '{candidate.owner}'",
                         code="definition-owned")
    if candidate.runtime_only:
        raise ParseError(f"{word}: '{candidate.name}' is runtime-only and cannot run at compile time",
                         code="definition-flags-conflict")
    if not candidate.prefer_l2:
        def mark(target: Word) -> None:
            target.prefer_l2 = True
            target.compile_time_override = True
        vm.dictionary.update(candidate, mark)
    vm.push(1)


def _ct_definition_prefer_l2(vm: CompileTimeVM) -> None:
    handle = _ct_pop_definition_handle(vm, "ct-definition-prefer-l2")
    _mark_prefer_l2(vm, "ct-definition-prefer-l2", vm.dictionary.resolve(handle))


def _ct_definition_prefer_l2_by_name(vm: CompileTimeVM) -> None:
    name = _ct_pop_definition_string(vm, "ct-definition-prefer-l2-by-name")
    _mark_prefer_l2(vm, "ct-definition-prefer-l2-by-name", vm.dictionary.selected(name))


def _staging_parser(parser: Parser) -> Tuple[Parser, List[Word]]:
    """A parser over the shared dictionary whose completed definitions are
    collected instead of registered."""
    staged = Parser(parser.dictionary, parser.reader)
    staged.rewrites = parser.rewrites.view_for(staged)
    staged._langs = parser._langs
    staged.block_openers = set(parser.block_openers)
    staged.control_overrides = set(parser.control_overrides)
    sink: List[Word] = []
    staged._definition_sink = sink
    return staged, sink


# ---------------------------------------------------------------------------
# Structured macro inspection and mutation and body replacement.
# ---------------------------------------------------------------------------

_MACRO_RECORD_KEYS = ("parameters", "body", "metadata")


def _macro_metadata_value(value: Any, where: str) -> Any:
    """Deep-detached copy of a metadata value; rejects non-data values."""
    if value is None or isinstance(value, (bool, int, float, str, Token, Syntax)):
        return value
    if isinstance(value, list):
        return [_macro_metadata_value(item, where) for item in value]
    if isinstance(value, Mapping):
        copy: Dict[Any, Any] = {}
        for key, item in value.items():
            _ct_check_map_key(key, where)
            copy[key] = _macro_metadata_value(item, where)
        return copy
    raise ParseError(f"{where}: metadata cannot hold a {_ct_type_name(value)}", code="definition-argument-invalid")


def _macro_record(word: Word) -> Dict[str, Any]:
    mdef: _MacroDef = word.macro_def
    return {
        "parameters": list(mdef.params),
        "body": mdef.body_tokens,
        "metadata": _macro_metadata_value(mdef.metadata, "ct-macro-get"),
    }


def _ct_macro_get(vm: CompileTimeVM) -> None:
    candidate = _ct_live_candidate(vm, _ct_pop_definition_handle(vm, "ct-macro-get"))
    _ct_push_found(vm, _macro_record(candidate) if candidate is not None and candidate.macro_def is not None else None)


def _ct_macro_get_by_name(vm: CompileTimeVM) -> None:
    candidate = vm.dictionary.selected(_ct_pop_definition_string(vm, "ct-macro-get-by-name"))
    _ct_push_found(vm, _macro_record(candidate) if candidate is not None and candidate.macro_def is not None else None)


def _ct_pop_macro_patch(vm: CompileTimeVM, word: str) -> Dict[str, Any]:
    patch = vm._resolve_handle(vm.pop())
    if not isinstance(patch, Mapping):
        raise ParseError(f"{word} expects a patch map, got {_ct_type_name(patch)}", code="definition-argument-type")
    result: Dict[str, Any] = {}
    for key, value in patch.items():
        if key not in _MACRO_RECORD_KEYS:
            raise ParseError(f"{word}: unknown or read-only macro field {key!r}", code="definition-argument-invalid")
        if key == "parameters":
            if not isinstance(value, list) or not all(isinstance(p, str) for p in value):
                raise ParseError(f"{word}: parameters must be a list of strings", code="definition-argument-type")
            for p in value:
                if not _is_l2_identifier(p) or vm.parser._reserved_binding_name(p):
                    raise ParseError(f"{word}: invalid parameter name {p!r}", code="definition-argument-invalid")
            if len(set(value)) != len(value):
                raise ParseError(f"{word}: duplicate parameter names", code="definition-argument-invalid")
            result[key] = tuple(value)
        elif key == "body":
            if not isinstance(value, Syntax):
                raise ParseError(f"{word}: body must be a Syntax value", code="definition-argument-type")
            result[key] = value
        else:
            if not isinstance(value, Mapping) or not all(isinstance(k, str) for k in value):
                raise ParseError(f"{word}: metadata must be a map with string keys", code="definition-argument-type")
            result[key] = _macro_metadata_value(value, word)
    return result


def _apply_macro_patch(vm: CompileTimeVM, word: str, candidate: Word, patch: Dict[str, Any]) -> None:
    mdef: Optional[_MacroDef] = candidate.macro_def
    if mdef is None:
        raise ParseError(f"{word}: '{candidate.name}' is a {_definition_kind(candidate)} definition, not a macro",
                         code="definition-kind-invalid")
    params = patch.get("parameters", mdef.params)
    body_tokens = patch.get("body", mdef.body_tokens)
    metadata = patch.get("metadata", mdef.metadata)
    unchanged = (params == mdef.params and body_tokens.lexemes() == mdef.body_tokens.lexemes()
                 and _ct_values_identical(metadata, mdef.metadata))
    if unchanged:
        return
    if params != mdef.params or body_tokens is not mdef.body_tokens:
        body = vm.parser._compile_macro_body(candidate.name, params, body_tokens)
    else:
        body = mdef.body
    fast = vm.parser._macro_fast_template(body)
    replacement = _MacroDef(params, body, body_tokens, metadata, fast)

    def install(target: Word) -> None:
        target.macro_def = replacement

    vm.dictionary.update(candidate, install)


def _apply_body(vm: CompileTimeVM, word: str, candidate: Word, body_tokens: Syntax) -> None:
    """ct-definition-set-body: parse Syntax as the new body of an L2 word
    (validated, not executed); flags and source provenance are kept."""
    definition = candidate.definition
    if candidate.macro_def is not None:
        raise ParseError(f"{word}: '{candidate.name}' is a macro; use ct-macro-set", code="definition-kind-invalid")
    if not isinstance(definition, Definition):
        raise ParseError(f"{word}: '{candidate.name}' is a {_definition_kind(candidate)} definition, not an L2 word",
                         code="definition-kind-invalid")
    staged, sink = _staging_parser(vm.parser)
    tokens = [_derive_token(None, "word"), _derive_token(None, candidate.name)]
    tokens += list(body_tokens.tokens) + [_derive_token(None, "end")]
    staged.parse(tokens, "")
    if len(sink) != 1 or not isinstance(sink[0].definition, Definition):
        raise ParseError(f"{word}: the Syntax is not a valid word body", code="definition-source-invalid")
    new_body = sink[0].definition.body
    replacement = Definition(name=definition.name, body=new_body, immediate=definition.immediate,
                             compile_only=definition.compile_only, runtime_only=definition.runtime_only,
                             terminator=definition.terminator, inline=definition.inline,
                             stack_inputs=definition.stack_inputs, stack_outputs=definition.stack_outputs,
                             preserve=definition.preserve)
    replacement.effect_exact = definition.effect_exact

    def install(target: Word) -> None:
        # Running calls keep the old Definition (entry-time snapshot).
        target.definition = replacement

    vm.dictionary.update(candidate, install)


def _ct_pop_body_syntax(vm: CompileTimeVM, word: str) -> Syntax:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, Syntax):
        raise ParseError(f"{word} expects a Syntax body, got {_ct_type_name(value)}", code="definition-argument-type")
    return value


def _ct_macro_context(vm: CompileTimeVM) -> None:
    vm.push(vm.parser.macro_context())


def _ct_definition_register_source(vm: CompileTimeVM) -> None:
    source = _ct_pop_definition_string(vm, "ct-definition-register-source", "source")
    parser = vm.parser
    module = parser._active_module
    if module is None:
        raise ParseError("ct-definition-register-source needs an active compilation", code="definition-source-invalid")
    staged, sink = _staging_parser(parser)
    tokens = parser.reader.tokenize(source, default_path="<ct-definition-register-source>")
    fragment = staged.parse(tokens, source)
    valid = (Definition, AsmDefinition)
    if (not all(isinstance(form, valid) for form in fragment.forms)
            or not all(isinstance(word.definition, valid) for word in sink)):
        raise ParseError("ct-definition-register-source source must contain only word or :asm definitions",
                         code="definition-source-invalid")
    # Validated: commit each candidate in source order; each registration
    # publishes its own events before the next one is committed.
    module.forms.extend(fragment.forms)
    module.variables.update(fragment.variables)
    module.cstruct_layouts.update(fragment.cstruct_layouts)
    handles: List[DefinitionHandle] = []
    for word in sink:
        parser.dictionary.register(word, warn=False)
        handles.append(word.handle)
    vm.push(handles)


def _ct_meta_runtime_source(vm: CompileTimeVM) -> None:
    """Internal intrinsic behind stdlib `meta-runtime-get-source` (not a
    public CT word).  In CT execution: name -- source byte-length, from the
    selected definition's retained source (ct-definition-source-by-name plus
    string-utf8-length), "" 0 when unavailable.  In the runtime-mode VM
    (--ct-run-main): see _rt_source_lookup."""
    if vm.runtime_mode:
        _rt_source_lookup(vm)
        return
    name = vm._resolve_handle(vm.pop())
    if not isinstance(name, str):
        raise ParseError(f"meta-runtime-get-source expects a name string, got {_ct_type_name(name)}",
                         code="ct-argument-type")
    candidate = vm.dictionary.selected(name)
    source = candidate.source_text if candidate is not None and candidate.source_text else ""
    vm.push(source)
    vm.push(len(source.encode("utf-8")))


def _rt_source_lookup(vm: CompileTimeVM) -> None:
    """name-address name-length -- source-address source-length, answering
    from the selected definition's retained source like the embedded
    catalog; 0 0 when unavailable or when source embedding is off."""
    name_len = vm.pop_int()
    name_addr = vm.pop_int()
    if name_len < 0:
        raise ParseError("meta-runtime-get-source-embedded: negative name length", code="ct-argument-invalid")
    name = ctypes.string_at(name_addr, name_len).decode("utf-8", errors="replace")
    candidate = vm.dictionary.selected(name)
    source = candidate.source_text if candidate is not None else None
    if not source or vm._ct_source_embed_text is None:
        vm.push(0)
        vm.push(0)
        return
    data = source.encode("utf-8")
    address = vm.memory.allocate(len(data) + 1)
    ctypes.memmove(address, data, len(data))
    ctypes.c_uint8.from_address(address + len(data)).value = 0
    vm.push(address)
    vm.push(len(data))


def _ct_parser_get_pos(vm: CompileTimeVM) -> None:
    vm.push(vm.parser.pos)


def _ct_parser_remaining(vm: CompileTimeVM) -> None:
    vm.push(max(0, len(vm.parser.tokens) - vm.parser.pos))


def _ct_pop_position(vm: CompileTimeVM, word: str) -> int:
    """Pop a strict integer parser position in [0, token-count]."""
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, bool) or not isinstance(value, int):
        raise ParseError(f"{word} expects an integer position, got {_ct_type_name(value)}", code="ct-argument-type")
    if value < 0 or value > len(vm.parser.tokens):
        raise ParseError(
            f"{word}: position {value} is outside the token stream [0, {len(vm.parser.tokens)}]",
            code="ct-argument-invalid",
        )
    return value


def _ct_parser_eof(vm: CompileTimeVM) -> None:
    vm.push(1 if vm.parser.pos >= len(vm.parser.tokens) else 0)


def _ct_definition_predeclare_all(vm: CompileTimeVM) -> None:
    parser = vm.parser
    tokens = parser.tokens
    scan_pos = parser.pos

    if parser.context_stack and isinstance(parser.context_stack[-1], Definition):
        depth = 1 + len(parser.control_stack)
        while scan_pos < len(tokens) and depth:
            lexeme = tokens[scan_pos].lexeme
            if lexeme == "end" or lexeme == "again":
                depth -= 1
            elif lexeme == "if" or lexeme in parser.block_openers - {"word"}:
                depth += 1
            scan_pos += 1
        if depth:
            raise ParseError("ct-definition-predeclare-all could not find the end of the current word", code="parser-definition-scan-failed")

    while scan_pos + 1 < len(tokens):
        if tokens[scan_pos].lexeme != "word":
            scan_pos += 1
            continue

        name = tokens[scan_pos + 1].lexeme
        end_pos = scan_pos + 2
        depth = 0
        while end_pos < len(tokens):
            lexeme = tokens[end_pos].lexeme
            if lexeme == "end":
                if depth == 0:
                    break
                depth -= 1
            elif lexeme == "again":
                depth -= 1
            elif lexeme == "if" or lexeme in parser.block_openers - {"word"}:
                depth += 1
            end_pos += 1
        if end_pos >= len(tokens):
            raise ParseError(f"ct-definition-predeclare-all could not find the end of word '{name}'", code="parser-definition-scan-failed")

        if name in parser._predeclared:
            scan_pos = end_pos + 1
            continue
        staged, sink = _staging_parser(parser)
        fragment = staged.parse(tokens[scan_pos : end_pos + 1], parser.source)
        if (len(fragment.forms) != 1 or not isinstance(fragment.forms[0], Definition)
                or len(sink) != 1 or sink[0].definition is not fragment.forms[0]):
            raise ParseError(f"ct-definition-predeclare-all expected a regular word definition for '{name}'", code="parser-definition-scan-failed")
        # Registered now as a completed candidate; the later normal parse
        # completes this same candidate.
        candidate = sink[0]
        parser.dictionary.register(candidate, warn=False)
        parser._predeclared[name] = candidate
        scan_pos = end_pos + 1


def _ct_parser_peek(vm: CompileTimeVM) -> None:
    offset = vm._resolve_handle(vm.pop())
    if isinstance(offset, bool) or not isinstance(offset, int):
        raise ParseError(f"ct-parser-peek expects an integer offset, got {_ct_type_name(offset)}", code="ct-argument-type")
    if offset < 0:
        raise ParseError(f"ct-parser-peek: offset must not be negative, got {offset}", code="ct-argument-invalid")
    idx = vm.parser.pos + offset
    if idx >= len(vm.parser.tokens):
        vm.push(None)
        return
    vm.push(vm.parser.tokens[idx])


def _ct_parser_set_pos(vm: CompileTimeVM) -> None:
    pos = _ct_pop_position(vm, "ct-parser-set-pos")
    old_pos = vm.parser.pos
    vm.parser.pos = pos
    vm.parser._last_token = vm.parser.tokens[pos - 1] if pos > 0 else None
    vm.push(old_pos)


def _ct_parser_checkpoint(vm: CompileTimeVM) -> None:
    parser = vm.parser
    vm.push(ParserCheckpoint(parser, parser.pos, parser._last_token))


def _public_restore_point(point: Dict[str, Any]) -> Dict[str, Any]:
    return {key: value for key, value in point.items() if key not in ("token", "last_token")}


def _ct_pop_restore_point_id(vm: CompileTimeVM, word: str) -> int:
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, bool) or not isinstance(value, int):
        raise ParseError(f"{word} expects an integer restore-point id, got {_ct_type_name(value)}",
                         code="ct-argument-type")
    return value


def _ct_recovery_list_restore_points(vm: CompileTimeVM) -> None:
    vm.push([_public_restore_point(vm.parser._restore_point_map(point))
             for point in vm.parser._error_restore_points])


def _ct_recovery_get_restore_point(vm: CompileTimeVM) -> None:
    point_id = _ct_pop_restore_point_id(vm, "ct-recovery-get-restore-point")
    point = vm.parser._find_error_restore_point(point_id)
    if point is None:
        raise ParseError(f"unknown restore point {point_id}", code="recovery-restore-point-invalid")
    vm.push(_public_restore_point(point))


def _ct_recovery_jump(vm: CompileTimeVM) -> None:
    point_id = _ct_pop_restore_point_id(vm, "ct-recovery-jump")
    recovery = vm.parser._active_error_recovery
    if recovery is None:
        raise ParseError("ct-recovery-jump is only available while a recoverable error is being dispatched",
                         code="recovery-operation-unavailable")
    point = vm.parser._find_error_restore_point(point_id)
    if point is None or point.get("stage") != recovery.get("stage"):
        raise ParseError(f"restore point {point_id} is not valid for this error", code="recovery-restore-point-invalid")
    recovery["restore_point_id"] = point_id


def _ct_recovery_resume(vm: CompileTimeVM) -> None:
    recovery = vm.parser._active_error_recovery
    if recovery is None:
        raise ParseError("ct-recovery-resume is only available while a recoverable error is being dispatched",
                         code="recovery-operation-unavailable")
    recovery["resume"] = True
    vm.push(1)


def _ct_recovery_get_retry_limit(vm: CompileTimeVM) -> None:
    vm.push(vm.parser._error_recovery_retry_limit)


def _ct_recovery_set_retry_limit(vm: CompileTimeVM) -> None:
    limit = vm._resolve_handle(vm.pop())
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise ParseError(f"ct-recovery-set-retry-limit expects a positive integer, got {limit!r}",
                         code="ct-argument-invalid")
    previous = vm.parser._error_recovery_retry_limit
    vm.parser._error_recovery_retry_limit = limit
    vm.push(previous)


def _ct_parser_restore(vm: CompileTimeVM) -> None:
    checkpoint = vm._resolve_handle(vm.pop())
    if not isinstance(checkpoint, ParserCheckpoint):
        raise ParseError(f"ct-parser-restore expects a ParserCheckpoint, got {_ct_type_name(checkpoint)}", code="ct-argument-type")
    parser = vm.parser
    if checkpoint.parser is not parser or checkpoint.pos > len(parser.tokens):
        vm.push(0)
        return
    parser.pos = checkpoint.pos
    parser._last_token = checkpoint.last_token
    vm.push(1)


def _ct_parser_tail(vm: CompileTimeVM) -> None:
    vm.push(list(vm.parser.tokens[vm.parser.pos:]))


def _ct_parser_session_begin(vm: CompileTimeVM) -> None:
    parser = vm.parser
    session = ParserSession(parser, list(parser.tokens), parser.pos, parser._last_token)
    parser._ct_parser_sessions.append(session)
    vm.push(session)


def _ct_pop_active_session(vm: CompileTimeVM, word: str) -> Optional[ParserSession]:
    """Pop a ParserSession; return it only if it is the open topmost session
    of this parser (strict LIFO), else None."""
    session = vm._resolve_handle(vm.pop())
    if not isinstance(session, ParserSession):
        raise ParseError(f"{word} expects a ParserSession, got {_ct_type_name(session)}", code="ct-argument-type")
    sessions = vm.parser._ct_parser_sessions
    if not session.open or not sessions or sessions[-1] is not session:
        return None
    sessions.pop()
    session.open = False
    return session


def _ct_parser_session_commit(vm: CompileTimeVM) -> None:
    session = _ct_pop_active_session(vm, "ct-parser-session-commit")
    vm.push(0 if session is None else 1)


def _ct_parser_session_rollback(vm: CompileTimeVM) -> None:
    session = _ct_pop_active_session(vm, "ct-parser-session-rollback")
    if session is None:
        vm.push(0)
        return
    parser = vm.parser
    parser.tokens = list(session.tokens)
    parser.pos = session.pos
    parser._last_token = session.last_token
    vm.push(1)


def _ct_pop_delimiter(vm: CompileTimeVM, word: str) -> str:
    delimiter = _ct_pop_string(vm, word)
    if delimiter == "":
        raise ParseError(f"{word}: delimiter must not be empty", code="ct-argument-invalid")
    return delimiter


def _ct_parser_collect_until(vm: CompileTimeVM) -> None:
    delimiter = _ct_pop_delimiter(vm, "ct-parser-collect-until")
    parser = vm.parser
    tokens = parser.tokens
    out: List[Token] = []
    found = 0
    while parser.pos < len(tokens):
        token = parser._consume()
        parser._last_token = token
        if token.lexeme == delimiter:
            found = 1
            break
        out.append(token)
    vm.push(out)
    vm.push(found)


def _ct_parser_collect_balanced(vm: CompileTimeVM) -> None:
    close_lexeme = _ct_pop_delimiter(vm, "ct-parser-collect-balanced")
    open_lexeme = _ct_pop_delimiter(vm, "ct-parser-collect-balanced")
    parser = vm.parser
    tokens = parser.tokens
    nests = open_lexeme != close_lexeme
    out: List[Token] = []
    depth = 0
    found = 0
    while parser.pos < len(tokens):
        token = parser._consume()
        parser._last_token = token
        lexeme = token.lexeme
        if lexeme == close_lexeme:
            if depth == 0:
                found = 1
                break
            depth -= 1
        elif nests and lexeme == open_lexeme:
            depth += 1
        out.append(token)
    vm.push(out)
    vm.push(found)


def _ct_parser_current(vm: CompileTimeVM) -> None:
    vm.push(vm.parser._last_token)


def _ct_expansion_set_depth_limit(vm: CompileTimeVM) -> None:
    """ct-expansion-set-depth-limit: limit --.  One nesting limit covers
    macro and rewrite expansion together."""
    limit = vm.pop()
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise ParseError(f"ct-expansion-set-depth-limit expects a positive integer, got {limit!r}",
                         code="ct-argument-invalid")
    vm.parser.set_macro_expansion_limit(limit)


def _ct_expansion_get_depth_limit(vm: CompileTimeVM) -> None:
    vm.push(vm.parser.macro_expansion_limit)


# ---------------------------------------------------------------------------
# Syntax values.  Syntax is immutable; every operation consumes
# its inputs and returns a new value.
# ---------------------------------------------------------------------------

def _ct_pop_syntax(vm: CompileTimeVM, word: str) -> Syntax:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, Syntax):
        raise ParseError(f"{word} expects a Syntax value, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_syntax_length(vm: CompileTimeVM) -> None:
    vm.push(len(_ct_pop_syntax(vm, "syntax-length").tokens))


def _ct_syntax_get(vm: CompileTimeVM) -> None:
    index = _ct_pop_index(vm, "syntax-get")
    tokens = _ct_pop_syntax(vm, "syntax-get").tokens
    length = len(tokens)
    if index < -length or index >= length:
        raise ParseError(f"syntax-get: index {index} out of range for Syntax of length {length}",
                         code="ct-index-out-of-range")
    vm.push(tokens[index])


def _ct_syntax_slice(vm: CompileTimeVM) -> None:
    end = _ct_pop_index(vm, "syntax-slice")
    start = _ct_pop_index(vm, "syntax-slice")
    vm.push(Syntax(_ct_pop_syntax(vm, "syntax-slice").tokens[start:end]))


def _ct_syntax_concat(vm: CompileTimeVM) -> None:
    right = _ct_pop_syntax(vm, "syntax-concat")
    left = _ct_pop_syntax(vm, "syntax-concat")
    vm.push(Syntax(left.tokens + right.tokens))


def _ct_syntax_to_list(vm: CompileTimeVM) -> None:
    vm.push(list(_ct_pop_syntax(vm, "syntax>list").tokens))


def _ct_list_to_syntax(vm: CompileTimeVM) -> None:
    items = _ct_pop_list(vm, "list>syntax")
    for index, item in enumerate(items):
        if not isinstance(item, Token):
            raise ParseError(f"list>syntax: element {index} is {_ct_type_name(item)}, expected a Token",
                             code="ct-argument-type")
    vm.push(Syntax(items))


def _ct_emit(vm: CompileTimeVM) -> None:
    """emit: syntax --.  Inserts the Syntax's Tokens at the current position
    of the compiler's input stream."""
    syntax = _ct_pop_syntax(vm, "emit")
    parser = vm.parser
    if parser._macro_frames:
        # Inside a macro body: append to its pending output.
        parser._macro_frames[-1]["buffer"].extend(syntax.tokens)
        return
    if not parser._parsing:
        raise ParseError("emit needs an active compiler input stream", code="emit-no-input")
    parser.emit_tokens(list(syntax.tokens))





def _ct_pop_token_value(vm: CompileTimeVM, word: str) -> Token:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, Token):
        raise ParseError(f"{word} expects a token, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_origin_value(vm: CompileTimeVM, word: str) -> SourceOrigin:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, SourceOrigin):
        raise ParseError(f"{word} expects a SourceOrigin, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_frame_value(vm: CompileTimeVM, word: str) -> ExpansionFrame:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, ExpansionFrame):
        raise ParseError(f"{word} expects an ExpansionFrame, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _ct_pop_lexeme(vm: CompileTimeVM, word: str) -> str:
    lexeme = _ct_pop_string(vm, word)
    if lexeme == "":
        raise ParseError(f"{word}: lexeme must not be empty", code="ct-argument-invalid")
    return lexeme


def _ct_token_lexeme(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_token_value(vm, "token-lexeme").lexeme)


def _ct_lexeme(vm: CompileTimeVM) -> None:
    """token-or-string -- string: a token's lexeme, or the string itself."""
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, Token):
        vm.push(value.lexeme)
    elif isinstance(value, str):
        vm.push(value)
    else:
        raise ParseError(f"lexeme expects a token or a string, got {_ct_type_name(value)}", code="ct-argument-type")


def _ct_token_p(vm: CompileTimeVM) -> None:
    vm.push(1 if isinstance(vm._resolve_handle(vm.pop()), Token) else 0)


def _ct_token_slice(vm: CompileTimeVM) -> None:
    """token start end -- token: the code points [start, end) of the lexeme.
    When the token's origin spans exactly its lexeme on one line (a token
    read from source), the new origin is narrowed to the slice; otherwise
    it keeps the token's origin.  The expansion chain is kept."""
    end = vm._resolve_handle(vm.pop())
    start = vm._resolve_handle(vm.pop())
    token = _ct_pop_token_value(vm, "token-slice")
    if type(start) is not int or type(end) is not int:
        raise ParseError("token-slice: start and end must be integers", code="ct-argument-type")
    lexeme = token.lexeme
    if not (0 <= start < end <= len(lexeme)):
        raise ParseError(f"token-slice: [{start}, {end}) is not a non-empty range of '{lexeme}'",
                         code="ct-argument-invalid")
    origin = token.origin
    piece = lexeme[start:end]
    if (origin is not _SYNTHETIC_ORIGIN and origin.start_line == origin.end_line
            and origin.end - origin.start == len(lexeme)):
        narrowed = SourceOrigin(origin.path, origin.start + start, origin.start + end, origin.start_line,
                                origin.start_column + start, origin.end_line, origin.start_column + end)
        vm.push(Token(piece, token.line, token.column + start, token.start + start, token.start + end,
                      token.expansion_depth, origin=narrowed, chain=token.expansion_chain))
    else:
        vm.push(_derive_token(token, piece))


def _ct_token_from_origin(vm: CompileTimeVM) -> None:
    origin = _ct_pop_origin_value(vm, "token-from-origin")
    lexeme = _ct_pop_lexeme(vm, "token-from-origin")
    vm.push(Token(lexeme, origin.start_line, max(0, origin.start_column - 1), origin.start, origin.end,
                  origin=origin))


def _ct_token_with_lexeme(vm: CompileTimeVM) -> None:
    lexeme = _ct_pop_lexeme(vm, "token-with-lexeme")
    template = _ct_pop_token_value(vm, "token-with-lexeme")
    vm.push(_derive_token(template, lexeme))


def _ct_token_origin(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_token_value(vm, "token-origin").origin)


def _ct_token_expansion_chain(vm: CompileTimeVM) -> None:
    vm.push(list(_ct_pop_token_value(vm, "token-expansion-chain").expansion_chain))


def _ct_token_line(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_token_value(vm, "token-line").origin.start_line)


def _ct_token_column(vm: CompileTimeVM) -> None:
    vm.push(_ct_pop_token_value(vm, "token-column").origin.start_column)


def _ct_origin_accessor(field: str, word: str) -> Callable[[CompileTimeVM], None]:
    def accessor(vm: CompileTimeVM) -> None:
        vm.push(getattr(_ct_pop_origin_value(vm, word), field))
    accessor.__name__ = f"_ct_{word.replace('-', '_')}"
    return accessor


def _ct_frame_accessor(field: str, word: str) -> Callable[[CompileTimeVM], None]:
    def accessor(vm: CompileTimeVM) -> None:
        vm.push(getattr(_ct_pop_frame_value(vm, word), field))
    accessor.__name__ = f"_ct_{word.replace('-', '_')}"
    return accessor


_CT_SOURCE_ORIGIN_ACCESSORS = (
    ("source-origin-path", "path"),
    ("source-origin-start", "start"),
    ("source-origin-end", "end"),
    ("source-origin-start-line", "start_line"),
    ("source-origin-start-column", "start_column"),
    ("source-origin-end-line", "end_line"),
    ("source-origin-end-column", "end_column"),
)
_CT_EXPANSION_FRAME_ACCESSORS = (
    ("expansion-frame-kind", "kind"),
    ("expansion-frame-name", "name"),
    ("expansion-frame-call-site", "call_site"),
    ("expansion-frame-definition-origin", "definition_origin"),
)


def _ct_parser_consume(vm: CompileTimeVM) -> None:
    parser = vm.parser
    if parser.pos >= len(parser.tokens):
        raise ParseError("ct-parser-consume: unexpected end of input", code="parser-unexpected-eof")
    token = parser._consume()
    parser._last_token = token
    vm.push(token)


def _ct_parser_inject(vm: CompileTimeVM) -> None:
    tokens = _ct_pop_list(vm, "ct-parser-inject")
    for index, item in enumerate(tokens):
        if not isinstance(item, Token):
            raise ParseError(
                f"ct-parser-inject: element {index} is {_ct_type_name(item)}, expected token",
                code="ct-argument-type",
            )
    vm.parser.inject_token_objects(list(tokens))


def _ct_parser_slice(vm: CompileTimeVM) -> None:
    end = _ct_pop_position(vm, "ct-parser-slice")
    start = _ct_pop_position(vm, "ct-parser-slice")
    lo, hi = (start, end) if start <= end else (end, start)
    vm.push(vm.parser.tokens[lo:hi])


def _ct_parser_expected(vm: CompileTimeVM) -> None:
    expected_raw = vm._resolve_handle(vm.pop())
    items = expected_raw if isinstance(expected_raw, list) else [expected_raw]
    if not items:
        raise ParseError("ct-parser-expected: expected list must not be empty", code="ct-argument-invalid")
    expected_lexemes: Set[str] = set()
    for item in items:
        resolved = vm._resolve_handle(item)
        if isinstance(resolved, Token):
            expected_lexemes.add(resolved.lexeme)
        elif isinstance(resolved, str):
            if resolved == "":
                raise ParseError("ct-parser-expected: expected lexeme must not be empty", code="ct-argument-invalid")
            expected_lexemes.add(resolved)
        else:
            raise ParseError(
                f"ct-parser-expected expects a string, token, or list of them, got {_ct_type_name(resolved)}",
                code="ct-argument-type",
            )
    token = vm.parser.peek_token()
    if token is None or token.lexeme not in expected_lexemes:
        vm.push(None)
        vm.push(0)
        return
    vm.push(token)
    vm.push(1)


# -- Rewrites --------------------------------------------------------

_REWRITE_PHASE_CODES = {
    "rewrite-input": "rewrite-input-invalid",
    "rewrite-control": "rewrite-control-invalid",
    "rewrite-query": "rewrite-query-invalid",
    "rewrite-mutation": "rewrite-mutation-invalid",
}


def _rewrite_pop_stage(vm: CompileTimeVM, word: str, phase: str) -> str:
    stage = vm._resolve_handle(vm.pop())
    if stage not in _REWRITE_STAGES or not isinstance(stage, str):
        raise _rewrite_error(_REWRITE_PHASE_CODES[phase],
                             f"{word}: stage must be \"reader\" or \"grammar\", got {stage!r}")
    return stage


def _rewrite_pop_flag(vm: CompileTimeVM, word: str, phase: str, argument: str) -> bool:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, int):
        raise _rewrite_error(_REWRITE_PHASE_CODES[phase],
                             f"{word}: {argument} must be an integer or boolean, got {_ct_type_name(value)}")
    return bool(value)


def _rewrite_pop_name(vm: CompileTimeVM, word: str, phase: str, argument: str) -> str:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, str) or value == "":
        raise _rewrite_error(_REWRITE_PHASE_CODES[phase], f"{word}: {argument} must be a nonempty string, got {value!r}")
    return value


def _rewrite_pop_lexemes(vm: CompileTimeVM, word: str) -> List[str]:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise _rewrite_error("rewrite-input-invalid", f"{word}: lexeme-list must be a list of strings, "
                                                      f"got {_ct_type_name(value)}")
    return list(value)


def _ct_rewrite_adder(stage: str, named: bool, word: str) -> Callable[[CompileTimeVM], None]:
    def add(vm: CompileTimeVM) -> None:
        replacement = vm._resolve_handle(vm.pop())
        pattern = vm._resolve_handle(vm.pop())
        name = vm._resolve_handle(vm.pop()) if named else None
        if named and (not isinstance(name, str) or name == ""):
            raise _rewrite_error("rewrite-name-invalid", f"{word}: rule name must be a nonempty string, got {name!r}")
        vm.push(vm.parser.rewrites.register(stage, name, pattern, replacement))
    add.__name__ = "_ct_" + word.replace("-", "_")
    return add


def _ct_rewrite_remove(vm: CompileTimeVM) -> None:
    handle = _rewrite_pop_handle(vm, "ct-rewrite-remove", "rewrite-mutation")
    vm.push(1 if vm.parser.rewrites.remove(handle) else 0)


def _ct_rewrite_clearer(stage: str) -> Callable[[CompileTimeVM], None]:
    def clear(vm: CompileTimeVM) -> None:
        vm.push(vm.parser.rewrites.clear(stage))
    clear.__name__ = f"_ct_rewrite_clear_{stage}"
    return clear


def _ct_rewrite_lister(stage: str) -> Callable[[CompileTimeVM], None]:
    def listing(vm: CompileTimeVM) -> None:
        vm.push(vm.parser.rewrites.listing(stage))
    listing.__name__ = f"_ct_rewrite_list_{stage}"
    return listing


def _ct_rewrite_set_loop_detection(vm: CompileTimeVM) -> None:
    vm.parser.rewrites.loop_detection = _rewrite_pop_flag(vm, "ct-rewrite-set-loop-detection", "rewrite-control",
                                                          "enabled")


def _ct_rewrite_loop_detection_p(vm: CompileTimeVM) -> None:
    vm.push(1 if vm.parser.rewrites.loop_detection else 0)


def _ct_rewrite_get_loop_reports(vm: CompileTimeVM) -> None:
    vm.push(_detach_value(vm.parser.rewrites.loop_reports))


def _ct_rewrite_clear_loop_reports(vm: CompileTimeVM) -> None:
    reports = vm.parser.rewrites.loop_reports
    count = len(reports)
    reports.clear()
    vm.push(count)


def _ct_rewrite_set_max_steps(vm: CompileTimeVM) -> None:
    limit = vm._resolve_handle(vm.pop())
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise _rewrite_error("rewrite-control-invalid",
                             f"ct-rewrite-set-max-steps: limit must be a nonnegative integer, got {limit!r}")
    vm.parser.rewrites.max_steps = limit


def _ct_rewrite_get_max_steps(vm: CompileTimeVM) -> None:
    vm.push(vm.parser.rewrites.max_steps)


def _ct_rewrite_set_pipeline_active(vm: CompileTimeVM) -> None:
    word = "ct-rewrite-set-pipeline-active"
    enabled = _rewrite_pop_flag(vm, word, "rewrite-control", "enabled")
    pipeline = _rewrite_pop_name(vm, word, "rewrite-control", "pipeline")
    stage = _rewrite_pop_stage(vm, word, "rewrite-control")
    vm.parser.rewrites.set_pipeline_active(stage, pipeline, enabled)


def _ct_rewrite_list_active_pipelines(vm: CompileTimeVM) -> None:
    stage = _rewrite_pop_stage(vm, "ct-rewrite-list-active-pipelines", "rewrite-control")
    vm.push(sorted(vm.parser.rewrites.pipelines[stage]))


def _ct_rewrite_scope_push(vm: CompileTimeVM) -> None:
    vm.push(vm.parser.rewrites.scope_push())


def _ct_rewrite_scope_pop(vm: CompileTimeVM) -> None:
    vm.push(1 if vm.parser.rewrites.scope_pop() else 0)


def _ct_rewrite_run_on_list(vm: CompileTimeVM) -> None:
    lexemes = _rewrite_pop_lexemes(vm, "ct-rewrite-run-on-list")
    stage = _rewrite_pop_stage(vm, "ct-rewrite-run-on-list", "rewrite-input")
    engine = vm.parser.rewrites
    result, patches = engine.simulate(stage, lexemes, engine.max_steps)
    vm.push(result)
    vm.push(patches)


def _ct_rewrite_dry_run(vm: CompileTimeVM) -> None:
    limit = vm._resolve_handle(vm.pop())
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise _rewrite_error("rewrite-input-invalid",
                             f"ct-rewrite-dry-run: max_steps must be a nonnegative integer, got {limit!r}")
    lexemes = _rewrite_pop_lexemes(vm, "ct-rewrite-dry-run")
    stage = _rewrite_pop_stage(vm, "ct-rewrite-dry-run", "rewrite-input")
    result, patches = vm.parser.rewrites.simulate(stage, lexemes, limit)
    vm.push(result)
    vm.push(patches)


def _rewrite_validate_property(word: str, prop: str, value: Any) -> Any:
    def bad(expected: str) -> ParseError:
        return _rewrite_error("rewrite-mutation-invalid", f"{word}: {prop} must be {expected}, got {value!r}")

    if prop == "priority":
        if isinstance(value, bool) or not isinstance(value, int):
            raise bad("an integer")
        return value
    if prop == "enabled":
        if not isinstance(value, int):
            raise bad("an integer or boolean")
        return bool(value)
    if prop == "pipeline":
        if not isinstance(value, str) or value == "":
            raise bad("a nonempty string")
        return value
    if value is not None and (not isinstance(value, str) or value == ""):
        raise bad("nil or a nonempty handler name")
    return value


def _ct_rewrite_rule_setter(prop: str) -> Callable[[CompileTimeVM], None]:
    word = f"ct-rewrite-rule-set-{prop}"

    def setter(vm: CompileTimeVM) -> None:
        value = vm._resolve_handle(vm.pop())
        handle = _rewrite_pop_handle(vm, word, "rewrite-mutation")
        value = _rewrite_validate_property(word, prop, value)
        engine = vm.parser.rewrites
        rule = engine.resolve(handle)
        if rule is None:
            vm.push(0)
            return
        if prop == "priority":
            engine.set_priority(rule, value)
        elif prop == "enabled":
            engine.set_enabled(rule, value)
        elif prop == "pipeline":
            engine.set_pipeline(rule, value)
        else:
            rule.guard = value
        vm.push(1)
    setter.__name__ = "_ct_" + word.replace("-", "_")
    return setter


def _ct_rewrite_rule_getter(prop: str) -> Callable[[CompileTimeVM], None]:
    word = f"ct-rewrite-rule-get-{prop}"

    def getter(vm: CompileTimeVM) -> None:
        engine = vm.parser.rewrites
        target = vm._resolve_handle(vm.pop())
        if isinstance(target, RewriteHandle):
            rule = engine.resolve(target)
        elif isinstance(target, str):
            if target == "":
                raise _rewrite_error("rewrite-query-invalid", f"{word}: rule name must be nonempty")
            stage = _rewrite_pop_stage(vm, word, "rewrite-query")
            rule = engine.by_name(stage, target)
        else:
            raise _rewrite_error("rewrite-handle-invalid",
                                 f"{word} expects a RewriteHandle or a stage and rule name, got {_ct_type_name(target)}",
                                 phase="rewrite-query")
        if rule is None:
            vm.push(None)
            vm.push(0)
            return
        value = getattr(rule, prop)
        vm.push((1 if value else 0) if prop == "enabled" else value)
        vm.push(1)
    getter.__name__ = "_ct_" + word.replace("-", "_")
    return getter


_CT_REWRITE_WORDS: List[Tuple[str, Callable[[CompileTimeVM], None]]] = [
    ("ct-rewrite-add-reader", _ct_rewrite_adder("reader", False, "ct-rewrite-add-reader")),
    ("ct-rewrite-add-reader-named", _ct_rewrite_adder("reader", True, "ct-rewrite-add-reader-named")),
    ("ct-rewrite-add-grammar", _ct_rewrite_adder("grammar", False, "ct-rewrite-add-grammar")),
    ("ct-rewrite-add-grammar-named", _ct_rewrite_adder("grammar", True, "ct-rewrite-add-grammar-named")),
    ("ct-rewrite-remove", _ct_rewrite_remove),
    ("ct-rewrite-clear-reader", _ct_rewrite_clearer("reader")),
    ("ct-rewrite-clear-grammar", _ct_rewrite_clearer("grammar")),
    ("ct-rewrite-list-reader", _ct_rewrite_lister("reader")),
    ("ct-rewrite-list-grammar", _ct_rewrite_lister("grammar")),
    ("ct-rewrite-set-loop-detection", _ct_rewrite_set_loop_detection),
    ("ct-rewrite-loop-detection?", _ct_rewrite_loop_detection_p),
    ("ct-rewrite-get-loop-reports", _ct_rewrite_get_loop_reports),
    ("ct-rewrite-clear-loop-reports", _ct_rewrite_clear_loop_reports),
    ("ct-rewrite-set-max-steps", _ct_rewrite_set_max_steps),
    ("ct-rewrite-get-max-steps", _ct_rewrite_get_max_steps),
    ("ct-rewrite-set-pipeline-active", _ct_rewrite_set_pipeline_active),
    ("ct-rewrite-list-active-pipelines", _ct_rewrite_list_active_pipelines),
    ("ct-rewrite-scope-push", _ct_rewrite_scope_push),
    ("ct-rewrite-scope-pop", _ct_rewrite_scope_pop),
    ("ct-rewrite-run-on-list", _ct_rewrite_run_on_list),
    ("ct-rewrite-dry-run", _ct_rewrite_dry_run),
] + [
    (f"ct-rewrite-rule-{verb}-{prop}", (_ct_rewrite_rule_setter if verb == "set" else _ct_rewrite_rule_getter)(prop))
    for prop in ("priority", "enabled", "pipeline", "guard")
    for verb in ("set", "get")
]


# -- Language packs and token hooks ------------------------------------

def _lang_pop_flag(vm: CompileTimeVM, word: str) -> bool:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, int):
        raise _lang_error("language-pack-invalid", f"{word}: enabled must be an integer or boolean, got {_ct_type_name(value)}")
    return bool(value)


def _lang_pop_priority(vm: CompileTimeVM, word: str) -> int:
    value = vm._resolve_handle(vm.pop())
    if isinstance(value, bool) or not isinstance(value, int):
        raise _lang_error("language-pack-invalid", f"{word}: priority must be an integer, got {value!r}")
    return value


def _lang_pop_hook_handle(vm: CompileTimeVM, word: str) -> TokenHookHandle:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, TokenHookHandle):
        raise _lang_error("language-pack-handle-invalid", f"{word} expects a TokenHookHandle, got {_ct_type_name(value)}")
    return value


def _ct_lang_create(vm: CompileTimeVM) -> None:
    vm.push(1 if vm.parser.lang_create(vm._resolve_handle(vm.pop())) else 0)


def _ct_lang_exists(vm: CompileTimeVM) -> None:
    name = vm._resolve_handle(vm.pop())
    vm.parser._lang_check_name(name, "ct-lang-exists?")
    vm.push(1 if name in vm.parser._langs.packs else 0)


def _ct_lang_active(vm: CompileTimeVM) -> None:
    name = vm._resolve_handle(vm.pop())
    vm.parser._lang_check_name(name, "ct-lang-active?")
    vm.push(1 if vm.parser._lang_owner_active(name) else 0)


def _ct_lang_list(vm: CompileTimeVM) -> None:
    vm.push(sorted(vm.parser._langs.packs))


def _ct_lang_list_active(vm: CompileTimeVM) -> None:
    vm.push(sorted(name for name, pack in vm.parser._langs.packs.items() if pack.active))


def _ct_lang_activator(active: bool) -> Callable[[CompileTimeVM], None]:
    word = "ct-lang-activate" if active else "ct-lang-deactivate"

    def activate(vm: CompileTimeVM) -> None:
        vm.push(1 if vm.parser.lang_set_active(vm._resolve_handle(vm.pop()), active, word) else 0)
    activate.__name__ = "_ct_" + word.replace("-", "_")
    return activate


def _ct_lang_set_meta(vm: CompileTimeVM) -> None:
    metadata = vm._resolve_handle(vm.pop())
    vm.parser.lang_set_metadata(vm._resolve_handle(vm.pop()), metadata)
    vm.push(1)


def _ct_lang_get_meta(vm: CompileTimeVM) -> None:
    name = vm._resolve_handle(vm.pop())
    vm.parser._lang_check_name(name, "ct-lang-get-meta")
    pack = vm.parser._langs.packs.get(name)
    if pack is None:
        vm.push(None)
        vm.push(0)
        return
    vm.push(_lang_portable_copy(pack.metadata, "metadata"))
    vm.push(1)


def _ct_lang_status(vm: CompileTimeVM) -> None:
    status = vm.parser.lang_status(vm._resolve_handle(vm.pop()))
    vm.push(status)
    vm.push(0 if status is None else 1)


def _ct_lang_remove(vm: CompileTimeVM) -> None:
    vm.push(1 if vm.parser.lang_remove(vm._resolve_handle(vm.pop())) else 0)


def _ct_lang_rewrite_adder(stage: str) -> Callable[[CompileTimeVM], None]:
    word = f"ct-lang-add-{stage}-rewrite-named"

    def add(vm: CompileTimeVM) -> None:
        replacement = vm._resolve_handle(vm.pop())
        pattern = vm._resolve_handle(vm.pop())
        rule_name = vm._resolve_handle(vm.pop())
        language = vm._resolve_handle(vm.pop())
        if not isinstance(rule_name, str) or rule_name == "":
            raise _rewrite_error("rewrite-name-invalid", f"{word}: rule name must be a nonempty string, got {rule_name!r}")
        vm.push(vm.parser.lang_add_rewrite(language, stage, rule_name, pattern, replacement))
    add.__name__ = "_ct_" + word.replace("-", "_")
    return add


def _ct_lang_add_token_hook(vm: CompileTimeVM) -> None:
    handler = vm._resolve_handle(vm.pop())
    vm.push(vm.parser.lang_add_token_hook(vm._resolve_handle(vm.pop()), handler))


def _ct_lang_set_token_hook_priority(vm: CompileTimeVM) -> None:
    word = "ct-lang-set-token-hook-priority"
    priority = vm.pop()
    hook = vm.parser.lang_hook(_lang_pop_hook_handle(vm, word))
    vm.push(priority)
    priority = _lang_pop_priority(vm, word)
    if hook is None:
        vm.push(0)
        return
    hook.priority = priority
    vm.parser._lang_refresh_hooks()
    vm.push(1)


def _ct_lang_set_token_hook_enabled(vm: CompileTimeVM) -> None:
    word = "ct-lang-set-token-hook-enabled"
    enabled = vm.pop()
    hook = vm.parser.lang_hook(_lang_pop_hook_handle(vm, word))
    vm.push(enabled)
    enabled = _lang_pop_flag(vm, word)
    if hook is None:
        vm.push(0)
        return
    hook.enabled = enabled
    vm.parser._lang_refresh_hooks()
    vm.push(1)


def _ct_lang_remove_token_hook(vm: CompileTimeVM) -> None:
    handle = _lang_pop_hook_handle(vm, "ct-lang-remove-token-hook")
    vm.push(1 if vm.parser.lang_remove_token_hook(handle) else 0)


def _ct_lang_adopter(macro: bool) -> Callable[[CompileTimeVM], None]:
    word = "ct-lang-register-macro" if macro else "ct-lang-register-word"

    def adopt(vm: CompileTimeVM) -> None:
        resource = vm._resolve_handle(vm.pop())
        vm.push(1 if vm.parser.lang_adopt(vm._resolve_handle(vm.pop()), resource, macro) else 0)
    adopt.__name__ = "_ct_" + word.replace("-", "_")
    return adopt


def _ct_lang_set_resource_priority(vm: CompileTimeVM) -> None:
    word = "ct-lang-set-resource-priority"
    priority = _lang_pop_priority(vm, word)
    resource = vm._resolve_handle(vm.pop())
    candidate = vm.parser.lang_resource(vm._resolve_handle(vm.pop()), resource, word)
    if candidate is None:
        vm.push(0)
        return
    vm.dictionary.set_priority(candidate, priority)
    vm.push(1)


def _ct_lang_get_resource_priority(vm: CompileTimeVM) -> None:
    resource = vm._resolve_handle(vm.pop())
    candidate = vm.parser.lang_resource(vm._resolve_handle(vm.pop()), resource, "ct-lang-get-resource-priority")
    vm.push(None if candidate is None else candidate.priority)
    vm.push(0 if candidate is None else 1)


def _ct_lang_unregister_resource(vm: CompileTimeVM) -> None:
    resource = vm._resolve_handle(vm.pop())
    vm.push(1 if vm.parser.lang_unregister_resource(vm._resolve_handle(vm.pop()), resource) else 0)


def _ct_parser_set_token_hook(vm: CompileTimeVM) -> None:
    vm.parser.set_global_token_hook(vm._resolve_handle(vm.pop()))


def _ct_parser_clear_token_hook(vm: CompileTimeVM) -> None:
    vm.parser.clear_global_token_hook()


_CT_LANG_WORDS: List[Tuple[str, Callable[[CompileTimeVM], None]]] = [
    ("ct-lang-create", _ct_lang_create),
    ("ct-lang-exists?", _ct_lang_exists),
    ("ct-lang-list", _ct_lang_list),
    ("ct-lang-list-active", _ct_lang_list_active),
    ("ct-lang-activate", _ct_lang_activator(True)),
    ("ct-lang-deactivate", _ct_lang_activator(False)),
    ("ct-lang-active?", _ct_lang_active),
    ("ct-lang-set-meta", _ct_lang_set_meta),
    ("ct-lang-get-meta", _ct_lang_get_meta),
    ("ct-lang-status", _ct_lang_status),
    ("ct-lang-remove", _ct_lang_remove),
    ("ct-lang-add-reader-rewrite-named", _ct_lang_rewrite_adder("reader")),
    ("ct-lang-add-grammar-rewrite-named", _ct_lang_rewrite_adder("grammar")),
    ("ct-lang-add-token-hook", _ct_lang_add_token_hook),
    ("ct-lang-set-token-hook-priority", _ct_lang_set_token_hook_priority),
    ("ct-lang-set-token-hook-enabled", _ct_lang_set_token_hook_enabled),
    ("ct-lang-remove-token-hook", _ct_lang_remove_token_hook),
    ("ct-lang-register-word", _ct_lang_adopter(False)),
    ("ct-lang-register-macro", _ct_lang_adopter(True)),
    ("ct-lang-set-resource-priority", _ct_lang_set_resource_priority),
    ("ct-lang-get-resource-priority", _ct_lang_get_resource_priority),
    ("ct-lang-unregister-resource", _ct_lang_unregister_resource),
    ("ct-parser-set-token-hook", _ct_parser_set_token_hook),
    ("ct-parser-clear-token-hook", _ct_parser_clear_token_hook),
]


# -- Diagnostics ----------------------------------------------------

_RELATED_KEYS = frozenset({"kind", "message", "origin"})


def _ct_pop_diagnostic(vm: CompileTimeVM, word: str) -> Diagnostic:
    value = vm._resolve_handle(vm.pop())
    if not isinstance(value, Diagnostic):
        raise ParseError(f"{word} expects a Diagnostic, got {_ct_type_name(value)}", code="ct-argument-type")
    return value


def _diagnostic_related_map(record: Tuple[str, Optional[str], SourceOrigin]) -> Dict[str, Any]:
    kind, message, origin = record
    out: Dict[str, Any] = {"kind": kind}
    if message is not None:
        out["message"] = message
    out["origin"] = origin
    return out


def _diagnostic_to_map(diag: Diagnostic) -> Dict[str, Any]:
    """Detached map view of a Diagnostic (ct-diagnostic-list)."""
    return {
        "severity": diag.severity,
        "code": diag.code,
        "category": diag.category,
        "phase": diag.phase,
        "message": diag.message,
        "primary": diag.primary,
        "related": [_diagnostic_related_map(record) for record in diag.related],
    }


def _ct_call_site_origin(vm: CompileTimeVM) -> SourceOrigin:
    """The SourceOrigin of the CT code currently executing."""
    origin = _origin_from_location(vm.current_location)
    if origin is None:
        origin = vm.parser._token_origin(vm.parser._last_token)
    return origin if origin is not None else _SYNTHETIC_ORIGIN


def _validate_related(value: Any) -> List[Tuple[str, Optional[str], SourceOrigin]]:
    if not isinstance(value, list):
        raise ParseError(f"diagnostic-new: related must be a list, got {_ct_type_name(value)}", code="ct-argument-type")
    records: List[Tuple[str, Optional[str], SourceOrigin]] = []
    for index, item in enumerate(value):
        if not isinstance(item, Mapping):
            raise ParseError(f"diagnostic-new: related record {index} must be a map, got {_ct_type_name(item)}",
                             code="ct-argument-type")
        extra = [key for key in item if key not in _RELATED_KEYS]
        if extra:
            raise ParseError(f"diagnostic-new: related record {index} has unknown key {extra[0]!r}",
                             code="ct-argument-invalid")
        kind = item.get("kind")
        if not isinstance(kind, str) or kind == "":
            raise ParseError(f"diagnostic-new: related record {index} needs a non-empty string 'kind'",
                             code="ct-argument-invalid")
        message = item.get("message") if "message" in item else None
        if "message" in item and not isinstance(message, str):
            raise ParseError(f"diagnostic-new: related record {index} 'message' must be a string",
                             code="ct-argument-type")
        origin = item.get("origin")
        if not isinstance(origin, SourceOrigin):
            raise ParseError(f"diagnostic-new: related record {index} needs a SourceOrigin 'origin'",
                             code="ct-argument-invalid")
        records.append((kind, message, origin))
    return records


def _ct_diagnostic_new(vm: CompileTimeVM) -> None:
    related_value = vm._resolve_handle(vm.pop())
    primary = vm._resolve_handle(vm.pop())
    message = vm._resolve_handle(vm.pop())
    phase = vm._resolve_handle(vm.pop())
    category = vm._resolve_handle(vm.pop())
    code = vm._resolve_handle(vm.pop())
    severity = vm._resolve_handle(vm.pop())
    if severity not in _DIAGNOSTIC_SEVERITIES:
        raise ParseError(f"diagnostic-new: severity must be error, warning, or note, got {severity!r}",
                         code="ct-argument-invalid")
    if not isinstance(code, str) or code == "":
        raise ParseError("diagnostic-new: code must be a non-empty string", code="ct-argument-invalid")
    if severity == "error":
        if not isinstance(category, str) or _DIAGNOSTIC_CATEGORY_RE.match(category) is None:
            raise ParseError(f"diagnostic-new: an error needs a lowercase snake_case category, got {category!r}",
                             code="ct-argument-invalid")
    elif category is not None:
        raise ParseError(f"diagnostic-new: a {severity} must have category nil", code="ct-argument-invalid")
    if phase is not None and (not isinstance(phase, str) or phase == ""):
        raise ParseError("diagnostic-new: phase must be a non-empty string or nil", code="ct-argument-invalid")
    if not isinstance(message, str):
        raise ParseError(f"diagnostic-new: message must be a string, got {_ct_type_name(message)}",
                         code="ct-argument-type")
    if not isinstance(primary, SourceOrigin):
        raise ParseError(f"diagnostic-new: primary must be a SourceOrigin, got {_ct_type_name(primary)}",
                         code="ct-argument-type")
    related = _validate_related(related_value)
    vm.push(Diagnostic(severity, message, code=code, category=category, phase=phase, primary=primary,
                       related=related))


def _ct_diagnostic_accessor(field: str, word: str) -> Callable[[CompileTimeVM], None]:
    def accessor(vm: CompileTimeVM) -> None:
        vm.push(getattr(_ct_pop_diagnostic(vm, word), field))
    accessor.__name__ = f"_ct_{word.replace('-', '_')}"
    return accessor


_CT_DIAGNOSTIC_ACCESSORS = (
    ("diagnostic-severity", "severity"),
    ("diagnostic-code", "code"),
    ("diagnostic-category", "category"),
    ("diagnostic-phase", "phase"),
    ("diagnostic-message", "message"),
    ("diagnostic-primary", "primary"),
)


def _ct_diagnostic_related(vm: CompileTimeVM) -> None:
    diag = _ct_pop_diagnostic(vm, "diagnostic-related")
    vm.push([_diagnostic_related_map(record) for record in diag.related])


def _ct_diagnostic_raise(vm: CompileTimeVM) -> None:
    diag = _ct_pop_diagnostic(vm, "ct-diagnostic-raise")
    if diag.severity != "error":
        raise ParseError(f"ct-diagnostic-raise accepts only error Diagnostics, got a {diag.severity}; "
                         "use ct-diagnostic-warning or ct-diagnostic-note", code="ct-argument-invalid")
    raise ParseError(diag.message, diagnostic=diag)


def _ct_diagnostic_list(vm: CompileTimeVM) -> None:
    vm.push([_diagnostic_to_map(diag) for diag in vm.parser.diagnostics])


def _ct_user_input_origin(vm: CompileTimeVM) -> Optional[SourceOrigin]:
    """The parser's current input position (the last consumed token,
    else the next one), i.e. the user code a library is processing."""
    parser = vm.parser
    origin = parser._token_origin(parser._last_token)
    if origin is None:
        origin = parser._token_origin(parser.peek_token())
    return origin


def _ct_user_error(vm: CompileTimeVM, message: str, code: str,
                   primary: Optional[SourceOrigin] = None) -> ParseError:
    """An error located at user input, with the raising CT code as a
    related 'raised by' record."""
    call_site = _ct_call_site_origin(vm)
    if primary is None:
        primary = _ct_user_input_origin(vm)
    if primary is None:
        return ParseError(message, code=code, origin=call_site)
    related = []
    if call_site is not _SYNTHETIC_ORIGIN and (call_site.path, call_site.start) != (primary.path, primary.start):
        related.append(("raised-by", "raised by compile-time code at", call_site))
    return ParseError(message, code=code, origin=primary, related=related)


def _ct_line_column_origin(vm: CompileTimeVM, word: str, line: Any, column: Any) -> SourceOrigin:
    """An origin at 1-based (line, column) in the file of the current user
    input, spanning the word that starts there."""
    if type(line) is not int or type(column) is not int:
        raise ParseError(f"{word}: line and column must be integers, got {_ct_type_name(line)} and "
                         f"{_ct_type_name(column)}", code="ct-argument-type")
    if line < 1 or column < 1:
        raise ParseError(f"{word}: line and column are 1-based, got {line}:{column}", code="ct-argument-invalid")
    anchor = _ct_user_input_origin(vm)
    if anchor is None:
        raise ParseError(f"{word}: no current source file to locate {line}:{column} in", code="ct-argument-invalid")
    lines = _preview_file_lines(anchor.path)
    if line > len(lines) or column > len(lines[line - 1]) + 1:
        raise ParseError(f"{word}: {line}:{column} is outside {anchor.path}", code="ct-argument-invalid")
    text = lines[line - 1]
    offset = sum(len(item) + 1 for item in lines[:line - 1]) + column - 1
    width = 0
    while column - 1 + width < len(text) and not text[column - 1 + width].isspace():
        width += 1
    width = max(width, 1)
    return SourceOrigin(anchor.path, offset, offset + width, line, column, line, column + width)


def _ct_diagnostic_error(vm: CompileTimeVM) -> None:
    message = _ct_pop_string(vm, "ct-diagnostic-error")
    raise _ct_user_error(vm, message, "ct-diagnostic-raised")


def _ct_diagnostic_error_at(vm: CompileTimeVM) -> None:
    column = vm._resolve_handle(vm.pop())
    line = vm._resolve_handle(vm.pop())
    message = _ct_pop_string(vm, "ct-diagnostic-error-at")
    origin = _ct_line_column_origin(vm, "ct-diagnostic-error-at", line, column)
    raise _ct_user_error(vm, message, "ct-diagnostic-raised", origin)


def _ct_diagnostic_record_nonerror(vm: CompileTimeVM, word: str, severity: str, code: str) -> None:
    message = _ct_pop_string(vm, word)
    diag = Diagnostic(severity, message, code=code, phase="ct-diagnostic", primary=_ct_call_site_origin(vm))
    vm.parser._record_diagnostic_obj(diag)


def _ct_diagnostic_warning(vm: CompileTimeVM) -> None:
    _ct_diagnostic_record_nonerror(vm, "ct-diagnostic-warning", "warning", "ct-warning-raised")


def _ct_diagnostic_note(vm: CompileTimeVM) -> None:
    _ct_diagnostic_record_nonerror(vm, "ct-diagnostic-note", "note", "ct-note-raised")



def _ct_parse_error(vm: CompileTimeVM) -> None:
    message = vm.pop_str()
    raise _ct_user_error(vm, message, "ct-parser-error-raised")


def _ct_parse_error_at(vm: CompileTimeVM) -> None:
    column = vm._resolve_handle(vm.pop())
    line = vm._resolve_handle(vm.pop())
    message = vm.pop_str()
    origin = _ct_line_column_origin(vm, "ct-parser-error-at", line, column)
    raise _ct_user_error(vm, message, "ct-parser-error-raised", origin)


def _ct_static_assert(vm: CompileTimeVM) -> None:
    """condition -- : a boolean, or an integer (nonzero passes)."""
    condition = vm._resolve_handle(vm.pop())
    if not isinstance(condition, int):
        raise ParseError(f"static-assert expects a boolean or integer condition, got {_ct_type_name(condition)}",
                         code="ct-argument-type")
    if not condition:
        origin = _ct_call_site_origin(vm)
        where = f" at {origin.path}:{origin.start_line}:{origin.start_column}" if origin is not _SYNTHETIC_ORIGIN else ""
        raise ParseError(f"static assertion failed{where}", code="static-assertion-failed", origin=origin)


# ---------------------------------------------------------------------------
# § 16. Runtime intrinsics for --ct-run-main
# ---------------------------------------------------------------------------

def _rt_exit(vm: CompileTimeVM) -> None:
    code = vm.pop_int()
    raise _CTVMExit(code)


def _rt_drop(vm: CompileTimeVM) -> None:
    # Runtime asm `drop` has no bounds check and can move r12 above dstack_top.
    # In ct-run-main/script keep behavior deterministic by treating empty-drop as no-op.
    if vm.r12 < vm._native_data_top:
        vm.r12 += 8


def _rt_resolve_word_pointer(vm: CompileTimeVM, value: Any) -> Word:
    resolved = vm._resolve_handle(value)
    if isinstance(resolved, Word):
        return resolved
    if isinstance(resolved, int):
        mapped = vm._handles.objects.get(resolved)
        if isinstance(mapped, Word):
            return mapped
    raise ParseError(
        f"expected word pointer on runtime stack, got {type(resolved).__name__}: {resolved!r}",
        code="ct-runtime-call-invalid",
    )


def _rt_catch_runtime_error(vm: CompileTimeVM) -> None:
    """Execute a callback in a forked child and push signal/errno style result."""
    target_word = _rt_resolve_word_pointer(vm, vm.pop())

    try:
        pid = os.fork()
    except OSError as exc:
        vm.push(-int(exc.errno or 1))
        return

    if pid == 0:
        try:
            vm._in_fork_child = True
            vm._call_word(target_word)
            os._exit(0)
        except _CTVMExit as exc:
            os._exit(int(getattr(exc, "code", 0)) & 0xFF)
        except BaseException:
            os._exit(1)

    while True:
        try:
            _wait_pid, status = os.waitpid(pid, 0)
            break
        except OSError as exc:
            if exc.errno == errno.EINTR:
                continue
            vm.push(-int(exc.errno or 1))
            return

    if os.WIFSIGNALED(status):
        vm.push(int(os.WTERMSIG(status)))
        return
    if os.WIFEXITED(status):
        vm.push(0)
        return
    vm.push(-1)


def _rt_try(vm: CompileTimeVM) -> None:
    _rt_catch_runtime_error(vm)
    signal = int(vm.pop())
    vm.push(1 if signal == 0 else 0)


def _rt_try_with_error(vm: CompileTimeVM) -> None:
    _rt_catch_runtime_error(vm)
    signal = int(vm.pop())
    vm.push(signal)
    vm.push(1 if signal == 0 else 0)


def _rt_jmp(vm: CompileTimeVM) -> None:
    target = vm.pop()
    resolved = vm._resolve_handle(target)
    if isinstance(resolved, Word):
        vm._call_word(resolved)
        raise _CTVMReturn()
    if isinstance(resolved, bool):
        raise _CTVMJump(int(resolved))
    if not isinstance(resolved, int):
        raise ParseError(
            f"jmp expects an address or word pointer, got {type(resolved).__name__}: {resolved!r}",
            code="ct-runtime-call-invalid",
        )
    raise _CTVMJump(resolved)


def _rt_call(vm: CompileTimeVM) -> None:
    target = vm.pop()
    resolved = vm._resolve_handle(target)
    if isinstance(resolved, Word):
        vm._call_word(resolved)
        return
    if isinstance(resolved, int):
        # Native pointers returned by libl2 factories use the L2
        # runtime ABI (r12 register as data-stack pointer).  Dispatch
        # them through l2_invoke_trampoline so the pointed-to native
        # code sees the CT VM's r12 in the actual r12 register.
        libl2_set = getattr(vm, "_libl2_trampolines", None)
        if libl2_set is not None and resolved in libl2_set:
            bridge = vm._libl2_invoke_bridge()
            vm.r12 = int(bridge(resolved, int(vm.r12)))
            return
        if not vm.runtime_mode:
            raise ParseError("calling a raw address is only supported in runtime mode", code="ct-runtime-call-invalid")
        # Ensure we have JIT resources
        vm._ensure_jit_out()
        if CompileTimeVM._JIT_FUNC_TYPE is None:
            CompileTimeVM._JIT_FUNC_TYPE = ctypes.CFUNCTYPE(None, ctypes.c_int64, ctypes.c_int64, ctypes.c_void_p)
        jf = CompileTimeVM._JIT_FUNC_TYPE(resolved)
        out = vm._jit_out2
        jf(vm.r12, vm.r13, vm._jit_out2_addr)
        vm.r12 = out[0]
        vm.r13 = out[1]
        return
    raise ParseError(
        f"call expects an address or word pointer, got {type(resolved).__name__}: {resolved!r}",
        code="ct-runtime-call-invalid",
    )


def _rt_mmap(vm: CompileTimeVM) -> None:
    """Runtime intrinsic for mmap wrapper word used by stdlib alloc paths.

    Mirrors the asm `mmap` word stack protocol exactly:
    [*, addr, len, prot, flags, fd | offset] -> [*, addr | result]
    """
    offset = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    fd = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    flags = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    prot = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    length = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    addr_hint = CTMemory.read_qword(vm.r12)

    result = _ct_linux_syscall(9, addr_hint, length, prot, flags, fd, offset)

    vm.r12 -= 8
    CTMemory.write_qword(vm.r12, result)
    if _wrap_i64(result) >= 0 and length > 0:
        vm._owned_maps[result & _I64_MASK_] = length
    vm._track_syscall_mmap(addr=result, length=length, result=result)


def _rt_munmap(vm: CompileTimeVM) -> None:
    """Runtime intrinsic for munmap wrapper word used by stdlib free paths.

    Mirrors the asm `munmap` word stack protocol exactly:
    [*, addr | len] -> [* | res]
    """
    length = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    addr = CTMemory.read_qword(vm.r12)
    vm.r12 += 8

    # The program runs inside the compiler process: it may only unmap memory
    # it mapped itself.  Anything else (an address heuristic misjudging the
    # compiler's own memory, for example) gets -EINVAL instead of unmapping
    # the compiler's heap.
    if vm._owns_mapping(addr, length):
        result = _ct_linux_syscall(11, addr, length)
        if _wrap_i64(result) == 0:
            vm._release_mapping(addr, length)
    else:
        result = -22

    vm.r12 -= 8
    CTMemory.write_qword(vm.r12, result)
    vm._track_syscall_munmap(addr=addr, length=length, result=result)


def _rt_mremap(vm: CompileTimeVM) -> None:
    """Runtime intrinsic for mremap wrapper word used by stdlib realloc paths.

    Mirrors the asm `mremap` word stack protocol exactly:
    [*, old_addr, old_size, new_size | flags] -> [* | new_addr]
    """
    flags = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    new_size = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    old_size = CTMemory.read_qword(vm.r12)
    vm.r12 += 8
    old_addr = CTMemory.read_qword(vm.r12)
    vm.r12 += 8

    if vm._owns_mapping(old_addr, old_size):
        result = _ct_linux_syscall(25, old_addr, old_size, new_size, flags)
        if _wrap_i64(result) >= 0:
            vm._release_mapping(old_addr, old_size)
            vm._owned_maps[result & _I64_MASK_] = new_size
    else:
        result = -22

    vm.r12 -= 8
    CTMemory.write_qword(vm.r12, result)
    vm._track_syscall_mremap(old_addr=old_addr, old_size=old_size, new_size=new_size, result=result)


def _rt_syscall(vm: CompileTimeVM) -> None:
    """Execute a real Linux syscall via a JIT stub, intercepting exit/exit_group."""
    # Lazily compile the syscall JIT stub
    stub = vm._jit_cache.get("__syscall_stub")
    if stub is None:
        stub = _compile_syscall_stub(vm)
        vm._jit_cache["__syscall_stub"] = stub

    # out layout:
    #   [0] final r12, [1] final r13,
    #   [2] exit flag (0=normal, 1=exit), [3] exit code,
    #   [4] syscall nr, [5] arg0, [6] arg1, [7] arg2, [8] arg3,
    #   [9] result (rax)
    out = vm._jit_out4
    stub(vm.r12, vm.r13, vm._jit_out4_addr)
    vm.r12 = out[0]
    vm.r13 = out[1]
    if out[4] == 9:
        vm._track_syscall_mmap(addr=out[9], length=out[6], result=out[9])
    elif out[4] == 11:
        vm._track_syscall_munmap(addr=out[5], length=out[6], result=out[9])
    elif out[4] == 25:
        vm._track_syscall_mremap(old_addr=out[5], old_size=out[6], new_size=out[7], result=out[9])
    if out[2] == 1:
        raise _CTVMExit(out[3])


def _compile_syscall_stub(vm: CompileTimeVM) -> Any:
    """JIT-compile a native syscall stub that intercepts exit/exit_group."""

    # The stub uses the same wrapper convention as _compile_jit:
    #   rdi = r12 (data stack ptr), rsi = r13 (return stack ptr), rdx = output ptr
    # Output struct:
    #   [r12, r13, exit_flag, exit_code, syscall_nr, arg0, arg1, arg2, arg3, result]
    #
    # Stack protocol (matching _emit_syscall_intrinsic):
    #   TOS:   syscall number -> rax
    #   TOS-1: arg count -> rcx
    #   then args on stack as ... arg0 arg1 ... argN (argN is top)
    #

    lines = [
        "_stub_entry:",
        "    push rbx",
        "    push r12",
        "    push r13",
        "    push r14",
        "    sub rsp, 24",
        "    mov [rsp], rdx",        # save output-struct pointer
        "    mov r12, rdi",          # data stack
        "    mov r13, rsi",          # return stack
        # Pop syscall number
        "    mov rax, [r12]",
        "    add r12, 8",
        "    mov r14, rax",          # keep syscall nr for reporting
        # Pop arg count
        "    mov rcx, [r12]",
        "    add r12, 8",
        # Clamp to [0,6]
        "    cmp rcx, 0",
        "    jge _count_nonneg",
        "    xor rcx, rcx",
        "_count_nonneg:",
        "    cmp rcx, 6",
        "    jle _count_clamped",
        "    mov rcx, 6",
        "_count_clamped:",
        # Check for exit (60) / exit_group (231)
        "    cmp rax, 60",
        "    je _do_exit",
        "    cmp rax, 231",
        "    je _do_exit",
        # Clear syscall arg registers
        "    xor rdi, rdi",
        "    xor rsi, rsi",
        "    xor rdx, rdx",
        "    xor r10, r10",
        "    xor r8, r8",
        "    xor r9, r9",
        # Pop args in the same order as _emit_syscall_intrinsic
        "    cmp rcx, 6",
        "    jl _skip_r9",
        "    mov r9, [r12]",
        "    add r12, 8",
        "_skip_r9:",
        "    cmp rcx, 5",
        "    jl _skip_r8",
        "    mov r8, [r12]",
        "    add r12, 8",
        "_skip_r8:",
        "    cmp rcx, 4",
        "    jl _skip_r10",
        "    mov r10, [r12]",
        "    add r12, 8",
        "_skip_r10:",
        "    cmp rcx, 3",
        "    jl _skip_rdx",
        "    mov rdx, [r12]",
        "    add r12, 8",
        "_skip_rdx:",
        "    cmp rcx, 2",
        "    jl _skip_rsi",
        "    mov rsi, [r12]",
        "    add r12, 8",
        "_skip_rsi:",
        "    cmp rcx, 1",
        "    jl _skip_rdi",
        "    mov rdi, [r12]",
        "    add r12, 8",
        "_skip_rdi:",
        "    syscall",
        "    mov rbx, rax",          # preserve result before writing output
        # Push result
        "    sub r12, 8",
        "    mov [r12], rax",
        # Normal return: flag=0
        "    mov rax, [rsp]",        # output-struct pointer
        "    mov qword [rax], r12",
        "    mov qword [rax+8], r13",
        "    mov qword [rax+16], 0", # exit_flag = 0
        "    mov qword [rax+24], 0", # exit_code = 0
        "    mov qword [rax+32], r14", # syscall_nr
        "    mov qword [rax+40], rdi", # arg0
        "    mov qword [rax+48], rsi", # arg1
        "    mov qword [rax+56], rdx", # arg2
        "    mov qword [rax+64], r10", # arg3
        "    mov qword [rax+72], rbx", # result
        "    jmp _stub_epilogue",
        # Exit path: don't actually call syscall, just report it
        "_do_exit:",
        "    xor rbx, rbx",
        "    cmp rcx, 1",
        "    jl _exit_code_ready",
        "    mov rbx, [r12]",        # arg0 = exit code (for exit/exit_group)
        "    add r12, 8",
        "_exit_code_ready:",
        "    mov rax, [rsp]",        # output-struct pointer
        "    mov qword [rax], r12",
        "    mov qword [rax+8], r13",
        "    mov qword [rax+16], 1", # exit_flag = 1
        "    mov [rax+24], rbx",     # exit_code
        "    mov qword [rax+32], r14", # syscall_nr
        "    mov qword [rax+40], rbx", # arg0 (exit code)
        "    mov qword [rax+48], 0",   # arg1
        "    mov qword [rax+56], 0",   # arg2
        "    mov qword [rax+64], 0",   # arg3
        "    mov qword [rax+72], 0",   # result
        "_stub_epilogue:",
        "    add rsp, 24",
        "    pop r14",
        "    pop r13",
        "    pop r12",
        "    pop rbx",
        "    ret",
    ]

    def _norm(l: str) -> str:
        l = l.split(";", 1)[0].rstrip()
        for sz in ("qword", "dword", "word", "byte"):
            l = l.replace(f"{sz} [", f"{sz} ptr [")
        return l
    normalized = [_norm(l) for l in lines if _norm(l).strip()]

    try:
        code = _x86_assemble("\n".join(normalized))
    except KsError as exc:
        debug_txt = "\n".join(normalized)
        raise ParseError(f"JIT syscall stub assembly failed: {exc}\n--- asm ---\n{debug_txt}\n--- end ---", code="ct-jit-failed") from exc
    if code is None:
        raise ParseError("keystone-engine is required for JIT syscall execution", code="ct-jit-failed")
    if not code:
        raise ParseError("JIT syscall stub produced no code", code="ct-jit-failed")

    page_size = max(len(code), 4096)
    _libc = ctypes.CDLL(None, use_errno=True)
    _libc.mmap.restype = ctypes.c_void_p
    _libc.mmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int,
                            ctypes.c_int, ctypes.c_int, ctypes.c_long]
    PROT_RWX = 0x1 | 0x2 | 0x4
    MAP_PRIVATE = 0x02
    MAP_ANONYMOUS = 0x20
    ptr = _libc.mmap(None, page_size, PROT_RWX, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)
    if ptr == ctypes.c_void_p(-1).value or ptr is None:
        raise RuntimeError("mmap failed for JIT syscall stub")
    ctypes.memmove(ptr, code, len(code))
    vm._jit_code_pages.append((ptr, page_size))
    # Same signature: (r12, r13, out_ptr) -> void
    if CompileTimeVM._JIT_FUNC_TYPE is None:
        CompileTimeVM._JIT_FUNC_TYPE = ctypes.CFUNCTYPE(None, ctypes.c_int64, ctypes.c_int64, ctypes.c_void_p)
    func = CompileTimeVM._JIT_FUNC_TYPE(ptr)
    return func


def _register_runtime_intrinsics(dictionary: Dictionary) -> None:
    """Register runtime intrinsics only for words that cannot run as native JIT.

    Most :asm words now run as native JIT-compiled machine code on real
    memory stacks.  Only a handful need Python-level interception:
      - exit    : must not actually call sys_exit (would kill the compiler)
      - jmp     : needs interpreter-level IP manipulation
    - mmap    : tracked in CTVM for leak-check mode
    - munmap  : tracked in CTVM for leak-check mode
    - mremap  : tracked in CTVM for leak-check mode
      - syscall : the ``syscall`` word is compiler-generated (no asm body);
                  intercept to block sys_exit and handle safely
    Note: get_addr is handled inline in _execute_nodes before _call_word.
    """
    _RT_MAP: Dict[str, Callable[[CompileTimeVM], None]] = {
        "exit": _rt_exit,
        "drop": _rt_drop,
        "jmp": _rt_jmp,
        "call": _rt_call,
        "catch_runtime_error": _rt_catch_runtime_error,
        "try": _rt_try,
        "try_with_error": _rt_try_with_error,
        "mmap": _rt_mmap,
        "munmap": _rt_munmap,
        "mremap": _rt_mremap,
        "syscall": _rt_syscall,
    }
    for name, func in _RT_MAP.items():
        dictionary.set_baseline_handler(name, "runtime_intrinsic", func)


