# § 17. Bootstrap dictionary (registers every CT word)
# ---------------------------------------------------------------------------

def bootstrap_dictionary() -> Dictionary:
    dictionary = Dictionary()
    dictionary.register_baseline(Word(name="immediate", immediate=True, macro=macro_immediate))
    dictionary.register_baseline(Word(name="compile-only", immediate=True, macro=macro_compile_only))
    dictionary.register_baseline(Word(name="runtime", immediate=True, macro=macro_runtime))
    dictionary.register_baseline(Word(name="runtime-only", immediate=True, macro=macro_runtime))
    dictionary.register_baseline(Word(name="inline", immediate=True, macro=macro_inline))
    dictionary.register_baseline(Word(name="preserve", immediate=True, macro=macro_preserve))
    dictionary.register_baseline(Word(name="on-event", immediate=True, macro=macro_on_event))
    dictionary.register_baseline(Word(name="emit-event", immediate=True, macro=macro_emit_event))
    dictionary.register_baseline(Word(name="label", immediate=True, macro=macro_label))
    dictionary.register_baseline(Word(name="goto", immediate=True, macro=macro_goto))
    dictionary.register_baseline(Word(name="compile-time", immediate=True, macro=macro_compile_time))
    dictionary.register_baseline(Word(name="here", immediate=True, macro=macro_here))
    dictionary.register_baseline(Word(name="with", immediate=True, macro=macro_with))
    dictionary.register_baseline(Word(name="macro", immediate=True, macro=macro_begin_definition))
    dictionary.register_baseline(Word(name="struct", immediate=True, macro=macro_struct_begin))
    dictionary.register_baseline(Word(name="cstruct", immediate=True, macro=macro_cstruct_begin))
    ct_word = Word(name="CT")
    ct_word.intrinsic = _emit_ct_runtime_flag
    ct_word.compile_time_intrinsic = _ct_push_compile_time_flag
    ct_word.runtime_intrinsic = _ct_push_compile_time_flag
    dictionary.register_baseline(ct_word)
    _register_compile_time_primitives(dictionary)
    _register_runtime_intrinsics(dictionary)
    return dictionary


