class FileSpan:
    __slots__ = ('path', 'start_line', 'end_line', 'local_start_line')

    def __init__(self, path: Path, start_line: int, end_line: int, local_start_line: int) -> None:
        self.path = path
        self.start_line = start_line
        self.end_line = end_line
        self.local_start_line = local_start_line


class FrontendSpec:
    """A selected custom frontend: canonical implementation path, entry-point
    word name, and the call site (the frontend header, or the import that
    made a file inherit the frontend)."""

    __slots__ = ('impl_path', 'entry', 'call_site')

    def __init__(self, impl_path: Path, entry: str, call_site: SourceOrigin) -> None:
        self.impl_path = impl_path
        self.entry = entry
        self.call_site = call_site


# The compiler's own directory: its stdlib is always importable, after the
# working directory and -I paths (so local files can still shadow it).
_INSTALL_DIR = Path(__file__).resolve().parent


def _default_include_paths(extra: Sequence[Path] = ()) -> List[Path]:
    return [Path("."), Path("./stdlib"), *extra, _INSTALL_DIR, _INSTALL_DIR / "stdlib"]


class SourceUnit:
    """One source file ready for parsing.  A default-frontend unit holds its
    preprocessed text, the FileSpans mapping that text back to the file, and
    its import directives (flat line -> target and target columns).  A
    custom-frontend unit holds the exact original text and its frontend."""

    __slots__ = ('path', 'text', 'spans', 'imports', 'frontend', 'explicit_frontend')

    def __init__(self, path: Path, text: str, spans: List[FileSpan], imports: Dict[int, Tuple[str, int, int]],
                 frontend: Optional[FrontendSpec], *, explicit_frontend: bool = False) -> None:
        self.path = path
        self.text = text
        self.spans = spans
        self.imports = imports
        self.frontend = frontend
        self.explicit_frontend = explicit_frontend


DEFAULT_FRONTEND_ENTRY = "frontend-parse"
# Internal lexeme of the token that makes the parser run a custom frontend.
# It contains a NUL, so source text cannot spell it as a word.
_FRONTEND_UNIT_LEXEME = "\x00l2-frontend-unit"


def _frontend_header_error(message: str, origin: SourceOrigin) -> ParseError:
    return ParseError(message, code="frontend-header-invalid", origin=origin)


def _detect_frontend_header(text: str, path: str) -> Optional[Tuple[str, str, SourceOrigin]]:
    """Return (implementation path, entry name, header SourceOrigin) when the
    first nonblank line is a frontend header, else None.  Grammar:
    `frontend STRING [IDENTIFIER]` with an optional trailing # comment."""
    if not text.lstrip(_L2_WHITESPACE).startswith("frontend"):
        return None  # fast exit: most files have no header
    starts = _spec_line_starts(text)
    length = len(text)
    for index, start in enumerate(starts):
        end = starts[index + 1] if index + 1 < len(starts) else length
        line = text[start:end]
        stripped = line.strip(_L2_WHITESPACE)
        if not stripped:
            continue
        if not stripped.startswith("frontend"):
            return None
        after = stripped[len("frontend"):len("frontend") + 1]
        if after and after not in _L2_WHITESPACE_SET and after not in '"#':
            return None  # a word such as `frontends`
        body = line.rstrip("\r\n")
        file_text = _SourceFileText(text)

        def origin(lo: int, hi: int) -> SourceOrigin:
            start_line, start_column = file_text.line_column(lo)
            end_line, end_column = file_text.line_column(hi)
            return SourceOrigin(path, lo, hi, start_line, start_column, end_line, end_column)

        header_origin = origin(start, start + len(body))
        try:
            tokens = Reader().tokenize_text(body, path)
        except ParseError as exc:
            raise _frontend_header_error(f"malformed frontend header ({exc})", header_origin) from exc
        lexemes = [tok.lexeme for tok in tokens]
        if len(tokens) < 2 or len(tokens) > 3:
            raise _frontend_header_error("expected: frontend \"path\" [entry]", header_origin)
        try:
            impl = _parse_string_literal(tokens[1])
        except ParseError as exc:
            raise _frontend_header_error(f"invalid frontend path ({exc})", header_origin) from exc
        if impl is None or impl == "":
            raise _frontend_header_error(f"frontend path must be a non-empty string literal, got {lexemes[1]}",
                                         header_origin)
        entry = DEFAULT_FRONTEND_ENTRY
        if len(tokens) == 3:
            entry = tokens[2].lexeme
            # One word name: identifier start, then any word characters
            # (L2 names such as frontend-parse contain hyphens).
            if not _is_l2_identifier(entry[0]) or entry[0] in "`\\":
                raise _frontend_header_error(f"frontend entry must be an identifier, got {entry!r}", header_origin)
        return impl, entry, header_origin
    return None


def _directive_target_columns(lstripped: str, keyword: str) -> Tuple[int, int]:
    """Column range of the target in `keyword <target> ...` (quotes included
    for a quoted target), relative to the left-stripped line."""
    pos = len(keyword)
    while pos < len(lstripped) and lstripped[pos].isspace():
        pos += 1
    start = pos
    if pos < len(lstripped) and lstripped[pos] == '"':
        close = lstripped.find('"', pos + 1)
        return start, (close + 1 if close != -1 else len(lstripped))
    while pos < len(lstripped) and not lstripped[pos].isspace():
        pos += 1
    return start, pos


def _l2_string_literal(value: str) -> str:
    """Spell `value` as an L2 string literal lexeme."""
    escaped = (value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
               .replace("\t", "\\t").replace("\r", "\\r").replace("\0", "\\0"))
    return f'"{escaped}"'


# Uppercase macro prefixes to strip (API export macros like RLAPI, WINGDIAPI, etc.)
# Keep common uppercase type names.
_C_HEADER_KEEP_UPPER = frozenset({"FILE", "DIR", "EOF", "NULL", "BOOL"})


def _parse_c_header_externs(header_text: str) -> List[str]:
    """Extract function declarations from a C header and return L2 ``extern`` lines."""
    text = re.sub(r"/\*.*?\*/", " ", header_text, flags=re.DOTALL)
    text = re.sub(r"//[^\n]*", "", text)
    text = re.sub(r"^\s*#[^\n]*$", "", text, flags=re.MULTILINE)
    text = text.replace("\\\n", " ")
    # Collapse whitespace (including newlines) so multi-line declarations become single-line
    text = re.sub(r"\s+", " ", text)
    # Strip __attribute__((...)), __nonnull((...)), __THROW, __wur, and similar GCC extensions
    text = re.sub(r"__\w+\s*\(\([^)]*\)\)", "", text)
    text = re.sub(r"__\w+", "", text)
    # Remove __restrict
    text = text.replace("__restrict", "")

    # Match function declarations: <tokens> <name>(<params>);
    _RE = re.compile(
        r"([\w][\w\s*]+?)"           # return type tokens + function name
        r"\s*\(([^)]*?)\)"           # parameter list
        r"\s*;"
    )

    results: List[str] = []
    for m in _RE.finditer(text):
        prefix = m.group(1).strip()
        params_raw = m.group(2).strip()

        if "..." in params_raw:
            # Variadic function: strip the ... from parameter list, keep fixed args
            params_fixed = re.sub(r",?\s*\.\.\.", "", params_raw).strip()
            param_str = "void" if params_fixed in ("void", "") else params_fixed
            is_variadic = True
        else:
            is_variadic = False

        tokens = prefix.split()
        if len(tokens) < 2:
            continue

        # Last token is function name (may have leading * for pointer-returning functions)
        func_name = tokens[-1].lstrip("*")
        if not func_name or not re.match(r"^[A-Za-z_]\w*$", func_name):
            continue

        # Skip typedef (struct/enum/union return types are fine — the regex
        # already ensures this matched a function declaration with parentheses)
        if tokens[0] in ("typedef",):
            continue

        # Build return type: strip API macros and calling-convention qualifiers
        type_tokens = tokens[:-1]
        cleaned: List[str] = []
        for t in type_tokens:
            if t in ("extern", "static", "inline"):
                continue
            # Strip uppercase macro prefixes (3+ chars, all caps) unless known type
            if re.match(r"^[A-Z_][A-Z_0-9]{2,}$", t) and t not in _C_HEADER_KEEP_UPPER:
                continue
            cleaned.append(t)

        # Pointer stars attached to the function name belong to the return type
        leading_stars = len(tokens[-1]) - len(tokens[-1].lstrip("*"))
        ret_type = " ".join(cleaned)
        if leading_stars:
            ret_type += " " + "*" * leading_stars
        ret_type = ret_type.strip()
        if not ret_type:
            ret_type = "int"

        if not is_variadic:
            param_str = "void" if params_raw in ("void", "") else params_raw

        va_suffix = ", ..." if is_variadic else ""
        results.append(f"extern {ret_type} {func_name}({param_str}{va_suffix})")
    return results


# Map C types to L2 cstruct field types
_C_TO_L2_FIELD_TYPE: Dict[str, str] = {
    "char": "i8", "signed char": "i8", "unsigned char": "u8",
    "short": "i16", "unsigned short": "u16", "short int": "i16",
    "int": "i32", "unsigned int": "u32", "unsigned": "u32",
    "long": "i64", "unsigned long": "u64", "long int": "i64",
    "long long": "i64", "unsigned long long": "u64",
    "float": "f32", "double": "f64",
    "size_t": "u64", "ssize_t": "i64",
    "int8_t": "i8", "uint8_t": "u8",
    "int16_t": "i16", "uint16_t": "u16",
    "int32_t": "i32", "uint32_t": "u32",
    "int64_t": "i64", "uint64_t": "u64",
}


def _parse_c_header_structs(header_text: str) -> List[str]:
    """Extract struct definitions from C header text and return L2 ``cstruct`` lines."""
    text = re.sub(r"/\*.*?\*/", " ", header_text, flags=re.DOTALL)
    text = re.sub(r"//[^\n]*", "", text)
    text = re.sub(r"#[^\n]*", "", text)
    text = re.sub(r"\s+", " ", text)

    results: List[str] = []
    # Match: struct Name { fields }; or typedef struct Name { fields } Alias;
    # or typedef struct { fields } Name;
    _RE_STRUCT = re.compile(
        r"(?:typedef\s+)?struct\s*(\w*)\s*\{([^}]*)\}\s*(\w*)\s*;",
    )
    for m in _RE_STRUCT.finditer(text):
        struct_name = m.group(1).strip()
        body = m.group(2).strip()
        typedef_name = m.group(3).strip()
        # Prefer typedef name if present
        name = typedef_name if typedef_name else struct_name
        if not name or name.startswith("_"):
            continue
        fields = _extract_struct_fields(body)
        if not fields:
            continue
        # Generate L2 cstruct declaration
        field_parts = []
        for fname, ftype in fields:
            field_parts.append(f"cfield {fname} {ftype}")
        results.append(f"cstruct {name} {' '.join(field_parts)} end")
    return results


def _extract_struct_fields(body: str) -> List[Tuple[str, str]]:
    """Parse C struct field declarations into (name, l2_type) pairs."""
    fields: List[Tuple[str, str]] = []
    for decl in body.split(";"):
        decl = decl.strip()
        if not decl:
            continue
        # Skip bitfields
        if ":" in decl:
            continue
        # Skip nested struct/union definitions (but allow struct pointers)
        if ("struct " in decl or "union " in decl) and "*" not in decl:
            continue
        tokens = decl.split()
        if len(tokens) < 2:
            continue
        # Last token is field name (may have * prefix for pointers)
        field_name = tokens[-1].lstrip("*")
        if not field_name or not re.match(r"^[A-Za-z_]\w*$", field_name):
            continue
        # Check if pointer
        if "*" in decl:
            fields.append((field_name, "ptr"))
            continue
        # Build type from all tokens except field name
        type_tokens = tokens[:-1]
        # Remove qualifiers
        type_tokens = [t for t in type_tokens if t not in ("const", "volatile", "static",
                                                            "register", "restrict", "_Atomic")]
        ctype = " ".join(type_tokens)
        l2_type = _C_TO_L2_FIELD_TYPE.get(ctype)
        if l2_type is None:
            # Unknown type, treat as pointer-sized
            fields.append((field_name, "ptr"))
        else:
            fields.append((field_name, l2_type))
    return fields


class Compiler:
    def __init__(
        self,
        include_paths: Optional[Sequence[Path]] = None,
        *,
        macro_expansion_limit: int = DEFAULT_MACRO_EXPANSION_LIMIT,
        macro_preview: bool = False,
        defines: Optional[Sequence[str]] = None,
        source_graph_cache: Optional["SourceGraphCache"] = None,
        event_bus: Optional[EventBus] = None,
    ) -> None:
        self.reader = Reader()
        self.event_bus = event_bus
        self.dictionary = bootstrap_dictionary()
        self._syscall_label_counter = 0
        self._register_syscall_words()
        self.parser = Parser(
            self.dictionary,
            self.reader,
            macro_expansion_limit=macro_expansion_limit,
            macro_preview=macro_preview,
            event_bus=event_bus,
        )
        self.parser._compiler_ref = self
        self.assembler = Assembler(self.dictionary, event_bus=event_bus)
        if include_paths is None:
            include_paths = _default_include_paths()
        self.include_paths: List[Path] = [p.expanduser().resolve() for p in include_paths]
        # (importer dir, target, include paths, self name) -> (resolved path,
        # paths tried before it that did not exist, symlinked path or None).
        self._import_resolve_cache: Dict[Tuple[Any, ...], Tuple[Path, Tuple[Path, ...], Optional[str]]] = {}
        # Every path an import looked for and did not find.  A cached build
        # that depends on these is stale once one of them exists (a new file
        # that would shadow an import).
        self._import_absent: Set[Path] = set()
        # Import paths that reach their file through a symlink -> the file
        # they resolved to.  A cached build is stale once one resolves
        # elsewhere (a retargeted link).
        self._import_links: Dict[str, str] = {}
        self._loaded_files: Set[Path] = set()
        self.defines: Set[str] = set(defines or [])
        self._last_loaded_path: Optional[Path] = None
        self._last_loaded_source: Optional[str] = None
        self._last_loaded_spans: Optional[List[FileSpan]] = None
        # Source units of the current graph, keyed by canonical path.
        self._units: Dict[Path, SourceUnit] = {}
        self._root_unit: Optional[SourceUnit] = None
        # Files the parser has loaded in the current parse (import dedup).
        self._parse_seen: Set[Path] = set()
        # Frontend implementations loaded in this compiler invocation.
        self._frontends_loaded: Set[Path] = set()
        # Populated from source-level `flags ...` pragmas while loading files.
        self.source_link_flags: List[str] = []
        self.source_include_paths: List[Path] = []
        self.source_cli_flags: List[str] = []
        self.source_graph_cache = source_graph_cache
        self.last_transformed_source: str = ""
        self._preview_focus_names: Optional[Set[str]] = None
        self._preview_focus_path: Optional[Path] = None
        # Files already parsed by a warm prefix this compiler resumes from.
        self._warm_seen: Optional[Set[Path]] = None
        # The warm prefix's preprocessed stdlib units, and for each one the
        # units it pulls in (itself first, depth-first): reused by _walk_unit.
        self._warm_units: Dict[Path, "SourceUnit"] = {}
        self._warm_unit_closure: Optional[Dict[Path, List[Path]]] = None

    def _reset_source_flag_state(self) -> None:
        self.source_link_flags.clear()
        self.source_include_paths.clear()
        self.source_cli_flags.clear()

    def _publish_compile_error(self, exc: Exception, source: Optional[Path] = None) -> None:
        """Record and publish a compiler error that escaped the parser's own
        dispatch (loader, emission, finalization).  Each error is reported
        once; non-compiler exceptions are internal failures and propagate."""
        if (isinstance(exc, _DiagnosticError) and not getattr(exc, "l2_reported", False)
                and exc.code != "compilation-failed"):  # a summary of errors already reported
            try:
                self.parser._report_unrecoverable_error(exc)
            except ParseError:
                pass  # the abort threshold; the original error is re-raised

    def _preview_focus(self) -> Optional[Set[str]]:
        """Definition names of the root file, for --preview rendering."""
        if self._preview_focus_names is None and self._preview_focus_path is not None:
            self._preview_focus_names = self._collect_preview_focus_names(self._preview_focus_path)
        return self._preview_focus_names

    def _collect_preview_focus_names(self, path: Path) -> Optional[Set[str]]:
        try:
            text = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            return None

        names: Set[str] = set()
        try:
            tokens = self.reader.tokenize(text)
        except Exception:
            return None

        i = 0
        n = len(tokens)
        while i < n:
            lex = tokens[i].lexeme
            if lex in {"word", ":asm", ":py", "macro", "struct", "cstruct"}:
                if i + 1 < n:
                    cand = tokens[i + 1].lexeme
                    if _is_identifier(cand):
                        names.add(cand)
                i += 2
                continue

            if lex == "extern":
                if i + 1 < n and _is_identifier(tokens[i + 1].lexeme):
                    names.add(tokens[i + 1].lexeme)
                elif i + 2 < n and _is_identifier(tokens[i + 2].lexeme):
                    names.add(tokens[i + 2].lexeme)
                i += 1
                continue

            i += 1

        return names or None

    def _load_source_graph(self, path: Path) -> Tuple[str, List[FileSpan]]:
        """Preprocess the root file and the default-frontend files it imports
        into SourceUnits.  Returns the root unit's text and spans; imports are
        loaded by the parser when it reaches them."""
        resolved = path.resolve()
        # Names for --preview output, collected only if a preview is rendered.
        self._preview_focus_path = resolved
        self._preview_focus_names = None
        self._units = {}
        if self.source_graph_cache is not None:
            cached = self.source_graph_cache.load(
                resolved,
                defines=self.defines,
                include_paths=self.include_paths,
            )
            if cached is not None and self._restore_cached_units(resolved, cached):
                return self._root_unit.text, self._root_unit.spans

        unit = self._load_with_imports(resolved)
        self._set_root_unit(resolved, unit)
        cacheable = all(u.frontend is None for u in self._units.values())
        if self.source_graph_cache is not None and cacheable:
            self.source_graph_cache.save(
                resolved,
                defines=self.defines,
                include_paths=self.include_paths,
                loaded_files=self._loaded_files,
                units=list(self._units.values()),
                source_link_flags=self.source_link_flags,
                source_include_paths=self.source_include_paths,
                source_cli_flags=self.source_cli_flags,
                absent=self._import_absent,
                links=self._import_links,
            )
        return unit.text, unit.spans

    def _set_root_unit(self, resolved: Path, unit: "SourceUnit") -> None:
        self._root_unit = unit
        self._last_loaded_path = resolved
        self._last_loaded_source = unit.text
        self._last_loaded_spans = unit.spans

    def _restore_cached_units(self, resolved: Path, cached: dict) -> bool:
        rows = cached.get("units")
        if not isinstance(rows, list):
            return False
        units: Dict[Path, SourceUnit] = {}
        try:
            for row in rows:
                unit_path = Path(row["path"])
                spans = [FileSpan(Path(p), int(a), int(b), int(c)) for p, a, b, c in row["spans"]]
                imports = {int(line): (str(t), int(a), int(b)) for line, (t, a, b) in row["imports"].items()}
                units[unit_path] = SourceUnit(unit_path, str(row["text"]), spans, imports, None)
        except (KeyError, TypeError, ValueError):
            return False
        if resolved not in units:
            return False

        loaded_files: Set[Path] = set()
        raw_files = cached.get("files", [])
        if isinstance(raw_files, list):
            loaded_files.update(Path(raw) for raw in raw_files if isinstance(raw, str))
        loaded_files.add(resolved)

        link_flags = cached.get("source_link_flags", [])
        self.source_link_flags = [str(f) for f in link_flags if isinstance(f, str) and f]
        cached_include_paths: List[Path] = []
        include_flags = cached.get("source_include_paths", [])
        if isinstance(include_flags, list):
            for raw in include_flags:
                if isinstance(raw, str) and raw:
                    inc = Path(raw)
                    cached_include_paths.append(inc)
                    if inc not in self.include_paths:
                        self.include_paths.append(inc)
        self.source_include_paths = cached_include_paths
        cli_flags = cached.get("source_cli_flags", [])
        self.source_cli_flags = [str(f) for f in cli_flags if isinstance(f, str) and f]

        self._units = units
        self._loaded_files = loaded_files
        absent = cached.get("absent")
        if isinstance(absent, list):
            self._import_absent.update(Path(item) for item in absent if isinstance(item, str))
        links = cached.get("links")
        if isinstance(links, dict):
            self._import_links.update({k: v for k, v in links.items() if isinstance(k, str) and isinstance(v, str)})
        self._set_root_unit(resolved, units[resolved])
        return True

    # -- parse-time source loading -------------------------------------------

    def _begin_parse_sources(self, source: str) -> List[Token]:
        """Tokens for the source the parser starts with.  The preloaded root
        unit is tokenized as a unit (canonical import requests, or the
        frontend marker); any other text is tokenized as plain source."""
        unit = self._root_unit
        warm_seen = self._warm_seen
        if unit is not None and source is unit.text:
            self._parse_seen = {unit.path} if warm_seen is None else (set(warm_seen) | {unit.path})
            return self._tokens_for_unit(unit)
        self._parse_seen = set() if warm_seen is None else set(warm_seen)
        return self.reader.tokenize(source, None, str(self._last_loaded_path or "<memory>"))

    def _tokens_for_unit(self, unit: "SourceUnit") -> List[Token]:
        if unit.frontend is not None:
            marker = Token(_FRONTEND_UNIT_LEXEME, unit.frontend.call_site.start_line,
                           max(0, unit.frontend.call_site.start_column - 1), unit.frontend.call_site.start,
                           unit.frontend.call_site.end, origin=unit.frontend.call_site)
            self.parser._frontend_markers[marker] = unit
            return [marker]
        tokens = self.reader.tokenize(unit.text, unit.spans, str(unit.path))
        if unit.imports:
            tokens = self._canonicalize_import_directives(tokens, unit)
        return tokens

    @staticmethod
    def _canonicalize_import_directives(tokens: List[Token], unit: "SourceUnit") -> List[Token]:
        """Turn each `import <target>` directive line into the canonical core
        request `import "target"`: the target's tokens become one string
        literal token spanning the original target text."""
        lines = [tok.line for tok in tokens]
        result: List[Token] = []
        cursor = 0
        for line_no in sorted(unit.imports):
            target, col_start, col_end = unit.imports[line_no]
            lo = bisect.bisect_left(lines, line_no, cursor)
            hi = bisect.bisect_right(lines, line_no, lo)
            result.extend(tokens[cursor:lo])
            cursor = hi
            line_tokens = tokens[lo:hi]
            if not line_tokens or line_tokens[0].lexeme != "import":
                raise ParseError(f"import directive at {unit.path} line {line_no} was not tokenized as an import", code="internal-import-directive")
            import_token = line_tokens[0]
            target_tokens = [t for t in line_tokens[1:] if col_start <= t.column < col_end]
            rest = [t for t in line_tokens[1:] if t.column >= col_end]
            if len(target_tokens) == 1 and target_tokens[0].lexeme.startswith('"'):
                path_token = target_tokens[0]
            else:
                first = target_tokens[0] if target_tokens else import_token
                start = first.start if target_tokens else import_token.start + (col_start - import_token.column)
                end = target_tokens[-1].end if target_tokens else start + (col_end - col_start)
                path_token = Token(_l2_string_literal(target), line_no, col_start, start, end,
                                   srcmap=import_token._srcmap)
            result.append(import_token)
            result.append(path_token)
            result.extend(rest)
        result.extend(tokens[cursor:])
        return result

    def _importing_file(self, token: Token) -> Path:
        srcmap = token._srcmap
        local = srcmap.location(token.line, token.column) if srcmap is not None else None
        path = str(local[0]) if local is not None else token.origin.path
        if path and not path.startswith("<"):
            return Path(path)
        if self._last_loaded_path is not None:
            return self._last_loaded_path
        return Path.cwd() / "<memory>"

    def _import_request(self, import_token: Token, target: str, *, support: bool = False) -> List[Token]:
        """Load the file named by a canonical `import "target"` request and
        return its tokens, or [] when it was already loaded.  `support`
        requests load a frontend implementation with the core frontend."""
        importer = self._importing_file(import_token)
        try:
            target_path = self._resolve_import_target(importer, target)
        except ParseError as exc:
            origin = import_token.origin
            raise ParseError(f"{exc}\n  at {origin.path}:{origin.start_line}:{origin.start_column}", code="import-unresolved") from exc
        if target_path in self._parse_seen:
            return []
        self._parse_seen.add(target_path)
        self._loaded_files.add(target_path)

        importer_unit = self._units.get(importer)
        inherited = None if support or importer_unit is None else importer_unit.frontend
        unit = self._units.get(target_path)
        if unit is None:
            walk_seen = set(self._units)
            self._walk_unit(target_path, walk_seen, depth=1)
            self._loaded_files.update(walk_seen)
            unit = self._units[target_path]
        if inherited is not None and not unit.explicit_frontend:
            # A headerless file inherits the importing file's frontend.
            text = target_path.read_bytes().decode("utf-8")
            unit = SourceUnit(target_path, text, [], {},
                              FrontendSpec(inherited.impl_path, inherited.entry, import_token.origin))
            self._units[target_path] = unit
        return self._tokens_for_unit(unit)

    def _resolve_frontend_implementation(self, source_path: Path, target: str, origin: SourceOrigin) -> Path:
        try:
            return self._resolve_import_target(source_path, target)
        except ParseError as exc:
            raise ParseError(
                f"frontend implementation {target!r} not found for "
                f"{origin.path}:{origin.start_line}:{origin.start_column}\n{exc}",
                code="frontend-implementation-unavailable",
            ) from exc

    def _expand_frontend_unit(self, marker: Token) -> List[Token]:
        """Tokens that replace a frontend marker.  The first time an
        implementation is needed, its source is imported (with the core
        frontend) ahead of the marker; then the entry point runs."""
        parser = self.parser
        unit = parser._frontend_markers.pop(marker)
        spec = unit.frontend
        if spec.impl_path not in self._frontends_loaded:
            self._frontends_loaded.add(spec.impl_path)
            support_import = Token("import", marker.line, marker.column, marker.start, marker.end,
                                   origin=spec.call_site)
            path_token = Token(_l2_string_literal(str(spec.impl_path)), marker.line, marker.column,
                               marker.start, marker.end, origin=spec.call_site)
            parser._support_import_tokens.add(support_import)
            parser._frontend_markers[marker] = unit
            return [support_import, path_token, marker]
        return self._run_frontend_entry(unit)

    def _run_frontend_entry(self, unit: "SourceUnit") -> List[Token]:
        spec = unit.frontend
        site = f"{spec.call_site.path}:{spec.call_site.start_line}:{spec.call_site.start_column}"
        word = self.dictionary.lookup(spec.entry)
        if word is None or word.runtime_only:
            reason = "is not defined" if word is None else "is runtime-only"
            raise ParseError(f"frontend entry point '{spec.entry}' {reason} "
                             f"(implementation {spec.impl_path}, selected at {site})", code="frontend-entry-unavailable")
        vm = self.parser.compile_time_vm
        try:
            vm.invoke_with_args(word, [unit.text, str(unit.path)])
        except ParseError as exc:
            raise ParseError(f"frontend entry point '{spec.entry}' failed on "
                             f"{unit.path}: {exc}", code="frontend-entry-failed") from exc
        stack = [vm._resolve_handle(value) for value in vm.stack]
        vm.reset()
        if len(stack) != 1 or not isinstance(stack[0], list):
            raise ParseError(f"frontend entry point '{spec.entry}' must leave exactly "
                             f"one token list for {unit.path}, left {len(stack)} value(s)", code="frontend-invalid-result")
        result = stack[0]
        for index, item in enumerate(result):
            if not isinstance(item, Token):
                raise ParseError(f"frontend entry point '{spec.entry}' returned a "
                                 f"{_ct_type_name(item)} at index {index} for {unit.path}; expected tokens", code="frontend-invalid-result")
        frame = ExpansionFrame("frontend", spec.entry, spec.call_site)
        tokens = [
            Token(tok.lexeme, tok.line, tok.column, tok.start, tok.end, tok.expansion_depth,
                  srcmap=tok._srcmap, origin=tok._origin, chain=(frame,) + tok.expansion_chain)
            for tok in result
        ]
        self.parser._canonical_tokens.update(tokens)
        return tokens

    def _record_source_link_flag(self, flag: str) -> None:
        if flag and flag not in self.source_link_flags:
            self.source_link_flags.append(flag)

    def _record_source_cli_flag(self, flag: str) -> None:
        if flag:
            self.source_cli_flags.append(flag)

    def _add_source_include_path(self, raw_path: str, *, base_path: Path) -> None:
        include_path = Path(raw_path).expanduser()
        if not include_path.is_absolute():
            include_path = (base_path.parent / include_path).resolve()
        else:
            include_path = include_path.resolve()
        if include_path not in self.include_paths:
            self.include_paths.append(include_path)
            # Resolution depends on include paths; invalidate old resolutions.
            self._import_resolve_cache.clear()
        if include_path not in self.source_include_paths:
            self.source_include_paths.append(include_path)

    def _apply_flags_directive(self, payload: str, *, path: Path, line_no: int) -> None:
        text = payload.strip()
        if not text:
            raise ParseError(f"flags directive missing arguments at {path}:{line_no}", code="preprocessor-flags-invalid")
        try:
            tokens = shlex.split(text, posix=True)
        except ValueError as exc:
            raise ParseError(f"invalid flags directive at {path}:{line_no}: {exc}", code="preprocessor-flags-invalid") from exc

        if len(tokens) > 1:
            raise ParseError(
                f"flags directive expects a single quoted string at {path}:{line_no}",
                code="preprocessor-flags-invalid",
            )

        # Allow a quoted shell-style bundle like: flags "-lc -lm -L. -I."
        if len(tokens) == 1 and any(ch.isspace() for ch in tokens[0]):
            try:
                tokens = shlex.split(tokens[0], posix=True)
            except ValueError as exc:
                raise ParseError(f"invalid flags directive at {path}:{line_no}: {exc}", code="preprocessor-flags-invalid") from exc

        if not tokens:
            raise ParseError(f"flags directive missing arguments at {path}:{line_no}", code="preprocessor-flags-invalid")

        i = 0
        while i < len(tokens):
            tok = tokens[i]
            if tok in ("-I", "--include"):
                i += 1
                if i >= len(tokens):
                    raise ParseError(f"{tok} requires a path in flags directive at {path}:{line_no}", code="preprocessor-flags-invalid")
                self._add_source_include_path(tokens[i], base_path=path)
                i += 1
                continue
            if tok.startswith("-I") and len(tok) > 2:
                self._add_source_include_path(tok[2:], base_path=path)
                i += 1
                continue
            if tok.startswith("--include="):
                self._add_source_include_path(tok.split("=", 1)[1], base_path=path)
                i += 1
                continue

            # Everything else is treated as a linker/runtime flag token.
            self._record_source_link_flag(tok)
            self._record_source_cli_flag(tok)
            i += 1

    def compile_source(
        self,
        source: str,
        spans: Optional[List[FileSpan]] = None,
        *,
        debug: bool = False,
        entry_mode: str = "program",
        c_abi: bool = False,
        module_name: str = "l2",
        render_preview: bool = False,
    ) -> Emission:
        self.last_transformed_source = ""
        if self.event_bus is not None:
            self.event_bus.publish("compile.begin", {"source": str(self._last_loaded_path or "<memory>"), "bytes": len(source.encode("utf-8"))})
        try:
            self.parser.file_spans = spans or []
            tokens = self._begin_parse_sources(source)
            module = self.parser.parse(tokens, source)
            self.parser._active_module = module
            if render_preview:
                self.last_transformed_source = _render_transformed_module_preview(
                    module,
                    focus_names=self._preview_focus(),
                )
            emit_restore_point_id = self.parser._add_error_restore_point(
                "emit", len(self.parser.tokens), None, self.parser._last_token
            )
            while True:
                try:
                    emission = self.assembler.emit(
                        module, debug=debug, entry_mode=entry_mode, c_abi=c_abi, module_name=module_name
                    )
                    self.parser._finish_recovery_chain("emit")
                    break
                except Exception as emit_exc:
                    restore_point = self.parser._dispatch_recoverable_compile_error(
                        emit_exc,
                        stage="emit",
                        restore_point_id=emit_restore_point_id,
                    )
                    if restore_point is None:
                        raise
                    if self.parser._active_module is None:
                        raise CompileTimeError("compile error handler removed the active module", code="recovery-module-removed")
                    module = self.parser._active_module
        except Exception as exc:
            self._publish_compile_error(exc)
            self.parser._active_module = None
            raise
        self.parser._active_module = None
        if self.event_bus is not None:
            self.event_bus.publish("compile.end", {"source": str(self._last_loaded_path or "<memory>"), "output_artifact": module_name, "size_bytes": emission.snapshot_byte_length()})
        return emission

    def parse_file(self, path: Path, *, render_preview: bool = False) -> None:
        """Parse a source file to populate the dictionary without emitting assembly."""
        self._reset_source_flag_state()
        try:
            source, spans = self._load_source_graph(path)
        except Exception as exc:
            self._publish_compile_error(exc, path)
            raise
        if self.event_bus is not None:
            self.event_bus.publish("compile.begin", {"source": str(path), "bytes": len(source.encode("utf-8"))})
        self.last_transformed_source = ""
        self.parser.file_spans = spans or []
        try:
            tokens = self._begin_parse_sources(source)
            module = self.parser.parse(tokens, source)
            if render_preview:
                self.last_transformed_source = _render_transformed_module_preview(
                    module,
                    focus_names=self._preview_focus(),
                )
        except Exception as exc:
            self._publish_compile_error(exc, path)
            raise
        if self.event_bus is not None:
            self.event_bus.publish("compile.end", {"source": str(path), "output_artifact": None})

    def check_references(self) -> List[Diagnostic]:
        """The --check-references lint: every word called or referenced by
        pointer from any definition or macro body must exist.  Unknown words
        are otherwise reported only when a definition is emitted or run, so
        forward references work but typos in unused words go unnoticed."""
        dictionary = self.dictionary
        found: Dict[Tuple[str, str, Any], Diagnostic] = {}
        for name, word in list(dictionary.words.items()):
            bodies: List[Sequence[Op]] = []
            definition = word.definition
            if isinstance(getattr(definition, "body", None), list):
                bodies.append(definition.body)
            if word.macro_def is not None:
                bodies.append(word.macro_def.body.body)
            for body in bodies:
                for op in body:
                    if op._opcode not in (OP_WORD, OP_WORD_PTR) or not isinstance(op.data, str):
                        continue
                    target = op.data
                    if target in ("exit", "get_addr") or dictionary.lookup(target) is not None:
                        continue
                    origin = _origin_from_location(op.loc)
                    key = (name, target, (origin.path, origin.start) if origin is not None else None)
                    if key not in found:
                        found[key] = Diagnostic(
                            "error", f"'{name}' refers to unknown word '{target}'",
                            code="reference-unknown", primary=origin,
                            notes=["reported by --check-references; a word that is never emitted or run "
                                   "would otherwise compile"],
                        )
        return list(found.values())

    def compile_file(
        self,
        path: Path,
        *,
        debug: bool = False,
        entry_mode: str = "program",
        c_abi: bool = False,
        module_name: Optional[str] = None,
        render_preview: bool = False,
    ) -> Emission:
        self._reset_source_flag_state()
        try:
            source, spans = self._load_source_graph(path)
        except Exception as exc:
            self._publish_compile_error(exc, path)
            raise
        mod_name = module_name or path.stem
        return self.compile_source(
            source,
            spans=spans,
            debug=debug,
            entry_mode=entry_mode,
            c_abi=c_abi,
            module_name=mod_name,
            render_preview=render_preview,
        )

    def collect_source_flags(self, path: Path) -> None:
        """Load source/import graph only to collect source-level pragma flags."""
        self._reset_source_flag_state()
        self._load_source_graph(path)

    def compile_preloaded(
        self,
        *,
        debug: bool = False,
        entry_mode: str = "program",
        c_abi: bool = False,
        module_name: str = "l2",
        render_preview: bool = False,
    ) -> Emission:
        if self._last_loaded_source is None or self._last_loaded_spans is None:
            raise CompileError("no preloaded source available", code="internal-no-preloaded-source")
        return self.compile_source(
            self._last_loaded_source,
            spans=self._last_loaded_spans,
            debug=debug,
            entry_mode=entry_mode,
            c_abi=c_abi,
            module_name=module_name,
            render_preview=render_preview,
        )

    def run_compile_time_word(
        self,
        name: str,
        *,
        libs: Optional[List[str]] = None,
        mmap_leak_check: bool = False,
        argv: Optional[Sequence[str]] = None,
    ) -> int:
        word = self.dictionary.lookup(name)
        if word is None:
            raise CompileTimeError(f"word '{name}' not defined; cannot run at compile time", code="ct-word-unavailable")
        # Skip if already executed via a ``compile-time <name>`` directive.
        if name in self.parser.compile_time_vm._ct_executed:
            return 0
        return self.parser.compile_time_vm.invoke(
            word,
            runtime_mode=True,
            libs=libs,
            mmap_leak_check=mmap_leak_check,
            argv=argv,
        )

    def run_compile_time_word_repl(self, name: str, *, libs: Optional[List[str]] = None) -> None:
        """Like run_compile_time_word but uses invoke_repl for persistent state."""
        word = self.dictionary.lookup(name)
        if word is None:
            raise CompileTimeError(f"word '{name}' not defined; cannot run at compile time", code="ct-word-unavailable")
        self.parser.compile_time_vm.invoke_repl(word, libs=libs)

    @staticmethod
    def _parse_directive_target_and_rest(
        line: str,
        keyword: str,
        *,
        path: Path,
        line_no: int,
        line_already_lstripped: bool = False,
    ) -> Optional[Tuple[str, str]]:
        """Parse `<keyword> <target> [remainder]` where target may be quoted."""
        text = line if line_already_lstripped else line.lstrip()
        if not text.startswith(keyword):
            return None
        if len(text) > len(keyword) and not text[len(keyword)].isspace():
            return None

        pos = len(keyword)
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos >= len(text):
            raise ParseError(f"empty {keyword} target in {path}:{line_no}", code="preprocessor-directive-invalid")

        if text[pos] == '"':
            pos += 1
            start = pos
            while pos < len(text) and text[pos] != '"':
                pos += 1
            if pos >= len(text):
                raise ParseError(f"unterminated quoted {keyword} target in {path}:{line_no}", code="preprocessor-directive-invalid")
            target = text[start:pos]
            pos += 1
        else:
            start = pos
            while pos < len(text) and not text[pos].isspace():
                pos += 1
            target = text[start:pos]

        while pos < len(text) and text[pos].isspace():
            pos += 1
        remainder = text[pos:]
        return target, remainder

    def _preprocess_c_header(self, header_path: Path, raw_text: str) -> str:
        """Try running the C preprocessor on a header file for accurate parsing.

        Falls back to raw_text if the preprocessor is not available."""
        import subprocess
        try:
            result = subprocess.run(
                ["cc", "-E", "-P", "-D__attribute__(x)=", "-D__extension__=",
                 "-D__restrict=", "-D__asm__(x)=", str(header_path)],
                capture_output=True, text=True, timeout=10,
            )
            if result.returncode == 0 and result.stdout.strip():
                return result.stdout
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        return raw_text

    def _resolved_include_paths(self) -> Tuple[Path, ...]:
        """The include paths, resolved once per distinct include list (each
        Path.resolve() is a filesystem call)."""
        key = tuple(self.include_paths)
        cached = getattr(self, "_include_paths_resolved", None)
        if cached is None or cached[0] != key:
            cached = (key, tuple(path.expanduser().resolve() for path in key))
            self._include_paths_resolved = cached
        return cached[1]

    def _resolve_import_target(self, importing_file: Path, target: str) -> Path:
        include_paths = self._resolved_include_paths()
        # The importer's name is part of the key only when it matches the
        # target, since only then does it change the result (see below).
        self_named = importing_file.name if Path(target).name == importing_file.name else None
        cache_key = (importing_file.parent.resolve(), target, include_paths, self_named)
        cached = self._import_resolve_cache.get(cache_key)
        if cached is not None and cached[0].exists():
            self._import_absent.update(cached[1])
            if cached[2] is not None:
                self._import_links[cached[2]] = str(cached[0])
            return cached[0]
        if cached is not None:
            self._import_resolve_cache.pop(cache_key, None)
        raw = Path(target)
        tried: List[Path] = []
        absent: List[Path] = []

        def found(candidate: Path) -> Path:
            result = candidate.resolve()
            link = os.path.abspath(candidate)
            link = link if link != str(result) else None
            self._import_resolve_cache[cache_key] = (result, tuple(absent), link)
            self._import_absent.update(absent)
            if link is not None:
                self._import_links[link] = str(result)
            return result

        def probe(candidate: Path) -> bool:
            tried.append(candidate)
            if candidate.exists():
                return True
            absent.append(Path(os.path.abspath(candidate)))
            return False

        if raw.is_absolute():
            candidate = raw.expanduser()
            if probe(candidate):
                return found(candidate)

        # A file never imports itself: `import io.sl` written in a file named
        # io.sl means another io.sl, found further along the search path.
        try:
            importer = importing_file.resolve()
        except OSError:
            importer = importing_file
        candidate = importing_file.parent / raw
        if probe(candidate) and candidate.resolve() != importer:
            return found(candidate)

        for base in include_paths:
            candidate = base / raw
            if probe(candidate) and candidate.resolve() != importer:
                return found(candidate)

        tried_str = "\n".join(f"  - {p}" for p in dict.fromkeys(tried))
        raise ParseError(
            f"cannot import {target!r} from {importing_file}\n"
            f"tried:\n{tried_str}",
            code="import-unresolved",
        )

    def _register_syscall_words(self) -> None:
        self.dictionary.set_baseline_handler("syscall", "intrinsic", self._emit_syscall_intrinsic)

    def _emit_syscall_intrinsic(self, builder: FunctionEmitter) -> None:
        def _try_pop_known_syscall_setup() -> Optional[Tuple[int, int]]:
            """Recognize and remove literal setup for known-argc syscalls.

            Supported forms right before `syscall`:
              1) <argc> <nr>
              2) <nr> <argc> ___linux_swap
            Returns (argc, nr) when recognized.
            """

            # Form 1: ... push argc ; push nr ; syscall
            nr = Assembler._pop_preceding_literal(builder)
            if nr is not None:
                argc = Assembler._pop_preceding_literal(builder)
                if argc is not None and 0 <= argc <= 6:
                    return argc, nr
                # rollback if second literal wasn't argc
                builder.push_literal(nr)

            # Form 2: ... push nr ; push argc ; ___linux_swap ; syscall
            text = builder.text
            swap_tail = [
                "mov rax, [r12]",
                "mov rbx, [r12 + 8]",
                "mov [r12], rbx",
                "mov [r12 + 8], rax",
            ]
            if len(text) >= 4 and [s.strip() for s in text[-4:]] == swap_tail:
                del text[-4:]
                argc2 = Assembler._pop_preceding_literal(builder)
                nr2 = Assembler._pop_preceding_literal(builder)
                if argc2 is not None and nr2 is not None and 0 <= argc2 <= 6:
                    return argc2, nr2
                # rollback conservatively if match fails
                if nr2 is not None:
                    builder.push_literal(nr2)
                if argc2 is not None:
                    builder.push_literal(argc2)
                text.extend(swap_tail)

            return None

        known = _try_pop_known_syscall_setup()
        if known is not None:
            argc, nr = known
            builder.push_literal(nr)
            builder.pop_to("rax")
            if argc >= 6:
                builder.pop_to("r9")
            if argc >= 5:
                builder.pop_to("r8")
            if argc >= 4:
                builder.pop_to("r10")
            if argc >= 3:
                builder.pop_to("rdx")
            if argc >= 2:
                builder.pop_to("rsi")
            if argc >= 1:
                builder.pop_to("rdi")
            builder.emit("    syscall")
            builder.push_from("rax")
            return

        label_id = self._syscall_label_counter
        self._syscall_label_counter += 1

        def lbl(suffix: str) -> str:
            return f"syscall_{label_id}_{suffix}"

        builder.pop_to("rax")  # syscall number
        builder.pop_to("rcx")  # arg count
        builder.emit("    ; clamp arg count to [0, 6]")
        builder.emit("    cmp rcx, 0")
        builder.emit(f"    jge {lbl('count_nonneg')}")
        builder.emit("    xor rcx, rcx")
        builder.emit(f"{lbl('count_nonneg')}:")
        builder.emit("    cmp rcx, 6")
        builder.emit(f"    jle {lbl('count_clamped')}")
        builder.emit("    mov rcx, 6")
        builder.emit(f"{lbl('count_clamped')}:")

        checks = [
            (6, "r9"),
            (5, "r8"),
            (4, "r10"),
            (3, "rdx"),
            (2, "rsi"),
            (1, "rdi"),
        ]
        for threshold, reg in checks:
            builder.emit(f"    cmp rcx, {threshold}")
            builder.emit(f"    jl {lbl(f'skip_{reg}')}")
            builder.pop_to(reg)
            builder.emit(f"{lbl(f'skip_{reg}')}:")

        builder.emit("    syscall")
        builder.push_from("rax")

    def _load_with_imports(self, path: Path, seen: Optional[Set[Path]] = None) -> "SourceUnit":
        """Preprocess `path` and, depth-first in directive order, every
        default-frontend file it imports.  Returns the root SourceUnit; all
        walked units are stored in `self._units`."""
        if seen is None:
            seen = set()
        root = path.resolve()
        self._walk_unit(root, seen, depth=0)
        self._loaded_files = set(seen)
        return self._units[root]

    def _walk_unit(self, path: Path, seen: Set[Path], *, depth: int) -> None:
        """Build the SourceUnit for `path` (already resolved).  Directives are
        applied in source order; an import directive walks its target at that
        point, so a `define` in an imported file affects later `ifdef`s
        exactly as textual inclusion did.  A file with a frontend header is
        not preprocessed: its frontend owns its syntax and imports."""
        if path in seen:
            return
        closure = self._warm_unit_closure
        if closure is not None and path in closure:
            # A stdlib file preprocessed by the warm prefix (unchanged, and
            # walked in the same preprocessor state): reuse it and the files
            # it imports instead of reading and preprocessing them again.
            for unit_path in closure[path]:
                if unit_path not in seen:
                    seen.add(unit_path)
                    self._units[unit_path] = self._warm_units[unit_path]
            return
        seen.add(path)

        if self.event_bus is not None:
            self.event_bus.publish("import.begin", {"path": str(path), "depth": depth})

        try:
            contents = path.read_bytes().decode("utf-8")
        except FileNotFoundError as exc:
            raise ParseError(f"cannot import {path}: {exc}", code="import-unreadable") from exc
        except UnicodeDecodeError as exc:
            raise ParseError(f"cannot import {path}: not valid UTF-8 ({exc})", code="import-unreadable") from exc

        header = _detect_frontend_header(contents, str(path))
        if header is not None:
            impl_target, entry, header_origin = header
            impl_path = self._resolve_frontend_implementation(path, impl_target, header_origin)
            self._units[path] = SourceUnit(
                path, contents, [], {}, FrontendSpec(impl_path, entry, header_origin), explicit_frontend=True,
            )
            if self.event_bus is not None:
                self.event_bus.publish("import.end", {"path": str(path), "resolved_path": str(path), "depth": depth})
            return

        out_lines: List[str] = []
        spans: List[FileSpan] = []
        imports: Dict[int, Tuple[str, int, int]] = {}

        # Fast path for files without preprocessor/import directives.
        # This avoids line-by-line scanning for the common plain-source case.
        if (
            "import" not in contents
            and "define" not in contents
            and "ifdef" not in contents
            and "ifndef" not in contents
            and "elsedef" not in contents
            and "endif" not in contents
            and "flags" not in contents
            and ":py" not in contents
        ):
            lines = contents.splitlines()
            if lines:
                out_lines.extend(lines)
                spans.append(FileSpan(path=path, start_line=1, end_line=len(out_lines) + 1, local_start_line=1))
            self._units[path] = SourceUnit(path, "\n".join(out_lines) + "\n", spans, imports, None)
            if self.event_bus is not None:
                self.event_bus.publish("import.end", {"path": str(path), "resolved_path": str(path), "depth": depth})
            return

        in_py_block = False
        brace_depth = 0
        string_char = None
        escape = False

        segment_start_global: Optional[int] = None
        segment_start_local: int = 1
        file_line_no = 1
        _out_append = out_lines.append
        _spans_append = spans.append
        _FileSpan = FileSpan

        # ifdef/ifndef/else/endif conditional compilation stack
        # Each entry is True (include lines) or False (skip lines)
        _ifdef_stack: List[bool] = []
        _ifdef_inactive = 0

        for line in contents.splitlines():
            # Avoid lstrip allocation when the line is already left-aligned.
            if line and (line[0] == " " or line[0] == "\t"):
                lstripped = line.lstrip()
            else:
                lstripped = line
            # Hot path: ordinary source line with no directive prefix.
            if not in_py_block and _ifdef_inactive == 0:
                lead = lstripped[:1]
                if lead not in ("i", "c", "d", "f", "e", ":"):
                    if segment_start_global is None:
                        segment_start_global = len(out_lines) + 1
                        segment_start_local = file_line_no
                    _out_append(line)
                    file_line_no += 1
                    continue

            stripped = lstripped.rstrip()

            # --- Conditional compilation directives ---
            if stripped[:6] == "ifdef " or stripped == "ifdef":
                name = stripped[6:].strip() if len(stripped) > 6 else ""
                if not name:
                    raise ParseError(f"ifdef missing symbol name at {path}:{file_line_no}", code="preprocessor-directive-invalid")
                branch_active = name in self.defines if _ifdef_inactive == 0 else False
                _ifdef_stack.append(branch_active)
                if not branch_active:
                    _ifdef_inactive += 1
                _out_append("")  # placeholder to keep line numbers aligned
                file_line_no += 1
                continue
            if stripped[:7] == "ifndef " or stripped == "ifndef":
                name = stripped[7:].strip() if len(stripped) > 7 else ""
                if not name:
                    raise ParseError(f"ifndef missing symbol name at {path}:{file_line_no}", code="preprocessor-directive-invalid")
                branch_active = name not in self.defines if _ifdef_inactive == 0 else False
                _ifdef_stack.append(branch_active)
                if not branch_active:
                    _ifdef_inactive += 1
                _out_append("")
                file_line_no += 1
                continue
            if stripped == "elsedef":
                if not _ifdef_stack:
                    raise ParseError(f"elsedef without matching ifdef/ifndef at {path}:{file_line_no}", code="preprocessor-directive-invalid")
                was_active = _ifdef_stack[-1]
                now_active = not was_active
                _ifdef_stack[-1] = now_active
                if was_active and not now_active:
                    _ifdef_inactive += 1
                elif (not was_active) and now_active:
                    _ifdef_inactive -= 1
                _out_append("")
                file_line_no += 1
                continue
            if stripped == "endif":
                if not _ifdef_stack:
                    raise ParseError(f"endif without matching ifdef/ifndef at {path}:{file_line_no}", code="preprocessor-directive-invalid")
                popped = _ifdef_stack.pop()
                if not popped:
                    _ifdef_inactive -= 1
                _out_append("")
                file_line_no += 1
                continue

            # If inside a false ifdef branch, skip the line
            if _ifdef_inactive:
                _out_append("")
                file_line_no += 1
                continue

            if stripped[:7] == "define " or stripped == "define":
                symbol = stripped[7:].strip() if len(stripped) > 7 else ""
                if not symbol:
                    raise ParseError(f"define missing symbol name at {path}:{file_line_no}", code="preprocessor-directive-invalid")
                symbol_name = symbol.split(None, 1)[0]
                self.defines.add(symbol_name)
                _out_append("")
                file_line_no += 1
                continue

            if lstripped.startswith("flags") and (len(lstripped) == 5 or lstripped[5].isspace()):
                payload = lstripped[5:].strip()
                self._apply_flags_directive(payload, path=path, line_no=file_line_no)
                _out_append("")
                file_line_no += 1
                continue

            if not in_py_block and stripped[:3] == ":py" and "{" in stripped:
                in_py_block = True
                brace_depth = 0
                string_char = None
                escape = False
                # scan_line inline
                for ch in line:
                    if string_char:
                        if escape:
                            escape = False
                        elif ch == "\\":
                            escape = True
                        elif ch == string_char:
                            string_char = None
                    else:
                        if ch == "'" or ch == '"':
                            string_char = ch
                        elif ch == "{":
                            brace_depth += 1
                        elif ch == "}":
                            brace_depth -= 1
                # begin_segment_if_needed inline
                if segment_start_global is None:
                    segment_start_global = len(out_lines) + 1
                    segment_start_local = file_line_no
                _out_append(line)
                file_line_no += 1
                if brace_depth == 0:
                    in_py_block = False
                continue

            if in_py_block:
                # scan_line inline
                for ch in line:
                    if string_char:
                        if escape:
                            escape = False
                        elif ch == "\\":
                            escape = True
                        elif ch == string_char:
                            string_char = None
                    else:
                        if ch == "'" or ch == '"':
                            string_char = ch
                        elif ch == "{":
                            brace_depth += 1
                        elif ch == "}":
                            brace_depth -= 1
                # begin_segment_if_needed inline
                if segment_start_global is None:
                    segment_start_global = len(out_lines) + 1
                    segment_start_local = file_line_no
                _out_append(line)
                file_line_no += 1
                if brace_depth == 0:
                    in_py_block = False
                continue

            parsed_import = None
            if lstripped.startswith("import"):
                parsed_import = self._parse_directive_target_and_rest(
                    lstripped,
                    "import",
                    path=path,
                    line_no=file_line_no,
                    line_already_lstripped=True,
                )
            if parsed_import is not None:
                target, _remainder = parsed_import
                # Keep the line: the parser turns it into the canonical
                # request `import "target"` and loads the file when it
                # reaches it.  Walk the target now, in directive order.
                if segment_start_global is None:
                    segment_start_global = len(out_lines) + 1
                    segment_start_local = file_line_no
                _out_append(line)
                indent = len(line) - len(lstripped)
                target_start, target_end = _directive_target_columns(lstripped, "import")
                imports[len(out_lines)] = (target, indent + target_start, indent + target_end)
                file_line_no += 1
                target_path = self._resolve_import_target(path, target)
                self._walk_unit(target_path, seen, depth=depth + 1)
                continue

            parsed_cimport = None
            if lstripped.startswith("cimport"):
                parsed_cimport = self._parse_directive_target_and_rest(
                    lstripped,
                    "cimport",
                    path=path,
                    line_no=file_line_no,
                    line_already_lstripped=True,
                )
            if parsed_cimport is not None:
                header_target, remainder = parsed_cimport
                # cimport "header.h" — extract extern declarations from a C header
                header_path = self._resolve_import_target(path, header_target)
                seen.add(header_path)
                try:
                    header_text = header_path.read_text()
                except FileNotFoundError as exc:
                    raise ParseError(f"cimport cannot read {header_path}: {exc}", code="cimport-unreadable") from exc

                # Try running the C preprocessor for more accurate parsing
                header_text = self._preprocess_c_header(header_path, header_text)

                extern_lines = _parse_c_header_externs(header_text)
                struct_lines = _parse_c_header_structs(header_text)

                # begin_segment_if_needed inline
                if segment_start_global is None:
                    segment_start_global = len(out_lines) + 1
                    segment_start_local = file_line_no
                source_line_no = file_line_no
                # Replace the cimport line with the extracted extern + struct declarations
                for ext_line in extern_lines:
                    _out_append(ext_line)
                for st_line in struct_lines:
                    _out_append(st_line)
                _out_append("")  # blank line after externs
                file_line_no += 1

                # Keep optional trailing statements after cimport on the same line.
                if remainder:
                    _out_append(remainder)
                    if segment_start_global is None:
                        segment_start_global = len(out_lines) + 1
                        segment_start_local = source_line_no
                continue

            # begin_segment_if_needed inline
            if segment_start_global is None:
                segment_start_global = len(out_lines) + 1
                segment_start_local = file_line_no
            _out_append(line)
            file_line_no += 1

        # close_segment_if_open inline
        if segment_start_global is not None:
            _spans_append(
                _FileSpan(
                    path=path,
                    start_line=segment_start_global,
                    end_line=len(out_lines) + 1,
                    local_start_line=segment_start_local,
                )
            )
        if _ifdef_stack:
            raise ParseError(f"unterminated ifdef/ifndef ({len(_ifdef_stack)} level(s) deep) in {path}", code="preprocessor-unterminated-conditional")
        self._units[path] = SourceUnit(path, "\n".join(out_lines) + "\n", spans, imports, None)
        if self.event_bus is not None:
            self.event_bus.publish("import.end", {"path": str(path), "resolved_path": str(path), "depth": depth})



def _file_identity(st: os.stat_result) -> Tuple[int, int, int, int]:
    """What a cache compares to decide that a file has not changed: size,
    modification time, inode change time and inode.  The change time is set
    by the kernel on every write and cannot be set back, so an edit that keeps
    the size and restores the modification time (cp -p, rsync -t, tar) is
    still noticed."""
    return (int(st.st_mtime_ns), int(st.st_size), int(st.st_ctime_ns), int(st.st_ino))


def _absent_paths_fresh(paths: Any) -> bool:
    """None of the paths an import looked for and did not find exists now."""
    if paths is None:
        return True
    if not isinstance(paths, list):
        return False
    return not any(isinstance(path, str) and os.path.exists(path) for path in paths)


def _import_links_fresh(links: Any) -> bool:
    """Every import path that went through a symlink still resolves to the
    same file."""
    if links is None:
        return True
    if not isinstance(links, dict):
        return False
    return all(isinstance(path, str) and os.path.realpath(path) == target for path, target in links.items())


def _write_text_if_changed(path: Path, text: str, *, force: bool = False,
                           encoding: str = "utf-8") -> bool:
    """Write text to path unless the file already holds exactly that text
    (or force is set).  Returns whether it wrote.  On a disk with slow
    writes any write can stall a compile, and most compiles would rewrite
    build files with what they already hold."""
    data = text.encode(encoding)
    if not force:
        try:
            if path.stat().st_size == len(data) and path.read_bytes() == data:
                return False
        except OSError:
            pass
    path.write_bytes(data)
    return True


class SourceGraphCache:
    """Caches fully preprocessed source graphs keyed by source/import state."""

    _VERSION = 3

    def __init__(self, cache_dir: Path) -> None:
        self.cache_dir = cache_dir

    @staticmethod
    def _hash_bytes(data: bytes) -> str:
        import hashlib
        return hashlib.sha256(data).hexdigest()

    @staticmethod
    def _hash_str(s: str) -> str:
        import hashlib
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    @staticmethod
    def _compiler_fingerprint() -> str:
        try:
            return ":".join(map(str, _file_identity(Path(__file__).stat())))
        except OSError:
            return "0:0"

    def _manifest_path(
        self,
        source: Path,
        *,
        defines: Set[str],
        include_paths: Sequence[Path],
    ) -> Path:
        define_key = "\x1f".join(sorted(str(item) for item in defines))
        include_key = "\x1f".join(str(Path(item).expanduser().resolve()) for item in include_paths)
        key = self._hash_str(
            f"v={self._VERSION}|source={source.resolve()}|"
            f"defines={define_key}|includes={include_key}|"
            f"compiler={self._compiler_fingerprint()}"
        )
        return self.cache_dir / f"graph_{key}.json"

    def _file_info(self, path: Path) -> dict:
        st = path.stat()
        return {
            "identity": list(_file_identity(st)),
            "hash": self._hash_bytes(path.read_bytes()),
        }

    def _deps_fresh(self, file_info: Dict[str, Any]) -> bool:
        for path_str, info in file_info.items():
            if not isinstance(path_str, str) or not isinstance(info, dict):
                return False
            p = Path(path_str)
            if not p.exists():
                return False
            try:
                st = p.stat()
            except OSError:
                return False

            if info.get("identity") == list(_file_identity(st)):
                continue

            actual_hash = self._hash_bytes(p.read_bytes())
            if actual_hash != info.get("hash"):
                return False
        return True

    def load(
        self,
        source: Path,
        *,
        defines: Set[str],
        include_paths: Sequence[Path],
    ) -> Optional[dict]:
        manifest_path = self._manifest_path(source, defines=defines, include_paths=include_paths)
        if not manifest_path.exists():
            return None
        try:
            import json
            payload = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            return None

        if not isinstance(payload, dict):
            return None
        if payload.get("version") != self._VERSION:
            return None
        file_info = payload.get("file_info")
        if not isinstance(file_info, dict):
            return None
        if not self._deps_fresh(file_info):
            return None
        if not _absent_paths_fresh(payload.get("absent")) or not _import_links_fresh(payload.get("links")):
            return None
        return payload

    def save(
        self,
        source: Path,
        *,
        defines: Set[str],
        include_paths: Sequence[Path],
        loaded_files: Set[Path],
        units: Sequence["SourceUnit"],
        source_link_flags: Sequence[str],
        source_include_paths: Sequence[Path],
        source_cli_flags: Sequence[str],
        absent: Iterable[Path] = (),
        links: Optional[Dict[str, str]] = None,
    ) -> None:
        self.cache_dir.mkdir(parents=True, exist_ok=True)

        file_info: Dict[str, dict] = {}
        for p in sorted(loaded_files, key=lambda item: str(item)):
            try:
                file_info[str(p)] = self._file_info(p)
            except OSError:
                continue

        unit_rows = [
            {
                "path": str(unit.path),
                "text": unit.text,
                "spans": [(span.path.as_posix(), int(span.start_line), int(span.end_line), int(span.local_start_line))
                          for span in unit.spans],
                "imports": {str(line): list(entry) for line, entry in unit.imports.items()},
            }
            for unit in units
        ]

        payload = {
            "version": self._VERSION,
            "units": unit_rows,
            "files": [str(p) for p in sorted(loaded_files, key=lambda item: str(item))],
            "file_info": file_info,
            "source_link_flags": [str(f) for f in source_link_flags if str(f)],
            "source_include_paths": [str(Path(p).expanduser().resolve()) for p in source_include_paths],
            "source_cli_flags": [str(f) for f in source_cli_flags if str(f)],
            "defines": sorted(str(item) for item in defines),
            "include_paths": [str(Path(p).expanduser().resolve()) for p in include_paths],
            "absent": sorted(str(p) for p in absent),
            "links": dict(links or {}),
        }

        manifest_path = self._manifest_path(source, defines=defines, include_paths=include_paths)
        try:
            import json
            _write_text_if_changed(manifest_path, json.dumps(payload))
        except OSError:
            return


class BuildCache:
    """Caches compilation artifacts keyed by source content and compiler flags."""

    _FORMAT_VERSION = 3

    def __init__(self, cache_dir: Path) -> None:
        self.cache_dir = cache_dir

    @staticmethod
    def _hash_bytes(data: bytes) -> str:
        import hashlib
        return hashlib.sha256(data).hexdigest()

    @staticmethod
    def _hash_str(s: str) -> str:
        import hashlib
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _manifest_path(self, source: Path) -> Path:
        key = self._hash_str(str(source.resolve()))
        return self.cache_dir / f"{key}.json"

    def flags_hash(
        self,
        debug: bool,
        folding: bool,
        peephole: bool,
        auto_inline: bool,
        asm_post_opt: bool,
        string_deduplication: bool,
        entry_mode: str,
        c_abi: bool = False,
        settings: str = "",
    ) -> str:
        """`settings`: every other option the generated assembly depends on
        (defines, warnings, include paths, code generation switches)."""
        # Include the compiler's own mtime so any change to main.py
        # (codegen improvements, bug fixes) invalidates cached results.
        try:
            compiler_mtime = ":".join(map(str, _file_identity(os.stat(__file__))))
        except OSError:
            compiler_mtime = "0"
        return self._hash_str(
            f"debug={debug},folding={folding},"
            f"peephole={peephole},auto_inline={auto_inline},"
            f"asm_post_opt={asm_post_opt},"
            f"string_deduplication={string_deduplication},"
            f"entry_mode={entry_mode},c_abi={c_abi},compiler_mtime={compiler_mtime},"
            f"settings={settings}"
        )

    def _file_info(self, path: Path) -> dict:
        st = path.stat()
        return {
            "identity": list(_file_identity(st)),
            "hash": self._hash_bytes(path.read_bytes()),
        }

    def load_manifest(self, source: Path) -> Optional[dict]:
        mp = self._manifest_path(source)
        if not mp.exists():
            return None
        try:
            import json
            payload = json.loads(mp.read_text())
        except (ValueError, OSError):
            return None
        if not isinstance(payload, dict):
            return None
        if payload.get("format_version") != self._FORMAT_VERSION:
            return None
        return payload

    def check_fresh(self, manifest: dict, fhash: str) -> bool:
        """Return True if all source files are unchanged and flags match."""
        if manifest.get("flags_hash") != fhash:
            return False
        if manifest.get("has_ct_effects"):
            return False
        files = manifest.get("files", {})
        for path_str, info in files.items():
            p = Path(path_str)
            if not p.exists():
                return False
            try:
                st = p.stat()
            except OSError:
                return False
            if info.get("identity") == list(_file_identity(st)):
                continue
            actual_hash = self._hash_bytes(p.read_bytes())
            if actual_hash != info.get("hash"):
                return False
        return _absent_paths_fresh(manifest.get("absent")) and _import_links_fresh(manifest.get("links"))

    def get_cached_asm(self, manifest: dict) -> Optional[str]:
        asm_hash = manifest.get("asm_hash")
        if not asm_hash:
            return None
        asm_path = self.cache_dir / f"{asm_hash}.asm"
        if not asm_path.exists():
            return None
        return asm_path.read_text()

    def save(
        self,
        source: Path,
        loaded_files: Set[Path],
        fhash: str,
        asm_text: str,
        has_ct_effects: bool = False,
        absent: Iterable[Path] = (),
        links: Optional[Dict[str, str]] = None,
    ) -> None:
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        files: Dict[str, dict] = {}
        for p in sorted(loaded_files):
            try:
                files[str(p)] = self._file_info(p)
            except OSError:
                pass
        asm_hash = self._hash_str(asm_text)
        asm_path = self.cache_dir / f"{asm_hash}.asm"
        _write_text_if_changed(asm_path, asm_text)
        manifest = {
            "format_version": self._FORMAT_VERSION,
            "source": str(source.resolve()),
            "flags_hash": fhash,
            "files": files,
            "asm_hash": asm_hash,
            "has_ct_effects": has_ct_effects,
            "absent": sorted(str(p) for p in absent),
            "links": dict(links or {}),
        }
        import json
        _write_text_if_changed(self._manifest_path(source), json.dumps(manifest))

    def clean(self) -> None:
        if self.cache_dir.exists():
            import shutil
            shutil.rmtree(self.cache_dir)


def _which_exec(name: str) -> Optional[str]:
    """Lightweight executable lookup without importing shutil."""
    if not name:
        return None
    if os.path.sep in name:
        return name if (os.path.isfile(name) and os.access(name, os.X_OK)) else None
    for part in os.environ.get("PATH", "").split(os.pathsep):
        base = part or "."
        candidate = os.path.join(base, name)
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            return candidate
    return None

def _find_nasm() -> str:
    p = _which_exec("nasm")
    if not p:
        raise RuntimeError("nasm not found")
    return p

def _find_linker() -> tuple:
    lld = _which_exec("ld.lld")
    if lld:
        return lld, True
    ld = _which_exec("ld")
    if ld:
        return ld, False
    raise RuntimeError("No linker found")

def _run_cmd(args: list) -> None:
    """Run a command using posix_spawn for lower overhead than subprocess."""
    pid = os.posix_spawn(args[0], args, os.environ)
    _, status = os.waitpid(pid, 0)
    if os.WIFEXITED(status):
        code = os.WEXITSTATUS(status)
        if code != 0:
            import subprocess
            raise subprocess.CalledProcessError(code, args)
    elif os.WIFSIGNALED(status):
        import subprocess
        raise subprocess.CalledProcessError(-os.WTERMSIG(status), args)


def run_nasm(asm_path: Path, obj_path: Path, debug: bool = False, asm_text: str = "") -> None:
    nasm = _find_nasm()
    cmd = [nasm, "-f", "elf64"]
    if debug:
        cmd.extend(["-g", "-F", "dwarf"])
    cmd += ["-o", str(obj_path), str(asm_path)]
    _run_cmd(cmd)


# -- Parallel assembly -------------------------------------------------------
#
# nasm costs ~6 us per instruction and is single-threaded, so a large program
# is split into parts assembled by concurrent nasm processes, then joined with
# `ld -r` into the one object file the link step expects.  Part 0 keeps
# everything but whole word definitions (`w_NAME:` blocks) that can be moved:
# the header, data, bss, `_start`, and any block that is exported, uses
# nasm's preprocessor, data or alignment directives, quotes, or externs, or
# that could fall through into its neighbour.  A label used across parts gets
# a hidden alias at the same address (`__l2_part_NAME`); the using part maps
# the name to it with %define, so no original name becomes global.
#
# The result has the same code and data with moved blocks placed after part
# 0's text.  If a part fails or prints anything, the whole file is assembled
# the normal way, so errors and warnings are exactly nasm's on the full file.
# L2_NASM_PARALLEL=0 disables it; =force uses it for any size (tests).

_NASM_PARALLEL_MIN_LINES = 1500
_NASM_PARALLEL_MAX_PARTS = 4
_NASM_PART_ALIAS = "__l2_part_"
_RE_NASM_IDENT = re.compile(r"[A-Za-z_.?@][A-Za-z0-9_.$@#~?]*")
_NASM_TERMINATORS = frozenset({"ret", "jmp"})


_NASM_SYMBOL = r"[A-Za-z_?][A-Za-z0-9_.$@#~?]*"
# The line-start patterns begin with a literal newline (the text is scanned
# with one prepended), which lets the regex engine skip between lines.
_RE_NASM_DIRECTIVE = re.compile(
    r"\n[ \t]*(%|\[|(?i:section|segment|global|extern|default|bits|cpu|absolute|org)\b)([^\n]*)")
# The same on lowercased ASCII text (several times faster than (?i:...)).
_RE_NASM_DIRECTIVE_LOWER = re.compile(
    r"\n[ \t]*(%|\[|(?:section|segment|global|extern|default|bits|cpu|absolute|org)\b)([^\n]*)")
_RE_NASM_BOUNDARY = re.compile(
    rf"\n(?:(w_[A-Za-z0-9_.$@#~?]*):|_start:|[ \t]*(?i:section|segment)[ \t]+(\S+))")
_RE_NASM_NUMERIC_EQU = re.compile(
    rf"\n[ \t]*({_NASM_SYMBOL})[ \t]+(?i:equ)[ \t]+(-?(?:0x[0-9A-Fa-f]+|\d+))[ \t]*(?:;[^\n]*)?(?=\n|$)")
# Words a moved block may not contain (data, alignment, section and symbol
# directives).  Lines starting with % or [ never get this far: the whole
# file is then assembled in one piece.
_NASM_UNMOVABLE_WORDS = frozenset({
    "align", "alignb", "times", "section", "segment", "global", "extern", "common", "default", "bits",
    "cpu", "struc", "endstruc", "istruc", "iend", "at", "incbin", "org", "absolute", "static", "required",
    "use16", "use32", "use64", "equ", "warning",
    "db", "dw", "dd", "dq", "dt", "do", "dy", "dz",
    "resb", "resw", "resd", "resq", "rest", "reso", "resy", "resz",
})
_RE_NASM_LABEL_LINE = re.compile(rf"^([ \t]*)({_NASM_SYMBOL}):", re.M)
_RE_NASM_COMMENT = re.compile(r";[^\n]*")


def _nasm_last_code(segment: str) -> str:
    """The mnemonic the last code line of segment starts with (after any
    label); ':' when that line is only a label, '' when there is none."""
    for line in reversed(segment.split("\n")):
        code = (line.split(";", 1)[0] if ";" in line else line).strip()
        if not code:
            continue
        first = code.split(None, 1)[0]
        if first.endswith(":"):
            rest = code[len(first):].strip()
            return rest.split(None, 1)[0].lower() if rest else ":"
        return first.lower()
    return ""


def _nasm_plan_parts(asm_text: str, parts: int, force: bool) -> Optional[Tuple[List[str], List[str]]]:
    """Split asm_text into part texts, or None when it should be assembled
    whole.  Returns (part texts, labels that got aliases)."""
    text = "\n" + asm_text
    header_defines: List[str] = []
    globals_: Set[str] = set()
    externs: Set[str] = set()
    note_line: Optional[str] = None
    first_block = text.find("\nw_")
    if text.isascii():
        # Lowercasing ASCII keeps every offset, so lines are cut from the
        # original text at the positions found in the lowercased copy.
        directive_matches = _RE_NASM_DIRECTIVE_LOWER.finditer(text.lower())
    else:
        directive_matches = _RE_NASM_DIRECTIVE.finditer(text)
    for m in directive_matches:
        kind = m.group(1).lower()
        line = text[m.start():m.end()].split(";", 1)[0].strip()
        if kind == "%" or kind == "[":
            if kind == "[":
                return None
            if line.lower().startswith("%define ") and (first_block < 0 or m.start() < first_block):
                header_defines.append(line)
                continue
            return None  # preprocessor use outside the header
        if kind == "[" or kind in ("default", "bits", "cpu", "absolute", "org"):
            return None
        if kind in ("section", "segment"):
            name = line.split()[1] if len(line.split()) > 1 else ""
            if name not in (".text", ".data", ".bss", ".note.GNU-stack"):
                return None
            if name == ".note.GNU-stack":
                note_line = line
        else:
            names = {item.split(":")[0].strip() for item in line.split(None, 1)[1].split(",")}
            (globals_ if kind == "global" else externs).update(names)
    numeric_equ = {m.group(1): m.group(2) for m in _RE_NASM_NUMERIC_EQU.finditer(text)}

    # Segments between boundaries; w_ blocks of the text section may move.
    # A block can move only if nothing runs into it (the text before it ends
    # in ret/jmp, not a label) and it does not run out of it.
    segments: List[Tuple[int, int, Optional[str]]] = []  # (start, end, block name)
    section = None
    previous = 0
    previous_name: Optional[str] = None
    for m in _RE_NASM_BOUNDARY.finditer(text):
        segments.append((previous, m.start(), previous_name))
        previous = m.start()
        previous_name = None
        if m.group(2) is not None:
            section = m.group(2)
        elif m.group(1) is not None and section == ".text":
            previous_name = m.group(1)
    segments.append((previous, len(text), previous_name))

    blocks: List[Tuple[int, int, int]] = []  # (start, end, code lines) of movable blocks
    terminated = True
    total_code = 0
    for seg_start, seg_end, name in segments:
        segment = text[seg_start:seg_end]
        code_lines = segment.count("\n")  # a line count is enough for balancing
        total_code += code_lines
        last = _nasm_last_code(segment)
        if name is not None:
            exits = last in _NASM_TERMINATORS
            if terminated and exits and name not in globals_:
                code = _RE_NASM_COMMENT.sub("", segment) if ";" in segment else segment
                movable = not ("$$" in code or '"' in code or "'" in code or "`" in code
                               or not _NASM_UNMOVABLE_WORDS.isdisjoint(code.lower().replace(",", " ").split()))
                if movable and globals_:
                    # An exported label stays in part 0 (a substring match is
                    # enough: a false hit only keeps the block there).
                    movable = not any(f"{name}:" in code for name in globals_)
                if movable and externs:
                    movable = externs.isdisjoint(_RE_NASM_IDENT.findall(code))
                if movable:
                    blocks.append((seg_start, seg_end, code_lines))
            terminated = exits
        elif last:
            if last in ("section", "segment"):
                continue
            terminated = last in _NASM_TERMINATORS

    movable_lines = sum(block[2] for block in blocks)
    if movable_lines == 0 or (not force and movable_lines < _NASM_PARALLEL_MIN_LINES):
        return None

    # Balance: largest block first, each to the part with the fewest lines so
    # far (part 0 starts with everything that stays).
    loads = [total_code - movable_lines] + [0] * (parts - 1)
    assignment: Dict[int, int] = {}
    for index in sorted(range(len(blocks)), key=lambda idx: -blocks[idx][2]):
        part = min(range(parts), key=lambda candidate: (loads[candidate], candidate))
        assignment[index] = part
        loads[part] += blocks[index][2]
    used = sorted(set(assignment.values()) - {0})
    if not used:
        return None

    pieces: Dict[int, List[str]] = {part: [] for part in [0] + used}
    position = 0
    for index, (start, end, _count) in enumerate(blocks):
        part = assignment[index]
        if part == 0:
            continue
        pieces[0].append(text[position:start])
        pieces[part].append(text[start:end])
        position = end
    pieces[0].append(text[position:])
    bodies = {part: "".join(chunks) for part, chunks in pieces.items()}
    bodies[0] = bodies[0][1:]  # the newline prepended for scanning

    owner: Dict[str, int] = {}
    for part, body in bodies.items():
        for m in _RE_NASM_LABEL_LINE.finditer(body):
            label = m.group(2)
            if label in owner:
                return None
            owner[label] = part
    imports: Dict[int, List[str]] = {}
    mentioned: Dict[int, Set[str]] = {}
    aliased: Set[str] = set()
    for part, body in bodies.items():
        names = set(_RE_NASM_IDENT.findall(_RE_NASM_COMMENT.sub("", body)))
        mentioned[part] = names
        wanted = sorted(name for name in names if owner.get(name, part) != part)
        imports[part] = wanted
        aliased.update(wanted)

    texts: List[str] = []
    for part in [0] + used:
        out: List[str] = []
        if part != 0:
            out.extend(header_defines)
            out.extend(f"{name} equ {numeric_equ[name]}" for name in sorted(mentioned[part] & numeric_equ.keys()))
        for name in imports[part]:
            out.append(f"extern {_NASM_PART_ALIAS}{name}")
            out.append(f"%define {name} {_NASM_PART_ALIAS}{name}")
        exported = sorted(name for name in aliased if owner.get(name) == part)
        out.extend(f"global {_NASM_PART_ALIAS}{name}:hidden" for name in exported)
        if part != 0:
            out.append("section .text")
        out.append(bodies[part])
        if part != 0 and note_line is not None:
            out.append(note_line)
        # Each alias is the label itself (same section and offset).
        out.extend(f"{_NASM_PART_ALIAS}{name} equ {name}" for name in exported)
        texts.append("\n".join(out) + "\n")
    return texts, sorted(aliased)


def _run_nasm_parallel(asm_path: Path, obj_path: Path, asm_text: str) -> bool:
    """Assemble asm_text in parallel parts into obj_path.  False when the
    file is not split (small, or not safely splittable) or anything about
    the parallel run differs from a clean assembly; the caller then runs
    nasm on the whole file."""
    mode = os.environ.get("L2_NASM_PARALLEL", "").strip().lower()
    if mode == "0":
        return False
    parts = min(_NASM_PARALLEL_MAX_PARTS, os.cpu_count() or 1)
    if parts < 2:
        return False
    try:
        plan = _nasm_plan_parts(asm_text, parts, force=(mode == "force"))
    except Exception:
        return False
    if plan is None:
        return False
    texts, _aliases = plan
    nasm = _find_nasm()
    count = len(texts)
    part_asm = [asm_path.with_name(f"{asm_path.stem}.part{index}.asm") for index in range(count)]
    part_obj = [obj_path.with_name(f"{obj_path.stem}.part{index}.o") for index in range(count)]
    part_out = [obj_path.with_name(f"{obj_path.stem}.part{index}.out") for index in range(count)]
    try:
        pids = []
        for src, obj, out, text in zip(part_asm, part_obj, part_out, texts):
            src.write_text(text)
            fd = os.open(out, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
            try:
                pids.append(os.posix_spawn(nasm, [nasm, "-f", "elf64", "-o", str(obj), str(src)], os.environ,
                                           file_actions=[(os.POSIX_SPAWN_DUP2, fd, 1),
                                                         (os.POSIX_SPAWN_DUP2, fd, 2)]))
            finally:
                os.close(fd)
        clean = True
        for pid in pids:
            _, status = os.waitpid(pid, 0)
            if not (os.WIFEXITED(status) and os.WEXITSTATUS(status) == 0):
                clean = False
        if not clean or any(out.stat().st_size for out in part_out):
            return False
        linker, _use_lld = _find_linker()
        fd = os.open(part_out[0], os.O_WRONLY | os.O_TRUNC)
        try:
            pid = os.posix_spawn(linker, [linker, "-r", "-o", str(obj_path), *map(str, part_obj)], os.environ,
                                 file_actions=[(os.POSIX_SPAWN_DUP2, fd, 1), (os.POSIX_SPAWN_DUP2, fd, 2)])
        finally:
            os.close(fd)
        _, status = os.waitpid(pid, 0)
        return os.WIFEXITED(status) and os.WEXITSTATUS(status) == 0 and part_out[0].stat().st_size == 0
    except OSError:
        return False
    finally:
        for path in (*part_asm, *part_obj, *part_out):
            try:
                path.unlink()
            except OSError:
                pass


def run_linker(obj_path: Path, exe_path: Path, debug: bool = False, libs=None, *, shared: bool = False):
    libs = libs or []

    linker, use_lld = _find_linker()

    cmd = [linker]

    if use_lld:
        cmd.extend(["-m", "elf_x86_64"])

    if shared:
        cmd.append("-shared")

    cmd.extend([
        "-o", str(exe_path),
        str(obj_path),
    ])

    if not shared and not libs:
        cmd.extend(["-nostdlib", "-static"])

    if libs:
        # Determine if any libs require dynamic linking (shared libraries).
        needs_dynamic = any(
            not (str(lib).endswith(".a") or str(lib).endswith(".o"))
            for lib in libs if lib
        )
        if not shared and needs_dynamic:
            cmd.extend([
                "-dynamic-linker", "/lib64/ld-linux-x86-64.so.2",
            ])
        # Add standard library search paths so ld.lld can find libc etc.
        for lib_dir in ["/usr/lib/x86_64-linux-gnu", "/usr/lib64", "/lib/x86_64-linux-gnu"]:
            if os.path.isdir(lib_dir):
                cmd.append(f"-L{lib_dir}")
        for lib in libs:
            if not lib:
                continue
            lib = str(lib)
            if lib.startswith(("-L", "-l", "-Wl,")):
                cmd.append(lib)
                continue
            if lib.startswith(":"):
                cmd.append(f"-l{lib}")
                continue
            if os.path.isabs(lib) or lib.startswith("./") or lib.startswith("../"):
                cmd.append(lib)
                continue
            if os.path.sep in lib or lib.endswith(".a"):
                cmd.append(lib)
                continue
            if ".so" in lib:
                cmd.append(f"-l:{lib}")
                continue
            cmd.append(f"-l{lib}")

    if debug:
        cmd.append("-g")

    _run_cmd(cmd)


def _render_source_embed_asm(source_text: str) -> str:
    payload = source_text.encode("utf-8")
    db_bytes = payload + b"\0"
    lines: List[str] = [
        "section .data",
        "global l2_source_embed",
        "global l2_source_embed_len",
        "align 8",
        "l2_source_embed:",
    ]
    chunk_size = 16
    for idx in range(0, len(db_bytes), chunk_size):
        chunk = db_bytes[idx:idx + chunk_size]
        encoded = ", ".join(f"0x{byte:02x}" for byte in chunk)
        lines.append(f"    db {encoded}")
    lines.extend(
        [
            "align 8",
            "l2_source_embed_len:",
            f"    dq {len(payload)}",
        ]
    )
    return "\n".join(lines) + "\n"


def _render_source_catalog_asm(catalog: Sequence[Tuple[str, str]]) -> str:
    """The selected-definition source catalog: a count followed by
    (name pointer, name bytes, source pointer, source bytes) records, sorted
    by name.  The layout is private to the runtime lookup in main.c."""
    lines: List[str] = ["section .data", "global l2_source_catalog", "align 8", "l2_source_catalog:",
                        f"    dq {len(catalog)}"]
    for index in range(len(catalog)):
        name, source = catalog[index]
        lines.append(f"    dq l2_srccat_name_{index}, {len(name.encode('utf-8'))}, "
                     f"l2_srccat_src_{index}, {len(source.encode('utf-8'))}")
    for index, (name, source) in enumerate(catalog):
        for label, text in ((f"l2_srccat_name_{index}", name), (f"l2_srccat_src_{index}", source)):
            data = text.encode("utf-8") + b"\0"
            lines.append(f"{label}:")
            for start in range(0, len(data), 32):
                lines.append("    db " + ", ".join(str(byte) for byte in data[start:start + 32]))
    return "\n".join(lines) + "\n"


def _append_source_embed_to_asm(asm_text: str, source_text: Optional[str],
                                catalog: Optional[Sequence[Tuple[str, str]]] = None) -> str:
    blocks: List[str] = []
    if source_text and "l2_source_embed:" not in asm_text:
        blocks.append(_render_source_embed_asm(source_text))
    if catalog is not None and "l2_source_catalog:" not in asm_text:
        blocks.append(_render_source_catalog_asm(catalog))
    if not blocks:
        return asm_text
    trimmed = asm_text.rstrip()
    joined = "\n".join(blocks)
    return f"{trimmed}\n\n{joined}" if trimmed else joined


def build_static_library(obj_path: Path, archive_path: Path) -> None:
    import subprocess
    parent = archive_path.parent
    if parent and not parent.exists():
        parent.mkdir(parents=True, exist_ok=True)
    subprocess.run(["ar", "rcs", str(archive_path), str(obj_path)], check=True)


def _load_sidecar_meta_libs(source: Path) -> List[str]:
    """Return additional linker libs from sibling <source>.meta.json."""
    meta_path = source.with_suffix(".meta.json")
    if not meta_path.exists():
        return []
    ct_run_exit_code = 0
    try:
        import json
        payload = json.loads(meta_path.read_text())
    except Exception as exc:
        print(f"[warn] failed to read {meta_path}: {exc}")
        return []
    libs = payload.get("libs")
    if not isinstance(libs, list):
        return []
    out: List[str] = []
    for item in libs:
        if isinstance(item, str) and item:
            out.append(item)
    return out


def _build_ct_sidecar_shared(source: Path, temp_dir: Path) -> Optional[Path]:
    """Build sibling <source>.c into a shared object for --ct-run-main externs."""
    c_path = source.with_suffix(".c")
    if not c_path.exists():
        return None
    temp_dir.mkdir(parents=True, exist_ok=True)
    so_path = temp_dir / f"{source.stem}.ctlib.so"
    cmd = ["cc", "-shared", "-fPIC", str(c_path), "-o", str(so_path)]
    import subprocess
    subprocess.run(cmd, check=True)
    return so_path


# ---------------------------------------------------------------------------
# § 19. REPL
# ---------------------------------------------------------------------------

def run_repl(
    compiler: Compiler,
    temp_dir: Path,
    libs: Sequence[str],
    debug: bool = False,
    initial_source: Optional[Path] = None,
) -> int:
    """REPL backed by the compile-time VM for instant execution.

    State (data stack, memory, definitions) persists across evaluations.
    Use ``:reset`` to start fresh.
    """

    # -- Colors ---------------------------------------------------------------
    _C_RESET = "\033[0m"
    _C_BOLD = "\033[1m"
    _C_DIM = "\033[2m"
    _C_GREEN = "\033[32m"
    _C_CYAN = "\033[36m"
    _C_YELLOW = "\033[33m"
    _C_RED = "\033[31m"
    _C_MAGENTA = "\033[35m"

    use_color = sys.stdout.isatty()
    def _c(code: str, text: str) -> str:
        return f"{code}{text}{_C_RESET}" if use_color else text

    # -- Helpers --------------------------------------------------------------
    def _block_defines_main(block: str) -> bool:
        stripped_lines = [ln.strip() for ln in block.splitlines() if ln.strip() and not ln.strip().startswith("#")]
        for idx, stripped in enumerate(stripped_lines):
            for prefix in ("word", ":asm", ":py", "extern"):
                if stripped.startswith(f"{prefix} "):
                    rest = stripped[len(prefix):].lstrip()
                    if rest.startswith("main"):
                        return True
            if stripped == "word" and idx + 1 < len(stripped_lines):
                if stripped_lines[idx + 1].startswith("main"):
                    return True
        return False

    temp_dir.mkdir(parents=True, exist_ok=True)
    src_path = temp_dir / "repl.sl"
    editor_cmd = os.environ.get("EDITOR") or "vim"

    default_imports = ["import stdlib/stdlib.sl", "import stdlib/io.sl"]
    imports: List[str] = list(default_imports)
    user_defs_files: List[str] = []
    user_defs_repl: List[str] = []
    main_body: List[str] = []
    has_user_main = False

    include_paths = list(compiler.include_paths)

    if initial_source is not None:
        try:
            initial_text = initial_source.read_text()
            user_defs_files.append(initial_text)
            has_user_main = has_user_main or _block_defines_main(initial_text)
            if has_user_main:
                main_body.clear()
            print(_c(_C_DIM, f"[repl] loaded {initial_source}"))
        except Exception as exc:
            print(_c(_C_RED, f"[repl] failed to load {initial_source}: {exc}"))

    # -- Persistent VM execution ----------------------------------------------
    def _run_on_ct_vm(source: str, word_name: str = "main") -> bool:
        """Parse source and execute *word_name* via the compile-time VM.

        Uses ``invoke_repl`` so stacks/memory persist across calls.
        Returns True on success, False on error (already printed).
        """
        nonlocal compiler
        src_path.write_text(source)
        try:
            _suppress_redefine_warnings_set(True)
            compiler._loaded_files.clear()
            compiler.parse_file(src_path)
        except (ParseError, CompileError, CompileTimeError) as exc:
            print(_c(_C_RED, f"[error] {exc}"))
            return False
        except Exception as exc:
            print(_c(_C_RED, f"[error] parse failed: {exc}"))
            return False
        finally:
            _suppress_redefine_warnings_set(False)

        try:
            compiler.run_compile_time_word_repl(word_name, libs=list(libs))
        except (CompileTimeError, _CTVMExit) as exc:
            if isinstance(exc, _CTVMExit):
                code = exc.code
                if code != 0:
                    print(_c(_C_YELLOW, f"[warn] program exited with code {code}"))
            else:
                print(_c(_C_RED, f"[error] {exc}"))
                return False
        except Exception as exc:
            print(_c(_C_RED, f"[error] execution failed: {exc}"))
            return False
        return True

    # -- Stack display --------------------------------------------------------
    def _show_stack() -> None:
        vm = compiler.parser.compile_time_vm
        values = vm.repl_stack_values()
        if not values:
            print(_c(_C_DIM, "<empty stack>"))
        else:
            parts = []
            for v in values:
                if v < 0:
                    v = v + (1 << 64)  # show as unsigned
                    parts.append(f"{v} (0x{v:x})")
                elif v > 0xFFFF:
                    parts.append(f"{v} (0x{v:x})")
                else:
                    parts.append(str(v))
            depth_str = _c(_C_DIM, f"<{len(values)}>")
            print(f"{depth_str} {' '.join(parts)}")

    # -- Word listing ---------------------------------------------------------
    def _show_words(filter_str: str = "") -> None:
        all_words = compiler.dictionary.names()
        if filter_str:
            all_words = [w for w in all_words if filter_str in w]
        if not all_words:
            print(_c(_C_DIM, "no matching words"))
            return
        # Print in columns
        max_len = max(len(w) for w in all_words) + 2
        cols = max(1, 80 // max_len)
        for i in range(0, len(all_words), cols):
            row = all_words[i:i + cols]
            print("  ".join(w.ljust(max_len) for w in row))
        print(_c(_C_DIM, f"({len(all_words)} words)"))

    # -- Word type/info -------------------------------------------------------
    def _show_type(word_name: str) -> None:
        word = compiler.dictionary.lookup(word_name)
        if word is None:
            print(_c(_C_RED, f"word '{word_name}' not found"))
            return

        # Header: name + kind
        defn = word.definition
        if word.is_extern:
            kind = "extern"
        elif word.macro_def is not None:
            kind = "macro"
        elif isinstance(defn, AsmDefinition):
            kind = "asm"
        elif isinstance(defn, Definition):
            kind = "word"
        elif word.compile_time_intrinsic is not None or word.runtime_intrinsic is not None:
            kind = "builtin"
        elif word.macro is not None:
            kind = "immediate/macro"
        else:
            kind = "unknown"
        print(f"  {_c(_C_BOLD, word_name)}  {_c(_C_CYAN, kind)}")

        # Tags
        tags: List[str] = []
        if word.immediate:
            tags.append("immediate")
        if word.compile_only:
            tags.append("compile-only")
        if word.runtime_only:
            tags.append("runtime-only")
        if word.inline:
            tags.append("inline")
        if word.compile_time_override:
            tags.append("ct-override")
        if word.priority != 0:
            tags.append(f"priority={word.priority}")
        if tags:
            print(f"  {_c(_C_DIM, '  tags: ')}{_c(_C_YELLOW, ' '.join(tags))}")

        # Extern signature
        if word.is_extern and word.extern_signature:
            arg_types, ret_type = word.extern_signature
            sig = f"{ret_type} {word_name}({', '.join(arg_types)})"
            print(f"  {_c(_C_DIM, '  sig:  ')}{_c(_C_GREEN, sig)}")
        elif word.is_extern:
            print(f"  {_c(_C_DIM, '  args: ')}{word.extern_inputs} in, {word.extern_outputs} out")

        # Stack effect from definition comment
        if isinstance(defn, Definition) and defn.stack_inputs is not None:
            print(f"  {_c(_C_DIM, '  args: ')}{defn.stack_inputs} inputs")

        # Macro expansion
        if word.macro_def is not None:
            params = word.macro_def.params
            body = " ".join(word.macro_def.body_tokens.lexemes())
            if len(body) > 80:
                body = body[:77] + "..."
            param_str = f" ({' '.join(params)})" if params else ""
            print(f"  {_c(_C_DIM, '  body:   ')}{param_str} {body}")

        # Asm body (trimmed)
        if isinstance(defn, AsmDefinition):
            body = defn.body.strip()
            lines = body.splitlines()
            if defn.effects:
                print(f"  {_c(_C_DIM, '  effects:')} {' '.join(sorted(defn.effects))}")
            if len(lines) <= 6:
                for ln in lines:
                    print(f"    {_c(_C_DIM, ln.rstrip())}")
            else:
                for ln in lines[:4]:
                    print(f"    {_c(_C_DIM, ln.rstrip())}")
                print(f"    {_c(_C_DIM, f'... ({len(lines)} lines total)')}")

        # Word body (decompiled ops)
        if isinstance(defn, Definition):
            ops = defn.body
            indent = 0
            max_show = 12
            shown = 0
            for op in ops:
                if shown >= max_show:
                    print(f"    {_c(_C_DIM, f'... ({len(ops)} ops total)')}")
                    break
                if op.op in ("branch_zero", "for_begin", "while_begin", "list_begin"):
                    pass
                if op.op in ("jump", "for_end"):
                    indent = max(0, indent - 1)

                if op.op == "literal":
                    if isinstance(op.data, str):
                        txt = f'"{op.data}"' if len(op.data) <= 40 else f'"{op.data[:37]}..."'
                        line_str = f"  {txt}"
                    elif isinstance(op.data, float):
                        line_str = f"  {op.data}"
                    else:
                        line_str = f"  {op.data}"
                elif op.op == "word":
                    line_str = f"  {op.data}"
                elif op.op == "branch_zero":
                    line_str = "  if"
                    indent += 1
                elif op.op == "jump":
                    line_str = "  else/end"
                elif op.op == "for_begin":
                    line_str = "  for"
                    indent += 1
                elif op.op == "for_end":
                    line_str = "  end-for"
                elif op.op == "label":
                    line_str = f"  label {op.data}"
                elif op.op == "goto":
                    line_str = f"  goto {op.data}"
                else:
                    line_str = f"  {op.op}" + (f" {op.data}" if op.data is not None else "")

                print(f"  {_c(_C_DIM, '  ' * indent)}{line_str}")
                shown += 1

    # -- readline setup -------------------------------------------------------
    history_path = temp_dir / "repl_history"
    try:
        import readline
        readline.parse_and_bind("tab: complete")
        try:
            readline.read_history_file(str(history_path))
        except (FileNotFoundError, OSError):
            pass

        def _completer(text: str, state: int) -> Optional[str]:
            commands = [":help", ":show", ":reset", ":load ", ":call ",
                        ":edit ", ":seteditor ", ":quit", ":q",
                        ":stack", ":words ", ":type ", ":clear"]
            if text.startswith(":"):
                matches = [c for c in commands if c.startswith(text)]
            else:
                all_words = compiler.dictionary.names()
                matches = [w + " " for w in all_words if w.startswith(text)]
            return matches[state] if state < len(matches) else None

        readline.set_completer(_completer)
        readline.set_completer_delims(" \t\n")
        _has_readline = True
    except ImportError:
        _has_readline = False

    # -- Help -----------------------------------------------------------------
    def _print_help() -> None:
        print(_c(_C_BOLD, "[repl] commands:"))
        cmds = [
            (":help", "show this help"),
            (":stack", "display the data stack"),
            (":clear", "clear the data stack (keep definitions)"),
            (":words [filter]", "list defined words (optionally filtered)"),
            (":type <word>", "show word info / signature"),
            (":show", "display current session source"),
            (":reset", "clear everything — fresh VM and dictionary"),
            (":load <file>", "load a source file into the session"),
            (":call <word>", "execute a word via the compile-time VM"),
            (":edit [file]", "open session file or given file in editor"),
            (":seteditor [cmd]", "show/set editor command (default from $EDITOR)"),
            (":quit | :q", "exit the REPL"),
        ]
        for cmd, desc in cmds:
            print(f"  {_c(_C_GREEN, cmd.ljust(20))} {desc}")
        print(_c(_C_BOLD, "[repl] free-form input:"))
        print("  definitions (word/:asm/:py/extern/macro/struct) extend the session")
        print("  imports add to session imports")
        print("  other lines run immediately (values stay on the stack)")
        print("  multiline: end lines with \\ to continue")

    # -- Banner ---------------------------------------------------------------
    prompt = _c(_C_GREEN + _C_BOLD, "l2> ") if use_color else "l2> "
    cont_prompt = _c(_C_DIM, "... ") if use_color else "... "
    print(_c(_C_BOLD, "[repl] L2 interactive — type :help for commands, :quit to exit"))
    print(_c(_C_DIM, "[repl] state persists across evaluations; :reset to start fresh"))

    pending_block: List[str] = []

    while True:
        try:
            cur_prompt = cont_prompt if pending_block else prompt
            line = input(cur_prompt)
        except (EOFError, KeyboardInterrupt):
            print()
            break

        stripped = line.strip()
        if stripped in {":quit", ":q"}:
            break
        if stripped == ":help":
            _print_help()
            continue
        if stripped == ":stack":
            _show_stack()
            continue
        if stripped == ":clear":
            vm = compiler.parser.compile_time_vm
            if vm._repl_initialized:
                vm.r12 = vm._native_data_top
            else:
                vm.stack.clear()
            print(_c(_C_DIM, "stack cleared"))
            continue
        if stripped.startswith(":words"):
            filt = stripped.split(None, 1)[1].strip() if " " in stripped else ""
            _show_words(filt)
            continue
        if stripped.startswith(":type "):
            word_name = stripped.split(None, 1)[1].strip()
            if word_name:
                _show_type(word_name)
            else:
                print(_c(_C_RED, "[repl] usage: :type <word>"))
            continue
        if stripped == ":reset":
            imports = list(default_imports)
            user_defs_files.clear()
            user_defs_repl.clear()
            main_body.clear()
            has_user_main = False
            pending_block.clear()
            compiler = Compiler(
                include_paths=include_paths,
                macro_expansion_limit=compiler.parser.macro_expansion_limit,
                macro_preview=compiler.parser.macro_preview,
            )
            print(_c(_C_DIM, "[repl] session reset — fresh VM and dictionary"))
            continue
        if stripped.startswith(":seteditor"):
            parts = stripped.split(None, 1)
            if len(parts) == 1 or not parts[1].strip():
                print(f"[repl] editor: {editor_cmd}")
            else:
                editor_cmd = parts[1].strip()
                print(f"[repl] editor set to: {editor_cmd}")
            continue
        if stripped.startswith(":edit"):
            arg = stripped.split(None, 1)[1].strip() if " " in stripped else ""
            target_path = Path(arg) if arg else src_path
            try:
                current_source = _repl_build_source(
                    imports,
                    user_defs_files,
                    user_defs_repl,
                    main_body,
                    has_user_main,
                    force_synthetic=bool(main_body),
                )
                src_path.write_text(current_source)
            except Exception as exc:
                print(_c(_C_RED, f"[repl] failed to sync source before edit: {exc}"))
            try:
                if not target_path.exists():
                    target_path.parent.mkdir(parents=True, exist_ok=True)
                    target_path.touch()
                import shlex
                cmd_parts = shlex.split(editor_cmd)
                import subprocess
                subprocess.run([*cmd_parts, str(target_path)])
                if target_path.resolve() == src_path.resolve():
                    try:
                        updated = target_path.read_text()
                        new_imports: List[str] = []
                        non_import_lines: List[str] = []
                        for ln in updated.splitlines():
                            stripped_ln = ln.strip()
                            if stripped_ln.startswith("import "):
                                new_imports.append(stripped_ln)
                            else:
                                non_import_lines.append(ln)
                        imports = new_imports if new_imports else list(default_imports)
                        new_body = "\n".join(non_import_lines).strip()
                        user_defs_files = [new_body] if new_body else []
                        user_defs_repl.clear()
                        main_body.clear()
                        has_user_main = _block_defines_main(new_body)
                        print(_c(_C_DIM, "[repl] reloaded session source from editor"))
                    except Exception as exc:
                        print(_c(_C_RED, f"[repl] failed to reload edited source: {exc}"))
            except Exception as exc:
                print(_c(_C_RED, f"[repl] failed to launch editor: {exc}"))
            continue
        if stripped == ":show":
            source = _repl_build_source(imports, user_defs_files, user_defs_repl, main_body, has_user_main, force_synthetic=True)
            print(source.rstrip())
            continue
        if stripped.startswith(":load "):
            path_text = stripped.split(None, 1)[1].strip()
            target_path = Path(path_text)
            if not target_path.exists():
                print(_c(_C_RED, f"[repl] file not found: {target_path}"))
                continue
            try:
                loaded_text = target_path.read_text()
                user_defs_files.append(loaded_text)
                if _block_defines_main(loaded_text):
                    has_user_main = True
                    main_body.clear()
                print(_c(_C_DIM, f"[repl] loaded {target_path}"))
            except Exception as exc:
                print(_c(_C_RED, f"[repl] failed to load {target_path}: {exc}"))
            continue
        if stripped.startswith(":call "):
            word_name = stripped.split(None, 1)[1].strip()
            if not word_name:
                print(_c(_C_RED, "[repl] usage: :call <word>"))
                continue
            if word_name == "main" and not has_user_main:
                print(_c(_C_RED, "[repl] cannot call main; no user-defined main present"))
                continue
            if word_name == "main" and has_user_main:
                source = _repl_build_source(imports, user_defs_files, user_defs_repl, [], True, force_synthetic=False)
            else:
                temp_defs = [*user_defs_repl, f"word __repl_call__\n    {word_name}\nend"]
                source = _repl_build_source(imports, user_defs_files, temp_defs, [], True, force_synthetic=False)
                _run_on_ct_vm(source, "__repl_call__")
                continue
            _run_on_ct_vm(source, word_name)
            continue
        if not stripped:
            continue

        # Multiline handling via trailing backslash
        if line.endswith("\\"):
            pending_block.append(line[:-1])
            continue

        if pending_block:
            pending_block.append(line)
            block = "\n".join(pending_block)
            pending_block.clear()
        else:
            block = line

        block_stripped = block.lstrip()
        first_tok = block_stripped.split(None, 1)[0] if block_stripped else ""
        is_definition = first_tok in {"word", ":asm", ":py", "extern", "macro", "struct"}
        is_import = first_tok == "import"

        if is_import:
            imports.append(block_stripped)
        elif is_definition:
            if _block_defines_main(block):
                user_defs_repl = [d for d in user_defs_repl if not _block_defines_main(d)]
                has_user_main = True
                main_body.clear()
            user_defs_repl.append(block)
        else:
            source = _repl_build_source(
                imports,
                user_defs_files,
                user_defs_repl,
                block.splitlines(),
                has_user_main,
                force_synthetic=True,
            )
            _run_on_ct_vm(source)
            continue

        # Validate definitions by parsing (no execution needed).
        source = _repl_build_source(imports, user_defs_files, user_defs_repl, main_body, has_user_main, force_synthetic=bool(main_body))
        try:
            src_path.write_text(source)
            _suppress_redefine_warnings_set(True)
            try:
                compiler._loaded_files.clear()
                compiler.parse_file(src_path)
            finally:
                _suppress_redefine_warnings_set(False)
        except (ParseError, CompileError, CompileTimeError) as exc:
            print(_c(_C_RED, f"[error] {exc}"))
            continue

    # Save readline history
    if _has_readline:
        try:
            readline.write_history_file(str(history_path))
        except OSError:
            pass

    return 0


def _repl_build_source(
    imports: Sequence[str],
    file_defs: Sequence[str],
    repl_defs: Sequence[str],
    main_body: Sequence[str],
    has_user_main: bool,
    force_synthetic: bool = False,
) -> str:
    lines: List[str] = []
    lines.extend(imports)
    lines.extend(file_defs)
    lines.extend(repl_defs)
    if (force_synthetic or not has_user_main) and main_body:
        lines.append("word main")
        for ln in main_body:
            if ln:
                lines.append(f"    {ln}")
            else:
                lines.append("")
        lines.append("end")
    return "\n".join(lines) + "\n"


def _preview_literal_text(value: Any) -> str:
    if isinstance(value, str):
        escaped = value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
        return f'"{escaped}"'
    if isinstance(value, bool):
        return "1" if value else "0"
    if value is None:
        return "nil"
    return str(value)


def _preview_format_op(node: Op) -> str:
    kind = node.op
    data = node.data
    if kind == "literal":
        return _preview_literal_text(data)
    if kind == "word":
        return str(data)
    if kind == "word_ptr":
        return f"&{data}"
    if kind == "ret":
        return "ret"
    if kind == "label":
        return f"label {data}"
    if kind == "list_begin":
        return "["
    if kind == "list_end":
        return "]"
    if kind == "list_literal" and isinstance(data, list):
        inner = " ".join(_preview_literal_text(item) for item in data)
        return f"[ {inner} ]"
    if kind == "bss_list_literal" and isinstance(data, dict):
        values = data.get("values", [])
        size = int(data.get("size", len(values)))
        inner = " ".join(_preview_literal_text(item) for item in values)
        if size != len(values):
            return f"{{ {inner} }} :{size}"
        return f"{{ {inner} }}"
    if data is None:
        return kind
    if isinstance(data, str):
        return f"{kind} {data}"
    return f"{kind} {data!r}"


def _render_transformed_module_preview(module: Module, *, focus_names: Optional[Set[str]] = None) -> str:
    lines: List[str] = []

    if module.text_preamble:
        lines.append("# text preamble fragments")
        for line in module.text_preamble:
            lines.append(f"#   {line}")
        lines.append("")

    if module.data:
        lines.append("# data fragments")
        for line in module.data:
            lines.append(f"#   {line}")
        lines.append("")

    if module.bss is not None:
        lines.append("# runtime bss buffer")
        for line in module.bss:
            lines.append(f"#   {line}")
        lines.append("")

    for form in module.forms:
        if isinstance(form, Definition):
            if focus_names and form.name not in focus_names:
                continue
            lines.append(f"word {form.name}")
            for op in form.body:
                lines.append(f"    {_preview_format_op(op)}")
            lines.append("end")
            flags: List[str] = []
            if form.immediate:
                flags.append("immediate")
            if form.compile_only:
                flags.append("compile-only")
            if form.runtime_only:
                flags.append("runtime-only")
            if form.inline:
                flags.append("inline")
            if flags:
                lines.append(f"# flags: {' '.join(flags)}")
            lines.append("")
            continue

        if isinstance(form, AsmDefinition):
            if focus_names and form.name not in focus_names:
                continue
            lines.append(f":asm {form.name} {{")
            body_lines = form.body.splitlines() or [""]
            for body_line in body_lines:
                lines.append(f"    {body_line}")
            lines.append("}")
            lines.append(";")
            flags: List[str] = []
            if form.immediate:
                flags.append("immediate")
            if form.compile_only:
                flags.append("compile-only")
            if form.runtime_only:
                flags.append("runtime-only")
            if form.inline:
                flags.append("inline")
            if flags:
                lines.append(f"# flags: {' '.join(flags)}")
            lines.append("")
            continue

        if isinstance(form, Op):
            lines.append(_preview_format_op(form))
            continue

        lines.append(f"# unsupported form: {type(form).__name__}")

    if not lines:
        return "# (no transformed forms)\n"
    return "\n".join(lines).rstrip() + "\n"


def _render_preview_trace_events(events: Sequence[Dict[str, Any]]) -> str:
    if not events:
        return "# (no compile-time execution events)\n"

    lines: List[str] = []
    for idx, event in enumerate(events, start=1):
        kind = str(event.get("kind", "ct"))
        word = str(event.get("word", "<unknown>"))
        path = str(event.get("path", "")).strip()
        line_no = int(event.get("line", 0) or 0)
        col_no = int(event.get("column", 0) or 0)
        if path and line_no > 0:
            at = f" @{path}:{line_no}:{col_no}"
        elif line_no > 0:
            at = f" @{line_no}:{col_no}"
        else:
            at = ""
        lines.append(f"{idx}. {kind} {word}{at}")

        consumed = [str(item) for item in event.get("consumed", [])]
        if consumed:
            lines.append(f"   consumed: {' '.join(consumed)}")

        before = [str(item) for item in event.get("stack_before", [])]
        after = [str(item) for item in event.get("stack_after", [])]
        lines.append("   stack-before: " + (" | ".join(before) if before else "(empty)"))
        lines.append("   stack-after:  " + (" | ".join(after) if after else "(empty)"))

        emitted = [str(item) for item in event.get("emitted", [])]
        if emitted:
            lines.append("   emitted:")
            for item in emitted:
                lines.append(f"     - {item}")

    return "\n".join(lines).rstrip() + "\n"


# ---- Docs explorer integration (delegated to docs.py) ----

_DOCS_HELPERS_MODULE: Any = None
_DOCS_HELPERS_LOADED = False
_DOCS_HELPERS_WARNED = False
_DOCS_HELPERS_ERROR = ""


def _load_docs_helpers(*, warn: bool = False) -> Optional[Any]:
    global _DOCS_HELPERS_MODULE
    global _DOCS_HELPERS_LOADED
    global _DOCS_HELPERS_WARNED
    global _DOCS_HELPERS_ERROR

    if not _DOCS_HELPERS_LOADED:
        _DOCS_HELPERS_LOADED = True
        docs_path = Path(__file__).with_name("docs.py")
        if docs_path.exists():
            spec = None
            try:
                spec = importlib.util.spec_from_file_location("l2_docs_helpers", docs_path)
                if spec is None or spec.loader is None:
                    raise RuntimeError("unable to create module spec")
                module = importlib.util.module_from_spec(spec)
                sys.modules[spec.name] = module
                spec.loader.exec_module(module)
                if hasattr(module, "configure_runtime"):
                    module.configure_runtime(ct_word_metadata_provider=_collect_ct_word_metadata)
                _DOCS_HELPERS_MODULE = module
                _DOCS_HELPERS_ERROR = ""
            except Exception as exc:
                if spec is not None and getattr(spec, "name", None):
                    sys.modules.pop(spec.name, None)
                _DOCS_HELPERS_MODULE = None
                _DOCS_HELPERS_ERROR = f"failed to import docs.py: {exc}"
        else:
            _DOCS_HELPERS_MODULE = None
            _DOCS_HELPERS_ERROR = "docs.py not found"

    if warn and _DOCS_HELPERS_MODULE is None and not _DOCS_HELPERS_WARNED:
        _DOCS_HELPERS_WARNED = True
        if _DOCS_HELPERS_ERROR:
            sys.stderr.write(f"[warn] docs helpers unavailable ({_DOCS_HELPERS_ERROR})\n")
        else:
            sys.stderr.write("[warn] docs helpers unavailable\n")

    return _DOCS_HELPERS_MODULE


def _collect_ct_word_metadata() -> List[Dict[str, Any]]:
    dictionary = bootstrap_dictionary()
    out: List[Dict[str, Any]] = []
    for name, word in dictionary.words.items():
        if not is_ct_api_word(name, word):
            continue
        out.append(
            {
                "name": name,
                "compile_only": bool(word.compile_only),
                "immediate": bool(word.immediate),
                "runtime_only": bool(word.runtime_only),
                "has_runtime_intrinsic": bool(word.runtime_intrinsic is not None),
            }
        )
    out.sort(key=lambda item: str(item["name"]).lower())
    return out


def _build_ct_ref_complete_summary_table(base_doc_text: str) -> str:
    docs_helpers = _load_docs_helpers(warn=False)
    if docs_helpers is None or not hasattr(docs_helpers, "build_ct_reference_bundle"):
        return ""
    bundle = docs_helpers.build_ct_reference_bundle(base_doc_text, _collect_ct_word_metadata())
    return str(bundle.get("summary_text", ""))


def _build_ct_ref_function_appendix(base_doc_text: str) -> str:
    docs_helpers = _load_docs_helpers(warn=False)
    if docs_helpers is None or not hasattr(docs_helpers, "build_ct_reference_bundle"):
        return ""
    bundle = docs_helpers.build_ct_reference_bundle(base_doc_text, _collect_ct_word_metadata())
    return str(bundle.get("appendix_text", ""))


# A file can only declare a macro or constant if it mentions `macro` or
# `const` (as a whole word); other files are not parsed for --docs.
_DOCS_DEFINITION_HINT_RE = re.compile(r"(?<![\w.-])(?:macro|const)(?![\w.-])")
# path -> (identity of every file its parse loaded, rows): --docs reloads
# reuse the rows of files whose parse inputs are unchanged.
_DEFINITION_METADATA_CACHE: Dict[str, Tuple[Tuple[Tuple[str, Tuple[int, int, int, int]], ...],
                                             List[Dict[str, Any]]]] = {}


def _definition_metadata_cached(target: str) -> Optional[List[Dict[str, Any]]]:
    entry = _DEFINITION_METADATA_CACHE.get(target)
    if entry is None:
        return None
    identities, rows = entry
    for dep, identity in identities:
        try:
            if _file_identity(os.stat(dep)) != identity:
                return None
        except OSError:
            return None
    return rows


def _collect_definition_metadata(files: Sequence[Path]) -> List[Dict[str, Any]]:
    """The macros and constants each file defines, read from a parse of
    the file: name, kind (macro/const), parameters as the stack-effect text,
    `doc` metadata, declaration source, path and line."""
    rows: List[Dict[str, Any]] = []
    for path in files:
        try:
            resolved = Path(path).resolve()
            source_text = resolved.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        if not _DOCS_DEFINITION_HINT_RE.search(source_text):
            continue
        target = str(resolved)
        cached = _definition_metadata_cached(target)
        if cached is not None:
            rows.extend(cached)
            continue
        file_rows = _parse_definition_metadata(target)
        if file_rows is not None:
            rows.extend(file_rows)
    return rows


def _parse_definition_metadata(target: str) -> Optional[List[Dict[str, Any]]]:
    """Parse target (and its imports) and return its macro/const rows, or
    None when it does not parse.  The rows are cached against the identity
    of every file the parse read."""
    rows: List[Dict[str, Any]] = []
    compiler = Compiler()
    text = f"import {_l2_string_literal(target)}\n"
    try:
        tokens = compiler.reader.tokenize(text, None, "<docs>")
        compiler._parse_seen = set()
        compiler.parser.file_spans = []
        compiler.parser._warm_pause = True
        compiler.parser.parse(tokens, text)
    except Exception:
        return None
    dictionary = compiler.dictionary
    for name, (const_token, _name_token, value_token) in dictionary.pending_consts.items():
        origin = const_token.origin
        if origin.path != target:
            continue
        rows.append({"name": name, "kind": "const", "stack_effect": f"-> {value_token.lexeme}",
                     "doc": None, "path": target, "line": origin.start_line,
                     "source": f"const {name} {value_token.lexeme}"})
    for name, word in dictionary.words.items():
        macro = word.macro_def
        token = word.source_origin
        if macro is None or not isinstance(token, Token):
            continue
        origin = token.origin
        if origin.path != target:
            continue
        source_text = word.source_text or ""
        metadata = macro.metadata if isinstance(macro.metadata, dict) else {}
        doc = metadata.get("doc") if isinstance(metadata.get("doc"), str) else None
        if source_text.startswith("const "):
            kind, effect = "const", "-> " + source_text.split(None, 2)[-1].strip()
        else:
            kind = "macro"
            effect = f"macro ({' '.join(macro.params)})" if macro.params else "macro"
        rows.append({"name": name, "kind": kind, "stack_effect": effect, "doc": doc,
                     "path": target, "line": origin.start_line, "source": source_text})
    identities = []
    for dep in sorted(str(p) for p in compiler._parse_seen | {Path(target)}):
        try:
            identities.append((dep, _file_identity(os.stat(dep))))
        except OSError:
            return rows  # changed while parsing: do not cache
    _DEFINITION_METADATA_CACHE[target] = (tuple(identities), rows)
    return rows


def run_docs_explorer(
    *,
    source: Optional[Path],
    include_paths: Sequence[Path],
    explicit_roots: Sequence[Path],
    initial_query: str,
    include_undocumented: bool = False,
    include_private: bool = False,
    include_tests: bool = False,
) -> int:
    docs_helpers = _load_docs_helpers(warn=True)
    if docs_helpers is None:
        reason = _DOCS_HELPERS_ERROR or "failed to import docs.py"
        raise CompileError(f"docs mode unavailable: {reason}", code="tool-unavailable")
    if not hasattr(docs_helpers, "run_docs_cli"):
        raise CompileError("docs mode unavailable: docs.py missing run_docs_cli", code="tool-unavailable")
    if hasattr(docs_helpers, "configure_definition_metadata"):
        docs_helpers.configure_definition_metadata(_collect_definition_metadata)
    try:
        return int(
            docs_helpers.run_docs_cli(
                source=source,
                include_paths=include_paths,
                explicit_roots=explicit_roots,
                initial_query=initial_query,
                include_undocumented=include_undocumented,
                include_private=include_private,
                include_tests=include_tests,
                ct_word_metadata_provider=_collect_ct_word_metadata,
            )
        )
    except Exception as exc:
        raise CompileError(f"docs mode failed: {exc}", code="tool-unavailable") from exc


def run_docs_server(
    *,
    source: Optional[Path],
    include_paths: Sequence[Path],
    explicit_roots: Sequence[Path],
    initial_query: str,
    include_undocumented: bool = False,
    include_private: bool = False,
    include_tests: bool = False,
    host: str = "127.0.0.1",
    port: int = 8008,
    open_browser: bool = True,
) -> int:
    docs_helpers = _load_docs_helpers(warn=True)
    if docs_helpers is None:
        reason = _DOCS_HELPERS_ERROR or "failed to import docs.py"
        raise CompileError(f"docs serve mode unavailable: {reason}", code="tool-unavailable")
    if not hasattr(docs_helpers, "run_docs_serve"):
        raise CompileError("docs serve mode unavailable: docs.py missing run_docs_serve", code="tool-unavailable")
    if hasattr(docs_helpers, "configure_definition_metadata"):
        docs_helpers.configure_definition_metadata(_collect_definition_metadata)
    try:
        return int(
            docs_helpers.run_docs_serve(
                source=source,
                include_paths=include_paths,
                explicit_roots=explicit_roots,
                initial_query=initial_query,
                include_undocumented=include_undocumented,
                include_private=include_private,
                include_tests=include_tests,
                host=host,
                port=port,
                open_browser=open_browser,
                ct_word_metadata_provider=_collect_ct_word_metadata,
            )
        )
    except Exception as exc:
        raise CompileError(f"docs serve mode failed: {exc}", code="tool-unavailable") from exc


# ---------------------------------------------------------------------------
# § 20. Integrity checks (--check-integrity)
# ---------------------------------------------------------------------------

def _integrity_opcode_symbols() -> Set[str]:
    return {
        name
        for name, value in globals().items()
        if name.startswith("OP_") and isinstance(value, int) and name != "OP_OTHER"
    }


def _integrity_symbols_in_object(obj: Any) -> Set[str]:
    try:
        import inspect
        source = inspect.getsource(obj)
    except Exception:
        return set()
    try:
        tree = ast.parse(textwrap.dedent(source))
    except SyntaxError:
        return set()
    seen: Set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id.startswith("OP_"):
            seen.add(node.id)
    return seen


def _integrity_load_ct_reference_text() -> str:
    """Load `_L2_CT_REF_TEXT` from docs.py `_run_docs_tui` assignments."""
    docs_path = Path(__file__).with_name("docs.py")
    if not docs_path.exists():
        return ""

    try:
        source = docs_path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return ""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return ""

    fn_node: Optional[ast.FunctionDef] = None
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == "_run_docs_tui":
            fn_node = node
            break
    if fn_node is None:
        return ""

    env: Dict[str, str] = {}

    def _eval_expr(node: ast.AST) -> Optional[str]:
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return node.value
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            left = _eval_expr(node.left)
            right = _eval_expr(node.right)
            if left is None or right is None:
                return None
            return left + right
        if isinstance(node, ast.Name):
            return env.get(node.id)
        if isinstance(node, ast.Call):
            func = node.func
            if (
                isinstance(func, ast.Attribute)
                and isinstance(func.value, ast.Name)
                and func.value.id == "textwrap"
                and func.attr == "indent"
                and len(node.args) >= 2
            ):
                text = _eval_expr(node.args[0])
                prefix = _eval_expr(node.args[1])
                if isinstance(text, str) and isinstance(prefix, str):
                    return textwrap.indent(text, prefix)
            return None
        return None

    for stmt in fn_node.body:
        if not isinstance(stmt, ast.Assign):
            continue
        value = _eval_expr(stmt.value)
        if not isinstance(value, str):
            continue
        for target in stmt.targets:
            if not isinstance(target, ast.Name):
                continue
            env[target.id] = value
            if target.id == "_L2_CT_REF_TEXT":
                return value
    return ""


def _integrity_doc_has_word_entry(doc_text: str, word_name: str) -> bool:
    pattern = re.compile(rf"(?m)^\s{{2,}}{re.escape(word_name)}(?:\s+|$)")
    return pattern.search(doc_text) is not None


def _run_integrity_compile_time_docs_checks(errors: List[str]) -> None:
    doc_text = _integrity_load_ct_reference_text()
    if not doc_text.strip():
        errors.append("failed to load built-in compile-time reference text")
        return

    docs_helpers = _load_docs_helpers(warn=False)
    summary_text = ""
    appendix_text = ""
    entries: List[Dict[str, Any]] = []

    try:
        if docs_helpers is not None and hasattr(docs_helpers, "build_ct_reference_bundle"):
            bundle = docs_helpers.build_ct_reference_bundle(
                doc_text,
                _collect_ct_word_metadata(),
            )
            summary_text = str(bundle.get("summary_text", ""))
            appendix_text = str(bundle.get("appendix_text", ""))
            entries = [dict(item) for item in bundle.get("entries", [])]
        else:
            summary_text = _build_ct_ref_complete_summary_table(doc_text)
            appendix_text = _build_ct_ref_function_appendix(doc_text)
    except Exception as exc:
        errors.append(f"failed to build generated compile-time reference sections: {exc}")
        return

    full_text = doc_text + summary_text + appendix_text

    dictionary = bootstrap_dictionary()
    registered_ct_words = sorted(
        name
        for name, word in dictionary.words.items()
        if is_ct_api_word(name, word)
    )
    missing_docs = [name for name in registered_ct_words if not _integrity_doc_has_word_entry(full_text, name)]
    if missing_docs:
        errors.append(
            "compile-time reference missing registered compile-time words: "
            + ", ".join(missing_docs)
        )

    missing_summary = [
        name
        for name in registered_ct_words
        if re.search(rf"(?m)^[ \t]{{2,}}{re.escape(name)}[ \t]{{2,}}", summary_text) is None
    ]
    if missing_summary:
        errors.append(
            "compile-time summary table missing CT words: "
            + ", ".join(missing_summary)
        )

    missing_appendix = [
        name
        for name in registered_ct_words
        if re.search(rf"(?m)^[ \t]{{2,}}{re.escape(name)}(?:[ \t]{{2,}}|$)", appendix_text) is None
    ]
    if missing_appendix:
        errors.append(
            "compile-time appendix missing CT words: "
            + ", ".join(missing_appendix)
        )

    if entries:
        bad_names = {"word", "call:", "->", "*", "overview:", "example:", "category:"}
        bad_present = sorted(
            name for name in {str(item.get("name", "")).strip().lower() for item in entries}
            if name in bad_names
        )
        if bad_present:
            errors.append(
                "compile-time entry catalog contains noisy/non-function names: "
                + ", ".join(bad_present)
            )

        entry_names = {str(item.get("name", "")).strip() for item in entries}
        missing_entry_records = [name for name in registered_ct_words if name not in entry_names]
        if missing_entry_records:
            errors.append(
                "compile-time entry catalog missing registered words: "
                + ", ".join(missing_entry_records)
            )

        for item in entries:
            name = str(item.get("name", "")).strip()
            if not name:
                errors.append("compile-time entry catalog contains blank name")
                continue
            overview = str(item.get("overview", "")).strip()
            example = str(item.get("example", "")).strip()
            stack_effect = str(item.get("stack_effect", "")).strip()
            examples = item.get("examples")
            category = str(item.get("category", "")).strip()
            if not overview:
                errors.append(f"compile-time entry '{name}' is missing overview text")
            if not stack_effect:
                errors.append(f"compile-time entry '{name}' is missing stack effect")
            if not example:
                errors.append(f"compile-time entry '{name}' is missing example text")
            if not isinstance(examples, list) or len(examples) != 1:
                errors.append(f"compile-time entry '{name}' must have exactly one curated example")
            if not category:
                errors.append(f"compile-time entry '{name}' is missing category")

            if "..." in example:
                errors.append(f"compile-time entry '{name}' example still uses placeholder ellipsis")
            if example == name:
                errors.append(f"compile-time entry '{name}' example should include an explicit usage context")
            if len(overview) < 100:
                errors.append(f"compile-time entry '{name}' overview is too short for useful guidance")
            if overview.lower().startswith("compile-time operation for "):
                errors.append(f"compile-time entry '{name}' overview is still generic boilerplate")
            if re.search(r"\bword demo_[A-Za-z0-9_]+_(?:ct|runtime)\b", example):
                errors.append(f"compile-time entry '{name}' example uses a generated placeholder wrapper")
            if not re.search(rf"(?<![A-Za-z0-9_?.:+\-*/<>=!&]){re.escape(name)}(?![A-Za-z0-9_?.:+\-*/<>=!&])", example):
                errors.append(f"compile-time entry '{name}' example should explicitly show the word invocation")

            text_blob = " ".join(
                [
                    name,
                    str(item.get("search_text", "")),
                    overview,
                    example,
                ]
            ).lower()
            if " handler:" in text_blob or " flags:" in text_blob:
                errors.append(f"compile-time entry '{name}' still embeds handler/flags text")

    for name in registered_ct_words:
        entry_match = re.search(
            rf"(?m)^[ \t]{{2,}}{re.escape(name)}(?:[ \t]+[^\n]*)?\n((?:[ \t]{{4}}[^\n]*\n)+)",
            appendix_text,
        )
        if entry_match is None:
            continue
        detail_lines = [line.strip() for line in entry_match.group(1).splitlines() if line.strip()]
        if not detail_lines:
            errors.append(f"compile-time appendix entry '{name}' is missing detail lines")
            continue

        if not any(line.startswith("Overview:") for line in detail_lines):
            errors.append(f"compile-time appendix entry '{name}' is missing descriptive overview line")

        if not any(line.startswith("Category:") for line in detail_lines):
            errors.append(f"compile-time appendix entry '{name}' is missing category metadata")
        if not any(line.startswith("Scope:") for line in detail_lines):
            errors.append(f"compile-time appendix entry '{name}' is missing scope metadata")

        example_idx = -1
        for idx, line in enumerate(detail_lines):
            if line.startswith("Example:"):
                example_idx = idx
                break

        if example_idx < 0:
            errors.append(f"compile-time appendix entry '{name}' is missing example line")
        else:
            example_payload = [
                line.strip()
                for line in detail_lines[example_idx + 1 :]
                if line.strip() and not line.startswith(("Category:", "Scope:", "Overview:", "Example:"))
            ]
            if not example_payload:
                errors.append(f"compile-time appendix entry '{name}' has an empty example")

    if (
        docs_helpers is not None
        and hasattr(docs_helpers, "attach_ct_entry_line_numbers")
        and hasattr(docs_helpers, "build_ct_detail_lines")
        and entries
    ):
        try:
            line_entries = [
                dict(item)
                for item in docs_helpers.attach_ct_entry_line_numbers(full_text, entries)
            ]
        except Exception as exc:
            errors.append(f"compile-time detail helper line mapping failed: {exc}")
            line_entries = []

        for item in line_entries[:40]:
            name = str(item.get("name", "")).strip() or "<unknown>"
            try:
                detail_lines = [str(line) for line in docs_helpers.build_ct_detail_lines(item, 100)]
            except Exception as exc:
                errors.append(f"compile-time detail helper failed for '{name}': {exc}")
                continue
            detail_blob = "\n".join(detail_lines).lower()
            if "overview:" not in detail_blob:
                errors.append(f"compile-time detail view for '{name}' is missing overview section")
            if "example:" not in detail_blob:
                errors.append(f"compile-time detail view for '{name}' is missing example section")
            if "handler:" in detail_blob or "flags:" in detail_blob:
                errors.append(f"compile-time detail view for '{name}' still shows handler/flags")

    for required in ("runtime", "CT"):
        if not _integrity_doc_has_word_entry(full_text, required):
            errors.append(f"compile-time reference missing '{required}' entry")


def _run_integrity_word_flag_checks(errors: List[str]) -> None:
    dictionary = bootstrap_dictionary()
    for name, word in sorted(dictionary.words.items()):
        if word.compile_only and word.runtime_only:
            errors.append(f"word '{name}' is both compile-only and runtime-only")
        if word.runtime_only and word.immediate:
            errors.append(f"word '{name}' is both runtime-only and immediate")
        if word.runtime_only and word.compile_time_override:
            errors.append(f"word '{name}' is runtime-only but has compile-time override enabled")

    ct_word = dictionary.lookup("CT")
    if ct_word is None:
        errors.append("missing built-in CT word")
        return
    if ct_word.intrinsic is None:
        errors.append("CT word missing runtime emission intrinsic")
    if ct_word.compile_time_intrinsic is None:
        errors.append("CT word missing compile-time intrinsic")
    if ct_word.runtime_intrinsic is None:
        errors.append("CT word missing runtime-mode compile-time intrinsic")

    parser = Parser(dictionary, Reader())
    vm = parser.compile_time_vm
    try:
        vm.invoke(ct_word)
        if vm.stack != [1]:
            errors.append(f"CT compile-time invocation expected stack [1], got {vm.stack!r}")
    except Exception as exc:
        errors.append(f"CT compile-time invocation failed: {exc}")

    try:
        vm.invoke(ct_word, runtime_mode=True)
        depth = vm.native_stack_depth()
        if depth != 1:
            errors.append(f"CT runtime-mode compile-time invocation expected native depth 1, got {depth}")
        elif CTMemory.read_qword(vm.r12) != 1:
            errors.append("CT runtime-mode compile-time invocation expected top-of-stack value 1")
    except Exception as exc:
        errors.append(f"CT runtime-mode compile-time invocation failed: {exc}")

    try:
        asm = Assembler(dictionary)
        emitted: List[str] = []
        builder = FunctionEmitter(emitted)
        asm._emit_wordref("CT", builder)
        if not any("mov qword [r12], 0" in line for line in emitted):
            errors.append("CT runtime emission did not push literal 0")
    except Exception as exc:
        errors.append(f"CT runtime emission probe failed: {exc}")


def _run_integrity_cfg_format_checks(errors: List[str]) -> None:
    asm = Assembler(Dictionary())
    cases: List[Tuple[Op, str]] = [
        (_make_op("literal", 123), "push 123"),
        (_make_word_op("dup"), "dup"),
        (_make_op("word_ptr", "dup"), "&dup"),
        (_make_op("branch_zero", "L0"), "branch_zero"),
        (_make_op("jump", "L0"), "jump"),
        (_make_op("label", "L0"), ".L0:"),
        (_make_op("for_begin", {"loop": "L", "end": "E"}), "for"),
        (_make_op("for_end", {"loop": "L", "end": "E"}), "end  (for)"),
        (_make_op("list_begin", "L"), "list_begin"),
        (_make_op("list_end", "L"), "list_end"),
        (_make_op("list_literal", [1, 2]), "list_literal [1, 2]"),
        (_make_op("bss_list_literal", {"size": 2, "values": [1]}), "bss_list_literal {'size': 2, 'values': [1]}"),
        (_make_op("ret"), "ret"),
    ]
    for node, expected in cases:
        actual = asm._format_cfg_op(node)
        if actual != expected:
            errors.append(
                f"Assembler._format_cfg_op mismatch for '{node.op}': expected {expected!r}, got {actual!r}"
            )


def _run_integrity_vm_semantic_checks(errors: List[str]) -> None:
    dictionary = bootstrap_dictionary()
    parser = Parser(dictionary, Reader())
    vm = parser.compile_time_vm

    vm_probe_word_name = "__integrity_vm_word__"
    if dictionary.lookup(vm_probe_word_name) is None:
        dictionary.register(
            Word(
                name=vm_probe_word_name,
                definition=Definition(
                    name=vm_probe_word_name,
                    body=[_make_literal_op(9)],
                ),
            )
        )

    loop_data = {"loop": "VM_LOOP", "end": "VM_END"}
    vm_cases: List[Dict[str, Any]] = [
        {
            "name": "word_call",
            "nodes": [_make_word_op(vm_probe_word_name)],
            "initial_stack": [],
            "check": lambda run_vm: None if run_vm.stack == [9] else f"expected [9], got {run_vm.stack!r}",
        },
        {
            "name": "literal_push",
            "nodes": [_make_literal_op(7)],
            "initial_stack": [],
            "check": lambda run_vm: None if run_vm.stack == [7] else f"expected [7], got {run_vm.stack!r}",
        },
        {
            "name": "word_ptr_handle",
            "nodes": [_make_op("word_ptr", vm_probe_word_name)],
            "initial_stack": [],
            "check": lambda run_vm: (
                None
                if len(run_vm.stack) == 1
                and isinstance(run_vm.stack[0], int)
                and isinstance(run_vm._resolve_handle(run_vm.stack[0]), Word)
                and run_vm._resolve_handle(run_vm.stack[0]).name == vm_probe_word_name
                else f"word_ptr did not resolve to {vm_probe_word_name!r}: stack={run_vm.stack!r}"
            ),
        },
        {
            "name": "branch_zero_taken",
            "nodes": [
                _make_op("branch_zero", "VM_LABEL"),
                _make_literal_op(111),
                _make_op("label", "VM_LABEL"),
                _make_literal_op(222),
            ],
            "initial_stack": [0],
            "check": lambda run_vm: None if run_vm.stack == [222] else f"expected [222], got {run_vm.stack!r}",
        },
        {
            "name": "branch_zero_not_taken",
            "nodes": [
                _make_op("branch_zero", "VM_LABEL"),
                _make_literal_op(111),
                _make_op("label", "VM_LABEL"),
                _make_literal_op(222),
            ],
            "initial_stack": [1],
            "check": lambda run_vm: None if run_vm.stack == [111, 222] else f"expected [111, 222], got {run_vm.stack!r}",
        },
        {
            "name": "jump",
            "nodes": [
                _make_op("jump", "VM_JUMP"),
                _make_literal_op(1),
                _make_op("label", "VM_JUMP"),
                _make_literal_op(2),
            ],
            "initial_stack": [],
            "check": lambda run_vm: None if run_vm.stack == [2] else f"expected [2], got {run_vm.stack!r}",
        },
        {
            "name": "for_loop_counted",
            "nodes": [
                _make_op("for_begin", loop_data),
                _make_literal_op(1),
                _make_op("for_end", loop_data),
            ],
            "initial_stack": [2],
            "check": lambda run_vm: None if run_vm.stack == [1, 1] else f"expected [1, 1], got {run_vm.stack!r}",
        },
        {
            "name": "for_loop_zero_skips",
            "nodes": [
                _make_op("for_begin", loop_data),
                _make_literal_op(1),
                _make_op("for_end", loop_data),
            ],
            "initial_stack": [0],
            "check": lambda run_vm: None if run_vm.stack == [] else f"expected [], got {run_vm.stack!r}",
        },
        {
            "name": "list_begin_end",
            "nodes": [
                _make_op("list_begin", "VM_LIST"),
                _make_literal_op(4),
                _make_literal_op(5),
                _make_op("list_end", "VM_LIST"),
            ],
            "initial_stack": [],
            "check": lambda run_vm: _integrity_check_heap_list(run_vm, [4, 5]),
        },
        {
            "name": "list_literal",
            "nodes": [_make_op("list_literal", [4, 5])],
            "initial_stack": [],
            "check": lambda run_vm: _integrity_check_heap_list(run_vm, [4, 5]),
        },
        {
            "name": "bss_list_literal",
            "nodes": [_make_op("bss_list_literal", {"size": 4, "values": [9]})],
            "initial_stack": [],
            "check": lambda run_vm: _integrity_check_heap_list(run_vm, [9, 0, 0, 0]),
        },
        {
            "name": "ret_terminates",
            "nodes": [_make_literal_op(1), _make_op("ret"), _make_literal_op(2)],
            "initial_stack": [],
            "check": lambda run_vm: None if run_vm.stack == [1] else f"expected [1], got {run_vm.stack!r}",
        },
    ]

    for case in vm_cases:
        vm.reset()
        vm.runtime_mode = False
        vm.stack.extend(list(case["initial_stack"]))
        try:
            vm._execute_nodes(case["nodes"])
        except Exception as exc:
            errors.append(f"VM semantic case '{case['name']}' failed with exception: {exc}")
            continue

        try:
            check_err = case["check"](vm)
        except Exception as exc:
            errors.append(f"VM semantic case '{case['name']}' validation crashed: {exc}")
            continue

        if check_err:
            errors.append(f"VM semantic case '{case['name']}' failed: {check_err}")

    runtime_only_probe = Word(
        name="__integrity_runtime_only_probe__",
        definition=Definition(name="__integrity_runtime_only_probe__", body=[_make_literal_op(1)]),
        runtime_only=True,
    )
    dictionary.register(runtime_only_probe)
    try:
        vm.invoke(runtime_only_probe)
    except CompileTimeError as exc:
        if "runtime-only" not in str(exc):
            errors.append(
                "runtime-only compile-time rejection raised unexpected message: " + str(exc)
            )
    except Exception as exc:
        errors.append(f"runtime-only compile-time rejection raised unexpected exception: {exc}")
    else:
        errors.append("runtime-only probe word executed in compile-time VM")


def _integrity_check_heap_list(vm: CompileTimeVM, expected: List[int]) -> Optional[str]:
    if len(vm.stack) != 1:
        return f"expected single pointer on stack, got {vm.stack!r}"
    addr = vm.stack[0]
    if not isinstance(addr, int):
        return f"expected list pointer int, got {type(addr).__name__}"
    try:
        length = CTMemory.read_qword(addr)
        values = [CTMemory.read_qword(addr + 8 + i * 8) for i in range(max(0, length))]
    except Exception as exc:
        return f"failed to read list memory at {addr}: {exc}"
    if length != len(expected):
        return f"expected length {len(expected)}, got {length}"
    if values != expected:
        return f"expected values {expected!r}, got {values!r}"
    return None


def _run_integrity_assembler_semantic_checks(errors: List[str]) -> None:
    dictionary = bootstrap_dictionary()
    probe_target = "__integrity_probe_target"
    if dictionary.lookup(probe_target) is None:
        dictionary.register(Word(name=probe_target))

    asm_cases: List[Dict[str, Any]] = [
        {
            "name": "word_call",
            "nodes": [_make_word_op(probe_target), _make_literal_op(1)],
            "required": [f"call {sanitize_label(probe_target)}", "mov qword [r12], 1"],
        },
        {
            "name": "tail_call_implicit",
            "nodes": [_make_word_op(probe_target)],
            "required": [f"jmp {sanitize_label(probe_target)}"],
            "check": lambda text_blob: None if f"\n    call {sanitize_label(probe_target)}" not in text_blob else "expected tail position call to emit jmp",
        },
        {
            "name": "tail_call_explicit_ret",
            "nodes": [_make_word_op(probe_target), _make_op("ret")],
            "required": [f"jmp {sanitize_label(probe_target)}"],
            "check": lambda text_blob: None if f"\n    call {sanitize_label(probe_target)}" not in text_blob else "expected call+ret tail pattern to emit jmp",
        },
        {
            "name": "literal_int",
            "nodes": [_make_literal_op(7)],
            "required": ["mov qword [r12], 7"],
        },
        {
            "name": "word_ptr",
            "nodes": [_make_op("word_ptr", probe_target)],
            "required": [
                f"lea rax, [rel {sanitize_label(probe_target)}]",
                "mov [r12], rax",
            ],
            "check": lambda text_blob: None
            if (
                f"lea rax, [rel {sanitize_label(probe_target)}]" in text_blob
                or f"mov qword [r12], {sanitize_label(probe_target)}" in text_blob
            )
            else f"expected word_ptr to push a symbol address for {sanitize_label(probe_target)}",
        },
        {
            "name": "branch_zero",
            "nodes": [_make_op("branch_zero", "L0")],
            "required": ["test rax, rax", "jz L0"],
        },
        {
            "name": "jump",
            "nodes": [_make_op("jump", "L0")],
            "required": ["jmp L0"],
        },
        {
            "name": "label",
            "nodes": [_make_op("label", "L0")],
            "required": ["L0:"],
        },
        {
            "name": "for_pair",
            "nodes": [
                _make_op("for_begin", {"loop": "LOOP0", "end": "END0"}),
                _make_op("for_end", {"loop": "LOOP0", "end": "END0"}),
            ],
            "required": ["jle END0", "LOOP0:", "jg LOOP0", "END0:"],
        },
        {
            "name": "list_begin_end",
            "nodes": [_make_op("list_begin", "LIST0"), _make_op("list_end", "LIST0")],
            "required": ["; list begin", "; list end", "LIST0_copy_loop:", "LIST0_copy_done:"],
        },
        {
            "name": "list_literal",
            "nodes": [_make_op("list_literal", [1, 2])],
            "required": ["mov qword [rax], 2", "mov qword [rax + 8], 1", "mov qword [rax + 16], 2"],
        },
        {
            "name": "bss_list_literal",
            "nodes": [_make_op("bss_list_literal", {"size": 2, "values": [1]})],
            "required": ["; bss list literal", "mov qword [rax], 2", "mov qword [rax + 8], 1", "mov qword [rax + 16], 0"],
        },
        {
            "name": "ret",
            "nodes": [_make_op("ret")],
            "required": ["ret"],
            "check": lambda text_blob: None if text_blob.count("\n    ret") >= 2 else "expected explicit ret plus function epilogue ret",
        },
    ]

    for case in asm_cases:
        asm = Assembler(dictionary)
        text: List[str] = []
        definition = Definition(name=f"__integrity_asm_case_{case['name']}", body=case["nodes"])
        try:
            asm._emit_definition(definition, text, debug=False)
        except Exception as exc:
            errors.append(f"Assembler semantic case '{case['name']}' failed with exception: {exc}")
            continue

        text_blob = "\n".join(text)
        missing = [snippet for snippet in case["required"] if snippet not in text_blob]
        if missing:
            errors.append(
                f"Assembler semantic case '{case['name']}' missing output: " + ", ".join(missing)
            )
            continue

        check_fn = case.get("check")
        if check_fn is not None:
            try:
                check_err = check_fn(text_blob)
            except Exception as exc:
                errors.append(f"Assembler semantic case '{case['name']}' validation crashed: {exc}")
                continue
            if check_err:
                errors.append(f"Assembler semantic case '{case['name']}' failed: {check_err}")


def _integrity_native_stack_values(vm: CompileTimeVM) -> List[int]:
    depth = vm.native_stack_depth()
    top_first = [CTMemory.read_qword(vm.r12 + i * 8) for i in range(depth)]
    return list(reversed(top_first))


def _run_integrity_python_pipeline_checks(errors: List[str]) -> None:
    import tempfile

    repo_root = Path(__file__).resolve().parent
    include_paths = [repo_root, repo_root / "stdlib"]

    deterministic_source = """
word __integrity_ct_flag
    CT
end
compile-time __integrity_ct_flag

word main
    CT
    0 if
        11
    else
        22
    end
end
""".lstrip()

    try:
        compiler_a = Compiler(include_paths=include_paths)
        asm_a = compiler_a.compile_source(deterministic_source, debug=False, entry_mode="program").snapshot()
        compiler_b = Compiler(include_paths=include_paths)
        asm_b = compiler_b.compile_source(deterministic_source, debug=False, entry_mode="program").snapshot()
    except Exception as exc:
        errors.append(f"python pipeline determinism probe failed during compilation: {exc}")
        return

    if asm_a != asm_b:
        errors.append("python pipeline determinism probe produced non-deterministic assembly output")
    if "global _start" not in asm_a:
        errors.append("python pipeline determinism probe expected program assembly to export _start")
    if "mov qword [r12], 0" not in asm_a:
        errors.append("python pipeline determinism probe expected CT runtime emission to push literal 0")
    if compiler_a.parser.compile_time_vm.stack != [1]:
        errors.append(
            "python pipeline determinism probe expected compile-time CT stack to be [1], got "
            + repr(compiler_a.parser.compile_time_vm.stack)
        )

    try:
        library_asm = Compiler(include_paths=include_paths).compile_source(
            "word helper\n    7\nend\n",
            debug=False,
            entry_mode="library",
        ).snapshot()
    except Exception as exc:
        errors.append(f"python pipeline library-mode probe failed: {exc}")
    else:
        if "global _start" in library_asm:
            errors.append("python pipeline library-mode probe unexpectedly exported _start")

    try:
        Compiler(include_paths=include_paths).compile_preloaded(debug=False, entry_mode="program")
    except CompileError as exc:
        if "no preloaded source available" not in str(exc):
            errors.append(
                "python pipeline preloaded-guard probe raised unexpected message: " + str(exc)
            )
    except Exception as exc:
        errors.append(
            "python pipeline preloaded-guard probe raised unexpected exception: "
            + f"{type(exc).__name__}: {exc}"
        )
    else:
        errors.append("python pipeline preloaded-guard probe expected compile_preloaded to fail without preload")

    try:
        Compiler(include_paths=include_paths).compile_source(
            "word main\n    0\nend\n",
            debug=False,
            entry_mode="invalid",
        )
    except CompileError as exc:
        if "unknown entry mode" not in str(exc):
            errors.append("python pipeline invalid-entry probe raised unexpected message: " + str(exc))
    except Exception as exc:
        errors.append(
            "python pipeline invalid-entry probe raised unexpected exception: "
            + f"{type(exc).__name__}: {exc}"
        )
    else:
        errors.append("python pipeline invalid-entry probe expected compile_source to reject unknown entry mode")

    with tempfile.TemporaryDirectory(prefix="l2_integrity_pipeline_") as temp_dir_raw:
        temp_dir = Path(temp_dir_raw)
        src_path = temp_dir / "pipeline_main.sl"
        src_path.write_text("word main\n    1\nend\n", encoding="utf-8")

        try:
            compiler_file = Compiler(include_paths=include_paths)
            snap_file = compiler_file.compile_file(src_path, debug=False, entry_mode="program").snapshot()

            compiler_preloaded = Compiler(include_paths=include_paths)
            compiler_preloaded.collect_source_flags(src_path)
            snap_preloaded = compiler_preloaded.compile_preloaded(debug=False, entry_mode="program").snapshot()
        except Exception as exc:
            errors.append(f"python pipeline preloaded roundtrip probe failed: {exc}")
        else:
            if snap_file != snap_preloaded:
                errors.append("python pipeline preloaded roundtrip probe produced mismatched assembly snapshots")
            if compiler_preloaded.dictionary.lookup("main") is None:
                errors.append("python pipeline preloaded roundtrip probe did not populate dictionary with 'main'")


def _run_integrity_python_interpreter_differential_checks(errors: List[str]) -> None:
    import random
    dictionary = bootstrap_dictionary()
    parser = Parser(dictionary, Reader())
    vm = parser.compile_time_vm
    rng = random.Random(0x1A2B3C4D)

    for idx in range(96):
        a = rng.randint(-32, 32)
        cond = rng.randint(0, 1)
        on_true = rng.randint(-32, 32)
        on_false = rng.randint(-32, 32)
        loop_count = rng.randint(0, 6)
        step = rng.randint(-8, 8)

        else_label = f"INT_ELSE_{idx}"
        after_label = f"INT_AFTER_{idx}"
        loop_data = {"loop": f"INT_LOOP_{idx}", "end": f"INT_END_{idx}"}
        name = f"__integrity_py_diff_{idx}"

        nodes = [
            _make_literal_op(a),
            _make_literal_op(cond),
            _make_op("branch_zero", else_label),
            _make_literal_op(on_true),
            _make_op("jump", after_label),
            _make_op("label", else_label),
            _make_literal_op(on_false),
            _make_op("label", after_label),
            _make_literal_op(loop_count),
            _make_op("for_begin", loop_data),
            _make_literal_op(step),
            _make_op("for_end", loop_data),
            _make_op("ret"),
        ]

        expected = [a, on_true if cond != 0 else on_false] + [step] * loop_count
        definition = Definition(name=name, body=nodes)

        word = dictionary.lookup(name)
        if word is None:
            word = Word(name=name, definition=definition)
            dictionary.register(word)
        else:
            word.definition = definition
            word.compile_only = False
            word.runtime_only = False
            word.immediate = False

        try:
            vm.invoke(word)
            interpreted_stack = list(vm.stack)
        except Exception as exc:
            errors.append(
                f"python interpreter differential case '{name}' failed in interpreted mode: {type(exc).__name__}: {exc}"
            )
            continue

        if interpreted_stack != expected:
            errors.append(
                f"python interpreter differential case '{name}' interpreted mismatch: expected {expected!r}, got {interpreted_stack!r}"
            )
            continue

        try:
            vm.invoke(word, runtime_mode=True)
            runtime_stack = _integrity_native_stack_values(vm)
        except Exception as exc:
            errors.append(
                f"python interpreter differential case '{name}' failed in runtime_mode: {type(exc).__name__}: {exc}"
            )
            continue

        if runtime_stack != expected:
            errors.append(
                f"python interpreter differential case '{name}' runtime mismatch: expected {expected!r}, got {runtime_stack!r}"
            )

    inner_name = "__integrity_py_diff_inner"
    outer_name = "__integrity_py_diff_outer"
    passthrough_name = "__integrity_py_diff_passthrough"

    inner_word = dictionary.lookup(inner_name)
    if inner_word is None:
        inner_word = Word(name=inner_name)
        dictionary.register(inner_word)
    inner_word.definition = Definition(name=inner_name, body=[_make_literal_op(3), _make_op("ret")])
    inner_word.compile_only = False
    inner_word.runtime_only = False
    inner_word.immediate = False

    outer_word = dictionary.lookup(outer_name)
    if outer_word is None:
        outer_word = Word(name=outer_name)
        dictionary.register(outer_word)
    outer_word.definition = Definition(
        name=outer_name,
        body=[_make_word_op(inner_name), _make_literal_op(4), _make_op("ret")],
    )
    outer_word.compile_only = False
    outer_word.runtime_only = False
    outer_word.immediate = False

    try:
        vm.invoke(outer_word)
        if vm.stack != [3, 4]:
            errors.append(
                f"python interpreter nested-call probe interpreted mismatch: expected [3, 4], got {vm.stack!r}"
            )
    except Exception as exc:
        errors.append(
            "python interpreter nested-call probe failed in interpreted mode: "
            + f"{type(exc).__name__}: {exc}"
        )

    try:
        vm.invoke(outer_word, runtime_mode=True)
        runtime_vals = _integrity_native_stack_values(vm)
        if runtime_vals != [3, 4]:
            errors.append(
                f"python interpreter nested-call probe runtime mismatch: expected [3, 4], got {runtime_vals!r}"
            )
    except Exception as exc:
        errors.append(
            "python interpreter nested-call probe failed in runtime_mode: "
            + f"{type(exc).__name__}: {exc}"
        )

    passthrough_word = dictionary.lookup(passthrough_name)
    if passthrough_word is None:
        passthrough_word = Word(name=passthrough_name)
        dictionary.register(passthrough_word)
    passthrough_word.definition = Definition(name=passthrough_name, body=[_make_op("ret")])
    passthrough_word.compile_only = False
    passthrough_word.runtime_only = False
    passthrough_word.immediate = False

    try:
        vm.invoke_with_args(passthrough_word, [7, -2, 11])
        if vm.stack != [7, -2, 11]:
            errors.append(
                "python interpreter invoke_with_args probe mismatch: "
                + f"expected [7, -2, 11], got {vm.stack!r}"
            )
    except Exception as exc:
        errors.append(
            "python interpreter invoke_with_args probe failed: "
            + f"{type(exc).__name__}: {exc}"
        )


def _run_integrity_python_repl_state_checks(errors: List[str]) -> None:
    dictionary = bootstrap_dictionary()
    parser = Parser(dictionary, Reader())
    vm = parser.compile_time_vm

    push7_name = "__integrity_repl_push7"
    push9_name = "__integrity_repl_push9"

    push7 = dictionary.lookup(push7_name)
    if push7 is None:
        push7 = Word(name=push7_name)
        dictionary.register(push7)
    push7.definition = Definition(name=push7_name, body=[_make_literal_op(7)])
    push7.compile_only = False
    push7.runtime_only = False
    push7.immediate = False

    push9 = dictionary.lookup(push9_name)
    if push9 is None:
        push9 = Word(name=push9_name)
        dictionary.register(push9)
    push9.definition = Definition(name=push9_name, body=[_make_literal_op(9)])
    push9.compile_only = False
    push9.runtime_only = False
    push9.immediate = False

    try:
        vm.invoke_repl(push7)
        first = vm.repl_stack_values()
        vm.invoke_repl(push9)
        second = vm.repl_stack_values()
        vm.invoke_repl(push7)
        third = vm.repl_stack_values()
    except Exception as exc:
        errors.append(f"python REPL state probe failed while invoking words: {type(exc).__name__}: {exc}")
        return

    if first != [7]:
        errors.append(f"python REPL state probe first snapshot mismatch: expected [7], got {first!r}")
    if second != [7, 9]:
        errors.append(f"python REPL state probe second snapshot mismatch: expected [7, 9], got {second!r}")
    if third != [7, 9, 7]:
        errors.append(
            f"python REPL state probe third snapshot mismatch: expected [7, 9, 7], got {third!r}"
        )

    vm.reset()
    if vm.repl_stack_values() != []:
        errors.append("python REPL state probe expected reset() to clear persistent REPL state")

    try:
        vm.invoke(push9)
    except Exception as exc:
        errors.append(f"python REPL state probe failed after reset in interpreted mode: {type(exc).__name__}: {exc}")
    else:
        if vm.stack != [9]:
            errors.append(
                f"python REPL state probe interpreted invoke mismatch after reset: expected [9], got {vm.stack!r}"
            )


def _run_integrity_roundtrip_checks(errors: List[str]) -> None:
    import subprocess
    import tempfile

    repo_root = Path(__file__).resolve().parent
    include_paths = [repo_root]

    probes: List[Tuple[str, str, int]] = [
        (
            "literal_exit",
            """
:asm exit_top {
    mov rax, 60
    mov rdi, [r12]
    add r12, 8
    syscall
} ;

word main
    7
    exit_top
end
""".lstrip(),
            7,
        ),
        (
            "if_else",
            """
:asm exit_top {
    mov rax, 60
    mov rdi, [r12]
    add r12, 8
    syscall
} ;

word main
    0 if
        11
    else
        22
    end
    exit_top
end
""".lstrip(),
            22,
        ),
        (
            "for_sum",
            """
:asm exit_top {
    mov rax, 60
    mov rdi, [r12]
    add r12, 8
    syscall
} ;

word main
    0
    5 for
        2 +
    end
    exit_top
end
""".lstrip(),
            10,
        ),
        (
            "asm_word",
            """
:asm exit_top {
    mov rax, 60
    mov rdi, [r12]
    add r12, 8
    syscall
} ;

:asm emit42 {
    mov rax, 42
    sub r12, 8
    mov [r12], rax
} ;

word main
    emit42
    exit_top
end
""".lstrip(),
            42,
        ),
    ]

    with tempfile.TemporaryDirectory(prefix="l2_integrity_roundtrip_") as temp_dir_raw:
        temp_dir = Path(temp_dir_raw)
        for name, source_text, expected_exit in probes:
            src_path = temp_dir / f"{name}.sl"
            asm_path = temp_dir / f"{name}.asm"
            obj_path = temp_dir / f"{name}.o"
            exe_path = temp_dir / f"{name}.out"

            src_path.write_text(source_text)

            try:
                compiler = Compiler(include_paths=include_paths)
                emission = compiler.compile_file(src_path, debug=False, entry_mode="program")
                asm_text = emission.snapshot()
                if not asm_text.strip():
                    errors.append(f"round-trip probe '{name}' produced empty assembly")
                    continue

                asm_path.write_text(asm_text)
                run_nasm(asm_path, obj_path, debug=False, asm_text=asm_text)
                run_linker(obj_path, exe_path, debug=False, libs=[], shared=False)
            except Exception as exc:
                errors.append(f"round-trip probe '{name}' failed during build: {exc}")
                continue

            try:
                proc = subprocess.run(
                    [str(exe_path)],
                    capture_output=True,
                    text=True,
                    timeout=5,
                    check=False,
                )
            except Exception as exc:
                errors.append(f"round-trip probe '{name}' failed to execute: {exc}")
                continue

            if proc.returncode != expected_exit:
                errors.append(
                    f"round-trip probe '{name}' exit-code mismatch: expected {expected_exit}, got {proc.returncode}; stdout={proc.stdout!r}; stderr={proc.stderr!r}"
                )
                continue

            if proc.stdout:
                errors.append(f"round-trip probe '{name}' expected empty stdout, got {proc.stdout!r}")
            if proc.stderr:
                errors.append(f"round-trip probe '{name}' expected empty stderr, got {proc.stderr!r}")


def _run_integrity_prompt_feature_matrix_checks(errors: List[str]) -> None:
    repo_root = Path(__file__).resolve().parent
    paths = {
        "l2_main.py": Path(__file__),
        "main.py": repo_root / "main.py",
        "docs.py": repo_root / "docs.py",
        "main.c": repo_root / "main.c",
    }

    texts: Dict[str, str] = {}
    for name, path in paths.items():
        if not path.exists():
            errors.append(f"feature-matrix missing required file: {name}")
            continue
        try:
            texts[name] = path.read_text(encoding="utf-8", errors="ignore")
        except Exception as exc:
            errors.append(f"feature-matrix failed to read {name}: {exc}")

    if len(texts) != len(paths):
        return

    impl_text = texts["l2_main.py"]
    impl_definitions = {
        node.name
        for node in ast.parse(impl_text).body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
    }
    main_py_text = texts["main.py"]
    docs_text = texts["docs.py"]
    main_c_text = texts["main.c"]

    checks: List[Tuple[str, bool]] = [
        (
            "--force CLI option and implication are wired",
            "--force" in impl_text
            and "force full rebuild (always recompile + assemble + relink); implies --no-cache" in impl_text
            and "if args.force:\n        args.no_cache = True" in impl_text,
        ),
        (
            "daemon requests use the canonical CLI with event observation",
            "def _run_cli_captured(" in impl_text
            and "cli(argv, event_observer=event_observer)" in impl_text
            and "return_code, stdout, stderr = _run_cli_captured(" in impl_text,
        ),
        (
            "quick compiler bypasses are absent",
            "_try_quick_compile_force" not in impl_definitions
            and "_try_quick_compile_no_cache" not in impl_definitions,
        ),
        (
            "source graph cache is wired in CLI path",
            "class SourceGraphCache:" in impl_text
            and "source_graph_cache = SourceGraphCache(" in impl_text
            and "source_graph_cache=source_graph_cache" in impl_text,
        ),
        (
            "rewrite engine extraction is active",
            "class RewriteEngine:" in impl_text and "self.rewrites = RewriteEngine(self)" in impl_text,
        ),
        (
            "unified macros run CT bodies with buffered emission",
            "def _expand_macro(" in impl_text
            and "def _run_macro_body(" in impl_text
            and "def _define_quotation_macro(" in impl_text,
        ),
        (
            "docs helpers are lazy-loaded with fallback diagnostics",
            "def _load_docs_helpers(" in impl_text
            and "docs.py not found" in impl_text
            and "using built-in fallback" in impl_text,
        ),
        (
            "docs module exports advanced CT reference helpers",
            "def run_docs_cli(" in docs_text
            and "def run_docs_explorer(" in docs_text
            and "def build_ct_reference_bundle" in docs_text
            and "def attach_ct_entry_line_numbers" in docs_text
            and "def build_ct_detail_lines" in docs_text,
        ),
        (
            "docs TUI supports CT filter/results/detail modes",
            "_MODE_CT_REF_FILTER = 12" in docs_text
            and "_MODE_CT_REF_RESULTS = 13" in docs_text
            and "_MODE_CT_REF_DETAIL = 14" in docs_text
            and "query fields: section:<name> scope:<mode>" in docs_text
            and "function(s)  (Enter: open results  Esc: cancel)" in docs_text,
        ),
        (
            "integrity harness includes roundtrip and feature matrix",
            "(\"roundtrip\", _run_integrity_roundtrip_checks)" in impl_text
            and "(\"feature-matrix\", _run_integrity_prompt_feature_matrix_checks)" in impl_text,
        ),
        (
            "main.c CLI supports script/no-artifact/ct-run-main path",
            "if (strcmp(arg, \"--ct-run-main\") == 0)" in main_c_text
            and "if (strcmp(arg, \"--no-artifact\") == 0)" in main_c_text
            and "if (strcmp(arg, \"--script\") == 0)" in main_c_text
            and "ct_run_main = true;" in main_c_text
            and "no_artifact = true;" in main_c_text,
        ),
        (
            "main.c exposes broad CT intrinsic surface",
            all(
                fragment in main_c_text
                for fragment in (
                    "register_ct_intrinsic(dict, \"list-peek-front\"",
                    "register_ct_intrinsic(dict, \"list-push-front\"",
                    "register_ct_intrinsic(dict, \"list-reverse\"",
                    "register_ct_intrinsic(dict, \"map-length\"",
                    "register_ct_intrinsic(dict, \"map-keys\"",
                    "register_ct_intrinsic(dict, \"string-contains?\"",
                    "register_ct_intrinsic(dict, \"string-starts-with?\"",
                    "register_ct_intrinsic(dict, \"string-ends-with?\"",
                    "register_ct_intrinsic(dict, \"token-line\"",
                    "register_ct_intrinsic(dict, \"token-column\"",
                    "register_ct_intrinsic(dict, \"ct-parser-consume\"",
                    "register_ct_intrinsic(dict, \"ct-parser-peek\"",
                    "register_ct_intrinsic(dict, \"ct-parser-inject\"",
                )
            ) and len(re.findall(r"(?m)^\s*register_ct_intrinsic\(", main_c_text)) >= 70,
        ),
    ]

    for label, ok in checks:
        if not ok:
            errors.append(f"feature checklist item failed: {label}")


def _run_integrity_failure_injection_checks(errors: List[str]) -> None:
    repo_root = Path(__file__).resolve().parent
    include_paths = [repo_root, repo_root / "stdlib"]

    failure_cases: List[Dict[str, Any]] = [
        {
            "name": "parse_unexpected_end",
            "source": "end\n",
            "expected_exc": ParseError,
            "message_contains": "compilation failed with",
            "diag_contains": "unexpected 'end'",
        },
        {
            "name": "parse_unterminated_macro",
            "source": "macro m 0 1\n",
            "expected_exc": ParseError,
            "message_contains": "compilation failed with",
            "diag_contains": "unterminated macro definition",
        },
        {
            "name": "compile_unknown_word",
            "source": "word main\n    __integrity_missing_word__\nend\n",
            "expected_exc": CompileError,
            "message_contains": "unknown word '__integrity_missing_word__'",
        },
        {
            "name": "compile_compile_only_word",
            "source": "word main\n    nil\nend\n",
            "expected_exc": CompileError,
            "message_contains": "compile-time only",
        },
        {
            "name": "parse_runtime_immediate_conflict",
            "source": "word rt\n    1\nend\nruntime\nimmediate\nword main\n    0\nend\n",
            "expected_exc": ParseError,
            "message_contains": "compilation failed with",
            "diag_contains": "runtime-only and cannot be immediate",
        },
        {
            "name": "parse_runtime_compile_only_conflict",
            "source": "word rt\n    1\nend\nruntime\ncompile-only\nword main\n    0\nend\n",
            "expected_exc": ParseError,
            "message_contains": "compilation failed with",
            "diag_contains": "runtime-only and cannot be compile-only",
        },
        {
            "name": "parse_compile_time_runtime_only_target",
            "source": "word rt\n    1\nend\nruntime\nword main\n    compile-time rt\nend\n",
            "expected_exc": ParseError,
            "message_contains": "compilation failed with",
            "diag_contains": "word 'rt' is runtime-only",
        },
        {
            "name": "ct_prefer_l2_runtime_only_target",
            "source": "word rt\n    1\nend\nruntime\nword cfg\n    \"rt\"\n    ct-definition-prefer-l2-by-name drop\nend\ncompile-time cfg\nword main\n    0\nend\n",
            "expected_exc": CompileTimeError,
            "message_contains": "runtime-only and cannot run at compile time",
        },
    ]

    for case in failure_cases:
        compiler = Compiler(include_paths=include_paths)
        try:
            compiler.compile_source(case["source"], debug=False, entry_mode="program")
        except Exception as exc:
            expected_exc = case["expected_exc"]
            if not isinstance(exc, expected_exc):
                errors.append(
                    f"failure-injection case '{case['name']}' raised {type(exc).__name__}, expected {expected_exc.__name__}"
                )
                continue

            message = str(exc)
            needle = case.get("message_contains")
            if needle and needle not in message:
                errors.append(
                    f"failure-injection case '{case['name']}' message mismatch: expected substring {needle!r}, got {message!r}"
                )

            diag_needle = case.get("diag_contains")
            if diag_needle:
                diagnostics = [d.message for d in compiler.parser.reportable_diagnostics() if d.severity == "error"]
                if not any(diag_needle in d for d in diagnostics):
                    errors.append(
                        f"failure-injection case '{case['name']}' missing diagnostic containing {diag_needle!r}; got {diagnostics!r}"
                    )
        else:
            errors.append(f"failure-injection case '{case['name']}' expected failure but compilation succeeded")


def _run_integrity_docs_consistency_checks(errors: List[str]) -> None:
    docs_path = Path(__file__).with_name("docs.py")
    if not docs_path.exists():
        errors.append("docs consistency probe requires docs.py but it is missing")
        return

    try:
        source_text = docs_path.read_text(encoding="utf-8", errors="ignore")
    except Exception as exc:
        errors.append(f"docs consistency probe failed to read docs.py: {exc}")
        return

    required_fragments = [
        "_L2_MACRO_CANONICAL_TEXT = (",
        "_L2_MACRO_LANG_DETAIL = (",
        "+ _L2_MACRO_CT_BLOCK",
        "+ _L2_MACRO_QA_BLOCK",
        "_MODE_CT_REF_FILTER = 12",
        "_MODE_CT_REF_RESULTS = 13",
        "_MODE_CT_REF_DETAIL = 14",
        "query fields: section:<name> scope:<mode>",
        "function(s)  (Enter: open results  Esc: cancel)",
        "Enter detail  o jump-to-full  / search",
        " / search  f filters  c clear ",
        "def run_docs_cli(",
    ]
    for fragment in required_fragments:
        if fragment not in source_text:
            errors.append(f"docs consistency probe missing expected fragment: {fragment!r}")

    doc_text = _integrity_load_ct_reference_text()
    if not doc_text.strip():
        errors.append("docs consistency probe could not load compile-time reference text")
        return

    # Macro docs should be centralized in §13 and reused via canonical blocks,
    # not duplicated ad-hoc in earlier CT sections.
    if "Macro definition syntax:" in doc_text:
        errors.append("compile-time reference still contains legacy scattered macro syntax block")
    canonical_count = doc_text.count("A macro is an L2 program run at compile time:")
    if canonical_count != 1:
        errors.append(
            "compile-time reference should contain exactly one canonical macro definition block "
            f"(found {canonical_count})"
        )


def _run_integrity_docs_module_checks(errors: List[str]) -> None:
    repo_root = Path(__file__).resolve().parent
    docs_path = repo_root / "docs.py"
    if not docs_path.exists():
        errors.append("docs.py is required for docs explorer/integrity checks but was not found")
        return

    try:
        docs_source = docs_path.read_text(encoding="utf-8", errors="ignore")
    except Exception as exc:
        errors.append(f"failed to read docs.py: {exc}")
        return

    required_fragments = [
        "def run_docs_explorer(",
        "def run_docs_cli(",
        "def _run_docs_tui(",
        "def build_ct_reference_bundle",
        "def attach_ct_entry_line_numbers",
        "def build_ct_detail_lines",
        "Overview:",
        "Example:",
    ]
    for fragment in required_fragments:
        if fragment not in docs_source:
            errors.append(f"docs.py missing expected fragment: {fragment!r}")

    docs_helpers = _load_docs_helpers(warn=False)
    if docs_helpers is None:
        err = _DOCS_HELPERS_ERROR or "unknown import failure"
        errors.append(f"docs.py exists but lazy import failed: {err}")
        return

    for attr in (
        "run_docs_cli",
        "run_docs_explorer",
        "build_ct_reference_bundle",
        "attach_ct_entry_line_numbers",
        "build_ct_detail_lines",
    ):
        if not hasattr(docs_helpers, attr):
            errors.append(f"docs.py helper missing callable '{attr}'")

    try:
        impl_text = Path(__file__).read_text(encoding="utf-8", errors="ignore")
    except Exception as exc:
        errors.append(f"failed to read l2_main.py for docs delegation checks: {exc}")
        return

    forbidden_main_patterns = [
        (r"(?m)^class\s+DocEntry\s*:", "class DocEntry"),
        (r"(?m)^def\s+_scan_doc_file\s*\(", "def _scan_doc_file("),
        (r"(?m)^def\s+_run_docs_tui\s*\(", "def _run_docs_tui("),
    ]
    for pattern, label in forbidden_main_patterns:
        if re.search(pattern, impl_text) is not None:
            errors.append(f"l2_main.py still contains migrated docs implementation fragment: {label!r}")

    required_main_fragments = [
        "def run_docs_explorer(",
        "docs_helpers.run_docs_cli(",
    ]
    for fragment in required_main_fragments:
        if fragment not in impl_text:
            errors.append(f"l2_main.py missing docs delegation fragment: {fragment!r}")


def _run_integrity_compiler_file_contract_checks(errors: List[str]) -> None:
    """Validate cross-file compiler contracts for main.py, l2_main.py, docs.py, and main.c.

    This check is intentionally static and file-scoped so integrity mode stays
    independent from external libraries and stdlib meta layers.
    """

    repo_root = Path(__file__).resolve().parent
    target_paths = {
        "main.py": repo_root / "main.py",
        "l2_main.py": repo_root / "l2_main.py",
        "docs.py": repo_root / "docs.py",
    }
    main_c_path = repo_root / "main.c"
    main_c_text = ""

    if not main_c_path.exists():
        errors.append("required compiler file missing: main.c")
    else:
        try:
            main_c_text = main_c_path.read_text(encoding="utf-8", errors="ignore")
        except Exception as exc:
            errors.append(f"failed to read main.c: {exc}")

    sources: Dict[str, str] = {}
    trees: Dict[str, ast.AST] = {}

    for name, path in target_paths.items():
        if not path.exists():
            errors.append(f"required compiler file missing: {name}")
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="ignore")
        except Exception as exc:
            errors.append(f"failed to read {name}: {exc}")
            continue
        sources[name] = text
        try:
            trees[name] = ast.parse(text)
        except SyntaxError as exc:
            errors.append(f"{name} has syntax error at line {exc.lineno}: {exc.msg}")

    missing = [name for name in target_paths if name not in sources or name not in trees]
    if missing:
        return

    main_text = sources["main.py"]
    l2_text = sources["l2_main.py"]
    docs_text = sources["docs.py"]

    # --- main.py contract checks ---
    required_main_fragments = [
        "if __name__ == \"__main__\":",
        "from l2_main import main as _entry_main",
        "from l2_main import *",
    ]
    for fragment in required_main_fragments:
        if fragment not in main_text:
            errors.append(f"main.py missing required compiler bootstrap fragment: {fragment!r}")

    main_top_imports: Set[str] = set()
    for node in trees["main.py"].body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                main_top_imports.add(alias.name)
        elif isinstance(node, ast.ImportFrom) and node.module:
            main_top_imports.add(node.module)
    for must_import in ("sys",):
        if must_import not in main_top_imports:
            errors.append(f"main.py missing top-level import '{must_import}'")

    if "def _run_cli_captured(" not in l2_text or "return_code, stdout, stderr = _run_cli_captured(" not in l2_text:
        errors.append("l2_main.py daemon does not route requests through the canonical CLI")
    l2_definitions = {
        node.name
        for node in trees["l2_main.py"].body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
    }
    if "_try_quick_compile_force" in l2_definitions or "_try_quick_compile_no_cache" in l2_definitions:
        errors.append("l2_main.py still contains a quick compiler bypass")

    # --- docs.py contract checks ---
    docs_required_defs = {
        "run_docs_cli",
        "run_docs_explorer",
        "_run_docs_tui",
        "build_ct_reference_bundle",
        "attach_ct_entry_line_numbers",
        "build_ct_detail_lines",
        "collect_docs",
    }
    docs_defs = {
        node.name
        for node in trees["docs.py"].body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
    }
    missing_docs_defs = sorted(docs_required_defs - docs_defs)
    if missing_docs_defs:
        errors.append("docs.py missing required APIs: " + ", ".join(missing_docs_defs))

    docs_required_fragments = [
        "imported lazily by l2_main.py",
        "only when docs or integrity features need it.",
        "Structured compile-time docs helpers",
    ]
    for fragment in docs_required_fragments:
        if fragment not in docs_text:
            errors.append(f"docs.py missing required module contract text: {fragment!r}")

    # --- l2_main.py contract checks ---
    l2_required_defs = {
        "cli",
        "main",
        "_run_integrity_checks",
        "_load_docs_helpers",
        "run_docs_explorer",
        "_run_integrity_compiler_file_contract_checks",
    }
    l2_defs = {
        node.name
        for node in trees["l2_main.py"].body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
    }
    missing_l2_defs = sorted(l2_required_defs - l2_defs)
    if missing_l2_defs:
        errors.append("l2_main.py missing required compiler entrypoints: " + ", ".join(missing_l2_defs))

    l2_required_fragments = [
        "--check-integrity",
        "run internal compiler integrity assertions",
        "if args.check_integrity:",
        "if args.source is None and args.check_integrity and not args.repl:",
        "docs_helpers.run_docs_cli(",
        'Path(__file__).with_name("docs.py")',
        "importlib.util.spec_from_file_location",
    ]
    for fragment in l2_required_fragments:
        if fragment not in l2_text:
            errors.append(f"l2_main.py missing required integration fragment: {fragment!r}")

    # Cross-file API usage integrity: methods invoked from l2_main must exist in docs.py.
    referenced_docs_apis = [
        "run_docs_cli",
        "run_docs_explorer",
        "build_ct_reference_bundle",
        "attach_ct_entry_line_numbers",
        "build_ct_detail_lines",
    ]
    for api in referenced_docs_apis:
        if f"docs_helpers.{api}" in l2_text and api not in docs_defs:
            errors.append(f"l2_main.py references docs helper '{api}' but docs.py does not define it")

    # --- main.c contract checks ---
    if main_c_text:
        required_main_c_fragments = [
            "int l2_cli(int argc, char **argv)",
            "int main(int argc, char **argv)",
            "return l2_cli(argc, argv);",
            "if (strcmp(arg, \"--ct-run-main\") == 0)",
            "if (strcmp(arg, \"--no-artifact\") == 0)",
            "if (strcmp(arg, \"--script\") == 0)",
            "ct_run_main = true;",
            "no_artifact = true;",
            "usage: %s <source.sl> [-o output] [--emit-asm] [--ct-run-main] [--no-artifact] [--script]",
        ]
        for fragment in required_main_c_fragments:
            if fragment not in main_c_text:
                errors.append(f"main.c missing required CLI/runtime fragment: {fragment!r}")

        ct_required_intrinsics = [
            "register_ct_intrinsic(dict, \"list-peek-front\"",
            "register_ct_intrinsic(dict, \"list-push-front\"",
            "register_ct_intrinsic(dict, \"list-reverse\"",
            "register_ct_intrinsic(dict, \"map-length\"",
            "register_ct_intrinsic(dict, \"map-keys\"",
            "register_ct_intrinsic(dict, \"string-contains?\"",
            "register_ct_intrinsic(dict, \"string-starts-with?\"",
            "register_ct_intrinsic(dict, \"string-ends-with?\"",
            "register_ct_intrinsic(dict, \"token-line\"",
            "register_ct_intrinsic(dict, \"token-column\"",
            "register_ct_intrinsic(dict, \"ct-parser-consume\"",
            "register_ct_intrinsic(dict, \"ct-parser-peek\"",
            "register_ct_intrinsic(dict, \"ct-parser-inject\"",
        ]
        missing_intrinsics = [frag for frag in ct_required_intrinsics if frag not in main_c_text]
        if missing_intrinsics:
            errors.append("main.c missing required CT intrinsic registrations")

        ct_registration_count = len(re.findall(r"(?m)^\s*register_ct_intrinsic\(", main_c_text))
        if ct_registration_count < 70:
            errors.append(
                f"main.c expected broad CT intrinsic surface (>=70 registrations), found {ct_registration_count}"
            )


def _run_integrity_opcode_matrix_checks(errors: List[str]) -> None:
    opcode_symbols = _integrity_opcode_symbols()
    opcode_values = {globals()[name] for name in opcode_symbols}
    mapped_values = set(_OP_STR_TO_INT.values())

    missing_from_mapping = sorted(opcode_values - mapped_values)
    extra_in_mapping = sorted(mapped_values - opcode_values)
    if missing_from_mapping or extra_in_mapping:
        if missing_from_mapping:
            errors.append(
                "opcode mapping missing values: " + ", ".join(str(v) for v in missing_from_mapping)
            )
        if extra_in_mapping:
            errors.append(
                "opcode mapping contains unknown values: " + ", ".join(str(v) for v in extra_in_mapping)
            )

    documented_ops = set(_OP_INTEGRITY_DOCS.keys())
    defined_ops = set(_OP_STR_TO_INT.keys())
    missing_docs = sorted(defined_ops - documented_ops)
    extra_docs = sorted(documented_ops - defined_ops)
    if missing_docs:
        errors.append("missing opcode docs entries: " + ", ".join(missing_docs))
    if extra_docs:
        errors.append("stale opcode docs entries: " + ", ".join(extra_docs))

    coverage_targets: List[Tuple[str, Any]] = [
        ("CompileTimeVM._execute_nodes", CompileTimeVM._execute_nodes),
        ("Assembler._emit_node", Assembler._emit_node),
        ("Assembler._format_cfg_op", Assembler._format_cfg_op),
    ]
    for target_name, target_obj in coverage_targets:
        seen_symbols = _integrity_symbols_in_object(target_obj)
        missing_symbols = sorted(opcode_symbols - seen_symbols)
        if missing_symbols:
            errors.append(
                f"{target_name} missing opcode coverage: " + ", ".join(missing_symbols)
            )


def _run_integrity_step(step_name: str, step_fn: Callable[[List[str]], None], errors: List[str]) -> None:
    before = len(errors)
    try:
        step_fn(errors)
    except Exception as exc:  # pragma: no cover - defensive guard for integrity harness itself
        errors.append(f"[{step_name}] unexpected integrity checker exception: {exc}")
        return
    for idx in range(before, len(errors)):
        msg = errors[idx]
        if not msg.startswith("["):
            errors[idx] = f"[{step_name}] {msg}"


def _run_integrity_checks() -> None:
    errors: List[str] = []

    steps: List[Tuple[str, Callable[[List[str]], None]]] = [
        ("opcode-matrix", _run_integrity_opcode_matrix_checks),
        ("ct-docs", _run_integrity_compile_time_docs_checks),
        ("word-flags", _run_integrity_word_flag_checks),
        ("python-pipeline", _run_integrity_python_pipeline_checks),
        ("cfg-format", _run_integrity_cfg_format_checks),
        ("vm-semantics", _run_integrity_vm_semantic_checks),
        ("python-interpreter-diff", _run_integrity_python_interpreter_differential_checks),
        ("python-repl-state", _run_integrity_python_repl_state_checks),
        ("assembler-semantics", _run_integrity_assembler_semantic_checks),
        ("roundtrip", _run_integrity_roundtrip_checks),
        ("failure-injection", _run_integrity_failure_injection_checks),
        ("docs-consistency", _run_integrity_docs_consistency_checks),
        ("docs-module", _run_integrity_docs_module_checks),
        ("compiler-files", _run_integrity_compiler_file_contract_checks),
        ("feature-matrix", _run_integrity_prompt_feature_matrix_checks),
    ]

    for step_name, step_fn in steps:
        _run_integrity_step(step_name, step_fn, errors)

    if errors:
        details = "\n".join(f"  - {msg}" for msg in errors)
        raise CompileError("integrity assertions failed:\n" + details, code="integrity-check-failed")


def _emit_macro_profile_report(parser: Parser, destination: Optional[str]) -> None:
    if destination is None:
        return
    report = parser.format_macro_profile()
    target = str(destination).strip().lower()
    if target in ("", "stderr"):
        print(report, file=sys.stderr)
        return
    if target in ("-", "stdout"):
        print(report)
        return
    out_path = Path(str(destination))
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(report + "\n", encoding="utf-8")
    print(f"[info] wrote macro profile to {out_path}")



# ---------------------------------------------------------------------------
# § 21. Warm stdlib (daemon workers)
# ---------------------------------------------------------------------------
#
# A daemon worker parses the stdlib (and the compiler's other libraries a
# job imports first) once into a paused Compiler: the parser stops at end of
# input without finalizing.  Each job runs in a child forked from the
# worker, so it inherits that state copy-on-write and resumes parsing with its
# own root file.  A prefix is the parsed form of a sequence of leading imports
# that resolve inside trusted directories: the compiler's own stdlib/ and
# libs/, and L2_DAEMON_TRUSTED_DIRS (only those are run in the long-lived
# worker).  The worker keeps a few prefixes, keyed by
# that sequence.  A prefix is reused only when the job's parse settings are
# the defaults it was built with, its root file's leading imports start with
# the same files, and every import made while building resolves the same way
# under the job's include paths.  It is rebuilt when one of its files' mtime
# or size changes, or on --force-stdlib (--force does not rebuild it).


# Parse settings a prefix is built with: (-D symbols, -W categories, --Werror),
# normalized as the CLI does (-W error means --Werror; --Werror alone means
# -W all).
_WarmSettings = Tuple[frozenset, frozenset, bool]
_WARM_DEFAULT_SETTINGS: _WarmSettings = (frozenset(), frozenset(), False)


def _warm_settings(defines: Sequence[str], warnings: Sequence[str], werror: bool) -> _WarmSettings:
    warning_set = set(warnings)
    if "error" in warning_set:
        warning_set.discard("error")
        werror = True
    if werror and not warning_set:
        warning_set.add("all")
    return frozenset(defines), frozenset(warning_set), bool(werror)


class _WarmPrefix:
    __slots__ = ('compiler', 'targets', 'files', 'resolutions', 'seen', 'taken', 'settings', 'asm_mapped')

    def __init__(self, compiler: "Compiler", targets: Tuple[Path, ...], files: Dict[Path, Tuple[int, int, int, int]],
                 resolutions: List[Tuple[Path, str, Path]], seen: Set[Path],
                 settings: _WarmSettings = _WARM_DEFAULT_SETTINGS) -> None:
        self.settings = settings
        # resolutions: (importing file, target, resolved path) seen while
        # building; a job must resolve each the same way.
        self.compiler = compiler
        self.targets = targets
        self.files = files
        self.resolutions = resolutions
        self.seen = seen
        self.taken = False
        # Its compile-time :asm words are mapped (daemon workers).
        self.asm_mapped = False

    def fresh(self) -> bool:
        for path, identity in self.files.items():
            try:
                st = path.stat()
            except OSError:
                return False
            if _file_identity(st) != identity:
                return False
        return True

    def take(self, include_paths: Sequence[Path], source_graph_cache: Optional["SourceGraphCache"]) -> "Compiler":
        """The paused compiler, configured with the job's include paths.
        One job per process uses it (a forked child gets its own copy)."""
        global _WARM_STDLIB
        if _WARM_STDLIB is self:
            _WARM_STDLIB = None
        self.taken = True
        compiler = self.compiler
        compiler.include_paths = [p.expanduser().resolve() for p in include_paths]
        compiler.source_graph_cache = source_graph_cache
        return compiler

    def accepts(self, compiler: "Compiler", source: Path) -> bool:
        unit = compiler._root_unit
        if unit is None or unit.frontend is not None or compiler._frontends_loaded:
            return False
        if unit.path in self.seen:
            return False
        try:
            for importer, target, result in self.resolutions:
                if compiler._resolve_import_target(importer, target) != result:
                    return False
            leading = _warm_leading_imports(unit)
            if len(leading) < len(self.targets):
                return False
            for target, expected in zip(leading, self.targets):
                if compiler._resolve_import_target(unit.path, target) != expected:
                    return False
            return True
        except ParseError:
            return False

    def activate(self, compiler: "Compiler") -> None:
        compiler._warm_seen = set(self.seen)
        compiler.parser._warm_resume = True


# The prefix chosen for the job about to run (the worker sets it before each
# fork; the job's cli takes it), and the worker's prefixes by import sequence.
_WARM_STDLIB: Optional[_WarmPrefix] = None
_WARM_PREFIXES: "OrderedDict[Tuple[Tuple[Path, ...], _WarmSettings], _WarmPrefix]" = OrderedDict()
_WARM_PREFIX_LIMIT = max(1, int(os.environ.get("L2_DAEMON_WARM_PREFIXES", "4") or 4))


def _warm_leading_imports(unit: "SourceUnit") -> List[str]:
    """The targets of the root unit's leading import lines (comments and
    blank lines may come between them)."""
    targets: List[str] = []
    for line_no, line in enumerate(unit.text.split("\n"), 1):
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        entry = unit.imports.get(line_no)
        if entry is None:
            break
        targets.append(entry[0])
    return targets


def _warm_stdlib_args_eligible(args: argparse.Namespace, event_bus: Optional[EventBus],
                               prefix: Optional["_WarmPrefix"] = None) -> bool:
    """The job's parse settings match those `prefix` was built with (-D, -W,
    --Werror), and nothing else that changes parsing is set."""
    if prefix is not None and prefix.settings != _warm_settings(args.defines, args.warnings, args.Werror):
        return False
    return (
        not args.repl
        and args.source is not None
        and event_bus is None
        and not args.no_events
        and args.macro_expansion_limit == DEFAULT_MACRO_EXPANSION_LIMIT
        and not args.macro_preview
        and not args.preview
        and args.macro_profile is None
    )


def _warm_stdlib_target() -> Optional[Path]:
    probe = Compiler()
    try:
        return probe._resolve_import_target(Path.cwd() / "<warm>", "stdlib.sl")
    except ParseError:
        return None


_WARM_IMPORT_LINE_RE = re.compile(r'^\s*import\s+(?:"([^"]+)"|(\S+))\s*(?:#.*)?$')


def _warm_trusted_dirs() -> Tuple[Path, ...]:
    """Directories whose files a worker may pre-parse (run their compile-time
    code in the long-lived worker): the compiler's stdlib/ and libs/, plus
    L2_DAEMON_TRUSTED_DIRS (colon-separated), so a project's own leading
    imports become incremental too."""
    dirs = [_INSTALL_DIR / "stdlib", _INSTALL_DIR / "libs"]
    for entry in os.environ.get("L2_DAEMON_TRUSTED_DIRS", "").split(os.pathsep):
        entry = entry.strip()
        if entry:
            try:
                dirs.append(Path(entry).expanduser().resolve())
            except OSError:
                continue
    return tuple(dirs)


def _warm_job_settings(argv: Sequence[str]) -> _WarmSettings:
    """-D, -W and --Werror as given on a job's command line."""
    defines: List[str] = []
    warnings: List[str] = []
    werror = False
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg in ("-D", "-W") and index + 1 < len(argv):
            (defines if arg == "-D" else warnings).append(argv[index + 1])
            index += 2
            continue
        if arg == "--Werror":
            werror = True
        elif arg.startswith("-D") and len(arg) > 2:
            defines.append(arg[2:])
        elif arg.startswith("-W") and len(arg) > 2 and not arg.startswith("--"):
            warnings.append(arg[2:])
        index += 1
    return _warm_settings(defines, warnings, werror)


def _warm_job_targets(argv: Sequence[str]) -> Optional[Tuple[Path, ...]]:
    """The job's leading imports that resolve into the compiler's own
    stdlib/ or libs/, in order (the longest such run), or None."""
    include_extra: List[Path] = []
    source: Optional[Path] = None
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg in ("-I", "--include", "-D", "-W", "-o") and index + 1 < len(argv):
            if arg in ("-I", "--include"):
                include_extra.append(Path(argv[index + 1]))
            index += 2
            continue
        if arg.startswith("-I") and len(arg) > 2:
            include_extra.append(Path(arg[2:]))
        elif not arg.startswith("-") and arg.endswith(".sl") and source is None:
            source = Path(arg)
        index += 1
    if source is None:
        return None
    try:
        text = source.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None
    probe = Compiler(include_paths=_default_include_paths(include_extra))
    trusted = _warm_trusted_dirs()
    targets: List[Path] = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        match = _WARM_IMPORT_LINE_RE.match(line)
        if match is None:
            break
        try:
            resolved = probe._resolve_import_target(source.resolve(), match.group(1) or match.group(2))
        except ParseError:
            break
        if not any(resolved.is_relative_to(base) for base in trusted):
            break
        targets.append(resolved)
    return tuple(targets) if targets else None


def _build_warm_stdlib(targets: Optional[Tuple[Path, ...]] = None,
                       settings: _WarmSettings = _WARM_DEFAULT_SETTINGS) -> Optional[_WarmPrefix]:
    """Parse `import` of each target (default: the stdlib) into a paused
    Compiler, with the given -D/-W/--Werror settings."""
    if targets is None:
        stdlib = _warm_stdlib_target()
        if stdlib is None:
            return None
        targets = (stdlib,)
    defines, warnings, werror = settings
    compiler = Compiler(defines=sorted(defines))
    compiler.parser.enable_dead_macro_elimination = True
    compiler.parser.enable_unused_rewrite_elimination = True
    compiler.parser._warnings_enabled = set(warnings)
    compiler.parser._werror = werror
    if warnings or werror:
        def _dict_warn_cb(name: str, priority: int) -> None:
            compiler.parser._warn(compiler.parser._last_token, "redefine",
                                  f"redefining word {name} (priority {priority})")
        compiler.parser.dictionary.warn_callback = _dict_warn_cb
    text = "".join(f"import {_l2_string_literal(str(target))}\n" for target in targets)
    try:
        tokens = compiler.reader.tokenize(text, None, "<warm-stdlib>")
        compiler._parse_seen = set()
        compiler.parser.file_spans = []
        compiler.parser._warm_pause = True
        compiler.parser.parse(tokens, text)
    except Exception:
        return None
    if compiler.parser._unresolved_errors or len(compiler.parser.context_stack) != 1 \
            or compiler.parser.control_stack or compiler.parser._macro_body_stack:
        return None
    seen = set(compiler._parse_seen)
    files: Dict[Path, Tuple[int, int, int, int]] = {}
    for path in seen:
        try:
            st = path.stat()
        except OSError:
            return None
        files[path] = _file_identity(st)
    resolutions = [(importer_dir / (self_named or "<warm>"), target_text, result)
                   for (importer_dir, target_text, _paths, self_named), (result, _absent, _link)
                   in compiler._import_resolve_cache.items()]
    _warm_prepare_unit_reuse(compiler, seen)
    return _WarmPrefix(compiler, tuple(targets), files, resolutions, seen, settings)


_WARM_UNIT_DIRECTIVE_RE = re.compile(r"^[ \t]*(define|ifdef|ifndef|elsedef|endif|flags)\b", re.M)


def _warm_prepare_unit_reuse(compiler: "Compiler", seen: Set[Path]) -> None:
    """Let jobs reuse the warm prefix's preprocessed units.  Only when no
    stdlib unit uses preprocessor or `flags` directives (those depend on, or
    change, state outside the file) and every unit is a plain default-frontend
    unit."""
    units = {path: unit for path, unit in compiler._units.items() if path in seen}
    if not units or set(units) != seen:
        return
    for path, unit in units.items():
        if unit.frontend is not None:
            return
        try:
            if _WARM_UNIT_DIRECTIVE_RE.search(path.read_text(encoding="utf-8")):
                return
        except OSError:
            return
    closure: Dict[Path, List[Path]] = {}

    def visit(path: Path, order: List[Path], visited: Set[Path]) -> None:
        if path in visited or path not in units:
            return
        visited.add(path)
        order.append(path)
        for _line, (target, _a, _b) in sorted(units[path].imports.items()):
            visit(compiler._resolve_import_target(path, target), order, visited)

    try:
        for path in units:
            order: List[Path] = []
            visit(path, order, set())
            closure[path] = order
    except ParseError:
        return
    compiler._warm_units = units
    compiler._warm_unit_closure = closure


def _warm_stdlib_prepare(force: bool = False, argv: Optional[Sequence[str]] = None) -> None:
    """Worker side, before each job: choose (building or rebuilding as needed)
    the prefix for the job's leading library imports and -D/-W settings,
    falling back to the stdlib alone.  --force-stdlib rebuilds every prefix."""
    global _WARM_STDLIB
    if os.environ.get("L2_NO_WARM_PREFIX", "").strip() not in ("", "0"):
        _WARM_STDLIB = None  # every job compiles cold
        return
    # Prefixes discarded here were frozen (gc.freeze below), so the collector
    # would never free their cyclic objects: unfreeze before collecting.
    dropped = False
    if force:
        dropped = bool(_WARM_PREFIXES)
        _WARM_PREFIXES.clear()
    stdlib = _warm_stdlib_target()
    settings = _warm_job_settings(argv) if argv else _WARM_DEFAULT_SETTINGS
    keys: List[Tuple[Tuple[Path, ...], _WarmSettings]] = []
    job_targets = _warm_job_targets(argv) if argv else None
    if job_targets:
        keys.append((job_targets, settings))
    if stdlib is not None and ((stdlib,), settings) not in keys:
        keys.append(((stdlib,), settings))
    _WARM_STDLIB = None
    for key in keys:
        warm = _WARM_PREFIXES.get(key)
        if warm is not None and not warm.taken and warm.fresh():
            _WARM_PREFIXES.move_to_end(key)
            _WARM_STDLIB = warm
            return
        if _WARM_PREFIXES.pop(key, None) is not None:
            dropped = True
        warm = _build_warm_stdlib(*key)
        if warm is None:
            continue
        _WARM_PREFIXES[key] = warm
        while len(_WARM_PREFIXES) > _WARM_PREFIX_LIMIT:
            _WARM_PREFIXES.popitem(last=False)
            dropped = True
        _WARM_STDLIB = warm
        import gc
        if dropped and hasattr(gc, "unfreeze"):
            gc.unfreeze()
        gc.collect()
        if hasattr(gc, "freeze"):
            gc.freeze()  # keep forked children from touching the warm pages
        return

def _daemon_asm_prepare() -> None:
    """Worker side, before forking each job: pick up code that earlier jobs
    (of any worker) assembled, load keystone once, and map the compile-time
    :asm words of the job's warm prefix.  The forked child inherits all of it,
    so it neither imports keystone nor assembles code another job needed."""
    if os.environ.get("L2_NO_ASM_PREWARM", "").strip() not in ("", "0"):
        return
    _ASM_CODE_STORE.refresh()
    _PEEPHOLE_STORE.refresh()
    _ensure_keystone()
    warm = _WARM_STDLIB
    if warm is None:
        return
    if warm.asm_mapped:
        return
    warm.asm_mapped = True
    for word in list(warm.compiler.dictionary.words.values()):
        definition = word.definition
        if not isinstance(definition, AsmDefinition):
            continue
        try:
            _ct_asm_static_func(word.name, definition.body.strip("\n"))
        except ParseError:
            continue  # reported if a job actually runs it at compile time


# ---------------------------------------------------------------------------
# § 22. Command-line interface
# ---------------------------------------------------------------------------

def cli(
    argv: Sequence[str],
    *,
    event_observer: Optional[Callable[[Dict[str, Any]], None]] = None,
) -> int:
    import argparse
    parser = argparse.ArgumentParser(description="L2 compiler driver")
    parser.add_argument(
        "source",
        type=Path,
        nargs="?",
        default=None,
        help="input .sl file (optional with --clean, --repl, --docs, --docs-serve, or standalone --check-integrity)",
    )
    parser.add_argument("-o", dest="output", type=Path, default=None, help="output path (defaults vary by artifact)")
    parser.add_argument(
        "-I",
        "--include",
        dest="include_paths",
        action="append",
        default=[],
        type=Path,
        help="add import search path (repeatable)",
    )
    parser.add_argument("--artifact", choices=["exe", "shared", "static", "obj"], default="exe", help="choose final artifact type")
    parser.add_argument(
        "--c-abi",
        "--sysv-wrappers",
        dest="c_abi",
        action="store_true",
        help="emit SysV C ABI wrappers and companion C header for runtime functions (requires --artifact shared, static, or obj)",
    )
    parser.add_argument("--emit-asm", action="store_true", help="stop after generating asm")
    parser.add_argument(
        "--events-stream",
        default=None,
        metavar="PATH",
        help="write compiler events as JSON Lines to a file path",
    )
    parser.add_argument(
        "--events-filter",
        default=None,
        metavar="PATTERNS",
        help="comma-separated event name patterns (fnmatch, e.g. 'compiler.error*,definition.*') "
             "limiting what --events-stream writes",
    )
    parser.add_argument(
        "--events-ring",
        type=int,
        default=DEFAULT_EVENT_RING_CAPACITY,
        metavar="N",
        help="number of recent events kept for replay (default: %(default)s)",
    )
    parser.add_argument(
        "--no-events",
        action="store_true",
        help="disable every compiler event, including CT handlers and error recovery dispatch",
    )
    parser.add_argument(
        "--no-events-json",
        action="store_true",
        help="disable JSONL event-file output only (CT handlers, socket observers, and recovery stay on)",
    )
    parser.add_argument("--temp-dir", type=Path, default=Path("build"))
    parser.add_argument("--debug", action="store_true", help="compile with debug info")
    parser.add_argument("--run", action="store_true", help="run the built binary after successful build")
    parser.add_argument("--dbg", action="store_true", help="launch gdb on the built binary after successful build")
    parser.add_argument("--clean", action="store_true", help="remove the temp build directory and exit")
    parser.add_argument("--repl", action="store_true", help="interactive REPL; source file is optional")
    parser.add_argument("-l", dest="libs", action="append", default=[], help="pass library to linker (e.g. -l m or -l libc.so.6)")
    parser.add_argument("--no-folding", action="store_true", help="disable constant folding optimization")
    parser.add_argument("--no-peephole", action="store_true", help="disable peephole optimizations")
    parser.add_argument("--no-loop-unroll", action="store_true", help="disable loop unrolling optimization")
    parser.add_argument("--no-auto-inline", action="store_true", help="disable auto-inlining of small asm bodies")
    parser.add_argument("--no-string-dedup", action="store_true", help="disable string literal deduplication in emitted data section")
    parser.add_argument("--no-asm-opt", action="store_true", help="disable post-emission assembly optimization pass")
    parser.add_argument("-O0", dest="O0", action="store_true", help="disable all optimizations")
    parser.add_argument("-O2", dest="O2", action="store_true", help="fast mode: disable all optimizations and checks")
    parser.add_argument("-v", "--verbose", type=int, default=0, metavar="LEVEL", help="verbosity level (1=summary+timing, 2=per-function/DCE, 3=full debug, 4=optimization detail)")
    parser.add_argument("--no-extern-type-check", action="store_true", help="disable extern function argument count checking")
    parser.add_argument("--no-stack-check", action="store_true", help="disable stack underflow checking for builtins")
    parser.add_argument(
        "--no-cache",
        action="store_true",
        help="disable compiler caches (source graph + asm cache) while keeping timestamp-based tool up-to-date checks",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="force full rebuild (always recompile + assemble + relink); implies --no-cache",
    )
    parser.add_argument(
        "--check-references",
        action="store_true",
        help="report every unknown word in all definitions and macro bodies, including unused ones",
    )
    parser.add_argument(
        "--force-stdlib",
        action="store_true",
        help="rebuild the compile daemon's pre-parsed stdlib (otherwise rebuilt only when a stdlib file changes)",
    )
    parser.add_argument("--ct-run-main", action="store_true", help="execute 'main' via the compile-time VM after parsing")
    parser.add_argument(
        "--ct-argv",
        action="append",
        default=[],
        metavar="ARG",
        help="append argv item used during --ct-run-main/--script execution (repeatable)",
    )
    parser.add_argument(
        "--leak-check",
        action="store_true",
        help="run 'main' in CTVM, intercept mmap/munmap/mremap syscalls, and fail on leaked mappings",
    )
    parser.add_argument(
        "--source-embed",
        action="store_true",
        help="embed expanded source code into the final artifact",
    )
    parser.add_argument("--no-artifact", action="store_true", help="compile source but skip producing final output artifact")
    parser.add_argument("--docs", action="store_true", help="open searchable TUI for word/function documentation")
    parser.add_argument(
        "--docs-root",
        action="append",
        default=[],
        type=Path,
        help="extra file/directory root to scan for docs (repeatable)",
    )
    parser.add_argument(
        "--docs-query",
        default="",
        help="initial filter query for --docs mode",
    )
    parser.add_argument(
        "--docs-serve",
        action="store_true",
        help="serve docs as an interactive web app",
    )
    parser.add_argument(
        "--docs-host",
        default="127.0.0.1",
        help="bind host for --docs-serve (default: %(default)s)",
    )
    parser.add_argument(
        "--docs-port",
        type=int,
        default=8008,
        help="bind port for --docs-serve (default: %(default)s)",
    )
    parser.add_argument(
        "--docs-no-browser",
        action="store_true",
        help="do not auto-open browser in --docs-serve mode",
    )
    parser.add_argument(
        "--docs-all",
        action="store_true",
        help="include undocumented and private symbols in docs index",
    )
    parser.add_argument(
        "--docs-include-tests",
        action="store_true",
        help="include tests/extra_tests in docs index",
    )
    parser.add_argument(
        "--script",
        action="store_true",
        help="shortcut for --no-artifact --ct-run-main",
    )
    parser.add_argument(
        "--dump-cfg",
        nargs="?",
        default=None,
        const="__AUTO__",
        metavar="PATH",
        help="write Graphviz DOT control-flow dump (default: <temp-dir>/<source>.cfg.dot)",
    )
    parser.add_argument(
        "--macro-expansion-limit",
        type=int,
        default=DEFAULT_MACRO_EXPANSION_LIMIT,
        help="maximum nested macro expansion depth (default: %(default)s)",
    )
    parser.add_argument(
        "--macro-preview",
        action="store_true",
        help="print each macro expansion and rewrite application to stderr during parsing",
    )
    parser.add_argument(
        "--preview",
        action="store_true",
        help="print transformed source after macro expansion and compile-time execution",
    )
    parser.add_argument(
        "--macro-profile",
        nargs="?",
        const="stderr",
        default=None,
        metavar="PATH",
        help="dump macro expansion profile to stderr/stdout or a file path",
    )
    parser.add_argument(
        "-D",
        dest="defines",
        action="append",
        default=[],
        metavar="NAME",
        help="define a preprocessor symbol for ifdef/ifndef (repeatable)",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="validate source without producing artifacts (parse + compile only)",
    )
    parser.add_argument(
        "--check-integrity",
        action="store_true",
        help="run internal compiler integrity assertions (compiler-only: main.py, l2_main.py, docs.py)",
    )
    parser.add_argument(
        "-W",
        dest="warnings",
        action="append",
        default=[],
        metavar="NAME",
        help="enable warning (e.g. -W redefine, -W stack-depth, -W all)",
    )
    parser.add_argument(
        "--Werror",
        action="store_true",
        help="treat all warnings as errors",
    )

    def _consume_unknown_link_tokens(raw_tokens: Sequence[str], *, strict_long_opts: bool) -> List[str]:
        """Parse unknown args as linker/library-style tokens."""
        out: List[str] = []
        i = 0
        while i < len(raw_tokens):
            tok = raw_tokens[i]
            if tok in ("-l", "-L"):
                if i + 1 >= len(raw_tokens):
                    parser.error(f"{tok} requires a value")
                out.append(f"{tok}{raw_tokens[i + 1]}")
                i += 2
                continue
            if tok.startswith(("-l", "-L", "-Wl,")):
                out.append(tok)
                i += 1
                continue
            if tok.startswith("--"):
                if strict_long_opts:
                    parser.error(f"unknown option in flags pragma: {tok}")
                i += 1
                continue
            # Single-dash passthrough or raw library/path token.
            out.append(tok)
            i += 1
        return out

    # main.py handles these before the compiler runs (see l2_client); they
    # are declared here so --help lists them.
    daemon_group = parser.add_argument_group(
        "compile daemon",
        "main.py compiles through a background daemon, one per checkout; these "
        "options are handled by main.py. Management commands take --json, and "
        "--daemon-stop/--daemon-kill/--daemon-reload/--daemon-clear also take --all.",
    )
    daemon_group.add_argument("--daemon", dest="_daemon_require", action="store_true",
                              help="require the daemon: fail instead of compiling in this process")
    daemon_group.add_argument("--no-daemon", dest="_daemon_off", action="store_true",
                              help="compile in this process, without the daemon")
    daemon_group.add_argument("--daemon-name", dest="_daemon_name", metavar="NAME",
                              help="use the daemon instance NAME of this checkout (default: L2_DAEMON_NAME or 'default')")
    daemon_group.add_argument("--daemon-workers", dest="_daemon_workers", metavar="N",
                              help="worker processes for a daemon that starts now (default: min(cpus, 8))")
    daemon_group.add_argument("--daemon-idle-timeout", dest="_daemon_idle", metavar="MIN",
                              help="minutes without requests before a daemon that starts now exits (default: 30)")
    for flag, nargs, metavar, text in (
        ("--daemon-status", None, None, "pid, uptime, workers, queue, settings and recent compiles"),
        ("--daemon-start", None, None, "start the daemon now"),
        ("--daemon-stop", None, None, "stop after running jobs finish"),
        ("--daemon-kill", None, None, "stop now: daemon, workers and running jobs"),
        ("--daemon-restart", None, None, "graceful stop and start, keeping its settings"),
        ("--daemon-reload", None, None, "re-execute in place after running jobs finish"),
        ("--daemon-list", None, None, "every daemon of yours, in all checkouts"),
        ("--daemon-logs", "?", "N|REQUEST", "last N lines of the daemon log, or one request's log (--follow)"),
        ("--daemon-events", "?", "PATTERN", "recent daemon events (--follow streams them)"),
        ("--daemon-clear", None, None, "drop the request history and restart workers with empty caches"),
        ("--daemon-prune", None, None, "remove files of stopped daemons and old request logs (--days N)"),
        ("--daemon-config", None, None, "settings for a new daemon and where each comes from"),
    ):
        dest = "_daemon_cmd_" + flag[len("--daemon-"):]
        if nargs is None:
            daemon_group.add_argument(flag, dest=dest, action="store_true", help=text)
        else:
            daemon_group.add_argument(flag, dest=dest, nargs=nargs, metavar=metavar, default=None,
                                      const="", help=text)

    # Parse known and unknown args to allow -l flags anywhere
    args, unknown = parser.parse_known_args(argv)
    for name, value in vars(args).items():
        # --no-daemon means "in this process", which this already is.
        if name.startswith("_daemon") and name != "_daemon_off" and value not in (None, False):
            parser.error("the daemon options are handled by main.py: run python main.py "
                         + " ".join(str(tok) for tok in argv))
    for tok in unknown:
        if tok == "--profile" or tok.startswith("--profile="):
            parser.error("--profile is no longer supported")
        if tok == "--compiler-profile" or tok.startswith("--compiler-profile="):
            parser.error("--compiler-profile is no longer supported")
        if tok.startswith("--"):
            parser.error(f"unknown option: {tok}")
    for lib_tok in _consume_unknown_link_tokens(unknown, strict_long_opts=False):
        if lib_tok not in args.libs:
            args.libs.append(lib_tok)

    if args.script:
        args.no_artifact = True
        args.ct_run_main = True

    if args.leak_check:
        args.no_artifact = True
        args.ct_run_main = True

    if args.check:
        args.no_artifact = True

    if args.force:
        args.no_cache = True

    source_graph_cache: Optional[SourceGraphCache] = None
    if not args.no_cache:
        source_graph_cache = SourceGraphCache(args.temp_dir / ".l2cache" / "graphs")

    # Only allocate the event bus when an observer or stream actually wants
    # compiler events. The default CLI path is hot enough that this bookkeeping
    # should be fully skipped unless tooling opted in.
    if args.no_events and args.events_stream is not None:
        parser.error("--events-stream cannot be combined with --no-events")
    if args.no_events_json and args.events_stream is not None:
        parser.error("--events-stream cannot be combined with --no-events-json")
    if args.events_filter is not None and args.events_stream is None:
        parser.error("--events-filter needs --events-stream")
    if args.events_ring < 0:
        parser.error("--events-ring must be >= 0")
    event_bus: Optional[EventBus] = None
    if not args.no_events and (event_observer is not None or args.events_stream is not None):
        event_bus = EventBus(max(0, args.events_ring))
    if event_observer is not None and event_bus is not None:
        event_bus.subscribe("*", event_observer)
    if args.events_stream is not None:
        stream_arg = str(args.events_stream)
        try:
            event_stream = open(stream_arg, "w", encoding="utf-8", buffering=1)
        except OSError as exc:
            parser.error(f"cannot open --events-stream {stream_arg!r}: {exc}")
        stream_patterns = ([p.strip() for p in str(args.events_filter).split(",") if p.strip()]
                           if args.events_filter else None)
        event_bus.add_sink(_jsonl_event_sink(event_stream), stream_patterns)

    parser_defaults = {
        action.dest: action.default
        for action in parser._actions
        if getattr(action, "dest", None) and action.dest != "help"
    }

    if args.macro_expansion_limit < 1:
        parser.error("--macro-expansion-limit must be >= 1")

    artifact_kind = args.artifact
    if args.O2:
        folding_enabled = False
        peephole_enabled = False
        loop_unroll_enabled = False
        auto_inline_enabled = False
        asm_post_opt_enabled = False
        string_deduplication_enabled = not args.no_string_dedup
        extern_type_check_enabled = False
        stack_check_enabled = False
    elif args.O0:
        folding_enabled = False
        peephole_enabled = False
        loop_unroll_enabled = False
        auto_inline_enabled = not args.no_auto_inline
        asm_post_opt_enabled = False
        string_deduplication_enabled = not args.no_string_dedup
        extern_type_check_enabled = not args.no_extern_type_check
        stack_check_enabled = not args.no_stack_check
    else:
        folding_enabled = not args.no_folding
        peephole_enabled = not args.no_peephole
        loop_unroll_enabled = not args.no_loop_unroll
        auto_inline_enabled = not args.no_auto_inline
        asm_post_opt_enabled = not args.no_asm_opt
        string_deduplication_enabled = not args.no_string_dedup
        extern_type_check_enabled = not args.no_extern_type_check
        stack_check_enabled = not args.no_stack_check
    cfg_output: Optional[Path] = None
    verbosity: int = args.verbose

    if args.ct_run_main and artifact_kind != "exe":
        parser.error("--ct-run-main requires --artifact exe")

    if artifact_kind != "exe" and (args.run or args.dbg):
        parser.error("--run/--dbg are only available when --artifact exe is selected")

    if args.no_artifact and (args.run or args.dbg):
        parser.error("--run/--dbg are not available with --no-artifact")

    if args.clean:
        try:
            if args.temp_dir.exists():
                import shutil
                shutil.rmtree(args.temp_dir)
                print(f"[info] removed {args.temp_dir}")
            else:
                print(f"[info] {args.temp_dir} does not exist")
        except Exception as exc:
            print(f"[error] failed to remove {args.temp_dir}: {exc}")
            return 1
        return 0

    if args.docs and args.docs_serve:
        parser.error("--docs and --docs-serve are mutually exclusive")

    if args.docs_serve and not (1 <= int(args.docs_port) <= 65535):
        parser.error("--docs-port must be in range 1..65535")

    if args.docs:
        try:
            return run_docs_explorer(
                source=args.source,
                include_paths=args.include_paths,
                explicit_roots=args.docs_root,
                initial_query=str(args.docs_query or ""),
                include_undocumented=args.docs_all,
                include_private=args.docs_all,
                include_tests=args.docs_include_tests,
            )
        except CompileError as exc:
            print(f"[error] {exc}", file=sys.stderr)
            return 1

    if args.docs_serve:
        try:
            return run_docs_server(
                source=args.source,
                include_paths=args.include_paths,
                explicit_roots=args.docs_root,
                initial_query=str(args.docs_query or ""),
                include_undocumented=args.docs_all,
                include_private=args.docs_all,
                include_tests=args.docs_include_tests,
                host=str(args.docs_host or "127.0.0.1"),
                port=int(args.docs_port),
                open_browser=not args.docs_no_browser,
            )
        except CompileError as exc:
            print(f"[error] {exc}", file=sys.stderr)
            return 1

    if args.source is None and args.check_integrity and not args.repl:
        if args.dump_cfg is not None:
            parser.error("--dump-cfg requires a source file")
        try:
            _run_integrity_checks()
        except CompileError as exc:
            print(f"[error] {exc}")
            return 1
        print("ok")
        return 0

    if args.source is None and not args.repl:
        parser.error("the following arguments are required: source")

    if args.dump_cfg is not None:
        if args.repl:
            parser.error("--dump-cfg is not available with --repl")
        if args.source is None:
            parser.error("--dump-cfg requires a source file")
        if args.dump_cfg == "__AUTO__":
            cfg_output = args.temp_dir / f"{args.source.stem}.cfg.dot"
        else:
            cfg_output = Path(args.dump_cfg)

    output_was_auto = False
    if not args.repl and args.output is None and not args.no_artifact:
        stem = args.source.stem
        default_outputs = {
            "exe": Path("a.out"),
            "shared": Path(f"lib{stem}.so"),
            "static": Path(f"lib{stem}.a"),
            "obj": Path(f"{stem}.o"),
        }
        args.output = default_outputs[artifact_kind]
        output_was_auto = True

    if not args.repl and artifact_kind in {"static", "obj"} and args.libs:
        print("[warn] --libs ignored for static/object outputs")

    def _new_cli_compiler() -> "Compiler":
        return Compiler(
            include_paths=_default_include_paths(args.include_paths),
            macro_expansion_limit=args.macro_expansion_limit,
            macro_preview=args.macro_preview,
            defines=args.defines,
            source_graph_cache=source_graph_cache,
            event_bus=event_bus,
        )

    # In a daemon job, start from the worker's pre-parsed stdlib when the
    # settings that affect parsing are the defaults it was built with.
    warm_prefix = (_WARM_STDLIB if _WARM_STDLIB is not None
                   and _warm_stdlib_args_eligible(args, event_bus, _WARM_STDLIB) else None)
    if warm_prefix is not None:
        compiler = warm_prefix.take(_default_include_paths(args.include_paths), source_graph_cache)
    else:
        compiler = _new_cli_compiler()
    # Warning configuration
    warnings_set = set(args.warnings)
    werror = args.Werror
    # Support GCC-style -Werror (single dash, parsed as -W error)
    if "error" in warnings_set:
        warnings_set.discard("error")
        werror = True
    # -Werror without explicit -W categories implies -W all
    if werror and not warnings_set:
        warnings_set.add("all")

    def _configure_cli_compiler(compiler: "Compiler") -> None:
        compiler.parser.events_hard_disabled = bool(args.no_events)
        compiler.parser.event_ring_capacity = args.events_ring
        compiler.assembler.enable_constant_folding = folding_enabled
        compiler.assembler.enable_peephole_optimization = peephole_enabled
        compiler.assembler.enable_loop_unroll = loop_unroll_enabled
        compiler.assembler.enable_auto_inline = auto_inline_enabled
        compiler.assembler.enable_string_deduplication = string_deduplication_enabled
        compiler.assembler.enable_extern_type_check = extern_type_check_enabled
        compiler.assembler.enable_stack_check = stack_check_enabled
        compiler.assembler.verbosity = verbosity
        if args.dump_cfg is not None:
            compiler.assembler._need_cfg = True
        compiler.parser._warnings_enabled = warnings_set
        compiler.parser._werror = werror
        compiler.parser.preview_trace_enabled = args.preview
        compiler.parser.set_macro_profile_enabled(args.macro_profile is not None)
        # --check-references also checks unused macros, so they are kept.
        compiler.parser.enable_dead_macro_elimination = not args.repl and not args.check_references
        compiler.parser.enable_unused_rewrite_elimination = not args.repl
        # Route dictionary redefine warnings through the parser's _warn system
        if warnings_set or werror:
            def _dict_warn_cb(name: str, priority: int) -> None:
                compiler.parser._warn(
                    compiler.parser._last_token, "redefine",
                    f"redefining word {name} (priority {priority})",
                )
            compiler.parser.dictionary.warn_callback = _dict_warn_cb

    _configure_cli_compiler(compiler)
    cache: Optional[BuildCache] = None

    def _build_cache_flags_hash() -> str:
        """The build cache's key for this compile: every option the assembly
        depends on, read after source-level `flags` pragmas were merged."""
        assert cache is not None
        include_key = []
        for path in args.include_paths:
            try:
                include_key.append(str(Path(path).expanduser().resolve()))
            except OSError:
                include_key.append(str(path))
        settings = "|".join([
            "defines=" + "\x1f".join(sorted(str(item) for item in args.defines)),
            "warnings=" + "\x1f".join(sorted(str(item) for item in warnings_set)),
            f"werror={int(bool(werror))}",
            "includes=" + "\x1f".join(include_key),
            f"loop_unroll={int(bool(loop_unroll_enabled))}",
            f"stack_check={int(bool(stack_check_enabled))}",
            f"extern_type_check={int(bool(extern_type_check_enabled))}",
            f"macro_expansion_limit={args.macro_expansion_limit}",
        ])
        return cache.flags_hash(
            args.debug,
            folding_enabled,
            peephole_enabled,
            auto_inline_enabled,
            asm_post_opt_enabled,
            string_deduplication_enabled,
            entry_mode,
            c_abi=bool(getattr(args, "c_abi", False)),
            settings=settings,
        )

    try:
        if args.repl:
            return run_repl(compiler, args.temp_dir, args.libs, debug=args.debug, initial_source=args.source)

        if args.source is not None:
            # Two passes allow `flags -D ...` / `flags -I ...` to expose
            # additional pragma-controlled sections/imports on the second pass.
            for _ in range(2):
                compiler.defines = set(args.defines)
                compiler.collect_source_flags(args.source)
                changed = False

                for include_path in compiler.source_include_paths:
                    if include_path not in args.include_paths:
                        args.include_paths.append(include_path)
                        changed = True

                if compiler.source_cli_flags:
                    probe_tokens = [str(args.source), *compiler.source_cli_flags]
                    src_args, src_unknown = parser.parse_known_args(probe_tokens)
                    for dest, default in parser_defaults.items():
                        cur_val = getattr(args, dest)
                        src_val = getattr(src_args, dest)
                        if isinstance(default, list):
                            for item in src_val:
                                if item not in cur_val:
                                    cur_val.append(item)
                                    changed = True
                            continue

                        if dest == "output" and output_was_auto and src_val != default:
                            setattr(args, dest, src_val)
                            output_was_auto = False
                            changed = True
                            continue

                        if cur_val == default and src_val != default:
                            setattr(args, dest, src_val)
                            changed = True

                    for lib_tok in _consume_unknown_link_tokens(src_unknown, strict_long_opts=True):
                        if lib_tok not in args.libs:
                            args.libs.append(lib_tok)
                            changed = True

                for flag in compiler.source_link_flags:
                    if flag not in args.libs:
                        args.libs.append(flag)
                        changed = True

                if args.script:
                    if not args.no_artifact or not args.ct_run_main:
                        changed = True
                    args.no_artifact = True
                    args.ct_run_main = True

                if args.leak_check:
                    if not args.no_artifact or not args.ct_run_main:
                        changed = True
                    args.no_artifact = True
                    args.ct_run_main = True

                if args.check and not args.no_artifact:
                    args.no_artifact = True
                    changed = True

                if args.force and not args.no_cache:
                    args.no_cache = True
                    changed = True

                if not changed:
                    break

            if warm_prefix is not None:
                # Source-level flags may have changed parse settings, and the
                # root must import the warm stdlib as its first form.
                if (_warm_stdlib_args_eligible(args, event_bus, warm_prefix)
                        and warm_prefix.accepts(compiler, args.source)):
                    warm_prefix.activate(compiler)
                else:
                    warm_prefix = None
                    compiler = _new_cli_compiler()
                    _configure_cli_compiler(compiler)
                    compiler.defines = set(args.defines)
                    compiler.collect_source_flags(args.source)

        cache_enabled = not args.no_cache
        if cache_enabled:
            if compiler.source_graph_cache is None:
                compiler.source_graph_cache = SourceGraphCache(args.temp_dir / ".l2cache" / "graphs")
            cache = BuildCache(args.temp_dir / ".l2cache" / "asm")
        else:
            compiler.source_graph_cache = None
            cache = None

        if args.macro_expansion_limit < 1:
            parser.error("--macro-expansion-limit must be >= 1")

        artifact_kind = args.artifact
        if args.O2:
            folding_enabled = False
            peephole_enabled = False
            loop_unroll_enabled = False
            auto_inline_enabled = False
            asm_post_opt_enabled = False
            string_deduplication_enabled = not args.no_string_dedup
            extern_type_check_enabled = False
            stack_check_enabled = False
        elif args.O0:
            folding_enabled = False
            peephole_enabled = False
            loop_unroll_enabled = False
            auto_inline_enabled = not args.no_auto_inline
            asm_post_opt_enabled = False
            string_deduplication_enabled = not args.no_string_dedup
            extern_type_check_enabled = not args.no_extern_type_check
            stack_check_enabled = not args.no_stack_check
        else:
            folding_enabled = not args.no_folding
            peephole_enabled = not args.no_peephole
            loop_unroll_enabled = not args.no_loop_unroll
            auto_inline_enabled = not args.no_auto_inline
            asm_post_opt_enabled = not args.no_asm_opt
            string_deduplication_enabled = not args.no_string_dedup
            extern_type_check_enabled = not args.no_extern_type_check
            stack_check_enabled = not args.no_stack_check
        verbosity = args.verbose

        if args.ct_run_main and artifact_kind != "exe":
            parser.error("--ct-run-main requires --artifact exe")
        if artifact_kind != "exe" and (args.run or args.dbg):
            parser.error("--run/--dbg are only available when --artifact exe is selected")
        if args.no_artifact and (args.run or args.dbg):
            parser.error("--run/--dbg are not available with --no-artifact")
        if getattr(args, "c_abi", False) and artifact_kind not in {"shared", "static", "obj"}:
            parser.error("--c-abi requires --artifact shared, static, or obj")

        if output_was_auto and not args.repl and not args.no_artifact:
            stem = args.source.stem
            default_outputs = {
                "exe": Path("a.out"),
                "shared": Path(f"lib{stem}.so"),
                "static": Path(f"lib{stem}.a"),
                "obj": Path(f"{stem}.o"),
            }
            args.output = default_outputs[artifact_kind]

        normalized_include_paths: List[Path] = []
        seen_include_paths: Set[Path] = set()
        for include_base in _default_include_paths(args.include_paths):
            resolved = include_base.expanduser().resolve()
            if resolved not in seen_include_paths:
                seen_include_paths.add(resolved)
                normalized_include_paths.append(resolved)
        compiler.include_paths = normalized_include_paths
        compiler._import_resolve_cache.clear()
        compiler.defines = set(args.defines)
        compiler.parser.macro_expansion_limit = args.macro_expansion_limit
        compiler.parser.macro_preview = args.macro_preview
        compiler.parser.preview_trace_enabled = args.preview
        compiler.parser.set_macro_profile_enabled(args.macro_profile is not None)
        compiler.parser.enable_dead_macro_elimination = not args.repl and not args.check_references
        compiler.parser.enable_unused_rewrite_elimination = not args.repl

        compiler.assembler.enable_constant_folding = folding_enabled
        compiler.assembler.enable_peephole_optimization = peephole_enabled
        compiler.assembler.enable_loop_unroll = loop_unroll_enabled
        compiler.assembler.enable_auto_inline = auto_inline_enabled
        compiler.assembler.enable_string_deduplication = string_deduplication_enabled
        compiler.assembler.enable_extern_type_check = extern_type_check_enabled
        compiler.assembler.enable_stack_check = stack_check_enabled
        compiler.assembler.verbosity = verbosity

        warnings_set = set(args.warnings)
        werror = args.Werror
        if "error" in warnings_set:
            warnings_set.discard("error")
            werror = True
        if werror and not warnings_set:
            warnings_set.add("all")
        compiler.parser._warnings_enabled = warnings_set
        compiler.parser._werror = werror
        if warnings_set or werror:
            def _dict_warn_cb(name: str, priority: int) -> None:
                compiler.parser._warn(
                    compiler.parser._last_token, "redefine",
                    f"redefining word {name} (priority {priority})",
                )
            compiler.parser.dictionary.warn_callback = _dict_warn_cb
        else:
            compiler.parser.dictionary.warn_callback = None

        if args.check_integrity:
            _run_integrity_checks()
            print("ok")

        ct_run_libs = list(args.libs)
        if args.source is not None:
            for lib in _load_sidecar_meta_libs(args.source):
                if lib not in args.libs:
                    args.libs.append(lib)
                if lib not in ct_run_libs:
                    ct_run_libs.append(lib)

        cfg_output = None
        if args.dump_cfg is not None:
            if args.repl:
                parser.error("--dump-cfg is not available with --repl")
            if args.source is None:
                parser.error("--dump-cfg requires a source file")
            if args.dump_cfg == "__AUTO__":
                cfg_output = args.temp_dir / f"{args.source.stem}.cfg.dot"
            else:
                cfg_output = Path(args.dump_cfg)
            compiler.assembler._need_cfg = True
        else:
            compiler.assembler._need_cfg = False

        entry_mode = "program" if artifact_kind == "exe" else "library"

        # --- assembly-level cache check ---
        asm_text: Optional[str] = None
        fhash = ""
        cache_asm_hit = False
        # An event consumer must observe the compiler pipeline even when the
        # artifact cache is warm; otherwise an IDE sees an empty stream.
        # --source-embed needs this emission's selected-definition catalog.
        if (cache and event_observer is None and args.events_stream is None and not args.ct_run_main
                and args.dump_cfg is None and not args.preview and not args.source_embed
                and not args.check_references):
            fhash = _build_cache_flags_hash()
            manifest = cache.load_manifest(args.source)
            if manifest and cache.check_fresh(manifest, fhash):
                cached = cache.get_cached_asm(manifest)
                if cached is not None:
                    asm_text = cached
                    cache_asm_hit = True
                    if verbosity >= 1:
                        print(f"[v1] cache hit for {args.source}")

        if asm_text is None:
            if verbosity >= 1:
                import time as _time_mod
                _compile_t0 = _time_mod.perf_counter()

            mod_name = args.source.stem if args.source else "l2"
            c_abi_flag = getattr(args, "c_abi", False)
            if compiler._last_loaded_path == args.source.resolve() and compiler._last_loaded_source is not None:
                emission = compiler.compile_preloaded(
                    debug=args.debug,
                    entry_mode=entry_mode,
                    c_abi=c_abi_flag,
                    module_name=mod_name,
                    render_preview=args.preview,
                )
            else:
                emission = compiler.compile_file(
                    args.source,
                    debug=args.debug,
                    entry_mode=entry_mode,
                    c_abi=c_abi_flag,
                    module_name=mod_name,
                    render_preview=args.preview,
                )

            # Snapshot assembly text *before* ct-run-main JIT execution, which may
            # corrupt Python heap objects depending on memory layout.
            asm_text = emission.snapshot()
            if args.preview:
                print("[preview] compile-time execution trace:")
                trace_text = _render_preview_trace_events(compiler.parser.preview_trace_events).rstrip()
                if trace_text:
                    print(trace_text)
                else:
                    print("# (no compile-time execution events)")
                print("[preview] transformed source (post-macro + post-compile-time):")
                preview_text = compiler.last_transformed_source.rstrip()
                if preview_text:
                    print(preview_text)
                else:
                    print("# (no transformed forms)")
                print("[preview] end")
            if verbosity >= 1:
                _compile_dt = (_time_mod.perf_counter() - _compile_t0) * 1000
                print(f"[v1] compilation: {_compile_dt:.1f}ms")
                print(f"[v1] assembly size: {len(asm_text)} bytes")

            has_ct = bool(compiler.parser.compile_time_vm._ct_executed)

            if asm_post_opt_enabled:
                use_asm_opt_cache = cache_enabled
                asm_opt_key_path = args.temp_dir / f"{args.source.stem}.asmopt.key"
                asm_opt_cache_path = args.temp_dir / f"{args.source.stem}.asmopt.asm"
                asm_opt_cache_version = "v1"

                asm_digest: Optional[str] = None
                try:
                    import hashlib
                    asm_digest = hashlib.blake2b(asm_text.encode("utf-8"), digest_size=16).hexdigest()
                except Exception:
                    asm_digest = None

                optimized_from_cache = False
                asm_opt_stats: Dict[str, int] = {}
                asm_opt_pass_logs: List[str] = []
                if use_asm_opt_cache and asm_digest is not None:
                    try:
                        cached_key = asm_opt_key_path.read_text(encoding="utf-8").strip()
                    except OSError:
                        cached_key = ""
                    expected_key = f"{asm_opt_cache_version}:{asm_digest}"
                    if cached_key == expected_key:
                        try:
                            asm_text = asm_opt_cache_path.read_text(encoding="utf-8")
                            optimized_from_cache = True
                        except OSError:
                            optimized_from_cache = False

                if not optimized_from_cache:
                    optimized_asm, asm_opt_stats, asm_opt_pass_logs = optimize_emitted_asm_text(
                        asm_text,
                        collect_pass_logs=(verbosity >= 4),
                    )
                    if optimized_asm != asm_text:
                        asm_text = optimized_asm
                    if use_asm_opt_cache and asm_digest is not None:
                        try:
                            asm_opt_key_path.parent.mkdir(parents=True, exist_ok=True)
                            _write_text_if_changed(asm_opt_cache_path, asm_text)
                            _write_text_if_changed(asm_opt_key_path, f"{asm_opt_cache_version}:{asm_digest}")
                        except OSError:
                            pass

                if verbosity >= 1:
                    if optimized_from_cache:
                        print("[v1] asm post-opt: cache hit")
                    else:
                        changed = sum(asm_opt_stats.values())
                        print(f"[v1] asm post-opt: {changed} rewrite(s)")
                if verbosity >= 2 and not optimized_from_cache:
                    for key in sorted(asm_opt_stats):
                        if asm_opt_stats[key]:
                            print(f"[v2] asm post-opt {key}: {asm_opt_stats[key]}")
                if verbosity >= 4 and not optimized_from_cache:
                    for msg in asm_opt_pass_logs:
                        print(f"[v4] asm post-opt {msg}")

            if cache and not args.ct_run_main:
                if not fhash:
                    fhash = _build_cache_flags_hash()
                cache.save(args.source, compiler._loaded_files, fhash, asm_text, has_ct_effects=has_ct,
                           absent=compiler._import_absent, links=compiler._import_links)

        # Merge source-level `flags ...` pragmas into effective linker flags.
        if compiler.source_link_flags:
            for flag in compiler.source_link_flags:
                if flag not in args.libs:
                    args.libs.append(flag)
                if flag not in ct_run_libs:
                    ct_run_libs.append(flag)

        def _normalize_ct_runtime_libs(raw_libs: List[str]) -> List[str]:
            out: List[str] = []
            seen: Set[str] = set()
            for lib in raw_libs:
                token = str(lib).strip()
                if not token:
                    continue
                # Linker/search/include-only flags are not directly loadable via ctypes.
                if token.startswith(("-L", "-Wl,")):
                    continue
                if token == "-I" or token.startswith("-I") or token.startswith("--include"):
                    continue
                if token.startswith("-l:"):
                    token = token[3:]
                elif token.startswith("-l") and len(token) > 2:
                    token = token[2:]
                if token and token not in seen:
                    out.append(token)
                    seen.add(token)
            return out

        ct_run_libs = _normalize_ct_runtime_libs(ct_run_libs)
        if args.ct_run_main:
            # For CT execution, when a static archive path is provided,
            # also try loading a sibling shared object path.
            expanded_ct_libs: List[str] = []
            seen_ct_libs: Set[str] = set()
            for lib in ct_run_libs:
                if lib not in seen_ct_libs:
                    expanded_ct_libs.append(lib)
                    seen_ct_libs.add(lib)
                if lib.endswith(".a"):
                    so_variant = lib[:-2] + ".so"
                    if so_variant not in seen_ct_libs:
                        expanded_ct_libs.append(so_variant)
                        seen_ct_libs.add(so_variant)
            ct_run_libs = expanded_ct_libs

        if args.ct_run_main and args.source is not None:
            import subprocess
            try:
                ct_sidecar = _build_ct_sidecar_shared(args.source, args.temp_dir)
            except subprocess.CalledProcessError as exc:
                print(f"[error] failed to build compile-time sidecar library: {exc}")
                return 1
            if ct_sidecar is not None:
                so_lib = str(ct_sidecar.resolve())
                if so_lib not in ct_run_libs:
                    ct_run_libs.append(so_lib)

        if cfg_output is not None:
            cfg_output.parent.mkdir(parents=True, exist_ok=True)
            cfg_dot = compiler.assembler.render_last_cfg_dot()
            cfg_output.write_text(cfg_dot)
            print(f"[info] wrote {cfg_output}")

        if args.ct_run_main:
            bridge_source = compiler._last_loaded_source if args.source_embed else None
            compiler.parser.compile_time_vm.set_runtime_embedded_source(bridge_source)
        else:
            compiler.parser.compile_time_vm.set_runtime_embedded_source(None)

        if args.ct_run_main:
            ct_entry = "main"
            start_word = compiler.dictionary.lookup("_start")
            if start_word is not None and start_word.definition is not None:
                ct_entry = "_start"

            ct_argv0_path = args.output if args.output is not None else Path("a.out")
            try:
                rel_argv0 = os.path.relpath(str(ct_argv0_path), start=os.getcwd())
                if rel_argv0 and not rel_argv0.startswith("..") and not os.path.isabs(rel_argv0):
                    ct_argv0 = rel_argv0 if rel_argv0.startswith("./") else f"./{rel_argv0}"
                else:
                    ct_argv0 = str(ct_argv0_path)
            except Exception:
                ct_argv0 = str(ct_argv0_path)

            ct_runtime_argv = [ct_argv0, *[str(item) for item in (args.ct_argv or [])]]

            ct_run_exit_code = compiler.run_compile_time_word(
                ct_entry,
                libs=ct_run_libs,
                mmap_leak_check=args.leak_check,
                argv=ct_runtime_argv,
            )
            if args.leak_check:
                has_issues, summary = compiler.parser.compile_time_vm.mmap_leak_check_report()
                if has_issues:
                    print(summary, file=sys.stderr)
                    return 1
                print(summary)

        if args.source_embed:
            asm_text = _append_source_embed_to_asm(asm_text, compiler._last_loaded_source,
                                                   compiler.assembler.source_catalog)
    except (ParseError, CompileError, CompileTimeError) as exc:
        # Print all collected diagnostics in Rust-style format
        use_color = _diagnostic_color_enabled()
        diags = compiler.parser.reportable_diagnostics() if 'compiler' in dir() else []
        exc_diag = getattr(exc, 'diagnostic', None)
        # compilation-failed only summarizes the diagnostics printed below.
        if isinstance(exc_diag, Diagnostic) and exc_diag.code != "compilation-failed":
            existing_keys = {
                (d.level, d.message, str(d.path), int(d.line), int(d.column))
                for d in diags
            }
            key = (
                exc_diag.level,
                exc_diag.message,
                str(exc_diag.path),
                int(exc_diag.line),
                int(exc_diag.column),
            )
            # A location-less copy of an already reported error (the same
            # failure re-raised outside its CT frame) is not printed twice.
            unlocated_dup = int(exc_diag.line) <= 0 and any(
                d.level == exc_diag.level and d.message == exc_diag.message and d.code == exc_diag.code
                for d in diags)
            if key not in existing_keys and not unlocated_dup:
                diags.append(exc_diag)
        if diags:
            for diag in diags:
                print(diag.format(color=use_color), file=sys.stderr)
            error_count = sum(1 for d in diags if d.level == "error")
            warn_count = sum(1 for d in diags if d.level == "warning")
            summary_parts = []
            if error_count:
                summary_parts.append(f"{error_count} error(s)")
            if warn_count:
                summary_parts.append(f"{warn_count} warning(s)")
            if summary_parts:
                print(f"\n{' and '.join(summary_parts)} emitted", file=sys.stderr)
        else:
            print(f"[error] {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"[error] unexpected failure: {exc}", file=sys.stderr)
        return 1

    if args.check_references:
        reference_errors = compiler.check_references()
        if reference_errors:
            use_color = _diagnostic_color_enabled()
            for diag in reference_errors:
                print(diag.format(color=use_color), file=sys.stderr)
            print(f"\n{len(reference_errors)} error(s) emitted", file=sys.stderr)
            return 1

    # Print any warnings accumulated during successful compilation
    use_color = _diagnostic_color_enabled()
    reported = [d for d in compiler.parser.diagnostics if d.severity in ("warning", "note")]
    if reported:
        for diag in reported:
            print(diag.format(color=use_color), file=sys.stderr)
        warning_count = sum(1 for d in reported if d.severity == "warning")
        if warning_count:
            print(f"\n{warning_count} warning(s) emitted", file=sys.stderr)

    if args.macro_profile is not None:
        _emit_macro_profile_report(compiler.parser, args.macro_profile)

    args.temp_dir.mkdir(parents=True, exist_ok=True)
    asm_path = args.temp_dir / (args.source.stem + ".asm")
    obj_path = args.temp_dir / (args.source.stem + ".o")

    # A C ABI artifact always carries its companion declaration header,
    # regardless of whether the caller requested assembly-only output.
    if getattr(args, "c_abi", False) and args.output is not None:
        c_header = getattr(locals().get("emission"), "c_header", "")
        if c_header:
            header_path = args.output.with_suffix(".h")
            header_path.parent.mkdir(parents=True, exist_ok=True)
            header_path.write_text(c_header, encoding="utf-8")
            print(f"[info] wrote {header_path}")

    # --- incremental: skip nasm if assembly unchanged ---
    asm_changed = _write_text_if_changed(asm_path, asm_text, force=args.force)

    if args.emit_asm:
        if args.output is not None and not output_was_auto:
            # An explicit -o names the assembly file itself.
            if args.output.parent and not args.output.parent.exists():
                args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_text(asm_text)
            print(f"[info] wrote {args.output}")
            return 0
        print(f"[info] wrote {asm_path}")
        return 0

    if args.no_artifact:
        print("[info] skipped artifact generation (--no-artifact)")
        return ct_run_exit_code if args.ct_run_main else 0

    # --- incremental: skip nasm if .o newer than .asm ---
    need_nasm = args.force or asm_changed or not obj_path.exists()
    if not need_nasm:
        try:
            need_nasm = obj_path.stat().st_mtime < asm_path.stat().st_mtime
        except OSError:
            need_nasm = True
    if need_nasm:
        if args.debug or artifact_kind != "exe" or not _run_nasm_parallel(asm_path, obj_path, asm_text):
            run_nasm(asm_path, obj_path, debug=args.debug)

    if args.output.parent and not args.output.parent.exists():
        args.output.parent.mkdir(parents=True, exist_ok=True)

    # --- incremental: skip linker if output newer than .o AND same source ---
    # Track which .o produced the output so switching source files forces relink.
    link_stamp = args.temp_dir / f"{args.output.name}.link_src"

    link_fingerprint_parts = [
        f"obj={obj_path.resolve()}",
        f"artifact={artifact_kind}",
        f"debug={int(bool(args.debug))}",
    ]

    def _lib_file_from_token(tok: str) -> Optional[Path]:
        if tok.startswith("-l:") and len(tok) > 3:
            return Path(tok[3:]).expanduser()
        if tok.startswith("-"):
            return None
        return Path(tok).expanduser()

    for lib in args.libs:
        link_fingerprint_parts.append(f"lib={lib}")
        lib_file = _lib_file_from_token(lib)
        if lib_file is None:
            continue
        try:
            resolved = lib_file.resolve()
            st = resolved.stat()
        except OSError:
            continue
        link_fingerprint_parts.append(
            f"libfile={resolved}:identity={':'.join(map(str, _file_identity(st)))}"
        )
    link_fingerprint = "\n".join(link_fingerprint_parts)

    need_link = args.force or need_nasm or not args.output.exists()
    if not need_link:
        # Check that the output was linked from the same inputs/config last time.
        try:
            recorded = link_stamp.read_text()
        except OSError:
            recorded = ""
        if recorded != link_fingerprint:
            need_link = True
    if not need_link:
        try:
            need_link = args.output.stat().st_mtime < obj_path.stat().st_mtime
        except OSError:
            need_link = True

    if artifact_kind == "obj":
        dest = args.output
        if obj_path.resolve() != dest.resolve():
            if need_link:
                import shutil
                shutil.copy2(obj_path, dest)
    elif artifact_kind == "static":
        if need_link:
            build_static_library(obj_path, args.output)
    else:
        if need_link:
            # Remove existing output first to avoid "Text file busy" on Linux
            # when the old binary is still mapped by a running process.
            try:
                args.output.unlink(missing_ok=True)
            except OSError:
                pass
            run_linker(
                obj_path,
                args.output,
                debug=args.debug,
                libs=args.libs,
                shared=(artifact_kind == "shared"),
            )

    if need_link:
        _write_text_if_changed(link_stamp, link_fingerprint, force=args.force)
        print(f"[info] built {args.output}")
    else:
        print(f"[info] {args.output} is up to date")

    if artifact_kind == "exe":
        import subprocess
        exe_path = Path(args.output).resolve()
        if args.dbg:
            subprocess.run(["gdb", str(exe_path)])
        elif args.run:
            subprocess.run([str(exe_path)])
    return 0


# ---------------------------------------------------------------------------
# § 23. Compile daemon
# ---------------------------------------------------------------------------

# The client (main.py) finds or starts the daemon of a checkout, passes it its
# socket, pid file and state directory, and talks to it with one JSON line
# per request.  DAEMON_PROTOCOL must match main._DAEMON_PROTOCOL.
DAEMON_PROTOCOL = 2
DAEMON_CODE_FILES = ("l2_main.py", "l2_client.py", "main.py", "docs.py")
DAEMON_DEFAULT_IDLE_MINUTES = 30.0
# Extra workers (beyond one) idle this long are stopped; a worker whose
# memory grows past the limit is replaced after its job.
DAEMON_WORKER_IDLE_SECONDS = float(os.environ.get("L2_DAEMON_WORKER_IDLE", "300"))
DAEMON_WORKER_MAX_RSS = int(float(os.environ.get("L2_DAEMON_WORKER_MAX_RSS_MB", "1024")) * 1024 * 1024)
DAEMON_REQUEST_LOGS_KEPT = 200
# Settings a daemon takes when it starts; reported by status so the client can
# show where the running daemon differs (main._DAEMON_START_ENV).
DAEMON_START_ENV = ("L2_NO_WARM_PREFIX", "L2_DAEMON_WARM_PREFIXES", "L2_NO_ASM_PREWARM",
                    "L2_DAEMON_NO_AUTO_RELOAD", "L2_DAEMON_LOG_LEVEL", "L2_DAEMON_DRAIN_TIMEOUT")


def _daemon_code_hash() -> str:
    digest = hashlib.sha256()
    root = Path(__file__).resolve().parent
    for name in DAEMON_CODE_FILES:
        path = root / name
        digest.update(name.encode("utf-8"))
        try:
            digest.update(path.read_bytes())
        except OSError:
            digest.update(b"<missing>")
    return digest.hexdigest()


def _daemon_code_fingerprint() -> Tuple[Tuple[Any, ...], ...]:
    """Cheap per-request freshness check: each code file's identity (size,
    mtime, ctime, inode)."""
    root = Path(__file__).resolve().parent
    rows = []
    for name in DAEMON_CODE_FILES:
        try:
            rows.append((name, *_file_identity((root / name).stat())))
        except OSError:
            rows.append((name, -1))
    return tuple(rows)


# Seconds a reload waits for in-flight compiles before terminating workers.
DAEMON_DRAIN_TIMEOUT = float(os.environ.get("L2_DAEMON_DRAIN_TIMEOUT", "600"))


def _daemon_open_fds() -> int:
    try:
        return len(list(Path("/proc/self/fd").iterdir()))
    except OSError:
        return 0


def _process_rss(pid: int) -> int:
    try:
        for line in Path(f"/proc/{pid}/status").read_text(encoding="utf-8").splitlines():
            if line.startswith("VmRSS:"):
                return int(line.split()[1]) * 1024
    except (OSError, ValueError, IndexError):
        pass
    return 0


def _proc_start_time_ns(pid: int) -> Optional[int]:
    try:
        stat_text = Path(f"/proc/{pid}/stat").read_text(encoding="utf-8")
    except OSError:
        return None
    if ")" not in stat_text:
        return None
    rest = stat_text.rsplit(")", 1)[1].strip()
    fields = rest.split()
    if len(fields) < 20:
        return None
    try:
        start_ticks = int(fields[19])
    except ValueError:
        return None
    clk_tck = os.sysconf("SC_CLK_TCK")
    if clk_tck <= 0:
        clk_tck = 100
    return int(start_ticks * (1_000_000_000 / clk_tck))


def _write_daemon_lease(socket_path: str, pid: int) -> None:
    """Publish the live daemon identity and heartbeat for stale-process detection.

    The lease includes both the process PID and the process start time from
    /proc/<pid>/stat. A client validates both fields before believing the daemon
    is still the original instance.
    """
    lease_path = Path(socket_path + ".lease")
    lease_path.parent.mkdir(parents=True, exist_ok=True)
    lease_path.write_text(
        json.dumps({"pid": int(pid), "start_time_ns": _proc_start_time_ns(pid), "ts_ns": time.time_ns()}, separators=(",", ":")),
        encoding="utf-8",
    )


def _daemon_heartbeat_loop(socket_path: str, stop_event: threading.Event) -> None:
    """Refresh the daemon lease while the daemon is live."""
    while not stop_event.wait(0.5):
        try:
            _write_daemon_lease(socket_path, os.getpid())
        except Exception:
            pass


_DAEMON_CLI_EXEC_LOCK = threading.RLock()


def _run_cli_captured(
    argv: Sequence[str],
    *,
    color: bool,
    stdin_data: Optional[str],
    event_observer: Optional[Callable[[Dict[str, Any]], None]],
    output_files: Optional[Tuple[Any, Any]] = None,
) -> Tuple[int, str, str]:
    """Run the canonical CLI in-process, capturing Python and native stdio."""
    import tempfile
    import traceback

    owned_output_files = output_files is None
    if output_files is None:
        stdout_file = tempfile.TemporaryFile()
        stderr_file = tempfile.TemporaryFile()
    else:
        stdout_file, stderr_file = output_files

    try:
        with _DAEMON_CLI_EXEC_LOCK:
            sys.stdout.flush()
            sys.stderr.flush()
            saved_stdout_fd = os.dup(1)
            saved_stderr_fd = os.dup(2)
            saved_stdin = sys.stdin
            old_force_color = os.environ.get("L2_FORCE_COLOR")
            code = 1
            stdout_text = ""
            stderr_text = ""
            input_stream = None
            input_file = None
            saved_stdin_fd = os.dup(0)

            try:
                if stdin_data is not None:
                    input_file = tempfile.TemporaryFile()
                    input_file.write(stdin_data.encode("utf-8"))
                    input_file.seek(0)
                    os.dup2(input_file.fileno(), 0)
                else:
                    null_stdin_fd = os.open(os.devnull, os.O_RDONLY)
                    try:
                        os.dup2(null_stdin_fd, 0)
                    finally:
                        os.close(null_stdin_fd)
                input_stream = os.fdopen(os.dup(0), "r", encoding="utf-8")
                sys.stdin = input_stream

                os.dup2(stdout_file.fileno(), 1)
                os.dup2(stderr_file.fileno(), 2)
                os.environ["L2_FORCE_COLOR"] = "1" if color else "0"

                try:
                    code = int(cli(argv, event_observer=event_observer))
                except SystemExit as exc:
                    code = int(exc.code) if isinstance(exc.code, int) else 0
                except Exception:
                    traceback.print_exc(file=sys.stderr)
                    code = 1
                finally:
                    sys.stdout.flush()
                    sys.stderr.flush()

                stdout_file.seek(0)
                stderr_file.seek(0)
                stdout_text = stdout_file.read().decode("utf-8", errors="replace")
                stderr_text = stderr_file.read().decode("utf-8", errors="replace")
            finally:
                try:
                    sys.stdout.flush()
                    sys.stderr.flush()
                except Exception:
                    pass
                os.dup2(saved_stdout_fd, 1)
                os.dup2(saved_stderr_fd, 2)
                os.close(saved_stdout_fd)
                os.close(saved_stderr_fd)
                os.dup2(saved_stdin_fd, 0)
                os.close(saved_stdin_fd)
                sys.stdin = saved_stdin
                if input_stream is not None:
                    input_stream.close()
                if input_file is not None:
                    input_file.close()
                if old_force_color is None:
                    os.environ.pop("L2_FORCE_COLOR", None)
                else:
                    os.environ["L2_FORCE_COLOR"] = old_force_color

        return code, stdout_text, stderr_text
    finally:
        if owned_output_files:
            stdout_file.close()
            stderr_file.close()


# Environment variables that apply to one compile: a daemon job runs with the
# client's values (set or unset), as a compile without the daemon would.
# main.py keeps the same list.
_DAEMON_JOB_ENV = ("L2_NASM_PARALLEL", "L2_ASM_CACHE", "L2_ASM_CACHE_DIR", "L2_CT_MERGED_JIT")


def _sanitize_job_env(raw: Any) -> Dict[str, Optional[str]]:
    if not isinstance(raw, dict):
        return {}
    return {name: value for name, value in raw.items()
            if name in _DAEMON_JOB_ENV and (value is None or (isinstance(value, str) and "\x00" not in value))}


def _apply_job_env(job_env: Dict[str, Optional[str]]) -> None:
    """In a forked job: take the client's values.  When the cache settings
    differ from the worker's, drop what the worker cached in memory and the
    pack files it opened, as a fresh process would not have them."""
    before = (os.environ.get("L2_ASM_CACHE"), os.environ.get("L2_ASM_CACHE_DIR"))
    for name, value in job_env.items():
        if value is None:
            os.environ.pop(name, None)
        else:
            os.environ[name] = value
    if (os.environ.get("L2_ASM_CACHE"), os.environ.get("L2_ASM_CACHE_DIR")) != before:
        global _ASM_CODE_STORE, _PEEPHOLE_STORE
        _ASM_CODE_STORE = _CachePack()
        _PEEPHOLE_STORE = _CachePack("peephole", _compiler_source_fingerprint, 32 * 1024 * 1024)
        _ASM_CODE_MEMO.clear()
        _PEEPHOLE_MEMO.clear()
        _CT_ASM_STATIC_FUNCS.clear()


def _run_cli_isolated(
    argv: Sequence[str],
    *,
    color: bool,
    stdin_data: Optional[str],
    event_observer: Optional[Callable[[Dict[str, Any]], None]],
    tool_path: Optional[str] = None,
    child_started: Optional[Callable[[int], None]] = None,
    child_finished: Optional[Callable[[], None]] = None,
    job_env: Optional[Dict[str, Optional[str]]] = None,
    umask: Optional[int] = None,
) -> Tuple[int, str, str]:
    """Run the canonical CLI in a forked child so native execution is contained."""
    import tempfile

    with tempfile.TemporaryFile() as stdout_file, tempfile.TemporaryFile() as stderr_file:
        sys.stdout.flush()
        sys.stderr.flush()
        child_pid = os.fork()
        if child_pid == 0:
            try:
                if tool_path is not None:
                    os.environ["PATH"] = tool_path
                if job_env:
                    _apply_job_env(job_env)
                if umask is not None:
                    os.umask(umask)
                os.setpgid(0, 0)
                signal.signal(signal.SIGTERM, signal.SIG_DFL)
                code, _stdout_text, _stderr_text = _run_cli_captured(
                    argv,
                    color=color,
                    stdin_data=stdin_data,
                    event_observer=event_observer,
                    output_files=(stdout_file, stderr_file),
                )
            except BaseException:
                import traceback

                traceback.print_exc(file=sys.stderr)
                sys.stderr.flush()
                os._exit(1)
            os._exit(code)

        try:
            os.setpgid(child_pid, child_pid)
        except OSError:
            pass
        if child_started is not None:
            child_started(child_pid)
        while True:
            try:
                _waited_pid, wait_status = os.waitpid(child_pid, 0)
                break
            except OSError as exc:
                if exc.errno != errno.EINTR:
                    raise
        if child_finished is not None:
            child_finished()

        if os.WIFEXITED(wait_status):
            code = os.WEXITSTATUS(wait_status)
        elif os.WIFSIGNALED(wait_status):
            code = 128 + os.WTERMSIG(wait_status)
        else:
            code = 1
        stdout_file.seek(0)
        stderr_file.seek(0)
        stdout_text = stdout_file.read().decode("utf-8", errors="replace")
        stderr_text = stderr_file.read().decode("utf-8", errors="replace")
        return code, stdout_text, stderr_text


class _DaemonCompilerWorker:
    def __init__(self) -> None:
        env = os.environ.copy()
        env["L2_DAEMON"] = "0"
        self.busy = False
        self.retire = False  # stop after the current job (clear, memory limit)
        self.started = time.time()
        self.last_used = self.started
        self.jobs = 0
        self.process = subprocess.Popen(
            [sys.executable, str(Path(__file__).resolve()), "--daemon-worker"],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            bufsize=1,
            env=env,
        )

    def run(
        self,
        argv: Sequence[str],
        *,
        color: bool,
        stdin_data: Optional[str],
        event_observer: Optional[Callable[[Dict[str, Any]], None]],
        tool_path: Optional[str] = None,
        job_env: Optional[Dict[str, Optional[str]]] = None,
        cwd: Optional[str] = None,
        umask: Optional[int] = None,
        trusted_dirs: Optional[str] = None,
    ) -> Tuple[int, str, str]:
        if self.process.poll() is not None or self.process.stdin is None or self.process.stdout is None:
            raise RuntimeError("compiler worker is not running")
        self.jobs += 1
        request = {
            "cmd": "run",
            "argv": list(argv),
            "color": bool(color),
            "stdin": stdin_data,
            "stream_events": event_observer is not None,
            "tool_path": tool_path,
            "job_env": job_env or {},
            "cwd": cwd,
            "umask": umask,
            "trusted_dirs": trusted_dirs,
        }
        self.process.stdin.write(json.dumps(request, separators=(",", ":")) + "\n")
        self.process.stdin.flush()

        while True:
            line = self.process.stdout.readline()
            if not line:
                raise RuntimeError(f"compiler worker exited with status {self.process.poll()}")
            message = json.loads(line)
            kind = message.get("kind")
            if kind == "event":
                record = message.get("record")
                if isinstance(record, dict):
                    event_observer(record)
                continue
            if kind == "result":
                return (
                    int(message.get("code", 1)),
                    str(message.get("stdout", "")),
                    str(message.get("stderr", "")),
                )
            raise RuntimeError(f"invalid compiler worker response: {kind!r}")

    def details(self) -> Dict[str, Any]:
        now = time.time()
        return {
            "pid": self.process.pid,
            "busy": self.busy,
            "jobs": self.jobs,
            "rss_bytes": _process_rss(self.process.pid),
            "uptime_seconds": now - self.started,
            "idle_seconds": 0.0 if self.busy else now - self.last_used,
        }

    def close(self) -> None:
        if self.busy and self.process.poll() is None:
            self.process.terminate()
        if self.process.stdin is not None and not self.process.stdin.closed:
            try:
                self.process.stdin.close()
            except BrokenPipeError:
                pass
        try:
            self.process.wait(timeout=2.0)
        except subprocess.TimeoutExpired:
            self.process.terminate()
            try:
                self.process.wait(timeout=2.0)
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.process.wait()
        if self.process.stdout is not None:
            self.process.stdout.close()


# Standard modules that jobs import lazily (argument parsing, file
# operations, the toolchain, JIT code, --script).  A daemon worker imports
# them once, before forking any job, so jobs do not import them again.
_DAEMON_JOB_MODULES = (
    "argparse", "shutil", "copy", "dataclasses", "gettext", "locale", "zlib", "bz2", "lzma",
    "subprocess", "selectors", "signal", "warnings", "json", "tempfile", "textwrap",
    "ctypes", "mmap", "hashlib", "inspect", "ast", "dis", "tokenize", "weakref", "struct",
    "_colorize",
)


def _daemon_preload_job_modules() -> None:
    for name in _DAEMON_JOB_MODULES:
        try:
            importlib.import_module(name)
        except Exception:
            continue


def _daemon_worker_serve() -> int:
    _daemon_preload_job_modules()
    # A daemon started ahead of time (--daemon-start) has its workers ready
    # the pre-parsed stdlib and its compile-time code before the first job.
    # A daemon started by a compile does not: the waiting job builds what it
    # needs (its leading imports may not be the default stdlib).
    if os.environ.get("L2_DAEMON_WORKER_PREWARM") == "1":
        try:
            _warm_stdlib_prepare()
            _daemon_asm_prepare()
        except Exception:
            pass
    freeze_startup_objects(collect_first=True)
    protocol_fd = os.dup(1)
    protocol_stdin = os.fdopen(os.dup(0), "r", encoding="utf-8")
    active_child_pid: Optional[int] = None
    stopping = False

    def _handle_sigterm(_signum: int, _frame: Any) -> None:
        nonlocal stopping
        stopping = True
        if active_child_pid is not None:
            try:
                os.killpg(active_child_pid, signal.SIGTERM)
            except ProcessLookupError:
                pass

    signal.signal(signal.SIGTERM, _handle_sigterm)

    def _send(message: Dict[str, Any]) -> None:
        data = (json.dumps(message, separators=(",", ":")) + "\n").encode("utf-8")
        remaining = memoryview(data)
        while remaining:
            written = os.write(protocol_fd, remaining)
            remaining = remaining[written:]

    try:
        for line in protocol_stdin:
            try:
                request = json.loads(line)
            except ValueError as exc:
                _send({"kind": "result", "code": 2, "stdout": "", "stderr": f"invalid worker request: {exc}\n"})
                continue
            if request.get("cmd") == "shutdown":
                break
            if request.get("cmd") != "run" or not isinstance(request.get("argv"), list):
                _send({"kind": "result", "code": 2, "stdout": "", "stderr": "invalid worker command\n"})
                continue

            def _forward_event(record: Dict[str, Any]) -> None:
                # Typed JSON projection; tooling observers are isolated, so
                # an event without a projection is not forwarded.
                try:
                    projected = _event_json_value(record, set())
                except ValueError:
                    return
                _send({"kind": "event", "record": projected})

            def _child_started(pid: int) -> None:
                nonlocal active_child_pid
                active_child_pid = pid

            def _child_finished() -> None:
                nonlocal active_child_pid
                active_child_pid = None

            job_argv = [str(arg) for arg in request["argv"]]
            # The job runs in the caller's directory, with its umask and its
            # trusted directories (which decide what may be pre-parsed).
            cwd = request.get("cwd")
            if isinstance(cwd, str) and cwd:
                try:
                    os.chdir(cwd)
                except OSError as exc:
                    _send({"kind": "result", "code": 2, "stdout": "",
                           "stderr": f"error: cannot use the working directory {cwd}: {exc}\n"})
                    continue
            trusted = request.get("trusted_dirs")
            if isinstance(trusted, str) and "\x00" not in trusted:
                os.environ["L2_DAEMON_TRUSTED_DIRS"] = trusted
            else:
                os.environ.pop("L2_DAEMON_TRUSTED_DIRS", None)
            umask = request.get("umask")
            try:
                _warm_stdlib_prepare(force="--force-stdlib" in job_argv, argv=job_argv)
            except Exception:
                pass  # jobs then compile cold
            try:
                _daemon_asm_prepare()
            except Exception:
                pass  # jobs then assemble their own code
            code, stdout_text, stderr_text = _run_cli_isolated(
                job_argv,
                color=bool(request.get("color")),
                stdin_data=request.get("stdin") if isinstance(request.get("stdin"), str) else None,
                event_observer=_forward_event if request.get("stream_events") else None,
                tool_path=request.get("tool_path") if isinstance(request.get("tool_path"), str) else None,
                child_started=_child_started,
                child_finished=_child_finished,
                job_env=_sanitize_job_env(request.get("job_env")),
                umask=umask if isinstance(umask, int) and 0 <= umask <= 0o777 else None,
            )
            _send({"kind": "result", "code": code, "stdout": stdout_text, "stderr": stderr_text})
            if stopping:
                break
    finally:
        protocol_stdin.close()
        os.close(protocol_fd)
    return 0


class _IntegratedCompilerDaemon:
    """Long-lived compiler coordinator; jobs execute in isolated workers.

    One instance serves one checkout for every directory it is used from:
    requests carry the caller's working directory, umask, PATH, per-compile
    environment and trusted directories.  Workers are started on demand (one
    is started right away) up to `workers`; extra workers idle for
    DAEMON_WORKER_IDLE_SECONDS are stopped, and a worker over
    DAEMON_WORKER_MAX_RSS is replaced after its job.  With no request for
    `idle_timeout_minutes` (0: never) the daemon exits."""

    def __init__(self, socket_path: str, pid_path: str, workers: int, *, state_dir: str,
                 name: str = "default", scope: str = "checkout",
                 idle_timeout_minutes: float = DAEMON_DEFAULT_IDLE_MINUTES, auto_reload: bool = True) -> None:
        self.socket_path, self.pid_path, self.workers = socket_path, pid_path, max(1, workers)
        self.name, self.scope = name, scope
        self.state_dir = Path(state_dir)
        self.state_dir.mkdir(parents=True, exist_ok=True)
        self.state_path = self.state_dir / "state.json"
        self.request_log_dir = self.state_dir / "req"
        self.idle_timeout = max(0.0, float(idle_timeout_minutes)) * 60.0
        self.auto_reload = auto_reload
        self.reload_forced = False
        self.code_hash = _daemon_code_hash()
        self.code_fingerprint = _daemon_code_fingerprint()
        self.checkout = str(Path(__file__).resolve().parent)
        self.instance_id = uuid.uuid4().hex[:12]
        self.started_at, self.bus = time.time(), EventBus(4096)
        self.last_activity = time.monotonic()
        self._slots, self._active, self._queued, self._pending_requests, self._lock = (
            threading.BoundedSemaphore(self.workers), 0, 0, 0, threading.Lock()
        )
        self._worker_condition = threading.Condition()
        self._compiler_workers: List[_DaemonCompilerWorker] = []
        self.total = self.success = self.failure = 0
        self._logs_written = 0
        self.history: Deque[Dict[str, Any]] = deque(maxlen=64)
        self._source_cache: "OrderedDict[str, Tuple[Tuple[int, int, int, int], str]]" = OrderedDict()
        self._source_cache_limit = 128
        self._cache_hits = 0
        self._cache_misses = 0
        self.reload_requested = threading.Event()
        self.stop_event = threading.Event()
        self.server: Any = None
        self._restore_state()
        try:
            (self.state_dir / "checkout").write_text(json.dumps(self.checkout), encoding="utf-8")
        except OSError:
            pass
        log_path = self.state_dir / "daemon.log"
        self.log = logging.getLogger(f"l2.integrated.daemon.{os.getpid()}.{id(self)}")
        level_name = os.environ.get("L2_DAEMON_LOG_LEVEL", "INFO").upper()
        self.log.setLevel(getattr(logging, level_name, logging.INFO))
        # Disk writes (this log, the per-request logs) happen on a
        # background thread: a request must not wait for a slow disk before
        # its client gets the answer.
        import queue
        from logging.handlers import RotatingFileHandler
        file_handler = RotatingFileHandler(log_path, maxBytes=2 * 1024 * 1024, backupCount=3)
        file_handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(message)s"))
        self._disk_queue: "queue.SimpleQueue[Optional[Callable[[], None]]]" = queue.SimpleQueue()
        disk_queue = self._disk_queue

        class _BackgroundHandler(logging.Handler):
            def emit(self, record: logging.LogRecord) -> None:
                record.message = record.getMessage()  # format now, write later
                record.msg, record.args = record.message, None
                disk_queue.put(lambda: file_handler.handle(record))

        self.log.addHandler(_BackgroundHandler())
        self._disk_writer = threading.Thread(target=self._disk_writer_loop, name="l2-daemon-disk",
                                             daemon=True)
        self._disk_writer.start()

    def _disk_writer_loop(self) -> None:
        while True:
            task = self._disk_queue.get()
            if task is None:
                return
            try:
                task()
            except Exception:
                pass

    def wait_disk_writes(self, timeout: float = 10.0) -> None:
        """Wait until the writes queued so far are on disk (page cache)."""
        if not self._disk_writer.is_alive():
            return
        done = threading.Event()
        self._disk_queue.put(done.set)
        done.wait(timeout)

    def flush_disk_writes(self) -> None:
        """Finish pending request-log and log writes and stop the writer
        (before exiting or re-executing)."""
        if self._disk_writer.is_alive():
            self._disk_queue.put(None)
            self._disk_writer.join(timeout=10.0)

    def _write_request_log(self, req_id: str, text: str) -> None:
        try:
            self.request_log_dir.mkdir(parents=True, exist_ok=True)
            (self.request_log_dir / f"{req_id}.log").write_text(text, encoding="utf-8")
        except OSError:
            return
        self._logs_written += 1
        if self._logs_written % 25 == 0:
            self._prune_request_logs()

    def settings(self) -> Dict[str, Any]:
        values: Dict[str, Any] = {
            "workers": self.workers,
            "idle_timeout_minutes": self.idle_timeout / 60.0,
            "auto_reload": self.auto_reload,
        }
        for name in DAEMON_START_ENV:
            values[name] = os.environ.get(name, "")
        return values

    def instance_info(self) -> Dict[str, Any]:
        return {
            "protocol": DAEMON_PROTOCOL,
            "pid": os.getpid(),
            "start_time_ns": _proc_start_time_ns(os.getpid()),
            "name": self.name,
            "scope": self.scope,
            "checkout": self.checkout,
            "python": f"{os.path.realpath(sys.executable)} ({sys.version.split()[0]})",
            "socket": self.socket_path,
            "state_dir": str(self.state_dir),
            "workers": self.workers,
            "idle_timeout_minutes": self.idle_timeout / 60.0,
            "auto_reload": self.auto_reload,
            "started_at": self.started_at,
            "settings": self.settings(),
        }

    def _restore_state(self) -> None:
        try:
            state = json.loads(self.state_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return
        if not isinstance(state, dict) or state.get("schema_version") != 1:
            return
        saved_hash = state.get("code_hash")
        if saved_hash != self.code_hash and not state.get("reload_restore"):
            return
        if state.get("reload_restore"):
            self.started_at = float(state.get("started_at", self.started_at))
        rows = state.get("recent_compilations", [])
        if isinstance(rows, list):
            self.history.extend(row for row in rows if isinstance(row, dict))
        self.total = int(state.get("total_requests", 0))
        self.success = int(state.get("success", 0))
        self.failure = int(state.get("failure", 0))
        self._cache_hits = int(state.get("cache_hits", 0))
        self._cache_misses = int(state.get("cache_misses", 0))
        rows = state.get("source_cache", [])
        if isinstance(rows, list):
            for row in rows:
                if not isinstance(row, dict):
                    continue
                path_text, content = row.get("path"), row.get("content")
                if not isinstance(path_text, str) or not isinstance(content, str):
                    continue
                path = Path(path_text)
                try:
                    stat = path.stat()
                except OSError:
                    continue
                if list(_file_identity(stat)) != row.get("identity"):
                    continue
                self._source_cache[path_text] = (_file_identity(stat), content)
            while len(self._source_cache) > self._source_cache_limit:
                self._source_cache.popitem(last=False)

    def _snapshot_state(self, *, reload_restore: bool = False) -> None:
        self.state_path.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "schema_version": 1,
            "code_hash": self.code_hash,
            "reload_restore": bool(reload_restore),
            "started_at": self.started_at,
            "recent_compilations": list(self.history),
            "total_requests": self.total,
            "success": self.success,
            "failure": self.failure,
            "source_cache_entries": len(self._source_cache),
            "cache_hits": self._cache_hits,
            "cache_misses": self._cache_misses,
            "source_cache": [
                {"path": path, "identity": list(identity), "content": content}
                for path, (identity, content) in self._source_cache.items()
            ],
        }
        tmp_path = self.state_path.with_suffix(".tmp")
        tmp_path.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")
        tmp_path.replace(self.state_path)

    def _touch_source_cache(self, source: Path) -> str:
        try:
            stat = source.stat()
            key = str(source.resolve())
            cached = self._source_cache.get(key)
            if cached is not None and cached[0] == _file_identity(stat):
                self._cache_hits += 1
                self._source_cache.move_to_end(key)
                return hashlib.sha256(cached[1].encode("utf-8")).hexdigest()
            content = source.read_text(encoding="utf-8")
        except OSError:
            return ""
        self._cache_misses += 1
        self._source_cache[key] = (_file_identity(stat), content)
        self._source_cache.move_to_end(key)
        while len(self._source_cache) > self._source_cache_limit:
            self._source_cache.popitem(last=False)
        return hashlib.sha256(content.encode("utf-8")).hexdigest()

    # -- workers ---------------------------------------------------------

    def start_first_worker(self) -> None:
        """Start one worker in the background, so the first compile does not
        wait for it."""
        def start() -> None:
            with self._worker_condition:
                if self._compiler_workers:
                    return
                self._compiler_workers.append(_DaemonCompilerWorker())
                self._worker_condition.notify()
        threading.Thread(target=start, name="l2-daemon-first-worker", daemon=True).start()

    def _acquire_compiler_worker(self) -> _DaemonCompilerWorker:
        with self._worker_condition:
            while True:
                for worker in list(self._compiler_workers):
                    if worker.busy:
                        continue
                    if worker.process.poll() is not None or worker.retire:
                        self._compiler_workers.remove(worker)
                        worker.close()
                        continue
                    worker.busy = True
                    return worker
                if len(self._compiler_workers) < self.workers:
                    worker = _DaemonCompilerWorker()
                    worker.busy = True
                    self._compiler_workers.append(worker)
                    return worker
                self._worker_condition.wait()

    def _release_compiler_worker(self, worker: _DaemonCompilerWorker) -> None:
        retired = False
        with self._worker_condition:
            worker.last_used = time.time()
            if worker.process.poll() is None and not worker.retire and _process_rss(worker.process.pid) > DAEMON_WORKER_MAX_RSS:
                self.log.info("worker %s over the memory limit; replacing it", worker.process.pid)
                worker.retire = True
            worker.busy = False
            if worker.process.poll() is not None or worker.retire:
                if worker in self._compiler_workers:
                    self._compiler_workers.remove(worker)
                retired = True
            self._worker_condition.notify()
        if retired:
            worker.close()  # may wait for the process; not under the lock

    def _shutdown_compiler_workers(self) -> None:
        with self._worker_condition:
            workers = list(self._compiler_workers)
            self._compiler_workers.clear()
            self._worker_condition.notify_all()
        for worker in workers:
            if worker.process.poll() is None:
                worker.process.terminate()
        for worker in workers:
            worker.close()

    def _retire_workers(self) -> int:
        """Stop idle workers now and busy ones after their job (--daemon-clear)."""
        with self._worker_condition:
            idle = [worker for worker in self._compiler_workers if not worker.busy]
            for worker in self._compiler_workers:
                worker.retire = True
            for worker in idle:
                self._compiler_workers.remove(worker)
            count = len(self._compiler_workers) + len(idle)
            self._worker_condition.notify_all()
        for worker in idle:
            worker.close()
        return count

    def _maintenance_loop(self) -> None:
        """Every few seconds: stop extra idle workers and workers over the
        memory limit, and exit after the idle timeout."""
        while not self.stop_event.wait(2.0):
            now = time.time()
            to_close: List[_DaemonCompilerWorker] = []
            with self._worker_condition:
                idle = [worker for worker in self._compiler_workers if not worker.busy]
                live = len(self._compiler_workers)
                for worker in sorted(idle, key=lambda w: w.last_used):
                    over_memory = _process_rss(worker.process.pid) > DAEMON_WORKER_MAX_RSS
                    if (live > 1 and now - worker.last_used >= DAEMON_WORKER_IDLE_SECONDS) or over_memory \
                            or worker.process.poll() is not None:
                        self._compiler_workers.remove(worker)
                        to_close.append(worker)
                        live -= 1
            for worker in to_close:
                self.log.info("stopping idle worker %s", worker.process.pid)
                worker.close()
            if self.idle_timeout > 0:
                with self._lock:
                    busy = self._active or self._queued or self._pending_requests
                    idle_for = time.monotonic() - self.last_activity
                if not busy and idle_for >= self.idle_timeout:
                    self.log.info("no requests for %.0f s; exiting", idle_for)
                    self.stop_event.set()
                    if self.server is not None:
                        threading.Thread(target=self.server.shutdown, daemon=True).start()
                    return

    # -- reload ----------------------------------------------------------

    def _watch_code(self) -> None:
        previous = self.code_hash
        while not self.stop_event.wait(0.5):
            if _daemon_code_hash() != previous:
                self._schedule_reload("compiler sources changed")
                return

    def _schedule_reload(self, reason: str, *, force: bool = False) -> None:
        if not self.auto_reload and not force:
            return
        with self._lock:
            if self.reload_requested.is_set():
                return
            self.reload_forced = force
            self.reload_requested.set()
            self.stop_event.set()
        self.log.warning("%s; scheduling daemon reload", reason)
        if self.server is not None:
            threading.Thread(target=self.server.shutdown, daemon=True).start()

    # -- requests --------------------------------------------------------

    def _prune_request_logs(self) -> None:
        try:
            logs = sorted(self.request_log_dir.glob("*.log"), key=lambda p: p.stat().st_mtime)
        except OSError:
            return
        for path in logs[:-DAEMON_REQUEST_LOGS_KEPT]:
            try:
                path.unlink()
            except OSError:
                pass

    def _run(
        self,
        argv: List[str],
        color: bool,
        stdin_data: Optional[str],
        tool_path: Optional[str] = None,
        job_env: Optional[Dict[str, Optional[str]]] = None,
        cwd: Optional[str] = None,
        umask: Optional[int] = None,
        trusted_dirs: Optional[str] = None,
    ) -> Dict[str, Any]:
        req_id, began = uuid.uuid4().hex[:12], time.perf_counter_ns()
        for index, arg in enumerate(argv):
            if arg == "--events-stream":
                if index + 1 >= len(argv) or argv[index + 1].startswith("-"):
                    return {"ok": False, "error": "--events-stream requires a file path"}
            elif arg.startswith("--events-stream="):
                if not arg.split("=", 1)[1]:
                    return {"ok": False, "error": "--events-stream requires a file path"}

        source_path = next((Path(x) for x in argv if x.endswith(".sl")), None)
        if source_path is not None and cwd and not source_path.is_absolute():
            source_path = Path(cwd) / source_path
        source_hash = self._touch_source_cache(source_path) if source_path is not None else ""
        self.log.info("req_id=%s start cwd=%s source=%s argv=%r", req_id, cwd, source_path or "<command>", argv)
        def forward_event(record: Dict[str, Any]) -> None:
            self.bus.publish_record(record)

        worker: Optional[_DaemonCompilerWorker] = None
        try:
            worker = self._acquire_compiler_worker()
            return_code, stdout, stderr = worker.run(
                argv,
                color=color,
                stdin_data=stdin_data,
                # Compiler events cost real time on every compile (thousands
                # per stdlib import), so they are produced and forwarded only
                # while something is subscribed to the daemon's bus.
                event_observer=forward_event if self.bus.has_subscribers() else None,
                tool_path=tool_path,
                job_env=job_env,
                cwd=cwd,
                umask=umask,
                trusted_dirs=trusted_dirs,
            )
        except Exception as exc:
            # Infrastructure failure (worker crashed or was terminated), not a
            # compile error: ask the client to compile locally instead of
            # reporting a bogus failure.
            self.failure += 1
            self.log.warning("req_id=%s compiler worker failed: %s", req_id, exc)
            return {"ok": False, "fallback": True, "error": f"compiler worker failed: {exc}"}
        finally:
            if worker is not None:
                self._release_compiler_worker(worker)

        result = {"ok": True, "code": return_code, "stdout": stdout, "stderr": stderr}
        stdout_text, stderr_text = result["stdout"], result["stderr"]
        cache_hit = "[v1] cache hit for " in stdout_text
        record = {
            "id": req_id,
            "source": str(source_path or "<command>"),
            "source_hash": source_hash,
            "duration_ns": time.perf_counter_ns() - began,
            "code": return_code,
            "cache_hit": cache_hit,
            "finished_at": time.time(),
        }
        self.history.append(record); self.success += return_code == 0; self.failure += return_code != 0
        log_text = (f"{time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())} INFO req_id={req_id} cwd={cwd} result={record}\n"
                    f"--- stdout ---\n{stdout_text}\n--- stderr ---\n{stderr_text}")
        self._disk_queue.put(lambda: self._write_request_log(req_id, log_text))
        self.log.info("req_id=%s finish code=%s duration_ns=%s", req_id, return_code, record["duration_ns"])
        return result

    def status(self) -> Dict[str, Any]:
        with self._lock:
            active, queued, pending = self._active, self._queued, self._pending_requests
            idle_seconds = time.monotonic() - self.last_activity
        with self._worker_condition:
            worker_details = [worker.details() for worker in self._compiler_workers]
        cache_bytes = sum(len(row[1].encode("utf-8")) for row in self._source_cache.values())
        return {
            "ok": True,
            "protocol": DAEMON_PROTOCOL,
            "pid": os.getpid(),
            "name": self.name,
            "scope": self.scope,
            "checkout_dir": self.checkout,
            "state_dir": str(self.state_dir),
            "uptime_seconds": time.time() - self.started_at,
            "idle_seconds": idle_seconds,
            "idle_timeout_minutes": self.idle_timeout / 60.0,
            "workers": self.workers,
            "worker_details": worker_details,
            "active_jobs": active,
            "queued_jobs": queued,
            "pending_requests": pending,
            "memory_rss_bytes": _process_rss(os.getpid()),
            "open_fds": _daemon_open_fds(),
            "total_requests": self.total,
            "success": self.success,
            "failure": self.failure,
            "stale": self.reload_requested.is_set(),
            "code_hash": self.code_hash,
            "instance_id": self.instance_id,
            "settings": self.settings(),
            "recent_compilations": list(self.history),
            "cache_stats": {"entries": len(self._source_cache), "hits": self._cache_hits, "misses": self._cache_misses, "bytes": cache_bytes},
            "event_bus_stats": self.bus.stats(),
        }

    def handle(self, payload: Dict[str, Any], server: Any, *, queued_registered: bool = False) -> Dict[str, Any]:
        cmd = str(payload.get("cmd", "")); self.total += 1
        if cmd == "ping": return {"ok": True, "pong": True, "stale": self.reload_requested.is_set()}
        if cmd == "status":
            return self.status()
        if cmd == "events": return {"ok": True, "events": self.bus.recent(str(payload.get("pattern", "*")), payload.get("limit"))}
        if cmd == "logs":
            self.wait_disk_writes()
            requested = payload.get("req")
            log_path = (self.request_log_dir / f"{Path(str(requested)).name}.log") if requested else (self.state_dir / "daemon.log")
            try:
                text = log_path.read_text(encoding="utf-8")
            except OSError as exc:
                return {"ok": False, "error": str(exc)}
            tail = payload.get("tail")
            if tail is not None:
                try:
                    text = "\n".join(text.splitlines()[-max(0, int(tail)):]) + ("\n" if text else "")
                except (TypeError, ValueError):
                    return {"ok": False, "error": "logs tail must be an integer"}
            return {"ok": True, "path": str(log_path), "text": text}
        if cmd in {"session-clear", "reset", "clear"}:
            self.history.clear()
            self._source_cache.clear()
            self._cache_hits = self._cache_misses = 0
            if cmd == "reset":
                try:
                    self.state_path.unlink()
                except OSError:
                    pass
            if cmd == "clear":
                return {"ok": True, "workers_retired": self._retire_workers()}
            return {"ok": True}
        if cmd == "reload":
            self._schedule_reload("reload requested", force=True)
            return {"ok": True}
        if cmd == "shutdown":
            self.stop_event.set()
            threading.Thread(target=server.shutdown, daemon=True).start(); return {"ok": True}
        if cmd != "run" or not isinstance(payload.get("argv"), list):
            if queued_registered:
                with self._lock:
                    self._queued -= 1
            return {"ok": False, "error": f"unknown or invalid daemon command: {cmd}"}

        def refuse(response: Dict[str, Any]) -> Dict[str, Any]:
            if queued_registered:
                with self._lock:
                    self._queued -= 1
            return response

        if payload.get("protocol", DAEMON_PROTOCOL) != DAEMON_PROTOCOL:
            return refuse({"ok": False, "fallback": True,
                           "error": f"client protocol {payload.get('protocol')} != daemon protocol {DAEMON_PROTOCOL}"})
        checkout = payload.get("checkout")
        if isinstance(checkout, str) and os.path.realpath(checkout) != self.checkout:
            return refuse({"ok": False, "fallback": True,
                           "error": f"this daemon serves {self.checkout}, not {checkout}"})
        # Never compile with outdated compiler code: the content-hash watcher
        # polls every 0.5 s, so also check a cheap fingerprint per request.
        if self.reload_requested.is_set() or (
            self.auto_reload and _daemon_code_fingerprint() != self.code_fingerprint
        ):
            if not self.reload_requested.is_set():
                self._schedule_reload("compiler sources changed")
            return refuse({"ok": False, "fallback": True, "stale": True, "error": "compiler daemon is reloading"})
        tool_path = payload.get("tool_path")
        if not isinstance(tool_path, str) or "\x00" in tool_path:
            tool_path = os.environ.get("PATH", "")
        cwd = payload.get("cwd")
        if not isinstance(cwd, str) or "\x00" in cwd or not os.path.isabs(cwd):
            cwd = None
        umask = payload.get("umask")
        if not isinstance(umask, int) or not 0 <= umask <= 0o777:
            umask = None
        trusted = payload.get("trusted_dirs")
        if not isinstance(trusted, str) or "\x00" in trusted:
            trusted = None
        if not queued_registered:
            with self._lock:
                self._queued += 1
        self._slots.acquire()
        with self._lock:
            self._queued -= 1
            self._active += 1
            self.last_activity = time.monotonic()
        try:
            return self._run(
                [str(x) for x in payload["argv"]],
                bool(payload.get("wants_color")),
                payload.get("stdin"),
                tool_path,
                _sanitize_job_env(payload.get("job_env")),
                cwd,
                umask,
                trusted,
            )
        finally:
            with self._lock:
                self._active -= 1
                self.last_activity = time.monotonic()
            self._slots.release()


def _peer_uid(connection: socket.socket) -> Optional[int]:
    try:
        raw = connection.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, _get_struct().calcsize("3i"))
        return _get_struct().unpack("3i", raw)[1]
    except (OSError, AttributeError):
        return None


def daemon_serve(argv: Sequence[str]) -> int:
    """`l2_main.py --daemon-serve`: the daemon process main.py starts.  The
    start lock (held by the client while it starts the daemon) arrives as
    L2_DAEMON_LOCK_FD and is kept for the daemon's lifetime."""
    import argparse
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--socket", required=True)
    parser.add_argument("--pid", required=True)
    parser.add_argument("--state-dir", required=True)
    parser.add_argument("--name", default="default")
    parser.add_argument("--scope", default="checkout")
    parser.add_argument("--workers", type=int, default=max(1, min(os.cpu_count() or 1, 8)))
    parser.add_argument("--idle-timeout", type=float, default=DAEMON_DEFAULT_IDLE_MINUTES)
    parser.add_argument("--no-auto-reload", action="store_true")
    parser.add_argument("--prewarm", action="store_true")
    args = parser.parse_args(list(argv))
    if args.prewarm:
        os.environ["L2_DAEMON_WORKER_PREWARM"] = "1"
    else:
        os.environ.pop("L2_DAEMON_WORKER_PREWARM", None)
    inherited_lock_fd = os.environ.get("L2_DAEMON_LOCK_FD")
    if inherited_lock_fd is not None:
        lock_fd = int(inherited_lock_fd)
        os.set_inheritable(lock_fd, True)
    else:
        lock_path = Path(str(args.socket) + ".lock")
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        lock_fd = os.open(lock_path, os.O_CREAT | os.O_RDWR, 0o600)
        fcntl.flock(lock_fd, fcntl.LOCK_EX)
        os.set_inheritable(lock_fd, True)
    os.environ["L2_DAEMON_LOCK_FD"] = str(lock_fd)
    daemon = _IntegratedCompilerDaemon(
        args.socket,
        args.pid,
        args.workers,
        state_dir=args.state_dir,
        name=args.name,
        scope=args.scope,
        idle_timeout_minutes=args.idle_timeout,
        auto_reload=not args.no_auto_reload and os.environ.get("L2_DAEMON_NO_AUTO_RELOAD", "0").lower() not in {"1", "true", "yes"},
    )

    def _request_daemon_shutdown(_signum: int, _frame: Any) -> None:
        daemon.stop_event.set()
        if daemon.server is not None:
            threading.Thread(target=daemon.server.shutdown, daemon=True).start()

    previous_sigterm_handler = signal.signal(signal.SIGTERM, _request_daemon_shutdown)
    try: Path(args.socket).unlink()
    except OSError: pass
    class Server(socketserver.ThreadingMixIn, socketserver.UnixStreamServer): daemon_threads = True
    class Handler(socketserver.StreamRequestHandler):
        def handle(self) -> None:
            if _peer_uid(self.connection) not in (os.getuid(), None):
                # Only this user's processes may use the daemon.
                self.wfile.write(b'{"ok":false,"error":"permission denied"}\n'); self.wfile.flush()
                return
            subscription: Optional[int] = None
            with daemon._lock:
                daemon._pending_requests += 1
            pending_registered = True
            response: Optional[Dict[str, Any]] = None
            try:
                payload = json.loads(self.rfile.readline().decode("utf-8"))
                queued_registered = payload.get("cmd") == "run" and isinstance(payload.get("argv"), list)
                with daemon._lock:
                    if queued_registered:
                        daemon._queued += 1
                if payload.get("cmd") == "subscribe_events":
                    with daemon._lock:
                        daemon._pending_requests -= 1
                        pending_registered = False
                    write_lock = threading.Lock()
                    def send_event(record: Dict[str, Any]) -> None:
                        with write_lock:
                            self.wfile.write((json.dumps({"ok": True, "event": record}, separators=(",", ":")) + "\n").encode("utf-8")); self.wfile.flush()
                    subscription = daemon.bus.subscribe(str(payload.get("pattern", "*")), send_event, replay=bool(payload.get("replay")))
                    send_event({"event": "subscription.ready", "timestamp_ns": time.time_ns(), "payload": {}})
                    while not daemon.stop_event.is_set():
                        try:
                            if self.connection.recv(1, socket.MSG_PEEK | socket.MSG_DONTWAIT) == b"": break
                        except BlockingIOError:
                            time.sleep(0.1); continue
                        except OSError: break
                    return
                response = daemon.handle(payload, self.server, queued_registered=queued_registered)
            except Exception as exc:
                response = {"ok": False, "error": str(exc)}
            finally:
                if subscription is not None: daemon.bus.unsubscribe(subscription)
                try:
                    if response is not None:
                        self.wfile.write((json.dumps(response, separators=(",", ":")) + "\n").encode("utf-8"))
                        self.wfile.flush()
                finally:
                    if pending_registered:
                        with daemon._lock:
                            daemon._pending_requests -= 1
    instance_dir = Path(args.socket).parent
    info_path = instance_dir / "instance.json"
    Path(args.pid).parent.mkdir(parents=True, exist_ok=True); Path(args.pid).write_text(f"{os.getpid()}\n", encoding="utf-8")
    _write_daemon_lease(args.socket, os.getpid())
    lease_thread = threading.Thread(target=_daemon_heartbeat_loop, args=(args.socket, daemon.stop_event), name="l2-daemon-lease", daemon=True)
    lease_thread.start()
    # A socket address holds 107 bytes; a longer path is bound through
    # /proc/self/fd/<directory>/<name> (the file is the same).
    bind_path = args.socket
    socket_dir_fd: Optional[int] = None
    if len(os.fsencode(args.socket)) >= 100:
        socket_dir_fd = os.open(os.path.dirname(args.socket) or ".", os.O_RDONLY | os.O_DIRECTORY)
        bind_path = f"/proc/self/fd/{socket_dir_fd}/{os.path.basename(args.socket)}"
    with Server(bind_path, Handler) as server:
        if socket_dir_fd is not None:
            os.close(socket_dir_fd)
        os.chmod(args.socket, 0o600)
        daemon.server = server
        try:
            info_path.write_text(json.dumps(daemon.instance_info(), indent=1), encoding="utf-8")
        except OSError:
            pass
        daemon.start_first_worker()
        if daemon.auto_reload:
            threading.Thread(target=daemon._watch_code, name="l2-daemon-reload", daemon=True).start()
        threading.Thread(target=daemon._maintenance_loop, name="l2-daemon-maintenance", daemon=True).start()
        daemon.log.info("daemon started: pid=%s name=%s checkout=%s workers=%s idle_timeout_min=%s",
                        os.getpid(), daemon.name, daemon.checkout, daemon.workers, daemon.idle_timeout / 60.0)
        try: server.serve_forever()
        finally:
            daemon.stop_event.set()
            # A reload re-executes this same process: its pid, lease and
            # instance.json stay valid, so they are kept (the socket is bound
            # again by the new image).
            reloading = daemon.reload_requested.is_set() and (daemon.auto_reload or daemon.reload_forced)
            for path in ((args.socket,) if reloading else (args.socket, args.pid, args.socket + ".lease", str(info_path))):
                try: Path(path).unlink()
                except OSError: pass
    # Let in-flight compiles finish; terminating them would turn a reload into
    # spurious compile failures for long-running jobs.
    drain_deadline = time.monotonic() + DAEMON_DRAIN_TIMEOUT
    workers_stopped = False
    while True:
        with daemon._lock:
            drained = daemon._active == 0 and daemon._queued == 0 and daemon._pending_requests == 0
        if drained:
            break
        if not workers_stopped and time.monotonic() >= drain_deadline:
            daemon.log.warning("daemon drain timed out; terminating active compiler workers")
            daemon._shutdown_compiler_workers()
            workers_stopped = True
            drain_deadline = time.monotonic() + 5.0
        elif workers_stopped and time.monotonic() >= drain_deadline:
            daemon.log.error("daemon requests did not drain after worker termination")
            break
        time.sleep(0.01)
    if not workers_stopped:
        daemon._shutdown_compiler_workers()
    daemon._snapshot_state(reload_restore=daemon.reload_requested.is_set())
    if daemon.reload_requested.is_set() and (daemon.auto_reload or daemon.reload_forced):
        daemon.log.info("re-executing for reload")
        daemon.flush_disk_writes()
        os.set_inheritable(lock_fd, True)
        os.environ["L2_DAEMON_LOCK_FD"] = str(lock_fd)
        os.execv(sys.executable, [sys.executable, str(Path(__file__).resolve()), "--daemon-serve", *list(argv)])
    daemon.log.info("daemon exiting")
    daemon.flush_disk_writes()
    os.close(lock_fd)
    signal.signal(signal.SIGTERM, previous_sigterm_handler)
    return 0


def freeze_startup_objects(*, collect_first: bool = False) -> None:
    """Move everything allocated so far (this module's code, tables,
    built-in words) out of the cyclic garbage collector's scope, so
    collections during a compile do not traverse it again.  Those objects
    live for the whole process, so no memory is retained that would
    otherwise be freed; objects allocated later stay collectable.

    One-shot CLI processes call this right after import.  The daemon worker
    passes `collect_first`, so garbage from its startup is freed rather than
    frozen; each job's forked child then inherits the frozen heap (as the
    gc module documentation recommends before fork)."""
    import gc
    if collect_first:
        gc.collect()
    gc.freeze()


# ---------------------------------------------------------------------------
# § 24. Entry point
# ---------------------------------------------------------------------------

def main() -> None:
    if len(sys.argv) >= 2 and sys.argv[1] == "--daemon-worker":
        code = _daemon_worker_serve()
        sys.stdout.flush()
        sys.stderr.flush()
        os._exit(code)
    if len(sys.argv) >= 2 and sys.argv[1] == "--daemon-serve":
        code = daemon_serve(sys.argv[2:])
        sys.stdout.flush()
        sys.stderr.flush()
        os._exit(code)
    freeze_startup_objects()
    code = cli(sys.argv[1:])
    # Flush all output then use os._exit to avoid SIGSEGV from ctypes/native
    # memory finalization during Python's shutdown sequence.
    sys.stdout.flush()
    sys.stderr.flush()
    os._exit(code)


if __name__ == "__main__":
    main()
